/* AI師匠の増やした中身 1/3＝よくある問いの答え 669本（mentor_more_pack.py が書く。手で直さない。材料は hoken-newtools-src/mentor-more/） */
(function(){var D={faq:[
      /* cmp.json */
      { key:'faq_xcmp_ikou_atogaki', faq:1, grp:'cmp', q:"意向把握の記録を後から書いてもいい？", re:/意向(把握|確認|の把握|の確認)?[^。]{0,10}(記録|メモ)[^。]{0,12}(後から|あとから|後で|あとで|後日|日がたって|日が経って|数日|まとめて|つけ忘れ|付け忘れ|書き忘れ|残し忘れ|書いていな)|(後から|あとから|後日|数日たって|数日経って|日がたって)[^。]{0,12}意向[^。]{0,6}(記録|メモ)|(つけ忘れ|付け忘れ|書き忘れ|残し忘れ)[^。]{0,8}意向/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"後から書くことはできますが、書いた日を正直に残し、日付をさかのぼらせません。", body:"意向把握の記録は、面談で伺ったご意向を、できるだけその日のうちに事実のまま残すものです。書き忘れに気づいたら、思い出せる範囲で書き、書いた日と後から書いた事情も添えます。面談の日に書いたように日付を合わせたり、申込みの内容に合わせて中身を整えたりすると、記録の作り変えになります。", acts:["書き忘れに気づいたら、その日のうちに上長へ伝え、後から書く旨を相談する", "書いた日と、面談の日とが違うことを、記録の中に正直に書く", "覚えていないことは書かず、お客様に改めて確かめてから書き足す", "次からは、面談のあと車に戻ったらすぐ要点を残す習慣にする"], actHead:"今日やること", note:"記録を書く期限・後から書くときの書き方・申込みの前の確認書面の扱いは、所属の保険会社と御社の手順で違う。上長とコンプライアンス担当で確かめる。", go:"iko", pre:1, say:"先日伺ったご意向を、念のためもう一度確かめさせてください。記録に間違いがないようにしたいので。", more:"よくあるのは、面談が続いて記録が溜まり、数日後にまとめて書く形です。記憶があいまいなまま書くと、申込みの内容に寄せてしまいがちです。迷うところは書かずに空けておき、次に会ったときやお電話で、お客様に確かめてから書き足します。", why:"記録は、お客様のご意向に沿って提案したことを、あとから第三者が確かめるためのものだからです。日付や中身を整えた記録は、事実を示す力を失い、点検や苦情のときにかえって疑いを招きます。" },
      { key:'faq_xcmp_ikou_chigau', faq:1, grp:'cmp', q:"途中でお客様の希望が変わり、別の商品で申し込むことになった", re:/(希望|意向|ご要望|最初の話)[^。]{0,10}(違う|ちがう|変わ)[^。]{0,10}(商品|保険|プラン|内容)[^。]{0,10}(申込|申し込|決ま|契約)|(途中で|提案の途中|面談の途中)[^。]{0,14}(別の|違う|ほかの)(商品|保険|プラン)[^。]{0,8}(選|決|申込|申し込)/, ng:/部下|後輩|新人|メンバー|上司|自動車|車の|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"ご意向が変わったら、変わった中身と理由を記録し、申込みの内容と照らしてから進めます。", body:"面談を重ねるうちに、お客様のご希望が変わるのは自然なことです。大事なのは、最初のご意向と申込みの内容がどこで違ったのか、なぜそうなったのかを、お客様と一緒に確かめて残すことです。保障の範囲や保険料、受け取り方など、変わった点が、ご本人の考えで選ばれたものかを確かめます。", acts:["最初のご意向と、いまの申込みの内容を並べて、違う点をお客様と読み合わせる", "変わった理由を、お客様の言葉でそのまま記録に書く", "変わった点で失うものや増える負担があれば、書面を見ながら説明し直す", "こちらの勧めで変わったときは、その理由も比較推奨の記録に残す"], actHead:"今日やること", note:"ご意向の確かめ方と、申込みの前に確認していただく書面の扱いは、所属の保険会社の手順と御社の規程で違う。迷ったらコンプライアンス担当へ。", go:"iko", pre:1, say:"最初に伺ったお考えと、いまのご希望で変わったところがあります。違いを一緒に確かめてから進めさせてください。", more:"よくあるのは、保険料を抑えたいというご希望から、途中で保障を厚くする方向に変わる、またはその逆の場面です。どちらでも、変わった理由がお客様ご自身の言葉で残っているかが要点です。こちらが言った一言で変わった場合は、その説明が偏っていなかったかも振り返ります。", why:"意向の確認は、最後に申し込む内容が、お客様が本当に望んだものかを確かめる仕組みだからです。途中で変わったこと自体は問題ではなく、変わった理由が残っていないと、勧められて流されたのか、ご本人が選んだのかが後から分からなくなります。" },
      { key:'faq_xcmp_ikou_houjin', faq:1, grp:'cmp', q:"法人契約の意向把握は誰から聞けばいい？", re:/(法人|会社で入る|会社の契約|福利厚生|法人契約)[^。]{0,14}(意向|ご意向|希望)[^。]{0,12}(把握|確認|確か|聞|伺)|意向(把握|確認)[^。]{0,10}(法人|会社の契約|社長と)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"法人の契約は、契約を決める権限のある方からご意向を伺い、被保険者の同意は別に確かめます。", body:"法人が契約者になる保険では、ご意向を伺う相手は、会社として契約を決める代表者や、その権限を任された方です。経理の担当の方から事情を伺うのは大事ですが、目的や受け取り方の最終の判断は、決める方に確かめます。役員や従業員が被保険者になる場合は、その方ご本人の同意が別に要ります。", acts:["面談の前に、契約を決める方が誰かを、窓口の方に確かめておく", "目的（退職金の準備・事業の保障・福利厚生など）と受け取る先を、決める方の言葉で記録する", "被保険者になる方には、別に内容を説明し、同意をいただく段取りを組む"], actHead:"現場で使うなら", note:"法人の申込みで署名する方の範囲・被保険者の同意の取り方は、所属の保険会社の手引きで決まっている。経理や税の扱いは顧問の税理士に確かめる。", go:"iko", pre:1, say:"このお話は、会社としてお決めになる方に、目的を直接お伺いしたいと考えています。ご都合のよい日に、少しお時間をいただけますか。", more:"よくあるのは、経理の担当の方とだけ話が進み、社長は申込書に署名するだけ、という形です。これでは、何のための契約かが社長の言葉で残りません。短くても社長と話す場をつくり、目的と受け取り方を確かめます。福利厚生の契約では、社内の規程の有無も確かめます。", why:"法人の契約は、会社のお金の使い方の判断なので、決める権限のある方の意思に沿っているかが要になるからです。担当の方の意向だけで進めると、後で社長の考えと違ったときに、解約や苦情につながります。" },
      { key:'faq_xcmp_ikou_koushin', faq:1, grp:'cmp', q:"更新や更改のときも意向把握は要る？", re:/(更新|更改|満期の切り替え|切り替え|継続)[^。]{0,12}(意向|ご意向)[^。]{0,10}(把握|確認|確か|聞き直|聞く|要る|必要|いらな|要らな)|(意向把握|意向確認|意向の確認)[^。]{0,10}(更新|更改)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"更新や更改のときも、ご意向が前と変わっていないかを確かめ、記録に残します。", body:"同じ内容で続ける場合でも、ご家族や車、住まい、お仕事など、前の契約のときから暮らしが変わっていることがあります。更新や更改は、補償や保障がいまの暮らしに合っているかを見直す機会です。どこまで確かめるか、どう記録するかは、保険の種類と所属の保険会社の手順で違います。", acts:["案内の前に、前回からの変化（車・運転する人・住まい・家族・仕事）を聞く項目を用意しておく", "変わっていないと言われたときも、確かめたこと自体を記録に残す", "補償の内容や保険料が前と変わる点は、案内の書面を見ながら説明する"], actHead:"現場で使うなら", note:"更新・更改のときに確かめる項目と記録の残し方は、商品の種類と所属の保険会社の手順で違う。社内の手引きとコンプライアンス担当で確かめる。", go:"iko", pre:1, say:"今回も同じ内容で続ける前に、前回から変わったことがないか、少しだけ確かめさせてください。", more:"自動車保険なら、運転する方の範囲や使い方。火災保険なら、建物の増改築や家財の量。生命保険の更新なら、保険料の変わり方と、いまの保障の役目がまだ必要か。毎回同じ質問を形だけで流さず、前回の記録を見てから聞くと、お客様にも意味が伝わります。", why:"更新は手続きが簡単な分、中身を確かめないまま続きやすく、暮らしと合わない補償が残りやすいからです。補償が足りないことに事故のあとで気づくと、お客様の負担が大きく、苦情のもとにもなります。" },
      { key:'faq_xcmp_shimei', faq:1, grp:'cmp', q:"お客様が商品を指名してきた。比較推奨はどうする？", re:/(商品|保険|プラン)を?(指名|名指し|指定)|(指名|名指し|指定)(して|され|した|の)[^。]{0,8}(商品|保険|プラン)|(この|その|あの)(保険|商品|プラン)にしたいと[^。]{0,4}(決めて|言われ|来)|(決めて|決めた上で)(来られ|来た|いらっしゃ)/, ng:/部下|後輩|新人|メンバー|口座|受取人|代理請求|指定代理|病院|医療機関|修理工場|工場|会社を指定|セット|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"指名された商品でも、ご意向に合うかを確かめ、御社の方針でどうお勧めするかを伝えて残します。", body:"お客様が商品を決めて来られたときも、その商品がご意向や暮らしに合っているかを確かめる手順は同じです。複数の保険会社の商品を扱う代理店では、御社の比較推奨の方針に沿って、ほかに比べられる商品があるかや、その商品を扱う理由を説明します。お客様が指名したこと自体も、記録に残します。", acts:["どこでその商品を知り、何に惹かれたかを最初に伺う", "ご意向を伺い、その商品の保障や条件が合っているかを一緒に確かめる", "合わない点があれば、それも伝えたうえで、選ぶのはお客様だと伝える", "お客様の指名だったことと、説明した内容を比較推奨の記録に残す"], actHead:"現場で使うなら", note:"指名があったときの比較推奨の説明と記録の仕方は、御社の比較推奨の方針と所属の保険会社の手引きで決まっている。コンプライアンス担当で確かめる。", go:"hikaku", pre:1, say:"この商品をご覧になって来てくださったのですね。お考えに合っているか、念のため一緒に確かめさせてください。", more:"よくあるのは、ネットの記事や知人の話で商品名を知り、そのまま申し込みたいと来られる場面です。指名どおりに進めるときも、なぜその商品なのか、ご家族や予算に合っているかを伺えば、思い違いを防げます。指名と違う商品を勧めるときは、勧める理由を分かる言葉で伝え、選ぶのはお客様に残します。", why:"お客様が自分で選んだつもりでも、仕組みや条件を誤解していることがあるからです。比較推奨の決まりは、お客様が納得して選んだかを残す仕組みなので、指名でも記録が要ります。" },
      { key:'faq_xcmp_senzoku', faq:1, grp:'cmp', q:"1社だけ扱う代理店でも比較推奨は要る？", re:/(専属|一社専属|1社専属)[^。]{0,16}(比較推奨|比べ|比較|説明)|(保険会社|会社)(が|を)?[^。]{0,4}(一社|1社|一つ|ひとつ)(だけ|のみ)[^。]{0,16}(比較推奨|比べ|比較|説明)|(一社|1社)(だけ|のみ)(を)?扱[^。]{0,12}(比較推奨|比べ|比較)|乗合(では|じゃ)な[^。]{0,12}(比較推奨|比べ|比較)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"比較推奨の決まりは複数の会社の商品を扱う代理店のもの。一社だけなら、その旨を分かるように伝えます。", body:"比べてお勧めする商品の選び方や理由を説明する決まりは、主に複数の保険会社から委託を受けている乗合代理店に向けたものです。一社の商品だけを扱う代理店では、ほかの会社の商品と比べてお勧めする場面がないので、どの保険会社の商品を扱っているのかを、お客様が分かるように伝えることが土台になります。ご意向に沿って提案し、記録する手順は同じです。", acts:["名刺や最初の説明で、どの保険会社の代理店かをはっきり伝える", "ほかの会社の商品と比べてほしいと言われたら、扱っているのは一社だと伝え、優劣は言わない", "ご意向の確かめと記録は、乗合の代理店と同じ手順で残す"], actHead:"現場で使うなら", note:"一社だけを扱う代理店での説明の仕方と記録の残し方は、所属の保険会社の手引きで決まっている。乗合に変わるときの手順も含め、保険会社と社内で確かめる。", go:"hikaku", pre:1, say:"私どもは、この保険会社の代理店として、この会社の商品をご案内しています。お考えに合うかを一緒に確かめさせてください。", more:"よくある勘違いは、一社専属だから記録は何も要らない、という思い込みです。比べる説明が要らなくても、ご意向に合う商品を選んだことの記録や、どの会社の代理店かの説明は要ります。将来、複数の会社と契約して乗合になるときは、比較推奨の方針づくりから始めます。", why:"お客様は、代理店がいくつもの会社の商品から選んでくれていると思い込むことがあるからです。扱う範囲を先に伝えておけば、お客様は、ほかの会社の商品も見るかどうかを自分で選べます。" },
      { key:'faq_xcmp_set_hanbai', faq:1, grp:'cmp', q:"住宅の契約とセットで、火災保険の会社を指定してもいい？", re:/(住宅|家|物件|マンション|ローン|売買|賃貸)[^。]{0,14}(セット|抱き合わせ|条件|一緒|決まり)[^。]{0,16}(火災保険|保険)[^。]{0,10}(指定|入って|入る|加入|選べな|しか)|(家|住宅|物件)を(買|購入|借り)[^。]{0,16}(火災保険|保険)に(入って|加入して)もらう|(提携|指定)の(火災保険|保険)しか/, ng:/部下|後輩|新人|メンバー|団信|団体信用|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"保険の加入や保険会社を、住まいの契約の条件のように見せず、お客様が選べることを伝えます。", body:"住まいの購入や賃貸の手続きの中で、火災保険を案内すること自体はよくあります。ただ、指定の保険に入らないと契約できないように伝えると、お客様の選ぶ自由を狭め、立場を使った勧誘と受け取られます。住宅ローンで火災保険の加入を求める金融機関はありますが、保険会社まで決まっているかは、金融機関の条件で確かめます。", acts:["案内の最初に、保険はほかの会社で入っても構わないことを伝える", "ローンの条件で保険が要るときは、金融機関の求める内容を書面で確かめてから伝える", "賃貸の火災保険も、求められる補償の内容と、選べる範囲を分けて説明する"], actHead:"現場で使うなら", note:"住まいの契約と保険の案内の線は、所属の保険会社の手引きと御社の規程で決まっている。ローンの条件は金融機関、物件の重要事項は宅地建物取引士に確かめる。", pre:1, say:"火災保険は、私どもでご用意もできますが、ほかの会社でお入りいただいても構いません。比べてお決めください。", more:"不動産や住宅の会社が代理店を兼ねていると、物件の担当と保険の担当が近い人になりがちです。そのときは、物件の話と保険の話を分けて、保険は別の書面で説明し、選ぶ自由があることを口でも伝えます。賃貸では、貸主が求める補償の内容と、保険会社まで決まっているかを分けて確かめます。", why:"住まいの契約は大きな決断で、お客様は担当者の言うことを断りにくい立場にあるからです。そこで保険まで条件のように扱うと、お客様は比べる機会を失い、後で知ったときに強い不信につながります。" },
      { key:'faq_xcmp_norikae_tasha', faq:1, grp:'cmp', q:"他社の営業に乗換を勧められたお客様から相談された", re:/(他社|他の(代理店|保険会社|営業|担当)|ほかの(代理店|保険会社|営業|担当|人)|別の(代理店|保険会社|営業|担当))[^。]{0,16}(乗換|乗り換え|見直|やめる|やめて|解約|入り直)[^。]{0,10}(勧め|すすめ|よう(に)?言われ|提案され|持ちかけ)|(乗換|乗り換え)を(勧め|すすめ)られ/, ng:/部下|後輩|新人|メンバー|上司|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"他社の勧めを悪く言わず、今の契約で失うものと、比べる点を一緒に書面で確かめます。", body:"お客様が他社から乗換を勧められて迷っているとき、こちらの役目は引き止めることではなく、判断の材料をそろえることです。今の契約をやめると、保障の空白、新たな告知、年齢で変わる保険料、払い込んだ額と戻る額の差など、失うものがあります。それを新しい提案と並べて書面で確かめ、決めるのはお客様です。", acts:["他社の提案書を見せていただき、今の契約と並べて違う点を書き出す", "今の契約をやめる前に、新しい契約が成立するまで待つことを伝える", "他社や担当の方を悪く言わず、比べる点だけを伝える"], actHead:"現場で使うなら", note:"他社の提案の中身の評価・乗換の扱いは、所属の保険会社と御社の比較推奨の方針で決まっている。解約の手続きの細部は保険会社の窓口で確かめる。", go:"hikaku", pre:1, say:"ご相談いただいてありがとうございます。どちらがいいかではなく、今の契約で続くものと、やめると失うものを一緒に並べてみましょう。", more:"よくあるのは、保険料が安くなる、新しい保障になる、という話だけを聞いて迷っている場面です。安くなる理由が保障の範囲や期間の違いにないか、告知で入れない可能性はないかを確かめると、お客様が自分で判断できます。結果として乗り換えると決められても、その判断を尊重します。", why:"乗換は、お客様のためになる場合も失うものが大きい場合もあり、その差はお客様の状況で変わるからです。自分の契約を守るために他社を悪く言うと、お客様の判断の材料がかえって偏ります。" },
      { key:'faq_xcmp_kourei_doseki', faq:1, grp:'cmp', q:"ご高齢のお客様に、家族の同席はいらないと言われた", re:/(高齢|年配|ご年配|お年寄り)[^。]{0,16}(同席|ご家族|家族|子ども|子供|息子|娘)[^。]{0,14}(いらない|要らない|不要|嫌が|断ら|呼ばな|知られたくな|知らせたくな|一人で|ひとりで)|(高齢|年配)[^。]{0,14}(一人で|ひとりで)(決め|大丈夫|できる)/, ng:/部下|後輩|新人|メンバー|(自分|私|僕|俺|うち)の(親|父|母|祖)|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"同席を断られたら、ご本人の気持ちを尊重しつつ、会社が決めた別の確かめ方で進めます。", body:"ご高齢のお客様の募集では、ご家族の同席を求める手順を決めている会社が多くあります。ご本人が同席を望まないときは、無理に呼ぶのではなく、面談の回数を増やす、ほかの担当者が同席するなど、会社の手順にある別の方法で、ご理解と意思を確かめます。断られた事実と、代わりにどう確かめたかを記録に残します。", acts:["同席をお願いする理由を、ご本人を守るためだと短く伝える", "断られたら、会社の手順にある代わりの方法（面談を重ねる・別の担当者の同席など）を選ぶ", "断られた事実と、代わりの確かめ方を面談の記録に残す", "迷ったら、その日のうちに上長へ相談してから次に進む"], actHead:"現場で使うなら", note:"対象のお客様・同席の要否・代わりの方法は、所属の保険会社と御社の手順で決まっている。コンプライアンス担当で確かめる。", go:"iko", pre:1, say:"ご家族にお声がけするのは、お客様ご自身が安心してお決めになれるようにするためです。ご希望でなければ、別の形で丁寧に確かめさせてください。", more:"よくあるのは、子どもに心配をかけたくない、自分のお金のことは自分で決める、とおっしゃる場面です。その気持ちは大事にしつつ、日を改めてもう一度説明を聞いていただく、書面を持ち帰って読んでいただく、といった形で、ご本人が内容を分かって決めたことを確かめます。", why:"ご高齢のお客様の契約は、あとでご家族から、本人は分かっていなかったと言われることがあるからです。同席や複数回の面談は、ご本人の意思で決めたことを示し、ご本人とご家族の両方を守る仕組みです。" },
      { key:'faq_xcmp_kourei_isogu', faq:1, grp:'cmp', q:"ご高齢のお客様が、一回の面談で決めたいと言う", re:/(高齢|年配|ご年配|お年寄り)[^。]{0,16}((一回|一度|1回)(の面談)?で|その場で|今日のうちに|今日中に|すぐに)[^。]{0,12}(決め|申し込|申込|契約|済ませ)|(高齢|年配)[^。]{0,14}何度も来なくて/, ng:/部下|後輩|新人|メンバー|(自分|私|僕|俺|うち)の(親|父|母|祖)|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"その場で決めたいと言われても急がせず、会社の手順に沿って考える時間を挟みます。", body:"ご高齢のお客様の中には、何度も時間を取らせたくない、早く済ませたいと考える方がいます。それでも、説明を一度で終わらせて申込みまで進めると、ご本人が内容を分かって決めたかを確かめにくくなります。会社の手順で面談を複数回にすると決めている場合はそれに従い、書面を持ち帰っていただく時間をとります。", acts:["説明の日と申込みの日を分けることを、お客様を守るためだと伝える", "書面を置いていき、次の面談で分からなかった点を伺う", "その場で決めたいと言われた事情も、面談の記録に残す"], actHead:"現場で使うなら", note:"面談の回数・日を分けるかどうか・対象のお客様は、所属の保険会社と御社の手順で決まっている。迷ったら上長とコンプライアンス担当へ。", go:"iko", pre:1, say:"お気遣いありがとうございます。大事なお金のことですので、一度ゆっくりお読みいただいて、次にお会いしたときにお決めください。その場で決めていただく必要はありません。", more:"よくあるのは、前の担当者とは一度で済んだ、と言われる場面です。そのときも、会社の決まりで日を分けていることを穏やかに伝えます。次の面談では、前回の説明を覚えておられるかを、お客様ご自身の言葉で話していただくと、ご理解の度合いが分かります。", why:"一度の面談で決めた契約は、あとで本人が十分に考えられなかったと言われたときに、それを打ち消す材料がないからです。日を分けることは、急かされずに決めたことの証にもなります。" },
      { key:'faq_xcmp_kujo_kubetsu', faq:1, grp:'cmp', q:"これは苦情？要望や意見との違いは？", re:/(苦情|クレーム)[^。]{0,6}(に当たる|になる|に入る|として扱|かどうか|との違い|と要望|と(ご)?意見)|(要望|意見|文句|不満|問い合わせ)[^。]{0,10}(苦情|クレーム)[^。]{0,8}(当たる|扱|違い|区別|見分け|線引き|どうか)|(苦情|クレーム)と(要望|意見|問い合わせ)[^。]{0,8}(違い|区別|見分け)/, ng:/部下|後輩|新人|メンバー|カスハラ|暴言|怒鳴|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"お客様の不満の表明は、言い方の強さにかかわらず、苦情として扱い記録するのが基本です。", body:"多くの保険会社や代理店は、お客様が不満を表したものを、強い口調かどうか、担当者が正しいと思うかどうかに関係なく、苦情として扱います。要望や問い合わせに見えても、裏に不満があれば同じです。迷ったときは、苦情として記録する側に倒します。小さな声を拾うほど、同じことが繰り返されるのを防げます。", acts:["迷ったら苦情として、その日のうちに台帳に記録する", "お客様の言葉を、こちらの言い換えをせずにそのまま書き取る", "要望として受けたものも、対応した内容と一緒に残す"], actHead:"現場で使うなら", note:"苦情の定義・記録する範囲・報告の流れは、所属の保険会社と御社の苦情対応の規程で決まっている。苦情の窓口とコンプライアンス担当で確かめる。", go:"kujo", pre:1, say:"ご不便をおかけして申し訳ありません。いただいたお声は、会社としてきちんと記録し、改善に生かします。", more:"見落としやすいのは、手続きが遅い、説明が分かりにくかった、連絡が来ない、といった静かな不満です。お客様は苦情と言わずに伝えることが多く、担当者が要望として流すと、台帳に残りません。後で同じ不満が大きくなって戻ってきたとき、最初の記録が無いことが問題になります。", why:"苦情は、お客様が感じた不満を会社が知り、仕組みを直すための材料だからです。担当者の判断で苦情から外すと、本当は直すべき問題が見えなくなります。" },
      { key:'faq_xcmp_kujo_okure', faq:1, grp:'cmp', q:"苦情の報告が遅れてしまった", re:/(苦情|クレーム|不満|お申し出)[^。]{0,14}(報告|台帳|記録|伝え|共有)[^。]{0,10}(遅れ|忘れ|していな|してない|ていなかっ|てなかっ|せず|しなかっ)|(苦情|クレーム|不満)[^。]{0,14}自分で(処理|片付け|対応|済ませ)/, ng:/部下|後輩|新人|メンバー|なぜ|何のため|どうして|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"遅れに気づいたら、遅れた事実も含めて、すぐ上長と苦情の窓口に報告します。", body:"苦情の報告が遅れたことに気づいたら、そのままにしたり、なかったことにしたりせず、すぐに報告します。受けた日と、報告が遅れた理由も正直に伝え、台帳には受けた日のまま記録します。お客様にまだ返事をしていないなら、次にいつ誰から連絡するかを、上長と決めてからお伝えします。", acts:["気づいたその日に、受けた日・お客様の言葉・これまでの対応を上長へ伝える", "台帳には、受けた日と報告した日の両方を正直に書く", "自分で約束したことがあれば、それも漏らさずに伝える"], actHead:"今日やること", note:"報告の期限・報告先・保険会社への連絡の要否は、御社の苦情対応の規程と所属の保険会社の決まりで違う。苦情の窓口とコンプライアンス担当で確かめる。", go:"kujo", pre:1, say:"ご連絡が遅くなり、申し訳ありません。いただいたお話は会社にきちんと伝えました。次は、担当の者から改めてご連絡いたします。", more:"遅れやすいのは、その場で謝って収まったように見えた苦情や、自分の説明の不足が原因の苦情です。自分で片付けたつもりでも、お客様の中では終わっていないことがあります。報告の遅れそのものを責められるのが怖くても、隠すほうが後で何倍も重くなります。", why:"苦情は、会社として受け止めて仕組みを直すものだからです。担当者のところで止まると、同じことがほかのお客様にも起き、保険会社への報告が必要な場合にも間に合わなくなります。" },
      { key:'faq_xcmp_kujo_adr', faq:1, grp:'cmp', q:"お客様が協会の相談所に申し立てると言っている", re:/(協会|相談所|adr|紛争解決|金融庁|消費生活センター|消費者センター)[^。]{0,14}(申し立て|申立|相談する|訴え|言う|言います|通報|持ち込)/, ng:/部下|後輩|新人|メンバー|協会けんぽ|健康保険協会|ガイドライン|検査/, head:"申し立ては、お客様の正当な手続きです。止めずに、すぐ上長と苦情の窓口に報告します。", body:"保険の苦情や紛争には、生命保険協会の生命保険相談所や、日本損害保険協会のそんぽADRセンターなど、裁判の外で話し合う仕組みがあります。お客様がそこへ相談すると言われたら、止めたり思いとどまるよう説得したりせず、受け止めます。そのうえで、すぐに上長と御社の苦情の窓口に伝え、保険会社と連絡を取りながら進めます。", acts:["申し立てを止めず、お客様のお考えを最後まで伺う", "その日のうちに、上長と苦情の窓口へ、経緯とお客様の言葉を伝える", "自分だけで約束や交渉をせず、会社と保険会社の対応に合わせる", "これまでのやりとりの記録を、そのままの形でそろえておく"], actHead:"今日やること", note:"紛争解決の手続きへの対応は、所属の保険会社と御社の苦情対応の規程で決まっている。苦情の窓口・コンプライアンス担当・保険会社の指示に従う。", go:"kujo", pre:1, say:"ご相談になるのは、お客様のお考えのとおりで構いません。私からも会社にきちんと伝え、誠実に対応させていただきます。", more:"よくあるのは、苦情のやりとりがこじれて、お客様が外の窓口の名前を出す場面です。ここで慌てて約束をしたり、申し立てを取り下げてもらおうとしたりすると、かえって不信が深まります。これまでの面談の記録や意向把握の記録が、事実を示す材料になります。", why:"外の窓口は、お客様と保険会社の間に中立の立場で入り、話し合いを助ける仕組みだからです。申し立てを止めようとすること自体が、お客様の権利を妨げたと受け取られます。" },
      { key:'faq_xcmp_kujo_shazai', faq:1, grp:'cmp', q:"クレームの電話で、その場で謝ってもいい？", re:/(クレーム|苦情|怒られ|お叱り|不満)[^。]{0,16}(謝って|謝る|謝罪|お詫び|非を認め)|謝(ると|ったら|れば)[^。]{0,8}(責任を認め|非を認め|認めたこと)|(苦情|クレーム)[^。]{0,12}(補償する|弁償する|払いますと|約束して)/, ng:/部下|後輩|新人|メンバー|上司|カスハラ|土下座|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"不快な思いをさせたことへのお詫びはしてよく、事実を確かめる前に非や補償は約束しません。", body:"お客様が怒っているとき、まずご不便やご心配をおかけしたことにお詫びするのは自然な対応です。ただし、原因を確かめる前に、こちらの誤りだと言い切ったり、補償や返金を約束したりはしません。事実を確かめ、会社として答えを出すのは、上長と苦情の窓口の役目です。", acts:["お気持ちへのお詫びと、事実を確かめることを分けて伝える", "その場で約束せず、いつ誰から連絡するかだけをお伝えする", "お客様の言葉と、自分が伝えたことを、そのまま記録に書き取る"], actHead:"現場で使うなら", note:"苦情の受け方・お詫びの伝え方・補償の判断は、御社の苦情対応の規程と所属の保険会社の決まりで決まっている。法律上の責任の判断は弁護士の領分。", go:"kujo", pre:1, say:"ご心配とご不快な思いをおかけして、申し訳ありません。事実をしっかり確かめて、改めて会社からご連絡いたします。", more:"言ってしまいがちなのは、私のミスです、全額お返しします、といった一言です。担当者の言葉は会社の約束として受け取られるので、確かめる前に言うと、後で違ったときにさらに大きな苦情になります。お詫びは気持ちに対して、判断は会社として、と分けて考えます。", why:"お客様の気持ちに寄り添う言葉と、責任や補償の判断とは別のものだからです。担当者がその場で判断を言うと、会社の対応と食い違い、お客様をもう一度失望させることになります。" },
      /* dun.json */
      { key:'faq_xdun_tesuryo', faq:1, grp:'dun', q:"代理店手数料はどういう仕組みで支払われる？", re:/代理店手数料|(代理店|代理店側)(の|が|に|へ)[^。]{0,6}手数料[^。]{0,10}(仕組み|出て|入る|支払|払われ|どこから|決まる|決まり)|手数料(は|が)?[^。]{0,4}(どこから|どういう仕組み)/, ng:/お客様|聞かれ|言われ|疑われ|いくら|開示|評価|品質|高い商品|戻入|返す|返還|明細|内訳|解約|失効|取り消|取消|消滅/, head:"代理店手数料は、保険会社が委託契約と手数料の決まりに沿って代理店へ払うものです。", body:"代理店は保険会社から募集や事務を任され、その対価として手数料を受け取ります。お金の出どころは、お客様の保険料のうち保険会社の運営にあてる部分で、お客様から別にいただくものではありません。率や支払いの時期は、保険会社・商品・委託契約の決まりで違います。", acts:["手数料の決まり（手数料の規程など）は、保険会社から渡された資料で確かめ、社内の担当と読む", "保険会社から届く手数料の明細と、自分が預かった契約の記録を月ごとに突き合わせる", "お客様に手数料を聞かれたときの答え方は、御社の決まりを先に確かめておく"], actHead:"今日やること", note:"率・支払いの時期・計算の決まりは、保険会社と委託契約で違う。所属の保険会社の手数料の資料と御社の担当で確かめる。", pre:1, say:"私どもは保険会社から募集とお手続きを任されていて、その分を保険会社から受け取っています。保険のご契約について、お客様から別にいただくものはありません。", more:"手数料は、新しく預かった契約の分と、続いている契約の分で決まりが違うことがあります。損害保険では、代理店の取り組みの評価で率が変わる仕組みを持つ保険会社もあります。明細の項目の名前は保険会社ごとに違うので、初めて見るときは保険会社の担当に読み方を聞きます。", why:"保険会社は自社で全てのお客様に会えないため、募集と手続きを代理店に任せ、その仕事の対価を手数料として払う形をとっているからです。率が保険会社ごとに違うのは、商品や任せる仕事の範囲がそれぞれ違うためです。" },
      { key:'faq_xdun_reinyu', faq:1, grp:'dun', q:"契約がすぐ解約されたら、代理店手数料はどうなる？", re:/戻入|(解約|失効|消滅|取り消|取消)[^。]{0,14}手数料[^。]{0,10}(返|戻|差し引|どうなる)|手数料[^。]{0,10}(返す|返還|返金|戻す|差し引かれ)/, ng:/値引|割戻|還元|お客様に返|お客様へ返|キャッシュバック/, head:"早い時期の解約や失効では、受け取った手数料の一部を返す決まりがあるのが一般的です。", body:"多くの保険会社では、契約が早い時期に解約・失効したり、取り消されたりすると、受け取った代理店手数料の一部を保険会社へ返す決まりがあり、戻入などと呼ばれます。どの時期の解約が対象か、どれだけ返すか、どう返すかは、保険会社と商品、委託契約で決まっています。", acts:["手数料の資料で、戻入の対象になる時期と計算の考え方を確かめておく", "早く解約されたお客様には、理由を伺い、困りごとを記録に残す", "解約や失効が続く契約は、提案の仕方に無理が無かったかを社内で振り返る"], actHead:"現場で使うなら", note:"対象の時期・返す額の決まりは、保険会社・商品・委託契約で違う。所属の保険会社の手数料の資料と御社の担当で確かめる。", pre:1, say:"ご事情が変わったときは、いつでもご相談ください。続け方を変える方法も、やめる場合のお手続きも、ご一緒に確かめます。", more:"戻入の決まりは、契約が続くことを前提に手数料を払っているために置かれています。早い解約や失効が多い代理店は、保険会社の点検で募集の仕方を問われることがあります。数字のために解約を止める話にせず、お客様の事情に合った続け方があるかを一緒に確かめる、という順番を守ります。", why:"手数料は、契約が続いてお客様を支えることへの対価として払われているので、すぐに終わった契約ではその一部を返す形にして、無理な募集が起きにくいようにしているからです。" },
      { key:'faq_xdun_meisai', faq:1, grp:'dun', q:"保険会社から届く手数料の明細は、どう見ればいい？", re:/手数料(の)?(支払)?(明細|内訳|計算書|支払通知)|明細[^。]{0,8}手数料/, ng:/お客様に|聞かれ|開示|いくら/, head:"手数料の明細は、自分の契約の記録と月ごとに突き合わせて見ます。", body:"手数料の明細には、契約ごとの保険料や手数料、新しく預かった分と続いている分、返す分などが載るのが一般的です。自分が預かった契約が載っているか、知らない契約や載っていない契約が無いかを、社内の記録と照らします。合わないものは、自分で直さず保険会社の担当に確かめます。", acts:["明細と社内の契約の記録を並べ、載っていない契約・知らない契約に印を付ける", "合わない理由が分からないものは、契約の番号を添えて保険会社の担当に聞く", "突き合わせた日と、確かめた結果を記録に残しておく"], actHead:"今日やること", note:"明細の項目・載る時期・計算の決まりは、保険会社と委託契約で違う。所属の保険会社の手数料の資料と担当者で確かめる。", pre:1, say:"ご契約の内容は、保険会社の記録と当社の記録を照らして、決まった時期に確かめています。", more:"よくあるずれは、成立の時期が遅れた契約、払い方を変えた契約、担当を替えた契約、保険料が返された契約です。突き合わせを続けると、事務の誤りや手続きの漏れに早く気づけます。明細は手数料の話だけでなく、契約の状態を確かめる材料にもなります。", why:"手数料の明細は保険会社の記録から作られるので、社内の記録と照らすことで、手続きの漏れや誤りを両方の側から見つけられるからです。" },
      { key:'faq_xdun_seisan', faq:1, grp:'dun', q:"保険会社との保険料の精算額が合わない", re:/精算[^。]{0,10}(合わな|ずれ|違う|違って|差が|食い違)|精算(額|書)/, ng:/経費|交通費|領収書をどこ|立て?替|肩代わり/, head:"精算が合わないときは、契約ごとに突き合わせて、ずれた契約と理由を特定します。", body:"保険料の精算は、代理店が受け取った保険料と保険会社の記録を照らして、決められた形でお金を動かすものです。合わないときは、全体の額で埋め合わせず、契約ごとに受け取った額・時期・払い方を照らして、どの契約がずれているかを先に見つけます。自分のお金で差を埋めたり、次に回して黙ったりしません。", acts:["精算書と社内の受け取りの記録を契約ごとに並べ、ずれた契約に印を付ける", "ずれの理由（受け取り漏れ・払い方の変更・解約の扱い）を書き出して上長に渡す", "保険会社の担当には、契約の番号と社内の記録を添えて確かめる"], actHead:"今日やること", note:"精算の方法・時期・ずれたときの扱いは、所属の保険会社と委託契約で決まっている。保険会社の事務の手引きと御社の担当で確かめる。", pre:1, say:"お預かりした保険料は、保険会社の記録と照らして確かめています。気になる点があれば、領収の控えをご一緒に見せていただけますか。", more:"ずれの原因で多いのは、受け取ったのに記録していない保険料、払い方や保険料が途中で変わった契約、解約や減額で保険料が戻った契約、別の契約の分として記録した保険料です。原因が分かったら、直し方を保険会社と決め、直した中身と日付を記録に残します。", why:"保険料はお客様からお預かりしたお金で、代理店のお金と混ぜないことが求められているからです。全体の額だけで合わせると、どのお客様のお金がどうなったかを後から示せなくなります。" },
      { key:'faq_xdun_shiteki', faq:1, grp:'dun', q:"保険会社の点検で指摘を受けたら、何をする？", re:/(点検|監査)[^。]{0,10}(指摘|改善を求め|是正)[^。]{0,12}(直|改善|報告|是正|進め|何を|どう|対応)|指摘(を)?(受け|され)[^。]{0,10}(直|改善|報告|是正|進め|何を)/, ng:/書類が不備|差し戻/, head:"指摘は、原因・直し方・期限・確かめ方の四つに分けて、記録に残して進めます。", body:"指摘を受けたら、まず指摘の中身をそのまま書き写し、その場で分からなかった点は保険会社の担当に聞き直します。次に、なぜ起きたか（手順が無い・手順はあるが守られていない・人が足りない）を分け、直し方と終える日を決めます。直したあとは、同じことが起きていないかを日を置いて確かめ、その記録も残します。", acts:["指摘の文をそのまま一覧に書き写し、一つずつ番号を振る", "番号ごとに、原因・直し方・担当・終える日を一行で書く", "直したあと、同じ記録を日を置いてもう一度確かめる日を決める"], actHead:"今日やること", note:"改善の報告の様式・出す先・期限は、所属の保険会社の点検の手引きと指示に従う。社内の担当と所属の保険会社の担当で確かめる。", pre:1, say:"ご契約の手続きについて、社内の確かめ方を見直しています。お手続きの書類で、もう一度ご確認をお願いすることがあります。", more:"指摘で多いのは、記録が残っていない・決めた手順と実際が違う・確かめた人が分からない、の三つです。直し方は、書き方を決める・確かめる人と時期を決める・抜き取りで見る、のどれかに落とすと続きます。個人のがんばりに頼る直し方は、人が替わると元に戻ります。", why:"点検は代理店を責めるためではなく、お客様への手続きが決めたとおりに行われているかを確かめるものだからです。直した記録が残っていれば、次の点検で同じ所を説明できます。" },
      { key:'faq_xdun_iten', faq:1, grp:'dun', q:"事務所を移転するとき、何を届け出る？", re:/(事務所|店舗|代理店|営業所|本店)[^。]{0,8}(移転|引っ越|住所が変わ|所在地)/, ng:/お客様の住所|ご住所|お客様が引っ越/, head:"移転は、届け出・保険会社への知らせ・お客様への案内の三つに分けて、日付を決めて進めます。", body:"代理店の所在地は、登録や委託契約の中身に入っていることがあり、変わるときは届け出が要ることがあります。所属の保険会社に移転の予定を早めに伝え、届け出の手続きと時期を確かめます。あわせて、お客様に渡している書類や名刺、ホームページの住所を直し、移転の案内を送ります。", acts:["所属の保険会社の担当に、移転の予定日と届け出の手続きを確かめる", "名刺・封筒・ホームページ・留守番電話など、住所が載っているものを書き出す", "お客様への移転の案内を、いつ誰が送るか決める"], actHead:"今日やること", note:"届け出の要否・様式・時期は、登録の種類と保険会社で違う。所属の保険会社の担当と、登録の手続きの窓口で確かめる。", pre:1, say:"事務所を移すことになりました。新しい住所と連絡先をお知らせします。ご契約の中身は変わりません。", more:"移転で抜けやすいのは、お客様の書類の保管場所と、引っ越しのあいだの郵便です。書類は運ぶ前に一覧にして、運んだあとに数を照らします。郵便は転送の届けを出し、保険会社からの郵便が新しい住所に届くか確かめます。", why:"代理店の住所は、保険会社の記録とお客様への書類の両方に載っているからです。片方だけ直すと、郵便や書類が古い住所に届き、手続きが止まることがあります。" },
      { key:'faq_xdun_houjinka', faq:1, grp:'dun', q:"個人の代理店を法人にするとき、何が要る？", re:/代理店[^。]{0,12}(法人化|法人成り|法人にする|法人に変え|会社にする)|個人(の)?代理店[^。]{0,10}(会社|法人)|個人事業[^。]{0,10}(会社にする|法人)/, ng:/お客様|社長の会社|顧客の|節税|役員報酬|退職金|保険料を経費/, head:"法人にするときは、登録と委託契約を新しい法人で整え直すことが多いので、保険会社と順番を決めます。", body:"個人の代理店を法人にすると、登録や代理店委託契約の名義が個人から法人に変わります。保険会社によっては、新しい法人で委託契約を結び直し、扱っている契約の担当を法人へ移す手続きが要ります。いつ切り替えるか、そのあいだの手数料や事務の扱いをどうするかを、所属の保険会社と先に決めます。", acts:["所属の保険会社ごとに、法人にするときの手続きと必要な書類を確かめる", "登録の届け出と委託契約の切り替えの順番と日付を一覧にする", "税金と会社の作り方は、顧問の税理士・司法書士に相談する日を決める"], actHead:"今日やること", note:"手続き・届け出・委託契約の切り替え方は、保険会社と登録の種類で違う。所属の保険会社で確かめる。税と会社の設立は税理士・司法書士の業務。", pre:1, say:"代理店を会社の形に改めることになりました。ご契約の中身は変わらず、これまでどおり担当いたします。", more:"切り替えの日をまたぐ契約や申込みがあると、どちらの名義で扱うかを決めておかないと事務が混乱します。お客様には、担当する人と連絡先が変わらないことを先に伝えると安心されます。名刺や書類の代理店名も切り替えの日に合わせて直します。", why:"代理店の名義は、登録・委託契約・お客様の契約の担当の三つにつながっているからです。順番を決めずに進めると、一時的に募集できない期間ができることがあります。" },
      { key:'faq_xdun_kokuchi_juryo', faq:1, grp:'dun', q:"告知を受け取る権限は、募集人にある？", re:/告知受領|告知(を)?受(け取|領)[^。]{0,8}権|(口頭|口で|聞いた)[^。]{0,10}(病歴|病気|持病)[^。]{0,8}告知|(病気|病歴|持病)[^。]{0,10}聞いた[^。]{0,8}告知/, ng:/書かなくていい|言わなくていい|黙って|妨害|隠|書かないで/, head:"生命保険の募集人は一般に告知を受け取る権限を持たないので、聞いた内容も告知書に書いていただきます。", body:"告知は、保険会社が引き受けを決めるために、お客様が健康状態などを伝えるものです。生命保険では一般に、募集人に話しただけでは告知したことにならず、告知書や診査で保険会社に伝えます。損害保険の代理店は告知を受け取る立場のことが多いですが、範囲は委託契約で決まります。聞いた内容は、告知書に正しく書いていただくよう案内します。", acts:["お客様が口にした病歴や通院は、告知書のどの問いに当たるか一緒に確かめる", "告知を受け取る権限の範囲を、所属の保険会社の手引きで確かめる"], actHead:"今日やること", note:"告知を受け取る権限の有無と範囲は、保険の種類・保険会社・委託契約で違う。所属の保険会社の手引きと担当で確かめる。", pre:1, say:"いまお聞きした通院のことは、告知書のこの問いに当たるかもしれません。告知書にそのままお書きいただけますか。", more:"口頭で聞いたのに告知書に書いてもらわないと、あとで保険金を受け取れないことにつながるおそれがあります。告知しなくていいと言うことや、書かないよう勧めることは、してはいけない行為です。迷う内容は、保険会社に確かめてから書いていただきます。", why:"告知は、お客様が保険会社に直接伝える形でしか届かないことが多いからです。募集人が聞いて安心してしまうと、お客様の大事な権利が守られなくなります。" },
      { key:'faq_xdun_saigai', faq:1, grp:'dun', q:"大きな災害のとき、代理店の事務はどう動く？", re:/(大きな)?(災害|震災)[^。]{0,10}(事務|連絡|順番|まず何|代理店)/, ng:/地震保険|補償され|出る|対象にな|下りる|おりる/, head:"まず社員の無事を確かめ、保険会社の特別な取扱いの案内を見てから、お客様への連絡の順番を決めます。", body:"大きな災害のあとは、まず社員と家族の無事を確かめます。保険会社は、災害のときに保険料の払込みを待つ扱いや、手続きの書類を簡単にする扱いなどを案内することがあるので、その中身を確かめます。お客様には、被害の大きい地域の方から、無事の確認と、事故の受付の窓口を伝えます。", acts:["社員の無事と、事務所・書類・パソコンの状態を確かめる", "所属の保険会社の災害時の案内を読み、払込みや手続きの特別な扱いを書き出す", "被害の大きい地域のお客様の一覧を作り、連絡の順番を決める"], actHead:"今日やること", note:"災害のときの特別な取扱いの有無と中身は、保険会社と災害ごとに案内される。所属の保険会社の案内で確かめる。", pre:1, say:"ご無事を確かめたくご連絡しました。お困りのことがあれば、保険会社の窓口と私どもで受け付けています。", more:"連絡の一覧は、ふだんから住所の地域ごとに並べられる形にしておくと、災害のときに早く動けます。保険金の受け取りの見込みを、その場で言い切らないことも大切です。被害の調べは保険会社が行います。", why:"災害のあとは、お客様が手続きや払込みのことまで考えられないことが多いからです。保険会社の特別な扱いを伝えられれば、契約が途切れるのを防げることがあります。" },
      { key:'faq_xdun_nijuu', faq:1, grp:'dun', q:"保険料を二重に受け取ってしまったら？", re:/二重(に)?(払|受け取|引き落|入金)|二重払|二回払|重複して(払|入金)|(払いすぎ|払い過ぎ)た?保険料|(保険料)[^。]{0,8}(二重|二回|2回|重複|払いすぎ|払い過ぎ|多く(振り込|払)|余分に)|(二重|二回|重複)(に)?[^。]{0,4}(引き?落とされ|払って|払っ)/, ng:/税|控除|年金|国民健康保険|国保|社会保険/, head:"重なった額と日付を確かめ、返すか次の保険料に充てるかは保険会社の決まりに従い、記録を残します。", body:"保険料の二重払いは、口座振替と現金の両方で払われたときなどに起きます。気づいたら、どの契約の、いつの分が、いくら重なったかを確かめ、上長と保険会社に伝えます。返し方は保険会社の決まりに従い、代理店のお金から立て替えて返すことはしません。返した日と方法を記録に残します。", acts:["重なった契約の番号・払われた日・払われた方法を書き出す", "上長と所属の保険会社の担当に伝え、返し方を確かめる", "お客様に、重なった理由と返し方・返す時期を伝える"], actHead:"今日やること", note:"二重払いの返し方と時期は、保険会社と払い方で違う。所属の保険会社の事務の手引きと担当で確かめる。社内の扱いは御社の規程で確かめる。", pre:1, say:"保険料が重ねてお支払いになっていました。お返しする方法を保険会社と確かめて、改めてご連絡します。", more:"二重払いが起きやすいのは、払い方を変えた月と、口座振替が始まる前の月です。払い方を変える手続きのときに、最初の引き落としの月をお客様に伝えておくと、重なりを防げます。引き落としができなかった月に振込みで払い、そのあと再振替でもう一度引き落とされることもあります。", why:"お預かりした保険料は、お客様のお金だからです。返し方を自分で決めると、保険会社の記録と合わなくなり、あとで精算がずれます。" },
      { key:'faq_xdun_boshunin_ichiran', faq:1, grp:'dun', q:"社内の募集人の登録の状況を一覧で持っておきたい", re:/(募集人|社員)[^。]{0,8}登録(の)?(状況|一覧|状態)|誰がどの保険会社で登録|登録(の)?状況[^。]{0,8}(一覧|まとめ)/, ng:/期限|切れ|更新の案内|継続教育|受講/, head:"人ごとに、登録の種類・扱える保険会社・届け出た日・更新の時期を一つの表にまとめます。", body:"乗合の代理店では、募集人ごとに扱える保険会社や商品の範囲が違うことがあります。誰が、どの保険会社で、どの種類の登録や届け出をしているかを一つの表にしておくと、扱えない商品を案内してしまうことを防げます。入社・退職・異動のたびに表を直し、直した日を書いておきます。", acts:["募集人ごとに、登録の種類と届け出ている保険会社を書き出す", "扱える商品の範囲に違いがある人に印を付け、本人に伝える", "入社・退職・異動のたびに、誰が表を直すか決める"], actHead:"今日やること", note:"登録と届け出の種類・扱える範囲・更新の手続きは、保険の種類と保険会社で違う。所属の保険会社と社内の登録の担当で確かめる。", pre:1, say:"この商品は、私が扱える範囲かを確かめてからご案内します。扱えないときは、扱える者からご説明します。", more:"登録の状況が分からないまま募集すると、届け出ていない保険会社の商品を案内してしまうことがあります。表は社内の決まった場所に一つだけ置き、写しを作らないと、どれが新しいか迷わずに済みます。", why:"募集できるかどうかは、人と保険会社の組み合わせで決まるからです。一覧があれば、扱える人にすぐつなげ、点検でも説明できます。" },
      { key:'faq_xdun_kaiji', faq:1, grp:'dun', q:"お客様から、自分の情報を見せてほしいと言われた", re:/(個人情報|自分の情報|ご自身の情報|私の情報)[^。]{0,10}(開示|見せて|知りたい|訂正)|個人情報の開示|預けた書類[^。]{0,8}(見たい|見せて)/, ng:/手数料|コミッション|他人|家族の|ご家族の|奥様の|ご主人の/, head:"本人かを確かめ、社内の手順で受け付け、保険会社が持つ情報は保険会社の窓口へつなぎます。", body:"お客様には、自分の個人情報の開示や訂正、利用を止めることを求める権利があります。求められたら、まず本人かを確かめ、社内の受け付けの手順に沿って記録します。代理店が持っている情報と、保険会社が持っている情報は扱う先が違うことがあるので、保険会社の記録にあるものは保険会社の窓口へつなぎます。", acts:["求められた中身（見せる・直す・止める・消す）と日付を記録する", "本人の確かめ方と受け付けの手順を、社内の規程で確かめる", "保険会社が持っている情報は、所属の保険会社の窓口へつなぐ"], actHead:"今日やること", note:"受け付けの手順・本人の確かめ方・答える期限は、個人情報の保護の法律と御社の規程、所属の保険会社の決まりで決まる。社内の担当と所属の保険会社で確かめる。法律上の判断は弁護士へ。", pre:1, say:"ご本人様のお申し出として承ります。ご本人様であることを確かめたうえで、決まった手順でご案内します。", more:"担当者が手元の資料を見せて済ませようとすると、見せてよい範囲や、ご本人の確かめを誤ることがあります。自分で判断せず、社内の手順に乗せます。家族からの申し出は、本人の同意を確かめます。", why:"個人情報は、お客様ご本人のものだからです。決まった手順で受け付ければ、本人でない人に情報を渡す間違いを防げます。" },
      { key:'faq_xdun_nukitori', faq:1, grp:'dun', q:"社内で記録を抜き取って確かめるには？", re:/抜き取|抜取|(自己点検|社内(の)?点検)[^。]{0,10}(何件|件数|どう見|選び方)/, head:"期間を決めて記録を無作為に選び、決めた項目で見て、見た結果を記録に残します。", body:"抜き取りで確かめるときは、見る期間を決め、その期間の契約や記録から、選ぶ人の好みが入らないように無作為に選びます。見る項目（意向の確かめ・比べた理由・書類の控え・ご高齢の方への配慮など）を前もって決めておき、一件ずつ同じ項目で見ます。見つかったことと直し方、見た日と見た人を記録に残します。", acts:["見る期間と、一度に見る件数の目安を社内で決める", "見る項目を一枚の表にして、記録ごとに印を付けられる形にする", "見つかったことを、直す人と直す日まで書いて残す"], actHead:"今日やること", note:"抜き取りの件数・頻度・見る項目は、保険会社の点検の手引きと御社の規程で決める。所属の保険会社と社内の担当で確かめる。", pre:1, say:"ご契約の手続きが決めたとおり進んでいるか、社内で確かめています。必要なときは、改めてご確認をお願いすることがあります。", more:"抜き取りは、人を責めるためではなく、手順が守られているかを見るものです。同じ人の記録だけを選んだり、問題がありそうな記録だけを選んだりすると、全体の様子が分かりません。選び方を記録しておくと、点検でも説明できます。", why:"全ての記録を毎回見るのは難しくても、無作為に選んで見れば、手順のずれに早く気づけるからです。結果を残すことが、社内で確かめている証しになります。" },
      { key:'faq_xdun_system_id', faq:1, grp:'dun', q:"保険会社の代理店システムのIDを、ほかの人と使い回していい？", re:/(代理店)?システム[^。]{0,8}(id|ログイン|パスワード)[^。]{0,10}(使い回|共有|貸|教え)|(自分の|募集人の)id(で)?[^。]{0,10}(入れて|手続|代わり)|(id|パスワード)を[^。]{0,8}(共有|使い回)/, head:"IDは一人ずつのものなので貸し借りや使い回しをせず、要る人は自分のIDを申し込みます。", body:"保険会社の代理店システムのIDは、誰が何の手続きをしたかを残すために一人ずつに与えられることが一般的です。ほかの人のIDで手続きを入れると、記録の上では別の人がしたことになり、点検で説明できません。事務員が手続きを入れるなら、事務員用のIDや権限を保険会社に申し込めるか確かめます。", acts:["社内で、IDやパスワードを共有している使い方が無いか洗い出す", "事務員が使うIDと権限を、所属の保険会社に申し込めるか確かめる", "パスワードの管理の決まりを、社内の規程に書く"], actHead:"今日やること", note:"IDの発行・権限の範囲・管理の決まりは、保険会社のシステムの利用の規約で決まる。所属の保険会社の担当と社内の規程で確かめる。", pre:1, say:"お手続きは、担当する者が自分のIDで保険会社のシステムに入れています。", more:"使い回しが起きるのは、事務員にIDが無い、急ぎの手続きを頼みたい、という場面です。誰がどの手続きをするかを決め、その人にIDを用意するほうが、急ぎのときにも安心です。退職した人のIDは、すぐに止める手続きをします。", why:"IDは、誰が手続きをしたかを示す記録そのものだからです。共有すると、お客様の情報を誰が見たかも分からなくなります。" },
      { key:'faq_xdun_taishoku', faq:1, grp:'dun', q:"募集人が退職するとき、事務で何をする？", re:/(募集人|社員|スタッフ)[^。]{0,6}(退職|辞め|やめ)[^。]{0,12}(事務|手続|届|引き継|何を|どうする)|退職する募集人/, ng:/連れて|持って行|引き抜|お客様を|顧客を|辞めたい|辞めようか/, head:"登録の届け出・IDの停止・担当の契約の引き継ぎ・書類の回収を、退職の日までに済ませます。", body:"募集人が退職するときは、登録の抹消などの届け出、保険会社の代理店システムのIDの停止、担当していたお客様の引き継ぎ、渡していた資料や預かり中の書類の回収を進めます。担当していたお客様には、新しい担当と連絡先を知らせます。退職したあとも、お客様の情報を持ち出さないことを本人と確かめます。", acts:["退職の日と、届け出・IDの停止・引き継ぎの日を一覧にする", "担当していた契約を一覧にし、新しい担当を決める", "渡していた資料・預かり中の書類・パソコンの中の情報を回収する"], actHead:"今日やること", note:"届け出の手続きと時期・IDの止め方は、登録の種類と保険会社で違う。所属の保険会社と社内の規程で確かめる。労務の手続きは社会保険労務士へ。", pre:1, say:"これまでの担当が代わりますが、ご契約はこれまでどおり続きます。新しい担当と連絡先をお知らせします。", more:"引き継ぎは、手続き中の契約、満期や更新が近い契約、苦情の対応中の契約を先にします。前の担当が口頭で聞いていたお客様の要望は、記録に書き出してもらってから引き継ぎます。", why:"退職した人の登録やIDが残ったままだと、誰が手続きをしたかが分からなくなるからです。お客様にとっても、担当の空白は不安につながります。" },
      /* hei.json */
      { key:'faq_xhei_kaitaku', faq:1, grp:'hei', q:"法人の新規開拓はどこから始める？", re:/(法人|会社|企業)[^。]{0,4}(の)?(新規)?(開拓|お客様を増や|顧客を増や|お客様を(一から)?作|顧客を作|マーケット)/, ng:/部下|後輩|新人|メンバー|自分の会社|うちの会社|うちの代理店|わが社|社内/, head:"法人の開拓は、今のお客様の中にいる経営者と、その周りの会社から始めます。", body:"名簿を買って電話をかけるより、既にお付き合いのある個人のお客様の中の経営者や役員、お勤め先、ご親族の会社など、つながりのあるところから当たるほうが話を聞いていただきやすくなります。最初の面談は保険の話ではなく、会社の歩みと社長の悩みを伺う場にします。", acts:["既契約のお客様の一覧から、経営者・役員・自営の方に印を付けて書き出す", "印を付けた方に、会社のことを伺いたいとお願いする連絡の文を作る", "最初の面談で伺うことを、会社の歩み・今の悩み・これからの予定の三つに絞る"], actHead:"現場で使うなら", note:"業種ごとの決まりや、勤め先の会社への接し方は、御社の手順と所属保険会社のコンプライアンスの決まりで確かめる。", pre:1, say:"保険のご案内ではなく、会社のこれまでとこれからを一度伺えればと思っています。お時間をいただけるときに、お話を聞かせてください。", more:"一緒に見るのは、既契約のお客様のご職業とお勤め先の欄です。よくある勘違いは、法人は飛び込みで開くものだと思い込むことで、実際は個人のお客様の紹介や、会社の集まりでのご縁から始まることが多くあります。初めから決算書を求めず、会社の話を伺う回を重ねてから、数字の話に進みます。", why:"社長は日ごろから多くの営業を受けていて、知らない相手の話にはなかなか時間を割きません。つながりのある方からの紹介や、既に信頼のある関係の延長だと、話を聞く理由が先にあるためです。" },
      { key:'faq_xhei_fukuri_iriguchi', faq:1, grp:'hei', q:"福利厚生の提案は何から話す？", re:/(福利厚生|従業員向けの制度|社員向けの制度)[^。]{0,10}(何から|入口|入り方|どう入|切り出|話の入|始め)/, ng:/養老|ハーフ|うちの会社|自分の会社|社内|わが社|法定|部下|後輩/, head:"福利厚生の話は、社長が社員にどうなってほしいかを伺うところから始めます。", body:"福利厚生は、社員の採用・定着・安心のために会社が用意する仕組みです。社長が社員に長く働いてほしいのか、万一のときに家族を守りたいのか、老後の準備を手伝いたいのかで、合う仕組みが変わります。今ある制度（退職金・休みの制度・団体の保険など）を一覧にしてから、足りないところを社長と考えます。", acts:["社長に、社員にどうなってほしいかを一言で伺う", "就業規則や退職金の規程など、今ある制度を一覧にしていただく", "保険で用意できるものと、公的な制度や共済で用意できるものを並べて見せる"], actHead:"現場で使うなら", note:"就業規則と労務の扱いは社会保険労務士、経理と税の扱いは顧問の税理士、制度の細部は所属保険会社の資料で確かめる。", pre:1, say:"社員の方に、どんなふうに働き続けてほしいとお考えですか。そのお考えに合う仕組みを、今ある制度と並べて整理してみたいと思います。", more:"場面の例は、若い社員がすぐに辞めてしまうと悩む社長です。この場合は、万一の保障より、長く働くほど積み上がる仕組みや、休みの取りやすさのほうが社長の思いに近いことがあります。よくある勘違いは、福利厚生を保険の商品の話から始めることです。", why:"福利厚生は社長から社員への約束で、その中身は社長の思いで決まるためです。思いが言葉になっていると、社員にも伝わり、制度が長く続きます。" },
      { key:'faq_xhei_kessansho_kaeshi', faq:1, grp:'hei', q:"決算書を見せてもらったあと、社長に何を返す？", re:/決算書[^。]{0,10}(見せてもらった|見せていただいた|見たあと|見た後|預かった|お預かりした|見せてくれた|目を通した)[^。]{0,16}(返す|伝え|お返し|まとめ|報告)|(預かった|お預かりした|見せてもらった|見せていただいた)決算書[^。]{0,16}(返す|伝え|お返し|まとめ|報告)/, ng:/部下|後輩|返却|返し方|いつ返|どう返せ|返せばいい|原本|写し|コピー|持ち帰|保管|見方|どこを見|どこから見|読み方/, head:"見て分かったことと、次に一緒に確かめたいことを、一枚にまとめてお返しします。", body:"見せていただいたまま何も返さないと、社長は何に使われたのか分からず、次からは見せにくくなります。手元のお金・借入の残り・利益の流れのうち、保険と関わるところで分かったことを短く書き、次に社長に伺いたいことを添えます。数字の良し悪しの評価や税の判断は書かず、気になる点は顧問の先生に確かめていただく形にします。", acts:["分かったことを、手元のお金・借入・利益の流れの三つの欄に一行ずつ書く", "保険と関わる点と、次に社長に伺いたいことを一つずつ添える", "税や経理で気になる点は、顧問の先生に確かめていただくよう書き添える"], actHead:"現場で使うなら", note:"決算書から写した数字の扱いと保管は、御社の個人情報と機密の扱いの手順で確かめる。経理と税の判断は顧問の税理士の領分。", pre:1, say:"見せていただいた決算書から、保険と関わるところで分かったことを一枚にまとめてきました。次は、借入の返済の予定について伺えればと思っています。", more:"よくある失敗は、返す一枚に会社の数字の評価を書き込み、社長の経営を採点しているように見えることです。書くのは、分かったことと、次に伺いたいことだけです。社長が数字の意味を尋ねてきたら、顧問の先生と一緒に確かめましょうと返します。", why:"見せたものが役に立ったと分かると、社長は次の相談を持ちかけやすくなるためです。評価をせずに整理だけを返す担当は、会社の数字を預けても安心な人として受け止められます。" },
      { key:'faq_xhei_kiridashi_jigyo', faq:1, grp:'hei', q:"事業保障の話を、社長にどう切り出す？", re:/(事業保障|事業の保障|会社の備え|借入の返済の備え|社長に万一のとき)[^。]{0,12}(切り出|持ち出|きっかけ|どう始め|話をする|話し始め|話の入)/, ng:/部下|後輩|刺さらな|聞き流|必要額|いくら|計算|自分の/, head:"社長が会社を空けたら、誰が仕事とお金を回すかを伺うところから入ります。", body:"事業保障の話を、社長に万一があったらという言葉から始めると、身構えられたり、縁起でもないと言われたりします。先に、社長が出張や入院で会社を空けたときに、取引先との約束・社員の給料・借入の返済を誰が回すのかを伺います。答えに詰まるところが、備えを考える場所です。そのうえで、必要なお金を決算書から一緒に書き出します。", acts:["社長が会社を空けるときに、仕事とお金の判断を誰が代わるかを伺う", "取引先・社員・借入の三つについて、止まると困るものを社長に挙げていただく", "必要なお金の考え方は、決算書を一緒に見る次の面談に回す"], actHead:"現場で使うなら", note:"必要なお金の考え方は会社ごとに違うので、決算書と顧問の税理士の確認で整理する。商品の説明は所属保険会社の資料と募集の決まりに沿う。", pre:1, say:"社長が出張やご病気で会社を空けられたとき、取引先とのお約束や社員のお給料、借入の返済は、どなたが判断されますか。一度一緒に整理してみませんか。", more:"場面の例は、社長が全ての判断を一人でしていて、奥様も役員も会社のお金の流れを知らない会社です。このときは保険の前に、誰が何を知っておくかを整える話になります。よくある勘違いは、事業保障を保険の額の話から始めることで、額は会社の事情を書き出したあとに決まります。", why:"社長は会社の将来を自分の責任として考えていて、責任の話として入ると、自分のこととして受け止めやすいためです。縁起の悪い話から入ると、社長は話を終わらせようとします。" },
      /* hzi.json */
      { key:'faq_xhzi_jishin_taisho', faq:1, grp:'hzi', q:"地震保険料控除の対象になるのはどんな建物？", re:/地震保険(料)?の?控除[^。]{0,16}(対象|どんな|建物|別荘|店舗|併用|家財|賃貸|貸)|(別荘|店舗|併用|貸家|賃貸|家財)[^。]{0,16}地震保険[^。]{0,6}控除/, head:"対象は、ご本人や生計を一にするご家族が住む家と、その家財にかけた地震保険です。", body:"地震保険料控除の対象は、本人や生計を一にする親族が持ち、ふだん住んでいる家屋と、暮らしに使う家財を保険の目的にした地震保険の保険料です。別荘や貸している家、事業だけに使う建物の地震保険は対象になりません。店舗と住まいが一緒の建物は、住まいとして使っている部分に応じて扱う決まりがあります。", acts:["証券で、保険の目的が住まいの建物か家財かを一緒に確かめる", "貸家や別荘の契約があれば、控除証明書が届いても対象にならないことがあると添える", "店舗と住まいが一緒の建物は、税務署か税理士で扱いを確かめていただく"], actHead:"現場で使うなら", note:"対象の範囲と併用住宅の扱いは国税庁タックスアンサーで確かめる。個別の税の判断は税理士。証明書は保険会社が出す。", pre:1, say:"地震保険料控除は、お住まいの家と家財にかけた地震保険が対象です。貸しているお部屋や別荘の分は対象外になる仕組みなので、どの契約が対象か一緒に確かめましょう。", more:"よくある勘違いは、地震保険の控除証明書が届けば全てを申告に入れてよいと考えることです。賃貸に出しているお部屋の地震保険は、この控除の対象になりません。不動産の収入がある方は、収入の計算の側で扱う話になるので、税理士に確かめていただきます。", why:"地震保険料控除は、暮らしの土台である住まいと家財を地震に備えることを後押しする趣旨の控除なので、本人や家族が住む家に絞って認められているからです。" },
      { key:'faq_xhzi_kyuchouki', faq:1, grp:'hzi', q:"旧長期損害保険料の控除とは？", re:/長期損害保険料?|(昔|古い|以前|前から)[^。]{0,8}(長期|積立)[^。]{0,10}(火災保険|損害保険|傷害保険)[^。]{0,12}(控除|年末調整)/, head:"前の制度のときに契約した長期の損害保険に、経過的に残っている控除の扱いです。", body:"損害保険料の控除は今の地震保険料控除に切り替わりましたが、切り替えの前に契約した、保険期間が長く満期返戻金のある損害保険には、経過措置として旧長期損害保険料の控除が残っています。地震保険料と合わせて使える上限があり、一つの契約がどちらにも当たるときはどちらか一方で数えます。契約の内容を変えると対象から外れることがあります。", acts:["保険会社の控除証明書に、旧長期損害保険料の欄があるかを一緒に見る", "長く続いている積立型の火災保険や傷害保険があるかを、証券で確かめる", "契約の変更を考えるときは、控除の扱いが変わるかを先に保険会社に確かめる"], actHead:"現場で使うなら", note:"経過措置の対象の要件・上限・契約を変えたときの扱いは、国税庁タックスアンサーと保険会社で確かめる。個別の判断は税理士。", pre:1, say:"古くからの長期の損害保険には、今も控除が残っていることがあります。届いている控除証明書に欄があるか、一緒に確かめてみましょう。", more:"よくある場面は、ずっと前に入った積立型の火災保険や傷害保険が続いていて、控除証明書に旧長期損害保険料と書かれているのに、年末調整で地震保険の欄だけ見て書き漏らすことです。逆に、契約を途中で変えたあとに、もとの控除のまま書いてしまうこともあるので、証明書の区分を見ます。", why:"控除の制度が変わったとき、それまで長い期間で契約していた方の扱いが急に変わらないよう、前の契約に限って経過的に前の扱いを残しているからです。" },
      { key:'faq_xhzi_sonpo_kojo', faq:1, grp:'hzi', q:"火災保険や自動車保険の保険料は控除になる？", re:/(火災保険|自動車保険|車の保険|傷害保険|損害保険)[^。]{0,4}(の|は)?[^。]{0,4}保険料[^。]{0,12}(控除|年末調整|確定申告)|(火災保険|自動車保険|車の保険|傷害保険)[^。]{0,8}(控除|年末調整)/, ng:/地震保険料控除|長期|昔|古い|経費|法人|会社(が|で|の)/, head:"火災保険と自動車保険の保険料は、地震保険の部分を除き、控除の対象になりません。", body:"保険料の控除は、生命保険料控除と地震保険料控除の二つです。火災保険のうち地震保険ではない部分や、自動車保険の保険料は対象になりません（前の制度の長期の損害保険の経過措置は別）。傷害保険やけがだけを補償する特約の保険料も、今の制度の生命保険料控除には入りません。一方、病気の医療費や働けない間の所得を補う損害保険会社の契約には、生命保険料控除の区分に入るものがあります。", acts:["控除証明書が届く契約と届かない契約を、お客様の保険の一覧で分けて見る", "火災保険とセットの地震保険の部分だけが控除になることを、証券の内訳で示す", "事業で使う車や建物の保険料の扱いは、税理士に確かめていただく"], actHead:"現場で使うなら", note:"対象かどうかは保険会社の控除証明書と国税庁タックスアンサーで確かめる。事業用の保険料の扱いは税理士。", pre:1, say:"火災保険と自動車保険の保険料は、地震保険の部分を除いて、年末調整の控除には入らない仕組みです。控除証明書が届いたご契約をお出しいただければ十分です。", more:"よくある勘違いは、損害保険会社の契約は全て控除にならないと考えることです。損害保険会社の医療保険や所得補償保険は、生命保険料控除の区分の証明書が届くことがあります。反対に、生命保険の契約に付けたけがの特約の保険料は、控除の額から外れていることがあります。証明書の額をそのまま使います。", why:"保険料の控除は、生活の保障や老後の準備、住まいの地震への備えを後押しするために、対象を絞って設けられているからです。物や車の損害に備える保険は、その趣旨の外に置かれています。" },
      { key:'faq_xhzi_tochu_kaiyaku', faq:1, grp:'hzi', q:"年の途中で解約した保険も控除になる？", re:/(途中で|年の途中|今年|年内に)[^。]{0,10}解約[^。]{0,16}(控除|年末調整|確定申告)|解約した(保険|契約|生命保険|医療保険)[^。]{0,16}(控除|年末調整|証明書)/, ng:/地震保険|法人|会社(が|で|の)/, head:"その年に払い込んだ保険料は、途中で解約しても、その年の控除の対象です。", body:"生命保険料控除は、その年に実際に払い込んだ保険料をもとに計算します。年の途中で解約した契約でも、解約までに払った分は、その年の控除に入れられます。その年に受け取った配当金などがあれば差し引いた額で数えます。解約した契約の控除証明書は、保険会社によって届く時期が違うので、届かなければ保険会社に頼みます。", acts:["解約の手続きのときに、その年に払った分の控除証明書がいつ届くかを保険会社に確かめて伝える", "年末調整の前に、解約した契約の証明書が手元にあるかを声をかけて確かめる", "乗換のときは、新しい契約と解約した契約の両方の証明書が要ることを添える"], actHead:"現場で使うなら", note:"控除の対象の額と証明書の出し方は、保険会社と国税庁タックスアンサーで確かめる。個別の税の判断は税理士。", pre:1, say:"途中で解約された保険も、今年お払いになった分は控除に入れられる仕組みです。解約した契約の証明書がいつ届くか、保険会社に確かめておきますね。", more:"よくある場面は、見直しで秋に乗り換えたお客様が、新しい契約の証明書だけを年末調整に出し、解約した契約の分を出し忘れることです。出し忘れても確定申告で直せることがあるので、解約の手続きのときに証明書の届く時期を一緒に控えておきます。", why:"保険料の控除は、その年に負担した保険料に応じて所得から差し引く仕組みなので、契約が今も続いているかではなく、その年に実際に払ったかで決まるからです。" },
      { key:'faq_xhzi_haito_kojo', faq:1, grp:'hzi', q:"配当金を受け取ったら保険料控除の額はどうなる？", re:/(配当金|割戻金|剰余金)[^。]{0,20}(保険料)?控除|控除証明書[^。]{0,12}(額|金額)[^。]{0,16}(少な|違う|合わな|低)/, ng:/地震保険|法人|会社(が|で|の)/, head:"その年に受け取った配当金などは、払い込んだ保険料から差し引いて控除の額を数えます。", body:"生命保険料控除の対象になるのは、その年に払い込んだ保険料から、その年に受け取った配当金（剰余金の分配）や割戻金を差し引いた額です。配当金を保険料の支払いにあてた場合も同じく差し引きます。保険会社の控除証明書は、この差し引きをした額で書かれていることが多いので、証明書の額をそのまま使います。", acts:["控除証明書の額が払った保険料と違うと言われたら、配当金の欄を一緒に見る", "配当金の受け取り方（受け取る・積み立てる・保険料にあてる）を、契約概要で確かめる", "合わない理由が分からないときは、保険会社の窓口に証明書の内訳を問い合わせる"], actHead:"現場で使うなら", note:"差し引く額の決まりは国税庁タックスアンサーで、証明書の内訳は保険会社で確かめる。個別の税の判断は税理士。", pre:1, say:"控除の額は、お払いになった保険料から、その年の配当金などを差し引いた額で数える仕組みです。証明書の額が少し少ないのはそのためなので、証明書の額のままお出しください。", more:"よくある勘違いは、払い込んだ保険料の合計を自分で足して申告に書くことです。証明書の額と違うと、勤め先や税務署から確かめの連絡が来ることがあります。配当金の受け取り方によって証明書の書き方が違うので、迷ったら保険会社の窓口で内訳を聞きます。", why:"配当金は、払い込んだ保険料のうち、結果として多く払った分が戻るものと考えられているので、戻った分まで負担した保険料に数えないよう差し引くからです。" },
      { key:'faq_xhzi_zennou', faq:1, grp:'hzi', q:"保険料を前納したら控除はどの年に入る？", re:/(前納|一時払|一括払|まとめて払)[^。]{0,16}(控除|年末調整|証明書)/, ng:/地震保険|法人|会社(が|で|の)/, head:"前納は払込の期日が来た年ごとに、一時払は払い込んだ年に、控除に入ります。", body:"何年分かの保険料を先にまとめて預ける前納は、保険会社が期日ごとに保険料にあてていくので、控除もそれぞれの年に期日が来た分ずつ入ります。一方、一時払いは保険料そのものを一度に払う形なので、払い込んだ年の控除にだけ入り、次の年からは入りません。どちらの払い方かは、契約の払い方の欄と控除証明書で確かめます。", acts:["申込書や証券で、前納か一時払いかを一緒に確かめる", "一時払いの方には、控除に入るのは払い込んだ年だけになることを先に添える", "毎年の控除証明書の額がどう書かれるかは、保険会社に確かめる"], actHead:"現場で使うなら", note:"前納と一時払いの控除の扱いは、国税庁タックスアンサーと保険会社の証明書で確かめる。個別の税の判断は税理士。", pre:1, say:"前納でお預けいただいた保険料は、毎年の期日が来た分ずつ控除に入る仕組みです。一時払いの場合は、お払いになった年だけ控除に入ります。", more:"よくある勘違いは、前納と一時払いを同じものと考えることです。前納は先に預けたお金を毎年の保険料にあてる形で、途中で解約すると、まだあてていない分が戻ることがあります。一時払いは一度で払い込みが終わる契約です。払い方の違いで、控除の入り方も解約したときの戻り方も変わります。", why:"控除は、その年に保険料として払い込まれた額で数えるからです。前納は預けた時点ではまだ保険料にあてられておらず、期日が来て保険料になった年にその分を払ったと見るので、年ごとに分かれます。" },
      { key:'faq_xhzi_danshin_kojo', faq:1, grp:'hzi', q:"団体信用生命保険の保険料は控除になる？", re:/(団信|団体信用(生命)?(保険)?)[^。]{0,16}(控除|年末調整|確定申告)/, ng:/住宅ローン控除|住宅ローン減税|相続/, head:"団体信用生命保険の保険料は、生命保険料控除の対象になりません。", body:"団体信用生命保険は、ローンを借りた方に万一があったとき、保険金が金融機関に支払われて残りのローンにあてられる仕組みです。保険金の受取人がご本人やご家族ではないので、生命保険料控除の対象になりません。がんや三大疾病の上乗せの団信も、保険金がローンの返済にあてられるので同じ扱いです。住宅ローンの控除は、別の仕組みとして考えます。", acts:["団信の保障はローンの返済にあてるものだと、ご家族の暮らしの保障と分けて話す", "年末調整で団信を書こうとしていたら、対象外であることと、届いた証明書の契約だけを出すことを伝える", "住宅ローン控除の手続きは、金融機関の書類と税務署の案内で確かめていただく"], actHead:"現場で使うなら", note:"控除の対象かは国税庁タックスアンサーで確かめる。住宅ローン控除の要件は税務署・税理士、団信の中身は金融機関の書類で確かめる。", pre:1, say:"団信は、もしものときに住宅ローンを返すための保険で、受け取るのは金融機関です。そのため生命保険料控除には入らない仕組みになっています。", more:"よくある場面は、がん団信に入った方が、医療保険と同じように控除になると思っていることです。保険金はローンの返済にあてられるので、扱いは普通の団信と同じです。ご家族の暮らしの保障は、団信とは別に、生活費や教育費から考えます。", why:"生命保険料控除は、受取人の全てがご本人や配偶者などの親族である契約に限って認められています。団信は保険金を金融機関が受け取るので、この要件に当たらないからです。" },
      { key:'faq_xhzi_uketori_kojo', faq:1, grp:'hzi', q:"受取人が親族でない保険も生命保険料控除になる？", re:/受取人[^。]{0,20}(親族(でない|ではない|以外|じゃない)|内縁|友人|知人|法人|会社)[^。]{0,16}(控除|年末調整)|(保険料)?控除[^。]{0,8}受取人[^。]{0,8}(条件|要件|誰)/, head:"生命保険料控除は、受取人の全てがご本人や配偶者などの親族である契約が対象です。", body:"一般の生命保険料控除と介護医療保険料控除は、保険金や給付金の受取人の全てがご本人か、配偶者などの親族である契約に限られます。内縁の方や友人、会社などが受取人だと、保険料を払っていても対象になりません。個人年金保険料控除は、年金の受取人について、さらに細かい要件があります。", acts:["証券で、受取人の欄が誰になっているかを一緒に見る", "受取人を変える相談があれば、控除の扱いも変わることがあると先に伝える", "内縁の方を受取人にできるかは、保険会社の決まりで確かめる"], actHead:"現場で使うなら", note:"受取人の要件と親族の範囲は国税庁タックスアンサーで、受取人に指定できる人は保険会社で確かめる。個別の判断は税理士。", pre:1, say:"保険料の控除は、受取人がご本人やご家族の契約が対象になる仕組みです。受取人の欄を一緒に見て、対象になっているか確かめてみましょう。", more:"よくある場面は、籍を入れていないパートナーや、お世話になった方を受取人にしている契約です。保険会社がその方を受取人として認めていても、控除の要件は税の決まりで別に決まっています。受取人を変えたら、次の年からの控除の扱いが変わることもあります。", why:"生命保険料控除は、ご本人や家族の暮らしを守るための備えを後押しする趣旨の控除なので、保険のお金が家族の外に渡る契約は対象から外しているからです。" },
      { key:'faq_xhzi_gaikoku_kojo', faq:1, grp:'hzi', q:"海外の保険会社の保険料は控除になる？", re:/(海外|外国|香港|シンガポール|アメリカ|米国)[^。]{0,16}(保険|保険会社)[^。]{0,16}(控除|年末調整)|外貨建て?[^。]{0,10}(保険)?[^。]{0,6}(保険料)?(控除|年末調整)/, ng:/個人年金|年金保険|変額/, head:"日本で保険業の免許を持つ会社と国内で結んだ契約が対象で、外貨建てでも同じです。", body:"生命保険料控除の対象は、日本で保険業の免許を受けた保険会社などと結んだ契約です。日本の保険会社の外貨建て保険は対象になり、証明書には円に直した額が書かれます。海外に出かけて、外国の保険会社と海外で結んだ契約は、対象になりません。日本で免許の無い外国の保険会社が日本の方を勧誘することには、別の問題があります。", acts:["外国の保険の話が出たら、どこの会社と、どこで結んだ契約かを先に伺う", "日本の保険会社の外貨建て保険は、届いた証明書の円の額で申告することを伝える", "海外の保険の勧誘を受けている方には、日本で免許があるかを金融庁の登録で確かめるよう添える"], actHead:"現場で使うなら", note:"控除の対象の範囲は国税庁タックスアンサーで確かめる。海外の保険会社の扱いと勧誘の線は、金融庁の案内と御社のコンプライアンス担当で。", pre:1, say:"保険料の控除は、日本で認められた保険会社とのご契約が対象です。日本の会社の外貨建ての保険なら、届く証明書の円の額でお出しいただけます。", more:"よくある場面は、旅行先や知人の紹介で海外の保険に入った方が、日本で控除を使えると思っていることです。対象にならないうえ、受け取るときの税や、日本での手続きにも別の確かめが要ります。外貨建て保険の証明書は、保険会社が円に直した額で書いているので、自分で直さずに使います。", why:"保険料の控除は、日本の監督のもとで営まれている保険の契約を前提にした仕組みなので、外国の会社と海外で結んだ契約まで対象にしていないからです。" },
      { key:'faq_xhzi_shotan_kojo', faq:1, grp:'hzi', q:"少額短期保険の保険料は控除になる？", re:/(少額短期|少短|ミニ保険)[^。]{0,16}(控除|年末調整|確定申告)/, head:"少額短期保険の保険料は、生命保険料控除の対象になりません。", body:"少額短期保険は、少額の保障を短い保険期間で引き受ける事業者が扱う保険で、生命保険会社や損害保険会社とは別の登録の仕組みで営まれています。所得税の生命保険料控除や地震保険料控除の対象は、決められた保険会社や共済などとの契約に限られるため、少額短期保険の保険料は対象になりません。", acts:["少額短期保険の契約がある方には、控除証明書が届かないことを先に伝える", "年末調整の書類を書くとき、控除証明書が届いた契約だけを出すよう添える", "少額短期保険と保険会社の保険の違いは、契約概要と事業者の案内で確かめる"], actHead:"現場で使うなら", note:"控除の対象は国税庁タックスアンサーで確かめる。少額短期保険の中身は扱う事業者、個別の税の判断は税理士。", pre:1, say:"少額短期保険の保険料は、年末調整の保険料の控除には入らない仕組みです。控除証明書が届いたご契約だけをお出しください。", more:"よくある場面は、ペットや家財、葬儀の費用に備える少額短期保険に入った方が、ほかの保険と同じように控除になると思っていることです。保障の中身と控除の扱いは別の話なので、選ぶときは保障の中身で考え、控除はあとから確かめるものとして添えます。", why:"保険料の控除は、所得税の決まりで対象の保険会社や共済が決められていて、少額短期保険を扱う事業者はその中に入っていないからです。" },
      { key:'faq_xhzi_gakushi_kojo', faq:1, grp:'hzi', q:"学資保険の保険料はどの控除に入る？", re:/(学資保険|こども保険|子ども保険|子供保険)[^。]{0,16}(控除|年末調整|区分)/, ng:/誰|だれ|どちら|どっち/, head:"学資保険の保険料は、一般の生命保険料控除の区分に入ります。", body:"学資保険（こども保険）は、子どもの成長や契約者の万一に備える生命保険の一つなので、保険料は一般の生命保険料控除の区分に入ります。控除を受けるのは、保険料を実際に払っている方です。受取人の要件など、ほかの生命保険と同じ決まりがかかります。区分は保険会社から届く控除証明書に書かれています。", acts:["控除証明書で、学資保険がどの区分に書かれているかを一緒に見る", "ほかの一般の区分の保険と合わせると上限で頭打ちになることがあると添える", "上限と控除の額の計算は、国税庁の案内か税理士で確かめていただく"], actHead:"現場で使うなら", note:"区分と上限は改正で変わる。国税庁タックスアンサーと保険会社の控除証明書で確かめる。個別の税の判断は税理士。", pre:1, say:"学資保険の保険料は、一般の生命保険料の控除に入る仕組みです。届いた控除証明書の区分のまま、年末調整でお出しください。", more:"よくある場面は、終身保険や定期保険と学資保険が両方とも一般の区分に入り、合わせると区分の上限を超えていて、学資保険を足しても控除の額が変わらないことです。控除のために契約を組み替える話にはせず、教育資金の準備として考えます。", why:"学資保険は、生存や死亡にもとづいてお金が支払われる生命保険の契約で、介護医療や個人年金の区分の要件に当たらないので、一般の区分に入るからです。" },
      { key:'faq_xhzi_henkaku_nenkin', faq:1, grp:'hzi', q:"変額個人年金保険は個人年金保険料控除になる？", re:/(変額|外貨建て?|ドル建て?)[^。]{0,4}(の)?(個人)?年金(保険)?[^。]{0,16}(控除|年末調整)/, head:"変額個人年金保険の保険料は、一般の生命保険料控除の区分になるのが基本です。", body:"個人年金保険料控除の区分に入るのは、税制適格の要件を満たし、その特約を付けた個人年金だけです。運用の成果で年金の額が変わる変額の個人年金は、この区分の対象から外れていて、一般の生命保険料の区分になります。外貨建ての個人年金は、商品によって特約を付けられるかが違うので、契約ごとに確かめます。", acts:["控除証明書で、変額の個人年金がどの区分に書かれているかを一緒に見る", "老後の準備として個人年金保険料控除を考えている方には、商品ごとに区分が違うと先に添える", "区分の確かめは、保険会社の契約概要と国税庁の案内でする"], actHead:"現場で使うなら", note:"区分の要件は国税庁タックスアンサーで、商品ごとの扱いは保険会社の契約概要と控除証明書で確かめる。個別の判断は税理士。", pre:1, say:"運用で年金の額が変わる個人年金は、個人年金の控除ではなく、一般の生命保険料の控除に入る仕組みです。届いた証明書の区分で確かめましょう。", more:"よくある勘違いは、名前に年金と付いていれば個人年金保険料控除になると考えることです。一般の区分は、終身保険や学資保険と同じ枠を分け合うので、ほかの契約と合わせると控除の額が増えないこともあります。控除の区分で商品を選ぶ話にはしません。", why:"個人年金保険料控除の対象は、税の決まりで要件が細かく定められた個人年金に限られていて、変額の個人年金はその対象から外されているからです。" },
      { key:'faq_xhzi_juminzei_kojo', faq:1, grp:'hzi', q:"生命保険料控除は住民税にもある？", re:/(生命保険料|地震保険料|保険料)控除[^。]{0,16}住民税|住民税[^。]{0,16}(生命保険料|地震保険料|保険料)控除|保険料控除で住民税/, head:"生命保険料控除と地震保険料控除は住民税にもあり、上限の額が所得税と違います。", body:"保険料の控除は、所得税だけでなく住民税の計算にもあります。住民税の控除は、区分ごとの上限や計算の仕方が所得税と違い、控除できる額は所得税より小さく決められています。年末調整や確定申告で出した内容が市区町村に伝わるので、住民税のために別に手続きをすることは、多くの場合、要りません。", acts:["控除の話をするときは、所得税と住民税の両方に効く仕組みだと添える", "いくら変わるかは所得で違うので、額は言い切らず税理士や市区町村で確かめていただく", "年末調整も確定申告もしない方の住民税の申告は、市区町村の案内で確かめていただく"], actHead:"現場で使うなら", note:"住民税の控除の上限と計算は、市区町村と国税庁・総務省の案内で確かめる。個別の税額は税理士。", pre:1, say:"保険料の控除は、所得税だけでなく住民税にもある仕組みです。年末調整でお出しいただければ、住民税の計算にも伝わります。", more:"よくある勘違いは、住民税の控除も所得税と同じ上限だと考えることです。住民税の控除は別の上限で計算されるので、控除の効き方を説明するときは、所得税の額だけで話さないようにします。年金だけの方など年末調整の無い方は、申告の仕方を市区町村で確かめます。", why:"所得税と住民税は、同じ所得をもとにしながら、それぞれの決まりで税を計算するからです。控除も税ごとに決められているので、上限や計算の仕方が分かれています。" },
      { key:'faq_xhzi_manryo_kojo', faq:1, grp:'hzi', q:"払込が終わった保険は控除になる？", re:/(払込|払い込み|払いこみ|保険料の払い)[^。]{0,6}(が)?(終わ|満了|済ん)[^。]{0,20}(控除|年末調整|証明書)|払い終え[^。]{0,16}(控除|年末調整|証明書)/, head:"保険料を払い終えた年の次の年からは、その契約の保険料の控除はありません。", body:"生命保険料控除は、その年に払い込んだ保険料をもとにする仕組みです。払込が終わった終身保険などは、保障が続いていても、その年に払う保険料が無いので、控除の対象になる額もありません。払込が終わる年は、その年に払った分だけが控除に入ります。控除証明書が届かなくなるのも、このためです。", acts:["払込の満了が近い契約は、満了の次の年から控除が無くなることを先に伝える", "控除が無くなると年末調整の額が変わることがあるので、家計の見通しに入れておくよう添える", "満了のあとの保障の続き方を、証券と契約概要で一緒に確かめる"], actHead:"現場で使うなら", note:"控除の対象の額は国税庁タックスアンサーと保険会社の控除証明書で確かめる。個別の税額は税理士。", pre:1, say:"保険料のお払いが終わったご契約は、保障は続いても、その後は保険料の控除がなくなる仕組みです。控除証明書が届かなくなるのはそのためです。", more:"よくある場面は、定年に合わせて払込が終わった方が、控除証明書が来ないので保険が切れたのではと心配されることです。保障が続いているかは証券や保険会社のお知らせで確かめられます。控除が無くなる年は、年末調整の額が前の年と変わることがあると添えておきます。", why:"保険料の控除は、その年に負担した保険料に応じて所得から差し引く仕組みなので、保険料を払わない年は差し引く元が無いからです。" },
      { key:'faq_xhzi_shomei_shinkoku', faq:1, grp:'hzi', q:"控除証明書の証明額と申告額の違いは？", re:/証明額|申告額|控除証明書[^。]{0,12}(二つ|2つ|ふたつ)[^。]{0,8}(金額|額)/, ng:/相続|贈与|法人/, head:"証明額はその時点までに払った額、申告額は年末まで払った場合の見込みの額です。", body:"秋に届く控除証明書には、証明書を作った時点までに払い込んだ保険料（証明額）と、そのまま年末まで払い込んだ場合の一年分の見込み（申告額）が並んで書かれていることが多いです。年末調整は年末の前に行うので、ふだんは申告額を使います。年末までに解約したり払込を止めたりする予定があるときは、実際に払う額に合わせます。", acts:["証明書の二つの欄を指さして、どちらがどの額かを一緒に見る", "年末までに解約や払込の変更を予定している方には、額が変わることを先に伝える", "どちらを書くか迷ったら、勤め先の担当と保険会社に確かめていただく"], actHead:"現場で使うなら", note:"書き方は国税庁の年末調整の案内と勤め先の担当で確かめる。証明書の額の中身は保険会社。個別の判断は税理士。", pre:1, say:"控除証明書の二つの額は、今までにお払いいただいた額と、年末まで続けた場合の見込みの額です。年末調整には、多くの場合、見込みの額をお使いいただきます。", more:"よくある勘違いは、証明額のほうが正確だからと証明額を書き、一年分より少ない額で控除を受けてしまうことです。反対に、年末までに解約した契約で申告額を書くと、実際に払った額より多くなります。年の途中で契約が変わった方には、どちらに合わせるかを先に話しておきます。", why:"年末調整は一年が終わる前に勤め先で済ませる手続きなので、年末までに払う見込みの額で計算できるよう、保険会社が二つの額を並べて書いているからです。" },
      { key:'faq_xhzi_junkakutei', faq:1, grp:'hzi', q:"準確定申告で亡くなった方の保険料はどこまで控除？", re:/準確定申告[^。]{0,20}(控除|保険料)|(亡くなった|死亡した)(方|人|父|母|夫|妻)?[^。]{0,16}(保険料控除|控除証明書|生命保険料控除)/, head:"準確定申告では、亡くなった日までに払った保険料が控除の対象です。", body:"年の途中で亡くなった方の所得税は、相続人が準確定申告で申告します。生命保険料控除や地震保険料控除は、亡くなった日までに、亡くなった方が払った保険料が対象になります。保険会社の控除証明書は、年末までの見込みで書かれていることがあるので、実際に払った額を保険会社で確かめてから使います。", acts:["ご家族から申告の相談があれば、準確定申告という手続きがあることと、税理士か税務署で確かめることを伝える", "亡くなった日までに払った保険料の額を、保険会社に問い合わせる方法を案内する", "申告書の作成は税理士の業務なので、こちらは書類の集め方の案内までにする"], actHead:"現場で使うなら", note:"準確定申告の期限・手続き・控除の範囲は、税務署と国税庁の案内で確かめる。申告書の作成は税理士の業務。", pre:1, say:"亡くなった方の所得税は、ご家族が準確定申告という手続きで申告します。保険料の控除は、亡くなった日までにお払いになった分が対象なので、必要な額は保険会社で確かめられます。", more:"よくある場面は、ご家族が年末に届いた控除証明書の申告額をそのまま使おうとすることです。亡くなったあとに引き落とされた保険料は、亡くなった方が払ったものとして数えないのが基本です。手続きが多い時期なので、こちらからは書類の取り方を一つずつご案内します。", why:"準確定申告は、亡くなった方のその年の初めから亡くなった日までの所得と税を締めくくる手続きなので、控除もその期間に本人が負担したものに限られるからです。" },
      { key:'faq_xhzi_kumi_shotoku', faq:1, grp:'hzi', q:"妻が保険料を払い夫にかけた保険を妻が受け取ったら何の税？", re:/契約者と受取人が同じ|保険料を払(い|って)、?(夫|妻|子|親|父|母|子ども)に(かけ|掛け)[^。]{0,16}受け取|(に|へ)(かけ|掛け)た保険[^。]{0,24}保険料を払っていた[^。]{0,8}受け取/, ng:/法人|会社(が|で|の)/, head:"保険料を払った人が受取人で、被保険者が別の人なら、死亡保険金は所得税の対象です。", body:"保険料を負担していた方が、自分を受取人にして別の人にかけていた保険の死亡保険金は、受取人の一時所得として所得税と住民税の対象になります。一時金で受け取るなら、受け取った額から払い込んだ保険料と特別控除を引いた残りの半分が、ほかの所得と合わさります。年金の形で受け取るなら、雑所得として扱います。相続税の非課税の枠は使えません。", acts:["証券で、保険料を払っている人・被保険者・受取人を紙に並べて書く", "一時所得になると、住民税や国民健康保険料の計算にも入ることがあると添える", "税額と確定申告が要るかは、税理士か税務署で確かめていただく"], actHead:"現場で使うなら", note:"所得の種類と計算は国税庁タックスアンサーで確かめる。個別の税額と申告は税理士の業務。契約の形を税のために組み替える話にしない。", pre:1, say:"保険料をお払いになった方ご自身が受け取る場合は、相続税ではなく所得税の対象になる仕組みです。どれくらいかかるかは、税理士か税務署でご確認ください。", more:"よくある場面は、妻が夫にかけた保険で、妻が保険料を払い、妻が受け取る形です。家族のための保険でも、相続税の非課税の枠は使えず、所得税と住民税の話になります。受け取った年の所得が増えるので、扶養や保険料の計算に響くことがあると先に伝えておきます。", why:"保険料を払った本人が保険金を受け取るのは、亡くなった方の財産が受け継がれたのではなく、自分が払ったお金から収入を得たのと同じ働きなので、受け取った人の所得として扱うからです。" },
      { key:'faq_xhzi_kumi_souzoku', faq:1, grp:'hzi', q:"自分にかけた保険を家族が受け取ると相続税？", re:/(自分|本人|自身)(に|自身に)(かけ|掛け)[^。]{0,24}(受け取|受取)|(保険料を)?(払っていた|払った|負担していた)(本人|人)(が|の)?[^。]{0,4}亡くな[^。]{0,16}(保険金|税)/, ng:/法人|会社(が|で|の)/, head:"保険料を払った人と被保険者が同じなら、家族が受け取る死亡保険金は相続税の対象です。", body:"保険料を負担していた方が自分にかけていて亡くなったときは、受け取った死亡保険金は、相続で受け継いだものと同じ扱い（みなし相続財産）として相続税の対象になります。受取人が相続人なら、死亡保険金の非課税の枠を使えます。受取人が相続人でない方だと、枠は使えず、相続税の額が加算されることがあります。", acts:["証券で、保険料を払っている人と被保険者が同じかを先に確かめる", "受取人が相続人に当たるかを家系図で一緒に見る", "相続税がかかるか・いくらかは、税理士に確かめていただく"], actHead:"現場で使うなら", note:"非課税の枠の額と計算・相続税がかかるかは、国税庁タックスアンサーと税理士で確かめる。保険で相続税を減らす話にしない。", pre:1, say:"保険料を払っていた方が、ご自身にかけていた保険の死亡保険金は、相続税の対象になる仕組みです。相続人の方が受け取るなら、非課税の枠もあります。", more:"よくある勘違いは、受取人のお金なので税金はかからないと考えることです。遺産分割の対象にならないことと、相続税の対象になることは別の話です。財産の合計が相続税の基礎控除の内なら、相続税そのものがかからないこともあるので、全体は税理士と確かめます。", why:"保険料を払っていた方が亡くなって家族にお金が渡るのは、亡くなった方の財産が受け継がれるのと同じ働きなので、相続税の対象として扱うと決められているからです。" },
      { key:'faq_xhzi_futansha', faq:1, grp:'hzi', q:"名義は夫でも保険料を妻が払っていたら税金はどう見る？", re:/(名義|契約者)[^。]{0,16}(でも|だけど|だが|なのに|と)[^。]{0,16}(実際に|本当に|実は)?[^。]{0,6}保険料を[^。]{0,8}(払|負担)[^。]{0,24}(税|課税)|保険料を(本当に|実際に)払った人|(名義|契約者)と保険料の?負担者/, ng:/法人|会社(が|で|の)|控除/, head:"税の扱いは、契約の名義ではなく、保険料を実際に負担した人で判断します。", body:"保険金や満期金、解約返戻金にかかる税の種類は、契約書の名義ではなく、保険料を実際に誰が負担していたかで決まります。名義は夫でも、保険料を妻の収入から払っていれば、妻が保険料を払ったものとして、相続税・所得税・贈与税のどれになるかを見ます。誰が払ったかは、引き落としの口座やお金の出どころで確かめられます。", acts:["保険料がどの口座から引き落とされているかを、お客様と一緒に確かめる", "名義と実際の負担者が違うときは、受け取るときの税の扱いが変わることを先に伝える", "名義を負担者に合わせるかの判断は、税理士に確かめてから手続きする"], actHead:"現場で使うなら", note:"負担者の判断と税の扱いは国税庁と税理士で確かめる。名義の変更の手続きは保険会社で。税を下げるために名義を動かす話にしない。", pre:1, say:"保険のお金にかかる税金は、名義よりも、実際に保険料をお払いになった方で決まる仕組みです。どの口座から引き落とされているかを一緒に確かめておきましょう。", more:"よくある場面は、子どもの名義の保険を親が払い続けていて、子どもが満期金を受け取る形です。名義が子どもでも、親が払っていれば、親から子へのお金の移り（贈与）と見られることがあります。夫婦の間でも同じ考え方なので、家計の口座が一つの家ほど確かめておきます。", why:"税は、お金が実際に誰から誰へ移ったかで考えるからです。名義だけを見ると、払った人と受け取った人の関係が分からないので、保険料を負担した人を基準にしています。" },
      { key:'faq_xhzi_futan_fukusu', faq:1, grp:'hzi', q:"保険料を途中から別の人が払った保険の税金は？", re:/保険料[^。]{0,8}(途中から|途中で)[^。]{0,12}(別の人|子|親|夫|妻|変わ)|保険料[^。]{0,6}(半分ずつ|分けて|折半|二人で|2人で)[^。]{0,16}(払|負担)|保険料の負担(者)?[^。]{0,6}(が)?(二人|2人|複数|変わ)/, ng:/法人|会社(が|で|の)|控除/, head:"保険料を払った人が複数いれば、払った割合ごとに税の種類を分けて考えます。", body:"保険料を途中から別の人が払ったり、二人で分けて払ったりした契約は、受け取ったお金を、それぞれが負担した保険料の割合で分けて考えます。例えば、受取人自身が払った分は所得税、亡くなった方が払った分は相続税、ほかの人が払った分は贈与税というように、一つの保険金に複数の税が関わることがあります。", acts:["保険料を誰がいつからいつまで払ったかを、引き落としの記録で一緒に整理する", "負担が変わった時期を紙に書き、受け取るときに税理士へ渡せるようにしておく", "割合の計算と申告は、税理士に確かめていただく"], actHead:"現場で使うなら", note:"負担の割合の数え方と税の計算は、国税庁と税理士で確かめる。個別の税額と申告は税理士の業務。", pre:1, say:"保険料をお払いになった方が途中で変わった場合は、払った割合ごとに税金の種類が分かれる仕組みです。いつから誰が払っていたかを、記録で整理しておきましょう。", more:"よくある場面は、子どもが社会人になって、親が払っていた保険料を子どもが払い始めた契約です。満期金や保険金を受け取るときに、親が払った分と子どもが払った分で扱いが分かれます。何年も前のことは記録が残りにくいので、負担が変わったときに書き残しておくよう添えます。", why:"税は、お金を実際に負担した人から受け取った人へ何が移ったかで考えるので、負担した人が複数いれば、それぞれの分ごとに考えるのが筋だからです。" },
      { key:'faq_xhzi_shunyu_hosho', faq:1, grp:'hzi', q:"収入保障保険を年金で受け取ると税金は？", re:/収入保障(保険)?[^。]{0,24}(税|課税)/, ng:/保険料控除|控除証明書|法人|会社(が|で|の)/, head:"年金で受け取る権利は相続税の対象で、毎年の年金にも所得税の計算が加わります。", body:"保険料を払っていた方が自分にかけていた収入保障保険なら、年金を受け取る権利は相続税の対象（みなし相続財産）として評価されます。年金の形で受け取ると、毎年の年金は雑所得の計算に入り、そのうち相続税の対象になった部分には所得税がかからない形で、課税される部分とされない部分に分けます。一括で受け取ると、相続税の対象として扱いが一度で終わります。", acts:["受け取り方を選ぶ前に、年金と一括のどちらも税の扱いが違うことを先に伝える", "受け取り方の選び方は、暮らしの費用の出方と合わせて一緒に考える", "税額の見込みと申告は、税理士に確かめていただく"], actHead:"現場で使うなら", note:"受給権の評価・年金の課税される部分の計算は国税庁と税理士で確かめる。受け取り方の手続きは保険会社。", pre:1, say:"収入保障保険は、年金で受け取るか一括で受け取るかで、税金の扱いが変わる仕組みです。どちらにするかは、暮らしのお金の出方と税理士のお話を合わせて決めましょう。", more:"よくある場面は、ご家族が一括のほうが分かりやすいと思って選び、毎月の生活費の見通しが立たなくなることです。反対に、年金で受け取ると毎年の申告や住民税の話が続きます。税だけで選ばず、暮らしの費用と手続きの手間を並べて考えます。", why:"年金で受け取る形は、受け取る権利そのものが相続で引き継がれたうえに、毎年の年金の中に運用で増えた分が含まれるので、相続税と所得税の両方の決まりが関わるからです。" },
      { key:'faq_xhzi_manki_shinkoku', faq:1, grp:'hzi', q:"満期金を受け取ったら確定申告は要る？", re:/満期(保険金|金)?[^。]{0,20}(確定申告|申告|年末調整)/, ng:/国保|国民健康保険|扶養|住民税が上が|法人|会社(が|で|の)|経理/, head:"一時所得になる満期金は、年末調整では済まず、確定申告が要ることがあります。", body:"保険料を払った人が受け取る満期金は一時所得で、勤め先の年末調整には入りません。一時所得の額によっては確定申告が要ります。会社員の方で給与のほかの所得が少ない場合は所得税の確定申告が要らないこともありますが、その場合でも住民税の申告が要ることがあります。要るかどうかは、ほかの所得と合わせて決まります。", acts:["満期の案内のときに、その年の申告が要るかを税務署か税理士で確かめるよう添える", "払い込んだ保険料の合計が分かる書類を、保険会社からもらっておくよう伝える", "住民税の申告が要るかは、お住まいの市区町村で確かめていただく"], actHead:"現場で使うなら", note:"確定申告が要る基準と住民税の申告は、国税庁タックスアンサー・税務署・市区町村で確かめる。個別の判断は税理士。", pre:1, say:"満期金は年末調整には入らないので、確定申告が要るかどうかを確かめておく必要があります。ほかの所得と合わせて決まるので、税務署か税理士でご確認ください。", more:"よくある勘違いは、保険会社から振り込まれたお金なので税金の手続きは済んでいると考えることです。一時所得になる満期金は、源泉徴収で終わる形ではありません。払い込んだ保険料より少なければ一時所得は生じないので、まず受け取った額と払った額を並べます。", why:"一時所得は、給与とは別の所得として本人がまとめて申告する仕組みだからです。勤め先は給与の分しか年末調整で計算できないので、満期金は本人の申告で扱います。" },
      { key:'faq_xhzi_manki_kokuho', faq:1, grp:'hzi', q:"満期金を受け取ると国民健康保険料は上がる？", re:/(満期|解約返戻金|返戻金|一時所得|保険金)[^。]{0,24}(国民健康保険|国保|介護保険料|後期高齢|住民税に響|住民税が上が)/, ng:/法人|会社(が|で|の)/, head:"一時所得は所得の合計に入るので、国保の保険料や住民税の計算に響くことがあります。", body:"満期金や解約返戻金のうち一時所得として数える部分は、所得の合計に入ります。国民健康保険料や介護保険料、住民税は、前の年の所得をもとに市区町村が計算するので、受け取った次の年の額が変わることがあります。後期高齢者医療の窓口の負担の区分に関わることもあります。どれくらい変わるかは、お住まいの市区町村の決まりで違います。", acts:["満期や解約の前に、次の年の国保や介護保険料に響くことがあると先に伝える", "受け取る時期を税のためだけに動かす話にはせず、暮らしの予定で決める", "変わる見込みは、お住まいの市区町村の窓口で確かめていただく"], actHead:"現場で使うなら", note:"保険料と住民税の計算は市区町村の窓口で、一時所得の数え方は国税庁と税理士で確かめる。", pre:1, say:"満期金を受け取った次の年は、国民健康保険料や住民税の計算に入ることがある仕組みです。気になる場合は、お住まいの市区町村の窓口で確かめられます。", more:"よくある場面は、退職後に国保に入っている方が満期金を受け取り、次の年の通知を見て驚くことです。一時所得は計算のうえで半分にした額が所得に入るので、受け取った額そのものではありません。前もって伝えておくと、驚かずに済みます。", why:"国民健康保険料や住民税は、所得の合計をもとに計算する仕組みなので、給与や年金のほかに一時所得があった年は、その分も計算に入るからです。" },
      { key:'faq_xhzi_manki_fuyou', faq:1, grp:'hzi', q:"満期金を受け取ったら扶養から外れる？", re:/(満期|解約返戻金|返戻金|一時所得|保険金)[^。]{0,24}(扶養|配偶者控除|配偶者特別控除)/, ng:/法人|会社(が|で|の)/, head:"税の扶養は一時所得も含めた所得で見るので、その年は外れることがあります。", body:"配偶者控除や扶養控除の対象かは、その年の合計所得金額で決まり、一時所得も計算のうえで含まれます。満期金の一時所得が大きいと、その年は控除の対象から外れることがあります。健康保険の扶養は税とは別の決まりで、見込みの収入で判断し、一時的な収入をどう数えるかは加入している健康保険の窓口で確かめます。", acts:["満期金を受け取るのが扶養に入っている方なら、税と健康保険の扶養の両方に関わると先に伝える", "税の扶養への影響は、税理士か税務署で確かめていただく", "健康保険の扶養は、勤め先の健康保険の窓口で確かめていただく"], actHead:"現場で使うなら", note:"税の扶養は国税庁と税理士、健康保険の扶養は加入している健康保険の窓口で確かめる。扶養の基準の額はここに書かない。", pre:1, say:"満期金の一時所得は、その年の税の扶養の判断に入る仕組みです。健康保険の扶養は別の決まりなので、両方を確かめておきましょう。", more:"よくある場面は、専業主婦の方が自分の名義の満期金を受け取り、夫の年末調整で配偶者控除をそのまま使ってしまうことです。あとで直す手間が出るので、満期の案内の段階で、受け取る方とご家族の両方に声をかけます。", why:"税の扶養は一年の所得の合計で判断する決まりなので、一時所得も入ります。一方、健康保険の扶養は暮らしを支えられているかを見る別の制度なので、基準と数え方が分かれているからです。" },
      { key:'faq_xhzi_haraizumi', faq:1, grp:'hzi', q:"払済保険にしたら税金はかかる？", re:/(払済|払い済|延長保険|延長定期)[^。]{0,16}(税|課税|一時所得|申告)/, ng:/法人|会社(が|で|の)|経理|仕訳|洗い替え|損金|益金/, head:"個人の契約を払済保険や延長保険に変えても、その時点ではお金を受け取らないので課税されません。", body:"払済保険は、その時点の解約返戻金をもとに、保険料の払込をやめて保障の額を小さくした保険に変える形です。延長保険は、保障の額を変えずに保険期間を短くする形です。どちらも個人の契約では、変えた時点でお金を受け取らないので、その時点で所得税はかかりません。あとで解約や満期、保険金の支払いがあったときに、その時の扱いで考えます。", acts:["払済や延長に変えると、保障の額や期間がどう変わるかを証券と保険会社の案内で示す", "特約が外れるなど、変えたあとの保障の違いを先に確かめる", "法人の契約の払済は経理の扱いが別なので、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"変えたあとの保障の中身は保険会社の約款と案内で、税の扱いは国税庁と税理士で確かめる。法人の契約は別の扱い。", pre:1, say:"払済保険に変えても、その時点でお金を受け取るわけではないので、税金はかからない仕組みです。保障がどう変わるかを先に確かめておきましょう。", more:"よくある勘違いは、払済にすると解約したのと同じだと思うことです。保障は小さくなりますが、契約は続いています。保険料の負担が重くなったときの選び方の一つとして、解約と並べて、保障の残り方を見比べます。", why:"所得税は、実際にお金や利益を受け取ったときに考える仕組みです。払済や延長は契約の形を変えるだけで、お金が契約者の手元に移らないので、その時点では所得が生じないからです。" },
      { key:'faq_xhzi_kashitsuke', faq:1, grp:'hzi', q:"契約者貸付を受けたら税金はかかる？", re:/(契約者貸付|契約者貸し付け|保険からお金を借り|保険でお金を借り)[^。]{0,20}(税|課税|所得|差し引|引かれ)|保険金から契約者貸付/, ng:/法人|会社(が|で|の)/, head:"契約者貸付は借りたお金なので、受け取っても所得にはならず、税金はかかりません。", body:"契約者貸付は、解約返戻金の範囲内で保険会社からお金を借りる仕組みで、利息がかかります。借りたお金なので、受け取っても所得ではありません。返さないまま満期や解約、保険金の支払いになると、支払われる額から貸付の残りと利息が差し引かれます。差し引かれたときの税の計算の扱いは、受け取る形ごとに税理士に確かめます。", acts:["貸付を受ける前に、利息がかかることと、返さないと受け取る額が減ることを伝える", "貸付の残りが解約返戻金を超えると契約が続かなくなることがあるので、保険会社の案内で確かめる", "保険金から差し引かれたときの税の扱いは、税理士に確かめていただく"], actHead:"現場で使うなら", note:"貸付の条件と利息は保険会社の約款と案内で、差し引かれたときの税の扱いは国税庁と税理士で確かめる。", pre:1, say:"契約者貸付は保険会社からお金を借りる形なので、受け取っても税金はかからない仕組みです。利息がかかるので、返し方も一緒に考えておきましょう。", more:"よくある場面は、急な出費で貸付を受け、返すのを忘れたまま長い年月がたち、満期のときに受け取る額が思ったより少なくなることです。利息も積み重なるので、借りた時に返す予定を書き残しておくよう添えます。", why:"所得は、返さなくてよいお金を得たときに生じるからです。契約者貸付は返す約束のある借り入れなので、受け取った時点では所得に当たりません。" },
      { key:'faq_xhzi_gakushi_manki', faq:1, grp:'hzi', q:"学資保険の満期金の税金は？", re:/(学資保険|こども保険|子ども保険|子供保険)[^。]{0,20}(満期|祝い金|受け取|学資金)[^。]{0,16}(税|課税|一時所得|贈与)/, ng:/控除|年末調整|法人|会社(が|で|の)/, head:"保険料を払った親が受け取るなら一時所得、子どもが受け取る形だと贈与税になることがあります。", body:"学資保険の満期金や祝い金の税は、保険料を払った人と受け取る人で決まります。契約者の親が保険料を払い、親が受け取るなら一時所得として所得税と住民税の対象です。受け取る人が子どもになっていると、親から子どもへお金が移ったものとして贈与税の対象になることがあります。受取人が誰になっているかは、証券で確かめます。", acts:["証券で、保険料を払う人と満期金・祝い金の受取人を一緒に確かめる", "受取人を子どもにしている契約は、受け取るときの税の扱いが変わると先に伝える", "受け取った年の申告が要るかは、税理士か税務署で確かめていただく"], actHead:"現場で使うなら", note:"所得の種類と贈与税の扱いは国税庁と税理士で確かめる。受取人の変更の手続きは保険会社で。", pre:1, say:"学資保険の満期金は、保険料をお払いになった方が受け取るなら一時所得の扱いになる仕組みです。受取人が誰になっているか、証券で一緒に確かめておきましょう。", more:"よくある勘違いは、子どものための保険なので子どもが受け取るのが自然だと考えることです。受取人を子どもにしていると、贈与税の話になることがあります。教育費を払うのは親なので、受取人の決め方を契約の段階で話しておきます。", why:"税は、保険料を負担した人から受け取った人へお金が移ったかで考えるからです。親が払って親が受け取れば自分の所得、子が受け取れば親から子へ渡ったと見られます。" },
      { key:'faq_xhzi_seizon', faq:1, grp:'hzi', q:"生存給付金やお祝い金は一時所得になる？", re:/(生存給付金|お祝い金|祝い金|生存祝金|健康祝い金|健康祝金)[^。]{0,16}(税|課税|一時所得|申告)/, ng:/学資|こども保険|子ども保険|子供保険|法人|会社(が|で|の)/, head:"保険料を払った人が受け取る生存給付金や祝い金は、一時所得として扱います。", body:"契約の途中で受け取る生存給付金や祝い金は、保険料を払った人が受け取れば一時所得として所得税と住民税の対象です。受け取る人が保険料を払った人と違うと、贈与税の対象になることがあります。一時所得はその年のほかの一時所得と合わせて特別控除を使うので、受け取った額だけでは税がかかるかが決まりません。", acts:["契約概要で、途中で受け取るお金がいつ・誰に支払われるかを一緒に確かめる", "その年にほかの満期金や一時所得があるかを伺い、合わせて考える必要を伝える", "申告が要るかは、税理士か税務署で確かめていただく"], actHead:"現場で使うなら", note:"一時所得の計算と申告は国税庁と税理士で確かめる。支払いの時期と受取人は保険会社の契約概要で。", pre:1, say:"途中で受け取るお祝い金も、保険料をお払いになった方が受け取るなら一時所得の扱いです。その年のほかの一時所得と合わせて考えるので、気になる場合は税務署か税理士でご確認ください。", more:"よくある場面は、医療保険の健康祝い金を受け取った方が、少額なので気にしていないことです。同じ年に満期金や懸賞の賞金など、ほかの一時所得があると合わさって計算されます。受け取った年のお金の動きを一覧にしておくと迷いません。", why:"途中で受け取るお金も、満期金と同じく保険の契約から得た一時的な収入なので、保険料を払った人が受け取れば一時所得として扱う決まりだからです。" },
      { key:'faq_xhzi_nenkin_zouyo', faq:1, grp:'hzi', q:"個人年金の年金受取人が契約者と違うとどうなる？", re:/年金(の)?(受取人|受け取る人)[^。]{0,20}(保険料を払った人|保険料を払う人|契約者|負担者)[^。]{0,8}(と)?(違|別)|個人年金[^。]{0,24}贈与税|(保険料を払(い|う|った)|契約者が)[^。]{0,8}(妻|夫|子)が受け取る個人年金/, ng:/亡くな|死亡|相続|法人|会社(が|で|の)|保険料控除/, head:"年金の支払いが始まるときに、年金を受け取る権利が贈与されたものとして贈与税の対象です。", body:"保険料を払った人と年金の受取人が違う個人年金は、年金の支払いが始まった時点で、受取人が年金を受け取る権利（年金受給権）を保険料を払った人からもらったものとして、贈与税の対象になります。その後に毎年受け取る年金は、受取人の雑所得として、課税される部分とされない部分に分けて計算します。", acts:["証券で、保険料を払う人と年金の受取人を一緒に確かめる", "受取人が違う契約は、年金が始まるときに贈与税の話が出ると先に伝える", "受給権の評価と税額は、税理士に確かめていただく"], actHead:"現場で使うなら", note:"受給権の評価と贈与税・毎年の年金の計算は、国税庁タックスアンサーと税理士で確かめる。受取人の変更は保険会社。", pre:1, say:"保険料をお払いになる方と年金の受取人が違う個人年金は、年金が始まるときに贈与税の対象になる仕組みです。受取人の欄を一緒に確かめておきましょう。", more:"よくある場面は、夫が保険料を払い、妻の老後のためにと妻を年金の受取人にしている契約です。年金が始まる年に贈与税の申告が要ることがあり、知らずにいると驚かれます。受取人をどうするかは、老後の暮らし方と税理士のお話を合わせて考えます。", why:"年金の支払いが始まった時点で、保険料を払った人のお金から生まれた年金を受け取る権利が、別の人のものに確定するからです。その時点の移りを贈与と見る決まりになっています。" },
      { key:'faq_xhzi_nenkin_kouteki', faq:1, grp:'hzi', q:"個人年金に公的年金等控除は使える？", re:/(個人年金|保険の年金)[^。]{0,16}(公的年金等控除|公的年金と同じ控除|雑所得はどう計算|雑所得の計算)|公的年金等控除[^。]{0,16}(個人年金|保険)/, ng:/ideco|イデコ|確定拠出|企業年金/, head:"使えません。個人年金の雑所得は、受け取った年金から対応する保険料を差し引いて計算します。", body:"公的年金等控除は、国の年金や企業年金、iDeCo の年金などに使う控除で、保険会社の個人年金保険には使えません。個人年金の年金は、受け取った年金の額から、その年金に対応する払い込んだ保険料を差し引いた残りが雑所得になります。公的年金と同じ雑所得でも、計算の仕方が違います。", acts:["公的年金と個人年金の受け取りがある方には、計算の仕方が別だと先に伝える", "保険会社から届く年金の支払いの書類を、申告のときまで取っておくよう添える", "申告と税額は、税理士か税務署で確かめていただく"], actHead:"現場で使うなら", note:"公的年金等控除の対象と個人年金の雑所得の計算は、国税庁タックスアンサーと税理士で確かめる。", pre:1, say:"個人年金保険の年金には、国の年金と同じ控除は使えない仕組みです。払い込んだ保険料を差し引く別の計算になるので、申告は税理士か税務署でご確認ください。", more:"よくある勘違いは、年金という名前が付いていれば公的年金と同じ扱いだと考えることです。個人年金は保険料を差し引く計算なので、源泉徴収の額と実際の税額が合わず、確定申告で精算することがあります。届いた書類をそろえておくと手続きが楽です。", why:"公的年金等控除は、公的年金や企業年金など、決められた年金の収入にだけ認められた控除で、保険会社と結ぶ個人年金はその対象に入っていないからです。" },
      { key:'faq_xhzi_shotoku_hosho', faq:1, grp:'hzi', q:"所得補償保険の保険金に税金はかかる？", re:/所得補償[^。]{0,16}(税|課税|非課税|申告|所得になる)/, ng:/うちの会社|社内|自分の会社|当社|弊社|法人|会社(が|で|の)|控除/, head:"病気やけがで働けない間に本人が受け取る所得補償保険の保険金は、非課税です。", body:"所得補償保険や就業不能保険は、病気やけがで働けない間の収入の減りに備える保険です。被保険者ご本人が受け取る保険金は、身体の傷害や病気にもとづいて支払われるものとして、所得税がかかりません。会社が契約して会社が受け取る形や、事業の収入として扱う場面は別の考え方になるので、契約の形で確かめます。", acts:["証券で、保険金の受取人が被保険者ご本人になっているかを確かめる", "会社が契約している団体の所得補償は、受け取り方を勤め先の担当に確かめていただく", "個人事業の方の扱いに迷うときは、税理士に確かめていただく"], actHead:"現場で使うなら", note:"非課税の範囲は国税庁タックスアンサーと税理士で確かめる。保障の中身と受取人は保険会社の約款で。", pre:1, say:"働けない間にご本人が受け取る所得補償の保険金は、税金がかからない仕組みです。受取人がご本人になっているかだけ、証券で確かめておきましょう。", more:"よくある勘違いは、給与の代わりに受け取るお金なので、給与と同じく税金がかかると考えることです。ご本人が受け取る保険金は非課税です。ただし会社が契約者と受取人の団体の保険では、会社を通して支払われる形によって扱いが変わることがあります。", why:"病気やけがにもとづいて本人が受け取る保険金は、失った体の働きを補うものと考えられ、所得税を課さない決まりになっているからです。" },
      { key:'faq_xhzi_senshin', faq:1, grp:'hzi', q:"先進医療の技術料は医療費控除になる？", re:/先進医療[^。]{0,20}(医療費控除|控除|確定申告|税)/, ng:/法人|会社(が|で|の)|保険料控除/, head:"治療のために支払った先進医療の技術料は、医療費控除の対象になり、給付金はそこから差し引きます。", body:"先進医療の技術料は健康保険が使えず自分で負担する費用ですが、病気やけがの治療のために支払ったものは、医療費控除の対象になります。先進医療の特約などから給付金を受け取ったときは、その技術料から差し引いて計算します。給付金そのものは、被保険者ご本人などが受け取れば非課税です。交通費などが対象になるかは、内容で決まります。", acts:["先進医療を受けたお客様には、領収書と給付金の通知を取っておくよう伝える", "通院の交通費など、対象になるかが分かれるものは税務署か税理士で確かめていただく", "先進医療の特約の請求の手続きを、保険会社の案内で一緒に確かめる"], actHead:"現場で使うなら", note:"医療費控除の対象と差し引きは国税庁タックスアンサーと税理士で、先進医療の給付は保険会社の約款で確かめる。", pre:1, say:"治療のために支払った先進医療の技術料は、医療費控除の対象になる仕組みです。給付金を受け取った場合は、その分を差し引いて計算します。", more:"よくある場面は、先進医療の特約から技術料と同じくらいの給付金を受け取り、医療費控除に入れても差し引くと残りが少なくなることです。それでもほかの入院費や通院の費用と合わせて控除になることがあるので、領収書はまとめて取っておきます。", why:"医療費控除は、治療のために自分で負担した費用を軽くする仕組みで、健康保険が使えるかどうかではなく、治療の対価かどうかで対象が決まるからです。" },
      { key:'faq_xhzi_mikakutei', faq:1, grp:'hzi', q:"確定申告のときに給付金がまだ決まっていなかったら？", re:/(給付金|保険金)[^。]{0,16}(まだ|決まって(いない|ない)|未確定|確定していない|決まる前)[^。]{0,24}(医療費控除|確定申告|申告)?|医療費控除[^。]{0,24}(まだ決まって|未確定|見込み)|(申告(した)?後|申告のあと)[^。]{0,12}(給付金|保険金)/, ng:/法人|会社(が|で|の)/, head:"申告のときに額が決まっていなければ、受け取る見込みの額を差し引いて申告します。", body:"医療費控除の申告のときに、保険の給付金の額がまだ決まっていない場合は、受け取る見込みの額を医療費から差し引いて申告します。あとで実際に受け取った額が見込みと違ったときは、申告をさかのぼって直す手続きをします。見込みの額は、保険会社に請求の状況を問い合わせて確かめます。", acts:["請求中の給付金がある方には、申告の前に保険会社へ支払いの見込みを問い合わせるよう伝える", "実際の額が決まったら、申告を直す手続きが要るかを税務署か税理士で確かめていただく", "請求の書類がそろっているかを一緒に確かめる"], actHead:"現場で使うなら", note:"見込み額での申告と直し方は、国税庁タックスアンサーと税務署・税理士で確かめる。支払いの見込みは保険会社に問い合わせる。", pre:1, say:"確定申告のときに給付金の額がまだ決まっていなければ、見込みの額を差し引いて申告する仕組みです。保険会社に支払いの見込みを確かめておきましょう。", more:"よくある場面は、年をまたいで入院した方が、給付金の請求を後回しにしていて、医療費控除の申告と順番が前後することです。見込みの額で出しておき、決まったら直せます。請求が遅れると、医療費控除の計算も落ち着かないので、早めに請求を済ませます。", why:"医療費控除は、補われる分を差し引いた本当の負担で計算するので、まだ受け取っていない給付金でも、受け取ることが分かっているなら差し引いて数える決まりだからです。" },
      { key:'faq_xhzi_iryohi_ooi', faq:1, grp:'hzi', q:"入院給付金が医療費より多かったら、ほかの医療費から引く？", re:/(給付金|保険金)[^。]{0,10}(が)?[^。]{0,8}(医療費|入院費|治療費)(より|を)[^。]{0,6}(多|上回|超え)|(給付金|保険金)の余った分/, ng:/法人|会社(が|で|の)/, head:"差し引くのは、その給付金の目的になった医療費までで、余った分をほかの医療費から引きません。", body:"医療費控除では、保険から受け取った給付金などを、支払った医療費から差し引いて計算します。差し引くのは、その給付金が支払われる理由になった入院や手術の医療費までです。給付金のほうが多くても、余った分を別の病気の通院や、ほかのご家族の医療費から差し引くことはしません。どの医療費にどの給付金が当たるかで、計算が変わります。", acts:["医療費の領収書と給付金の支払いの通知を、病気やけがごとに分けて並べる", "どの給付金がどの医療費に当たるかを一緒に整理し、税務署か税理士で確かめていただく", "医療費控除そのものの要件は、国税庁の案内で確かめていただく"], actHead:"現場で使うなら", note:"差し引く範囲と計算は国税庁タックスアンサー（医療費控除）と税理士で確かめる。給付の理由は保険会社の支払いの通知で。", pre:1, say:"医療費控除では、入院の給付金はその入院の医療費からだけ差し引く仕組みです。余った分をほかの医療費から引くことはないので、病気ごとに分けて整理しておきましょう。", more:"よくある勘違いは、受け取った給付金の合計を、一年の医療費の合計からまとめて差し引くことです。そうすると控除の額が小さくなりすぎることがあります。給付の通知には、何の入院や手術に対する支払いかが書かれているので、それを見ながら当てはめます。", why:"医療費控除は、実際に自分で負担した医療費に応じて税を軽くする仕組みなので、保険で補われた分はその医療費からだけ外し、ほかの医療費の負担まで消さないようにしているからです。" },
      { key:'faq_xhzi_iryohi_sashihiki', faq:1, grp:'hzi', q:"医療費控除で入院給付金は差し引く？", re:/医療費控除[^。]{0,24}(差し引|引く|引か|補てん|補填|どう扱|扱い)|(給付金|保険金|高額療養費)[^。]{0,16}医療費控除[^。]{0,8}(差し引|引く|引か|から引|扱)/, ng:/法人|会社(が|で|の)/, head:"差し引きます。保険の給付金や高額療養費などで補われた分は、医療費から差し引いて計算します。", body:"医療費控除は、その年に支払った医療費から、保険の入院給付金や手術給付金、健康保険の高額療養費など、医療費を補うお金を差し引いた額をもとに計算します。給付金そのものには税金がかかりませんが、控除の計算では差し引く決まりです。死亡保険金や、働けない間の収入を補う保険金のように、医療費を補う目的でないものは差し引きません。", acts:["医療費控除の相談があれば、受け取った給付金の通知もそろえるよう伝える", "どのお金が医療費を補うものに当たるかは、国税庁の案内か税理士で確かめていただく", "給付金の請求がまだなら、請求できるものがないかを一緒に確かめる"], actHead:"現場で使うなら", note:"差し引くお金の範囲は国税庁タックスアンサー（医療費控除）と税理士で確かめる。高額療養費は加入している健康保険の窓口で。", pre:1, say:"医療費控除の計算では、保険の給付金など医療費を補うお金を差し引く仕組みです。給付金そのものに税金はかかりませんので、通知を一緒にそろえておきましょう。", more:"よくある勘違いは、給付金は非課税だから医療費控除の計算でも関係ないと考えることです。非課税であることと、医療費から差し引くことは別の話です。反対に、差し引かなくてよいお金まで引いて、控除を小さくしてしまうこともあるので、目的で分けます。", why:"医療費控除は、自分で負担した医療費を軽くする仕組みなので、保険や健康保険で補われた分まで負担として数えないよう、医療費から差し引くからです。" },
      { key:'faq_xhzi_shitei_dairi', faq:1, grp:'hzi', q:"指定代理請求で家族が受け取った給付金に税金は？", re:/指定代理[^。]{0,24}(税|課税|非課税|贈与)|本人の代わりに[^。]{0,12}(請求|受け取)[^。]{0,16}(税|課税|贈与)/, ng:/法人|会社(が|で|の)/, head:"指定代理請求で家族が受け取っても、本人が受け取ったものと同じく非課税です。", body:"指定代理請求は、被保険者ご本人が病名を知らされていない場合や、意思を伝えられない状態のときに、あらかじめ決めた家族などが本人の代わりに給付金や保険金を請求できる仕組みです。受け取ったお金は本人が受け取ったものとして扱うので、入院給付金や高度障害保険金などは非課税のままで、家族への贈与にもなりません。", acts:["指定代理請求人が誰になっているかを証券で一緒に確かめる", "請求人に指定された方へ、仕組みと請求の手順を伝えておくよう添える", "受け取ったお金の管理の仕方は、ご家族で話し合っていただく"], actHead:"現場で使うなら", note:"指定代理請求の要件と手続きは保険会社の約款で、税の扱いは国税庁と税理士で確かめる。", pre:1, say:"指定代理請求でご家族が受け取ったお金も、ご本人が受け取ったものと同じ扱いで、税金はかからない仕組みです。請求人に決めた方には、仕組みを伝えておきましょう。", more:"よくある場面は、請求人に指定された方がその仕組みを知らず、いざというときに請求が遅れることです。指定したことを本人と請求人の両方が覚えていられるよう、契約の時や見直しの時に一言添えておきます。", why:"指定代理請求は、本人に代わって手続きをするだけの仕組みで、お金を受け取る権利そのものは本人のものだからです。本人が受け取ったのと同じに扱われます。" },
      { key:'faq_xhzi_shigo_kyufu', faq:1, grp:'hzi', q:"亡くなったあとに支払われた入院給付金は相続財産？", re:/(亡くな|死亡)[^。]{0,8}(後|あと|てから|る前)[^。]{0,16}(入院給付金|手術給付金|給付金)|(入院給付金|手術給付金|給付金)[^。]{0,16}(亡くな|死亡)[^。]{0,6}(後|あと|てから)/, ng:/法人|会社(が|で|の)|死亡保険金|誰が請求|請求する|請求でき|請求の(手続|仕方|やり方)/, head:"本人が受け取るはずだった入院給付金は本来の相続財産で、死亡保険金の非課税の枠は使えません。", body:"亡くなる前の入院や手術の給付金が、亡くなったあとに支払われた場合、そのお金は本人が受け取るはずだったものなので、亡くなった方の財産（本来の相続財産）になります。相続税の計算に入り、遺産分割の対象にもなります。死亡保険金と違って、相続人が受け取る死亡保険金の非課税の枠は使えません。", acts:["ご家族から請求の相談があれば、受け取ったお金は相続財産として扱うことを先に伝える", "請求の手続きと必要な書類は、保険会社の案内で一緒に確かめる", "相続税の申告が要るかと遺産分割の扱いは、税理士と弁護士に確かめていただく"], actHead:"現場で使うなら", note:"相続財産としての扱いは国税庁と税理士で、遺産分割の判断は弁護士で確かめる。請求の手続きは保険会社。", pre:1, say:"亡くなる前の入院の給付金は、ご本人の財産として相続の対象になる仕組みです。死亡保険金とは扱いが違うので、税理士とご確認ください。", more:"よくある勘違いは、保険会社から受け取ったお金なので死亡保険金と同じに扱えると考えることです。給付金は遺産分割の話し合いに入るので、受け取ったご家族が一人で使ってしまうと、ほかの相続人との話がこじれることがあります。", why:"入院給付金は、亡くなった方が生前に入院したことで本人に支払われるはずのお金です。本人の財産が受け継がれる形なので、相続財産そのものとして扱う決まりになっています。" },
      { key:'faq_xhzi_kouisho', faq:1, grp:'hzi', q:"後遺障害保険金に税金はかかる？", re:/後遺障害[^。]{0,16}(税|課税|非課税|申告|所得)/, ng:/法人|会社(が|で|の)/, head:"けがの後遺障害で本人などが受け取る保険金は、非課税です。", body:"傷害保険や自動車保険の人身傷害などで、けがの後遺障害によって受け取る保険金は、身体の傷害にもとづくものとして、被保険者ご本人や配偶者などの親族が受け取れば所得税がかかりません。相手から受け取る損害賠償金も同じく非課税です。受け取る人や契約の形によって扱いが変わることがあるので、証券で確かめます。", acts:["証券で、後遺障害保険金の受取人が誰になっているかを確かめる", "後遺障害の認定や保険金の請求の手順は、保険会社の案内で確かめる", "会社の団体保険など契約の形が違う場合は、税理士に確かめていただく"], actHead:"現場で使うなら", note:"非課税の範囲は国税庁タックスアンサーと税理士で、後遺障害の認定と請求は保険会社の約款と窓口で確かめる。", pre:1, say:"けがの後遺障害でご本人が受け取る保険金は、税金がかからない仕組みです。請求の手順は保険会社の案内で一緒に確かめましょう。", more:"よくある勘違いは、まとまったお金を受け取ったので確定申告が要ると考えることです。非課税の保険金は申告に入れません。ただし、会社が契約して会社が受け取った保険金を、あとから本人に支払う形だと扱いが変わるので、誰が受け取ったかを先に確かめます。", why:"身体の傷害にもとづいて本人が受け取る保険金は、失った体の働きを補うものとして、所得税を課さない決まりになっているからです。" },
      { key:'faq_xhzi_kasai_hokenkin', faq:1, grp:'hzi', q:"火災保険の保険金に税金はかかる？", re:/(火災保険|家財保険|地震保険|家財の損害|火事)[^。]{0,10}(で)?(受け取った)?(保険金|見舞金|臨時費用)[^。]{0,16}(税|課税|非課税|申告|所得)/, ng:/控除|法人|会社(が|で|の)|事業|店舗|お店|商品|在庫|賃貸|貸して/, head:"住まいや家財の損害で個人が受け取る火災保険や地震保険の保険金は、非課税です。", body:"火事や風水害、地震などで住まいや家財が損害を受け、個人が受け取る火災保険や地震保険の保険金は、資産の損害を補うものとして所得税がかかりません。臨時の費用の保険金なども、損害にもとづくものは同じ考え方です。事業に使う建物や商品の損害、貸している建物の損害の保険金は、事業の収入などの扱いになることがあるので別に確かめます。", acts:["住まいの損害か、事業や貸している建物の損害かを先に伺う", "雑損控除を考える方には、受け取った保険金を損害から差し引くことを添える", "事業や賃貸の建物の保険金の扱いは、税理士に確かめていただく"], actHead:"現場で使うなら", note:"非課税の範囲と事業用の扱いは国税庁タックスアンサーと税理士で確かめる。支払いの中身は保険会社の約款で。", pre:1, say:"お住まいや家財の損害で受け取った火災保険の保険金は、税金がかからない仕組みです。事業やお貸ししている建物の場合は扱いが違うので、税理士にご確認ください。", more:"よくある場面は、保険金で修理をしたあと、余ったお金があるので申告が要ると考えることです。暮らしの資産の損害の保険金は申告に入れません。一方で、雑損控除を使うときは保険金を差し引くので、受け取った額の通知は取っておきます。", why:"損害の保険金は、失った資産を元に戻すためのお金で、新たな利益を得たわけではないと考えられているので、所得税を課さない決まりになっているからです。" },
      { key:'faq_xhzi_zasson', faq:1, grp:'hzi', q:"雑損控除で保険金はどう扱う？", re:/雑損控除|(災害|盗難|空き巣|台風|地震|火事|水害)[^。]{0,20}(被害|損害|壊れ)[^。]{0,16}(確定申告|控除|税金が戻|所得税)/, ng:/法人|会社(が|で|の)|事業/, head:"雑損控除は、災害や盗難の損失から、受け取った保険金などを差し引いた額で計算します。", body:"災害や盗難、横領で住まいや家財などに損失が出たとき、確定申告で雑損控除を受けられることがあります。損失の額から、火災保険や地震保険などで受け取った保険金や損害賠償金を差し引いた残りをもとに計算します。災害のときは、雑損控除とは別の、所得税を軽くする仕組みを選べることもあります。対象になる資産と計算は、内容で決まります。", acts:["被害を受けたお客様には、被害の写真や修理の見積り、保険金の支払いの通知を取っておくよう伝える", "雑損控除と別の仕組みのどちらが使えるかは、税務署か税理士で確かめていただく", "保険金の請求がまだなら、請求の手順を一緒に確かめる"], actHead:"現場で使うなら", note:"雑損控除の対象・計算・別の仕組みとの選び方は、国税庁タックスアンサーと税務署・税理士で確かめる。保険金の請求は保険会社で。", pre:1, say:"災害で被害を受けたときは、確定申告で税金が軽くなる仕組みがあり、受け取った保険金を差し引いて計算します。どの仕組みが使えるかは、税務署か税理士でご確認ください。", more:"よくある場面は、保険金の請求と税の手続きの両方が重なり、どちらも後回しになることです。保険金の請求を先に進めると、差し引く額が決まり、税の計算もしやすくなります。書類は一つのファイルにまとめておくよう添えます。", why:"雑損控除は、自分で負担した損失を軽くする仕組みなので、保険金や賠償金で補われた分まで損失に数えないよう、差し引いて計算するからです。" },
      { key:'faq_xhzi_jinshin', faq:1, grp:'hzi', q:"人身傷害保険の死亡保険金に税金はかかる？", re:/人身傷害[^。]{0,24}(税|課税|非課税|相続税)/, ng:/法人|会社(が|で|の)|保険料控除/, head:"相手の過失にあたる部分は非課税で、自分の過失にあたる部分は死亡保険金として税を考えます。", body:"人身傷害保険で受け取る死亡保険金は、二つに分けて考えます。相手の過失にあたる部分は、相手から受け取る損害賠償金と同じ扱いで非課税です。亡くなった方ご自身の過失にあたる部分は、生命保険の死亡保険金と同じく、保険料を払った人と受け取る人の関係で、相続税・所得税・贈与税のどれになるかが決まります。分け方は保険会社の支払いの明細で確かめます。", acts:["保険会社の支払いの明細で、過失の割合ごとの内訳が分かるかを一緒に見る", "自動車保険の保険料を誰が払っていたかを確かめる", "相続税の申告に入れる額と扱いは、税理士に確かめていただく"], actHead:"現場で使うなら", note:"過失の部分ごとの扱いは国税庁と税理士で確かめる。支払いの内訳と過失の割合は保険会社と契約の約款で。", pre:1, say:"人身傷害保険の保険金は、相手の過失の部分と、ご本人の過失の部分で税金の扱いが分かれる仕組みです。支払いの明細を見ながら、税理士とご確認ください。", more:"よくある勘違いは、事故の保険金は全て非課税だと考えることです。ご本人の過失にあたる部分は、生命保険の死亡保険金と同じく相続税などの対象になることがあります。支払いの明細を相続税の申告まで取っておくよう、ご家族に添えます。", why:"相手の過失の部分は相手が償うべき損害を保険が肩代わりしたもので、自分の過失の部分は自分で契約した保険から受け取る保険金だからです。性質が違うので扱いを分けます。" },
      { key:'faq_xhzi_jiko_baisho', faq:1, grp:'hzi', q:"事故で受け取った賠償金や車両保険金に税金は？", re:/(賠償金|慰謝料|示談金|車両保険|見舞金)[^。]{0,16}(税|課税|非課税|申告|所得)/, ng:/法人|会社(が|で|の)|事業|営業用|仕事の車|社用車|火災保険|地震保険|家財/, head:"個人が受け取る事故の賠償金や慰謝料、自家用の車の車両保険金は、多くの場合、非課税です。", body:"事故で体や心が受けた損害に対する損害賠償金や慰謝料、自分の車が壊れたことに対する賠償金や車両保険金は、損害を補うお金として所得税がかかりません。見舞金も、世間の常識の範囲なら同じ扱いです。事業に使う車の車両保険金や、休業で失った事業の収入を補うお金は、事業の収入として扱うことがあるので別に確かめます。", acts:["受け取るお金が、体の損害・物の損害・事業の損害のどれに当たるかを伺う", "事業に使う車や休業の補償があるときは、税理士に確かめていただく", "示談の内容と賠償の額の判断は、保険会社の担当と弁護士に任せる"], actHead:"現場で使うなら", note:"非課税の範囲は国税庁タックスアンサーと税理士で確かめる。示談と賠償の判断は保険会社と弁護士の領域。", pre:1, say:"事故で受け取った慰謝料や車両保険の保険金は、多くの場合、税金がかからない仕組みです。お仕事で使う車の場合は扱いが違うので、税理士にご確認ください。", more:"よくある場面は、お客様から事故の示談金の額や税金を聞かれ、その場で答えたくなることです。賠償の額の話は保険会社の担当と弁護士の領域なので、こちらからは非課税の仕組みと、確かめる先をお伝えするところまでにします。", why:"損害を補うお金は、失ったものを元に戻すためのもので、新たな利益を得たわけではないと考えられているので、所得税を課さない決まりになっているからです。" },
      { key:'faq_xhzi_jigyou_hokenkin', faq:1, grp:'hzi', q:"個人事業主が受け取った保険金に税金はかかる？", re:/(個人事業|自営|フリーランス|お店|店舗)[^。]{0,24}(保険金|休業補償|休業損害)[^。]{0,16}(税|課税|収入|所得|申告)|(商品|在庫|棚卸)[^。]{0,16}(保険金)[^。]{0,16}(税|課税|収入)|休業補償の保険金/, ng:/法人|会社(が|で|の)|株式会社/, head:"商品の損害や休業で失った収入を補う保険金は、事業の収入として扱います。", body:"個人事業の方が受け取る保険金のうち、商品や在庫の損害を補うものや、休業で失った事業の収入を補うものは、事業所得などの収入として扱い、確定申告に入れます。事業に使う建物や設備の損害の保険金は、その資産の損失の計算と合わせて考えます。住まいや家財の損害の保険金は、暮らしの資産として非課税なので、事業の分と分けて整理します。", acts:["受け取った保険金が、商品・設備・休業・住まいのどれの損害に当たるかを分けて書き出す", "店舗と住まいが一緒の建物は、どの部分の損害かを保険会社の明細で確かめる", "帳簿への付け方と申告は、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"事業の収入としての扱いと資産の損失の計算は、国税庁と顧問の税理士で確かめる。支払いの内訳は保険会社の明細で。", pre:1, say:"お店の商品や休業の補償で受け取る保険金は、事業の収入として扱う仕組みです。お住まいの分とは分けて、顧問の税理士にご確認ください。", more:"よくある勘違いは、保険金は全て非課税だと考え、事業の帳簿に入れないことです。商品や休業の補償は、もともと売上で得るはずだったお金の代わりなので、事業の収入になります。保険会社の明細を、帳簿の資料として税理士に渡すよう添えます。", why:"商品や休業で失った収入を補う保険金は、本来は売上として得るはずだったお金の代わりなので、事業の収入と同じに扱う決まりになっているからです。" },
      { key:'faq_xhzi_tsumitate_sonpo', faq:1, grp:'hzi', q:"積立型の損害保険の満期金に税金は？", re:/(積立|積み立て)[^。]{0,4}(型の?)?[^。]{0,6}(火災保険|傷害保険|損害保険|損保|介護費用保険)[^。]{0,16}(満期|返戻金)[^。]{0,16}(税|課税|一時所得|申告)?|積立傷害/, ng:/控除|年末調整|法人|会社(が|で|の)/, head:"保険料を払った人が受け取る積立型の損害保険の満期返戻金は、一時所得として扱います。", body:"積立型の火災保険や傷害保険などの満期返戻金は、保険料を払った人が受け取れば、生命保険の満期金と同じく一時所得として所得税と住民税の対象です。払い込んだ保険料のうち積み立ての部分などを差し引いて計算します。保険期間が短い一時払いの契約は、源泉徴収で課税が終わる形になることがあります。受け取る人が違うと、贈与税の話になります。", acts:["証券で、積立型かどうかと、保険料を払う人と満期返戻金の受取人を確かめる", "満期の前に、その年のほかの一時所得と合わせて考える必要があると伝える", "一時所得の計算と申告は、税理士か税務署で確かめていただく"], actHead:"現場で使うなら", note:"一時所得の計算と源泉徴収で終わる形の要件は、国税庁と税理士で確かめる。満期返戻金の額は保険会社の案内で。", pre:1, say:"積立型の損害保険の満期返戻金も、保険料をお払いになった方が受け取るなら一時所得の扱いです。満期の前に、ほかの一時所得と合わせて確かめておきましょう。", more:"よくある場面は、長く続いた積立型の傷害保険の満期を、生命保険ではないので税は関係ないと思っていることです。扱いは生命保険の満期金と同じ考え方です。満期の案内が届いたら、払い込んだ保険料の合計が分かる書類も一緒に取っておきます。", why:"積立型の損害保険の満期返戻金は、払い込んだ保険料から生まれた一時的な収入なので、生命保険の満期金と同じく一時所得の仕組みで扱う決まりだからです。" },
      { key:'faq_xhzi_haito_zei', faq:1, grp:'hzi', q:"保険の配当金を受け取ったら税金はかかる？", re:/(保険の)?(配当金|剰余金|割戻金)[^。]{0,16}(税金|課税|一時所得|所得税|申告)/, ng:/控除|株|投資信託|法人|会社(が|で|の)|証券口座|nisa|ニーサ|引き出し方|引き出したい/, head:"契約の途中で受け取る保険の配当金は、受け取ったときには課税されません。", body:"契約が続いている間に受け取る保険の配当金（剰余金の分配）は、払い込んだ保険料の一部が戻るものと考えるので、受け取った時点では所得税がかかりません。その代わり、あとで満期金や解約返戻金を受け取るときに、一時所得の計算で払い込んだ保険料から差し引きます。満期金や保険金と一緒に受け取る配当金は、そのお金と合わせて扱います。", acts:["配当金の受け取り方（受け取る・積み立てる・保険料にあてる）を契約概要で一緒に確かめる", "満期や解約のときの計算で、受け取った配当金が差し引かれることを先に伝える", "配当金の額は約束されたものではないことを、保険会社の案内のとおりに伝える"], actHead:"現場で使うなら", note:"配当金の税の扱いは国税庁と税理士で、配当金の受け取り方と額は保険会社の契約概要と案内で確かめる。", pre:1, say:"契約の途中で受け取る保険の配当金は、その時点では税金がかからない仕組みです。満期や解約のときの計算で差し引かれるので、受け取った記録を残しておきましょう。", more:"よくある勘違いは、配当金を株の配当と同じものと考えることです。保険の配当金は、払い込んだ保険料のうち結果として多く払った分が戻るものです。株の配当とは扱いが違うので、確定申告の配当の欄に書くものではありません。", why:"保険の配当金は、払い込んだ保険料の一部が戻るものと考えられているので、受け取ったときに所得とせず、あとで受け取る満期金などの計算の中で保険料から差し引く形にしているからです。" },
      { key:'faq_xhzi_henkaku_uneki', faq:1, grp:'hzi', q:"変額保険の運用中に増えた分に税金はかかる？", re:/変額(保険|終身|有期|個人年金)?[^。]{0,20}(運用中|運用益|増えた分|特別勘定|スイッチング|繰入)[^。]{0,16}(税|課税)/, ng:/控除|年末調整|法人|会社(が|で|の)/, head:"運用中に増えた分や、特別勘定の間の移しかえには、その時点では税金がかかりません。", body:"変額保険は、払い込んだ保険料の一部を特別勘定で運用し、その成果で受け取る額が変わる保険です。契約が続いている間は、運用で増えた分にも、特別勘定の間で移しかえるときにも、その時点では所得税がかかりません。税は、解約や満期、保険金や年金を受け取るときに、受け取る形と保険料を払った人で決まる扱いで考えます。運用の成果で、払った額を下回ることもあります。", acts:["変額保険は運用の成果で受け取る額が増えも減りもする仕組みだと、契約概要で示す", "受け取るときの税は、満期金・解約返戻金・死亡保険金のそれぞれの決まりで考えると伝える", "税の見込みは、受け取る形が決まったときに税理士に確かめていただく"], actHead:"現場で使うなら", note:"受け取るときの税の扱いは国税庁と税理士で、運用の仕組みと費用は保険会社の契約概要と注意喚起情報で確かめる。", pre:1, say:"変額保険は、契約が続いている間に増えた分には、その時点では税金がかからない仕組みです。受け取る額は運用で増えも減りもするので、契約概要を一緒に見ておきましょう。", more:"よくある勘違いは、運用中に税金がかからないことを、そのまま有利さとして受け取ることです。税は受け取るときにかかり、運用の成果によっては払った額を下回ることもあります。税の仕組みと、運用の増減の仕組みは、分けてお伝えします。", why:"保険の運用益は、契約者が自由に引き出せる形で受け取っているわけではないので、契約が終わってお金を受け取るときに、保険の契約全体の所得としてまとめて考える決まりだからです。" },
      { key:'faq_xhzi_shinkoku_shorui', faq:1, grp:'hzi', q:"相続税の申告で保険について要る書類は？", re:/相続税の申告[^。]{0,20}保険[^。]{0,16}(書類|何が要|必要|出す)|保険[^。]{0,16}相続税の申告[^。]{0,12}(書類|何が要|出す)/, ng:/法人|会社(が|で|の)/, head:"受け取った保険金の支払いの明細と、続く契約の解約返戻金の額の証明などをそろえます。", body:"相続税の申告では、受け取った死亡保険金の支払いの明細（いつ・誰に・いくら支払われたか）が要ります。亡くなった方が保険料を払っていて契約が続くものは、亡くなった日の解約返戻金の額の証明を保険会社に頼みます。亡くなった方が受け取るはずだった給付金も財産に入るので、その支払いの明細も取っておきます。何が要るかは、申告を頼む税理士の案内に合わせます。", acts:["ご家族と一緒に、亡くなった方が関わっていた保険の契約を一覧にする", "続く契約は、亡くなった日の解約返戻金の額の証明を保険会社に頼む手順を案内する", "書類の集め方を案内するところまでにし、申告書の作成は税理士に任せる"], actHead:"現場で使うなら", note:"要る書類と申告の期限は、税理士と国税庁・税務署の案内で確かめる。証明書の出し方は保険会社の窓口で。申告書の作成は税理士の業務。", pre:1, say:"相続税の申告には、受け取った保険金の明細と、続くご契約の解約返戻金の額の証明が要ることがあります。保険会社への頼み方は私がご案内しますので、申告は税理士にお任せください。", more:"よくある場面は、受け取った保険金のことは覚えていても、亡くなった方が保険料を払っていた家族の契約を忘れていることです。続く契約も相続財産になるので、家族全員の証券を集めて、保険料を誰が払っていたかを一緒に見ます。", why:"相続税は、亡くなった日の財産の額で計算するので、受け取った保険金の額に加え、続く契約の亡くなった日の値打ちを示す書類が要るからです。" },
      { key:'faq_xhzi_danshin_souzoku', faq:1, grp:'hzi', q:"団信でなくなった住宅ローンは相続税の債務控除になる？", re:/(団信|団体信用(生命)?(保険)?)[^。]{0,24}(相続|債務控除|ローンは|ローンが|返され|なくなった)/, ng:/控除証明書|年末調整|保険料控除/, head:"団信で返されたローンは債務控除になりませんが、団信の保険金も相続財産に入りません。", body:"住宅ローンを借りた方が亡くなり、団体信用生命保険の保険金で残りのローンが返されると、そのローンは借金として残りません。そのため、相続税の計算で差し引ける借金（債務控除）にはなりません。一方、保険金は金融機関が受け取ってローンにあてるので、ご家族の相続財産にも入りません。住まいそのものは相続財産になります。", acts:["ローンが団信で返されたかを、金融機関の書類で一緒に確かめる", "ローンが無くなった住まいの扱いと相続税がかかるかは、税理士に確かめていただく", "団信のほかに残る借り入れがあれば、債務の一覧に入れるよう伝える"], actHead:"現場で使うなら", note:"債務控除の範囲は国税庁と税理士で確かめる。団信で返されたかは金融機関の書類で。", pre:1, say:"団信で住宅ローンが返された場合、そのローンは相続税の計算で差し引けませんが、団信の保険金も相続財産には入らない仕組みです。詳しくは税理士にご確認ください。", more:"よくある勘違いは、住宅ローンの残りを借金として相続税の計算から引こうとすることです。団信で返された分は引けません。反対に、団信に入っていない借り入れや、団信の対象外のローンは債務として残るので、借り入れを一つずつ確かめます。", why:"債務控除は、亡くなった方が残した借金を差し引く仕組みです。団信で返されたローンは亡くなったときに消えて、相続人が引き継ぐ借金にならないからです。" },
      { key:'faq_xhzi_keisan_irai', faq:1, grp:'hzi', q:"お客様に税額を計算してほしいと頼まれたら？", re:/(税額|税金|相続税|所得税|贈与税)[^。]{0,10}(を)?(計算して|出して|いくらになるか計算)[^。]{0,12}(ほしい|欲しい|頼まれ|言われ|と言)|(確定申告|申告)の書類を(代わりに|代わって)(書|作)|無料なら[^。]{0,12}(税金|税額)の計算|(税金|税務)の相談[^。]{0,8}(どこまで|答えて)|(税金|税務)の手続きを[^。]{0,4}(代わりに|代わって)/, head:"個別の税額の計算や申告書の作成は税理士の業務なので、無料でも引き受けません。", body:"お客様ごとの具体的な税額の計算、税の相談への個別の回答、申告書の作成は、税理士の業務です。お金をいただかない場合でも同じ扱いなので、募集人が引き受けることはできません。こちらでお伝えできるのは、税の仕組みの一般的な説明と、確かめる先のご案内までです。お客様の了承を得て、顧問の税理士や税理士会の窓口につなぎます。", acts:["頼まれたら、仕組みの一般的な説明までにして、税額は税理士に確かめていただくと伝える", "お客様の了承を得て、顧問の税理士に渡す資料（証券の写し・保険料の負担者）をそろえる", "顧問の税理士がいない方には、税理士会などの相談の窓口を案内する"], actHead:"現場で使うなら", note:"税理士の業務の範囲は日本税理士会連合会と国税庁の案内で、募集の場での線引きは社内の規定と御社のコンプライアンス担当で確かめる。", pre:1, say:"税額の計算は税理士の専門のお仕事なので、私からは仕組みのご説明までにさせてください。必要な資料をそろえて、税理士におつなぎします。", more:"よくある場面は、親しいお客様から、だいたいでいいから相続税を出してと言われることです。概算でも個別の税額を出すと、税理士の業務に当たるおそれがあり、外れたときにはお客様の判断を誤らせます。仕組みの説明と資料の準備に徹すると、信頼を損ねません。", why:"税の計算と申告は、お客様の権利と義務に直接関わるので、専門の資格を持つ税理士だけが行えると決められているからです。お金をもらわないことは、その線を変えません。" },
      /* jsk.json */
      { key:'faq_xjsk_kimekata', faq:1, grp:'jsk', q:"後継者はどうやって決める？", re:/(後継者|跡継ぎ|後継ぎ)[^。]{0,8}(決め方|選び方|決める|選ぶ|を誰に|は誰に|の候補)/, ng:/自分の代|うちの代理店|自分の会社|うちの会社|私の会社|弊社|当社/, head:"後継者は、社長が会社に残したいものを言葉にしてから、候補を並べて決めます。", body:"候補は、ご家族、社員や役員、社外の会社や人の三つに分かれます。誰がふさわしいかは、経営を担う力と意欲に加えて、株を持てるか、借入の保証を引き継げるか、社員や取引先が付いてくるかで変わります。決めるのは社長とご家族で、こちらは材料をそろえて並べるところまでを手伝います。", acts:["社長が会社に残したいもの（社員の雇用・取引先・技術・名前）を先に書き出していただく", "候補ごとに、経営の力・株を持つお金・保証の引継ぎ・周りの受け止めを表に並べる", "候補ご本人の意思は、社長から直接確かめていただく流れをお伝えする"], actHead:"現場で使うなら", note:"誰を後継者にするかは社長とご家族が決めること。株の移し方と税は税理士・弁護士、公的な事業承継の相談窓口でも確かめる。", pre:1, say:"誰に継いでいただくかの前に、会社に何を残したいかを伺えますか。そこが決まると、候補の方の見え方が変わってきます。", more:"よくある勘違いは、後継者を経営を担う人のことだけで考えることです。実際は、経営を任せる人と株を持つ人が分かれることもあり、どちらも同じ人に集めるのか、分けるのかで準備が変わります。候補が決まらないときは、決める時期だけでも先に置いていただくと、準備の段取りが組めます。", why:"後継者には、経営を担う力のほかに、株を持ち、借入の保証を引き継ぎ、社員や取引先に受け入れられることが求められるためです。会社に何を残したいかが決まっていないと、どの力を重く見るかが定まりません。" },
      { key:'faq_xjsk_tsuganai', faq:1, grp:'jsk', q:"社長の子どもが会社を継がないと言っていたら？", re:/(子ども|子供|息子|娘|お子様|お子さん|長男|次男|長女)[^。]{0,8}(継がない|継ぐ気がない|継ぐ気はない|継ぎたくない|継ぐつもりがない)/, ng:/自分の代|うちの代理店|うちの子|私の子/, head:"お子様が継がないときは、理由を責めず、社員や社外への承継の道を並べます。", body:"継がないと決めたお子様にも、それぞれの仕事や暮らしの事情があります。その場合の道は、社員や役員に継いでもらう、社外の会社に引き継いでもらう、時期を決めて会社を閉じる、のいずれかで、どれを選ぶかで準備が変わります。継がないお子様も株の相続人になりうるので、株の行き先は別に考えておきます。", acts:["お子様の気持ちが変わる見込みより、社長ご自身がいつ退きたいかを先に伺う", "社員・社外への承継・閉じる道のそれぞれに、要る準備を並べてお見せする", "公的な事業承継の相談窓口で、社外の引き継ぎ先を探す相談ができることをお伝えする"], actHead:"現場で使うなら", note:"継ぐかどうかはご家族が決めること。株と税は税理士、法律上の判断は弁護士。社外への引き継ぎは公的な事業承継の相談窓口でも確かめる。", pre:1, say:"お子様が別の道を選ばれても、会社を続ける道はほかにもあります。まずは社長がいつ頃退きたいかから、ご一緒に整理させてください。", more:"よくある勘違いは、子どもが継がなければ会社を閉じるしかないと考えることです。社員への承継や、社外の会社への引き継ぎで、社員の雇用や取引先との関係を残せることもあります。ただし継がないお子様にも株が相続で渡ると、のちに経営と持ち主が分かれるので、株を誰に渡すかは早めに決めておきます。", why:"継ぐかどうかは、お子様の人生の選択でもあり、説得の話にすると親子の関係にも響くためです。道ごとに準備の中身と時間が違うので、選ぶ道を先に決めるほど、残された時間を準備に使えます。" },
      { key:'faq_xjsk_shinzoku', faq:1, grp:'jsk', q:"子どもに会社を継がせるときに気をつけることは？", re:/親族内承継|(子ども|子供|息子|娘|お子様|長男|次男|長女)[^。]{0,6}(に|へ)[^。]{0,6}(会社|事業|経営)[^。]{0,4}(を継が|を継い|を継ぐ|を任せ|を譲)/, ng:/継がない|継ぎたくない|継ぐ気|自分の代|うちの代理店/, head:"親族に継ぐときは、株と経営の両方を、ほかのご家族の気持ちと並べて渡し方を決めます。", body:"親族内承継は、社員や取引先に受け入れられやすく、株を相続や贈与で渡せる道がある一方、継がないご家族との分け方が問題になりやすい形です。会社の株や事業用の土地が財産の多くを占めると、後継者に集めるほど、ほかのご家族の取り分との釣り合いが難しくなります。経営を任せる時期と株を渡す時期を、別々に考えておきます。", acts:["後継者になるお子様ご本人の意思を、社長から確かめていただけているかを伺う", "社長の財産のうち、株と事業用の財産がどれだけを占めるかを書き出していただく", "継がないご家族への分け方は、弁護士・税理士を交えて考える段取りをお伝えする"], actHead:"現場で使うなら", note:"株の渡し方と税は税理士、遺留分や遺言など法律上の判断は弁護士の業務。こちらでは分け方を決めない。", pre:1, say:"お子様に継いでいただくときは、会社のことと、ほかのご家族への分け方を一緒に考えておくと、あとの話し合いが穏やかになります。", more:"場面の例としては、長男に株を全て残す遺言を作ったあとで、ほかのお子様から取り分の話が出る形です。一緒に見るのは、株主名簿・決算書・社長名義の土地や建物の一覧です。よくある勘違いは、身内だから話さなくても分かってくれると考えることで、継がないご家族への説明の場は前もって考えておきます。", why:"会社の株や事業用の財産は分けにくく、後継者に集めると、ほかのご家族の取り分が小さくなりやすいためです。相続人には法律が認める最低限の取り分もあるので、経営の都合だけで渡し方を決めると、あとで争いの種になることがあります。" },
      { key:'faq_xjsk_shain', faq:1, grp:'jsk', q:"社員に会社を継いでもらうときの注意は？", re:/(従業員|社員|役員|番頭)[^。]{0,4}(承継|に会社を継|に事業を継|に継いで|に継が|に事業を引き継|に会社を引き継)|親族以外の(社員|従業員|役員)/, ng:/自分の代|うちの代理店|自分の会社|うちの会社|うちの社員|持株会|持ち株会/, head:"社員に継ぐときは、株を買うお金と、借入の保証の引継ぎを先に考えます。", body:"社員や役員への承継は、会社をよく知る人に任せられる一方、後継者が株を買い取るお金を用意しにくく、社長の個人保証を引き継ぐ重さも課題になります。株を社長のご家族が持ち続け、経営だけを任せる形もあります。ご家族の了解と、取引の金融機関の受け止めも、早めに確かめておきます。", acts:["後継者の候補ご本人に、株を持つ意思と保証を引き継ぐ考えがあるかを、社長から伺っていただく", "株の評価のおおよそと、買い取りの資金の道（借入・分けて買う・会社が関わる形）を税理士に確かめる", "社長のご家族が株をどうするお考えかを、同じ席で確かめる"], actHead:"現場で使うなら", note:"株の評価と税は税理士、株の移し方の法律上の判断は弁護士、借入と保証は取引の金融機関に確かめる。公的な事業承継の相談窓口もある。", pre:1, say:"社員の方に継いでいただくときは、株と借入の保証をどうするかで準備が大きく変わります。顧問の先生や金融機関も交えて、順番に整理しませんか。", more:"場面の例としては、長く番頭役を務めた役員に社長を任せたいが、株を買うお金がなく、社長の奥様が株を持ち続けたいという形です。経営を任せる人と株を持つ人が分かれると、のちに株の持ち主が代替わりしたときの扱いも決めておく必要があります。買い取りの資金は、金融機関の融資や公的な制度の相談先もあります。", why:"非上場の会社の株は評価の額が大きくなりやすく、給与で暮らしてきた社員にはまとまったお金を用意しにくいためです。また中小企業の借入には社長の個人保証が付いていることが多く、引き継ぐ人の暮らしに響くためです。" },
      { key:'faq_xjsk_ikusei', faq:1, grp:'jsk', q:"後継者の育て方は？何から任せる？", re:/(後継者|跡継ぎ|後継ぎ)[^。]{0,4}(の育て方|を育て|の育成|育成|教育|に何から|に任せる順)/, ng:/自分の代|うちの代理店|自分の後継|私の後継/, head:"後継者は、現場・数字・社外との関係の順に、社長のそばで任せる範囲を広げて育てます。", body:"後継者の育成は、会社の現場と仕事の流れを知ること、決算書や資金繰りを読めること、金融機関や取引先と社長として向き合えることの三つを、時間をかけて身に付けていく道のりです。社内で経験を積む形と、社外で働いたり学んだりしてから戻る形があります。権限を少しずつ渡し、任せた仕事の結果を社長と振り返る場を持ちます。", acts:["社長に、後継者に任せている仕事と、まだ任せていない仕事を書き出していただく", "決算書の読み合わせや、金融機関との面談に後継者を同席させる段取りを伺う", "公的な事業承継の相談窓口や商工会議所などに、後継者向けの学びの場があることをお伝えする"], actHead:"現場で使うなら", note:"育て方の決まった正解は無く、会社ごとに違う。研修や支援の中身は、公的な事業承継の相談窓口・商工会議所・顧問の税理士に確かめる。", pre:1, say:"後継者の方には、どの仕事から任せていらっしゃいますか。任せている範囲を一度書き出すと、渡す順番が見えてきます。", more:"場面の例としては、現場の仕事はできても、決算書や借入の話に関わったことがない後継者です。社長のそばで金融機関との面談に同席するだけでも、経営の目線が育ちます。よくある勘違いは、社長の肩書きを渡せば育つと考えることで、肩書きの前に、判断を任せて結果を一緒に振り返る経験を重ねます。", why:"経営の判断は、現場の仕事とは別の力で、教わるだけでなく実際に任されて身に付くものだからです。社員や取引先、金融機関の信頼も、後継者が社長として向き合う回数を重ねて少しずつ移っていきます。" },
      { key:'faq_xjsk_torihiki', faq:1, grp:'jsk', q:"事業承継を取引先や金融機関にどう伝える？", re:/(事業承継|承継|社長交代|代替わり)[^。]{0,10}(取引先|金融機関|銀行)|(後継者|跡継ぎ)[^。]{0,4}を[^。]{0,6}(取引先|金融機関|銀行)/, head:"承継は、金融機関には早めに相談として、取引先には順番を決めて、社長と後継者がそろって伝えます。", body:"金融機関は、借入の返済と保証の扱いに関わるので、承継の計画の段階から相談しておくと話が進みやすくなります。取引先には、大事な先から社長が自分の口で伝え、後継者を紹介して、これからも関係が続くことを示します。伝える前に社内の役員や主な社員に知らせておくと、外から聞いて動揺することを防げます。", acts:["伝える相手を、金融機関・主な取引先・社内に分け、伝える順番を一緒に決める", "後継者が金融機関と顔を合わせる場を、決算の説明の機会などに作る段取りを伺う", "保険の担当や契約の窓口が替わることがあれば、こちらからもごあいさつに伺うと伝える"], actHead:"現場で使うなら", note:"伝える時期と中身は社長が決めること。借入と保証の扱いは金融機関、契約の名義の変更は保険会社と顧問の税理士に確かめる。", pre:1, say:"社長交代のお知らせは、金融機関と大事な取引先から、社長と後継者の方がおそろいで伝えると、関係がそのまま続きやすくなります。", more:"よくある勘違いは、承継が終わってから知らせればよいと考えることです。金融機関は後継者の経営の力と、保証をどうするかを見たいので、早めに会っておくと話が進みます。取引先には、窓口の担当が替わるのか、取引の条件は変わらないのかも合わせて伝えます。", why:"中小企業の取引は、社長個人への信用で成り立っている面が大きく、伝え方と順番で、後継者への信用の移り方が変わるためです。" },
      { key:'faq_xjsk_jiki', faq:1, grp:'jsk', q:"事業承継のタイミングはいつがいい？", re:/事業承継[^。]{0,6}(タイミング|時期|いつ)|(社長|代表)[^。]{0,4}(交代|を譲る|の交代)[^。]{0,8}(時期|タイミング|いつ)/, ng:/自分の代|うちの代理店|自分が引退/, head:"承継の時期は、社長の体と気力、後継者の育ち、会社の業績の三つを並べて決めます。", body:"時期に決まった正解はなく、社長が元気なうちに後継者へ少しずつ任せ、株を渡す時期と経営を任せる時期を分けて組むことが多くあります。後継者の育成や株の移し方には時間がかかるので、交代の目安から逆算して準備を始めます。株の評価は業績で動くので、渡す時期の考え方は顧問の税理士と相談します。", acts:["社長に、いまの働き方をいつまで続けたいかと、交代の目安の時期を伺う", "交代の目安から逆算して、後継者の育成・株の移し方・保証の引継ぎの順番を一枚に並べる", "株を渡す時期の税の考え方は、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"時期は社長とご家族が決めること。株を渡す時期の税の扱いは税理士、法律の手続きは弁護士・司法書士に確かめる。", pre:1, say:"交代の時期そのものより、いつ頃までに何を終えておきたいかを先に伺えますか。そこから準備の順番をご一緒に組めます。", more:"よくある勘違いは、承継を社長が退く日だけの出来事と考えることです。実際は、後継者に任せる仕事を増やす時期、株を渡す時期、社長が会長などに退く時期、と段階に分かれます。社長が急に倒れると、この段階を踏めないまま進むので、元気なうちに目安だけでも置いておきます。", why:"経営の力や取引先の信頼は、肩書きを渡した日に移るものではなく、少しずつ移っていくためです。株の評価も業績で上下するので、時期を一つの日で考えると、準備も税の扱いも組み立てにくくなります。" },
      { key:'faq_xjsk_keikaku', faq:1, grp:'jsk', q:"事業承継計画とは？何を書く？", re:/事業承継計画|事業承継の計画|承継計画/, ng:/特例/, head:"事業承継計画は、誰に・いつ・何を渡すかを、年ごとの表にまとめたものです。", body:"会社の今の姿（業績・株主・借入と保証）と、社長と後継者の役職や株の持ち分を、これから先の年ごとに並べて書きます。後継者の育成、株を移す順番、退職金や保証の引継ぎ、取引先への伝え方なども入れます。中小企業庁の事業承継ガイドラインに作り方の例があり、顧問の税理士や公的な事業承継の相談窓口と作ります。", acts:["社長と後継者の年齢と役職、株の持ち分を、年ごとに並べる表の枠をお見せする", "決算書・株主名簿・借入の返済予定表を、計画の材料としてそろえていただく", "保険で用意するお金（退職金・納めるお金など）が計画のどこに入るかを一緒に書き込む"], actHead:"現場で使うなら", note:"計画の中身は社長とご家族、株と税は税理士、法律の手続きは弁護士・司法書士。税の特例のための計画は別の様式なので、都道府県の窓口と税理士で確かめる。", pre:1, say:"承継の段取りを、年ごとの一枚の表にしてみませんか。誰が・いつ・何をするかが見えると、ご家族とも話しやすくなります。", more:"場面の例としては、社長は何となく考えているが、後継者も社員も段取りを知らない会社です。計画を表にすると、後継者に何をいつまでに任せるかが共有できます。よくある勘違いは、事業承継税制で出す計画と同じものと考えることで、税の特例の計画は決まった様式で都道府県に出すもので、会社全体の承継の計画とは別です。", why:"承継は長い時間をかけて進み、関わる人も多いため、頭の中の予定のままだと、後継者・ご家族・専門家の動きがそろわないためです。表にしておくと、遅れや抜けにも気づけます。" },
      { key:'faq_xjsk_center', faq:1, grp:'jsk', q:"事業承継・引継ぎ支援センターとは？", re:/引継ぎ支援センター|引き継ぎ支援センター|後継者人材バンク|事業承継[^。]{0,6}(公的な|相談窓口|相談先)|公的な[^。]{0,6}事業承継/, head:"事業承継・引継ぎ支援センターは、国が各都道府県に置いている、承継の公的な相談窓口です。", body:"親族や社員への承継の相談のほか、後継者がいない会社と、事業を引き継ぎたい会社や人を引き合わせる支援もしています。後継者のいない小さな事業と、起業したい人を引き合わせる後継者人材バンクの取り組みもあります。相談の中身や費用は窓口で確かめます。", acts:["後継者が決まっていない社長に、公的な相談窓口があることを一つの道としてお伝えする", "お住まいの都道府県の窓口の連絡先を、社長と一緒に調べる", "保険の話とは分けて、相談するかどうかは社長に決めていただく"], actHead:"現場で使うなら", note:"窓口の支援の中身・費用・手続きは、各都道府県の事業承継・引継ぎ支援センターと中小企業庁の公表資料で確かめる。", pre:1, say:"後継者のことは、国が都道府県ごとに置いている公的な相談窓口でも相談できます。保険のお話とは別に、こうした道もあることをお伝えしておきます。", more:"場面の例としては、子どもも社員も継がない小さな会社の社長が、閉じるしかないと思い込んでいる形です。窓口では、引き継ぎ先を探す相談や、専門家の紹介を受けられることがあります。よくある勘違いは、大きな会社の売買の話だけを扱うと思うことで、小さな事業や個人の事業の相談もしています。", why:"後継者がいないまま、まだ続けられる会社が閉じると、雇用や技術、取引先とのつながりが失われるため、国が承継の相談の場を公的に用意しているためです。" },
      { key:'faq_xjsk_haigyou', faq:1, grp:'jsk', q:"後継者がいないと廃業するしかない？", re:/(後継者|跡継ぎ|後継ぎ)[^。]{0,8}(いない|不在|おらず)[^。]{0,10}(廃業|畳む|たたむ|閉じる)|廃業(するしか|しかない|か|と)[^。]{0,4}(承継|売|譲)|(会社|事業)を(たたむ|畳む)か[^。]{0,4}(売|譲|継)/, ng:/自分の代|うちの代理店|自分の会社/, head:"後継者がいなくても、社員や社外への引き継ぎで、会社を残せる道があります。", body:"道は、社員や役員に継いでもらう、社外の会社や人に引き継いでもらう、時期を決めて会社を閉じる、に分かれます。閉じる道にも、借入の返済、社員の雇用、取引先や設備の始末といった手続きとお金が要ります。どの道でも、決算書と借入・保証の状況を先に書き出しておくと、比べやすくなります。", acts:["社長に、会社を閉じた場合と、誰かに引き継いだ場合に、社員と取引先がどうなるかを並べていただく", "借入と社長の個人保証の残りを、決算書と返済予定表で確かめる", "社外への引き継ぎは、公的な事業承継の相談窓口で相談できることをお伝えする"], actHead:"現場で使うなら", note:"どの道を選ぶかは社長とご家族が決めること。廃業と承継の税は税理士、法律の手続きは弁護士・司法書士、公的な事業承継の相談窓口でも確かめる。", pre:1, say:"閉じる以外にも、社員の方や社外に引き継いでもらう道があります。どの道でも要る準備を、まずは並べて見てみませんか。", more:"よくある勘違いは、小さな会社は引き継ぎ手が見つからないと決めつけることです。取引先や技術、地域のお客様を求めている会社や人がいることもあります。閉じる道を選ぶときも、借入の返済と保証の始末、社員の再就職の手当てなど、時間のかかる準備があるので、早めに段取りを考えます。", why:"会社を閉じると、社員の雇用や取引先との関係、技術や地域のお客様が失われますが、引き継ぎなら残せることがあるためです。どちらの道にも手続きとお金が要るので、比べてから選ぶ順番が大事になります。" },
      { key:'faq_xjsk_enkatsu', faq:1, grp:'jsk', q:"経営承継円滑化法とは？", re:/円滑化法|経営承継円滑化/, head:"経営承継円滑化法は、中小企業の承継を、税・民法・金融の三つの面から支える法律です。", body:"事業承継税制（相続税・贈与税の納税の猶予）を使うための都道府県知事の認定、後継者が受け継いだ株を遺留分の計算から外すなどの民法の特例、承継に要るお金を借りやすくする金融の支援、が柱です。どれも要件と手続きがあり、使えるかどうかは会社ごとに確かめます。", acts:["承継の相談で、税・民法・金融の支えがあることを入口としてお伝えする", "使えるかどうかと手続きは、顧問の税理士と都道府県の窓口に確かめていただく", "保険の話は、これらの支えでまかなえない部分の備えとして分けて話す"], actHead:"現場で使うなら", note:"要件と手続きは中小企業庁と都道府県の公表資料、税は税理士、民法の特例は弁護士に確かめる。改正が続いているので最新を見る。", pre:1, say:"承継には、税や法律の面で国の支えの仕組みがあります。使えるかどうかは顧問の先生と確かめ、その上で残る備えをご一緒に考えましょう。", more:"場面の例としては、事業承継税制を使いたいが、何から手を付けるか分からない社長です。税の特例は、都道府県知事の認定を受けることが前提になります。よくある勘違いは、法律の名前を聞いて自動で税の扱いが変わると考えることで、申請と報告の手続きを続けて初めて使える仕組みです。", why:"中小企業では、株が社長の財産の多くを占め、相続の税や家族の取り分、資金繰りが承継の妨げになりやすいため、法律でまとめて支える形にしているためです。" },
      { key:'faq_xjsk_ruiji', faq:1, grp:'jsk', q:"類似業種比準方式とは？", re:/類似業種/, head:"類似業種比準方式は、同じ業種の上場会社と、配当・利益・純資産の三つを比べて株を評価する方法です。", body:"国税庁が業種ごとに公表する上場会社の株価と、1株あたりの配当・利益・純資産の平均をもとに、評価する会社の同じ三つの数字と比べて計算します。会社の規模に応じた割り引きもあります。利益や配当の数字が評価に効くので、業績の良い年が続くと評価が上がりやすくなります。", acts:["決算書の利益・配当・純資産の動きを、社長と一緒に年ごとに見る", "評価の計算そのものは、顧問の税理士にお願いする流れを最初にお伝えする", "評価が上下する理由を、業績の数字とつなげて説明する"], actHead:"現場で使うなら", note:"評価の計算と税は税理士の業務。計算の方法と業種ごとの数字は、国税庁の財産評価基本通達と公表資料で確かめる。", pre:1, say:"会社の株の評価は、同じ業種の上場会社と比べる方法があり、利益や配当の数字で動きます。計算は顧問の先生にお願いし、まずは数字の流れを一緒に見ませんか。", more:"よくある勘違いは、売上が大きいほど評価が上がると考えることで、この方法で見るのは配当・利益・純資産です。業種の分け方によっても比べる相手が変わります。大きな会社ほどこの方法の重みが大きく、小さな会社では純資産から計算する方法との組み合わせになるのが一般的です。", why:"取引相場のない株には市場の値段が無いため、同じ業種の上場会社の値段を手がかりに、会社の稼ぐ力と蓄えを比べて値を付ける考え方をとっているためです。" },
      { key:'faq_xjsk_junshisan', faq:1, grp:'jsk', q:"純資産価額方式とは？", re:/純資産価額/, head:"純資産価額方式は、会社の財産を相続税の評価に置き直し、借金を引いた額から株を評価する方法です。", body:"会社の持つ土地や建物、保険の権利などを、帳簿の額ではなく相続税の評価の額に置き直して合計し、借入などの負債を差し引きます。含み益があるときは、その一部を差し引く調整もあります。会社に財産が積み上がるほど評価が上がり、小さな会社ではこの方法の重みが大きくなります。", acts:["会社が持つ土地・建物・有価証券・保険の一覧を、決算書の明細と一緒に見る", "帳簿の額と評価の額が違うことを、土地の例で説明する", "評価の計算は、顧問の税理士にお願いする流れをお伝えする"], actHead:"現場で使うなら", note:"評価の計算と税は税理士の業務。財産ごとの評価の方法は、国税庁の財産評価基本通達と顧問の税理士で確かめる。", pre:1, say:"会社が持っている財産を、相続のときの評価に置き直して株を評価する方法があります。土地や保険の評価も入るので、顧問の先生と一緒に確かめておきませんか。", more:"場面の例としては、昔に買った土地を持つ会社で、帳簿では小さな額でも、評価に置き直すと大きくなる形です。会社が契約している保険も、解約返戻金などをもとに財産として数えられます。よくある勘違いは、決算書の純資産の額がそのまま評価になると考えることです。", why:"会社を解散して財産を分けたら株主にいくら残るか、という見方で株の値を測る考え方だからです。帳簿の額は買った時の値段なので、今の値打ちに置き直します。" },
      { key:'faq_xjsk_haitou', faq:1, grp:'jsk', q:"配当還元方式とは？", re:/配当還元|少数株主[^。]{0,8}(評価|株価|値段)/, head:"配当還元方式は、経営に関わらない少数の株主が受け取る株を、配当をもとに評価する方法です。", body:"取引相場のない株は、受け取る人が会社を支配する立場の同族株主かどうかで評価の方法が変わります。同族株主以外など、配当を受け取るために株を持つ立場の人が取得する株は、過去の配当の額をもとにした配当還元方式で評価するのが原則です。どちらに当たるかは、持ち分と親族の関係で細かく決まります。", acts:["株主名簿で、誰がどれだけ持っているかと、社長との関係を確かめていただく", "株を渡す相手が評価のうえでどちらの立場に当たるかは、顧問の税理士に確かめていただく", "従業員持株会などで株を持つ方の評価の考え方として説明する"], actHead:"現場で使うなら", note:"どの方法で評価するかと税の扱いは税理士の業務。判定の決まりは国税庁の財産評価基本通達と顧問の税理士で確かめる。", pre:1, say:"同じ会社の株でも、受け取る方の立場によって評価の方法が変わります。誰に渡すかで変わるので、顧問の先生と一緒に確かめておきませんか。", more:"よくある勘違いは、株の評価は会社ごとに一つの額だと考えることです。同じ株でも、後継者が受け取る場合と、社員や遠い親族が受け取る場合では評価の方法が違うことがあります。株を誰に渡すか、渡したあとの持ち分がどうなるかで判定が変わるので、渡す前に確かめます。", why:"会社を支配する株主にとって株は会社そのものの値打ちですが、経営に関わらない少数の株主にとっては、主に配当を受け取る手段だと考えられているためです。" },
      { key:'faq_xjsk_kibo', faq:1, grp:'jsk', q:"会社の規模で自社株の評価は変わる？", re:/(大会社|中会社|小会社)[^。]{0,10}(区分|評価|株|違い)|(会社|自社)の規模[^。]{0,10}(評価|株|区分|決ま|変わ)/, head:"自社株の評価は、従業員の数・資産の額・取引の金額で会社を大・中・小に分け、方法の重みが変わります。", body:"取引相場のない株を評価するとき、会社を従業員の数、総資産の額、1年の取引の金額で大会社・中会社・小会社に分けます。大きな会社ほど同じ業種の上場会社と比べる方法の重みが大きく、小さな会社ほど会社の純資産から計算する方法の重みが大きくなります。業種によって区分の基準も違います。", acts:["決算書で、従業員の数・総資産・売上がどのくらいかを社長と見る", "どの区分に当たり、それで評価がどう変わるかは、顧問の税理士に確かめていただく", "会社が大きくなると評価の方法も変わることを、承継の計画と並べてお伝えする"], actHead:"現場で使うなら", note:"区分の基準と評価の計算は、国税庁の財産評価基本通達と顧問の税理士で確かめる。こちらでは区分を決めつけない。", pre:1, say:"会社の大きさによって、株の評価の方法の重みが変わる決まりがあります。会社が育つと評価の形も変わるので、顧問の先生と一度確かめておきませんか。", more:"よくある勘違いは、規模の区分が資本金で決まると考えることです。実際は従業員の数・総資産・取引の金額で決まり、業種で基準が違います。人を増やしたり売上が伸びたりして区分が変わると、評価の方法の重みも変わるので、承継の計画では会社の成長の見込みも並べます。", why:"大きな会社は上場会社に近い姿なので上場会社と比べる方法が合い、小さな会社は個人の財産に近い姿なので財産から測る方法が合う、という考え方で決まりが作られているためです。" },
      { key:'faq_xjsk_tokutei', faq:1, grp:'jsk', q:"株式保有特定会社・土地保有特定会社とは？", re:/(株式|株式等|土地)保有特定会社|特定の評価会社|(土地|不動産|株)を(たくさん|多く)持つ会社[^。]{0,10}(評価|株価)/, head:"財産の多くが株や土地の会社などは、特定の評価会社として、普通と違う方法で株を評価します。", body:"会社の財産に占める株や土地の割合が高い会社、開業して間もない会社、配当・利益・純資産が一定の形に当たる会社などは、特定の評価会社とされます。その場合は、同じ業種の上場会社と比べる方法を原則として使えず、会社の純資産から計算する方法で評価するのが基本です。当たるかどうかは割合などの基準で決まります。", acts:["会社の財産のうち、株や土地がどれだけを占めるかを決算書で見る", "特定の評価会社に当たるかは、顧問の税理士に確かめていただく", "持株会社や不動産を多く持つ会社の承継では、この決まりがあることを入口としてお伝えする"], actHead:"現場で使うなら", note:"当たるかどうかの基準と評価の計算は、国税庁の財産評価基本通達と顧問の税理士で確かめる。こちらでは判定しない。", pre:1, say:"会社の財産の中身によって、株の評価の方法が普通と違う決まりがあります。当たるかどうかは顧問の先生に確かめていただくのが確かです。", more:"場面の例としては、本業のほかに不動産を多く持つ会社や、子会社の株を持つ持株会社です。こうした会社は上場会社と比べにくいので、財産から評価する形になります。よくある勘違いは、財産の中身を変えれば判定がすぐ変わると考えることで、評価の前に財産を入れ替えた場合の扱いにも決まりがあります。", why:"財産の多くが株や土地の会社は、事業で稼ぐ会社というより財産を持つ器に近く、上場会社と比べる方法では値打ちを正しく測りにくいと考えられているためです。" },
      { key:'faq_xjsk_taishoku_kabu', faq:1, grp:'jsk', q:"社長の退職金を払うと自社株の評価はどうなる？", re:/(退職金|退職慰労金)[^。]{0,12}(株価|株の評価|自社株)|(株価|自社株|株の評価)[^。]{0,12}(退職金|退職慰労金)/, head:"退職金を払うと、その期の会社の利益と純資産が減るので、自社株の評価が動くことがあります。", body:"自社株の評価には、会社の利益や純資産の数字が使われるので、大きな退職金を払った期は数字が下がり、評価が動くことがあります。株を渡す時期と退職金を払う時期の並べ方は、承継の計画の中で顧問の税理士と考えるものです。退職金の額には、不相当に高い部分が損金に入らない決まりもあります。", acts:["社長が退く時期と、株を渡す時期の予定を一枚に並べる", "退職金の財源と額の考え方は、規程と顧問の税理士に確かめていただく", "評価の動きは、顧問の税理士の試算で確かめる流れをお伝えする"], actHead:"現場で使うなら", note:"評価の計算と退職金の税の扱いは税理士の業務。評価を下げる目的で退職金や保険を勧めない。規程と決議の手続きは弁護士・司法書士にも確かめる。", pre:1, say:"退職金をいつお支払いになるかで、会社の数字や株の評価が動くことがあります。株を渡す時期と並べて、顧問の先生と一緒に考えておきませんか。", more:"よくある勘違いは、評価を下げるために退職金を多く払えばよいと考えることです。額は規程と社長の働きに見合うものであることが求められ、払ったあとの会社の資金繰りも苦しくなります。評価が動くのは数字の結果であって、承継の目的は会社を続けることだと、話の順番を守ります。", why:"自社株の評価は決算の数字をもとに計算するので、会社から大きなお金が出た期には、もとになる利益や純資産が小さくなるためです。" },
      { key:'faq_xjsk_taisaku', faq:1, grp:'jsk', q:"社長に自社株の株価対策を聞かれたら？", re:/(株価|自社株|株の評価|株式の評価)[^。]{0,8}(対策|を下げ|下げる|引き下げ)|自社株対策|株価対策/, head:"株価対策の相談は、承継の計画の中で、顧問の税理士と一緒に考えるものとして受けます。", body:"自社株の評価は、利益や財産の数字、会社の規模や形で変わるので、退職金の支払いや会社の組み直しで評価が動くことはあります。ただし評価を下げることだけを目的に動くと、会社の体力や後継者の経営に響き、税の上でも認められないことがあります。こちらは保険を評価の道具として勧めず、承継の計画の順番を整える役に回ります。", acts:["株価を下げたい理由（誰に・いつ・どう渡したいか）を先に伺う", "評価の試算と対策の良し悪しは、顧問の税理士に確かめていただく", "保険は、納めるお金や退職金の財源など、計画の中の役目で説明する"], actHead:"現場で使うなら", note:"評価と税の判断は税理士の業務。評価を下げることを目的に保険を勧めない。会社法の手続きは弁護士・司法書士に確かめる。", pre:1, say:"株価の前に、どなたに・いつ頃・どう渡したいかを伺えますか。そこが決まると、顧問の先生と考える対策の順番も決まります。", more:"よくある勘違いは、評価が下がれば承継は全て片づくと考えることです。評価が下がっても、ほかのご家族への分け方、後継者の議決権、借入の保証は別に残ります。業績を落としてまで評価を下げれば、後継者が受け継ぐ会社そのものが弱くなります。保険で利益を消すような話にもしません。", why:"自社株の評価は税の計算のための値で、会社を良くする目的とは別のものだからです。評価だけを見て動くと、承継のほかの課題が置き去りになり、税の上でも行き過ぎた動きは認められないことがあるためです。" },
      { key:'faq_xjsk_meigi', faq:1, grp:'jsk', q:"名義株とは？", re:/名義株|名義だけの株主|株主名簿に[^。]{0,8}(知らない|昔の|名前だけ)/, head:"名義株は、株主名簿の名前と、実際にお金を出した持ち主が違う株のことです。", body:"昔の会社の設立には何人もの発起人が要った時代があり、親族や知人の名前を借りて株を持ってもらった会社があります。名義の人が亡くなると、その相続人が株主だと主張したり、相続の財産に誰の株として入るかが問題になったりします。実際の持ち主を確かめ、名義を整える手続きが要ります。", acts:["株主名簿と法人税の申告書の株主の一覧を、社長と一緒に見る", "名前だけの株主がいないか、設立のときの事情を社長に伺う", "名義を整える手続きは、弁護士・司法書士・税理士に確かめていただく"], actHead:"現場で使うなら", note:"誰の株かの判断と手続きは弁護士・司法書士、相続と贈与の税は税理士の業務。こちらでは持ち主を判断しない。", pre:1, say:"株主名簿に、昔お名前を借りた方が残っていないか、一度確かめてみませんか。承継の前に整えておくと、あとの手続きが楽になります。", more:"場面の例としては、設立のときに親戚や社員の名前を借り、そのままになっている会社です。名義の人やその相続人と話をして名義を整えますが、時間がたつほど事情を知る人が少なくなります。よくある勘違いは、配当を払っていないから問題が無いと考えることで、承継や相続の場面で表に出ます。", why:"株主の権利は名簿の名前で扱われるので、実際の持ち主と違うと、議決権や相続のときに誰の株かが争いになりやすいためです。事情を知る人が元気なうちに整えると、確かめやすくなります。" },
      { key:'faq_xjsk_bunsan', faq:1, grp:'jsk', q:"自社株が親族に分散していると何が困る？", re:/(株|自社株|株式)[^。]{0,6}(分散|ばらばら|散らば)|(分散|ばらばら)[^。]{0,6}(株|株主)/, ng:/分散投資|投資信託|nisa|ideco/, head:"株が分散していると、大事なことを決める議決権が集まらず、承継が進めにくくなります。", body:"会社の大事なことは株主総会で決め、議決権の多くを持つ人が経営を左右します。株が親族や元の社員に分かれていると、後継者が持つ議決権が足りず、定款の変更や役員の選び方で思うように決められないことがあります。相続のたびにさらに分かれていくので、誰がどれだけ持つかを早めに確かめます。", acts:["株主名簿で、株主ごとの持ち分と、社長との関係を書き出していただく", "後継者に集めたい持ち分の目安と、そのための道を、弁護士・税理士に確かめていただく", "分散した株を集めるお金の備えとして、保険がどの役に立つかを分けて説明する"], actHead:"現場で使うなら", note:"議決権と株の集め方の法律上の判断は弁護士、評価と税は税理士、登記は司法書士の業務。こちらでは持ち分の目安を言い切らない。", pre:1, say:"株を誰がどれだけお持ちかで、後継者の方が決められることが変わります。一度、株主の一覧を一緒に確かめてみませんか。", more:"場面の例としては、創業者の兄弟や、既に辞めた役員が株を持ち続けている会社です。持ち主が亡くなると、その相続人に分かれ、連絡もつきにくくなります。よくある勘違いは、少しの株なら影響が無いと考えることで、一定の持ち分があれば帳簿を見る権利などもあり、決め方によっては少数の持ち分が重みを持ちます。", why:"株主総会で決める事柄には、議決権の過半数や、より多くの賛成が要るものがあり、後継者の持ち分が足りないと会社の大事なことを一人で決められないためです。" },
      { key:'faq_xjsk_atsumeru', faq:1, grp:'jsk', q:"株を後継者に集めるにはどうする？", re:/(株|自社株|株式)[^。]{0,8}(後継者|跡継ぎ|後継ぎ)[^。]{0,6}(に集め|に移|に渡す方法|に集約|へ移)|(後継者|跡継ぎ|後継ぎ)に[^。]{0,4}(株|自社株)を[^。]{0,4}(集め|移す|渡す方法|集約)/, head:"株を後継者に集める道は、贈与・売買・遺言による相続・会社の買い取りに分かれます。", body:"生前に渡すなら贈与か売買、亡くなったあとなら遺言による相続が基本で、ほかの株主の株を会社が買い取る形もあります。贈与は受け取る側に贈与税、売買は買うお金と売る側の税、相続は相続税と遺留分が関わります。事業承継税制や民法の特例が使えることもあり、どの組み合わせにするかは専門家と決めます。", acts:["社長の持ち分と、ほかの株主の持ち分を株主名簿で確かめていただく", "贈与・売買・遺言・会社の買い取りの違いを一枚に並べてお見せする", "どの組み合わせにするかは、顧問の税理士と弁護士を交えて決めていただく"], actHead:"現場で使うなら", note:"渡し方ごとの税は税理士、遺言・遺留分・会社法の手続きは弁護士、登記は司法書士の業務。こちらでは渡し方を決めない。", pre:1, say:"株の渡し方にはいくつかの道があり、税や手間がそれぞれ違います。どの組み合わせが合うかは、顧問の先生とご一緒に決めていただくのが確かです。", more:"よくある勘違いは、遺言を書いておけば株の承継は済むと考えることです。遺言で後継者に株を残しても、ほかの相続人の取り分の問題や、相続税を納めるお金の問題が残ります。生前に少しずつ渡す、会社が買い取る、と組み合わせることもあり、その順番と時期を承継の計画に書きます。", why:"株は会社の経営を決める権利でもあるので、後継者に議決権を集めないと経営が安定しにくいためです。渡し方ごとに、受け取る人・渡す人・会社にかかる税と手続きが違うので、組み合わせて考えます。" },
      { key:'faq_xjsk_uriwatashi', faq:1, grp:'jsk', q:"相続人等に対する売渡請求とは？", re:/売渡請求|売渡しを(求め|請求)|売り渡し請求/, head:"売渡請求は、相続などで株を受け取った人に、会社がその株を売るよう求められる定款の定めです。", body:"株を譲るのに会社の承認が要る会社では、定款に定めておけば、相続などで株を受け取った人に、会社へ売り渡すよう求められます。求めるたびに株主総会の決議が要り、求められる期間と、会社が買い取れるお金の範囲にも決まりがあります。値段は話し合いで決め、まとまらなければ裁判所が決めます。", acts:["定款に売渡請求の定めがあるかを、社長に確かめていただく", "定めを入れるか、入れたときに起こりうることは、弁護士・司法書士に確かめていただく", "買い取るお金の備えとして、会社の手元資金や保険がどの役に立つかを分けて話す"], actHead:"現場で使うなら", note:"定めの入れ方と使うときの法律上の判断は弁護士・司法書士、株の値段と税は税理士に確かめる。", pre:1, say:"相続で株がばらばらにならないように、会社が買い取れる定めを定款に置く方法があります。使い方に注意が要るので、弁護士の先生に一度確かめてみませんか。", more:"注意が要るのは、社長が亡くなったときに、後継者が受け継いだ株にもこの定めが使われうることです。その決議では、求められる側は議決権を使えないので、ほかの株主の持ち分によっては、後継者が株を手放すよう求められる形が起こりえます。定めを入れる前に、株主の顔ぶれと持ち分で確かめます。", why:"株を譲るのに承認が要る会社でも、相続で株が移るときは承認が要らないため、会社にとって望まない人が株主になることを防ぐ手段として、会社法が用意している定めだからです。" },
      { key:'faq_xjsk_joutoseigen', faq:1, grp:'jsk', q:"株の譲渡制限とは？", re:/譲渡制限|(自社株|株)を勝手に(売|譲)/, head:"譲渡制限は、株を人に譲るときに会社の承認が要る、と定款で決めておく仕組みです。", body:"多くの中小企業は、知らない人が株主にならないよう、株の譲渡に会社の承認が要る定めを置いています。承認する機関は定款で決め、株主総会や取締役会などです。ただし相続や合併で株が移るときは承認が要らないので、相続で株が分かれるのを防ぐには、別の定めや準備が要ります。", acts:["定款と登記簿で、株の譲渡制限の定めがあるかを確かめていただく", "相続で株が移るときは承認が要らないことを、承継の話の入口でお伝えする", "株の移し方の手続きは、弁護士・司法書士に確かめていただく"], actHead:"現場で使うなら", note:"定款の定めと手続きの法律上の判断は弁護士、登記は司法書士の業務。こちらでは定款の解釈をしない。", pre:1, say:"株を譲るときに会社の承認が要る定めがあっても、相続で株が移るときは止められません。承継の前に、定款の中身を一度確かめておきませんか。", more:"よくある勘違いは、譲渡制限があれば相続でも株が勝手に移らないと考えることです。相続では承認なしに相続人へ移るので、相続した人から会社が株を買い取れる定めを置く会社もあります。譲渡制限は登記簿にも載るので、定款が見つからないときは登記簿から確かめられます。", why:"中小企業では、株主が誰かで経営が大きく変わるので、会社の知らない人に株が渡らないよう、会社法が譲るときの承認の仕組みを認めているためです。相続は本人の意思で譲るのとは違うので、承認の対象から外れています。" },
      { key:'faq_xjsk_kinko', faq:1, grp:'jsk', q:"会社が自社株を買い取る（金庫株）とは？", re:/金庫株|自己株式|(自社株|株)を会社[^。]{0,4}(に|が)[^。]{0,4}(買い取|買取|売)/, head:"金庫株は、会社が自社の株を株主から買い取って持つことで、会社のお金の範囲内でしかできません。", body:"会社が株主から自社の株を買い取るには、株主総会の決議などの手続きが要り、買い取れる額は会社の分配できるお金の範囲に限られます。売った株主の側では、受け取ったお金の一部が配当とみなされ、税の扱いが重くなることがあります。相続で受け継いだ株を、決まった期間のうちに会社へ売るときは、税の扱いの特例があります。", acts:["株の買い取りを考えている株主と、会社の手元のお金・分配できる額を、顧問の税理士に確かめていただく", "相続のあとに会社が株を買い取る場合の資金の備えを、承継の計画に書き込む", "手続きと税の扱いは、弁護士と税理士に確かめていただく"], actHead:"現場で使うなら", note:"手続きの法律上の判断は弁護士、買い取れる額と税の扱い・特例の期限は税理士と国税庁の公表資料で確かめる。", pre:1, say:"会社が株を買い取る形もありますが、会社のお金の範囲や税の扱いに決まりがあります。顧問の先生に、会社の数字と並べて確かめていただくのが確かです。", more:"場面の例としては、社長が亡くなり、継がないご家族が相続した株を会社に買い取ってほしいという形です。会社にまとまったお金が要るので、社長にかけた保険の保険金を会社が受け取り、買い取りの資金に充てる考え方もあります。よくある勘違いは、会社に預金があればいくらでも買えると考えることです。", why:"会社が株主にお金を返すと、会社の財産が減り、取引先や貸し手を害するおそれがあるので、会社法が買い取れる額に上限を設けているためです。税の上では、会社に積み上がった利益を受け取るのと同じ面があるので、配当とみなす扱いになります。" },
      { key:'faq_xjsk_hd', faq:1, grp:'jsk', q:"承継のために持株会社を作る話をされたら？", re:/持株会社|持ち株会社|ホールディングス|hd化/, head:"持株会社の話は、会社の形を変える目的を先に確かめ、税と法律の判断は専門家に任せます。", body:"持株会社は、事業をする会社の株を持つための会社で、株の交換や移転、会社の分割などの手続きで作ります。承継では、いくつかの事業をまとめる、後継者が持株会社の株を持つ、といった形で使われます。作ると評価の方法が変わることがあり、特定の評価会社に当たる場合もあるので、目的と手続きを専門家と確かめます。", acts:["持株会社を作りたい理由（経営の形・事業の整理・株の渡し方）を社長に伺う", "評価と税の扱いは顧問の税理士、手続きは弁護士・司法書士に確かめていただく", "会社の形が変わったときの法人契約の保険の扱いは、保険会社に確かめる"], actHead:"現場で使うなら", note:"組織の組み直しの税と評価は税理士、会社法の手続きは弁護士・司法書士の業務。こちらでは作るかどうかを勧めない。", pre:1, say:"持株会社にするかどうかは、会社の形をどうしたいかで決まる話です。税と手続きは顧問の先生と確かめていただき、保険の扱いはこちらで確かめます。", more:"よくある勘違いは、持株会社にすれば承継の税の心配が無くなると考えることです。評価の方法が変わる、手続きに費用と時間がかかる、会社が増えて管理が重くなる、といった面もあります。税の目的だけで組み直すと、税の上で認められない扱いになることもあるので、経営の目的を先に置きます。", why:"持株会社は、会社の持ち主と事業を分けて整理する仕組みで、承継のためだけの道具ではないためです。作ることで評価や税、法人契約の扱いが変わるので、目的を先に決めないと、思わぬ負担が残ることがあります。" },
      { key:'faq_xjsk_mochikabukai', faq:1, grp:'jsk', q:"従業員持株会とは？", re:/(従業員|社員)持株会|(従業員|社員)持ち株会/, head:"従業員持株会は、社員がお金を出し合って自社の株を持ち、配当を受け取る仕組みです。", body:"多くは社員が積み立てたお金で会社の株を持つ組合の形で作られ、規約で入り方や辞めたときの株の扱いを決めます。承継では、社長の株の一部を持株会に移して、後継者に集める株を整理する形に使われることがあります。持株会が持つ株にも議決権があるので、持ち分と議決権の扱いを先に決めておきます。", acts:["持株会の規約で、辞めたときの株の扱いと値段の決め方を確かめていただく", "承継の計画の中で持株会を使う目的を、社長と顧問の税理士に確かめていただく", "社員の方への説明は、会社の役員から行うものとしてお伝えする"], actHead:"現場で使うなら", note:"規約と株の扱いの法律上の判断は弁護士、評価と税は税理士の業務。社員への説明と勧め方は会社が決める。", pre:1, say:"社員の方が株を持つ持株会という仕組みがあります。承継にどう使うかは、規約と税の扱いを顧問の先生と確かめてから考えるものです。", more:"よくある勘違いは、持株会に株を移せば議決権の心配が無くなると考えることです。持株会の株にも議決権があり、規約で扱いを決めておかないと、後継者の経営に響くことがあります。議決権を持たない種類の株を持株会に持ってもらう形もあり、その場合は定款の変更が要ります。", why:"社員が株を持つと、会社の業績が自分の配当につながり、経営に関わる気持ちが育つ面があるためです。一方で株主が増えるので、辞めた社員の株の扱いや議決権を決めておかないと、株が分散する原因にもなります。" },
      { key:'faq_xjsk_kojinban', faq:1, grp:'jsk', q:"個人事業主にも事業承継税制はある？", re:/個人版事業承継税制|個人(事業|事業主)[^。]{0,10}(事業承継税制|納税猶予)|事業用資産[^。]{0,10}納税猶予/, head:"個人事業にも、事業用の土地や建物・機械などの相続税・贈与税を猶予する特例があります。", body:"個人事業者が事業で使う土地・建物・機械などを、後継者が贈与や相続で受け継いだとき、要件を満たせば納税が猶予される、個人版の事業承継税制があります。先に承継の計画を都道府県に出すことや、適用の期限があります。事業用の宅地の評価の特例とは一緒に使えない決まりがあり、どちらを使うかは税理士と決めます。", acts:["事業で使っている土地・建物・機械の一覧と、名義を確かめていただく", "個人版の特例と宅地の特例のどちらを使うかは、顧問の税理士に確かめていただく", "計画の提出と期限があることを、早めの相談の理由としてお伝えする"], actHead:"現場で使うなら", note:"使えるかどうか・要件・期限は、税理士と国税庁・都道府県の公表資料で最新を確かめる。こちらでは結論を言い切らない。", pre:1, say:"個人で事業をされている方にも、事業用の財産を継ぐときの税の特例があります。計画の提出や期限があるので、顧問の先生に早めに確かめておきませんか。", more:"よくある勘違いは、会社にしていないと承継の特例は使えないと考えることです。個人版の特例は、事業で使う財産が対象で、自宅など事業に使っていないものは対象外です。後継者が事業を続ける、報告を出すといった要件があり、外れると猶予された税を納めることになるのは会社の特例と同じです。", why:"個人事業では、事業用の財産が事業主個人の財産なので、相続や贈与の税のために手放すと事業が続かなくなるためです。会社の株の特例と同じ考え方で、事業を続けることを条件に納める時期を待つ形にしています。" },
      { key:'faq_xjsk_zeisei_hoken', faq:1, grp:'jsk', q:"事業承継税制を使えば保険は要らない？", re:/(事業承継税制|納税猶予)[^。]{0,12}(保険|要らない|いらない)/, head:"事業承継税制は株の税を待つ仕組みで、保険が受け持つお金の役目は別に残ります。", body:"猶予の対象は後継者が受け継いだ株の税で、株のほかの財産にかかる税、ほかのご家族への分け方、猶予が打ち切られたときに納めるお金、社長が亡くなったあとの会社の資金繰りは別に残ります。保険は、こうした場面のお金を、受け取る人を決めて用意する手段の一つです。どこまで備えるかは、承継の計画と並べて考えます。", acts:["特例でまかなえる部分と、残るお金の場面を一枚に分けて書き出す", "残る場面ごとに、誰の手元にいつお金が要るかを並べる", "税の特例の当てはまりは、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"特例の当てはまりと税額は税理士の業務。保険で備えるかどうかは社長が決めること。こちらでは保険が要ると言い切らない。", pre:1, say:"税の特例で待ってもらえるのは株の税で、ほかに残るお金の場面があります。その場面に備えが要るかどうかを、ご一緒に並べてみませんか。", more:"場面の例としては、特例で株の税は猶予されても、継がないお子様に渡す財産が足りず、取り分の話でもめる形です。社長が急に亡くなると、取引先や金融機関の受け止めで会社の資金繰りが苦しくなることもあります。よくある勘違いは、特例を使えば相続のお金の心配が全て無くなると考えることです。", why:"税の特例は事業を続けるための株の税の扱いを決めた仕組みで、ご家族の取り分や会社の資金繰りまでは受け持たないためです。" },
      { key:'faq_xjsk_zeisei_uchikiri', faq:1, grp:'jsk', q:"事業承継税制の猶予が打ち切られるのはどんなとき？", re:/(事業承継税制|納税猶予)[^。]{0,10}(打ち切|取り消|取消|外れ|やめたら)/, head:"後継者が代表を退く、株を手放す、会社を閉じるなど、要件を外れると猶予が打ち切られます。", body:"猶予は、後継者が会社の代表を続け、受け継いだ株を持ち続け、決まった報告を出し続けることが前提です。代表を退いたり、株を譲ったり、会社が解散したり、報告を出さなかったりすると、猶予が打ち切られ、猶予されていた税を利子とともに納めることになります。打ち切りになる事柄と、一部だけを納める場合などの細かな決まりは、措置ごとに違います。", acts:["猶予を受けている会社か、これから使う会社かを先に伺う", "打ち切りになる場面を、後継者の働き方・株の扱い・会社の将来と並べて確かめていただく", "打ち切られたときに納めるお金の備えを、承継の計画の中で話す"], actHead:"現場で使うなら", note:"打ち切りの事柄と納める額は、税理士と国税庁の公表資料で確かめる。こちらでは個別の当てはまりを判断しない。", pre:1, say:"この特例は、後継者の方が会社を続ける間の猶予なので、途中で事情が変わると納めることになります。そのときの備えも、承継の計画に入れておきませんか。", more:"場面の例としては、猶予を受けた後継者が体を壊して代表を退く、会社を売る、といった形です。事情によっては猶予が続く場合や、一部だけを納める場合もあり、判断は税理士に確かめます。よくある勘違いは、打ち切られても元の税だけで済むと考えることで、猶予の間の利子もかかります。", why:"事業を続けることを条件に納める時期を待つ仕組みなので、その条件が崩れたら、待っていた税を納めてもらう形になっているためです。利子は、納める時期を待っていた間の分としてかかります。" },
      { key:'faq_xjsk_zeisei_nagare', faq:1, grp:'jsk', q:"事業承継税制を使う流れは？", re:/(事業承継税制|納税猶予)[^。]{0,8}(流れ|手順|手続き|順番|使うには|申請|認定)/, head:"流れは、計画と認定を都道府県で、申告を税務署で行い、そのあとも報告を続けます。", body:"特例の措置では、先に承継の計画を都道府県に出して確認を受け、贈与や相続のあとに都道府県知事の認定を申請し、税務署に申告して猶予を受けます。猶予の税額に見合う担保を出すことも要ります。そのあとも決められた時期ごとに、都道府県と税務署へ報告や届け出を続けます。計画の提出や適用には期限があり、見直しが続いています。", acts:["使うかどうかを決める前に、手続きを任せる顧問の税理士がいるかを伺う", "都道府県と税務署の両方に手続きがあることを、一枚の流れ図でお見せする", "報告を続ける担当を、会社の中で決めておくことをお伝えする"], actHead:"現場で使うなら", note:"手続きの様式・期限・要件は、都道府県の窓口・中小企業庁・国税庁の公表資料と税理士で確かめる。期限は改正で変わる。", pre:1, say:"この特例は、使い始めてからも報告を続ける手続きがあります。顧問の先生と、誰がいつ何を出すかを決めてから進めるのが安心です。", more:"よくある勘違いは、一度申告すれば終わりと考えることです。報告や届け出を出し忘れると猶予が打ち切られることがあるので、会社の中で担当と時期を決めておきます。一般の措置では先の計画の提出は要らないなど、措置によって手続きが違うので、どちらを使うかも税理士と決めます。", why:"猶予は、後継者が事業を続けていることを前提にした仕組みなので、国が事業の様子と株の持ち方を確かめ続ける必要があるためです。" },
      { key:'faq_xjsk_zeisei', faq:1, grp:'jsk', q:"事業承継税制とは？", re:/事業承継税制|(自社株|非上場株|非上場株式)[^。]{0,10}納税猶予|納税猶予[^。]{0,10}(自社株|非上場株|事業承継)/, head:"事業承継税制は、後継者が受け継いだ自社株にかかる相続税・贈与税の納税を猶予する仕組みです。", body:"後継者が先代から贈与や相続で非上場の会社の株を受け継いだとき、都道府県知事の認定を受けるなどの要件を満たせば、その株にかかる税の納税が猶予され、後継者が亡くなったときなどに免除されます。いつでも使える一般の措置と、期限を区切って要件を広げた特例の措置があり、期限や要件は改正が続いています。", acts:["税の特例を使えるかどうかは、顧問の税理士に確かめていただく流れを最初にお伝えする", "猶予の間も報告と要件を守り続けることを、社長と後継者に説明する", "猶予が打ち切られたときの納めるお金の備えを、承継の計画の中で考える"], actHead:"現場で使うなら", note:"使えるかどうか・要件・期限は、税理士と国税庁・中小企業庁・都道府県の公表資料で最新を確かめる。こちらでは税額と結論を言い切らない。", pre:1, say:"自社株の税には、後継者が会社を続ける間、納めるのを待ってもらえる国の特例があります。使えるかどうかは顧問の先生に確かめていただくのが確かです。", more:"よくある勘違いは、税が初めから免除される制度だと考えることです。基本は猶予で、後継者が代表を続ける、株を持ち続けるといった要件を守り、決まった報告を出し続けることが前提です。要件を外れると、猶予された税を利子とともに納めることになります。株のほかの財産や、ほかのご家族の取り分は対象外です。", why:"株が財産の多くを占める中小企業では、相続や贈与の税を納めるために株を手放したり、会社のお金を抜いたりすると、事業が続けにくくなるためです。事業を続けることを条件に、納める時期を待つ形にしています。" },
      { key:'faq_xjsk_iryu_tokurei', faq:1, grp:'jsk', q:"遺留分の民法特例（除外合意・固定合意）とは？", re:/除外合意|固定合意|遺留分[^。]{0,8}(民法の特例|特例|計算から外|除外|算定から)/, head:"民法の特例は、後継者が受け取った自社株を、遺留分の計算から外したり、価額を固定したりする合意です。", body:"経営承継円滑化法にもとづき、先代から後継者が贈与などで受け取った株について、遺留分の計算から外す除外合意と、計算に入れる価額を合意した時の額に固定する固定合意ができます。先代の推定相続人の全員の合意を書面にし、経済産業大臣の確認と家庭裁判所の許可を受けることが要ります。", acts:["推定相続人になる方を家系図で書き出し、全員の合意が要ることを社長にお伝えする", "合意の中身と手続きは、弁護士に確かめていただく", "合意が難しいときに、ほかのご家族へ渡すお金の備えを別に考える"], actHead:"現場で使うなら", note:"合意の要件と手続きの法律上の判断は弁護士の業務。経済産業省・中小企業庁の公表資料と、家庭裁判所の手続きで確かめる。", pre:1, say:"後継者の方が受け取る株を、ご家族の取り分の計算から外す合意の仕組みがあります。ご家族全員の合意が要るので、弁護士の先生と進め方を確かめてみませんか。", more:"よくある勘違いは、後継者と社長の二人で決められると考えることです。推定相続人の全員の合意が要り、一人でも反対すれば使えません。固定合意は、株を受け取ったあとに後継者の努力で評価が上がっても、その分を遺留分の計算に入れない形です。合意の話し合いそのものが、ご家族の承継の話し合いの場になります。", why:"後継者が会社を伸ばすほど株の評価が上がり、遺留分の額も大きくなると、後継者が経営に励む気持ちを損ない、株が分散するおそれがあるためです。ご家族全員の合意と国・裁判所の確認を条件に、例外を認めています。" },
      { key:'faq_xjsk_iryu_shiharai', faq:1, grp:'jsk', q:"後継者が遺留分を払うお金はどう用意する？", re:/遺留分[^。]{0,10}(払う|支払|お金|資金|用意|現金)/, head:"遺留分は原則としてお金で払うので、株を継ぐ後継者の手元にお金が来る形を前もって考えます。", body:"いまの決まりでは、遺留分を求められると、原則としてお金で払います。株や事業用の土地を受け継いだ後継者は、財産はあっても手元のお金が少ないことが多く、払うお金の用意が問題になります。用意の道は、後継者の預貯金、借入、死亡退職金の受け取り、後継者を受取人にした生命保険などで、組み合わせて考えます。", acts:["後継者が受け継ぐ財産と、ほかのご家族に渡る財産を一枚に書き出す", "遺留分の額のおおよそは、弁護士・税理士に確かめていただく", "後継者の手元にお金が来る道（受取人の指定など）を、選択肢として並べる"], actHead:"現場で使うなら", note:"遺留分の額と請求の扱いは弁護士、相続税は税理士の業務。死亡保険金が遺留分の計算に入るかの個別の判断も弁護士に確かめる。", pre:1, say:"株を継ぐ方は、財産はあっても手元のお金が少なくなりがちです。ほかのご家族に渡すお金をどこから用意するか、一緒に整理しておきませんか。", more:"死亡保険金は原則として受取人の財産で、遺留分の計算の元になる財産には入らないとされますが、額が大きく不公平が著しいときなどに例外の考え方もあります。後継者を受取人にして、受け取ったお金をほかのご家族に払う形を考えるときも、例外に当たらないかを弁護士に確かめます。", why:"遺留分を原則お金で払う決まりになったため、株や土地を分けずに後継者に残せる一方で、後継者が払うお金を用意できるかどうかが承継の課題として残るためです。" },
      { key:'faq_xjsk_yuigon', faq:1, grp:'jsk', q:"自社株を誰に渡すか遺言で決めておく意味は？", re:/(自社株|株)[^。]{0,10}遺言|遺言[^。]{0,10}(自社株|株の|会社の株)|社長[^。]{0,6}遺言/, ng:/自分の代|うちの代理店/, head:"遺言で株の行き先を決めておくと、社長が亡くなったときに株が共有のまま止まるのを避けやすくなります。", body:"遺言が無いと、株は相続人全員の共有になり、遺産分割の話し合いがまとまるまで、議決権を誰がどう使うかが定まりにくくなります。遺言で後継者に株を残すと決めておけば、経営の空白を小さくできます。ただし、ほかのご家族の遺留分や、相続税を納めるお金の問題は別に残ります。", acts:["遺言があるか、あればいつ作ったものかを社長に伺う", "遺言の種類と作り方は、弁護士・公証役場・司法書士に確かめていただく", "遺言で株を残すときの、ほかのご家族への分け方とお金の備えを並べる"], actHead:"現場で使うなら", note:"遺言の作り方と中身の法律上の判断は弁護士・公証役場、相続税は税理士の業務。こちらでは遺言の文を作らない。", pre:1, say:"株を誰に残すかを遺言で決めておくと、万一のときに会社の決めごとが止まりにくくなります。作り方は弁護士の先生や公証役場に確かめていただくのが確かです。", more:"よくある勘違いは、社長が元気なうちは遺言は要らないと考えることです。社長が急に亡くなると、株の行き先が決まるまで役員の選び方も定まりにくくなります。遺言は書き直せるので、承継の計画が変わったら見直します。遺言とあわせて、ご家族にその考えを伝えておくと、あとの話し合いが穏やかになります。", why:"株は遺産の一つとして相続人の共有になり、共有の株の議決権は代表して使う人を決めないと使えないため、行き先が決まっていないと会社の決めごとが滞るからです。" },
      { key:'faq_xjsk_kyuushi', faq:1, grp:'jsk', q:"社長が急に亡くなったら自社株はどうなる？", re:/(社長|代表|オーナー)[^。]{0,8}(急に|突然|急死)[^。]{0,10}(株|自社株)|株[^。]{0,4}(が|の)(共有|準共有)|株を共有|(相続人|遺族)[^。]{0,10}(議決権|株主総会)/, head:"社長が亡くなると、株は遺産分割まで相続人の共有になり、議決権を使う人を決めて会社に知らせます。", body:"相続人が何人かいると、遺言が無ければ株は遺産分割がまとまるまで共有になり、議決権は共有している人の中から代表して使う人を決めて、会社に知らせる必要があります。決まるまでは株主総会で新しい社長を選ぶことも進めにくく、会社の決めごとが滞ります。遺言や生前の株の移し方で、この空白を小さくできます。", acts:["社長に万一があったときに、株が誰に渡り、誰が議決権を使うかを一緒に書き出す", "遺言の有無と、株主名簿・定款の定めを確かめていただく", "経営の空白と資金繰りの備えを、承継の計画に書き込む"], actHead:"現場で使うなら", note:"共有の株の扱いと議決権の法律上の判断は弁護士、遺言は弁護士・公証役場、相続税は税理士の業務。こちらでは結果を言い切らない。", pre:1, say:"社長に万一があったとき、株が誰に渡り、誰が会社の決めごとをするかを、お元気なうちに決めておくと会社が止まりにくくなります。", more:"場面の例としては、遺言が無いまま社長が亡くなり、奥様とお子様の話し合いがまとまらず、新しい社長を選ぶ株主総会が開けない形です。その間も会社の支払いや取引は続くので、金融機関や取引先が先行きを心配します。代わりに会社を動かす役員がいるか、資金繰りのお金があるかも並べて確かめます。", why:"相続した株は相続人全員のものとして扱われ、会社に対して一つの声で議決権を使うために、代表して使う人を決める決まりになっているためです。" },
      { key:'faq_xjsk_ninchi', faq:1, grp:'jsk', q:"社長が認知症になったら会社はどうなる？", re:/(社長|経営者|代表|オーナー)[^。]{0,8}(認知症|判断能力|判断する力)/, head:"社長が判断できなくなると、株の議決権や会社の契約が止まりやすいので、元気なうちに備えます。", body:"社長が株の多くを持ったまま判断する力を失うと、株主総会で議決権を使えず、役員の選び直しや大事な決定が進めにくくなります。家庭裁判所が選ぶ成年後見人が付いても、本人の財産を守る立場で動くため、経営の判断を任せる形にはなりにくいとされます。元気なうちの備えとして、株を移しておく、任意後見の契約、信託、議決権の扱いを決める定款の定めなどがあります。", acts:["社長の持ち分と、代わりに会社を動かせる役員がいるかを確かめていただく", "元気なうちの備えの選択肢を並べ、中身は弁護士・司法書士に確かめていただく", "社長個人の財産の管理と、会社の経営の両方に分けて準備を考える"], actHead:"現場で使うなら", note:"成年後見・任意後見・信託・定款の法律上の判断は弁護士・司法書士の業務。税は税理士、病気の判断は医師に確かめる。", pre:1, say:"社長がお元気なうちに、判断が難しくなったときに会社を誰が動かすかを決めておく方法があります。弁護士の先生と、一度確かめておきませんか。", more:"よくある勘違いは、ご家族が代わりに議決権を使えると考えることです。本人の判断が難しくなると、ご家族でも代わりに株主として決めることはできず、手続きに時間がかかります。社長個人の保険の契約でも、代わりに請求できる人を決める手続きがあるかを、保険会社に前もって確かめておきます。", why:"株主の議決権も会社の契約も、本人の意思で使うものなので、判断する力を失うと誰も代わりに使えない空白が生まれるためです。後見の制度は本人の財産を守ることが目的で、会社の経営を前に進めるための仕組みとは役目が違います。" },
      { key:'faq_xjsk_ma_hoken', faq:1, grp:'jsk', q:"会社を売ったら法人契約の保険はどうなる？", re:/(会社を売|会社を譲|m&a|事業承継|譲渡)[^。]{0,12}(法人契約|法人の保険|社長の保険|会社の保険|保険の契約者)/, head:"株を売る形なら、法人契約の保険は会社のまま残り、契約の扱いは売買の条件で決めます。", body:"株式譲渡では会社そのものが続くので、会社が契約者の保険も残ります。被保険者の社長が退くと保険の目的が変わるので、解約する、契約者や受取人を変える、そのまま続ける、のいずれかを、買い手との条件の中で決めます。事業譲渡では、保険の契約は自動では移りません。どの扱いでも、税と経理の扱いを顧問の税理士に確かめます。", acts:["会社が契約している保険の一覧（目的・被保険者・解約返戻金）を、売る前に作る", "保険の扱いが売買の条件の一つになることを、社長と支援機関にお伝えする", "契約者や受取人を変える手続きと税の扱いは、保険会社と顧問の税理士に確かめる"], actHead:"現場で使うなら", note:"契約の変更の可否と手続きは保険会社、税と経理の扱いは税理士、売買の条件は弁護士・支援機関に確かめる。こちらで扱いを決めない。", pre:1, say:"会社を譲るときは、会社でかけている保険をどうするかも決めておく必要があります。一覧を作っておくと、話し合いがしやすくなります。", more:"場面の例としては、社長の退職金の財源として会社がかけていた保険を、譲る前に解約して退職金に充てる形や、契約者を社長個人に移す形です。どちらも税と経理の扱いが変わるので、顧問の税理士を交えます。よくある勘違いは、保険は社長個人のものだから会社を売っても関係ないと考えることです。", why:"法人契約の保険は会社の財産で、解約返戻金は会社の値打ちの一部として売買の値段にも響くためです。被保険者の社長が退くと契約の目的が変わるので、扱いを決めておく必要があります。" },
      { key:'faq_xjsk_jouto_chigai', faq:1, grp:'jsk', q:"株式譲渡と事業譲渡の違いは？", re:/事業譲渡|株式譲渡と|株を売るのと事業/, head:"株式譲渡は会社ごと持ち主が替わり、事業譲渡は会社が事業の一部や全部を売る形です。", body:"株式譲渡では、株主が株を売り、会社の契約・社員・借入はそのまま会社に残って持ち主だけが替わります。事業譲渡では、会社が事業の資産や契約を選んで売り、契約や社員の雇用は一つずつ移す手続きと相手の同意が要ります。売ったお金を受け取るのは、株式譲渡では株主、事業譲渡では会社で、税の扱いも違います。", acts:["売る形によって、社長の手元にお金が入るか、会社に入るかが違うことを並べて説明する", "法人契約の保険や借入・保証が、売る形でどう扱われるかを書き出す", "どちらの形にするかと税の扱いは、弁護士・税理士と支援機関に確かめていただく"], actHead:"現場で使うなら", note:"契約と手続きの法律上の判断は弁護士、税の扱いは税理士の業務。こちらではどちらが良いかを言わない。", pre:1, say:"会社を引き継ぐ形には、株を売る形と事業を売る形があり、お金を受け取る人や手続きが違います。どちらが合うかは、顧問の先生と相手との話し合いで決まります。", more:"よくある勘違いは、事業譲渡でも社員や取引先の契約が自動で移ると考えることです。一つずつ相手の同意を得て移す必要があり、許認可が引き継げない業種もあります。株式譲渡は手続きが少なくて済む一方、会社の古い借入や隠れた問題も一緒に引き継ぐので、買い手の調べが細かくなります。", why:"株式譲渡は会社の持ち主が替わるだけで会社そのものは同じなのに対し、事業譲渡は会社から別の会社へ財産と契約を移す取引だからです。この違いが、手続き・同意・税の扱いの違いになります。" },
      { key:'faq_xjsk_ma_soudan', faq:1, grp:'jsk', q:"M&Aは誰に相談すればいい？", re:/m&a[^。]{0,10}(相談|仲介|支援機関|登録制度|アドバイザー|どこに|誰に)/, head:"M&Aの相談先は、公的な窓口・登録された支援機関・顧問の税理士で、役目と費用を確かめて選びます。", body:"仲介の会社は売り手と買い手の両方の間に立ち、助言の会社は片方の立場で関わることが多く、手数料の決め方も会社ごとに違います。中小企業庁には中小M&Aのガイドラインと、支援機関の登録の制度があります。公的な事業承継の相談窓口では、相手探しの相談や専門家の紹介を受けられることがあります。", acts:["相談する前に、手数料の決め方と、売り手と買い手のどちらの立場で関わるかを確かめるよう伝える", "中小企業庁のガイドラインと登録の制度があることをお伝えする", "保険の契約や保証の整理は、こちらで一覧にしてお手伝いできることを伝える"], actHead:"現場で使うなら", note:"支援機関の選び方と契約は社長が決めること。契約の法律上の判断は弁護士、税は税理士、制度は中小企業庁の公表資料で確かめる。", pre:1, say:"M&Aの相談先はいくつかあり、手数料の決め方や関わる立場が違います。契約する前に、そこを確かめてから選ばれるのが安心です。", more:"よくある勘違いは、仲介の会社が売り手だけの味方だと考えることです。両方の間に立つ形では利益がぶつかる場面もあるので、ガイドラインでも説明が求められています。最初の契約で、相談の範囲・費用がかかる時期・途中でやめるときの扱いを書面で確かめます。", why:"M&Aは一度きりの大きな取引で、売り手の社長には相場や進め方が分かりにくいため、支援する側の役目や費用を見えるようにする決まりが、国によって整えられてきたためです。" },
      { key:'faq_xjsk_mbo', faq:1, grp:'jsk', q:"経営陣や社員が株を買い取る（MBO・EBO）とは？", re:/mbo|ebo|(役員|経営陣|社員|従業員)が[^。]{0,4}(会社|株)を[^。]{0,4}買い取/, head:"MBOは経営陣が、EBOは社員が、会社の株を買い取って引き継ぐ形です。", body:"会社をよく知る人が持ち主になるので、経営の考え方や取引先との関係を引き継ぎやすい形です。一方で、株を買うまとまったお金が要り、金融機関の融資や、出資してくれる相手と組むことがあります。社長の個人保証を誰が引き継ぐかも、金融機関と話します。", acts:["株を買うお金の道と、借入の返済の見込みを、金融機関と顧問の税理士に確かめていただく", "社長の個人保証の扱いを、取引の金融機関と早めに話す段取りを伝える", "引き継ぐ役員に万一があったときに、借入を返すお金がどうなるかも並べて考える"], actHead:"現場で使うなら", note:"株の値段と税は税理士、契約の法律上の判断は弁護士、融資と保証は金融機関に確かめる。こちらでは買い取りの形を勧めない。", pre:1, say:"役員や社員の方が株を買い取って継ぐ形もあります。買うお金と借入の返し方、保証の扱いを、金融機関も交えて一緒に整理しませんか。", more:"よくある勘違いは、会社をよく知る人ならお金の心配は無いと考えることです。買い取りのお金を借りると、引き継いだ人が返していくことになり、その人に万一があったときの返済の備えも考えます。株の値段は、売る社長と買う役員の間で利害がぶつかるので、評価の考え方を専門家に確かめます。", why:"株を買うには評価に見合うお金が要るのに、給与で暮らしてきた役員や社員には用意が難しく、借入や出資者を使う形になるためです。" },
      { key:'faq_xjsk_ma', faq:1, grp:'jsk', q:"M&Aで会社を引き継ぐとは？", re:/m&a|第三者承継|(社外|他社|第三者)[^。]{0,6}(に会社を|に事業を|へ会社を)(譲|売|引き継)|会社を売[^。]{0,6}(引退|承継|退き)/, ng:/自分の代|うちの代理店|自分の会社/, head:"M&Aによる承継は、後継者のいない会社を、社外の会社や人に引き継いでもらう道です。", body:"株を売る形と、事業を売る形があり、社員の雇用や取引先との関係を残しながら、社長が退くことができます。相手探し、会社の中身の調べ、条件の話し合い、契約、引き継ぎの順に進み、時間がかかります。社長の個人保証や、社長にかけた法人契約の保険の扱いも、条件の中で決めます。", acts:["社長が会社に残したいもの（社員・取引先・名前）と、退く時期の考えを伺う", "決算書・借入・保証・保険の契約を一覧にしておくと、調べに備えやすいことをお伝えする", "相談先として、公的な事業承継の相談窓口や登録された支援機関があることを伝える"], actHead:"現場で使うなら", note:"売買の条件と契約の法律上の判断は弁護士、税は税理士、仲介や助言は登録された支援機関。中小企業庁の公表資料と公的な相談窓口でも確かめる。", pre:1, say:"社外の方に引き継いでもらう道でも、社員の方や取引先との関係を残せることがあります。まずは会社に残したいものから伺えますか。", more:"よくある勘違いは、業績が良い会社しか引き継ぎ手が見つからないと考えることです。技術や取引先、地域のお客様を求める相手もいます。一方で、社長が退いたあともしばらく引き継ぎに関わる条件が付くことも多く、社長の予定と合わせて考えます。", why:"後継者のいない会社でも、事業そのものには値打ちがあり、引き継ぐ相手がいれば雇用や技術を残せるためです。社外の相手には会社の中身が見えないので、調べと話し合いに時間がかかります。" },
      { key:'faq_xjsk_hoshou', faq:1, grp:'jsk', q:"事業承継で社長の個人保証はどうなる？", re:/(承継|後継者|跡継ぎ|社長交代|代替わり)[^。]{0,12}(個人保証|経営者保証|連帯保証|保証)|(個人保証|経営者保証|連帯保証)[^。]{0,12}(承継|後継者|特則)/, head:"承継のときの個人保証は、金融機関と話して、引き継ぐ・外す・条件を変えるのいずれかを決めます。", body:"中小企業の借入には社長の個人保証が付いていることが多く、後継者が引き継ぐのをためらう理由になります。経営者保証に関するガイドラインには事業承継のときの決まりがあり、前の社長と新しい社長の両方から保証を取ることは原則として控え、保証が要るかを改めて考えるとされています。外せるかは、会社の財務の状況などで金融機関が判断します。", acts:["借入ごとに、誰が保証しているかを返済予定表と契約書で確かめていただく", "金融機関に、承継の予定と保証の扱いの相談を早めに持ちかける段取りをお伝えする", "保証が残る間に、保証している人に万一があったときの返済の備えも並べる"], actHead:"現場で使うなら", note:"保証の扱いは取引の金融機関が判断すること。ガイドラインの中身は金融庁・中小企業庁の公表資料、法律上の判断は弁護士に確かめる。", pre:1, say:"承継のときの保証の扱いには、金融機関向けの決まりもあります。まずは借入ごとの保証を一覧にして、金融機関に早めに相談してみませんか。", more:"よくある勘違いは、社長が退けば保証も自動で外れると考えることです。前の社長の保証は、外す話をしない限り残ります。会社の財務の状況が良く、経営と家計が分けられているほど、保証を外す話を進めやすいとされています。保証を付けない信用保証協会の承継向けの制度もあり、金融機関に確かめます。", why:"保証の重さが、後継者が承継をためらう大きな理由になっているため、国と金融の団体が、承継の場面での保証の扱いの決まりを作っているためです。" },
      { key:'faq_xjsk_bunshou', faq:1, grp:'jsk', q:"社長を退いて会長に残るときの退職金は？", re:/分掌変更|会長[^。]{0,14}(退職金|退職慰労金)|(退職金|退職慰労金)[^。]{0,10}会長/, head:"会長に残るときは、実質的に退いたと言える変化が無いと、退職金と認められないことがあります。", body:"役員のまま肩書きや役目が変わる場合、常勤から非常勤になる、報酬が大きく下がるなど、経営の立場が実質的に変わったと言えれば、退職金として扱われることがあります。会長になっても経営の判断を続けていると、退職金ではなく役員の給与と見られ、会社の損金に入らないおそれがあります。", acts:["会長になったあとの役目・勤め方・報酬の予定を、社長に書き出していただく", "退職金として扱えるかは、顧問の税理士に確かめていただく", "後継者に任せる範囲を決めることが、承継そのものの準備にもなるとお伝えする"], actHead:"現場で使うなら", note:"退職金として認められるかの判断は税理士の業務。決まりの細部は国税庁の法人税基本通達と顧問の税理士で確かめる。", pre:1, say:"会長として残られる場合は、退いたと言える変化があるかで退職金の扱いが変わります。会長になってからの役目を、顧問の先生と一緒に決めておきませんか。", more:"よくある勘違いは、肩書きを会長に変えれば退職金が払えると考えることです。退いたあとも取引先との交渉や大事な決定を続けていると、実質は社長のままと見られることがあります。後継者に経営の判断を任せることは、退職金の扱いのためだけでなく、後継者の育ちのためにも大事です。", why:"退職金は職を退いたことに対して払うもので、立場が実質的に変わっていないのに払うと、給与を退職金の形で払うのと同じになるためです。" },
      { key:'faq_xjsk_ougon', faq:1, grp:'jsk', q:"黄金株（拒否権付き株式）とは？", re:/黄金株|拒否権/, head:"黄金株は、株主総会などの決議に拒否権を持つ株で、一株でも大事な決定を止められます。", body:"定款で定めた事柄について、この株を持つ人の決議が無いと決められない、という形の種類株式です。承継では、後継者に株を渡したあとも、先代が黄金株を持って行き過ぎた判断を止める形に使われることがあります。持つ人が亡くなったり判断できなくなったりすると、会社の決定が止まるおそれがあり、扱いを先に決めておきます。", acts:["黄金株を持つ目的（後継者の見守り・会社を守る）を社長に伺う", "持つ人が亡くなった・判断できなくなったときの扱いを、弁護士・司法書士に確かめていただく", "黄金株が誰に相続されるかも、承継の計画に書いておく"], actHead:"現場で使うなら", note:"黄金株の設計と定款の法律上の判断は弁護士、登記は司法書士、評価と税は税理士の業務。こちらでは設計を勧めない。", pre:1, say:"後継者に株を渡したあとも、大事な決定を止められる株を持つ方法があります。持つ方に万一があったときの扱いも、一緒に決めておくことが大事です。", more:"よくある勘違いは、黄金株を持てば先代が安心とだけ考えることです。後継者から見ると、いつでも止められる重さがあり、関係が悪くなると会社が動かなくなります。会社が買い取れる定めを付けておくなど、手放すときの形も最初に決めておきます。", why:"拒否権は強い力なので、持つ人の判断に会社の行方が左右され、持つ人がいなくなったときの扱いが決まっていないと、決議が止まったままになるためです。" },
      { key:'faq_xjsk_zokujin', faq:1, grp:'jsk', q:"属人的株式とは？", re:/属人的株|株主ごとに[^。]{0,8}(議決権|配当|扱い)/, head:"属人的株式は、株を譲るのに承認が要る会社が、株主ごとに議決権などの扱いを定款で変える仕組みです。", body:"全ての株に譲渡の制限がある会社では、株の種類を分けなくても、特定の株主の議決権を多くする、配当の扱いを変えるといった定めを定款に置けます。承継では、先代が株を渡したあともしばらく、議決権を多く持つ形などに使われることがあります。定めるには特に重い株主総会の決議が要り、登記簿には載りません。", acts:["株主の顔ぶれと、どんな扱いの違いを付けたいかを社長に伺う", "定めの中身と決議の手続きは、弁護士・司法書士に確かめていただく", "定めが登記に載らないので、定款を大切に保管しておくことをお伝えする"], actHead:"現場で使うなら", note:"属人的株式の定めと手続きの法律上の判断は弁護士・司法書士、評価と税の扱いは税理士の業務。こちらでは設計を勧めない。", pre:1, say:"株を譲るのに承認が要る会社では、株主ごとに議決権の扱いを変える定めを置ける場合があります。使うかどうかは弁護士の先生と確かめるものです。", more:"よくある勘違いは、種類株式と同じものだと考えることです。属人的株式は株そのものではなく人に付く定めで、その株主が亡くなったり株を手放したりしたときの扱いも定款に書いておきます。株主の間の公平が問題になることもあるので、決める前にほかの株主へ説明します。", why:"株主の顔ぶれが限られた会社では、株主どうしの事情に合わせた扱いを認めたほうが経営に合う場面があるため、会社法が全ての株に譲渡の制限がある会社に限って認めているためです。" },
      { key:'faq_xjsk_shuruikabu', faq:1, grp:'jsk', q:"種類株式とは？承継でどう使う？", re:/種類株|無議決権株|議決権(のない|が無い|がない)株|議決権制限/, head:"種類株式は、議決権や配当などの中身を変えた株で、経営の権利と財産を分けて渡すのに使われます。", body:"会社は定款を変えて、議決権の無い株、配当を先に受け取る株、特定の決議を止められる株などを出せます。承継では、後継者に議決権のある株を、継がないご家族に議決権の無い株を渡して、経営の権利を後継者に集めながら財産を分ける形に使われることがあります。定款の変更には株主総会の決議と登記が要ります。", acts:["株の分け方で困っている点（議決権・ご家族への分け方）を先に伺う", "種類株式を使うかどうかと設計は、弁護士・司法書士・税理士に確かめていただく", "議決権の無い株も財産なので、相続税の評価がかかることをお伝えする"], actHead:"現場で使うなら", note:"種類株式の設計と定款の変更の法律上の判断は弁護士、登記は司法書士、評価と税は税理士の業務。こちらでは設計を勧めない。", pre:1, say:"株の中身を変えて、経営の権利と財産を分けて渡す方法があります。使うかどうかは、弁護士や顧問の先生と確かめてから決めるものです。", more:"よくある勘違いは、議決権の無い株なら評価がかからないと考えることです。財産としての評価はかかり、相続税の対象にもなります。継がないご家族が、意見が言えない、配当が少ないと不満を持つこともあるので、渡す前に中身を説明しておきます。", why:"中小企業では株が財産の多くを占めるため、株を平等に分けると経営の権利まで分かれてしまうので、権利の中身を分けて渡す方法として会社法が種類株式を認めているためです。" },
      { key:'faq_xjsk_nouzei', faq:1, grp:'jsk', q:"自社株の相続税を納めるお金はどう考える？", re:/(自社株|株)[^。]{0,10}相続税[^。]{0,10}(払え|納め|納税|お金)|(後継者|跡継ぎ)[^。]{0,8}(相続税を納め|相続税を払)/, head:"自社株は売ってお金にしにくいので、相続税を納めるお金を、株とは別に用意する形を考えます。", body:"相続税は原則としてお金で納めるため、財産の多くが自社株だと、相続した人の手元のお金が足りなくなりやすくなります。用意の道は、預貯金、会社が株を買い取る形、死亡退職金、受取人を決めた生命保険、納め方の特例などで、組み合わせて考えます。事業承継税制で株の税が猶予される場合も、ほかの財産の税は残ります。", acts:["財産の一覧で、自社株と、すぐお金にできる財産の割合を見る", "相続税のおおよその額は、顧問の税理士に試算をお願いしていただく", "納めるお金の道ごとに、誰の手元にいつお金が来るかを並べる"], actHead:"現場で使うなら", note:"相続税の計算・納め方の特例は、税理士と国税庁の公表資料で確かめる。こちらでは税額を言い切らない。", pre:1, say:"会社の株はすぐにお金に替えにくいので、相続税を納めるお金を別に用意しておく考え方があります。おおよその額を顧問の先生に確かめてから、道を並べませんか。", more:"よくある勘違いは、会社にお金があれば相続税も払えると考えることです。会社のお金と後継者個人のお金は別で、会社から個人へお金を移すには、退職金や株の買い取りなどの手続きと税が関わります。納める期限までに遺産分割がまとまらないと使えない特例もあるので、早めに段取りを考えます。", why:"相続税は相続した人それぞれが、決められた期限までにお金で納めるのが原則で、売りにくい自社株が財産の多くを占めると、財産はあってもお金が足りないことが起きるためです。" },
      { key:'faq_xjsk_hoken_yakume', faq:1, grp:'jsk', q:"事業承継で保険はどんな役目がある？", re:/(事業承継|承継)[^。]{0,10}(保険|生命保険)[^。]{0,10}(役目|役割|意味|役に立|関係|使う|使え|活用)|(保険|生命保険)[^。]{0,8}(事業承継|承継)[^。]{0,8}(役目|役割|意味|役に立|関係|使)/, head:"承継での保険の役目は、お金が要る場面に、受け取る人と時期を決めてお金を届けることです。", body:"主な場面は、社長が亡くなったときの会社の資金繰り、ご遺族への死亡退職金や弔慰金の財源、相続した株を会社が買い取るお金、後継者がほかのご家族に払うお金、相続税を納めるお金です。どの場面に、誰が契約者になり誰が受け取るかで、保険の形と税の扱いが変わります。承継の計画で場面を先に決め、保険はそのあとに置きます。", acts:["承継の計画から、お金が要る場面を書き出し、会社と個人のどちらの手元に要るかを分ける", "場面ごとに契約者・被保険者・受取人の形を並べ、税の扱いは顧問の税理士に確かめていただく", "保険で備えない場面（預金・借入など）も並べて、社長に選んでいただく"], actHead:"現場で使うなら", note:"税の扱いと経理は税理士、遺留分などの法律上の判断は弁護士の業務。商品の細部は保険会社の約款で確かめる。こちらでは税の効果で保険を勧めない。", pre:1, say:"承継の中でお金が要る場面がいくつかあります。どの場面に、誰の手元へお金を届けたいかから、ご一緒に整理させてください。", more:"よくある勘違いは、承継の保険を相続税の話だけと考えることです。社長が急に亡くなると、取引先や金融機関の受け止めで会社の資金繰りが苦しくなる場面もあります。会社が受け取るお金と、ご家族が受け取るお金を取り違えると、届けたい人にお金が届かないので、受取人の形を先に決めます。", why:"承継では、株や事業用の財産のように分けにくく、すぐお金にならない財産が多く、お金が要る場面と手元のお金がずれやすいためです。保険は、決めた人に決めた時にお金を届けられる仕組みなので、そのずれを埋める役目を持ちます。" },
      /* kkl.json */
      { key:'faq_xkkl_kyouiku_rogo', faq:1, grp:'kkl', q:"教育費と老後資金の準備が重なるときは、どう考える？", re:/(教育(費|資金)|学費)[^。]{0,14}老後|老後[^。]{0,14}(教育(費|資金)|学費)/, ng:/部下|法人|社長/, head:"教育費は時期が決まり、老後は長く続きます。並べて一枚で見ます。", body:"教育費は進学の時期に集まってかかり、遅らせることが難しいお金です。老後のお金は長い期間にわたって必要で、準備を始める時期や働き方で変えられる部分があります。教育費を優先して老後の準備が止まると、教育が終わった後に残る準備の期間が短くなります。ライフプランツールで、教育費がかかる時期と老後に向けた貯えを並べ、どの時期に何を受け持つかを決めます。", acts:["お子さまの進学の時期と、退職の時期を一枚の年表に並べる", "教育費が重い時期にも、老後の積立を小さくても続けられるか確かめる", "奨学金や学び方の選び方は、お子さまと話して決める"], actHead:"現場で使うなら", note:"奨学金の要件は学校や日本学生支援機構の窓口で、年金の見込みは日本年金機構のねんきん定期便で確かめる。", pre:1, say:"教育費と老後のお金は、時期を並べて見ると、どこで両方を受け持てるかが見えてきます。一緒に年表を作ってみませんか。", more:"教育費が重い時期と住宅ローンの返済、親の介護が同じ時期に重なるご家庭もあります。そのときは、どれか一つを遅らせるのではなく、働き方・住まい・支出の形を組み合わせて考えます。教育には奨学金など借りる手段がある一方、老後の暮らしのお金は借りにくい、という違いも話しておきます。", why:"教育費だけを見ていると老後の準備が後回しになり、老後だけを見ていると教育の時期に家計が回らなくなるからです。並べると、両方の落としどころが見えます。" },
      { key:'faq_xkkl_rogo_itsu', faq:1, grp:'kkl', q:"老後資金の準備は、いつから始めればいい？", re:/老後(の)?(資金|お金|生活費|の備え|に向け)[^。]{0,10}(いつから|何歳から|始め時|はじめ時)/, ng:/部下|法人|社長|退職金/, head:"始めるのが早いほど毎月の額を小さくできます。続けられる額から始めます。", body:"老後のお金は、準備の期間が長いほど毎月の額を小さくできます。ただ、子育てや住宅ローンの時期と重なると、老後の分まで回らないこともあります。大事なのは、今の家計で続けられる額で止めずに続けることです。公的年金の見込みはねんきん定期便で確かめられるので、ライフプランツールに入れ、年金だけで足りない分がどれくらいかを見てから額を決めます。", acts:["ねんきん定期便で、今の年金の見込みを確かめる", "ライフプランツールに入れ、老後に足りない分の見込みを見る", "今の家計で続けられる額を決め、自動の積立にする"], actHead:"現場で使うなら", note:"年金の見込みは日本年金機構のねんきん定期便とねんきんネットで、積立の制度の要件は金融機関で確かめる。", pre:1, say:"老後のお金は、続けられる額で早めに始めるほど毎月の負担を小さくできます。まず年金の見込みから一緒に見てみませんか。", more:"老後の準備を考えると、iDeCoやNISAなどの制度が気になる方が多いです。どれを使うかは、使い道の時期と途中で引き出せるかどうかで選びます。税の扱いの細かな判断は税理士に確かめます。子育て期は、少額でも続けることを先にします。", why:"準備を始める時期が遅れるほど、残りの期間で同じ額を準備するために、毎月の負担が重くなるからです。" },
      { key:'faq_xkkl_tatenaoshi', faq:1, grp:'kkl', q:"貯金を取り崩したあと、どう立て直す？", re:/(取り崩|使い切|使ってしま|減っ)[^。]{0,12}(立て直|戻す|戻し|貯め直|元に)|いざというときのお金を使い切/, ng:/法人|会社の|資金繰り|運転資金/, head:"毎月の流れを先に戻し、いざというときの分から少しずつ貯め直します。", body:"取り崩したあとは、まず毎月の家計が赤字になっていないかを確かめます。毎月の流れが黒字に戻れば、いざというときの分から順に貯め直せます。貯め直す間は、新しい積立や大きな買い物を少し待ち、どの時期までに戻すかの目安を決めておくと続けやすくなります。同じ出費がまた来そうなら、その備えも一緒に分けておきます。", acts:["毎月の家計が黒字かどうかを、明細で確かめる", "いざというときの分を、ほかの貯金より先に戻す", "戻す時期の目安を決め、毎月の額を自動の積立にする"], actHead:"現場で使うなら", note:"借入で立て直す場合の条件は金融機関で、公的な貸付や給付の要件は市区町村の窓口で確かめる。", pre:1, say:"取り崩したあとは、まず毎月の流れを戻して、いざというときの分から少しずつ貯め直していきましょう。", more:"貯め直しを急いで毎月の額を大きくすると、暮らしが苦しくなって途中で止まりがちです。今の家計で続けられる額にして、ボーナスや臨時の収入があれば一部を足す形が続けやすいです。", why:"いざというときのお金が無いまま次の出費が来ると、借入や大事な積立の取り崩しにつながるからです。先にそこを戻すと、ほかの準備も落ち着いて続けられます。" },
      { key:'faq_xkkl_hitorioya', faq:1, grp:'kkl', q:"ひとり親の家庭のライフプランで、大事なことは？", re:/(ひとり親|シングルマザー|シングルファーザー|母子家庭|父子家庭)[^。]{0,10}(ライフプラン|家計|教育費|備え|制度|大事|考え)/, ng:/保険|保障|部下|法人/, head:"収入を一人で受け持つので、働けなくなったときと教育費の備えを先に見ます。", body:"ひとり親の家庭では、暮らしと教育費を一人の収入で受け持ちます。働けなくなったときや、もしものときに子どもの暮らしがどうなるかを先に確かめます。ひとり親の家庭が受けられる手当や医療費の助成、就学の援助などの公的な制度があり、要件は住んでいる自治体で違います。ライフプランツールで教育費の山の時期を見て、制度で受け持てる分と並べます。", acts:["受けられる手当や助成を、市区町村の窓口で確かめる", "働けなくなったときの収入と、子どもの暮らしの備えを確かめる", "教育費の山の時期と、奨学金などの手段を並べて見る"], actHead:"現場で使うなら", note:"ひとり親の家庭の手当や助成の要件は、市区町村の窓口で確かめる。", pre:1, say:"ひとり親のご家庭は、使える制度が自治体ごとにあります。まずそれを確かめて、教育費の時期と一緒に見通しを作ってみませんか。", more:"もしものときに子どもの暮らしを誰が見るかを決めておくことも大事です。元の配偶者からの養育費がある場合は、受け取りが続くかどうかも見通しに入れます。手当は所得などで変わるので、毎年確かめます。", why:"一人の収入で家族を支えるので、その収入が途切れたときの影響が大きいからです。制度を先に知ると、家計で受け持つ分を落ち着いて決められます。" },
      { key:'faq_xkkl_kaigo_kakei', faq:1, grp:'kkl', q:"親の介護が始まったら、家計で何を確かめる？", re:/(親|親御さん|両親|父|母)[^。]{0,4}(の)?介護[^。]{0,8}(始まっ|始ま|することにな|が必要にな)[^。]{0,12}(家計|お金|確かめ|どうする|見方)|(親|両親)の介護で家計/, ng:/部下|社員|うちの会社|規定|規程|休業|休暇|何日|保険金|給付金/, head:"介護の費用は親のお金から出すのが基本です。親の収入と貯えを先に確かめます。", body:"介護の費用は、まず介護を受ける親ご本人の年金や貯えから出すのが基本の考え方です。子の家計から出すと、子自身の老後の準備や教育費に響きます。親の収入と貯え、公的な介護保険で受けられるサービス、兄弟姉妹で誰が何を受け持つかを確かめます。介護で働き方が変わる場合は、子の家計の見通しも入れ直します。", acts:["親の年金と貯え、毎月の支出を、親ご本人と一緒に確かめる", "要介護認定と受けられるサービスを、地域包括支援センターで確かめる", "兄弟姉妹で、お金と手間を誰が受け持つかを話す", "介護で働き方が変わるなら、ご自身のライフプランも入れ直す"], actHead:"現場で使うなら", note:"介護のサービスと費用の扱いは、市区町村の窓口や地域包括支援センターで確かめる。", pre:1, say:"介護のお金は、まず親御さんご本人の年金や貯えから考えるのが基本です。ご自身の老後に響かない形を一緒に考えましょう。", more:"親のお金の中身を子が知らないことはよくあります。通帳の置き場所・年金の受け取り口座・保険の契約を、元気なうちに聞いておくと、介護が始まってから慌てずに済みます。親が判断できなくなると、親の口座のお金を動かしにくくなる場合もあります。", why:"子が介護の費用を受け持ちすぎると、子自身の老後のお金が足りなくなり、次の世代に負担が移るからです。先に親のお金を確かめると、無理のない受け持ち方が見えます。" },
      { key:'faq_xkkl_kaigo_ryoritsu', faq:1, grp:'kkl', q:"介護と仕事を両立するには、何から始める？", re:/介護と仕事(の両立|を両立|を続け)|仕事と介護(の両立|を両立)|介護(で|のために)[^。]{0,6}(仕事を辞め|離職|退職)|介護離職|仕事を続けながら[^。]{0,6}介護/, ng:/部下|社員|メンバー|うちの会社|規定|規程|何日/, head:"辞める前に、勤め先の制度と地域の介護の窓口を両方確かめます。", body:"介護が始まると、仕事を辞めて付き添うことを考える方もいます。ただ、辞めると収入が止まり、介護が長く続いたときにご自身の暮らしと老後のお金が苦しくなります。勤め先には、介護のための休みや働き方の制度があることが多く、地域包括支援センターでは介護のサービスの組み立てを相談できます。両方を確かめてから、働き方を決めます。", acts:["勤め先の介護のための制度を、規程と担当の窓口で確かめる", "親の住む地域の地域包括支援センターに、介護の相談をする", "辞めた場合と続けた場合の家計の見通しを並べる"], actHead:"現場で使うなら", note:"勤め先の制度は御社の規程と担当の窓口で、介護のサービスは地域包括支援センターや市区町村で確かめる。", pre:1, say:"辞める前に、勤め先の制度と地域の介護の窓口を両方確かめてみませんか。続けながら介護をする形が見つかることがあります。", more:"介護の休みは、ずっと付き添うためというより、介護の体制を整えるための期間として使う考え方があります。サービスの組み立てができれば、仕事を続けながら介護を続けやすくなります。一人で抱えず、兄弟姉妹や専門の窓口と分け合います。", why:"介護は先がどれくらい続くか分からないので、収入を止めてしまうと、ご自身の暮らしまで続かなくなるおそれがあるからです。" },
      { key:'faq_xkkl_kaigo_dare', faq:1, grp:'kkl', q:"親の介護のお金は、誰が出すもの？", re:/(親|両親)の介護(の)?(費用|お金)[^。]{0,10}(誰が|子ども|子供|払うべき|分け|出す|出して)|兄弟(姉妹)?で[^。]{0,8}介護(の)?(お金|費用)/, ng:/部下|社員|うちの会社|規定|規程|保険金|給付金|控除/, head:"親ご本人のお金から出すのが基本です。足りない分を、家族で話して分けます。", body:"介護の費用は、介護を受ける親ご本人の年金や貯えから出すのが基本の考え方です。それで足りない分を、子や兄弟姉妹でどう受け持つかを話し合います。お金を出す人と、手間をかける人が違うことも多いので、お金と手間の両方で分け方を決めると、あとの揉めごとを防げます。誰がいくら出したかは、記録に残しておきます。", acts:["親の年金と貯えで、毎月どこまで受け持てるかを確かめる", "足りない分の受け持ち方を、兄弟姉妹で話して決める", "出したお金と使い道を記録に残す"], actHead:"現場で使うなら", note:"介護の費用と相続の関わりは弁護士や税理士で、介護のサービスの費用は市区町村の窓口で確かめる。", pre:1, say:"介護のお金は、まず親御さんご本人のお金から考えるのが基本です。足りない分は、ご兄弟で話して分けていきましょう。", more:"介護に手間をかけた人と、かけなかった人で、相続のときに考えが分かれることがあります。介護が始まった段階で、お金と手間の分け方を話し、記録しておくと、あとの話し合いがしやすくなります。", why:"子が自分の貯えから出しすぎると、子自身の老後が苦しくなるからです。親のお金から出す形を基本にすると、家族全体で無理のない形を保てます。" },
      { key:'faq_xkkl_tool_akaji', faq:1, grp:'kkl', q:"ライフプランツールで足りないと出たら、どう伝える？", re:/(ライフプランツール|試算)[^。]{0,12}(足りな|マイナス|赤字|底をつ|尽き)[^。]{0,16}(伝え|話し方|説明|言い方|どう)/, ng:/部下|法人/, head:"結果を怖がらせる材料にせず、変えられることを一緒に探す入口にします。", body:"足りないと出たのは、今の前提のまま何も変えなかった場合の目安です。まずそのことを伝え、どの時期から差が出るのかを一緒に見ます。そのうえで、働き方・支出・住まい・貯え方など、変えられることを入れて将来プランで試算し直すと、どこを変えるとどう変わるかが見えます。決めるのはお客様で、その場で決めていただく必要はありません。", acts:["今の前提のまま変えなかった場合の目安だと、最初に伝える", "差が出始める時期と理由を、一緒に確かめる", "変えられることを将来プランに入れ、現状と並べる"], actHead:"現場で使うなら", note:"結果の伝え方は、所属保険会社の募集の決まりと御社の手順で確かめる。", pre:1, say:"これは今の前提のまま、何も変えなかった場合の目安です。どこを変えると見通しが変わるか、一緒に試してみましょう。", more:"足りないという結果をそのまま保険や運用の話につなげると、お客様は不安で決めることになります。先に支出や働き方で変えられることを試し、それでも残る部分があるときに、備えの選び方を話します。その場で決めていただく必要はないことも添えます。", why:"不安で決めた選択は、あとで続かなかったり、後悔につながったりしやすいからです。変えられることが見えると、お客様は落ち着いて考えられます。" },
      { key:'faq_xkkl_tool_zentei', faq:1, grp:'kkl', q:"物価上昇率や利回りの前提は、どう決める？", re:/(物価上昇率|物価の前提|物価の上がり方|運用利回り|利回りの前提)[^。]{0,14}(決め|入れ|前提|どう|試算)|試算の(運用)?利回り/, ng:/部下|法人|保険の利回り|予定利率|インフレ/, head:"高めに置かず控えめな前提で作り、前提を変えた場合とも並べて見ます。", body:"物価の上がり方や運用の利回りは、先のことなので誰にも分かりません。高めの利回りを置くと、見通しが実際より明るく見えます。控えめな前提で作っておき、前提を変えるとどれくらい結果が動くかを並べて見ると、前提の重さが分かります。ライフプランツールでは、前提の値は小さい字で示してあるので、お客様にも前提であることを伝えます。", acts:["使っている前提の値を、お客様に見せて伝える", "前提を少し変えた場合を将来プランで作り、並べる", "利回りの前提は、預けている先の実際に合わせて控えめにする"], actHead:"現場で使うなら", note:"運用の商品の中身と見込みは、各金融機関や保険会社のパンフレットで確かめる。", pre:1, say:"ここは先のことなので、控えめな前提で作っています。前提を変えるとどれくらい動くかも、一緒に見てみましょう。", more:"預貯金に置いたままのお金は、物価が上がると実際に買えるものが減ります。一方で、運用には値動きがあり、思った通りに増えるとは限りません。前提はお客様と一緒に決め、どちらかに寄りすぎない形にします。", why:"前提を楽観的に置くと、試算が明るく見えて、必要な準備が後回しになるからです。控えめに置くと、見通しが外れたときの困りごとを小さくできます。" },
      /* nkn.json */
      { key:'faq_xnkn_kiso_gaku', faq:1, grp:'nkn', q:"老齢基礎年金の額は何で決まる？", re:/(老齢基礎年金|国民年金|基礎年金)[^。]{0,6}(の)?(年金額|額|金額|満額)[^。]{0,10}(決ま|計算|何で|どうやって|どう決|って|とは|もら|受け取|届か|足りな)|満額[^。]{0,4}(の)?(老齢基礎年金|国民年金|基礎年金)/, ng:/厚生年金|遺族|障害|免除|猶予|任意加入|付加|繰り?上げ|繰り?下げ|在職|個人年金|企業年金|ideco|イデコ|確定拠出/, head:"老齢基礎年金の額は、保険料を納めた月の数で決まり、全ての月を納めると満額になります。", body:"国民年金に入る期間の全てで保険料を納めると、その年度の満額を受け取れ、納めていない月があると少なくなります。その期間のうち、厚生年金に入っていた期間や、その扶養に入っていた配偶者の期間も、納めた期間に数えます。免除の期間は度合いに応じて一部が反映され、納付猶予や学生納付特例の期間は、追納しないと額に反映されません。満額は毎年度改定されます。", acts:["ねんきん定期便とねんきんネットで、納めた月の数と未納・免除の月があるかを一緒に確かめる", "満額に届かないときは、任意加入や追納で額を増やす道があると伝え、年金事務所で確かめていただく", "老後の見込みには、満額で決め打ちせず、ご本人の記録の見込み額を使う"], actHead:"現場で使うなら", note:"満額の額・受給資格期間の長さ・免除の反映のしかたは制度で決まり改定される。個別の見込みは日本年金機構・年金事務所で確かめる。", pre:1, say:"国民年金から受け取る年金は、保険料を納めた月の数で決まります。ねんきん定期便で、納めた月と未納の月を一緒に見てみましょう。", more:"例えば学生の頃に学生納付特例を使い、そのあと追納していない方は、その期間が額に反映されていないことがあります。追納できる期間には限りがあるので、気づいた時点で年金事務所に確かめると、追納か任意加入かを選べます。厚生年金の加入が長い方も、基礎年金の部分は同じ考え方です。", why:"老齢基礎年金は、国民年金に入る期間の全てで保険料を納めた方に満額を払う設計なので、納めた月の割合で額が決まります。納めた保険料に応じて受け取る、という公平さを保つための作りです。" },
      { key:'faq_xnkn_kousei_gaku', faq:1, grp:'nkn', q:"老齢厚生年金の額は何で決まる？", re:/(老齢厚生年金|厚生年金)[^。]{0,6}(の)?(年金額|額|金額)[^。]{0,10}(決ま|計算|何で|どう|何を見)|(給料|給与|収入|報酬|ボーナス|賞与)[^。]{0,10}(高|多|少|低)[^。]{0,10}(厚生年金|年金)[^。]{0,6}(多|少|増|減|高|低|変わ)/, ng:/在職|働きながら|働く|止ま|カット|特別支給|遺族|障害|個人年金|企業年金|役員報酬|ideco|イデコ|確定拠出|加給|繰り?上げ|繰り?下げ|改定|毎年/, head:"老齢厚生年金の額は、厚生年金に入っていた間の給与と賞与の平均と、入っていた月の数で決まります。", body:"会社員や公務員として厚生年金に入っていた間の給与と賞与（標準報酬月額と標準賞与額）を平均し、入っていた月の数に応じて計算する部分が中心で、加入した時期によって計算のしかたが違う部分もあります。給与が高かった期間や、入っていた期間が長いほど額は大きくなりますが、標準報酬月額には上限があります。条件に合うご家族がいると加給年金が加わることがあります。", acts:["ねんきん定期便の厚生年金の加入記録と見込み額を、お客様と一緒に確かめる", "転職の多い方には、全ての勤め先の加入記録がそろっているかを、ねんきんネットで確かめていただく", "額の見込みはこちらで計算せず、ねんきんネットや年金事務所の数字を使う"], actHead:"現場で使うなら", note:"計算のしかた・乗率・標準報酬月額の上限は制度で決まり改定される。個別の額は日本年金機構・年金事務所、ねんきんネットで確かめる。", pre:1, say:"厚生年金から受け取る年金は、会社員として働いていた間の給与と、入っていた期間の長さで決まります。ねんきん定期便で、ご自身の記録を確かめてみましょう。", more:"会社員の期間が長くても、若い頃の給与が低い期間が多いと平均は下がります。また、標準報酬月額には上限があるので、給与が上限を超えている方は、超えた分が額に反映されません。改正で上限は段階的に引き上げられることが決まっているので、最新の扱いは日本年金機構で確かめます。", why:"厚生年金は、給与に応じた保険料を納め、納めた保険料に応じて受け取る作りなので、給与の平均と加入した月の数で額が決まります。働いていた間の収入を、老後もある程度保つための制度です。" },
      { key:'faq_xnkn_ninni', faq:1, grp:'nkn', q:"国民年金の任意加入とは？", re:/任意加入|任意で[^。]{0,4}(入|加入|納め)|(あとから|後から|60歳(を)?(過ぎ|以降|から)|60歳以上)[^。]{0,10}(国民年金|年金の保険料)[^。]{0,8}(入れ|入る|加入|納め|払え|払う)|満額[^。]{0,10}(足りな|届かな)[^。]{0,16}(入れ|加入|納め|払)/, ng:/自動車|任意保険|自賠責|労災|特別加入|雇用保険|健康保険|繰り?上げ|繰り?下げ|遺族|障害|ideco|イデコ|企業年金|個人年金|確定拠出|付加|基金|追納/, head:"任意加入は、国民年金に入る期間のあとも申し出て保険料を納め、年金を満額に近づける仕組みです。", body:"国民年金に入る期間が終わったとき、納めた月が足りず満額に届かない方や、受給資格期間に足りない方は、申し出ると一定の年齢まで国民年金に入って保険料を納められます。海外に住む日本人の方も申し出て入れます。ただし、厚生年金に入っている方や、老齢基礎年金を繰上げて受け取っている方は入れません。入れる年齢と条件は生年月日などで決まります。", acts:["ねんきん定期便で納めた月の数を確かめ、満額に届かない方には任意加入という道があると伝える", "申し出の窓口は、住所地の市区町村の国民年金の窓口か年金事務所だと案内する", "入るかどうかは、増える額と納める保険料をお客様が見比べて決めることとして、額は年金事務所で確かめていただく"], actHead:"現場で使うなら", note:"入れる年齢・期間・条件は生年月日や住まいで違い、改正で変わる。日本年金機構・年金事務所・市区町村で確かめる。", pre:1, say:"国民年金は、決まった期間が終わったあとでも、満額に足りない方は申し出て保険料を納め、年金を増やせることがあります。年金事務所で確かめてみましょう。", more:"任意加入の期間の保険料は、口座振替で納めるのが原則です。付加保険料を一緒に納められる場合もあります。繰上げ受給を選ぶと任意加入ができなくなるので、どちらを先に考えるかは、ご本人の記録を見ながら年金事務所で確かめます。", why:"国民年金は、決まった期間の全てで保険料を納めると満額になる作りなので、納めた月が足りない方のために、期間が終わったあとで足りない分を補える道を用意しています。受給資格に届かない方を年金のない状態にしないための仕組みでもあります。" },
      { key:'faq_xnkn_tokubetsu', faq:1, grp:'nkn', q:"特別支給の老齢厚生年金とは？", re:/特別支給|(本来より前|本来より早|65歳(より)?前|65歳になる前)[^。]{0,10}(もらえる|受け取れる|出る)[^。]{0,4}(厚生)?年金/, ng:/特別支給金|労災|休業|繰り?上げ|遺族|障害|個人年金|企業年金|ideco|イデコ|確定拠出/, head:"特別支給の老齢厚生年金は、生年月日によって、本来の年齢より前に受け取れる厚生年金です。", body:"昔の制度から移るときの経過の仕組みで、生年月日と性別で受け取り始める年齢が決まり、厚生年金に入っていた期間などの要件もあります。対象の方は段階的に減っていて、これから受け取る方は限られます。繰上げとは違うので、受け取っても本来の年齢からの年金は減りません。繰下げの仕組みも無く、遅らせても額は増えず、請求しないと時効で受け取れない分が出ます。", acts:["対象になる方には、受け取り始める時期が近づくと年金請求書が届くことを伝える", "請求しても本来の年齢からの年金が減らないことを、繰上げと混同しないように伝える", "働きながら受け取る方や失業給付を受ける方は、調整があるので年金事務所で確かめていただく"], actHead:"現場で使うなら", note:"対象になる生年月日・受け取り始める年齢・要件は制度で決まる。対象かどうかと額は日本年金機構・年金事務所で確かめる。", pre:1, say:"生年月日によっては、本来の年齢より前に受け取れる厚生年金があります。受け取っても後の年金が減るものではないので、対象かどうかを確かめましょう。", more:"よくある勘違いは、繰上げと同じだと思って請求を控えることです。特別支給の老齢厚生年金は、請求を控えても額は増えず、時効で受け取れない分が出ます。ただし、厚生年金に入って働く間は在職老齢年金の調整があり、雇用保険の失業給付を受ける間は止まります。", why:"本来の受け取り始めの年齢を引き上げたときに、急な変化にならないよう、生年月日ごとに段階的に移る経過の仕組みとして設けられました。そのため対象は生年月日で決まり、だんだん少なくなっています。" },
      { key:'faq_xnkn_kaitei', faq:1, grp:'nkn', q:"年金の額は毎年変わる？", re:/年金(額|の額)?[^。]{0,4}(改定|毎年[^。]{0,6}(変わ|見直|改定|上が|下が))|マクロ経済スライド|物価[^。]{0,6}(上が|下が|上昇|変わ)[^。]{0,10}年金[^。]{0,6}(増え|上が|下が|変わ|連動|追いつ)|年金[^。]{0,8}物価[^。]{0,6}(連動|追いつ|合わせ|上が)/, ng:/個人年金|企業年金|ideco|イデコ|確定拠出|在職|働|給料|給与|学生|保険料|在職定時|退職時/, head:"年金の額は、物価や賃金の動きに合わせて毎年度改定されます。", body:"公的年金の額は、物価や賃金の変わり方をもとに毎年度見直され、改定のお知らせが届きます。ただし、少子高齢化に合わせて給付の伸びを抑えるマクロ経済スライドという仕組みがあり、物価や賃金が上がっても、年金はその上がり方より小さくしか増えない年があります。物価や賃金が下がった年などの扱いにも決まりがあります。", acts:["老後の見込みを立てるときは、物価の上がり方と年金の増え方が同じとは限らないと伝える", "改定のお知らせや振込の通知の額を、お客様と一緒に前の年と比べて見る", "将来の額の見込みはこちらで決めず、ねんきんネットや公的年金シミュレーターで確かめていただく"], actHead:"現場で使うなら", note:"改定のしかたとマクロ経済スライドの調整は法律で決まり、毎年度の改定率は厚生労働省・日本年金機構が公表する。個別の額は年金事務所で確かめる。", pre:1, say:"年金の額は毎年度、物価や賃金の動きに合わせて見直されます。ただし、物価と同じだけ増えるとは限らないので、その分も考えて老後の計画を立てましょう。", more:"改定は、年齢によって賃金の動きを基本にする方と物価の動きを基本にする方に分かれるなど、決まりがあります。そこからマクロ経済スライドの分が差し引かれるので、上がる年でも物価の上がり方より小さく増えることがあります。", why:"公的年金は、今働く世代の保険料などで今の受給者を支える仕組みが中心なので、物価に合わせて価値を保ちつつ、支え手が減る分だけ伸びを抑えて、制度を長く続けられるように調整しています。" },
      { key:'faq_xnkn_shourai', faq:1, grp:'nkn', q:"年金って将来もらえなくなるの？", re:/年金[^。]{0,12}(もらえなくな|もらえない(って|と|の|んじゃ)|破綻|なくなる|つぶれ|潰れ|崩壊|払われなくな|受け取れなくな|続くの|大丈夫なの)|(若い人|若者|若い世代|私たちの世代)[^。]{0,10}年金[^。]{0,8}(もらえ|受け取れ)/, ng:/個人年金|企業年金|ideco|イデコ|確定拠出|未納|払わな|払っていな|請求|時効|遺族|障害|加給|会社|事業|資格|足りな|期間|再婚|離婚|結婚|事実婚|免除|猶予|手帳|振替加算|特別支給/, head:"年金は、なくなるのではなく、給付の水準を調整しながら続ける作りになっています。", body:"公的年金は、今働く世代の保険料に、積み立ててきた積立金と国の負担（税金）を合わせて支えています。少子高齢化に合わせて、マクロ経済スライドで給付の伸びを抑える調整が組み込まれ、国は定期的に財政検証で長い先の見通しを点検しています。そのため、年金そのものがなくなるかより、受け取る額の水準がどうなるかが論点です。将来の額を約束できる人はいません。", acts:["なくなると言い切らず、なくならないとも約束せず、仕組みと見通しの出どころを伝える", "ねんきん定期便の見込み額を使い、公的年金を土台に足りない分を考える順番で話す", "不安をきっかけに商品の話へ急がず、まず年金の記録と見込みを一緒に確かめる"], actHead:"現場で使うなら", note:"財政検証の結果と給付の見通しは厚生労働省が公表する。個別の見込み額は日本年金機構・ねんきんネットで確かめる。将来の額は約束しない。", pre:1, say:"年金は、なくなる仕組みではなく、受け取る水準を調整しながら続ける仕組みです。将来の額は約束できないので、ご自身の見込みを確かめて、足りない分を一緒に考えましょう。", more:"財政検証では、経済の伸び方などをいくつかの前提に分けて、将来の給付の水準を見通しています。前提によって結果が違うので、一つの数字で将来を言い切らないことが大事です。お客様には公表された資料の出どころを示し、ご本人の見込み額は、ねんきんネットで試していただきます。", why:"公的年金は、支える世代と受け取る世代の人数の釣り合いが変わっても続くよう、給付の伸びを自動で抑える調整と、定期的な点検を組み込んでいます。その分、受け取る額の水準は経済や人口の動きで変わり得ます。" },
      { key:'faq_xnkn_imi', faq:1, grp:'nkn', q:"国民年金は払っても意味がないと言われたら？", re:/(国民年金|年金)[^。]{0,12}(意味がな|意味ない|払い損|元が取れな|払いたくな|払う必要がな|払わなくてい)/, ng:/個人年金|企業年金|ideco|イデコ|確定拠出|免除|猶予|払えな|払えず|生命保険|医療保険|学生|亡くな|死ん|死亡/, head:"損得で答えず、障害や遺族の保障もあり、生涯受け取れる公的な土台だという中身を伝えます。", body:"国民年金は、老後の年金のほかに、病気やけがで障害が残ったときの障害基礎年金と、亡くなったときに子のある配偶者などが受け取る遺族基礎年金も支えています。老齢基礎年金は生きている限り受け取れ、毎年度改定され、基礎年金には国の負担も入っています。加入と納付は法律で決まっていて、払えないときは免除や猶予を申請する道があります。", acts:["得か損かの話に乗らず、障害・遺族・生涯という三つの中身を順に伝える", "払うのが苦しい事情があるときは、未納のままにせず免除や猶予の申請を案内する", "保険の話につなげる前に、まず公的年金の土台をお客様に分かっていただく"], actHead:"現場で使うなら", note:"納付の義務・免除や猶予の基準・給付の要件は法律で決まり改定される。日本年金機構・年金事務所・市区町村で確かめる。損得は言い切らない。", pre:1, say:"国民年金は、老後の年金のほかに、障害や万一のときのご家族の年金も支えている、公的な土台です。払うのが苦しいときは、免除や猶予の申請という道があります。", more:"払い損かどうかは、受け取る期間の長さで変わるので、誰にも言い切れません。一方で、未納のまま病気やけがをすると、障害基礎年金の納付の要件を満たせず受け取れないことがあります。損得より、何が支えられているかを並べると、お客様が自分で考えやすくなります。", why:"国民年金は、老いや障害、家計を支える人の死といった、誰にでも起き得ることに国全体で備える社会保険なので、払った分だけ戻る貯金とは考え方が違います。支え合いの仕組みなので、損得だけでは比べられません。" },
      { key:'faq_xnkn_kaisei', faq:1, grp:'nkn', q:"年金制度の改正で何が変わる？", re:/年金(制度|法)?[^。]{0,6}(改正|改革|見直し)[^。]{0,12}(何が|どう|中身|内容|ポイント|変わ|教えて)|(改正|改革)[^。]{0,6}年金(制度|法)?[^。]{0,8}(何が|どう|中身|内容|ポイント|変わ)/, ng:/保険業法|個人年金|企業年金|ideco|イデコ|確定拠出|個人型/, head:"2025年成立の年金制度の改正で、パートの方の厚生年金や在職老齢年金、遺族年金などが見直されます。", body:"主な中身は、パートなどで厚生年金に入る条件の見直し（賃金と会社の規模の要件）、働きながら受け取る年金が止まる基準の引き上げ、子のいない配偶者の遺族厚生年金の受け取り方の見直しと男女差の解消、厚生年金の標準報酬月額の上限の段階的な引き上げ、加給年金と子の加算の見直し、iDeCoの加入できる年齢の引き上げなどです。始まる時期は項目ごとに違い、段階的に進みます。", acts:["改正の話は、項目ごとに始まる時期と対象の方が違うので言い切らず、お客様に関係する項目だけ確かめる", "パートで働く方のいるご家庭には、厚生年金の加入の見直しが家計と年金の両方に関わると伝える", "遺族年金を前提にした保障の話は、改正後の扱いを日本年金機構の案内で確かめてから考える"], actHead:"現場で使うなら", note:"項目ごとの始まる時期・対象・額は法律と政令で決まり、段階的に進む。厚生労働省・日本年金機構の案内で最新を確かめる。", pre:1, say:"2025年の年金制度の改正で、パートの方の厚生年金や、働きながら受け取る年金、遺族年金などが見直されます。始まる時期は項目ごとに違うので、関係するところだけ確かめましょう。", more:"例えば、遺族厚生年金の見直しは、今受け取っている方は対象外とされ、これから受け取る方から段階的に進みます。在職老齢年金の基準の引き上げは既に始まっています。基礎年金の水準の底上げは、次の財政検証の結果を見て検討することとされました。細部は厚生労働省の資料で確かめます。", why:"働き方の多様化や共働きの広がり、長く働く方の増加に合わせて、制度を今の暮らし方に近づけるために見直されました。年金制度は、定期的な点検の結果を受けて、こうした見直しを重ねる作りです。" },
      { key:'faq_xnkn_machi_shibou', faq:1, grp:'nkn', q:"繰下げを待っている間に亡くなったらどうなる？", re:/(繰り?下げ|遅らせ|待機)[^。]{0,16}(亡くな|死亡|死んだ|死去|万一)|(亡くな|死亡)[^。]{0,10}(繰り?下げ|待機中)/, ng:/ideco|イデコ|確定拠出|個人年金|企業年金|保険金|受取人/, head:"繰下げで待っている間に亡くなると、ご遺族は、増える前の本来の額で未支給年金を請求できます。", body:"繰下げは請求して初めて増えた額が決まるので、待っている間に亡くなると、増えた額では受け取れません。その代わり、生計を同じくしていたご遺族が、本来の額で受け取れたはずの分を未支給年金として請求できます。ただし時効があるので、さかのぼれる期間には限りがあり、受け取れる方の範囲と順番も決まっています。遺族年金は別の要件で決まります。", acts:["繰下げを考えるお客様には、待つ間に亡くなったときの扱いも先に伝え、ご家族とも共有していただく", "ご遺族から相談を受けたら、未支給年金の請求ができるかを年金事務所で確かめていただく", "待つ期間が長いほど時効にかかる分が出やすい点を、繰下げを決める材料として並べる"], actHead:"現場で使うなら", note:"受け取れるご遺族の範囲と順番・時効の期間は法律で決まる。手続きは日本年金機構・年金事務所で確かめる。", pre:1, say:"繰下げで待っている途中に万一のことがあると、増えた額ではなく、本来の額をご家族が請求する形になります。待つかどうかを決めるときの材料にしてください。", more:"未支給年金を請求できるのは、亡くなった方と生計を同じくしていた配偶者や子、父母などで、順番が決まっています。待っていた期間が長く、時効にかかる部分があると、その分は受け取れません。繰下げを選ぶときは、ご家族にも待っていることを伝えておくと、手続きの漏れを防げます。", why:"繰下げの増額は、ご本人が遅らせる申し出をした時点で決まる仕組みなので、申し出の前に亡くなると増額は生まれません。受け取る権利そのものは生まれているため、本来の額が未支給年金として残ります。" },
      { key:'faq_xnkn_sakanobori', faq:1, grp:'nkn', q:"繰下げで待っていた年金は、さかのぼって受け取れる？", re:/(繰り?下げ|遅らせ|待機|待ってい)[^。]{0,16}(さかのぼ|遡|一括|まとめて|本来の額|本来請求|やめて)|(さかのぼ|遡)[^。]{0,10}(繰り?下げ|待機)/, ng:/亡くな|死亡|ideco|イデコ|確定拠出|個人年金|企業年金|障害|遺族/, head:"待っている途中でも、増えた額で受け取り始めるか、本来の額でさかのぼって受け取るかを選べます。", body:"繰下げで待っている方が請求するときは、その時点までに増えた額で受け取り始める方法と、繰下げをせず、本来の額をさかのぼってまとめて受け取る方法から選べます。さかのぼれるのは時効の範囲までです。一定の年齢を過ぎてからさかのぼる受け取りを選ぶと、さかのぼれる期間の初めに遅らせる申し出をしたとみなし、増えた額で計算する仕組みもあります。", acts:["請求のときに二つの受け取り方があることを伝え、どちらにするかはお客様に決めていただく", "さかのぼってまとめて受け取ると、過去の年の税や保険料に関わることがあると伝え、税は税理士・税務署に確かめていただく", "受け取り方ごとの額は、年金事務所で出していただく"], actHead:"現場で使うなら", note:"さかのぼれる期間・みなしの仕組みの対象・税や保険料の扱いは法律で決まる。年金は日本年金機構・年金事務所、税は税理士・税務署で確かめる。", pre:1, say:"繰下げで待っていた年金は、増えた額で受け取り始めるか、本来の額でさかのぼってまとめて受け取るかを選べます。どちらが合うかは、年金事務所で額を出してもらってから考えましょう。", more:"まとめて受け取ると、その年金は本来受け取るはずだった年ごとの収入として扱われるため、過去の年の所得税や住民税、国民健康保険料や介護保険料が変わることがあります。また、さかのぼる受け取りを選ぶと、その後の毎回の額も、さかのぼった時点で決まる額で続きます。どちらの影響が大きいかは、ご本人の状況で違います。", why:"繰下げの増額は、遅らせた期間に応じて毎回の額を増やす仕組みなので、遅らせることをやめて本来の額で受け取る道も残されています。長く待った方が時効で受け取れない分を抱えないよう、みなしの仕組みが後から加えられました。" },
      { key:'faq_xnkn_toku', faq:1, grp:'nkn', q:"繰上げと繰下げ、どっちが得と聞かれたら？", re:/(繰り?上げ|繰り?下げ|早くもら|早く受け取|遅らせ|遅くもら|待って(受け取|もら))[^。]{0,16}(得|損|有利|不利|元が取れ)|(年金|繰り?上げ|繰り?下げ)[^。]{0,10}(どっちが|どちらが)[^。]{0,6}(得|損|有利|いい|良い)/, ng:/亡くな|死亡|個人年金|企業年金|ideco|イデコ|確定拠出|ローン|返済|nisa|ニーサ/, head:"どちらが得かは受け取る期間で変わるので言い切らず、暮らし・健康・働き方で選ぶものと伝えます。", body:"繰上げは早く受け取れる代わりに額が減り、繰下げは待つ代わりに額が増えて、どちらも決めた額が生涯続きます。どちらが多く受け取れるかは何歳まで生きるかで変わり、誰にも分かりません。待つ間の暮らしのお金、健康、働き続けるか、加給年金の対象のご家族、税や社会保険料、障害や遺族の年金との関係などを並べて、お客様が選びます。", acts:["得か損かの答えは出さず、比べる材料を表に並べて一緒に見る", "受け取る額は、ねんきんネットや公的年金シミュレーターで、遅らせた場合と早めた場合をお客様と試す", "繰上げは取り消せないことと、障害年金などに関わることを、決める前に年金事務所で確かめていただく"], actHead:"現場で使うなら", note:"増減の率・選べる年齢の範囲は制度で決まり改定される。個別の額は日本年金機構・年金事務所で確かめる。どちらが得かは言い切らない。", pre:1, say:"どちらが多く受け取れるかは、何歳まで受け取るかで変わるので、誰にも言い切れません。暮らしのお金や健康、働き方を並べて、ご自身に合う時期を一緒に考えましょう。", more:"よく出る損益分岐の年齢の話は、税や社会保険料、物価の変化、加給年金を入れると変わるので、一つの年齢で決めつけないことが大事です。繰下げは基礎年金と厚生年金を別々に遅らせることもできるので、片方だけ遅らせる選び方もあります。", why:"繰上げと繰下げは、受け取る期間の長さに合わせて毎回の額を増減させ、平均すると釣り合うよう設計されています。そのため、どちらが得かは一人ひとりの寿命と暮らし方で決まり、制度としての正解はありません。" },
      { key:'faq_xnkn_konashi', faq:1, grp:'nkn', q:"子どもがいない妻の遺族年金は？", re:/(子ども|子供|お子様|お子さん|子)(が|は)?(いない|居ない|ない|無い)[^。]{0,24}遺族|子なし[^。]{0,20}遺族/, ng:/再婚|事実婚|内縁|自分の年金|両方|併給|請求|手続|生命保険|保険金|収入保障|父子/, head:"子のいない妻には遺族基礎年金は出ず、夫が厚生年金に入っていた場合などに遺族厚生年金が出ます。", body:"遺族基礎年金は子のある配偶者か子が受け取るので、子のいない妻は対象外です。夫が厚生年金に入っていたなどの要件を満たすと遺族厚生年金が出ますが、若い妻は受け取れる期間が限られ、一定の年齢の妻には中高齢寡婦加算が付く仕組みがあります。夫が自営業などで国民年金だけの場合は、寡婦年金か死亡一時金の対象になることがあります。改正で見直しも決まっています。", acts:["子のいないご夫婦の保障を考えるときは、遺族厚生年金の見込みと受け取れる期間を先に確かめていただく", "夫が自営業の期間が長いご家庭は、遺族厚生年金が無いか少ないことを前提に考える", "改正後の扱いは、日本年金機構の案内で確かめてから保障の話につなげる"], actHead:"現場で使うなら", note:"受け取れる要件・年齢・期間・加算は法律で決まり、2025年の改正で段階的に見直される。個別の見込みは日本年金機構・年金事務所で確かめる。", pre:1, say:"お子様がいないご夫婦では、遺族基礎年金は出ず、遺族厚生年金が中心になります。受け取れる期間や額は年齢などで変わるので、まず見込みを確かめましょう。", more:"2025年の改正で、子のいない配偶者の遺族厚生年金は、男女とも、受け取れる期間を区切る形を基本に段階的に見直されることが決まっています。今受け取っている方は対象外とされ、始まる時期と対象の年齢は案内で確かめます。中高齢寡婦加算も段階的に見直されます。", why:"遺族年金は、子を育てる家庭を手厚く支える考え方で作られているので、子のいない若い妻は、働いて自分の暮らしを立てられることを前提に、受け取れる期間が区切られています。共働きが広がったことを受けて、男女の差をなくし、この考え方を広げる方向で見直しが決まりました。" },
      { key:'faq_xnkn_izoku_heikyu', faq:1, grp:'nkn', q:"夫が亡くなったら、妻は自分の年金と遺族年金を両方もらえる？", re:/遺族(厚生|基礎)?年金[^。]{0,12}(自分の|ご自身の|本人の|妻の|老齢)[^。]{0,10}(年金|厚生)|(自分の|ご自身の|本人の|老齢)[^。]{0,10}年金[^。]{0,8}(と|も|が)[^。]{0,12}遺族(厚生|基礎)?年金|(自分の|ご自身の)[^。]{0,4}年金が(ある|あれば)[^。]{0,12}遺族/, ng:/障害|再婚|事実婚|請求|手続|税|課税/, head:"ご自身の老齢年金を受け取る年齢になると、自分の年金が先で、遺族厚生年金は上回る分だけ出ます。", body:"年金は一人一年金が原則で、受け取る年齢になると、ご自身の老齢基礎年金と老齢厚生年金を先に受け取り、遺族厚生年金は、ご自身の老齢厚生年金より多い分だけが支給されます。遺族厚生年金の額は、亡くなった方の年金をもとにした計算と、ご自身の年金も合わせた計算のうち、多いほうになる仕組みがあります。その年齢より前は、どちらかを選ぶ場面があります。", acts:["共働きのご夫婦には、残された方の年金が単純な足し算にならないことを先に伝える", "受け取る額の組み合わせは、ご夫婦の記録で年金事務所に試算していただく", "保障の額を考えるときは、遺族厚生年金が差額だけになる場合も見込みに入れる"], actHead:"現場で使うなら", note:"併給の組み合わせ・計算のしかたは法律で決まり改定される。個別の額は日本年金機構・年金事務所で確かめる。", pre:1, say:"ご自身の年金を受け取る年齢になると、まずご自身の年金を受け取り、遺族厚生年金はそれより多い分だけが出ます。両方がそのまま足されるわけではありません。", more:"例えば、妻ご自身も長く会社員だった場合は、妻の老齢厚生年金が大きく、遺族厚生年金の差額は小さくなるか出ないこともあります。一方、専業主婦の期間が長い方は、遺族厚生年金の差額が大きく残ることが多くなります。どちらになるかは、ご夫婦それぞれの記録で決まります。", why:"公的年金は、一人が受け取れる年金を一つにまとめる一人一年金が原則なので、同じ方が老齢と遺族の両方の権利を持つときは、重なる部分を調整します。自分で納めた保険料の分を先に受け取る作りです。" },
      { key:'faq_xnkn_otto', faq:1, grp:'nkn', q:"妻が亡くなったら、夫は遺族年金をもらえる？", re:/(妻|奥様|奥さん|家内)[^。]{0,12}(亡くな|死亡|万一|先立|死んだ)[^。]{0,16}(夫|ご主人|旦那)[^。]{0,8}(遺族|年金)|(夫|ご主人|旦那|男性)(でも|は|も)[^。]{0,6}遺族(厚生|基礎)?年金|父子家庭[^。]{0,10}(遺族|年金)|夫の遺族(厚生|基礎)?年金|(夫|ご主人|旦那)(が|は|も|でも)((?!亡くな|死亡|死ん)[^。]){0,14}(妻|奥様|奥さん|家内)(が|に)?(亡くな|死亡|万一|先立|死ん)[^。]{0,10}遺族(厚生|基礎)?年金/, ng:/自分の年金|両方|併給|再婚|事実婚|保険金|生命保険|収入保障/, head:"子のある夫は遺族基礎年金を受け取れ、遺族厚生年金には今の制度では夫に年齢の要件があります。", body:"遺族基礎年金は子のある配偶者が受け取る仕組みで、妻を亡くした子のある夫も対象です。遺族厚生年金は、今の制度では、妻が亡くなったときの夫の年齢などに要件があり、受け取り始める年齢にも決まりがあります。どちらの年金も、生計を同じくし、夫の収入が一定の基準より少なかったこと（生計維持の要件）が前提です。2025年の改正で、遺族厚生年金の男女の差をなくす方向の見直しが決まり、段階的に進みます。", acts:["共働きのご家庭では、夫が受け取れる遺族年金が限られる場合があることを伝え、見込みを確かめていただく", "お子様のいるご家庭では、遺族基礎年金が子の年齢で終わる時期も合わせて確かめる", "改正後の扱いは、日本年金機構の案内で確かめてから保障の話につなげる"], actHead:"現場で使うなら", note:"受け取れる要件・年齢・始まる時期は法律で決まり、2025年の改正で段階的に見直される。個別の見込みは日本年金機構・年金事務所で確かめる。", pre:1, say:"奥様に万一のことがあったとき、お子様のいるご家庭ではご主人も遺族基礎年金を受け取れます。遺族厚生年金には年齢などの要件があるので、見込みを確かめましょう。", more:"共働きで妻の収入が家計の大きな柱になっているご家庭ほど、妻の万一のときの備えが話題になります。今の制度では、夫が受け取れる遺族厚生年金は年齢などの要件で限られることがあり、改正後は男女で同じ考え方に近づきます。どの時点からどう変わるかは、生年月日と時期で違います。", why:"遺族年金は、もともと夫が家計を支える家庭を前提に作られていたため、夫が受け取る場合の要件が厳しくなっていました。共働きの広がりに合わせて、男女の差を小さくする見直しが進んでいます。" },
      { key:'faq_xnkn_saikon', faq:1, grp:'nkn', q:"遺族年金をもらっている人が再婚したら？", re:/遺族(厚生|基礎)?年金[^。]{0,16}(再婚|結婚|婚姻|事実婚になっ)|(再婚|結婚|婚姻)[^。]{0,16}(遺族(厚生|基礎)?年金|遺族の年金)|事実婚になっ[^。]{0,12}遺族/, ng:/受取人|保険金|生命保険|事実婚の妻でも|内縁の妻でも|事実婚でも(もらえ|受け取|出る)/, head:"遺族年金を受け取っている方が再婚（事実婚を含む）すると権利はなくなり、離婚しても戻りません。", body:"遺族年金は、受け取っている方が婚姻すると、その方の受け取る権利がなくなります。届け出をしていない事実婚も同じに扱われ、のちに離婚しても権利は戻りません。お子様の遺族基礎年金などは扱いが別に決まっています。受け取る権利がなくなったときは届け出が要り、気づかずに受け取り続けると、あとで返す必要が出ることがあります。", acts:["再婚を考えている方には、遺族年金がなくなることを先に年金事務所で確かめていただく", "再婚後の家計と保障を考えるときは、遺族年金が無くなる前提で見直す", "届け出の手続きは、日本年金機構の案内で確かめていただく"], actHead:"現場で使うなら", note:"権利がなくなる場面・届け出・お子様の分の扱いは法律で決まる。個別の扱いは日本年金機構・年金事務所で確かめる。", pre:1, say:"遺族年金を受け取っている方が再婚すると、事実婚を含めて受け取る権利がなくなり、あとで離婚しても戻りません。再婚の前に、家計の見通しを確かめておきましょう。", more:"再婚の相手の方の収入で暮らしを立てる前提に変わるので、家計の柱と保障の形を合わせて見直す場面になります。お子様の遺族基礎年金は、親が再婚しても子の権利は残る一方、受け取れるかは同居などの事情で決まりがあり、改正でも見直されます。", why:"遺族年金は、亡くなった方の収入で暮らしていたご家族の暮らしを支えるためのものなので、再婚して新しい家計を作ると、支える役目を終えたと考えられます。事実婚も暮らしの実態で同じに扱われます。" },
      { key:'faq_xnkn_jijitsukon', faq:1, grp:'nkn', q:"事実婚の妻でも遺族年金はもらえる？", re:/(事実婚|内縁)[^。]{0,16}(遺族(厚生|基礎)?年金|遺族の年金|年金)|(籍を入れて(い)?な|入籍して(い)?な|婚姻届を出して(い)?な)[^。]{0,16}(遺族|年金)/, ng:/控除|受取人|保険金|生命保険|個人年金|再婚|事実婚になっ|離婚/, head:"事実婚の妻でも、夫婦として暮らし生計を維持されていたと示せれば、遺族年金の対象になり得ます。", body:"遺族年金の配偶者には、婚姻の届け出をしていない事実婚の方も含まれます。ただし、事実上の夫婦として暮らしていたことと、亡くなった方に生計を維持されていたことを書類で示す必要があり、住民票や健康保険の扶養の記録、周りの方の証明などで確かめます。法律上の配偶者がほかにいる場合などは扱いが込み入り、個別に判断されます。子の有無などのほかの要件は、法律婚と同じです。", acts:["事実婚のご夫婦には、万一のときに事実婚を示す書類が要ることを、保障の話の前に伝える", "どんな書類で示せるかは、年金事務所で前もって確かめていただく", "法律上の配偶者がいるなど込み入った事情は、こちらで判断せず、年金事務所と弁護士につなぐ"], actHead:"現場で使うなら", note:"事実婚の認め方・生計維持の基準・要る書類は日本年金機構が決める。対象かどうかは年金事務所で、法律上の配偶者がいる場合などの判断は弁護士に確かめる。", pre:1, say:"事実婚の方でも、夫婦として暮らし、生計を支えられていたことを示せれば、遺族年金の対象になり得ます。どんな書類が要るか、年金事務所で確かめておきましょう。", more:"遺族年金の請求では、事実婚の関係を示すために、住民票の写しや、二人が一緒に暮らしていたことが分かる書類、周りの方の申し立ての書類などを求められることがあります。日頃の記録の残し方で示しやすさが変わるので、事実婚のご夫婦は、前もって窓口で要る書類を聞いておくと、手続きのときに慌てずに済みます。", why:"公的年金は、届け出の有無より、実際に夫婦として暮らし、家計を支え合っていたかという暮らしの実態を見る作りだからです。その分、実態を示す書類が要ります。" },
      { key:'faq_xnkn_seikei', faq:1, grp:'nkn', q:"妻に収入があると遺族年金は出ない？", re:/(妻|夫|配偶者|奥様|ご主人)[^。]{0,10}(収入|年収|給料|給与|稼ぎ)[^。]{0,16}遺族(厚生|基礎)?年金|共働き[^。]{0,10}遺族(厚生|基礎)?年金|遺族(厚生|基礎)?年金[^。]{0,10}(収入|年収)[^。]{0,8}(制限|基準|要件|条件|がある|あると|多い|高い)|生計維持[^。]{0,12}遺族|遺族[^。]{0,12}生計維持|(妻|奥様|奥さん|配偶者)[^。]{0,4}(が|は|も)?(働いて|仕事をして|勤めて|正社員|会社員|パートで|パートを)[^。]{0,12}遺族(厚生|基礎)?年金/, ng:/保険金|生命保険|収入保障|税|控除|再婚|事実婚|内縁|加給|障害/, head:"妻に収入があっても、国の定める基準より少なければ、遺族年金の収入の要件は満たします。", body:"遺族年金を受け取るには、亡くなった方に生計を維持されていたことが要件の一つで、生計を同じくしていたことと、受け取る方の収入が国の定める基準より少ないことで判断します。基準は年収の目安で決められていて、働いている妻でも、基準より少なければ当てはまります。基準を超えていても、近いうちに退職するなどで収入が下がると見込まれる事情があれば、認められる場合があります。", acts:["共働きのご家庭にも、遺族年金は出ないと決めつけず、収入の基準で決まると伝える", "基準の額と、収入をどの時点のもので見るかは、年金事務所で確かめていただく", "遺族年金を保障の話に入れるときは、受け取れる前提かを先に確かめてから組み立てる"], actHead:"現場で使うなら", note:"生計維持の収入の基準・収入を見る時点・基準を超えるときの例外は日本年金機構が決める。個別の判断は年金事務所で確かめる。", pre:1, say:"奥様に収入があっても、国の定める基準より少なければ、遺族年金を受け取る要件の一つを満たします。共働きだから出ないと決めつけずに、確かめてみましょう。", more:"収入の基準とは別に、生計を同じくしていたことも見られます。単身赴任などで別に暮らしていても、仕送りや行き来があれば、生計を同じくしていたと認められることがあります。どちらも、亡くなった当時の事情で判断されます。子のいない配偶者の扱いは2025年の改正で見直されるので、案内で確かめます。", why:"遺族年金は、亡くなった方の収入で暮らしていたご家族を支えるための年金なので、ご自身の収入で十分に暮らせる方を外すために、収入の基準を設けています。" },
      { key:'faq_xnkn_izoku_seikyu', faq:1, grp:'nkn', q:"遺族年金の請求はどうする？", re:/遺族(厚生|基礎)?年金[^。]{0,12}(請求|申請|手続|もらう方法|受け取る方法|どこに|どこで|窓口|書類|必要なもの|要るもの)/, ng:/税|確定申告|申告|保険金|生命保険|忘れ|時効|遅れ|前に(説明|伝え)/, head:"遺族年金は、年金事務所などに年金請求書と、戸籍・住民票・収入などの書類を出して請求します。", body:"請求先は、年金事務所か街角の年金相談センターで、遺族基礎年金だけを請求する場合などは、市区町村の窓口が受け付けることもあります。年金請求書のほか、戸籍の書類、世帯の住民票、亡くなったことが分かる書類、請求する方の収入が分かる書類、受け取る口座の書類などが要り、マイナンバーで省ける書類もあります。請求しないと受け取れず、時効もあります。", acts:["ご遺族から相談を受けたら、まず年金事務所に予約して、要る書類を確かめていただくよう案内する", "亡くなった方の基礎年金番号が分かるものを、手元に用意していただく", "書類の集め方や書き方の代行はこちらでせず、難しいときは社会保険労務士につなぐ"], actHead:"現場で使うなら", note:"請求先・要る書類・時効は日本年金機構が決める。個別の書類は年金事務所・市区町村で確かめる。請求の代行は社会保険労務士の業務。", pre:1, say:"遺族年金は、年金事務所などに書類を出して請求すると受け取れます。要る書類は事情で変わるので、まず年金事務所に予約して確かめましょう。", more:"ご家族を亡くしたばかりの時期は、葬儀や役所の手続きが重なります。遺族年金は、時効の範囲なら、亡くなった翌月の分からさかのぼって受け取れるので、落ち着いた頃に年金事務所の予約を取るよう、ご家族に一言添えると親切です。生命保険の請求とは、窓口も書類も別です。", why:"公的年金は、受け取る権利があっても、自分で請求して初めて支払いが始まる作りです。請求の書類で、亡くなった方との関係や生計の事情を確かめるためです。" },
      { key:'faq_xnkn_chukorei', faq:1, grp:'nkn', q:"中高齢寡婦加算とは？", re:/寡婦加算/, ng:/寡婦控除|ひとり親/, head:"中高齢寡婦加算は、一定の年齢の妻が受け取る遺族厚生年金に、一定の年齢まで上乗せされるお金です。", body:"夫が亡くなったときに一定の年齢以上で子のいない妻や、子が大きくなって遺族基礎年金を受け取れなくなった一定の年齢の妻には、遺族基礎年金が無い分を補うため、遺族厚生年金に中高齢寡婦加算が付きます。一定の年齢で終わり、生年月日によっては、そのあと経過的寡婦加算に切り替わります。夫の厚生年金の加入期間などの要件があり、2025年の改正で段階的に見直されます。", acts:["子のいないご夫婦や、お子様が大きいご家庭の保障の話では、中高齢寡婦加算が付くかを年金事務所で確かめていただく", "加算が終わる時期と、その後のご自身の年金の見込みを一緒に並べる", "改正の影響は生年月日と時期で違うので、言い切らずに日本年金機構の案内で確かめる"], actHead:"現場で使うなら", note:"対象の年齢・夫の加入期間の要件・額・経過的寡婦加算の生年月日の区切りは法律で決まり、2025年の改正で見直される。日本年金機構・年金事務所で確かめる。", pre:1, say:"中高齢寡婦加算は、子のいない妻などが受け取る遺族厚生年金に、一定の年齢まで上乗せされるものです。対象になるかは年齢と記録で決まるので、確かめてみましょう。", more:"例えば、夫が亡くなったときに妻が一定の年齢以上で子がいないと、遺族基礎年金は出ませんが、遺族厚生年金に中高齢寡婦加算が付くことがあります。お子様がいるご家庭では、お子様が大きくなって遺族基礎年金が終わったあとに、加算が始まる形もあります。", why:"遺族基礎年金は子のいる家庭のための年金なので、子のいない中高年の妻は受け取れません。就職して暮らしを立て直すのに時間がかかる年代の妻を、ご自身の年金が始まるまで支えるために設けられました。" },
      { key:'faq_xnkn_mae_shibou', faq:1, grp:'nkn', q:"年金をもらう前に亡くなったら、払った保険料は戻る？", re:/(年金を?(もらう|受け取る|受給する|もらい始める|受け取り始める)前に|受給前に|(もらわず|受け取らず)に)[^。]{0,12}(亡くな|死亡|死ん|死去)|(国民年金|厚生年金|年金の保険料|年金保険料)[^。]{0,10}(払った|納めた|払って|納めて)[^。]{0,8}(亡くな|死亡|死ん)|年金[^。]{0,16}(もらう|受け取る|受給する|もらい始める|受け取り始める)前に[^。]{0,8}(亡くな|死亡|死ん|死去)/, ng:/個人年金|企業年金|ideco|イデコ|確定拠出|生命保険|保険金|受取人|解約|繰り?下げ|待機/, head:"払った保険料は戻りませんが、要件を満たせば、遺族年金や死亡一時金などがご遺族に出ます。", body:"公的年金は貯金ではなく社会保険なので、受け取る前に亡くなっても、納めた保険料そのものは戻りません。その代わり、要件を満たすご遺族には遺族基礎年金や遺族厚生年金が出ます。遺族基礎年金を受け取れる方がいないときは、国民年金の保険料を一定の期間以上納めていた方なら、ご遺族に寡婦年金か死亡一時金のどちらかが出ることがあります。受け取る権利が生まれていた分は、未支給年金として請求できます。", acts:["払い損だという声には、保険料が戻る仕組みではなく、ご遺族への給付があるという中身を伝える", "自営業などで国民年金だけのご家庭は、ご遺族への給付が限られることを保障の話の前に確かめる", "どの給付が出るかは要件で決まるので、年金事務所で確かめていただく"], actHead:"現場で使うなら", note:"寡婦年金・死亡一時金・遺族年金の要件と、どれを選ぶかの決まりは法律で決まる。日本年金機構・年金事務所で確かめる。", pre:1, say:"年金を受け取る前に亡くなっても、払った保険料は戻りませんが、ご家族に遺族年金などが出ることがあります。どれが出るかは、記録とご家族の状況で決まります。", more:"例えば、自営業の夫が国民年金だけに入っていて、子のいない妻が残された場合は、遺族基礎年金も遺族厚生年金も出ないことがあります。そのときに、夫が保険料を納めた期間などの要件を満たしていれば、妻は寡婦年金か死亡一時金のどちらか一つを選びます。", why:"公的年金は、長生きや障害、家計を支える人の死に備える保険の仕組みなので、亡くなった方本人に保険料を返すのではなく、残されたご家族の暮らしを支える形で給付します。" },
      { key:'faq_xnkn_noufu', faq:1, grp:'nkn', q:"未納があると障害年金や遺族年金は出ない？", re:/(未納|払っていな|納めていな|払ってない|納めてない|滞納)[^。]{0,16}(障害(基礎|厚生)?年金|遺族(基礎|厚生)?年金)|(障害(基礎|厚生)?年金|遺族(基礎|厚生)?年金)[^。]{0,16}(未納|納付要件|払っていな|納めていな|払ってない)|納付要件/, ng:/民間|保険金|生命保険|就業不能|所得補償|払込免除|失効/, head:"障害年金と遺族年金には保険料を納めた期間の要件があり、未納が多いと出ないことがあります。", body:"障害年金は初めて病院にかかった日の前日の時点で、遺族年金は亡くなった日の前日の時点で、それまでの加入期間のうち保険料を納めた期間と免除などの期間が一定の割合以上あるか、直前の一定の期間に未納が無いことが要件です。その日のあとで納めても数えられません。免除や猶予の期間は、要件では納めた期間と合わせて数えます。国民年金に入る前の病気などには別の扱いがあり、受給資格を満たしていた方が亡くなった場合も別の要件で見ます。", acts:["未納のあるお客様には、病気やけがの前に、免除や猶予の申請で未納を残さないことが大事だと伝える", "要件を満たすかは初診日や亡くなった日の記録で決まるので、年金事務所で確かめていただく", "民間の保険の話の前に、公的な保障が受けられる状態かを先に確かめる"], actHead:"現場で使うなら", note:"納付の要件の割合・期間・特例の期限は法律で決まり改定される。要件を満たすかは日本年金機構・年金事務所で確かめる。", pre:1, say:"障害年金や遺族年金は、未納が多いと出ないことがあります。払えないときは、未納のままにせず免除や猶予を申請しておくと、要件のうえでは納めた期間と合わせて数えられます。", more:"例えば、未納の期間が長い方が、病気で初めて病院にかかったあとで、さかのぼって納めても、その病気の障害年金の要件には数えられません。免除や猶予の申請は、さかのぼれる範囲が決まっているので、払えないと分かった時点で、市区町村や年金事務所に相談します。", why:"公的年金は保険の仕組みなので、保険料を納めて支える側にいた方に給付するという考え方で、納付の要件を設けています。病気になってから納めて給付を受けることを防ぐため、その日より前の記録で見ます。" },
      { key:'faq_xnkn_shuro', faq:1, grp:'nkn', q:"障害年金をもらいながら働ける？", re:/障害(基礎|厚生)?年金[^。]{0,16}(働|仕事|就職|就労|勤め|給料|給与|収入|復職)|(働|仕事|就職|就労|復職)[^。]{0,16}障害(基礎|厚生)?年金/, ng:/就業不能|所得補償|払込免除|民間|保険金|在職老齢/, head:"障害年金は、働いて収入があっても、それだけで止まる仕組みではありません。", body:"障害年金は障害の状態で決まるので、働いていることだけで止まることはありません。ただし、更新のときの書類で、働き方や仕事の内容が障害の状態を見る材料の一つになることがあり、病気の種類によって扱いが違います。国民年金に入る前の病気などによる障害基礎年金には、所得による制限があります。厚生年金に入って働いても、障害厚生年金が給与で減る仕組みはありません。", acts:["障害年金を受け取っている方が働き始めるときは、止まると決めつけず、更新の扱いを年金事務所で確かめていただく", "更新の書類は医師に書いていただくものなので、働き方や困りごとを主治医にありのまま伝えるよう話す", "等級に当たるかの判断はこちらでせず、年金事務所や社会保険労務士につなぐ"], actHead:"現場で使うなら", note:"障害の状態の見方・所得による制限・更新の扱いは日本年金機構が決める。個別の判断は年金事務所・社会保険労務士で確かめる。", pre:1, say:"障害年金は、働いているだけで止まるものではありません。更新のときに働き方が見られることはあるので、主治医にありのままを伝えることが大事です。", more:"例えば、心の病気で障害年金を受け取っている方が短い時間から働き始めた場合、更新のときに、働いている時間や職場の配慮なども含めて状態が見られます。働けているから等級が変わると決まるわけではなく、働く中での困りごとも含めて判断されます。", why:"障害年金は、障害によって暮らしや仕事に生じる不自由を支えるためのもので、収入そのものではなく障害の状態で決める作りだからです。" },
      { key:'faq_xnkn_shogai_seikyu', faq:1, grp:'nkn', q:"障害年金の請求は自分でできる？", re:/障害(基礎|厚生)?年金[^。]{0,12}(請求|申請|手続|申し込|もらう方法|受け取る方法|窓口|書類|社労士|社会保険労務士|代行|自分で)/, ng:/就業不能|所得補償|払込免除|民間|保険金|給付金|税|さかのぼ|遡|認定日|事後重症|更新|障害状態確認届|忘れ|時効|両方|併給/, head:"障害年金の請求はご本人やご家族でもでき、初診日の証明や医師に書いていただく書類などをそろえます。", body:"請求先は年金事務所などで、障害基礎年金だけを請求する場合などは、市区町村の窓口でも受け付けることがあります。初めて病院にかかった日を示す書類、障害の状態について医師に書いていただく書類、発病からの経過や暮らしの様子を書く申立書、年金請求書などをそろえます。初めにかかった病院の記録が残っていないなど、書類集めが難しいときは、社会保険労務士に頼む方法もあります。", acts:["請求を考えている方には、まず年金事務所に予約して、初診日と要る書類を確かめるよう案内する", "書類の中身や等級の見込みをこちらで判断せず、難しいときは社会保険労務士を紹介できるようにしておく", "民間の保険の給付金の請求とは別の手続きだと、分けて伝える"], actHead:"現場で使うなら", note:"要る書類・請求先は日本年金機構が決める。障害年金の請求の代行は社会保険労務士の業務で、等級の判断は日本年金機構が行う。", pre:1, say:"障害年金の請求は、ご本人やご家族でもできます。まず年金事務所に予約して、初めて病院にかかった日と、要る書類を確かめるところから始めましょう。", more:"障害年金でつまずきやすいのは、初めて病院にかかった日の証明です。何年も前に別の病院に通っていた場合、その病院の記録が残っていないこともあります。申立書は、発病から今までの経過を、暮らしや仕事の困りごとも含めて書くもので、医師に書いていただく書類と食い違わないよう気をつけます。", why:"障害年金は、初めて病院にかかった日を基準に、入っていた制度や保険料の納め方を見て決まる作りなので、その日を示す書類と、今の障害の状態を示す書類の両方が要ります。" },
      { key:'faq_xnkn_koushin', faq:1, grp:'nkn', q:"障害年金はずっともらえる？", re:/障害(基礎|厚生)?年金[^。]{0,12}(ずっと|一生|いつまで|更新|打ち切|止ま|なくな|支給停止|期限|有期)|障害状態確認届/, ng:/就業不能|所得補償|払込免除|民間|保険金|老齢|両方|併給|働|仕事|就職|就労|未納/, head:"障害年金は、状態が変わり得る場合、決まった時期に更新があり、続くか変わるか止まるかが決まります。", body:"障害の状態が変わり得る病気などでは、決まった年ごとに、医師に書いていただく書類（障害状態確認届）を出す更新があります。結果によって、同じ等級で続く、等級が変わる、支給が止まる、のいずれかになります。止まったあとで状態が重くなれば、届け出で受け取りが戻ることがあります。手足の障害などで状態が変わらないと判断された場合は、更新が無いこともあります。", acts:["障害年金を受け取っている方には、更新の書類が届く時期と、出し忘れると止まることがあると伝える", "更新の書類は医師に書いていただくものなので、今の暮らしの様子を主治医に伝えておくよう話す", "等級が変わる見込みはこちらで判断せず、年金事務所や社会保険労務士につなぐ"], actHead:"現場で使うなら", note:"更新の時期・書類・止まったあとの届け出は日本年金機構が決める。結果の判断は日本年金機構が行う。相談は年金事務所・社会保険労務士へ。", pre:1, say:"障害年金は、病気によっては決まった時期に更新があり、医師に書いていただく書類で状態を確かめます。書類が届いたら、出し忘れないようにしましょう。", more:"更新の書類は、提出の期限より前に届きます。主治医に書いていただくのに時間がかかることもあるので、届いたら早めに頼みます。また、ご自身の老齢年金を受け取る年齢になると、障害年金と老齢年金の組み合わせを選ぶ場面が来ます。", why:"障害の状態は、治療や時間の経過で変わることがあるので、受け取る方の今の状態に合った年金にするため、更新で確かめる作りになっています。" },
      { key:'faq_xnkn_sokyu', faq:1, grp:'nkn', q:"障害年金はさかのぼってもらえる？", re:/障害(基礎|厚生)?年金[^。]{0,16}(さかのぼ|遡|過去の分|前の分|まとめて)|障害認定日|認定日請求|事後重症/, ng:/就業不能|所得補償|払込免除|民間|保険金/, head:"障害認定日の頃に障害の状態だったと書類で示せれば、時効の範囲でさかのぼって受け取れます。", body:"障害年金は、初めて病院にかかった日から一定の期間がたった障害認定日の状態で請求するのが基本で、その頃の状態を医師に書いていただく書類で示せれば、請求が遅れても、時効の範囲でさかのぼって受け取れます。障害認定日の頃は軽かった方や、その頃の記録が取れない方は、請求した時点の状態で判断する請求になり、受け取りは請求の翌月の分からです。", acts:["長く治療を続けている方には、さかのぼって請求できる場合があると伝え、年金事務所で確かめていただく", "障害認定日の頃の病院の記録が要るので、通っていた病院に記録が残っているかを確かめていただく", "どちらの請求になるかの判断はこちらでせず、年金事務所や社会保険労務士につなぐ"], actHead:"現場で使うなら", note:"障害認定日の決まり・時効の期間・請求の種類は法律で決まる。個別の判断は日本年金機構・年金事務所・社会保険労務士で確かめる。", pre:1, say:"障害年金は、障害認定日の頃の状態を書類で示せれば、時効の範囲でさかのぼって受け取れることがあります。まず年金事務所で、どちらの請求になるかを確かめましょう。", more:"例えば、何年も前から治療を続けていて、障害年金を知らずに請求していなかった方は、障害認定日の頃に通っていた病院の書類が取れるかどうかで、受け取れる範囲が変わります。病院の記録には残しておく期限があるので、気づいた時点で確かめるのが大事です。", why:"障害年金は、初めて病院にかかってから一定の期間がたった時点を、障害の状態を判断する基準の日としているので、その日の状態が分かれば、その時点からの受け取りを認める作りです。" },
      { key:'faq_xnkn_shogai_gaku', faq:1, grp:'nkn', q:"障害年金の額は何で決まる？", re:/障害(基礎|厚生)?年金[^。]{0,8}(の)?(額|金額|年金額|いくら|どれくらい|どのくらい|計算|何で決ま)/, ng:/就業不能|所得補償|払込免除|民間|保険金|両方|併給|老齢|税|働|仕事|給料|給与/, head:"障害年金の額は、障害の等級と、厚生年金の加入記録と、条件に合うご家族の有無で決まります。", body:"障害基礎年金は等級ごとに決まった額で、重い等級ほど多く、条件に合う子がいると加算があります。障害厚生年金は、老齢厚生年金と同じく給与と加入期間で計算し、加入期間が短い方は一定の月数があったものとして計算する仕組みがあり、重い等級では配偶者の加算が付くことがあります。厚生年金には、軽い等級の年金と一時金もあります。額は毎年度改定されます。", acts:["障害年金の見込みは等級に当たるかで大きく変わるので、こちらで額を言い切らない", "会社員の方には、障害厚生年金があるかどうかで額が変わることを伝え、記録を確かめていただく", "保障の話では、公的な障害年金を土台に、足りない分を考える順番で話す"], actHead:"現場で使うなら", note:"等級ごとの額・加算・加入期間のみなしの月数は法律で決まり、毎年度改定される。等級の判断と額は日本年金機構・年金事務所で確かめる。", pre:1, say:"障害年金の額は、障害の等級と、厚生年金の記録、ご家族の状況で決まります。等級に当たるかで大きく変わるので、見込みは年金事務所で確かめましょう。", more:"例えば、会社員の期間に初めて病院にかかった病気なら、重い等級では障害基礎年金に障害厚生年金が上乗せされ、軽い等級でも障害厚生年金が出ることがありますが、自営業の期間なら障害基礎年金だけです。初めて病院にかかった日にどの制度に入っていたかで、受け取れる年金の種類そのものが変わります。", why:"障害年金は、障害の重さに応じて暮らしの不自由を支え、厚生年金に入っていた方には働いていた頃の給与に応じた上乗せをする作りなので、等級と加入記録の両方で額が決まります。" },
      { key:'faq_xnkn_heikyu', faq:1, grp:'nkn', q:"障害年金と老齢年金は両方もらえる？", re:/障害(基礎|厚生)?年金[^。]{0,12}(老齢|自分の年金|ほかの年金|他の年金|遺族)[^。]{0,16}(両方|一緒|同時|併給|併せ|合わせ|どちら|組み合わせ|もらえ|受け取)|(老齢|遺族)(基礎|厚生)?年金[^。]{0,12}障害(基礎|厚生)?年金[^。]{0,8}(両方|一緒|同時|併給|組み合わせ|どちら)|障害(基礎|厚生)?年金[^。]{0,16}(6[0-9]|7[0-9])歳(になっ|から|以降|を過ぎ)|(6[0-9]|7[0-9])歳(になっ|から|以降|を過ぎ)[^。]{0,12}障害(基礎|厚生)?年金|(年金を受け取る|年金をもらう|年金の)年齢[^。]{0,12}障害(基礎|厚生)?年金|一人一年金|併給調整/, ng:/就業不能|所得補償|払込免除|民間|保険金|税金がかか|課税|確定申告/, head:"年金は一人一つが原則で選びますが、一定の年齢からは障害基礎年金と老齢厚生年金を組み合わせられます。", body:"公的年金は一人一つが原則で、障害年金と老齢年金の権利が両方あるときは、どちらかを選びます。一定の年齢からは、障害基礎年金と老齢厚生年金、障害基礎年金と遺族厚生年金のような組み合わせも選べます。どの組み合わせが多くなるかは記録で違い、税の扱いも年金の種類で違うので、年金事務所で額を出していただいて選びます。", acts:["障害年金を受け取っている方が年金を受け取る年齢に近づいたら、組み合わせを選ぶ場面があると伝える", "どの組み合わせにするかは額と税の扱いで変わるので、額は年金事務所、税は税理士・税務署に確かめていただく", "繰上げを考えている方には、障害年金との関係で注意があることを年金事務所で確かめていただく"], actHead:"現場で使うなら", note:"組み合わせられる年金と選び方の決まりは法律で決まる。額は日本年金機構・年金事務所、税の扱いは税理士・税務署で確かめる。", pre:1, say:"年金は一人一つが原則なので、障害年金と老齢年金は選ぶ形になりますが、一定の年齢からは組み合わせて受け取れることがあります。どの形が合うかは、額を出してもらってから考えましょう。", more:"例えば、障害基礎年金を受け取りながら会社員として働いてきた方は、一定の年齢から、障害基礎年金と老齢厚生年金を組み合わせる形を選べます。障害年金は税がかからない一方、老齢年金は税の対象になるので、額だけでなく手取りでも比べます。", why:"一人一年金は、同じ方に年金が重なりすぎないようにする決まりですが、障害がありながら働いて納めた保険料が年金に生きるよう、一定の年齢からの組み合わせが認められています。" },
      { key:'faq_xnkn_jikou', faq:1, grp:'nkn', q:"年金の請求を忘れていたらどうなる？", re:/(年金|老齢年金|遺族年金|障害年金)[^。]{0,12}(請求)?[^。]{0,4}(忘れ|していなかった|してなかった|しそびれ|出し忘れ|時効)|(もらい忘れ|受け取り忘れ|請求し忘れ|請求を忘れ)[^。]{0,8}年金/, ng:/個人年金|企業年金|ideco|イデコ|確定拠出|保険会社|保険金|給付金|振込|振り込|天引|手取り|保険料/, head:"年金の請求を忘れていても気づいた時点で請求できますが、時効にかかった古い分は受け取れません。", body:"年金は、受け取る権利が生まれても、請求しないと支払われません。請求が遅れても、気づいた時点で請求すれば、時効にかかっていない期間の分はさかのぼってまとめて受け取れますが、それより古い分は受け取れなくなります。記録の誤りが直ったことで年金が増えた場合などは、時効にかかわらず受け取れる特例があります。遺族年金や障害年金、未支給年金にも時効があります。", acts:["受け取る年齢を過ぎても請求していないお客様に気づいたら、年金事務所で確かめるよう早めに伝える", "ご家族が亡くなったあとの未支給年金や遺族年金にも、時効があると伝える", "さかのぼって受け取ると税や保険料に関わることがあるので、税は税理士・税務署に確かめていただく"], actHead:"現場で使うなら", note:"時効の期間・特例の対象・さかのぼる受け取りの決まりは法律で決まる。日本年金機構・年金事務所で確かめる。税は税理士・税務署へ。", pre:1, say:"年金は、請求を忘れていても、気づいた時点で請求すれば受け取れますが、時効にかかった古い分は受け取れません。気づいたら、年金事務所で確かめましょう。", more:"例えば、特別支給の老齢厚生年金は、受け取りを遅らせても額が増える仕組みが無いので、請求しないままだと、古い分から時効で受け取れなくなります。繰下げのつもりで待っていた方がさかのぼって受け取るときは、受け取り方の選び方に決まりがあるので、年金事務所で額を出していただいてから決めます。", why:"時効は、権利を長く使わずにいると消えるという法律の決まりで、年金も支払いごとに時効が進みます。記録の誤りのように本人の落ち度でない場合は、特例で受け取れるようにしています。" },
      { key:'faq_xnkn_kako_minou', faq:1, grp:'nkn', q:"昔の国民年金の未納は、今から納められる？", re:/(昔|以前|若い(頃|ころ|とき|時)|学生(時代|の頃|のころ|のとき|の時)|過去)[^。]{0,10}(の)?[^。]{0,6}(未納|払っていな|払ってな|納めていな|納めてな|払わなかった|納めなかった)|(未納|未払い)[^。]{0,6}(の)?(分|期間|月)[^。]{0,12}(後から|あとから|今から|さかのぼ|遡|払え|納め|払いた|納めた|埋め)|(国民年金|年金の保険料|年金保険料)[^。]{0,10}(さかのぼ|遡)[^。]{0,6}(払|納)|(国民年金|年金)[^。]{0,4}(の)?(未納|未払い)(の)?(期間|分|月)が(ある|あった)/, ng:/障害|遺族|免除|猶予|学生納付特例|学生特例|追納|生命保険|個人年金|ideco|イデコ|確定拠出|厚生年金|督促|催告|差し押さえ|延滞/, head:"昔の未納は、時効の範囲の分なら後から納められますが、それより古い分は納められません。", body:"国民年金の保険料は、時効にかかっていない分なら後から納められますが、時効を過ぎた古い未納の分は納められず、その月は老齢基礎年金に反映されません。免除や学生納付特例などを申請していた期間なら、一定の期間のうちは追納できます。満額に足りない方は、国民年金に入る期間が終わったあとに任意加入して、納めた月を足す道があります。未納の月があるかは、ねんきん定期便とねんきんネットで確かめられます。", acts:["昔の未納を気にしているお客様とは、ねんきん定期便で未納の月を一緒に見て、時効にかかっていない分があるかを年金事務所で確かめていただく", "免除や学生納付特例を申請していた期間なら、追納できる期間を年金事務所で確かめていただく", "満額に足りない方には、任意加入で納めた月を足す道があると伝える"], actHead:"現場で使うなら", note:"後から納められる範囲（時効）・追納できる期間・任意加入の条件は法律で決まる。未納の月と納められる分は日本年金機構・年金事務所で確かめる。", pre:1, say:"昔の未納は、時効にかかっていない分なら後から納められますが、それより古い分は納められません。満額に足りないときは、任意加入で納めた月を足す道があります。", more:"例えば、学生のころに学生納付特例を申請していれば、一定の期間のうちは追納して年金に反映できますが、申請せずに未納のままだった古い分は、もう納められません。後から納めた保険料は老齢基礎年金に反映されますが、病気やけがで初めて病院にかかった日のあとに納めた分は、障害年金の納付の要件には数えられません。", why:"保険料を集める側の権利にも時効があり、長く納めずにいた分は、もう納められなくなります。一方、免除や猶予は、納めるのが難しい時期に申請で受けるものなので、暮らしが落ち着いたあとに追納して年金に反映できる道が残されています。" },
      { key:'faq_xnkn_minou', faq:1, grp:'nkn', q:"国民年金を払わないとどうなる？", re:/(国民年金|年金の保険料|年金保険料)[^。]{0,10}(払わな|払ってな|払っていな|納めな|納めてな|納めていな|払えな|払えず|未納|滞納|払い忘れ|納め忘れ)[^。]{0,16}(どうな|いい|大丈夫|困る|督促|差し押さえ|ばれ|届い|来た|来る|どうす|どうしたら|問題|放って|そのまま)|(国民年金|年金の保険料)[^。]{0,8}(督促|催告|差し押さえ|延滞金)|(国民年金|年金の保険料|年金保険料)[^。]{0,6}(が|を|は)?[^。]{0,4}(払えな|払えず|納められな|納めるのが(難し|苦し|厳し)|払うのが(難し|苦し|厳し))/, ng:/障害|遺族|生命保険|民間|個人年金|ideco|イデコ|意味がな|意味ない|払い損|元が取れ|払いたくな|免除|猶予|学生納付特例|学生特例|追納|出産|産前|産後|妊娠|昔|以前|若い頃|若いころ|学生時代|学生の頃|学生のころ|過去/, head:"国民年金を未納のままにすると年金が減り、納付の催促も届くので、払えないときは免除や猶予を申請します。", body:"納めていない月は老齢基礎年金に反映されず、未納が多いと、障害年金や遺族年金の納付の要件を満たせないことがあります。納めずにいると催告の通知が届き、所得などの事情によっては、督促を経て延滞金が付いたり、財産を差し押さえられたりすることがあります。払えない事情があるときは、未納のままにせず、免除や納付猶予を申請すると、要件のうえでは未納と扱いが違います。納め忘れた分は、時効の範囲なら後から納められます。", acts:["国民年金を納めていないお客様には、責めずに、払えない事情があれば免除や猶予の申請があると伝える", "申請の窓口は、住所地の市区町村の国民年金の窓口か年金事務所だと案内する", "納め忘れた分を後から納められるかは、時効の範囲を年金事務所で確かめていただく"], actHead:"現場で使うなら", note:"督促・延滞金・差し押さえの扱い、免除と猶予の基準、後から納められる期間は法律で決まる。日本年金機構・年金事務所・市区町村で確かめる。", pre:1, say:"国民年金を納めずにいると、老後の年金が減るだけでなく、障害や遺族の年金が出ないこともあります。払うのが苦しいときは、免除や猶予の申請という道があります。", more:"免除は、所得に応じて保険料の全てか一部を免除する仕組みで、免除の期間も度合いに応じて老齢基礎年金に反映されます。納付猶予や学生納付特例は、反映されない代わりに、要件のうえでは納めた期間と合わせて数えます。どちらも、あとから追納すれば老齢基礎年金に反映できます。", why:"国民年金は、法律で入ることと納めることが決まっている社会保険なので、納めない人をそのままにすると支え合いが成り立ちません。その一方で、払えない事情の方のために、免除や猶予の道を用意しています。" },
      { key:'faq_xnkn_zennou', faq:1, grp:'nkn', q:"国民年金の保険料をまとめて払う方法は？", re:/(国民年金|年金の保険料|年金保険料)[^。]{0,12}(前納|まとめて(払|納)|一括で?(払|納)|クレジットカード|カードで(払|納)|口座振替|口座から|引き落とし|納付書|コンビニ|納め方|払い方|安く|割引|早割)|(前納|まとめ払い)[^。]{0,8}(国民年金|年金の保険料)/, ng:/控除|生命保険|個人年金|ideco|イデコ|民間|払えな|払わな|未納|免除|猶予|厚生年金|給与|給料/, head:"国民年金の保険料は、まとめて前納すると割引があり、口座振替やクレジットカードでも納められます。", body:"国民年金の保険料は、毎月納める方法のほか、決まった期間の分をまとめて前納する方法があり、前納する期間が長いほど割引が大きくなります。口座振替、クレジットカード、納付書で納められ、口座振替には早めに引き落とす分の割引がある形もあります。前納の申し込みには締め切りがあり、選べる期間は納め方で違います。会社に勤めて厚生年金に入るなどで納める必要がなくなった月の分は、戻る扱いがあります。", acts:["まとめて納めたい方には、前納の期間と納め方で割引が違うことを伝え、日本年金機構の案内で確かめていただく", "前納の申し込みには締め切りがあるので、時期を年金事務所で確かめていただく", "前納した保険料の税の扱いは、税理士・税務署に確かめていただく"], actHead:"現場で使うなら", note:"前納の期間・割引・申し込みの締め切り・戻る扱いは日本年金機構が決める。年金事務所で確かめる。税の扱いは税理士・税務署へ。", pre:1, say:"国民年金の保険料は、まとめて前納すると割引があり、口座振替やクレジットカードでも納められます。申し込みの時期が決まっているので、案内で確かめましょう。", more:"例えば、自営業を始めた方が毎月の納め忘れを防ぎたいときは、口座振替で前納する形があります。途中で会社に勤めて厚生年金に入った場合は、その後の月の分は戻る扱いがあります。付加保険料も一緒に前納できる場合があります。払うのが苦しいときは、前納ではなく免除や猶予を考えます。", why:"前もってまとめて納めていただくと、納める側は納め忘れを防げ、集める側は手間が減るので、その分を割引として返す作りです。" },
      { key:'faq_xnkn_sanzen', faq:1, grp:'nkn', q:"出産のとき国民年金の保険料は免除される？", re:/(国民年金|年金の保険料|年金保険料)[^。]{0,16}(出産|産前|産後|妊娠|出産予定)|(出産|産前|産後|妊娠)[^。]{0,16}(国民年金|年金の保険料|年金保険料)/, ng:/厚生年金|育休|育児休業|出産手当金|出産育児一時金|会社員/, head:"自分で国民年金に入っている方は、出産の前後の一定の期間、届け出で保険料が免除されます。", body:"自営業の方や学生など、自分で国民年金に入っている方は、出産の前後の一定の期間、届け出をすると国民年金の保険料が免除されます。この期間は、ほかの免除と違い、保険料を納めた期間として老齢基礎年金に反映されます。届け出は住所地の市区町村の窓口で、出産の予定日の前から出せ、出産のあとでも出せます。会社員などで厚生年金に入っている方には、産前産後休業の間の別の仕組みがあります。", acts:["自営業や学生のお客様が出産を控えているときは、国民年金の保険料の免除の届け出があると伝える", "届け出の窓口と時期は、住所地の市区町村の国民年金の窓口で確かめていただく", "会社員の方の産前産後休業の間の扱いは別なので、勤め先に確かめていただく"], actHead:"現場で使うなら", note:"免除の期間・届け出の時期・対象の方は法律で決まる。届け出は市区町村の国民年金の窓口、詳しくは日本年金機構・年金事務所で確かめる。", pre:1, say:"ご自身で国民年金に入っている方は、出産の前後の一定の期間、届け出で保険料が免除され、その期間も納めた期間として年金に反映されます。市区町村の窓口に届け出ましょう。", more:"ほかの免除は、度合いに応じて年金の額への反映が少なくなりますが、出産の前後の免除は、納めた期間と同じに扱われるのが違いです。双子などの場合は免除の期間が長くなります。国民健康保険の保険料にも出産の前後の軽減の仕組みがあり、こちらも市区町村で確かめます。", why:"出産の前後は働くのが難しく収入が減りやすい時期なので、会社員の産前産後休業の間の仕組みと同じように、自営業の方なども年金を減らさずに済むよう設けられました。" },
      { key:'faq_xnkn_taishoku', faq:1, grp:'nkn', q:"会社を辞めたら国民年金の手続きは要る？", re:/(会社を辞め|退職|離職|独立|脱サラ|失業|開業)[^。]{0,16}(年金|国民年金|厚生年金)[^。]{0,12}(手続|切り替|切替|届|どうな|どうす|入り直|変わ|要る)|(国民年金|年金)[^。]{0,6}(への)?切り替え/, ng:/退職金|企業年金|確定拠出|ideco|イデコ|在職|再雇用|定年|継続雇用|健康保険|国民健康保険|任意継続|失業保険|雇用保険|基本手当|団体|天引|受け取り始め|もらい始め|請求/, head:"会社を辞めて次の勤め先が決まっていないときは、国民年金への切り替えを市区町村に届け出ます。", body:"会社を辞めると厚生年金から外れるので、国民年金に入る年齢の間で次の勤め先がすぐに決まっていない方は、住所地の市区町村で国民年金への切り替えを届け出ます。扶養されていた配偶者も、国民年金に入る年齢の間なら、自分で納める形に変わるので届け出が要ります。退職して保険料を納めるのが難しいときは、失業による特例の免除を申請できます。健康保険の手続きは別に要ります。", acts:["退職を控えたお客様には、年金と健康保険の両方に切り替えの手続きがあることを伝える", "扶養されていた配偶者の切り替えも、忘れずに届け出るよう伝える", "届け出の時期と書類は、市区町村の国民年金の窓口で確かめていただく"], actHead:"現場で使うなら", note:"届け出の期限・要る書類・特例の免除の基準は法律で決まる。市区町村の国民年金の窓口と日本年金機構・年金事務所で確かめる。健康保険は加入先の窓口へ。", pre:1, say:"会社を辞めて次の勤め先が決まっていないときは、国民年金への切り替えを市区町村に届け出ます。扶養されていた配偶者の方の分も届け出が要るので、一緒に確かめましょう。", more:"例えば、会社員の夫が退職して独立すると、夫は自分で国民年金に入る形に変わり、扶養されていた妻も同じく自分で国民年金に入る形に変わります。届け出を忘れると未納の期間が生まれ、障害年金などの要件に関わることがあります。国民年金に入る年齢を過ぎている方は、切り替えの届け出は要りません。", why:"公的年金は、働き方によって入る制度が変わる作りなので、会社を辞めて厚生年金から外れると、国民年金に入る形に自分で切り替える届け出が要ります。" },
      { key:'faq_xnkn_seikyu_tetsuzuki', faq:1, grp:'nkn', q:"年金をもらい始める手続きは？", re:/(年金|老齢年金|老齢厚生年金|老齢基礎年金)[^。]{0,4}(を)?(もらい始め|受け取り始め|受給開始|もらう(とき|ため)の|受け取る(とき|ため)の)[^。]{0,8}(手続|請求)|年金請求書|(老齢年金|老齢厚生年金|老齢基礎年金|年金)の(請求|受給)の?(手続|方法|仕方|しかた)|(老齢年金|老齢厚生年金|老齢基礎年金)[^。]{0,6}(の)?手続|年金(は|を)?[^。]{0,4}(どこで|どこに)[^。]{0,4}(請求|申請|手続)/, ng:/遺族|障害|未支給|亡くな|死亡|死去|他界|分割|離婚|代わり|代理|委任|手帳|番号|海外|振込|口座|相談|免除|猶予|特例|追納|保険料|任意加入|付加|基金|切り替|辞め|離職|独立|失業|開業|繰り?下げ|繰り?上げ|加給|振替加算|在職|個人年金|企業年金|ideco|イデコ|確定拠出|退職金|保険会社|忘れ|時効/, head:"年金は、受け取る年齢が近づくと届く年金請求書に書類を添えて出すと、受け取り始められます。", body:"受け取る年齢が近づくと、日本年金機構から年金請求書が届きます。受け取る年齢になってから、戸籍や住民票などの書類、受け取る口座の書類などを添えて、年金事務所や街角の年金相談センターに出し、国民年金だけに入っていた方などは、市区町村の窓口でも受け付けます。マイナンバーで省ける書類があります。老齢基礎年金と老齢厚生年金の両方を遅らせたい方は、請求書を出さずに待ち、受け取りたい時期に申し出ます。", acts:["受け取る年齢が近いお客様には、年金請求書が届いたら、繰下げをするかを決めてから出すよう伝える", "出す窓口と要る書類は、年金事務所に予約して確かめていただく", "配偶者や子がいる方は、加給年金のために追加の書類が要ることがあると伝える"], actHead:"現場で使うなら", note:"請求書が届く時期・要る書類・窓口は日本年金機構が決める。年金事務所・街角の年金相談センター・市区町村で確かめる。", pre:1, say:"年金は、受け取る年齢が近づくと届く年金請求書を出して、初めて受け取りが始まります。遅らせるかどうかを決めてから、年金事務所で手続きしましょう。", more:"年金請求書は、受け取る年齢になる前に届いても、出せるのはその年齢になってからです。出したあと、年金証書が届き、それから少したって最初の振り込みがあります。老齢基礎年金と老齢厚生年金の片方だけを遅らせることもできるので、出す前に決めておきます。", why:"公的年金は、受け取る権利が生まれても、自分で請求して初めて支払いが始まる作りです。請求のときに、受け取る方が受け取りを遅らせるかどうかも確かめます。" },
      { key:'faq_xnkn_shibou_todoke', faq:1, grp:'nkn', q:"年金をもらっている親が亡くなったら手続きは？", re:/(年金を?(もらって|受け取って|受給して)(いる|いた)|年金受給者|年金暮らしの|年金生活の)[^。]{0,16}(亡くな|死亡|死去|他界)|(親|父|母|夫|妻|家族|祖父|祖母|義父|義母)[^。]{0,8}(亡くな|死亡|死去|他界)[^。]{0,16}年金[^。]{0,8}(手続|届|止め|どうす|どうな|請求|振り込|振込|返)|未支給年金|年金受給者死亡届|受給権者死亡届|(親|父|母|夫|妻|祖父|祖母|義父|義母)[^。]{0,4}(の)?年金[^。]{0,6}(を)?(止め|停止)/, ng:/遺族|保険金|生命保険|受取人|個人年金|企業年金|ideco|イデコ|確定拠出|相続税|税|繰り?下げ|待機/, head:"年金を受け取っていた方が亡くなったら、年金を止める届け出と、残った分の未支給年金の請求をします。", body:"亡くなったことを届け出ると年金が止まり、日本年金機構にマイナンバーが登録されている方は、届け出を省ける場合があります。亡くなった月の分までの年金で、まだ受け取っていない分は、生計を同じくしていたご家族が未支給年金として請求できます。ご遺族が遺族年金の要件を満たすときは、別に請求します。届け出が遅れて振り込まれた分は、返す必要があります。", acts:["ご家族が亡くなった方には、お悔やみのあとで、年金を止める届け出と未支給年金の請求があることを伝える", "届け出と請求の窓口と要る書類は、年金事務所や街角の年金相談センターで確かめていただく", "遺族年金を受け取れるかも、年金事務所で一緒に確かめていただく"], actHead:"現場で使うなら", note:"届け出の期限・届け出を省ける条件・未支給年金を受け取れるご家族の範囲と順番は日本年金機構が決める。年金事務所で確かめる。税の扱いは税理士へ。", pre:1, say:"年金を受け取っていた方が亡くなったら、年金を止める届け出と、まだ受け取っていない分の請求をします。遺族年金を受け取れるかも、年金事務所で一緒に確かめましょう。", more:"年金は後払いなので、亡くなった時点で、まだ振り込まれていない月の分が残っていることがほとんどです。この分は未支給年金として、生計を同じくしていた配偶者や子などが、決まった順番で請求します。相続の財産とは別のものとされ、税の扱いは税理士に確かめます。", why:"年金は、受け取る方が生きている間の暮らしを支えるものなので、亡くなると止まります。後払いの作りのために残った分は、暮らしを共にしていたご家族が受け取れるようにしています。" },
      { key:'faq_xnkn_oya', faq:1, grp:'nkn', q:"大学生の子どもの国民年金を親が払っていい？", re:/(子ども|子供|息子|娘|お子様|お子さん|学生|大学生|専門学校生|大学院生|短大生)[^。]{0,16}(国民年金|年金の保険料|年金保険料)|(国民年金|年金の保険料|年金保険料)[^。]{0,10}(学生|大学生|専門学校)|(二十歳|20歳)(になっ|を迎え|にな)[^。]{0,8}(国民年金|年金)[^。]{0,10}(通知|届い|来た|手続|加入|入る|払う|どうす|どうな|は？|は\?)|成人(し|にな|を迎え)[^。]{0,8}(国民年金|年金)[^。]{0,10}(通知|届い|来た|手続|加入|入る|払う|どうす|どうな|は？|は\?)/, ng:/免除|猶予|学生納付特例|学生特例|追納|障害|遺族|控除|出産|妊娠|扶養|就職|厚生年金|アルバイト|パート|時代|当時|昔|海外|留学/, head:"学生も一定の年齢から国民年金に入り、保険料は親が納めても良く、学生納付特例で先に延ばす道もあります。", body:"学生でも、国民年金に入る年齢になると加入し、日本年金機構から加入のお知らせが届きます。保険料は親が代わりに納めても構わず、世帯主には、世帯の方の保険料を連帯して納める義務もあります。生計を同じくするお子様の分を親が納めると、親の所得の計算で社会保険料控除の対象になることがあります。納めるのが難しいときは、学生納付特例で納めるのを先に延ばせますが、追納しないと年金の額には反映されません。", acts:["大学生のお子様がいるご家庭には、親が納める形と、学生納付特例で先に延ばす形の二つがあると伝える", "親が納めた分の税の扱いは、税理士・税務署に確かめていただく", "学生納付特例を使った方には、追納できる期間に限りがあることを年金事務所で確かめていただく"], actHead:"現場で使うなら", note:"学生納付特例の要件と追納できる期間は日本年金機構が決める。社会保険料控除の扱いは税理士・税務署で確かめる。", pre:1, say:"大学生のお子様の国民年金の保険料は、親御さんが納めても構いません。納めるのが難しければ、学生納付特例で先に延ばす道もあるので、どちらにするかご家族で考えましょう。", more:"学生納付特例は、親の所得ではなく学生ご本人の所得で決まり、申請は年度ごとに要ります。この期間は、追納しない限り老齢基礎年金の額には反映されませんが、障害年金などの要件のうえでは、納めた期間と合わせて数えます。就職してから追納する形もあるので、追納できる期間をご家族で共有しておくと忘れにくくなります。", why:"国民年金は、学生も含めて国内に住む一定の年齢の方が全員入る仕組みなので、学生には収入が少ない事情に合わせて、納めるのを先に延ばせる特例が用意されています。" },
      { key:'faq_xnkn_part', faq:1, grp:'nkn', q:"パートで厚生年金に入ると、将来の年金は増える？", re:/(パート|アルバイト|短時間)[^。]{0,16}(厚生年金|社会保険|社保)[^。]{0,16}(入る|入っ|加入|入れ|入ら|年金|将来|増え|どうな|変わ|メリット|対象)|厚生年金[^。]{0,8}(の)?(加入|適用)[^。]{0,8}(拡大|広が)/, ng:/扶養|年収の壁|壁|130万|106万|第3号|3号|配偶者控除|控除|税|役員|ライフプラン|試算|学生/, head:"パートで厚生年金に入ると、保険料はかかりますが、老齢・障害・遺族の年金に厚生年金の分が加わります。", body:"勤め先の規模や働く時間などの条件に当てはまると、パートやアルバイトでも厚生年金と健康保険に入ります。保険料は勤め先と半分ずつ負担し、その分の手取りは減りますが、老齢基礎年金に加えて老齢厚生年金を受け取れるようになり、障害や遺族の年金にも厚生年金の分が加わります。扶養されていた配偶者の方は、扶養から外れて、ご自身で厚生年金に入る形に変わります。条件は改正で段階的に広がっています。", acts:["働き方を変えるか迷っているお客様には、手取りの変化と、年金と保障の変化の両方を並べて見ていただく", "加入の条件に当てはまるかは、勤め先と年金事務所に確かめていただく", "健康保険の扱いや税の扶養との関係は、それぞれの窓口と税理士・税務署に確かめていただく"], actHead:"現場で使うなら", note:"加入の条件（働く時間・賃金・会社の規模）は改正で段階的に見直される。勤め先と日本年金機構・年金事務所で確かめる。税は税理士・税務署へ。", pre:1, say:"パートで厚生年金に入ると、保険料はかかりますが、将来の年金や、障害・遺族の年金に厚生年金の分が加わります。手取りの変化と並べて考えましょう。", more:"例えば、扶養の範囲で働いていた方が、勤め先の規模の条件で厚生年金に入ることになった場合、保険料の分だけ手取りは減ります。その一方で、病気で休んだときの健康保険の手当金や、障害厚生年金の対象にもなります。損得ではなく、何が増えて何が減るかで見るのが大事です。", why:"働き方の違いで保障に差が出ないよう、短い時間で働く方にも厚生年金を広げる見直しが続いています。保険料を勤め先と分け合い、国民年金に厚生年金の分が上乗せされる作りです。" },
      { key:'faq_xnkn_shien', faq:1, grp:'nkn', q:"年金生活者支援給付金とは？", re:/年金生活者支援給付金|年金生活者[^。]{0,6}給付金|(年金|年金暮らし)[^。]{0,10}(上乗せ|足し)[^。]{0,8}(給付金|もらえるお金)/, ng:/保険金|個人年金|生命保険|保険会社/, head:"年金生活者支援給付金は、所得が一定より少ない年金受給者に、年金に上乗せして支給される給付金です。", body:"老齢基礎年金を受け取っている方で、世帯の全員が住民税のかからない方などの要件を満たす方のほか、所得が一定より少ない障害基礎年金・遺族基礎年金を受け取っている方が対象です。受け取るには請求が要り、対象になりそうな方には日本年金機構から請求書が届きます。年金と一緒に振り込まれ、所得の状況は毎年確かめられます。", acts:["年金の額が少ないお客様には、年金生活者支援給付金という仕組みがあると伝え、対象かを年金事務所で確かめていただく", "届いた請求書を出し忘れると受け取れないことがあると伝える", "対象になるかは所得と世帯の状況で決まるので、こちらで言い切らない"], actHead:"現場で使うなら", note:"対象の要件・所得の基準・額は法律で決まり改定される。日本年金機構・年金事務所・市区町村で確かめる。", pre:1, say:"所得が一定より少ない年金受給者の方には、年金に上乗せして支給される給付金があります。日本年金機構から請求書が届いたら、出し忘れないようにしましょう。", more:"老齢の方の給付金の額は、保険料を納めた期間や免除の期間をもとに決まります。世帯の状況が変わって新しく対象になったときにも請求書が届くので、届いた書類を見落とさないことが大事です。給付金は年金とは別のものですが、振り込みは年金と一緒です。", why:"年金の額が少なく暮らしが苦しい方を支えるため、消費税の引き上げに合わせて設けられた給付金です。年金とは別の財源で、年金に上乗せする形で支給されます。" },
      { key:'faq_xnkn_techo', faq:1, grp:'nkn', q:"年金手帳をなくしたらどうする？", re:/年金手帳[^。]{0,12}(なくし|無くし|失くし|紛失|見つからな|ない|無い|再発行|再交付|どこ|捨て|もう|今は|今も|廃止|使え|要る|必要|保管|取っておく|とっておく)|基礎年金番号[^。]{0,12}(分からな|わからな|知りたい|調べ|確かめ|どこ|忘れ|通知書)|基礎年金番号通知書/, ng:/マイナンバーカード|個人年金|保険証券|証券/, head:"年金手帳は今も番号を確かめる書類として使え、なくしたときは基礎年金番号通知書の再交付を申し出ます。", body:"年金手帳は新しく発行されなくなり、今は基礎年金番号を知らせる基礎年金番号通知書が代わりになっていますが、お持ちの年金手帳は、基礎年金番号を確かめる書類として今も使えます。なくしたときは、年金事務所に基礎年金番号通知書の再交付を申し出られ、会社員の方は勤め先を通して申し出る場合もあります。年金の多くの手続きでは、基礎年金番号の代わりにマイナンバーを書けば済みます。", acts:["基礎年金番号を聞かれたときは、まずマイナンバーで手続きできるかを、手続きの窓口に確かめていただく", "年金手帳が何冊もある方には、番号が分かれていないか年金事務所で確かめていただく", "お客様の基礎年金番号やマイナンバーを、こちらで預かったり書き写したりしない"], actHead:"現場で使うなら", note:"基礎年金番号通知書の再交付の窓口と方法、マイナンバーで手続きできる範囲は日本年金機構が決める。年金事務所で確かめる。マイナンバーの取り扱いは社内の規程に従う。", pre:1, say:"年金手帳をなくしても、年金事務所で基礎年金番号通知書の再交付を申し出られます。多くの手続きはマイナンバーでもできるので、まず窓口に確かめてみましょう。", more:"転職や結婚で年金手帳が何冊もある方は、基礎年金番号が二つ以上に分かれていて、記録がつながっていないことがあります。ねんきん定期便の加入記録に抜けがないかを見て、気になる期間があれば、年金事務所で調べていただきます。", why:"基礎年金番号は、国民年金と厚生年金の記録を一人ひとりにまとめるための番号なので、手帳という紙がなくなっても、番号と記録は年金の仕組みの中に残っています。" },
      /* sei.json */
      { key:'faq_xsei_shibou_shorui', faq:1, grp:'sei', q:"死亡保険金の請求に要る書類は？", re:/死亡保険金[^。]{0,12}(書類|何が(必要|要る|いる)|用意|そろえ|揃え)|(ご遺族|遺族|受取人)[^。]{0,10}(用意|そろえ|揃え)[^。]{0,8}書類/, ng:/法人|会社が受け取|税|相続税|団信|団体信用/, head:"死亡保険金の書類は、請求書と、亡くなったことと受取人を確かめるものが基本です。", body:"一般的には、保険会社所定の請求書、亡くなったことと死因を確かめる書類（死亡診断書の写しなど）、被保険者と受取人の関係や受取人ご本人を確かめる書類がそろうと請求できます。何をどの形で出すかは、保険会社・契約・保険金の額・亡くなった原因によって違います。事故などで亡くなったときは、事故の状況を確かめる書類が加わることがあります。", acts:["保険会社の窓口に連絡し、その契約で要る書類の一覧を出してもらってからご遺族にお伝えする", "書類ごとに「どこで取るか」を書いた紙一枚をお渡しし、取る順番も一緒に決める", "役所で取る書類は、ほかの手続きの分もまとめて取れるよう、ほかに要る枚数も伺っておく"], actHead:"現場で使うなら", note:"要る書類と出し方は、保険会社と契約で違う。こちらで一覧を決めつけず、保険会社の窓口の案内で確かめる。相続の手続きと関わるときは司法書士・税理士へ。", pre:1, say:"お手続きの書類は、保険会社から一覧をもらってから、取る場所と順番を紙にしてお渡しします。ご無理のない順に一緒に進めましょう。", more:"よく手間取るのは、役所で取る書類を何度も取りに行くことです。保険のほかに、年金・勤め先・銀行・相続の手続きでも同じ種類の書類が要ることが多いので、全体で何枚要りそうかを先に伺い、まとめて取っていただくと負担が減ります。", why:"保険会社は、亡くなった事実と、受け取る方が契約で決めた本人であることを確かめてから支払います。違う人に支払うと、本来の受取人に届かなくなるため、本人と関係を確かめる書類が求められます。" },
      { key:'faq_xsei_shibou_shindansho', faq:1, grp:'sei', q:"死亡診断書はコピーでいい？", re:/死亡診断書|死体検案書/, head:"死亡診断書は役所に出すと手元に戻らないので、出す前に写しを取っておくのが基本です。", body:"死亡診断書は死亡届と一枚になった用紙で、役所に死亡届を出すと原本は戻ってきません。保険の請求では、写しで受け付ける保険会社もあれば、保険会社所定の証明書を求める場合もあります。事故などで医師の検案を受けたときは、死亡診断書の代わりに死体検案書が出され、扱いは同じように保険会社で確かめます。", acts:["死亡届を出す前に、写しを何枚か取っておくとよいとご遺族にお伝えする", "原本を出してしまったときは、保険会社に代わりの書類で受け付けられるかを確かめる", "保険のほか、勤め先や年金の手続きでも写しが要ることが多いと添えておく"], actHead:"現場で使うなら", note:"写しで受け付けるか、所定の証明書が要るかは保険会社と契約で違う。各保険会社の窓口で確かめる。死亡届の出し方は市区町村の窓口へ。", pre:1, say:"死亡診断書は、役所に出すと手元に戻りません。出される前に写しを取っておかれると、保険やほかの手続きで助かります。", more:"原本を出したあとでも、手が無いわけではありません。保険会社によっては、別の証明書や、役所で取れる書類で受け付けることがあります。慌てて病院に頼み直す前に、まず保険会社の窓口に、何なら受け付けられるかを確かめます。", why:"死亡診断書は医師が書き、死亡届と一緒に役所が受け取って記録する書類だからです。保険会社は亡くなった事実と原因を確かめる必要があるので、その写しや代わりの証明を求めます。" },
      { key:'faq_xsei_uketori_honnin', faq:1, grp:'sei', q:"受取人が被保険者ご本人の死亡保険金は、誰が請求する？", re:/受取人[^。]{0,10}(被保険者|亡くなった(方|人)?)(ご)?本人|受取人[^。]{0,4}(が|の)?(指定|決め)[^。]{0,4}(が)?(無い|ない|されていない|していない)/, ng:/法人|会社/, head:"受取人がご本人か指定が無い死亡保険金は、相続人の方が請求する形になるのが一般的です。", body:"受取人が被保険者ご本人になっている、または受取人の指定が無い死亡保険金は、約款の決まりにより、被保険者の相続人の方が請求する形になるのが一般的です。受取人がご本人なのか、指定が無いのかで、相続の手続きとの関わり方や、相続人どうしの話し合いの要り方が変わることがあります。請求の前に、約款と保険会社の案内で誰が請求するかを確かめます。", acts:["証券の受取人の欄を、ご遺族と一緒に確かめる", "保険会社に、誰がどの書類で請求するかを確かめてからお伝えする", "相続人が何人もいるときは、相続の手続きを頼む専門家と順番を合わせていただく"], actHead:"現場で使うなら", note:"誰が受け取り、相続の手続きとどう関わるかは、約款と法律の話。保険会社の窓口で確かめ、個別の判断は弁護士・司法書士、税は税理士へ。", pre:1, say:"この契約は受取人の形が特別なので、誰がどの書類で請求するかを保険会社に確かめてからお伝えします。相続のお手続きとも順番を合わせましょう。", more:"見つかりやすいのは、昔の契約や、ご本人が受取人を決めないまま入った契約です。相続人の方が多いと、全員の書類や話し合いが要ることがあり、時間がかかります。契約のうちに、受取人を決めておくことの大切さもここで分かります。", why:"死亡保険金は、契約で決めた受取人が受け取るお金です。決めた人が亡くなった本人だったり、決めていなかったりすると、受け取る人を約款と法律で決めることになるため、相続の手続きと関わってきます。" },
      { key:'faq_xsei_uketori_fukusu', faq:1, grp:'sei', q:"保険金を受け取る方が何人もいるとき、請求は誰がする？", re:/受取人[^。]{0,6}(の)?代表|(受け取る(人|方)|受取人)[^。]{0,8}(何人も|大勢)[^。]{0,16}(請求|手続|誰)/, ng:/税|非課税|相続税|全員|みんな/, head:"受取人が二人以上のときは、代表の方を決めて請求する決まりの約款が多くあります。", body:"受取人が二人以上いる契約では、受取人どうしで代表の方を一人決め、その方がほかの受取人を代表して請求する決まりの約款が多くあります。受け取る割合は契約で決めてあり、決めていなければ等しく分けるなど、約款の決まりに従います。受取人の中に未成年の方や、連絡がつきにくい方がいると、書類が増えることがあります。", acts:["証券で、受取人の顔ぶれと受け取る割合を確かめる", "保険会社に、代表の方の決め方と、ほかの受取人に要る書類を確かめる", "受取人どうしの連絡の取り方を伺い、こちらから個別に事情を話して回らない"], actHead:"現場で使うなら", note:"代表の方の決め方と受け取る割合は、約款と契約で決まる。保険会社の窓口で確かめる。受取人どうしで話がまとまらないときは弁護士へ。", pre:1, say:"受取人がお二人の契約なので、代表の方を決めて請求する形になることが多いです。保険会社に確かめて、お二人に要る書類をまとめてお伝えします。", more:"つまずきやすいのは、受取人の一人が遠方に住んでいる、または未成年という場面です。書類のやりとりに時間がかかるので、早めに保険会社の案内をもらい、誰が何を用意するかを一覧にします。割合は証券に書いてあることが多いので、先に一緒に見ておきます。", why:"保険会社は、同じ保険金を二重に支払ったり、受取人どうしの取り分を間違えたりしないよう、窓口を一人にして確かめる仕組みにしています。" },
      { key:'faq_xsei_uketori_miseinen', faq:1, grp:'sei', q:"受取人が未成年のとき、保険金の請求は誰がする？", re:/(受取人|保険金)[^。]{0,12}(未成年)[^。]{0,12}(請求|手続|受け取)|(未成年|子ども|子供|こども|お子様|お子さん)(が|の)受取人[^。]{0,16}(請求|手続)|未成年の受取人/, ng:/税|非課税|相続税|学資/, head:"受取人が未成年のときは、親権者などの法律上の代理人が代わりに手続きをするのが一般的です。", body:"未成年の方は自分だけで請求の手続きができないので、親権者が法律上の代理人として請求するのが一般的です。親権者がいないときは、家庭裁判所が選ぶ未成年後見人などが手続きをします。代理人と未成年の方の関係を確かめる書類が要るほか、事情によっては家庭裁判所の手続きが要ることもあるので、保険会社と専門家に確かめます。", acts:["受取人の年齢と、親権者がどなたかを伺う", "保険会社に、代理人が請求するときの書類を確かめてからお伝えする", "親権者がいない・事情が込み入っているときは、弁護士や家庭裁判所の窓口を案内する"], actHead:"現場で使うなら", note:"誰が代理人になり、家庭裁判所の手続きが要るかは法律の話。保険会社の窓口で書類を確かめ、個別の判断は弁護士・家庭裁判所へ。", pre:1, say:"お子様が受取人の保険金は、親権者の方が代わりにお手続きをする形が一般的です。要る書類を保険会社に確かめてお伝えします。", more:"気をつけたいのは、親権者の方ご自身も相続人や受取人になっている場面です。立場が重なると、手続きの形が変わることがあるので、自己流で進めず保険会社と専門家に確かめます。受け取ったお金をどう管理するかは、ご家族と専門家で決めることです。", why:"法律は、未成年の方を守るために、契約や大きなお金の手続きを本人だけではできない仕組みにしています。だから、法律上の代理人が本人に代わって請求します。" },
      { key:'faq_xsei_uketori_ninchi', faq:1, grp:'sei', q:"受取人が認知症で、保険金の請求ができないときは？", re:/受取人[^。]{0,12}(認知症|判断能力|意思(を)?(示せ|伝えられ))|(認知症|判断能力)[^。]{0,16}(保険金|給付金)[^。]{0,10}(請求|手続|受け取)/, ng:/被保険者|ご本人|本人が|指定代理|備え|保険料/, head:"受取人が手続きできないときは、成年後見人などの法律上の代理人が請求するのが基本です。", body:"受取人の方に判断能力が十分でないと、ご本人の意思で請求の手続きをすることが難しくなります。そのときは、家庭裁判所が選ぶ成年後見人などの法律上の代理人が請求するのが基本です。保険会社によって、ご家族が手続きをするときの扱いを設けていることもあるので、まず窓口に状況を伝えて、どの形で進められるかを確かめます。", acts:["ご家族から状況を伺い、保険会社の窓口に、受取人の方の状態を伝えて進め方を確かめる", "成年後見の手続きが要りそうなときは、市区町村の窓口や弁護士・司法書士を案内する", "ご本人の判断能力をこちらで決めつけず、保険会社と専門家の判断を待つ"], actHead:"現場で使うなら", note:"判断能力の判断は医師、成年後見の手続きは家庭裁判所・弁護士・司法書士。請求の扱いは保険会社の窓口で確かめる。", pre:1, say:"受取人の方がご自身で手続きをするのが難しいときの進め方を、保険会社に確かめます。成年後見の手続きが要るかどうかも、専門の窓口と一緒に確かめましょう。", more:"よくあるのは、ご高齢の配偶者が受取人で、手続きのときに初めて難しさが分かる場面です。後見の手続きには時間がかかることがあるので、分かった時点で早めに窓口に相談します。契約のうちに受取人の顔ぶれを見直す話は、別の機会に落ち着いてします。", why:"保険金の請求は、受け取るお金についての大事な手続きなので、受取人ご本人の意思で行うのが原則です。意思を示すのが難しい方を守るために、法律上の代理人の仕組みがあります。" },
      { key:'faq_xsei_shikkou', faq:1, grp:'sei', q:"失効していた契約で亡くなったら、保険金は出る？", re:/失効[^。]{0,10}(中|して(いた|た)|した(あと|後))[^。]{0,12}(亡くな|死亡|入院|手術|保険金|給付金)/, ng:/自動車|火災|地震|損保|年金|免許/, head:"失効している間に起きたことは、原則として保険金や給付金の対象になりません。", body:"猶予期間を過ぎて失効した契約は、保障が止まっているため、その間の死亡や入院は原則として支払いの対象になりません。ただ、自動で保険料を貸し付けて契約を続ける仕組みが働いていたり、復活の手続きが済んでいたりすると、契約が続いていることがあります。本当に失効していたのか、いつからかを、まず保険会社に確かめます。", acts:["思い込みで「出ません」と言わず、保険会社に契約の状態と日付を確かめる", "自動で貸し付ける仕組みや、復活の手続きの有無も一緒に確かめてもらう", "結果を伝えるときは、ご家族の気持ちを受け止め、事実を落ち着いてお伝えする"], actHead:"現場で使うなら", note:"失効の時期と扱い、例外の決まりは約款と保険会社で決まる。個別の支払いの可否は保険会社の窓口で確かめる。", pre:1, say:"契約の状態は、保険会社でないと正確には分かりません。いつの時点でどうなっていたかを確かめて、お知らせします。", more:"現場で大事なのは、失効の前に手を打つことです。保険料の払込が止まったという連絡を受けたら、その時点で契約者の方に連絡し、払い方を変える・保障を小さくするなどの道を一緒に考えます。失効のあとに分かると、できることがほとんど残りません。", why:"保険は、保険料を出し合うことで保障が続く仕組みです。払込が止まり、猶予期間も過ぎると保障が止まるので、その間に起きたことまで支払うと、払い続けているほかの加入者との公平が保てません。" },
      { key:'faq_xsei_sokuji', faq:1, grp:'sei', q:"死亡保険金を早く受け取る方法はある？", re:/(保険金|給付金)[^。]{0,10}(早く|先に|急ぎ|すぐに)[^。]{0,10}(受け取|もらえ|もらい|支払|振り込)|(葬儀|葬式|お葬式)[^。]{0,12}(保険金|間に合)/, ng:/税|法人|会社が受け取|ローン/, head:"保険会社によっては、書類を簡単にして、死亡保険金の一部を早く支払う扱いがあります。", body:"葬儀の費用などに充てたい方のために、一定の範囲で、通常より少ない書類で死亡保険金の一部を早く支払う扱いを設けている保険会社があります。使えるかどうか、受け取れる範囲、要る書類は、保険会社と契約で違います。扱いが無いときは、書類をそろえる順番を工夫して、できるだけ早く請求できるよう手伝います。", acts:["保険会社に、早く支払う扱いがあるか、要る書類は何かを確かめる", "葬儀の日程と、お金が要る時期をご家族に伺い、間に合うかを一緒に考える", "受け取れる時期を約束せず、保険会社の案内のとおりにお伝えする"], actHead:"現場で使うなら", note:"早く支払う扱いの有無・範囲・書類は保険会社と契約で違う。各保険会社の窓口で確かめる。", pre:1, say:"葬儀の費用に間に合うよう、早く受け取れる扱いがあるかを保険会社に確かめます。間に合わない場合も、書類の順番を一緒に工夫しましょう。", more:"受取人の方の口座が、亡くなった方と同じ銀行で動かしにくくなっていると、振込先で手間取ることがあります。受取人ご本人の名義の口座を先に確かめておきます。また、早く受け取った分とあとから受け取る分の関係は、保険会社の案内で確かめます。", why:"亡くなった直後は、葬儀などでまとまったお金が要るのに、預金がすぐ動かせないことがあります。その負担を軽くするために、確かめる書類を絞って一部を先に支払う扱いを設けている保険会社があります。" },
      { key:'faq_xsei_uketorikata', faq:1, grp:'sei', q:"死亡保険金は、分けて受け取ることもできる？", re:/保険金[^。]{0,20}(分けて受け取(る|れ)[^。]{0,6}(形|こと|方法|か)|年金(のように|で|形式|払い)|分割(で|払い|して)|据え?置|預けて(おけ|おく))/, ng:/税|課税|相続税|個人年金|受給権|法人|会社が受け取|会社の保険/, head:"商品と保険会社によっては、一度に受け取るほか、年金のように分けて受け取る形も選べます。", body:"死亡保険金は一度にまとめて受け取るのが基本ですが、契約によっては、年金のように何回かに分けて受け取る形や、保険会社にしばらく置いておく形を選べることがあります。選べる形と、選べる時期（契約のうちか、請求のときか）は商品と保険会社で違います。受け取り方で税の扱いが変わることもあるので、税は税理士に確かめます。", acts:["証券と約款で、選べる受け取り方があるかを確かめる", "ご遺族の暮らしのお金の流れを伺い、まとめて要るのか、毎月要るのかを一緒に考える", "税の扱いが変わることがあると伝え、顧問の税理士か税務署に確かめていただく"], actHead:"現場で使うなら", note:"選べる受け取り方と時期は商品と保険会社で違う。保険会社の窓口と約款で確かめる。税の扱いは税理士・税務署へ。", pre:1, say:"この保険金は、まとめて受け取るほかに、分けて受け取る形を選べるかもしれません。保険会社に確かめて、暮らしのお金の流れと一緒に考えましょう。", more:"分けて受け取る形は、まとまったお金を一度に持つと使い方に迷う方や、毎月の生活費として受け取りたい方に向いています。一方で、急にまとまったお金が要ったときに引き出せるかは、形によって違います。選んだあとに変えられるかも、選ぶ前に確かめます。", why:"ご遺族の暮らしのために残すお金なので、受け取る形も暮らし方に合わせて選べるよう、分けて支払う仕組みを用意している商品があります。" },
      { key:'faq_xsei_shigo_hokenryo', faq:1, grp:'sei', q:"亡くなったあとに引き落とされた保険料は戻る？", re:/(亡くな|死亡)[^。]{0,8}(あと|後|月|以降)[^。]{0,10}保険料[^。]{0,12}(戻|返|引き?落|引落|どうな)/, ng:/自動車|火災|地震|損保|年金|国民年金|健康保険/, head:"亡くなったあとの期間の保険料は、精算して返すのが一般的です。", body:"被保険者が亡くなったあとも、保険会社に連絡が届くまでは、保険料の引き落としが続くことがあります。亡くなったあとの期間に当たる保険料は、保険金と一緒に精算されて返されるなどの扱いが一般的です。どの月の分が返るかは、払い方と約款の決まりで違うので、保険会社に確かめます。", acts:["亡くなったことを保険会社に早めに伝え、引き落としを止める手続きを確かめる", "引き落とされた月と金額を通帳で一緒に確かめ、保険会社に伝える", "返る分があるかは言い切らず、保険会社の精算の案内を待つと伝える"], actHead:"現場で使うなら", note:"精算の扱いと返る範囲は、払い方と約款で違う。保険会社の窓口で確かめる。口座そのものの手続きは金融機関へ。", pre:1, say:"亡くなられたあとの保険料は、精算されて戻る扱いが一般的です。どの分が戻るか、保険会社に確かめてお知らせします。", more:"引き落とし口座が亡くなった方の名義だと、金融機関に亡くなったことが伝わった時点で口座が止まり、ほかの契約の保険料も引き落とせなくなることがあります。ご家族の契約で同じ口座を使っているものが無いかも、一緒に確かめておきます。", why:"保険料は、保障を受ける期間に対して払うお金です。亡くなったあとは保障の期間が終わっているので、その先の分を受け取り続ける理由が無く、精算して返す仕組みになっています。" },
      { key:'faq_xsei_souki', faq:1, grp:'sei', q:"加入してすぐに入院したら、請求はどうなる？", re:/(加入|契約|入っ)[^。]{0,4}(して)?(すぐ|間もな|まもな|ばかり|直後)[^。]{0,16}(入院|手術|亡くな|死亡|請求|給付金|保険金)/, ng:/自動車|火災|地震|損保|クーリング/, head:"加入して間もない時期の請求は、保険会社が告知の内容などを確かめることが多くあります。", body:"加入から間もない時期に入院や死亡があると、保険会社は、責任開始日より前から病気が始まっていなかったか、告知の内容が事実どおりだったかを、医療機関への問い合わせなどで確かめることが多くあります。確かめる分、支払いまでに時間がかかることがあります。がん保険のように、保障が始まるまでの待ち期間がある商品もあるので、責任開始日も確かめます。", acts:["責任開始日と、入院・死亡の日付を証券で確かめる", "保険会社の確認に時間がかかることがあると、先にお伝えしておく", "告知のときのことを聞かれても、記憶で話を作らず、事実をありのまま保険会社に伝えていただく"], actHead:"現場で使うなら", note:"確かめる内容と支払いの可否は保険会社が決める。責任開始日と待ち期間は約款で確かめ、保険会社の窓口に進み具合を確かめる。", pre:1, say:"加入して間もない時期のご請求なので、保険会社が通常より丁寧に確かめることがあります。少しお時間がかかるかもしれませんが、進み具合はこちらからもお伝えします。", more:"このときに担当が気をつけるのは、告知の場面を自分に都合よく思い出さないことです。保険会社から当時のことを聞かれたら、覚えている事実だけを答え、分からないことは分からないと伝えます。申込みのときの記録が残っていれば、それを確かめます。", why:"保険は、加入する時点で病気が無い方どうしで支え合う仕組みです。加入の直後の請求は、加入の前から病気があったかどうかで扱いが変わるため、公平のために事実を確かめる手順が入ります。" },
      { key:'faq_xsei_nyuin_chu', faq:1, grp:'sei', q:"入院中でも給付金は請求できる？", re:/入院(中|の途中|途中)[^。]{0,10}(請求|受け取|もらえ)|退院(を)?(待たず|前|する前)[^。]{0,12}(請求|給付)/, ng:/自動車|火災|損保|高額療養|限度額/, head:"入院給付金は退院後にまとめて請求するのが多いですが、途中で請求できる扱いもあります。", body:"入院給付金は、退院したあとに入院の日数が決まってから、まとめて請求するのが一般的です。ただ、入院が長くなる場合などに、入院中でもそれまでの分を請求できる扱いを設けている保険会社があります。途中で請求したときも、退院のあとに残りの分を請求することになるので、書類が二度要ることがあります。", acts:["入院の見込みの長さと、お金が要る時期を伺う", "保険会社に、入院中の請求ができるか、要る書類は何かを確かめる", "途中で請求したときは、退院後に残りの分の請求を忘れないよう、日付をメモしてお渡しする"], actHead:"現場で使うなら", note:"入院中の請求の扱いと書類は保険会社と契約で違う。保険会社の窓口で確かめる。入院の見込みは医師に。", pre:1, say:"入院が長くなりそうなときは、途中でそれまでの分を請求できる場合があります。保険会社に確かめて、退院のあとの分も忘れないよう一緒に管理します。", more:"入院中の方は、書類を自分で集めるのが難しいことが多いので、ご家族のどなたが手続きをするかを先に決めておきます。病院の書類は退院時にまとめて頼むほうが手間が少ないこともあるので、二度に分けるかどうかは費用と手間を比べて決めていただきます。", why:"入院給付金は日数に応じて支払うので、日数が決まる退院後にまとめるのが手続きとして確かです。一方で長い入院ではその間の暮らしのお金が要るため、途中の請求を受け付ける扱いがあります。" },
      { key:'faq_xsei_nissu', faq:1, grp:'sei', q:"入院の日数はどう数える？", re:/入院(の)?日数[^。]{0,8}(数え|カウント|入る|含)|入院(した)?日と退院(した)?日|日帰り入院[^。]{0,8}(何日|日数|数え)/, ng:/自動車|火災|損保|有給|休暇|休職/, head:"多くの医療保険では、入院した日と退院した日を、どちらも一日として数えます。", body:"多くの医療保険では、入院した日も退院した日もそれぞれ一日として数え、その間の日を足して入院の日数とします。入院した日に退院する日帰り入院は、一日として数える商品が多くあります。ただし、外来の扱いになる場合や、古い契約で一定の日数を超えないと支払われない決まりのものもあるので、約款と医療機関の書類で確かめます。", acts:["医療機関の書類（領収書や入院の証明）で、入院した日と退院した日を確かめる", "外来の扱いではなく入院だったかを、書類の書き方で確かめる", "古い契約は、日数の決まりが今の商品と違うことがあるので約款で確かめる"], actHead:"現場で使うなら", note:"日数の数え方と対象になる入院の決まりは約款で違う。保険会社の窓口と約款で確かめる。", pre:1, say:"入院した日と退院した日は、多くの契約でどちらも一日に数えます。この契約の決まりを確かめて、お受け取りの見込みを一緒に見ましょう。", more:"迷いやすいのは、夜遅くに入院して翌朝に退院した場合や、救急で運ばれて入院にならなかった場合です。医療機関の書類で入院の扱いだったかどうかが分かれ目になるので、お客様の記憶ではなく書類で確かめます。", why:"入院給付金は、入院の日数に合わせて支払う仕組みなので、数え方を約款で決めておく必要があります。入院した日も退院した日も病院で過ごしているため、それぞれ一日に数える決まりが多くあります。" },
      { key:'faq_xsei_nyuin_teigi', faq:1, grp:'sei', q:"どんな入院なら、入院給付金の対象になる？", re:/検査(入院|のための入院|目的の入院)|自宅療養[^。]{0,12}(給付|対象|出る|保険)|人間ドック[^。]{0,12}(入院|給付|出る)|(どんな|どういう)入院[^。]{0,10}(対象|給付|出る)|入院の(定義|条件)/, ng:/自動車|火災|損保|有給|休暇|休職|健康診断の結果/, head:"対象になるのは、治療のために医師の管理のもとで病院に入る入院です。", body:"多くの約款では、医師による治療が必要で、自宅などでは治療が難しいため病院や診療所に入り、常に医師の管理のもとで治療に専念することを入院としています。だから、治療を目的としない検査だけの入院や人間ドック、自宅での療養は、原則として対象になりません。検査で病気が見つかり、そのまま治療に移った場合などの扱いは約款で確かめます。", acts:["入院の目的（治療か検査か）を、医療機関の書類で確かめる", "対象かどうかは言い切らず、保険会社に入院の目的を伝えて確かめる", "自宅での療養は、通院の保障やほかの特約で当てはまるものが無いかも確かめる"], actHead:"現場で使うなら", note:"入院の決まりと例外は約款と保険会社で違う。保険会社の窓口と約款で確かめる。治療の要否の判断は医師。", pre:1, say:"入院給付金は、治療のための入院が対象です。今回の入院の目的を書類で確かめて、保険会社に対象になるかを確かめます。", more:"迷いやすいのは、検査入院のはずが、検査の結果で治療が始まった場合です。どこからが治療の入院かで扱いが変わることがあるので、医療機関の書類に入院の目的と経過がどう書かれているかを確かめます。担当が書類の書き方を医療機関に頼むことはしません。", why:"医療保険は、病気やけがの治療にかかる負担に備えるものです。治療の要らない検査や、自宅で過ごす療養まで含めると、保障の範囲が決めにくくなり、加入者どうしの公平が保てないため、入院の意味を約款で決めています。" },
      { key:'faq_xsei_shindansho_hiyou', faq:1, grp:'sei', q:"診断書の費用は誰が払う？", re:/診断書[^。]{0,8}(費用|代|料金|お金|いくら|有料)/, ng:/自動車|火災|損保|会社に出す|休職|勤め先/, head:"請求のための診断書の費用は、請求する方の負担になるのが一般的です。", body:"保険会社に出す診断書や入院の証明は、医療機関に書いていただくもので、その費用は医療機関が決め、請求する方が払うのが一般的です。保険会社から費用が戻らないことが多いので、受け取る給付の額が小さいと、費用のほうが気になる方もいます。保険会社によっては、条件を満たすと診断書の代わりに領収書などで請求できる扱いがあります。", acts:["請求の前に、保険会社に診断書が要るか、ほかの書類で足りるかを確かめる", "診断書の費用は医療機関で違うので、医療機関の窓口で確かめていただく", "一つの診断書で複数の契約を請求できるかも、保険会社に確かめる"], actHead:"現場で使うなら", note:"診断書の要否と代わりの書類の扱いは保険会社で違う。保険会社の窓口で確かめる。診断書の費用は医療機関へ。", pre:1, say:"診断書の費用はご負担になることが多いので、先に保険会社に、診断書が要るか、ほかの書類で足りるかを確かめます。", more:"見落としやすいのは、同じ入院で複数の保険会社に請求するときに、診断書を何通も取ってしまうことです。他社の診断書の写しで受け付ける保険会社もあるので、請求の順番と、どの会社に原本を出すかを先に決めておくと、費用と手間が減ります。", why:"診断書は、医療機関が医師の手間をかけて作る書類で、費用は医療機関が決めています。保険会社は、支払うかどうかを確かめるためにその書類を求めているので、取る費用は請求する方の負担という扱いが一般的です。" },
      { key:'faq_xsei_shindansho_shouryaku', faq:1, grp:'sei', q:"診断書なしで給付金を請求できる？", re:/診断書[^。]{0,4}(なし|無し|無く|なく|不要|いらな|要らな|省略|の省略|を省略)|(領収書|診療明細書|明細書)[^。]{0,6}(だけ|のみ)[^。]{0,10}(請求|給付)/, ng:/自動車|火災|損保|会社に出す|休職|勤め先/, head:"保険会社によっては、条件を満たすと、診断書の代わりに領収書などで請求できます。", body:"請求する給付の内容や額などの条件を満たすと、診断書の代わりに、医療機関の領収書や診療明細書、入院の日付が分かる書類の写しなどで請求できる扱いを設けている保険会社が多くあります。条件は保険会社と契約、請求する給付の種類で違い、がんの診断の給付や高度障害など、診断書が要る請求もあります。", acts:["請求の前に、保険会社にその請求で診断書を省略できるかを確かめる", "領収書と診療明細書を、退院のときに捨てずに取っておいていただく", "省略できないと言われたときは、診断書を取る順番と時期を一緒に決める"], actHead:"現場で使うなら", note:"省略できる条件と代わりの書類は保険会社と契約で違う。保険会社の窓口で確かめる。", pre:1, say:"今回の請求は、診断書の代わりに領収書などで足りる場合があります。保険会社に確かめますので、退院のときの書類は捨てずに取っておいてください。", more:"よくあるのは、領収書を捨ててしまい、結局診断書を取り直すことです。入院や手術の連絡を受けたら、その場で、領収書と診療明細書は取っておくようお願いします。省略の扱いで出した書類から、保険会社が追加の確認を求めることもあります。", why:"診断書には費用と時間がかかるため、小さな額の請求ほどお客様の負担が重くなります。保険会社は、確かめる中身を絞れる請求では、ほかの書類で受け付けて負担を軽くする扱いを設けています。" },
      { key:'faq_xsei_shindansho_yoshiki', faq:1, grp:'sei', q:"診断書は保険会社の用紙で取る？病院の書式でいい？", re:/診断書[^。]{0,12}(用紙|書式|様式|所定|使い回|コピー|写し|ほかの保険会社|他社)|(用紙|書式|様式|所定)[^。]{0,8}診断書|(ほかの保険会社|他社|複数の保険会社)[^。]{0,8}(用)?の?診断書/, ng:/自動車|火災|損保|会社に出す|休職|勤め先/, head:"診断書は保険会社所定の用紙が基本で、ほかの書式や写しを受け付ける保険会社もあります。", body:"保険の請求に使う診断書は、保険会社が用意した所定の用紙に、医療機関に書いていただくのが基本です。保険会社によっては、医療機関の書式の診断書や、ほかの保険会社に出した診断書の写しで受け付ける扱いがあります。受け付けるかどうかと、どの項目が書かれている必要があるかは、保険会社と請求の内容で違います。", acts:["請求の前に、保険会社所定の用紙を取り寄せてお渡しする", "ほかの会社にも請求するときは、写しで受け付けるかを各社に確かめてから診断書を頼む", "用紙の書き方は医療機関にお任せし、こちらから中身を頼まない"], actHead:"現場で使うなら", note:"受け付ける書式と写しの扱いは保険会社で違う。各保険会社の窓口で確かめる。診断書の中身は医療機関と医師が書く。", pre:1, say:"診断書は保険会社の用紙が基本ですが、ほかの書式や写しで受け付ける場合もあります。先に確かめて、診断書を何通も取らずに済む順番にしましょう。", more:"複数の会社に請求するときは、所定の用紙が要る会社に原本を出し、写しで受け付ける会社に写しを出す、という順番にすると無駄が減ります。医療機関が保険会社の用紙に慣れていないこともあるので、用紙は早めにお渡しします。", why:"保険会社は、支払いを決めるのに要る項目（病名・入院の日付・手術の名前など）を漏れなく確かめたいので、所定の用紙を用意しています。同じ項目が分かる書類なら、負担を軽くするために受け付ける扱いもあります。" },
      { key:'faq_xsei_shindansho_naiyou', faq:1, grp:'sei', q:"診断書の中身が、お客様の話と違うときは？", re:/診断書[^。]{0,8}(中身|内容|病名|記載|書いてある)[^。]{0,12}(違|ちが|間違|おかし)|診断書[^。]{0,8}(書き直|訂正|直して)/, ng:/自動車|火災|損保/, head:"診断書の中身は医師が書くもので、担当が書き直しを頼んだり、中身を変えたりはしません。", body:"診断書は、医師が医学の判断で書く書類です。お客様の話と違って見えても、担当が医療機関に書き方を頼んだり、受け取った書類に手を加えたりはしません。お客様が思い違いをしていることもあれば、書き間違いのこともあります。気になる点は、お客様ご自身から医療機関に確かめていただき、保険会社にはそのまま出します。", acts:["どこが違うと感じるのかを、お客様から事実として伺う", "書き間違いかもしれないときは、お客様ご自身から医療機関に確かめていただく", "受け取った書類の中身をこちらで書き足したり消したりせず、そのまま保険会社に出す"], actHead:"現場で使うなら", note:"診断書の中身の判断は医師。支払いの判断は保険会社。担当は書類に手を加えない。迷うときは上長と保険会社の窓口に確かめる。", pre:1, say:"診断書は先生が書かれるものなので、私から書き方をお願いすることはできません。気になるところは、病院に直接確かめていただけますか。", more:"もっとも危ないのは、給付が出やすいように書いてほしいという頼みに、担当が乗ってしまうことです。善意でも不正な請求につながります。病名がお客様の聞いた言い方と違うのは、正式な病名と普段の呼び方の違いであることも多いので、まず落ち着いて確かめます。", why:"保険会社は、医師の書いた診断書を事実として支払いを決めます。担当やお客様が中身に手を加えると、事実と違う請求になり、ほかの加入者との公平と、保険の仕組みそのものへの信頼が崩れるからです。" },
      { key:'faq_xsei_jikou', faq:1, grp:'sei', q:"保険金や給付金の請求に、期限（時効）はある？", re:/(請求|保険金|給付金)[^。]{0,10}(時効|期限)|(請求|給付金|保険金)[^。]{0,6}(は|が)?いつまで(に)?(でき|請求|受け取)/, ng:/年金|手当|還付|高額療養|傷病手当|労災|税|自動車|車両|火災|地震|水災|告知|解除|保険料/, head:"請求には期限があり、法律（保険法）と約款に決まりがあります。", body:"保険金や給付金を請求する権利には、保険法で時効の決まりがあり、約款にも請求の期限が書かれています。期限を過ぎると、原則として請求できなくなります。ただ、事情によっては保険会社が相談に応じることもあるので、過ぎていそうでも、自分であきらめず保険会社に確かめます。いつから数えるかも、約款の決まりで確かめます。", acts:["入院や死亡の連絡を受けたら、期限があることを伝え、書類の手配を先に始めていただく", "前の出来事の請求は、期限の内かどうかを約款と保険会社で確かめる", "期限の年数をこちらで言い切らず、約款の該当の欄を一緒に見る"], actHead:"現場で使うなら", note:"期限の長さと数え始めは、保険法と約款で決まる。約款と保険会社の窓口で確かめる。期限をめぐって争いになるときは弁護士へ。", pre:1, say:"保険の請求には期限があります。急がなくて大丈夫ですが、書類の手配だけは早めに始めておきましょう。", more:"期限で困りやすいのは、ご本人が入院のことを忘れていたり、ご家族が契約を知らなかったりして、時間がたってから気づく場面です。年に一度の契約の点検のときに、この一年で入院や手術が無かったかを伺うと、期限の内に気づけます。", why:"長い時間がたつと、何があったかを確かめる記録が無くなり、支払うかどうかを正しく決められなくなります。だから法律は、権利をいつまでも行使できる形にせず、期限を設けています。" },
      { key:'faq_xsei_kako', faq:1, grp:'sei', q:"何年も前の入院を、今から請求できる？", re:/(何年も前|数年前|昔|ずっと前|前回|以前)の(入院|手術|通院|がん)[^。]{0,16}(請求|給付金|受け取)/, ng:/年金|手当|還付|高額療養|労災|税|自動車|火災|告知/, head:"期限の内なら請求でき、過ぎていても、まず保険会社に相談します。", body:"前の入院や手術でも、請求の期限の内なら請求できます。期限を過ぎていそうなときも、事情によって保険会社が相談に応じることがあるので、自分で決めつけずに確かめます。古い出来事は、医療機関の記録が残っていなかったり、診断書を書いてもらえなかったりして、証明が難しいことがあるので、早めに医療機関に確かめていただきます。", acts:["入院や手術のおおよその時期と医療機関を伺い、保険会社に請求できるかを確かめる", "医療機関に、その時期の記録が残っているか、診断書を書いてもらえるかを確かめていただく", "ほかにも前の入院や手術が無いか、この機会に一緒に思い出していただく"], actHead:"現場で使うなら", note:"請求できる期限と例外の扱いは、保険法・約款と保険会社で決まる。保険会社の窓口で確かめる。医療機関の記録の残り方は医療機関へ。", pre:1, say:"前の入院でも、請求できる場合があります。病院の記録が残っているかも含めて確かめますので、時期と病院を教えてください。", more:"思い出すきっかけになるのは、医療費の領収書、健康保険の医療費の通知、ご本人の手帳やカレンダーです。日帰りの手術や、短い入院は忘れられやすいので、手術の名前を伺いながら一つずつ確かめます。", why:"保険金や給付金は、請求があって初めて支払われる仕組みなので、請求していなければ時間がたっても自動では支払われません。そのため、期限の内に気づいた人が請求することが大切になります。" },
      { key:'faq_xsei_kokuchi_hakken', faq:1, grp:'sei', q:"請求のときに、告知していない持病が分かったら？", re:/(告知(して)?(いない|していな|しなかった|漏れ|もれ)|告知(に|で)書かなかった)[^。]{0,20}(請求|給付金|保険金)|(請求|給付金|保険金)[^。]{0,20}告知(して)?(いない|していな|漏れ|もれ|しなかった)|告知書に書かなかった[^。]{0,16}(請求|給付金|保険金)/, ng:/自動車|火災|損保/, head:"隠さずにそのまま請求していただき、支払いと契約の扱いは保険会社が決めます。", body:"請求のときに、告知していない病気が分かることがあります。そのときも、事実を隠して請求したり、請求をやめさせたりはしません。保険会社が事実を確かめ、告知しなかったことと今回の入院に関係が無ければ支払われる場合もあれば、契約が解除される場合もあります。どちらになるかは保険会社が決め、担当は言い切りません。", acts:["お客様に、事実をありのまま保険会社に伝えていただくようお願いする", "請求の書類から病歴を消す・書き換えるなどの助言は、どんな形でもしない", "解除などの結果になったときに備え、上長に報告し、保障の空白への手当ての相談に乗る"], actHead:"現場で使うなら", note:"支払いの可否と契約の扱いは保険会社が決める。約款と保険会社の窓口で確かめる。争いになるときは弁護士へ。申込みのときの事情は上長とコンプライアンス担当に報告する。", pre:1, say:"告知のことも含めて、ありのままを保険会社に伝えてご請求ください。どう扱われるかは保険会社が決めますが、私も結果まで一緒に見届けます。", more:"申込みのときに担当が告知を省かせていたとしたら、それは担当の大きな問題です。思い当たることがあれば、隠さずに上長とコンプライアンス担当に報告します。お客様に「黙っていれば分からない」と言うことは、不正な請求を手伝うことになります。", why:"保険は、告知された健康状態をもとに引き受けて、加入者どうしの公平を保つ仕組みです。告知と違う事実が分かったときに、それを隠して支払いを受けると、公平が崩れ、詐欺に当たるおそれもあります。" },
      { key:'faq_xsei_kakunin', faq:1, grp:'sei', q:"保険金の請求で、保険会社の調査の人が会いに来ると言われた", re:/(請求|給付金|保険金|支払)[^。]{0,16}(確認|調査)(の)?(担当|会社|員|の人)[^。]{0,16}(来る|会いに|訪問|面談|連絡)|(病院|医療機関)に(問い合わせ|照会|確認)[^。]{0,10}同意書|同意書[^。]{0,12}(請求|給付金|保険金|病院|医療機関)/, ng:/自動車|火災|損保|修理|金融庁|監査|点検|検査/, head:"支払いを決めるために、保険会社が事実を確かめる手続きで、珍しいことではありません。", body:"保険会社は、支払いを正しく決めるために、自社の担当者や委託を受けた確認の会社の担当者が、お客様と面談したり、医療機関に問い合わせたりすることがあります。医療機関への問い合わせには、お客様の同意（同意書）が要ります。疑われているからではなく、事実を確かめる手続きの一つです。", acts:["確認は普通の手続きの一つで、事実をありのまま伝えればよいとお伝えする", "面談の日時と担当者の名乗りを、保険会社に確かめてからお客様にお伝えする", "同席するかどうかは、保険会社の決まりとお客様の希望を確かめてから決める"], actHead:"現場で使うなら", note:"確かめる内容と進め方は保険会社が決める。担当者が本物かどうかも含め、保険会社の窓口で確かめる。", pre:1, say:"支払いを正しく決めるための、普段からある確認です。分かることをそのままお話しいただければ大丈夫です。", more:"お客様が不安になるのは、何を聞かれるか分からないからです。聞かれやすいのは、病気の始まった時期、通っていた医療機関、仕事や暮らしの様子などです。記憶があいまいなことは、無理に答えず分からないと伝えてよいとお伝えします。保険会社を名乗る不審な連絡にも気をつけます。", why:"保険会社は、受け取った書類だけでは分からない事実を確かめてから支払う責任があります。支払いを正しく決めることが、ほかの加入者との公平と、確かな支払いにつながるからです。" },
      { key:'faq_xsei_tsuika_shorui', faq:1, grp:'sei', q:"請求のあと、保険会社から追加の書類を求められた", re:/(追加の|足りない|不足の?)(書類|資料)[^。]{0,10}(求め|言われ|連絡|来た|頼まれ)|(請求|給付金|保険金)[^。]{0,12}書類が(足りな|不足)|(請求|給付金|保険金)[^。]{0,16}(もう一枚|もう一つ|ほかの|別の)書類[^。]{0,8}(出して|求め|言われ)/, ng:/申込|自動車|火災|損保|手数料/, head:"何が足りないか、なぜ要るかを保険会社に確かめ、お客様に一枚で伝えます。", body:"請求のあと、記入の漏れや、支払いを決めるのに要る事実を確かめるために、保険会社から追加の書類を求められることがあります。何が足りないのか、どこで取るのか、なぜ要るのかを保険会社に確かめてから、お客様にお伝えすると、何度もやりとりせずに済みます。追加の書類がそろうまで、支払いは進まないことが多いです。", acts:["保険会社に、足りない書類・取る場所・理由を確かめる", "お客様には、紙一枚で何をどこで取るかをお伝えし、二度手間を減らす", "書類を出したあとも、こちらから保険会社に進み具合を確かめてお伝えする"], actHead:"現場で使うなら", note:"追加の書類の要否と中身は保険会社が決める。保険会社の窓口で確かめる。", pre:1, say:"保険会社から、確かめのための書類を追加で求められています。何をどこで取るかを一枚にまとめましたので、ご無理のない時にお願いします。", more:"戻ってくる理由で多いのは、記入の漏れ、押印や署名の不足、本人確認の書類の期限、受取人の口座の名義の違いです。最初の請求のときに、こちらで書き漏れが無いかを一緒に確かめておくと、戻ってくることが減ります。中身を担当が書き足すことはしません。", why:"保険会社は、支払いを決めるのに要る事実が書類でそろって初めて支払えます。足りないまま支払うと、間違った支払いになるおそれがあるため、追加の書類を求めます。" },
      { key:'faq_xsei_shiharaenai', faq:1, grp:'sei', q:"支払えないと連絡が来たお客様に、どう向き合う？", re:/(支払え|払え|支払われ|支払わ)ない(と|という)[^。]{0,4}(連絡|通知|決ま|言われ|回答|結果)|(保険金|給付金)[^。]{0,4}(が|は)(出ない|おりない|下りない|支払われない)(と|という)[^。]{0,4}(連絡|通知|言われ|決ま|回答)/, ng:/保険料|手数料|給料|給与|家賃|自動車|車両|火災|地震|損保|ローン/, head:"まず気持ちを受け止め、保険会社が書面で示した理由を一緒に確かめます。", body:"支払えないという結果を聞いたお客様は、驚きや怒りを感じていることが多いので、先にお気持ちを受け止めます。そのうえで、保険会社からの書面に書かれた理由（約款のどの決まりに当たったか）を一緒に読み、分からないところは保険会社に確かめます。結果に納得できないときは、保険会社に申し出る道や、相談の窓口があることも伝えます。", acts:["お客様の話を最後まで聞き、言い訳や保険会社の弁護から入らない", "保険会社の書面の理由と、約款の該当の欄を一緒に確かめる", "納得できないときの申し出の窓口を伝え、上長にも報告して記録を残す"], actHead:"現場で使うなら", note:"支払いの判断は保険会社がする。理由の説明は保険会社の窓口で確かめる。不服の申し出は保険会社の窓口、争いになるときは弁護士へ。", go:"kujo", pre:1, say:"思っていたお答えではなく、お気持ちはよく分かります。保険会社からの理由を一緒に確かめ、分からないところは私から確かめます。", more:"このときの一言で、お客様との関係が決まります。「仕方がありません」で終わらせず、理由を一緒に確かめ、ほかの契約や特約で当てはまるものが無いかも探します。納得できないというお申し出は、苦情・お申し出として社内の決まりに従って記録します。", why:"支払えないという結果は、お客様にとって保険への信頼が揺らぐ場面です。理由を分かる形にして、申し出の道も示すことで、結果は変わらなくても、担当と保険への信頼を保てるからです。" },
      { key:'faq_xsei_fufuku', faq:1, grp:'sei', q:"支払いの結果に納得できないお客様の相談先は？", re:/(支払い?の(結果|判断)|査定|保険金の(判断|結果)|給付金の(判断|結果|査定))[^。]{0,8}(納得でき|納得いか|納得しな|不服|不満)/, ng:/自動車|車両|火災|地震|損保|過失|示談|評価|人事|給料/, head:"まず保険会社に申し出て、それでも納得できないときは業界の相談の窓口があります。", body:"支払いの結果に納得できないときは、まず保険会社の窓口に申し出て、理由の説明や、改めて確かめてもらうことを求められます。それでも解決しないときは、生命保険なら生命保険協会の生命保険相談所、損害保険なら日本損害保険協会のそんぽADRセンターなど、中立の立場で相談に乗る窓口があります。法律上の判断が要るときは弁護士に相談します。", acts:["お客様の申し出の中身を書き取り、社内の苦情・お申し出の記録に残す", "保険会社の窓口への申し出の仕方を伝え、必要なら一緒に連絡する", "業界の相談の窓口の名前と連絡先を、各協会の案内で確かめてお伝えする"], actHead:"現場で使うなら", note:"支払いの判断は保険会社がする。相談の窓口の受け付ける範囲と手順は、生命保険協会・日本損害保険協会の案内で確かめる。法律の判断は弁護士へ。", go:"kujo", pre:1, say:"ご納得いただけないお気持ちは当然です。保険会社に改めて確かめてもらう道と、中立の相談の窓口がありますので、順番にご案内します。", more:"申し出のときは、何が納得できないのか（理由の説明か、事実の受け止め方か）を整理しておくと、話が進みます。担当は保険会社の判断を代わりに覆すことはできませんが、事実を整理し、追加で出せる書類が無いかを一緒に考えることはできます。", why:"保険会社の判断にも誤りや説明不足があり得るため、改めて確かめてもらう道と、会社の外の中立の窓口が用意されています。お客様が泣き寝入りしない仕組みがあること自体が、保険への信頼を支えています。" },
      { key:'faq_xsei_tsuin_seikyu', faq:1, grp:'sei', q:"通院給付金の請求に要る書類は？", re:/通院[^。]{0,10}(請求|書類|日数の数え|数え方)/, ng:/自動車|車両|火災|損保|労災|休職/, head:"通院の給付は、入院の給付と一緒か、通院が終わってから請求するのが一般的です。", body:"多くの医療保険の通院の給付は、入院の前後や手術のあとの通院など、約款で決めた通院が対象です。通院した日付が分かる書類（医療機関の領収書や通院の証明）をそろえて請求するのが一般的で、入院の給付と一緒に請求できることもあります。通院だけで対象になるかは商品で違うので、請求の前に約款で確かめます。", acts:["退院のときに、通院の給付が付いているかを証券で確かめてお伝えする", "通院の日付が分かる領収書を、通院のたびに取っておいていただく", "通院が続いている間は、いつまとめて請求するかを一緒に決めておく"], actHead:"現場で使うなら", note:"通院の給付の対象と数え方は約款で違う。保険会社の窓口と約款で確かめる。", pre:1, say:"通院の給付は、入院と一緒か、通院が終わってからまとめて請求できることが多いです。領収書は捨てずに取っておいてください。", more:"通院の給付は、入院の給付より請求を忘れやすいところです。退院の時点ではまだ通院が続いているので、入院の分だけ請求して終わってしまいます。通院が落ち着いたころに、こちらから一度声をかける約束をしておくと漏れが減ります。", why:"通院の給付は、入院や手術に続く治療の負担に備えるものなので、どの通院が対象かを約款で決めています。対象の日付を確かめるために、通院した日が分かる書類が要ります。" },
      { key:'faq_xsei_gan_seikyu', faq:1, grp:'sei', q:"がんの診断給付金の請求に要るものは？", re:/(がん|ガン|癌)[^。]{0,12}(給付金|一時金|保険金|がん保険)[^。]{0,10}(請求|書類|手続|流れ)|(がん保険|ガン保険)[^。]{0,8}(請求|書類|手続)/, ng:/自動車|火災|損保|告知|伝えて|知らせて/, head:"がんの診断の給付は、多くの場合、診断の根拠が分かる診断書をそろえて請求します。", body:"がんの診断の給付は、約款で決めたがんと診断されたことが支払いの条件なので、多くの場合、病理の検査など診断の根拠が書かれた診断書が要ります。上皮内がんの扱いや、二回目以降の給付の条件は商品で違います。告知の内容や、保障が始まるまでの待ち期間に当たらないかも保険会社が確かめるので、責任開始日も一緒に確かめます。", acts:["まずお気持ちを受け止め、手続きは急がなくてよいとお伝えする", "保険会社に、診断書が要るか、どの用紙で取るかを確かめてからお伝えする", "入院・手術・通院の給付など、ほかに請求できるものが無いかも証券で確かめる"], actHead:"現場で使うなら", note:"診断の給付の条件と書類は約款と保険会社で違う。保険会社の窓口と約款で確かめる。診断と治療の判断は医師。", pre:1, say:"お手続きは、お気持ちが落ち着いてからで大丈夫です。要る書類は私が保険会社に確かめて、まとめてお伝えします。", more:"がんの診断を受けた直後は、お客様の頭は治療のことでいっぱいです。担当は書類の話を急がず、入院や手術の予定が決まったころに、診断・入院・手術・通院の請求を一度にまとめる段取りを一緒に考えます。診断書を何通も取らずに済む順番も確かめます。", why:"がんの診断の給付は、診断されたこと自体が支払いの条件なので、約款で決めたがんに当たるかを、医師の書いた根拠で確かめる必要があるからです。" },
      { key:'faq_xsei_senshin_seikyu', faq:1, grp:'sei', q:"先進医療の給付金は、どう請求する？", re:/先進医療[^。]{0,16}(請求|書類|直接支払|直接払|領収書|手続)/, head:"先進医療の給付は、受けた技術の名前と費用が分かる書類をそろえて請求します。", body:"先進医療の給付は、受けた技術が、治療を受けた時点で国が認めた先進医療に当たり、その技術を行うことを認められた医療機関で受けたことが条件です。技術の名前と、自己負担した技術の費用が分かる書類（領収書や証明）をそろえて請求するのが一般的です。保険会社によっては、医療機関に直接支払う扱いを設けています。", acts:["治療を受ける前に、技術の名前と医療機関を伺い、保険会社に対象になるかを確かめる", "直接支払いの扱いがあるか、使うなら事前の手続きが要るかを確かめる", "技術の費用の領収書は、ほかの費用と分けて取っておいていただく"], actHead:"現場で使うなら", note:"対象の技術と医療機関は、治療を受けた時点の国の決まりで変わる。厚生労働省の公表と保険会社の窓口で確かめる。治療の選び方は医師。", pre:1, say:"先進医療の給付は、受けた技術と費用が分かる書類で請求します。治療の前に、対象になるかと病院への直接払いが使えるかを確かめておきましょう。", more:"大事なのは、治療を受ける前に確かめることです。技術の費用は大きくなることがあるので、直接支払いが使えるかどうかで、お客様が一度立て替えるかどうかが変わります。対象の技術の一覧は見直されるので、前に対象だった技術がそのままとは限りません。", why:"先進医療の給付は、国が認めた技術を認められた医療機関で受けたときの、技術の費用の負担に備えるものです。だから、技術の名前・医療機関・費用の三つを書類で確かめてから支払います。" },
      { key:'faq_xsei_menjo_seikyu', faq:1, grp:'sei', q:"保険料の払込免除は、請求しないと始まらない？", re:/(払込免除|保険料(の)?(払込(み)?)?(が)?免除)[^。]{0,12}(請求|手続|自動|申し出|申請|書類|始ま|当たる)/, ng:/国民年金|年金|学生|健康保険/, head:"払込免除は、多くの場合、請求の手続きをして初めて始まります。", body:"払込免除は、約款で決めた病気や状態に当たると、それ以降の保険料の払込が免除される仕組みです。多くの場合、保険会社が自動で始めるのではなく、診断書などをそろえて請求し、保険会社が確かめて初めて免除が決まります。請求しないまま保険料を払い続けていることもあるので、給付金の請求のときに一緒に確かめます。", acts:["入院や手術の給付を請求するときに、払込免除に当たらないかも一緒に確かめる", "保険会社に、免除の請求に要る書類と、既に払った保険料の扱いを確かめる", "免除に当たるかどうかは言い切らず、保険会社の確認を待つと伝える"], actHead:"現場で使うなら", note:"免除の条件と手続きは約款と保険会社で違う。保険会社の窓口と約款で確かめる。", pre:1, say:"保険料の払込免除は、こちらから請求して初めて始まることが多いです。今回の入院で当たるかどうか、保険会社に確かめましょう。", more:"見落としやすいのは、主な契約の免除だけでなく、付けている特約の保険料の扱いです。免除の範囲は契約で違うので、どの保険料が止まるのかを保険会社に確かめます。免除が決まるまでの保険料を払ったときの扱いも、あわせて確かめておきます。", why:"保険会社は、約款で決めた状態に当たるかを確かめてから免除を決めるので、請求と書類が要ります。病気になったことを保険会社が自分から知ることはできないためです。" },
      { key:'faq_xsei_dairi_nashi', faq:1, grp:'sei', q:"指定代理請求人を決めていない契約で、本人が請求できないときは？", re:/(指定代理請求人|代理請求人|代理人)[^。]{0,6}(を)?(決めて|指定して|付けて)(い)?(ない|なか)|(指定代理|代理請求)[^。]{0,10}(付いて|ついて)(い)?(ない|なか)/, head:"代理で請求する決まりが無いときは、法律上の代理人の手続きを考えることになります。", body:"ご本人が意識の無い状態などで請求できず、指定代理請求の決まりも使えないときは、ご家族がそのまま代わりに請求することは原則としてできません。成年後見人などの法律上の代理人を立てて請求する形を考えることになります。保険会社によって扱いが違うこともあるので、まず状況を伝えて、どう進められるかを確かめます。", acts:["保険会社に、ご本人の状況と、請求したい給付を伝えて進め方を確かめる", "法律上の代理人が要りそうなときは、市区町村の窓口や弁護士・司法書士を案内する", "ご本人が回復して請求できる見込みがあるときは、急がずに待つ道もあると伝える"], actHead:"現場で使うなら", note:"請求できる人と扱いは約款と保険会社で違う。保険会社の窓口で確かめる。成年後見の手続きは家庭裁判所・弁護士・司法書士。", pre:1, say:"代わりに請求する決まりが無い契約なので、どう進められるかを保険会社に確かめます。必要なら、法律の手続きの窓口もご案内します。", more:"この場面で分かるのは、契約のうちに代わりに請求する方を決めておく大切さです。ただ、今はその話をする時ではありません。目の前の手続きを落ち着いて進め、ご本人やご家族が落ち着かれたあとで、ほかの契約の見直しを一緒に考えます。", why:"保険金や給付金はご本人の権利なので、ご本人の意思で請求するのが原則です。代わりに請求する決まりが無いと、ご本人の権利を守るために、法律上の代理人の仕組みを使うことになります。" },
      { key:'faq_xsei_tsuuchi', faq:1, grp:'sei', q:"本人に病名を伝えていないとき、保険会社からの通知はどうなる？", re:/(病名|がん|ガン|癌|余命)[^。]{0,10}(を)?(本人|ご本人)?[^。]{0,4}(に)?(伝えて|知らせて|言って|告げて)(い)?(ない|なか)/, head:"保険会社からの通知が本人に届くことがあるので、請求の前にご家族と保険会社で確かめます。", body:"給付金を請求すると、保険会社から支払いの通知などが契約者や被保険者あてに届くことがあり、通知の中身から病名が分かってしまうことがあります。ご家族が代わりに請求する決まりを使うときも、通知の送り先や書き方の扱いは保険会社で違います。病名を伝えるかどうかはご家族と医師の判断なので、担当は請求の段取りだけを手伝います。", acts:["請求の前に、保険会社に、通知の送り先と中身の扱いを確かめる", "ご家族の気持ちを伺い、病名を伝えるかどうかには踏み込まない", "代わりに請求する決まりが使えるかを証券で確かめる"], actHead:"現場で使うなら", note:"通知の送り先と扱いは保険会社で違う。保険会社の窓口で確かめる。病名を伝えるかどうかは、ご家族と医師が決める。", pre:1, say:"保険会社からの書類がご本人に届くことがあるので、送り先や書き方を先に確かめます。ご家族のお気持ちに沿うよう、段取りを一緒に考えます。", more:"気をつけたいのは、ご本人あての郵便や、保険会社からの電話でご本人が知ってしまう場面です。請求の前に保険会社へ事情を伝えておくと、配慮してもらえることがあります。担当が事情をほかの人に話さないことも、改めて気をつけます。", why:"保険会社は、契約の当事者に支払いを知らせる責任があるので、通知を送る仕組みになっています。一方でご家族の事情もあるため、請求の前に扱いを確かめることで、両方を守れます。" },
      { key:'faq_xsei_kouza', faq:1, grp:'sei', q:"保険金の振込先は、どの口座にできる？", re:/(保険金|給付金)[^。]{0,10}(振込先|振り込み先|口座)|(振込先|振り込み先)[^。]{0,8}(保険金|給付金|受取人|家族)/, ng:/変更|変わ|保険料|手数料|給料|給与|紹介料|引き?落|引落/, head:"振込先は、受け取る方ご本人の名義の口座が基本です。", body:"保険金や給付金は、受け取る方ご本人の名義の口座に振り込むのが基本です。死亡保険金なら受取人の方の口座で、亡くなった方の口座には振り込みません。亡くなった方の口座は金融機関に亡くなったことが伝わると動かせなくなることがあるからです。ご家族の口座にできるかは、代わりに請求する決まりなどの事情で違うので、保険会社に確かめます。", acts:["請求の前に、受け取る方ご本人の名義の口座を確かめていただく", "名義の書き方（旧姓・カナ）が請求書と口座で合っているかを一緒に確かめる", "ご本人以外の口座にしたいときは、できるかどうかを保険会社に確かめる"], actHead:"現場で使うなら", note:"振込先の決まりと例外は保険会社で違う。保険会社の窓口で確かめる。口座そのものの手続きは金融機関へ。", pre:1, say:"振込先は、受け取られる方ご本人の名義の口座が基本です。名義の書き方も、請求書と合わせて一緒に確かめましょう。", more:"書類が戻ってくる理由で多いのが、口座の名義の違いです。結婚で名字が変わったまま口座の名義を変えていない、カナの書き方が違う、などです。請求書を書く前に、通帳かキャッシュカードの名義を見せていただくと、二度手間が減ります。", why:"保険会社は、契約で決めた受取人に確かに支払うために、受取人ご本人の名義の口座に振り込みます。別の人の口座に振り込むと、本当に受取人に届いたかが確かめられないからです。" },
      { key:'faq_xsei_shigo_kyufu', faq:1, grp:'sei', q:"亡くなったあとに残った入院給付金は、誰が請求する？", re:/(亡くな|死亡)[^。]{0,8}(あと|後)[^。]{0,12}(入院|手術|給付金)[^。]{0,10}(誰|受け取|請求)|入院中に亡くな[^。]{0,16}(給付金|請求)|(受け取ら|請求し)ない(まま|うちに)[^。]{0,6}亡くな/, ng:/税|相続税|誰のもの|相続財産|自動車|火災/, head:"受け取らないまま亡くなった給付金は、約款の決まりで、受け取る方が決まります。", body:"被保険者が受け取る入院や手術の給付金を、請求しないまま亡くなったときは、約款の決まりにより、死亡保険金の受取人や相続人の方などが請求する形になります。誰が請求するかは契約と約款で違い、死亡保険金とは書類や扱いが違うことがあります。死亡保険金の請求と一緒に、残った給付金が無いかも確かめます。", acts:["死亡保険金の請求のときに、亡くなるまでの入院や手術の給付が残っていないかを確かめる", "保険会社に、誰がどの書類で請求するかを確かめてからお伝えする", "相続の手続きと関わるときは、相続を頼む専門家と順番を合わせていただく"], actHead:"現場で使うなら", note:"誰が請求するかは約款と契約で違う。保険会社の窓口で確かめる。相続と関わるときは弁護士・司法書士、税は税理士へ。", pre:1, say:"亡くなるまでの入院の給付も、請求できることがあります。誰がどの書類で請求するかを、保険会社に確かめてお伝えします。", more:"見落としやすいのは、長い入院のあとに亡くなった場合の入院給付金や、亡くなる前に受けた手術の給付です。ご遺族は死亡保険金のことで頭がいっぱいになるので、担当が亡くなるまでの経過を伺い、残った請求を一緒に拾います。", why:"入院や手術の給付金は、本来は被保険者ご本人が受け取るお金です。ご本人が亡くなると受け取れないので、誰が代わりに受け取るかを約款で決めておく必要があります。" },
      { key:'faq_xsei_azukari', faq:1, grp:'sei', q:"お客様の請求書類を、担当が預かっていい？", re:/(請求|給付金|保険金)[^。]{0,4}(の)?(書類|書)[^。]{0,10}(預か|預け|持ち帰|代わりに[^。]{0,8}(出|送|提出)|郵送)/, ng:/代筆|代わりに書|申込/, head:"請求書類を預かるかどうかは、所属保険会社と社内の決まりに従います。", body:"請求の書類には、病名や口座など大切な情報が入っています。担当が預かって保険会社へ出してよいかは、所属保険会社の決まりと社内の手順で決まっていて、お客様から直接保険会社へ送っていただく形の会社も多くあります。預かるときは、受け取った日と中身を記録し、無くしたり見られたりしない扱いを守ります。", acts:["預かってよいかを、所属保険会社の決まりと社内の手順で先に確かめる", "預かるときは、受け取った日・書類の名前・枚数を記録し、お客様にも控えをお渡しする", "書類の中身を書き足したり、預かったまま置いたりしない"], actHead:"現場で使うなら", note:"書類を預かる扱いは、所属保険会社の決まりと社内の規程で確かめる。迷うときは上長とコンプライアンス担当に確かめる。", pre:1, say:"書類の出し方は会社の決まりがあるので、確かめてからご案内します。お預かりする場合は、控えをお渡ししますね。", more:"事故が起きやすいのは、預かった書類を車に置いたまま、机の上に出したまま、という扱いです。請求の書類は個人の情報がたくさん入っているので、預かる場合も、その日のうちに出すか、決まった場所にしまうかを決めておきます。", why:"請求の書類は病名や口座など大切な個人の情報で、無くすとお客様に大きな迷惑がかかります。だから扱いを会社で決め、誰がいつ何を預かったかを残す仕組みにしています。" },
      { key:'faq_xsei_tasha', faq:1, grp:'sei', q:"扱っていない保険会社や共済の請求を頼まれたら？", re:/(扱っていない|取り扱っていない|担当していない|ほかの保険会社|他社|共済)[^。]{0,16}(請求|給付金|保険金)[^。]{0,10}(頼まれ|手伝|手続|どこ|どう|出す)/, ng:/診断書|自動車|火災/, head:"扱っていない契約の請求は、その保険会社や共済の窓口へつなぐのが基本です。", body:"担当が扱っていない保険会社や共済の契約は、その契約の窓口（保険会社・共済・その契約を扱った代理店）に請求するのが基本です。担当は契約の中身や手続きの決まりを知らないので、代わりに判断はできません。お客様が困っているときは、証券に書かれた連絡先を一緒に確かめ、連絡の仕方を案内するところまで手伝います。", acts:["証券や共済の書類で、請求の窓口の連絡先を一緒に確かめる", "連絡するときに伝えること（契約の番号・出来事の日付）をメモにしてお渡しする", "中身の判断はせず、その窓口の案内に従っていただく"], actHead:"現場で使うなら", note:"その契約の請求の決まりは、その保険会社・共済・扱った代理店の窓口で確かめる。社内で手伝える範囲は社内の規程で確かめる。", pre:1, say:"その保険の請求は、契約先の窓口にお願いすることになります。連絡先と、伝えることを一緒にまとめましょう。", more:"ここで丁寧に手伝うと、お客様は「この人に聞けば道が分かる」と感じてくださいます。ただし、扱っていない契約について出る・出ないを言うのは、知らない約款で判断することになるので避けます。全体の保障を一度一緒に並べる話は、落ち着いたあとにします。", why:"請求の判断はその契約の約款で決まり、窓口はその契約先だからです。扱っていない担当が判断すると、間違った案内になるおそれがあります。" },
      { key:'faq_xsei_dekiru', faq:1, grp:'sei', q:"保険金の請求で、募集人ができることは？", re:/(請求|保険金|給付金)[^。]{0,12}(募集人|担当|代理店)[^。]{0,8}(できる|できない|して(いい|よい|もいい|はいけな)|どこまで|手伝)|(募集人|担当|代理店)[^。]{0,6}(が|は|として)?[^。]{0,6}(請求|保険金の手続)[^。]{0,12}(できる|どこまで|手伝|してはいけな)/, ng:/代筆|代わりに書|ほかの代理店|他の代理店|別の代理店|他社|で入った/, head:"担当ができるのは、請求の案内と書類の手配の手伝いまでで、支払いを決めるのは保険会社です。", body:"担当ができるのは、請求できる給付があるかを証券で一緒に確かめる、保険会社に連絡して要る書類を案内する、書類の書き漏れが無いかを一緒に見る、進み具合を確かめて伝える、といった手伝いです。支払うかどうかや金額を決めること、診断書の中身に口を出すこと、お客様に代わって書類を書くことはしません。範囲は社内の決まりでも確かめます。", acts:["請求の連絡を受けたら、証券で請求できそうな給付を一緒に洗い出す", "保険会社への連絡と書類の手配を手伝い、進み具合をこちらから伝える", "支払いの可否や金額を聞かれても言い切らず、保険会社の判断を待つと伝える"], actHead:"現場で使うなら", note:"担当の役割の範囲は、所属保険会社の決まりと社内の規程で確かめる。支払いの判断は保険会社。", pre:1, say:"請求できるものを一緒に確かめて、書類の手配までお手伝いします。お支払いを決めるのは保険会社なので、結果は保険会社からのお知らせを待ちましょう。", more:"請求の場面は、担当への信頼がいちばん育つ場面です。お客様が困っているときに、連絡が早い、書類の説明が分かりやすい、進み具合を自分から伝える、という当たり前を続けます。逆に、出るかどうかを先に言ってしまうと、結果が違ったときに信頼を失います。", why:"保険金の支払いは、保険会社が約款と事実に照らして決めるものです。担当が判断に入り込むと、間違った期待を持たせたり、不正な請求に巻き込まれたりするおそれがあるため、役割を手伝いに限っています。" },
      { key:'faq_xsei_dantai_seikyu', faq:1, grp:'sei', q:"勤め先の団体保険の請求は、どこに出す？", re:/(団体保険|団体定期|グループ保険|勤め先の保険|職場の保険|職場で入っている保険)[^。]{0,10}(請求|給付金|保険金|手続|流れ)/, ng:/団体信用|団信|ローン/, head:"勤め先の団体保険は、多くの場合、勤め先の担当部署を通して請求します。", body:"勤め先を通して入る団体保険は、契約者が勤め先や団体になっていることが多く、請求も勤め先の担当部署（総務・人事など）を通して行う形が一般的です。どの書類が要り、誰に出すかは団体ごとの決まりで違います。退職などで加入の状態が変わっていると扱いも変わるので、まず勤め先の担当部署に確かめていただきます。", acts:["勤め先の担当部署に、請求の窓口と要る書類を確かめていただく", "ご自身で入っている保険と、勤め先の保険の両方で請求できるものを一緒に洗い出す", "退職の時期と出来事の日付が近いときは、加入の状態を先に確かめていただく"], actHead:"現場で使うなら", note:"団体保険の請求の窓口と書類は、団体ごとの決まりで違う。勤め先の担当部署と、その保険会社の窓口で確かめる。", pre:1, say:"勤め先で入っている保険は、会社の担当の部署が窓口になることが多いです。そちらと、ご自身で入っている保険の両方を一緒に確かめましょう。", more:"団体保険は、お客様ご自身が入っていることを忘れていることがよくあります。入院や亡くなった連絡を受けたら、勤め先の保険や、組合の共済が無いかも伺います。ご遺族は勤め先に連絡しにくいことがあるので、聞く順番を一緒に考えます。", why:"団体保険は、勤め先や団体が契約者になって、まとめて入る仕組みです。契約の窓口が勤め先なので、請求も勤め先を通す形になります。" },
      { key:'faq_xsei_danshin_seikyu', faq:1, grp:'sei', q:"団信の保険金の請求は、どこに出す？", re:/(団信|団体信用生命|団体信用)[^。]{0,12}(請求|手続|書類|どこ|流れ)/, head:"団信の請求は、住宅ローンを借りている金融機関に連絡するところから始めます。", body:"団信（団体信用生命保険）は、住宅ローンを借りた金融機関などが契約者と受取人になっていることが多く、保険金はローンの返済に充てられます。だから請求も、まず借入先の金融機関に連絡し、案内に従って書類を出す形が一般的です。保障の範囲（死亡のほか、病気の状態で支払われるもの）は契約で違うので、借入先に確かめていただきます。", acts:["借入先の金融機関の連絡先を、ローンの書類で一緒に確かめる", "亡くなった場合だけでなく、病気の状態で支払われる保障が付いていないかも確かめていただく", "ご自身で入っている保険の請求とは別の手続きだと、分けて整理する"], actHead:"現場で使うなら", note:"団信の請求の窓口と保障の範囲は、借入先の金融機関と契約で違う。金融機関の窓口で確かめる。相続と関わるときは司法書士・税理士へ。", pre:1, say:"住宅ローンの団信は、借りている金融機関に連絡するところから始めます。ご自身の保険の請求とは別に、一緒に整理しましょう。", more:"団信は、ご遺族が手続きを知らずに、ローンの返済を続けてしまうことがあります。亡くなった連絡を受けたら、住宅ローンがあるかを伺い、あれば借入先へ早めに連絡していただくよう伝えます。登記の手続きが関わるときは司法書士に相談していただきます。", why:"団信は、ローンを借りた人に万一のことがあったとき、保険金で残りのローンを返す仕組みです。保険金を受け取るのが借入先なので、請求の窓口も借入先になります。" },
      { key:'faq_xsei_kaigai', faq:1, grp:'sei', q:"海外で入院したときの給付金の請求は？", re:/(海外|外国|国外)[^。]{0,12}(入院|手術|病院|治療|診断書)[^。]{0,16}(請求|給付金|書類|出る|対象|できる)/, ng:/旅行保険|海外旅行保険|旅行の保険|クレジットカード|カード|移住|住む|赴任/, head:"海外での入院や手術も、約款の条件に当たれば請求できる医療保険が多くあります。", body:"多くの医療保険は、海外での入院や手術も、約款の入院や手術の決まりに当たれば給付の対象にしています。ただ、現地の医療機関の診断書や領収書に、日本語の訳文を付けるよう求められることが多く、書類をそろえるのに時間がかかります。対象になる治療の範囲や書類の扱いは商品と保険会社で違います。現地で払った医療費は、健康保険の海外療養費の手続きが別にあります。", acts:["帰国後でもよいので、現地の診断書と領収書を捨てずに持ち帰っていただく", "保険会社に、海外での請求に要る書類と、訳文の扱いを確かめる", "健康保険の海外療養費は別の手続きなので、加入している健康保険の窓口を案内する"], actHead:"現場で使うなら", note:"海外の治療の扱いと書類は約款と保険会社で違う。保険会社の窓口と約款で確かめる。海外療養費は加入している健康保険の窓口へ。", pre:1, say:"海外での入院も、請求できることが多いです。現地の書類を持ち帰っていただければ、要る訳文なども保険会社に確かめてご案内します。", more:"困りやすいのは、現地の書類を持ち帰らなかったり、帰国してから取り寄せるのに手間取ったりすることです。海外へ行かれるお客様には、出発の前に、何かあったら現地の書類を取っておくようお伝えしておくと、いざというときに助かります。", why:"医療保険は、約款で決めた入院や手術に当たるかで支払いを決めるので、治療を受けた場所が海外でも対象になることがあります。ただ、外国の書類の中身を確かめるために、訳文などが求められます。" },
      { key:'faq_xsei_meisai', faq:1, grp:'sei', q:"支払いの通知（明細）の見方を聞かれた", re:/支払(い)?(の)?(通知|明細|お知らせ|内容のお知らせ)|支払明細|支払通知|(思っていた|聞いていた)(額|金額)と違/, ng:/保険料|手数料|給料|給与|年金|税/, head:"支払いの通知には、支払った給付ごとの日数や額と、差し引いたものが書かれています。", body:"支払いの通知（明細）には、どの給付をどの日数や回数で支払ったか、差し引いたもの（払われていない保険料など）があればその中身、振込先が書かれているのが一般的です。思っていた額と違うときは、対象にならなかった日数や、支払いの限度に当たった部分がないかを、通知と約款で一緒に確かめます。分からないところは保険会社に確かめます。", acts:["通知をお客様と一緒に見て、給付ごとに日数や回数を確かめる", "思っていた額と違うときは、どこが違うかを書き出してから保険会社に確かめる", "結果を変えることはできないと伝えたうえで、説明を受け直す道を案内する"], actHead:"現場で使うなら", note:"支払いの中身の説明は保険会社の窓口で確かめる。支払いの判断は保険会社がする。", pre:1, say:"通知を一緒に見て、どの給付をどれだけお支払いしたのかを確かめましょう。分からないところは、私から保険会社に確かめます。", more:"額が違って見える理由で多いのは、入院の日数の数え方、支払いの限度の日数、対象にならない手術、差し引いた保険料です。通知を見ながら一つずつ確かめると、多くは理由が分かります。それでも納得できないときは、保険会社に申し出る道があります。", why:"保険会社は、どの決まりでいくら支払ったかを契約者や受取人が確かめられるよう、通知で中身を示しています。中身が分かれば、ほかに請求できるものの見落としにも気づけます。" },
      { key:'faq_xsei_sashihiki', faq:1, grp:'sei', q:"保険金から貸付金が差し引かれていた", re:/(保険金|給付金)[^。]{0,10}(から)?[^。]{0,8}(貸付|貸し付け|未払|払われていない保険料|保険料)[^。]{0,8}(が|を)?(差し引|差引|引かれ|相殺)|(保険金|給付金)[^。]{0,8}(思ったより|聞いていたより|予定より)少な/, ng:/税|源泉|所得税|住民税|契約者貸付は差し引/, head:"契約者貸付や払われていない保険料があると、保険金から差し引いて支払うのが一般的です。", body:"契約者貸付を受けていたり、自動で保険料を貸し付ける仕組みが使われていたりすると、その残りと利息を保険金から差し引いて支払うのが一般的です。猶予期間のうちの払われていない保険料も同じように差し引かれます。何がいくら差し引かれたかは支払いの通知に書かれているので、一緒に確かめ、分からないところは保険会社に確かめます。", acts:["支払いの通知で、差し引かれたものの中身を一緒に確かめる", "貸付を受けていたことをご遺族が知らないこともあるので、落ち着いて事実を伝える", "中身に疑問があるときは、保険会社に貸付の履歴を確かめる"], actHead:"現場で使うなら", note:"差し引く中身と扱いは約款と契約で決まる。保険会社の窓口で確かめる。", pre:1, say:"保険金から、借りていたお金や払われていない保険料が差し引かれていることがあります。通知を一緒に見て、中身を確かめましょう。", more:"ご遺族が驚くのは、亡くなった方が保険からお金を借りていたことを知らなかった場面です。責める話にせず、事実として通知の中身を説明します。契約のうちに貸付を受けている方には、残りがあることを時々お伝えしておくと、こうした驚きを減らせます。", why:"契約者貸付は、解約したときに戻るお金の範囲で保険会社が貸すお金です。保険金を支払うときには、その貸したお金と利息を精算する決まりになっています。" },
      { key:'faq_xsei_saigai', faq:1, grp:'sei', q:"災害の特約の請求に要るものは？", re:/(災害(割増|入院|死亡)?特約|災害の特約|傷害特約|不慮の事故)[^。]{0,12}(請求|書類|手続|要る)|交通事故証明書|事故で入院[^。]{0,12}(特約|請求|書類)/, ng:/自動車保険|車両|火災|損保|示談|過失/, head:"災害の特約は、事故で起きたことを確かめる書類が加わるのが一般的です。", body:"災害の特約は、約款で決めた不慮の事故などが原因のときに支払われるので、病気の給付の書類に加えて、事故の状況を確かめる書類が求められるのが一般的です。交通事故なら交通事故証明書、そのほかの事故なら事故の状況を書いた書類などです。事故から時間がたっていたり、病気と重なっていたりすると、確かめるのに時間がかかることがあります。", acts:["事故の日時・場所・状況を、お客様から事実として伺う", "保険会社に、事故を確かめる書類として何が要るかを確かめる", "交通事故証明書は、取り方を案内し、早めに取っていただく"], actHead:"現場で使うなら", note:"対象になる事故の決まりと書類は約款と保険会社で違う。保険会社の窓口と約款で確かめる。交通事故証明書の取り方は自動車安全運転センターの窓口へ。", pre:1, say:"事故が原因の請求なので、事故の状況が分かる書類も要ります。保険会社に確かめて、取り方と一緒にご案内します。", more:"大事なのは、事故の状況を担当が作文しないことです。お客様の話のとおりに、分かることだけを書いていただきます。病気が原因か事故が原因かで扱いが変わることがあるので、どちらと決めるかは保険会社に任せます。自動車保険など損害保険の請求は別の窓口です。", why:"災害の特約は、病気ではなく不慮の事故が原因のときに上乗せされる保障です。だから、事故が原因だったことを書類で確かめる必要があります。" },
      { key:'faq_xsei_teigaku', faq:1, grp:'sei', q:"健康保険や労災から出ても、医療保険は請求できる？", re:/(健康保険|労災|高額療養費|相手(の|方の)?(保険|賠償)|勤め先から|会社から)[^。]{0,16}(出|戻|もら|受け取|払われ)[^。]{0,12}(医療保険|給付金|自分の保険|自分の医療保険)[^。]{0,10}(請求|もらえ|出る|受け取|減る)/, head:"多くの医療保険は、公的な給付や相手方の賠償とは別に、決めた額を支払う形です。", body:"多くの生命保険会社の医療保険は、入院の日数や手術の種類で決めた額を支払う形なので、健康保険・高額療養費・労災・相手方の賠償などから支払いがあっても、それとは別に請求できることが多くあります。ただ、実際にかかった費用を補う形の保険（損害保険の医療の保険など）は、ほかから出た分と調整されることがあります。どちらの形かは約款で確かめます。", acts:["お客様の医療保険が、決めた額を払う形か、かかった費用を補う形かを約款で確かめる", "公的な給付の手続きは、それぞれの窓口（健康保険・労働基準監督署など）を案内する", "請求できるものを一覧にして、窓口ごとに分けてお渡しする"], actHead:"現場で使うなら", note:"支払いの形と調整の決まりは約款で違う。保険会社の窓口と約款で確かめる。公的な給付は加入している健康保険・労働基準監督署の窓口へ。", pre:1, say:"公的な給付や相手の方の保険とは別に、ご自身の医療保険も請求できることが多いです。契約の形を確かめて、窓口ごとに一覧にしますね。", more:"お客様は「ほかで出たから、自分の保険はいい」と思い込みやすいところです。請求できるものを窓口ごとに書き出すと、漏れが減ります。逆に、かかった費用を補う形の保険では、受け取りが重ならないように調整されることがあるので、言い切らずに約款で確かめます。", why:"決めた額を払う形の医療保険は、かかった費用そのものを補うのではなく、入院や手術という出来事に対して支払う約束です。だから、ほかからの支払いとは別に受け取れる仕組みになっています。" },
      { key:'faq_xsei_tsuika_seikyu', faq:1, grp:'sei', q:"請求したあとに、ほかにも請求できる給付があると分かった", re:/(請求した|受け取った|もらった)(あと|後)[^。]{0,16}(ほかに|ほかにも|別の|追加で)[^。]{0,10}(給付|請求|特約|保険金)|追加(で)?(の)?請求|(もらった|受け取った)(あと|後)[^。]{0,12}(手術|通院|特約)[^。]{0,8}(出る|気づ|分か)/, ng:/保険料|手数料|税|自動車|火災/, head:"期限の内なら、あとから気づいた給付も改めて請求できます。", body:"入院の給付を受け取ったあとに、手術や通院の給付、特約の給付などがあると分かったときは、請求の期限の内なら改めて請求できます。前に出した診断書や書類が使えることもあれば、新しく要ることもあるので、保険会社に確かめます。同じ入院で、ほかの保険会社の契約にも請求できるものがないか、一緒に確かめます。", acts:["保険会社に、追加の請求に要る書類と、前の書類が使えるかを確かめる", "証券を一緒に見直し、ほかに付いている特約が無いかを確かめる", "次に入院や手術があったときに漏れないよう、請求できるものの一覧をお渡しする"], actHead:"現場で使うなら", note:"追加の請求の扱いと書類は保険会社で違う。保険会社の窓口で確かめる。期限は約款で確かめる。", pre:1, say:"あとから気づいた給付も、改めて請求できることが多いです。前の書類が使えるかも含めて、保険会社に確かめます。", more:"あとから気づくのは、担当として少し悔しい場面です。最初の請求のときに、証券の全ての特約を一緒に読み上げて確かめると、こうした漏れは減ります。気づいたときに隠さず伝えて手伝うことで、かえって信頼が深まります。", why:"保険金や給付金は、請求があって初めて支払われる仕組みです。一度の請求で全てを確かめる仕組みではないので、あとから気づいたものは、改めて請求することになります。" },
      { key:'faq_xsei_web', faq:1, grp:'sei', q:"保険金の請求は、ネットやアプリでできる？", re:/(請求|給付金|保険金)[^。]{0,12}(ネット|インターネット|アプリ|スマホ|スマートフォン|オンライン|ウェブ|web)|(ネット|インターネット|アプリ|スマホ|スマートフォン|オンライン|ウェブ|web)[^。]{0,12}(請求|給付金|保険金)/, ng:/契約|申込|加入|解約/, head:"ネットやアプリで請求できる保険会社が増えていますが、使える請求の範囲は会社で違います。", body:"保険会社によっては、ホームページやアプリから請求の手続きができ、書類を写真で出せる扱いもあります。ただ、使えるのは一定の給付や条件に当たる請求だけのことが多く、死亡保険金のように書類の原本が要る請求は、郵送などの手続きになることがあります。使えるかどうかと手順は、各保険会社の案内で確かめます。", acts:["保険会社のホームページで、ネットで請求できる給付と条件を確かめる", "お客様がスマホの操作に慣れているかを伺い、合う出し方を一緒に選ぶ", "書類の写真が読める形か、出す前に一緒に確かめる"], actHead:"現場で使うなら", note:"ネットでの請求の範囲と手順は保険会社で違う。各保険会社の窓口と案内で確かめる。", pre:1, say:"保険会社によっては、スマホから請求できます。今回の請求で使えるかを確かめて、出し方を一緒に選びましょう。", more:"ネットの請求は早い一方で、写真がぼやけていたり、書類の一部が写っていなかったりすると、やり直しになります。お客様が慣れていないときは、無理にネットにせず、郵送の手続きを選んでいただいてかまいません。", why:"書類を写真で受け付けると、郵送の手間と時間が減るので、保険会社はネットでの請求を広げています。ただ、確かめるのに原本が要る請求もあるため、範囲を決めて受け付けています。" },
      { key:'faq_xsei_deru_to', faq:1, grp:'sei', q:"お客様に「出ますよ」と言ってしまった", re:/(出ます|おります|下ります|支払われます)(よ)?[^。]{0,4}(と)?(言って|伝えて)しま|(出る|おりる|下りる|支払われる)と(言って|伝えて|言い切って)しま|(出ると|おりると)(伝えた|言った)のに/, head:"すぐにお客様に正直に伝え直し、支払いは保険会社が決めることを改めてお伝えします。", body:"支払うかどうかは保険会社が約款と事実で決めるので、担当が「出ます」と言い切ることはできません。言ってしまったと気づいたら、結果が出る前に、お客様に「保険会社が確かめて決めることで、言い切ったのは私の誤りでした」と伝え直します。支払われなかったときは、理由を一緒に確かめ、言い過ぎたことも含めて上長に報告します。", acts:["結果が出る前に、お客様に正直に伝え直す", "上長に事実を報告し、社内の決まりに従って記録を残す", "次からは「保険会社が確かめて決めます」の言い方に揃える"], actHead:"現場で使うなら", note:"支払いの判断は保険会社がする。伝え直し方とお客様からの申し出の扱いは、上長とコンプライアンス担当に確かめ、社内の規程に従う。", pre:1, say:"先日、お支払いを言い切るようなお伝え方をしてしまいました。お支払いは保険会社が確かめて決めることで、私の誤りでした。結果が出るまで、私も一緒に見届けます。", more:"言い切りたくなるのは、お客様を安心させたい気持ちからです。けれど、結果が違えば、安心は一度に不信に変わります。言える言い方は「請求できる給付が付いています。お支払いは保険会社が確かめて決めます」です。期待を持たせ過ぎず、手続きは丁寧に手伝います。", why:"担当の言葉は、お客様にとって保険会社の言葉と同じ重さで届きます。結果を約束すると、違ったときに誤った説明になり、お客様の信頼と担当の立場の両方を損なうからです。" },
      { key:'faq_xsei_ikura', faq:1, grp:'sei', q:"給付金がいくら出るか、お客様に聞かれた", re:/(給付金|保険金)[^。]{0,6}(が|は)?(いくら|どのくらい|どれくらい)(出|もらえ|支払|受け取|おり)/, ng:/必要|要る|いる|足り|税|相続税|保険料|死亡|どこで/, head:"証券の額と約款から見込みは話せますが、確かな額は保険会社の支払いで決まります。", body:"入院の給付は日額と日数、手術の給付は手術の種類ごとの決まりなど、証券と約款から見込みを一緒に計算することはできます。ただ、入院の日数の数え方、対象になる手術かどうか、支払いの限度、差し引くものなどで、実際の額は変わることがあります。見込みとして伝え、確かな額は保険会社の支払いの通知で確かめていただきます。", acts:["証券と約款を一緒に見て、見込みの計算の仕方を説明する", "「見込みで、確かな額は保険会社が決めます」と添えて伝える", "対象になるか迷う手術や入院は、先に保険会社に確かめる"], actHead:"現場で使うなら", note:"支払う額は保険会社が約款と事実で決める。対象の決まりと計算は約款と保険会社の窓口で確かめる。", pre:1, say:"証券から見込みを一緒に計算しますね。確かな額は、保険会社が確かめてからのお知らせで決まります。", more:"見込みを伝えるときは、数字だけを一人歩きさせない工夫をします。計算の根拠（日額と日数など）を一緒に紙に書き、「ここが変わると額も変わります」と添えます。手術の給付は対象かどうかで大きく変わるので、手術の名前が分かったら保険会社に確かめます。", why:"給付の額は、約款の決まりと、医療機関の書類で分かる事実で決まります。担当が先に額を言い切ると、事実が違ったときに誤った説明になるため、見込みと確かな額を分けて伝えます。" },
      { key:'faq_xsei_tamerau', faq:1, grp:'sei', q:"給付金を請求すると、保険料が上がる？", re:/(請求|給付金を受け取|給付金をもら)[^。]{0,12}(保険料|掛金)[^。]{0,6}(が)?(上が|高く|増え)|請求(する|した)と[^。]{0,8}(入れなく|加入でき)|請求(を)?(ためら|遠慮|迷っ|しない方が|しないほうが)/, ng:/自動車|車|等級|火災|事故で保険を使|地震/, head:"多くの生命保険・医療保険では、給付を受けても、その契約の保険料は上がらない仕組みです。", body:"多くの生命保険会社の医療保険は、給付を受けたことを理由に、その契約の保険料が上がる仕組みにはなっていません。ためらって請求しないと、受け取れるものを受け取れないままになります。ただ、あとで新しい保険に入るときは、入院や手術の事実を告知することになり、入り方に影響することがあります。それは請求したかどうかではなく、病気やけがの事実によるものです。", acts:["請求をためらう理由を伺い、保険料の仕組みを落ち着いて説明する", "その契約の保険料の決まりは、約款と保険会社で確かめてから伝える", "新しく保険に入るときの告知は、請求したかどうかではなく事実で答えるものだと伝える"], actHead:"現場で使うなら", note:"保険料の決まりは商品と約款で違う。保険会社の窓口と約款で確かめる。新しい契約の引き受けは保険会社が決める。", pre:1, say:"多くの医療保険は、給付を受けてもその契約の保険料は上がりません。受け取れるものは、ご遠慮なくご請求ください。", more:"ためらう方の多くは、自動車保険の等級の話と重ねて考えています。自動車保険は使うと次の保険料に響く仕組みがありますが、医療保険は多くの場合そうではありません。どちらの話かを分けて説明します。告知を偽ってよいという話にはしません。", why:"医療保険は、入院や手術という出来事に備えて保険料を出し合う仕組みで、多くは加入のときに保険料を決めています。給付を受けた人の保険料を上げる形にはしていない商品が多いためです。" },
      { key:'faq_xsei_byouin', faq:1, grp:'sei', q:"担当が病院に問い合わせてもいい？", re:/(担当|募集人|私|代理店)[^。]{0,8}(が|から|の方から)?[^。]{0,4}(病院|医療機関|主治医|医師)[^。]{0,4}(に|へ)[^。]{0,6}(問い合わせ|確認|確かめ|聞いて|聞い|電話)|(代わりに|代理で)[^。]{0,6}(病院|医療機関|主治医|医師)[^。]{0,4}(に|へ)[^。]{0,8}(問い合わせ|電話|聞)|(主治医|医師|病院)(に|へ)[^。]{0,8}(病名|入院の日)[^。]{0,4}(を)?(確かめ|聞)/, head:"病院への問い合わせは、担当からはしません。お客様ご本人か、保険会社が同意を得て行います。", body:"病名や入院の中身は、お客様の大切な個人の情報で、医療機関は本人の同意なしに外へ伝えません。担当が病院に問い合わせると、お客様の情報を勝手に扱うことになり、医療機関にも迷惑がかかります。入院の日付などはお客様に領収書で確かめていただき、支払いのために医療機関へ確かめるのは、保険会社がお客様の同意を得て行います。", acts:["入院の日付や手術の名前は、お客様に領収書や医療機関の書類で確かめていただく", "保険会社が医療機関に確かめることがあると、先にお伝えしておく", "医療機関への連絡を頼まれても、担当からはしないと丁寧に伝える"], actHead:"現場で使うなら", note:"医療機関への照会は保険会社が本人の同意を得て行う。個人情報の扱いは社内の規程とプライバシーの決まりで確かめる。", pre:1, say:"病院への問い合わせは、私からはできないんです。入院の日付は領収書で一緒に確かめましょう。保険会社が確かめるときは、ご同意をいただいてからになります。", more:"善意で病院に電話したくなる場面ほど気をつけます。お客様のためと思っても、医療機関から見れば、知らない人が患者の情報を聞いてきたことになります。担当の仕事は、お客様が書類を集める段取りを手伝うことで、情報を取りに行くことではありません。", why:"病気の情報は、とくに慎重に扱う個人の情報です。本人の同意なく第三者が取り扱うと、お客様の権利を損ない、医療機関や保険会社との信頼も崩れるからです。" },
      { key:'faq_xsei_shuugyou', faq:1, grp:'sei', q:"就業不能の給付金は、一度の請求で終わる？", re:/(就業不能|働けない状態|所得補償)[^。]{0,12}(給付金|保険金|保険)?[^。]{0,8}(請求|書類|毎月|何度|続けて|一度)/, ng:/傷病手当|労災|障害年金|休職|有給/, head:"就業不能の給付は、働けない状態が続いているかを、一定の間ごとに確かめて支払う形が多くあります。", body:"就業不能の給付は、約款で決めた働けない状態が続いている間、毎月などの形で支払われる商品が多くあります。そのため、最初の請求のあとも、状態が続いていることを確かめる書類を、決められた間ごとに出すよう求められることがあります。どんな状態が対象か、待つ期間や支払いの期間は商品で違うので、約款で確かめます。", acts:["最初の請求のときに、続けて出す書類と、その時期を保険会社に確かめる", "続けて出す時期を、お客様と一緒に手帳やカレンダーに書いておく", "公的な給付（傷病手当金など）の手続きは、それぞれの窓口を案内する"], actHead:"現場で使うなら", note:"対象の状態・待つ期間・支払いの期間と書類は約款で違う。保険会社の窓口と約款で確かめる。公的な給付は加入している健康保険などの窓口へ。", pre:1, say:"働けない状態が続く間は、決まった時期ごとに続けて請求することが多いです。次に出す時期を、一緒に書いておきましょう。", more:"働けない状態のお客様は、書類のことまで気が回らないことが多いので、続けて出す時期を担当が覚えておき、近づいたら声をかけます。状態がよくなって仕事に戻るときの届け出が要る商品もあるので、それも一緒に確かめておきます。", why:"就業不能の給付は、働けない状態が続いていることに対して支払うものです。状態は時間とともに変わるので、支払いを続けるたびに、今も続いているかを確かめる仕組みになっています。" },
      /* szi.json */
      { key:'faq_xszi_kyuyo_kojo', faq:1, grp:'szi', q:"給与所得控除とは？", re:/給与所得控除|会社員の(必要)?経費/, head:"会社員の必要経費の代わりに、給与の収入額に応じて決まった額を差し引く仕組みです。", body:"会社員は、仕事のための費用を一つずつ経費として引く代わりに、給与の収入額に応じて決まる給与所得控除を引きます。給与の収入から給与所得控除を引いた残りが給与所得になります。額は収入に応じて段階的に決まり、税制改正で見直されてきました。仕事の費用が多い方には、特定支出控除という別の仕組みもあります。", acts:["源泉徴収票の支払金額と、給与所得控除後の金額の欄を並べてご説明する", "収入と所得は違う、という一言を最初にお伝えする", "最新の控除の額は、国税庁の公表か勤め先の担当の方で確かめていただく"], actHead:"現場で使うなら", note:"給与所得控除の額と特定支出控除の要件は国税庁の公表で確かめる。個別の税額の判断は税理士か税務署の窓口。", pre:1, say:"会社員の方は、仕事の経費を一つずつ集める代わりに、収入に応じて決まった額を差し引ける仕組みがあります。源泉徴収票の給与所得控除後の金額の欄が、引いたあとの数字です。", more:"源泉徴収票には、支払金額と、給与所得控除後の金額が並んでいます。この差が給与所得控除です。ここからさらに基礎控除や社会保険料控除などの所得控除を引いて、税率を当てる金額が決まります。収入の額面と税金のかかる額の間に、二つの段がある形です。", why:"会社員の仕事の費用を一人ずつ計算して確かめるのは、本人にも税務署にも大きな手間になるので、収入に応じた決まった額で概算して引く形がとられているからです。" },
      { key:'faq_xszi_nenkin_zatsu', faq:1, grp:'szi', q:"公的年金は何所得になる？", re:/(公的年金|老齢年金|年金収入|年金)[^。]{0,8}(何所得|雑所得|所得の種類|税金の計算|所得税の計算)|公的年金等控除/, ng:/個人年金|遺族年金|障害年金|確定申告/, head:"老齢の公的年金は雑所得で、公的年金等控除を引いた残りに税がかかります。", body:"老齢基礎年金や老齢厚生年金などの公的年金は、雑所得に当たります。年金の収入から公的年金等控除を引いた残りが所得になります。控除の額は、年齢と年金の収入額、ほかの所得の額で段階的に決まります。遺族年金と障害年金は税がかからない年金です。個人年金保険の年金は計算のしかたが違うので、分けて考えます。", acts:["受け取っている年金が、老齢・遺族・障害のどれかを最初に確かめる", "年金の源泉徴収票を一緒に見て、支払金額と源泉徴収税額の欄をご説明する", "控除の額は、国税庁の公表か年金事務所で確かめていただく"], actHead:"現場で使うなら", note:"公的年金等控除の額は国税庁の公表で確かめる。年金の源泉徴収の扱いは日本年金機構か年金事務所。税額の判断は税理士。", pre:1, say:"老齢の公的年金は雑所得という区分で、決まった控除を引いた残りに税金がかかります。遺族年金と障害年金には税金がかからないので、どの年金かを最初に確かめましょう。", more:"年金の受け取りが始まると、年金から所得税と住民税が差し引かれることがあります。毎年届く年金の源泉徴収票に、支払金額と差し引かれた税額が載っています。ほかに給与や不動産の収入がある方は、年金と合わせて計算するので、確定申告が要るかを確かめます。", why:"老齢の公的年金は、長年の保険料をもとに受け取る暮らしのためのお金ですが、所得として扱われ、高齢期の暮らしに配慮して公的年金等控除という専用の控除が置かれているからです。" },
      { key:'faq_xszi_nenkin_fuyo', faq:1, grp:'szi', q:"年金暮らしでも確定申告は要る？", re:/年金[^。]{0,12}(確定申告|申告)[^。]{0,8}(要る|いる|必要|不要|しなくて|しなければ)|確定申告不要制度/, ng:/個人年金|遺族年金|障害年金/, head:"年金の収入とほかの所得が一定以下なら、所得税の確定申告は要らない仕組みがあります。", body:"公的年金等の収入が一定以下でその全てが源泉徴収の対象となり、ほかの所得も一定以下の方は、所得税の確定申告をしなくてよい仕組みがあります。ただし、医療費控除などで税金が戻る方は、申告して戻してもらえます。所得税の申告が要らない方でも、住民税の申告が要ることがあります。条件の額は国税庁の公表で確かめます。", acts:["年金のほかに、給与・不動産・個人年金などの収入があるかを聞き取る", "医療費控除などで戻る税金がないかを、ご家族と一緒に確かめていただく", "住民税の申告が要るかは、お住まいの市区町村で確かめていただく"], actHead:"現場で使うなら", note:"確定申告不要制度の条件の額は国税庁の公表で確かめる。住民税の申告は市区町村の窓口。個別の判断は税理士か税務署。", pre:1, say:"年金の収入とほかの所得が一定以下なら、所得税の確定申告をしなくてよい仕組みがあります。ただ、医療費が多い年などは申告すると戻ることがあるので、一度確かめておきましょう。", more:"この仕組みは申告しなくてよいというもので、申告してはいけないわけではありません。医療費控除や社会保険料控除を年金の源泉徴収で反映しきれていないときは、申告で戻ることがあります。住民税は所得税と別に市区町村が決めるので、市区町村からの案内も確かめます。", why:"年金暮らしの方の多くは年金から税が差し引かれていて、改めて申告しても税額がほとんど変わらないことが多いため、手間を省くために申告しなくてよい線が設けられているからです。" },
      { key:'faq_xszi_nenkin_shinkokusho', faq:1, grp:'szi', q:"年金の扶養親族等申告書とは？", re:/扶養親族等申告書|年金[^。]{0,10}(源泉(?!徴収票)|所得税が引かれ|税金が引かれ|税金を引かれ)|(日本年金機構|年金機構)[^。]{0,8}(届く|来た|送られ)[^。]{0,6}(申告書|はがき)/, head:"年金から差し引く所得税に、配偶者や扶養の控除を反映させるための書類です。", body:"老齢の公的年金は、支払いのときに所得税が差し引かれることがあります。日本年金機構から届く扶養親族等申告書を出すと、配偶者や扶養しているご家族の控除が、差し引く税額に反映されます。出さないと、こうした控除が反映されないまま差し引かれます。差し引かれた額は、確定申告で精算できることがあります。", acts:["届いた申告書を出したか、毎年の届き方をお客様と確かめる", "書き方が分からないときは、日本年金機構の案内か年金事務所で確かめていただく", "控除を反映しきれなかったときは、確定申告で精算できるかを税務署で確かめていただく"], actHead:"現場で使うなら", note:"申告書の出し方と期限は日本年金機構の案内で確かめる。年金事務所が窓口。精算と税額の判断は税務署か税理士。", pre:1, say:"年金から差し引かれる所得税に、配偶者やご家族の控除を反映させるための書類です。毎年届くので、出し忘れていないか一緒に確かめておきましょう。", more:"この申告書は、会社員でいう扶養控除等申告書に近い役目の書類です。出さなくても年金は受け取れますが、控除が反映されないぶん差し引かれる税が多くなることがあります。その場合は、確定申告で控除を入れて精算します。毎年の届き方と出し方は日本年金機構の案内で確かめます。", why:"年金を支払う側が、受け取る方の家族の状況を知らなければ、控除を差し引く税額に反映できないため、申告書で毎年知らせてもらう仕組みになっているからです。" },
      { key:'faq_xszi_hikazei', faq:1, grp:'szi', q:"税金がかからない収入にはどんなものがある？", re:/非課税所得|(税金|所得税)が?かからない(収入|お金|所得)|(失業保険|失業給付|基本手当|遺族年金|障害年金|傷病手当金|出産手当金)[^。]{0,10}(税金|課税|所得税|確定申告|非課税)/, ng:/保険金|給付金|相続/, head:"失業給付や遺族年金・障害年金など、税金がかからないと決められた収入があります。", body:"法律で税金がかからないと決められた収入を非課税所得といいます。雇用保険の基本手当（失業給付）、遺族年金と障害年金、健康保険の傷病手当金と出産手当金、出産育児一時金などがこれに当たります。こうした収入は所得に入れず、確定申告にも書きません。ただし、扶養の判断などで別の扱いになることがあります。", acts:["受け取っているお金の名前と出どころを、通知書で確かめる", "健康保険の扶養の判断では非課税の収入も数えることがあると添える", "扱いに迷うお金は、税務署か市区町村で確かめていただく"], actHead:"現場で使うなら", note:"非課税になる収入の範囲は国税庁の公表で確かめる。健康保険の扶養の扱いは健康保険組合か協会けんぽ。税額の判断は税理士。", pre:1, say:"失業給付や遺族年金のように、税金がかからないと決められた収入があります。ただ、健康保険の扶養の判断では数えることがあるので、目的ごとに確かめましょう。", more:"税の扶養と健康保険の扶養は、基準が別です。税の扶養では非課税の収入は所得に入れませんが、健康保険の扶養では、失業給付や遺族年金なども収入として数えることがあります。同じお金でも、どの制度の話かで扱いが変わる点に気をつけます。", why:"暮らしを支えるための給付まで所得として税をかけると、支えの効き目が薄れてしまうため、生活の保障を目的とする給付には税をかけない決まりが置かれているからです。" },
      { key:'faq_xszi_kojo_shurui', faq:1, grp:'szi', q:"所得から差し引ける控除の種類は？", re:/所得控除の(種類|一覧)|所得から(差し)?引ける(もの|控除)|(人的控除|物的控除)|控除の(種類|一覧)[^。]{0,8}(一覧|知りたい|教えて|は？|は\?)/, head:"人や家族の事情に応じた控除と、払ったお金や受けた損失に応じた控除があります。", body:"所得控除は、所得から差し引いて税金のかかる額を小さくするものです。本人や家族の事情に応じた控除（基礎・配偶者・扶養・障害者・ひとり親・寡婦・勤労学生など）と、払ったお金や損失に応じた控除（社会保険料・生命保険料・地震保険料・医療費・寄附金・小規模企業共済等掛金・雑損）に分けられます。控除の種類と額は改正で見直されます。", acts:["お客様の家族構成と、その年に払った保険料・医療費などを書き出す", "年末調整で受けられる控除と、確定申告が要る控除を分けてご説明する", "最新の種類と額は、国税庁の公表か税務署で確かめていただく"], actHead:"現場で使うなら", note:"所得控除の種類と額は国税庁の公表で確かめる。改正で新しい控除が加わることがある。個別の判断は税理士か税務署の窓口。", pre:1, say:"所得控除には、ご家族の事情に応じたものと、払った保険料や医療費などに応じたものがあります。年末調整で受けられるものと確定申告が要るものがあるので、分けて確かめましょう。", more:"医療費控除・寄附金控除・雑損控除は、年末調整では受けられず、確定申告が要ります。生命保険料控除や地震保険料控除は、年末調整で受けられます。近年の改正では、大学生の年代の子がアルバイトで稼いだときの控除が新しく設けられるなど、種類そのものが変わることもあります。", why:"同じ所得でも、養う家族の数や病気・災害の事情によって税を負担する力が違うため、その違いを税額に映すために、事情ごとの控除が設けられているからです。" },
      { key:'faq_xszi_fuyou_nenrei', faq:1, grp:'szi', q:"扶養控除は子どもの年齢で変わる？", re:/扶養控除[^。]{0,12}(年齢|何歳|子ども|子供|大学生|高校生|中学生|小学生|赤ちゃん)|(特定扶養|老人扶養|年少扶養)親族|(子ども|子供|中学生|小学生|赤ちゃん|大学生|高校生)[^。]{0,10}扶養控除/, ng:/社会保険|健康保険|アルバイト|バイト|どちら|どっち|共働き|夫婦|両方|夫と妻/, head:"扶養控除は、その年の最後の日の年齢で区分が決まり、区分ごとに額が違います。", body:"扶養控除は、扶養している親族の年齢で区分が分かれます。おおむね中学生までの年代の子は、児童手当などがあるため扶養控除の対象になりません。大学生の年代の子は特定扶養親族として額が大きくなり、高齢の親などは老人扶養親族になります。年齢はその年の最後の日の時点で見ます。区分の年齢と額は国税庁の公表で確かめます。", acts:["お子さまとご家族の生年月日を書き出し、どの区分に当たるかを並べる", "対象にならない年代の子も、住民税の非課税の判断などでは数えることがあると添える", "区分の年齢と額は、国税庁の公表か勤め先の担当の方で確かめていただく"], actHead:"現場で使うなら", note:"扶養控除の区分の年齢と額は国税庁の公表で確かめる。住民税の扱いは市区町村。個別の税額の判断は税理士か税務署の窓口。", pre:1, say:"扶養控除は、ご家族の年齢で区分が分かれていて、区分ごとに額が違います。大学生の年代のお子さまは額が大きい区分になるので、生年月日で一緒に確かめましょう。", more:"おおむね中学生までの子が扶養控除の対象にならないのは、子ども手当（いまの児童手当）が設けられたときに見直されたためです。ただ、扶養控除の申告書には書く欄があります。住民税の非課税の判断や、ほかの制度で家族の人数を数えるときに使われることがあるからです。", why:"子育てや親の介護で家計の負担が重くなる時期は年齢でおおよそ分かるため、負担の重い年代に控除を厚くし、手当で支える年代とは役目を分ける仕組みにしているからです。" },
      { key:'faq_xszi_tokutei_shinzoku', faq:1, grp:'szi', q:"大学生の子がアルバイトで稼いだら扶養はどうなる？", re:/特定親族特別控除|(大学生|学生|専門学校)の?(子|子ども|子供|息子|娘)[^。]{0,14}(アルバイト|バイト|稼|収入)[^。]{0,14}(扶養|控除)|(子|子ども|子供|息子|娘)の?(アルバイト|バイト)[^。]{0,10}(収入|稼)[^。]{0,10}(親|控除)/, ng:/社会保険|健康保険|年金/, head:"大学生の年代の子の所得が扶養の範囲を超えても、一定までは段階的な控除があります。", body:"大学生の年代の子の所得が扶養控除の範囲に収まれば、親は特定扶養控除を受けられます。所得がその範囲を超えても、一定の範囲までは、子の所得に応じて段階的に小さくなる特定親族特別控除を受けられます。この控除は令和7年分の所得税から設けられました。子のアルバイトの見込みの収入を年の途中から把握しておくと、年末調整で慌てません。", acts:["お子さまのアルバイトの見込みの年収を、年の途中で一緒に確かめる", "税の控除と健康保険の扶養は基準が別、とお伝えする", "最新の範囲と額は、国税庁の公表か勤め先の担当の方で確かめていただく"], actHead:"現場で使うなら", note:"特定親族特別控除の範囲と額は国税庁の公表で確かめる。健康保険の扶養は勤め先と健康保険組合。税額の判断は税理士。", pre:1, say:"大学生の年代のお子さまのアルバイト収入が扶養の範囲を超えても、一定までは段階的な控除が受けられる仕組みが新しくできました。健康保険の扶養は基準が別なので、分けて確かめましょう。", more:"前は、子の所得が扶養の範囲を少しでも超えると、親の特定扶養控除が丸ごとなくなる形でした。そのため、年末にアルバイトを控える学生もいました。新しい控除で、超えたあとも段階的に小さくなる形になりました。ただし、健康保険の扶養の線は別にあるので、そちらは勤め先で確かめます。", why:"子の稼ぎが少し増えただけで親の税負担が大きく増える形は、学生が働く時間を抑える理由になっていたため、控除をなだらかに小さくして、その段差をならす仕組みが設けられたからです。" },
      { key:'faq_xszi_oya_fuyou', faq:1, grp:'szi', q:"離れて暮らす親を扶養に入れられる？", re:/(親|両親|父|母)[^。]{0,14}(扶養|扶養控除)[^。]{0,10}(入れ|できる|受けられ|対象)|(別居|仕送り|離れて暮らす)[^。]{0,14}(扶養|扶養控除)|同居老親|老人ホーム[^。]{0,12}(扶養控除|扶養)/, ng:/社会保険|健康保険|介護保険|年金/, head:"生計を一にしていれば、別居の親も扶養控除の対象になることがあります。", body:"別居していても、仕送りなどで生活費をまかなっていて、親の所得が一定以下なら、扶養控除の対象になることがあります。これを生計を一にするといいます。同居している高齢の親は、同居老親等として額が大きい区分になりますが、老人ホームに入った親は同居には当たりません。兄弟姉妹の誰か一人だけが控除を受けられます。", acts:["仕送りの記録（振込の控えなど）が残っているかを確かめていただく", "兄弟姉妹の誰が控除を受けるかを、ご家族で決めていただく", "当てはまるかは、税務署か勤め先の担当の方で確かめていただく"], actHead:"現場で使うなら", note:"生計を一にするの考え方と所得の範囲は国税庁の公表で確かめる。健康保険の扶養は健康保険組合。税額の判断は税理士。", pre:1, say:"離れて暮らす親御さんでも、仕送りで生活を支えていれば扶養控除の対象になることがあります。仕送りの記録を残しておくと、確かめるときに役に立ちます。", more:"生計を一にするとは、同じ家に住んでいるかではなく、生活費を一緒にまかなっているかで考えます。別居の親へ定期的に送金していれば当たることがあります。一方、健康保険の扶養は同居か別居かで条件が違うなど、税と別の基準なので、勤め先の健康保険で確かめます。", why:"親の生活を支える負担は、同じ家に住んでいるかどうかに関係なく生じるため、仕送りで支えている実態があれば、税の上でも扶養している家族として扱う仕組みになっているからです。" },
      { key:'faq_xszi_tomobataraki', faq:1, grp:'szi', q:"共働きで子どもの扶養控除はどちらが受ける？", re:/(共働き|夫婦)[^。]{0,16}(扶養|扶養控除)[^。]{0,12}(どちら|どっち|片方|両方|決め)|(夫婦|共働き)[^。]{0,6}(両方|二人|ふたり)[^。]{0,14}扶養控除|(子|子ども|子供)の(扶養|扶養控除)[^。]{0,10}(どちら|どっち|夫と妻|妻と夫)/, ng:/社会保険|健康保険|配偶者控除/, head:"一人の子の扶養控除は、夫婦のどちらか一方だけが受けられます。", body:"同じ子の扶養控除を、夫婦の両方で受けることはできません。どちらが受けるかは家族で決められ、子ごとに分けることもできます。どちらで受けるかによって世帯の税額が変わることがあるので、決める前に二人の所得を並べて確かめます。健康保険の扶養は、収入の多いほうに入れるなど別の決まりがあります。", acts:["お子さまごとに、どちらの申告書に書いているかを確かめていただく", "税の扶養と健康保険の扶養を、表を分けて書き出す", "世帯の税額の違いは、税理士か市区町村で確かめていただく"], actHead:"現場で使うなら", note:"扶養控除を受ける人の決め方は国税庁の公表で確かめる。健康保険の扶養は勤め先と健康保険組合。税額の判断は税理士。", pre:1, say:"お子さまの扶養控除は、ご夫婦のどちらか一方だけが受けられる決まりです。健康保険の扶養とは決め方が別なので、二つを分けて確かめておきましょう。", more:"子が二人以上いれば、一人は夫、一人は妻の扶養控除にすることもできます。ただし、同じ子を夫婦それぞれの申告書に書いてしまうと、あとで直すことになります。毎年の扶養控除等申告書を書くときに、夫婦で書いた内容を見せ合っておくと間違いが防げます。", why:"扶養控除は、一人の家族を養う負担を一度だけ税額に映すための控除なので、同じ家族を二人の控除に重ねて数えないよう、一方だけが受ける決まりになっているからです。" },
      { key:'faq_xszi_hitorioya', faq:1, grp:'szi', q:"ひとり親控除とは？", re:/ひとり親控除|寡婦控除|(シングルマザー|シングルファザー|母子家庭|父子家庭|ひとり親)[^。]{0,12}(控除|税金|所得税)|(離婚|死別)[^。]{0,12}(所得税の)?控除/, ng:/保険|年金|手当/, head:"結婚していない方が、生計を一にする子を育てているときに受けられる控除です。", body:"ひとり親控除は、婚姻していない方などが、生計を一にする子を育てていて、ご本人の所得が一定以下のときに受けられます。事実婚の相手がいる方は対象になりません。ひとり親に当たらない方で、夫と離婚や死別をしたあと再婚していない女性などは、寡婦控除を受けられることがあります。どちらも年末調整で受けられます。", acts:["勤め先の扶養控除等申告書の、ひとり親か寡婦の欄を確かめていただく", "お子さまの所得と、ご本人の所得の見込みを書き出す", "当てはまるかは、税務署か勤め先の担当の方で確かめていただく"], actHead:"現場で使うなら", note:"ひとり親控除と寡婦控除の要件と額は国税庁の公表で確かめる。手当や住民税の扱いは市区町村。個別の判断は税理士か税務署。", pre:1, say:"お子さまを一人で育てている方には、ひとり親控除という控除があります。年末調整で受けられるので、勤め先の申告書の欄にしるしが付いているか確かめておきましょう。", more:"前は、離婚か死別か、男性か女性かで受けられる控除が分かれていました。見直しで、婚姻歴や性別を問わず、子を育てるひとり親は同じひとり親控除を受けられる形になりました。住民税にも同じ趣旨の控除があり、市区町村の手当の判断に所得が使われることもあります。", why:"一人で子を育てる家庭は、収入を得る人が一人で家計の負担が重くなりやすいため、婚姻歴や性別で差を付けずに、その負担を税額に映す仕組みに見直されたからです。" },
      { key:'faq_xszi_shougaisha', faq:1, grp:'szi', q:"障害者控除は手帳がなくても受けられる？", re:/障害者控除|障害者控除対象者認定|(要介護|介護認定|認知症)[^。]{0,14}(控除|税金|所得税)/, ng:/介護保険料|保険料|医療費/, head:"障害者手帳のある方のほか、市区町村などの認定を受けた高齢の方も対象になります。", body:"障害者控除は、ご本人や扶養している家族に障害があるときに受けられる控除です。障害者手帳などのある方が対象で、重い障害の方は特別障害者として額が大きくなります。手帳がなくても、要介護認定を受けた高齢の方などが、市区町村などから障害者控除の対象者と認める書類を受けると対象になることがあります。要介護認定だけでは当たりません。", acts:["ご家族が手帳か市区町村の認定書を持っているかを確かめていただく", "要介護認定を受けた親御さんがいれば、市区町村の窓口へ認定の申請を案内する", "当てはまるかと額は、税務署か勤め先の担当の方で確かめていただく"], actHead:"現場で使うなら", note:"障害者控除の対象と額は国税庁の公表で確かめる。認定の申請は市区町村の窓口。個別の税額の判断は税理士か税務署。", pre:1, say:"障害者控除は手帳のある方だけでなく、要介護認定を受けた高齢のご家族も、市区町村の認定を受けると対象になることがあります。お住まいの市区町村で確かめてみましょう。", more:"要介護認定を受けた親御さんを扶養している方は、この認定を知らずに控除を受けていないことがあります。認定の基準と申請の仕方は市区町村ごとに決まっています。認定を受けた年より前の年の分も、申告を直すことで受けられることがあるので、税務署で確かめます。", why:"障害や介護が必要な状態の家族がいると、暮らしの負担が重くなるため、その負担を税額に映す控除が設けられ、手帳のない高齢の方も市区町村の判断で対象に含められるようになっているからです。" },
      { key:'faq_xszi_kinro_gakusei', faq:1, grp:'szi', q:"勤労学生控除とは？", re:/勤労学生|働いている学生[^。]{0,10}控除|学生の?(アルバイト|バイト)[^。]{0,12}(所得税|税金)/, ng:/親|扶養/, head:"働いて得た所得が一定以下の学生が、自分の所得税を軽くするための控除です。", body:"勤労学生控除は、学生本人が働いて得た給与などの所得があり、合計の所得が一定以下で、働いて得たもの以外の所得も一定以下のときに受けられます。対象は決められた学校の学生や生徒です。この控除を受けても、親の扶養に入れるかどうかは別の線で判断します。勤め先の申告書に書けば年末調整で受けられます。", acts:["学生ご本人の年収の見込みと、学校の種類を確かめる", "親の扶養の線と、勤労学生控除の線は別だと分けてお伝えする", "当てはまるかは、勤め先か税務署で確かめていただく"], actHead:"現場で使うなら", note:"勤労学生控除の要件と所得の範囲は国税庁の公表で確かめる。対象の学校かどうかは学校の窓口。税額の判断は税理士か税務署。", pre:1, say:"働いている学生さんが、自分の所得税を軽くできる控除があります。勤め先の申告書に書くと年末調整で受けられるので、アルバイト先で確かめてみましょう。", more:"勤労学生控除は、学生本人の税を軽くする控除です。親の扶養控除を受けられるかは、子の所得が扶養の範囲に収まるかで決まるので、勤労学生控除を受けたから親の扶養に入れる、という関係ではありません。学生ご本人と親御さんの両方の立場で、線を分けて確かめます。", why:"学びながら働く学生は収入が限られ、学費などの負担もあるため、本人が働いて得た所得への税を軽くして、学業と仕事の両立を支える控除が設けられているからです。" },
      { key:'faq_xszi_kifu', faq:1, grp:'szi', q:"NPOや赤十字への寄付も税金が戻る？", re:/(npo|赤十字|公益|政党|政治|学校法人|ユニセフ|募金|国境なき)[^。]{0,14}(寄附|寄付)[^。]{0,14}(控除|税金|確定申告)|(寄附|寄付)[^。]{0,8}(npo|赤十字|公益|政党|政治|学校法人|ユニセフ|募金)[^。]{0,14}(控除|税金|確定申告)|ふるさと納税以外の(寄附|寄付)/, head:"国や自治体、認定NPO法人・公益法人・政党などへの寄付は、控除の対象になることがあります。", body:"国や地方公共団体、認定NPO法人、公益社団法人や公益財団法人、学校法人、政党などへの一定の寄付は、所得控除の対象になります。寄付先によっては、所得控除の代わりに税額から直接差し引く形を選べることがあります。どちらも確定申告で受けるもので、年末調整では受けられません。寄付先が出す領収書が要ります。", acts:["寄付先の領収書に、控除の対象と書かれているかを確かめていただく", "年末調整では受けられず、確定申告が要るとお伝えする", "どの形で受けるかは、税理士か税務署で確かめていただく"], actHead:"現場で使うなら", note:"対象になる寄付先と控除の形は国税庁の公表で確かめる。住民税の扱いは市区町村の条例。税額の判断は税理士か税務署の窓口。", pre:1, say:"認定NPO法人や公益法人などへの寄付は、確定申告をすると控除を受けられることがあります。年末調整では受けられないので、寄付先の領収書を残しておきましょう。", more:"寄付先が控除の対象になるかは、寄付先の法人の種類で決まります。同じ団体名でも、認定を受けていない法人への寄付は対象になりません。住民税は、都道府県や市区町村が条例で決めた寄付先なら控除の対象になるので、所得税とは範囲が少し違います。", why:"公益のための活動を寄付で支える人を後押しするため、国が認めた公益性のある寄付先への寄付に限って、税の負担を軽くする仕組みが設けられているからです。" },
      { key:'faq_xszi_chousei', faq:1, grp:'szi', q:"所得金額調整控除とは？", re:/所得金額調整控除|給与と年金の両方[^。]{0,12}控除/, head:"給与所得控除の見直しで負担が増えないよう、決まった方の給与所得から差し引く控除です。", body:"所得金額調整控除は、給与所得控除の上限が引き下げられたときに、子育てや介護をしている方の負担が増えないように設けられました。給与の収入が一定を超え、本人が特別障害者であるか、年齢の若い扶養親族や特別障害者の家族がいる方が対象です。給与と公的年金の両方がある方にも、別の形の調整があります。", acts:["源泉徴収票の所得金額調整控除の欄に額があるかを確かめる", "給与と年金の両方がある方には、確定申告で受ける形があると添える", "当てはまるかは、勤め先か税務署で確かめていただく"], actHead:"現場で使うなら", note:"所得金額調整控除の対象と計算は国税庁の公表で確かめる。年末調整の扱いは勤め先の担当。税額の判断は税理士か税務署。", pre:1, say:"給与の収入が一定を超える方で、お子さまや介護の必要なご家族がいるときに、給与所得から差し引ける控除があります。源泉徴収票に欄があるので、一緒に見てみましょう。", more:"この控除は、所得控除ではなく、給与所得を計算する段で差し引く形です。そのため、源泉徴収票では給与所得控除後の金額の近くに欄があります。子育てや介護による対象は年末調整で受けられ、給与と年金の両方による調整は確定申告で受けるのが基本です。", why:"給与所得控除を見直したときに、収入の多い方の負担を増やしつつ、子育てや介護で家計の負担が重い方には増えすぎないよう、調整のための控除を組み合わせたからです。" },
      { key:'faq_xszi_jumin_kojo_chigai', faq:1, grp:'szi', q:"所得税と住民税で控除の額は違う？", re:/(住民税|所得税)と(住民税|所得税)で[^。]{0,8}控除|住民税[^。]{0,4}(基礎控除|扶養控除|配偶者控除|人的控除)|(基礎控除|扶養控除|配偶者控除)[^。]{0,10}住民税|調整控除/, ng:/生命保険|保険料|地震|医療費|ふるさと|住宅ローン/, head:"基礎控除や扶養控除などの額は、住民税のほうが所得税より小さく決められています。", body:"所得税と住民税は、同じような名前の所得控除を持っていますが、額は別々に決められています。基礎控除・配偶者控除・扶養控除などの人や家族の事情に応じた控除は、住民税のほうが小さくなっています。その差で住民税の負担が増えすぎないよう、住民税には調整控除という仕組みがあります。所得税の改正が住民税にそのまま及ぶとは限りません。", acts:["所得税の控除と住民税の控除を、表を分けて書き出す", "改正の話は、所得税と住民税のどちらの話かを最初に確かめる", "住民税の額は、市区町村の通知書か窓口で確かめていただく"], actHead:"現場で使うなら", note:"住民税の控除の額と調整控除は総務省と市区町村の公表で確かめる。所得税は国税庁。税額の判断は税理士か市区町村の窓口。", pre:1, say:"同じ名前の控除でも、所得税と住民税では額が別々に決められていて、住民税のほうが小さくなっています。改正の話を聞いたときは、どちらの税の話かを確かめましょう。", more:"所得税の基礎控除は近年の改正で見直されましたが、住民税の基礎控除はそれとは別の額のままです。ニュースで控除が増えると聞いても、住民税まで同じように変わるとは限りません。住民税の額は、毎年の住民税の通知書で確かめられます。", why:"住民税は、地域の行政サービスの費用を住民が広く分かち合う考え方の税なので、所得税より控除を小さくして、多くの人に少しずつ負担してもらう作りになっているからです。" },
      { key:'faq_xszi_nenmatsu_shorui', faq:1, grp:'szi', q:"年末調整で出す書類は何がある？", re:/年末調整[^。]{0,12}(書類|申告書|用紙|何を出|何を書|出すもの)/, ng:/保険料控除申告書の書き方|生命保険|証明書/, head:"扶養控除等申告書、基礎控除や配偶者控除の申告書、保険料控除の申告書が中心です。", body:"年末調整では、主に三つの申告書を勤め先へ出します。家族の状況を書く扶養控除等申告書、基礎控除や配偶者控除などをまとめた申告書、生命保険料や地震保険料などを書く保険料控除申告書です。住宅ローン控除を年末調整で受ける方は、税務署から届く専用の申告書なども出します。用紙と出し方は勤め先の案内に従います。", acts:["勤め先から届いた用紙の種類と、出す時期を確かめていただく", "控除証明書が全て手元にそろっているかを、一緒に確かめる", "書き方に迷う欄は、勤め先の担当の方か税務署で確かめていただく"], actHead:"現場で使うなら", note:"申告書の種類と書き方は国税庁の公表で確かめる。出し方と時期は勤め先の担当と社内の案内。税額の判断は税理士。", pre:1, say:"年末調整では、ご家族の状況を書く申告書と、保険料などの控除を書く申告書を勤め先へ出します。控除証明書がそろっているかを、先に確かめておきましょう。", more:"扶養控除等申告書は、その年の最初の給与を受け取る前に出す決まりの書類で、年末調整のときに翌年の分を一緒に出すことが多くなっています。最近は紙ではなく、勤め先の仕組みで画面から出す形も増えています。控除証明書も、電子の形で受け取れる保険会社があります。", why:"勤め先が一人ずつの家族の状況と払った保険料を知らなければ、その年の税額を正しく計算し直せないため、申告書で知らせてもらう仕組みになっているからです。" },
      { key:'faq_xszi_nenmatsu_taishoku', faq:1, grp:'szi', q:"年の途中で退職したら年末調整はどうなる？", re:/(年の途中|途中で|中途)[^。]{0,10}(退職|辞め|転職)[^。]{0,16}(年末調整|確定申告|源泉徴収票|所得税)|(退職|辞め|転職)[^。]{0,12}(年末調整|源泉徴収票|所得税は戻|所得税が戻)/, ng:/住民税|退職金|退職所得/, head:"年の途中で辞めると年末調整は受けないので、次の勤め先か確定申告で精算します。", body:"年の途中で退職すると、多くはその勤め先で年末調整を受けません。その年のうちに再就職したら、前の勤め先の源泉徴収票を新しい勤め先に出し、合わせて年末調整をしてもらいます。再就職しなかった方は、確定申告で精算します。給与から差し引かれた税が多すぎた分は、精算で戻ることがあります。", acts:["前の勤め先から源泉徴収票を受け取っているかを確かめていただく", "再就職の予定があれば、新しい勤め先へ出すようにお伝えする", "確定申告が要るかは、税務署か税理士で確かめていただく"], actHead:"現場で使うなら", note:"途中で退職したときの精算の扱いは国税庁の公表で確かめる。源泉徴収票は前の勤め先の担当。個別の判断は税理士か税務署の窓口。", pre:1, say:"年の途中で退職すると年末調整を受けないので、次の勤め先か確定申告で精算します。前の会社の源泉徴収票が要るので、受け取っているか確かめておきましょう。", more:"給与から差し引く税は、一年働く前提で計算されています。年の途中で辞めると、その年の給与は少なくなるので、精算すると戻ることが多くなります。住民税は前の年の所得で決まるので、辞めたあとも払う場面がある点は別に確かめます。", why:"毎月の給与から差し引く税は概算で、年末調整か確定申告で一年分を計算し直して初めて正しい額が決まるため、途中で辞めた方は別の場面で精算する必要があるからです。" },
      { key:'faq_xszi_nenmatsu_go', faq:1, grp:'szi', q:"年末調整のあとで扶養が変わったらどうする？", re:/年末調整[^。]{0,16}(後|あと)[^。]{0,12}(変わ|増え|減っ|間違|直|出し忘れ)|年末調整[^。]{0,10}(やり直|再調整|間違え)/, ng:/保険料|生命保険|控除証明|住宅ローン/, head:"勤め先がやり直しを受け付けるうちは勤め先で、間に合わなければ確定申告で直します。", body:"年末調整のあとで、扶養する家族が増えた・書き方を間違えた、と分かったときは、まず勤め先に伝えます。勤め先によっては、年が明けてからもしばらくは年末調整のやり直しを受け付けます。間に合わないときは、確定申告で正しい内容に直します。払いすぎた税は戻り、足りない税は納めます。", acts:["分かった時点で、勤め先の担当の方へ早めに伝えていただく", "勤め先で間に合わないときは、確定申告で直せるとお伝えする", "直し方と期限は、勤め先か税務署で確かめていただく"], actHead:"現場で使うなら", note:"年末調整のやり直しと確定申告で直す扱いは国税庁の公表で確かめる。受付の時期は勤め先の担当。判断は税理士か税務署。", pre:1, say:"年末調整のあとで扶養が変わったと分かったら、まず勤め先に伝えましょう。勤め先で間に合わないときも、確定申告で直せます。", more:"年末のぎりぎりに結婚した場合も、配偶者の控除はその年の最後の日の状況で判断するので、所得の条件に合えば、その年の分から受けられることがあります。一方、生まれたお子さまは、年齢の区分で扶養控除の対象にはなりませんが、申告書に書く欄があります。気づいた時点で、勤め先か税務署に相談します。", why:"年末調整は勤め先が一年分の税を計算し直す手続きで、勤め先は届いた申告書の内容でしか計算できないため、あとから変わったことは改めて知らせるか、確定申告で直す必要があるからです。" },
      { key:'faq_xszi_gensen_shiharai', faq:1, grp:'szi', q:"源泉徴収票の支払金額は手取りのこと？", re:/源泉徴収票[^。]{0,10}(支払金額|支払い金額|支払額|一番上の金額|いちばん上の金額)|(年収|額面|手取り)[^。]{0,10}源泉徴収票[^。]{0,8}(どこ|どの欄|どれ)|源泉徴収票[^。]{0,8}(どこ|どの欄)[^。]{0,8}(年収|額面|手取り)/, head:"支払金額は手取りではなく、税や社会保険料を引く前の、その年の給与と賞与の合計です。", body:"源泉徴収票の支払金額は、その年に勤め先から受け取った給与と賞与を、税や社会保険料を引く前の額で合計したものです。いわゆる額面の年収に近く、口座に入った手取りとは違います。通勤手当のうち税のかからない分は含まれません。隣の給与所得控除後の金額は、支払金額から給与所得控除を引いた額で、所得税の計算のもとになります。", acts:["源泉徴収票の支払金額と、給与明細の手取りの合計を並べて見ていただく", "ライフプランの収入に入れた額が、額面と手取りのどちらかを書き添える", "欄の読み方に迷うときは、勤め先の担当の方か税務署で確かめていただく"], actHead:"現場で使うなら", note:"源泉徴収票の欄の意味は国税庁の公表で確かめる。前の勤め先の分を含むかは勤め先の担当と社内の案内。税額の判断は税理士か税務署の窓口。", pre:1, say:"源泉徴収票の支払金額は、税や社会保険料を引く前の年収です。手取りはここから税や保険料を引いた額なので、給与明細と並べて見てみましょう。", more:"支払金額から源泉徴収税額と社会保険料等の金額を引くと、手取りのおおよその額が見えます。住民税は源泉徴収票に載らず、別に給与から引かれているので、手取りを見るときは住民税の分も差し引きます。年の途中で勤め先が変わった方は、前の勤め先の分が含まれているかを摘要の欄で確かめます。", why:"源泉徴収票は所得税の計算のための書類で、税を計算するもとになる、差し引く前の給与の額をそのまま載せる作りになっているからです。" },
      { key:'faq_xszi_gensen_zero', faq:1, grp:'szi', q:"源泉徴収税額がゼロなのはなぜ？", re:/源泉徴収税額[^。]{0,8}(ゼロ|零|空欄|空白|無い|ない|なし|入っていない)|(源泉徴収票|年末調整|給与|給料)[^。]{0,12}所得税[^。]{0,6}(引かれていない|引かれてない|ゼロ|かかっていない|かからなかった)/, ng:/年金/, head:"控除の合計が所得を上回るか、住宅ローン控除などで税額が全て差し引かれると、ゼロになります。", body:"年末調整を受けた方の源泉徴収税額は、年末調整で計算し直したその年の所得税の額です。給与所得から基礎控除・扶養控除・保険料控除などを引いた残りが無いと、税がかからずゼロになります。残りがあっても、住宅ローン控除のような税額から引く控除で全て差し引かれると、ゼロになります。月々の給与から引かれていた税は、年末調整で戻っています。", acts:["年末調整を受けたかどうかを、勤め先の担当の方に確かめていただく", "住宅ローン控除を受けている方は、住民税からも差し引かれているかを通知書で見ていただく", "ゼロになった理由に迷うときは、勤め先の担当の方か税務署で確かめていただく"], actHead:"現場で使うなら", note:"年末調整と税額控除の仕組みは国税庁の公表で確かめる。個別の理由は勤め先の担当と税務署の窓口。税額の判断は税理士。", pre:1, say:"源泉徴収税額がゼロなのは、控除の合計が所得より多いか、住宅ローン控除などで税が全て差し引かれたためです。月々引かれていた税は、年末調整で戻っています。", more:"所得税がゼロでも、住民税はかかることがあります。住民税は控除の額や税のかからない線が所得税と違うためです。住宅ローン控除で所得税から引ききれなかった分は、一定の範囲で翌年度の住民税から差し引かれる仕組みがあります。", why:"所得税は、所得から控除を引いた残りに税率を当て、さらに税額から引く控除を差し引く順で計算するため、どちらかの段階で残りが無くなれば、税はかからないからです。" },
      { key:'faq_xszi_gensen_saihakko', faq:1, grp:'szi', q:"源泉徴収票をなくしたらどうする？", re:/源泉徴収票[^。]{0,10}(なくし|無くし|紛失|再発行|再交付|もう一度|出してもらえ|くれな|もらえな|届かな|届いていな)/, head:"勤め先に再発行を頼みます。年金の源泉徴収票は、日本年金機構に頼みます。", body:"給与の源泉徴収票は、勤め先に頼めば出し直してもらえることが多くあります。勤め先は、その年に退職した方にも源泉徴収票を渡す決まりがあります。退職した勤め先が出してくれないときは、税務署に相談する手続きがあります。公的年金の源泉徴収票は、日本年金機構に再交付を申し込めます。", acts:["どの年の、どの勤め先の源泉徴収票が要るのかを、まず書き出していただく", "退職した勤め先には、送り先の住所を添えて再発行を頼んでいただく", "出してもらえないときや年金の分は、税務署か年金事務所の窓口で確かめていただく"], actHead:"現場で使うなら", note:"源泉徴収票の交付と、出してもらえないときの手続きは国税庁の公表で確かめる。年金の分は日本年金機構か年金事務所。個別の扱いは税務署の窓口。", pre:1, say:"源泉徴収票をなくしたときは、勤め先に頼めば出し直してもらえることが多いです。年金の分は日本年金機構に頼めます。", more:"確定申告では、源泉徴収票を書類として付ける必要はありませんが、書き写す数字のもとになるので、手元にあると確かです。ローンの審査などで収入を示す書類として求められることもあるので、届いたら年ごとにまとめておきます。", why:"源泉徴収票は、勤め先が一年分の給与と税の記録から作る書類で、元の記録が勤め先に残っているため、出し直してもらえるからです。" },
      { key:'faq_xszi_jumin_choshu', faq:1, grp:'szi', q:"住民税の特別徴収と普通徴収の違いは？", re:/特別徴収|普通徴収|住民税[^。]{0,10}(給料から引かれ|給与から引かれ|天引き|自分で払|自分で納め|納付書)/, ng:/介護保険|国民健康保険|国保|後期高齢|健康保険料|退職|辞め|離職|引っ越|引越|転居|所得税と住民税|住民税と所得税/, head:"特別徴収は勤め先が給与から引いて納める形、普通徴収は自分で納付書などで納める形です。", body:"住民税の納め方には二つあります。勤めている方は、勤め先が毎月の給与から差し引いて市区町村へ納める特別徴収が基本です。事業をしている方や勤めていない方は、市区町村から届く納付書などで自分で納める普通徴収になります。公的年金を受け取る一定の方は、年金から差し引かれる形もあります。", acts:["お客様の住民税が、給与から引かれているか自分で納めているかを確かめる", "納付書で納める方には、納め忘れがないよう納期を手帳に書いておくようお伝えする", "納め方の切り替えや納期は、お住まいの市区町村の窓口で確かめていただく"], actHead:"現場で使うなら", note:"特別徴収と普通徴収の扱いと納期はお住まいの市区町村の公表で確かめる。勤め先での扱いは勤め先の担当と社内の案内。判断は税理士か市区町村の窓口。", pre:1, say:"住民税は、勤めている方なら勤め先が給与から引いて納め、そうでない方は届いた納付書などで自分で納めます。納付書で納める方は、納め忘れに気をつけましょう。", more:"普通徴収は、年に数回に分けて納めるのが基本で、まとめて納めることもできます。口座振替や、スマートフォンの決済で納められる市区町村もあります。納期を過ぎると延滞金がかかることがあるので、届いた通知書で納期を確かめておきます。", why:"勤めている方は勤め先が給与の額を知っていて毎月差し引けるので、納め忘れを防ぎ、市区町村が確かに受け取れるよう、勤め先に納めてもらう形が基本になっているからです。" },
      { key:'faq_xszi_jumin_taishoku', faq:1, grp:'szi', q:"会社を辞めたら住民税はどうなる？", re:/(退職|辞め|会社をやめ|仕事をやめ|離職)[^。]{0,12}住民税|住民税[^。]{0,10}(退職|辞め|離職)/, ng:/退職金|退職所得|健康保険|国民健康保険|国保|年金/, head:"辞めた時期で、最後の給与からまとめて引かれるか、自分で納める形に変わります。", body:"退職すると、勤め先が給与から住民税を引く形は続けられなくなり、残りの分の納め方が辞めた時期で変わります。年の初めから春ごろまでに辞めたときは、残りの分を最後の給与などからまとめて引くのが原則です。それより後に辞めたときは、残りの分を自分で納付書で納める形が基本で、希望すれば最後の給与などからまとめて引いてもらえます。転職先が決まっていれば、引き継いで給与から引いてもらえることもあります。", acts:["辞める時期と、転職先が決まっているかを最初に聞き取る", "自分で納める形になる方には、届く納付書の納期を確かめていただく", "残りの分の扱いは、勤め先の担当の方か市区町村の窓口で確かめていただく"], actHead:"現場で使うなら", note:"退職したときの住民税の納め方は、お住まいの市区町村の公表で確かめる。勤め先での手続きは勤め先の担当と社内の案内。判断は市区町村の窓口か税理士。", pre:1, say:"会社を辞めても、住民税は前の年の所得で決まっているので、残りの分を納めます。辞めた時期で、まとめて引かれるか自分で納めるかが変わるので、勤め先に確かめましょう。", more:"辞めた翌年も住民税がかかるのは、住民税が前の年の所得をもとに、翌年度に納める仕組みだからです。辞めたあとに届く住民税は、働いていた年の所得をもとに決まります。辞める前に、その分も家計の予定に入れておくと慌てません。", why:"住民税は、前の年の所得が一年分そろってから計算して、翌年度に分けて納める仕組みなので、退職したあとも、働いていた年の分を納める形になるからです。" },
      { key:'faq_xszi_jumin_shinsotsu', faq:1, grp:'szi', q:"新社会人の住民税はいつから引かれる？", re:/(新社会人|新卒|新入社員|入社(一|1|二|2)年目|社会人(一|1|二|2)年目|社会人になっ)[^。]{0,16}(住民税|手取りが減)|住民税[^。]{0,10}(新社会人|新卒|新入社員|(一|1|二|2)年目)/, head:"働き始めた翌年の六月ごろから、給与から引かれるのが基本です。", body:"住民税は、前の年の所得をもとに、その年の六月から翌年の五月までの分を給与から引く仕組みです。四月に働き始めた方は、その年の給与をもとにした住民税が、翌年の六月ごろから引かれ始めます。そのため、働き始めた翌年から手取りが減ったように感じます。前の年にアルバイトなどで一定の収入があった方は、働き始めた年からかかることがあります。", acts:["新社会人のお客様には、翌年の六月ごろから手取りが変わることを先にお伝えする", "前の年のアルバイトの収入を聞き取り、住民税がかかるかを確かめていただく", "始まる時期と額は、勤め先から届く通知書か市区町村の窓口で確かめていただく"], actHead:"現場で使うなら", note:"住民税の年度と特別徴収の始まりはお住まいの市区町村の公表で確かめる。勤め先での扱いは勤め先の担当と社内の案内。判断は市区町村の窓口か税理士。", pre:1, say:"住民税は前の年の所得で決まるので、働き始めた翌年の六月ごろから給与から引かれ始めます。その月から手取りが変わるので、家計の予定に入れておきましょう。", more:"所得税は、働き始めた最初の給与から引かれますが、住民税は前の年の所得が決まってから計算するので、一年ほど遅れて始まります。前の年の所得が少ない方は、住民税がかからないこともあります。ライフプランの手取りは、住民税が引かれ始めたあとの額で見ておくと確かです。", why:"住民税は、勤め先や本人から集めた一年分の所得の記録をもとに市区町村が計算するので、所得が決まった翌年に、決まった額を分けて納める作りになっているからです。" },
      { key:'faq_xszi_jumin_kettei', faq:1, grp:'szi', q:"住民税の決定通知書はどこを見ればいい？", re:/住民税[^。]{0,8}(決定通知|通知書|税額決定|の紙|の明細)|決定通知書|税額決定通知|(ふるさと納税|寄附|寄付)[^。]{0,12}住民税[^。]{0,10}(引かれ|反映|控除され|確かめ|確認)/, ng:/国民健康保険|国保|介護保険|後期高齢|保険料|年金/, head:"前の年の所得と控除、所得割と均等割の税額、月ごとに引かれる額の三つを見ます。", body:"給与から住民税が引かれる方には、新しい年度の住民税が始まる前に、勤め先を通して税額の決定通知書が届きます。前の年の所得と、差し引かれた控除の額、所得割と均等割の税額、税額から引かれた控除、月ごとに引かれる額が載っています。自分で納める方には、納税通知書が届きます。", acts:["通知書の控除の欄に、扶養や配偶者の控除が入っているかを一緒に見る", "ふるさと納税をした方は、税額から引かれた控除の欄を見ていただく", "欄の読み方に迷うときは、お住まいの市区町村の窓口で確かめていただく"], actHead:"現場で使うなら", note:"決定通知書の欄の名前と並びは市区町村ごとに違うので、お住まいの市区町村の公表で確かめる。税額の判断は市区町村の窓口か税理士。", pre:1, say:"住民税の決定通知書には、前の年の所得と控除、税額、月ごとに引かれる額が載っています。控除が漏れていないか、一緒に見てみましょう。", more:"ワンストップ特例でふるさと納税をした方は、所得税の分も含めて住民税から差し引かれるので、税額から引かれた控除の欄に寄附の分が入ります。確定申告をした方は、所得税の還付と住民税の控除に分かれます。寄附の分が見当たらないときは、市区町村に確かめます。", why:"住民税は市区町村が計算して決めるので、どの所得と控除をもとに計算したかを本人が確かめられるよう、計算の中身を書いて知らせる作りになっているからです。" },
      { key:'faq_xszi_jumin_hikkoshi', faq:1, grp:'szi', q:"引っ越したら住民税はどこに納める？", re:/(引っ越|引越|転居|転入|転出|住所が変わ)[^。]{0,14}住民税|住民税[^。]{0,12}(引っ越|引越|転居|転入|転出|どこに(納|払)|一月一日|1月1日)/, ng:/ワンストップ|ふるさと|寄附|寄付/, head:"その年の一月一日に住んでいた市区町村に、その年度の分を納めます。", body:"住民税は、その年の一月一日に住んでいた市区町村が、前の年の所得をもとに一年度分を決めて、その市区町村に納めます。年の途中で引っ越しても、その年度の分は前の市区町村に納め、引っ越し先の市区町村に納めるのは翌年度の分からです。勤め先が変わらなければ、給与から引かれる形はそのまま続きます。", acts:["引っ越しの時期と、一月一日にどこに住んでいたかを確かめる", "前の市区町村からの通知が届くよう、郵便の転送の届けを出していただく", "納める先と手続きは、前の市区町村か新しい市区町村の窓口で確かめていただく"], actHead:"現場で使うなら", note:"住民税を納める先の決まりはお住まいの市区町村の公表で確かめる。勤め先での扱いは勤め先の担当と社内の案内。判断は市区町村の窓口か税理士。", pre:1, say:"住民税は、その年の一月一日に住んでいた市区町村に、その年度の分を納めます。引っ越し先に納めるのは翌年度の分からなので、前の市区町村からの通知も受け取れるようにしておきましょう。", more:"一月一日の時点で住民票を移していなくても、実際に住んでいた所の市区町村が課税することがあります。年末に引っ越すときは、一月一日にどちらに住んでいるかで、次の年度に納める先が決まるので、住民票を移す時期を確かめておきます。", why:"住民税は住んでいる地域の暮らしを支える税なので、一月一日を基準の日として、その日に住んでいた市区町村が一年度分をまとめて決める作りにしているからです。" },
      { key:'faq_xszi_jumin_kintou', faq:1, grp:'szi', q:"住民税の均等割と所得割とは？", re:/均等割|所得割|森林環境税/, ng:/国民健康保険|国保|保険料|介護保険|後期高齢/, head:"均等割は一定の所得がある方が同じ額を納める部分、所得割は所得に応じて納める部分です。", body:"住民税は、二つの部分を合わせた額です。均等割は、一定の所得がある方が、所得の多い少ないに関係なく同じ額を納める部分です。所得割は、前の年の所得から控除を引いた額に一律の税率を当てて計算する部分です。所得が少ない方は、所得割だけがかからない、または両方ともかからないことがあります。森林環境税は国の税で、均等割と一緒に納めます。", acts:["お客様の決定通知書で、所得割と均等割の額を分けて見ていただく", "所得が少ない年は、所得割がかからないことがあるとお伝えする", "かからない線と税率は、お住まいの市区町村の窓口で確かめていただく"], actHead:"現場で使うなら", note:"均等割の額と税のかからない線はお住まいの市区町村の公表で確かめる。森林環境税は総務省と林野庁の公表。判断は市区町村の窓口か税理士。", pre:1, say:"住民税は、同じ額を納める均等割と、所得に応じて納める所得割を合わせた額です。決定通知書で二つを分けて見ると、なぜこの額なのかが見えてきます。", more:"均等割の額は、市区町村と都道府県の分を合わせたもので、地域によって上乗せがあることもあります。所得割は、所得税のように所得が増えるほど率が上がる形ではなく、一律の率です。そのため、住民税の額は所得におおむね比例して増えます。", why:"地域の行政サービスは住む人の誰もが使うので、全員が同じ額を少しずつ出す部分と、所得に応じて出す部分を組み合わせて、費用を分け合う作りにしているからです。" },
      { key:'faq_xszi_shotoku_jumin_chigai', faq:1, grp:'szi', q:"所得税と住民税の違いは？", re:/(所得税と住民税|住民税と所得税)[^。]{0,8}(違|ちが|差|どちらも|両方)/, ng:/控除|ふるさと|住宅ローン|保険料|医療費|寄附|寄付/, head:"所得税は国に、住民税は住んでいる市区町村と都道府県に納め、もとにする年も違います。", body:"所得税は国の税で、その年の所得をもとに計算し、勤めている方は毎月の給与から先に引かれ、年末調整や確定申告で精算します。住民税は地方の税で、前の年の所得をもとに市区町村が計算し、翌年度に納めます。所得税は所得が増えるほど率が上がる形で、住民税の所得割は一律の率です。控除の額も、所得税と住民税で違うものがあります。", acts:["お客様の給与明細で、所得税と住民税の欄を分けて見ていただく", "収入が大きく変わる年は、住民税が翌年に響くことを先にお伝えする", "税額の細かい計算は、税理士か税務署、市区町村の窓口で確かめていただく"], actHead:"現場で使うなら", note:"所得税は国税庁、住民税はお住まいの市区町村の公表で確かめる。個別の税額の判断は税理士か税務署・市区町村の窓口。", pre:1, say:"所得税はその年の所得で国に、住民税は前の年の所得で住んでいる市区町村などに納めます。どちらも給与から引かれますが、決まる時期が違うので、収入が変わった年は翌年の住民税にも気をつけましょう。", more:"確定申告をすると、その内容は市区町村にも届くので、住民税の申告を別にしなくて済みます。年末調整で終わる方も、勤め先が市区町村へ給与の額を知らせています。どちらの税も、もとになる所得の記録は一つで、そこから国と地方がそれぞれの決まりで計算します。", why:"所得税は本人が一年の所得を申告して納める税で、住民税は市区町村が集まった所得の記録をもとに決めて知らせる税なので、決まる時期と計算の作りが分かれているからです。" },
      { key:'faq_xszi_fukugyo_shoukaku', faq:1, grp:'szi', q:"副業の所得が少なければ確定申告はしなくていい？", re:/(副業|副収入|サイドビジネス|内職)[^。]{0,16}(少な|少し|ちょっと|わずか|少額|小さ)[^。]{0,16}(申告|確定申告|住民税)|(副業|副収入)[^。]{0,10}(申告不要|申告は要らな|申告はいらな|申告しなくて)/, ng:/していい|してもいい|就業規則|社内|うちの会社|規定|許可|禁止|ばれ|バレ|知られ/, head:"年末調整を受けた会社員なら、副業などの所得が一定以下のとき、所得税の確定申告は要りません。", body:"給与を一か所から受けて年末調整を受けた方などは、給与以外の所得の合計が一定以下なら、所得税の確定申告をしなくてよい決まりがあります。ここでの所得は、副業の収入から必要経費を引いた額です。ただし、住民税にはこの決まりが無いので、住民税の申告は要ります。医療費控除などで確定申告をするときは、少ない副業の所得も含めて申告します。", acts:["副業の収入と、かかった費用を年の途中から書き残していただく", "住民税の申告が要るかを、お住まいの市区町村で確かめていただく", "申告が要るかと所得の計算は、税理士か税務署で確かめていただく"], actHead:"現場で使うなら", note:"確定申告をしなくてよい線と条件は国税庁の公表で確かめる。住民税の申告は市区町村の窓口。勤め先の副業の決まりは社内の規程。個別の判断は税理士か税務署。", pre:1, say:"副業の所得が一定以下なら、所得税の確定申告は要らないことがあります。ただ、住民税の申告は別に要るので、お住まいの市区町村で確かめましょう。", more:"ここでいう線は収入ではなく、収入から費用を引いた所得の額で見ます。副業の所得が赤字のときに、給与と差し引きできるかは所得の種類で決まります。副業を勤め先が認めているかは、税とは別に、勤め先の決まりで確かめます。", why:"少ない額のために全員が申告すると手間が大きいので、年末調整で給与の税を精算した方には所得税の申告を省く線を設けた一方、住民税は市区町村が別の決まりで集めているからです。" },
      { key:'faq_xszi_nikasho', faq:1, grp:'szi', q:"二か所から給料をもらっていたら確定申告は要る？", re:/(二か所|2か所|二箇所|2箇所|二ヶ所|2ヶ所|二カ所|2カ所|二つの会社|2つの会社|ふたつの会社|複数の会社|二社|2社)[^。]{0,10}(給料|給与|勤め|働)|(掛け持ち|かけもち|ダブルワーク|wワーク)[^。]{0,14}(年末調整|確定申告|所得税|源泉徴収)|甲欄|乙欄/, ng:/していい|してもいい|就業規則|社内|規定|許可|禁止|会社に申告|勤め先に申告|会社に言|会社に報告|届け出|社会保険|健康保険|厚生年金|雇用保険/, head:"年末調整は一か所だけなので、もう一か所の給与が一定を超えると確定申告が要ります。", body:"年末調整は、扶養控除等申告書を出した一か所の勤め先でしか受けられません。もう一か所の給与は、乙欄という高めの率で源泉徴収されるだけで、年末調整では精算されません。そのため、もう一か所の給与の収入とほかの所得の合計が一定を超えると、確定申告が要ります。確定申告で、二か所の給与を合わせて一年分の税を計算し直します。", acts:["どちらの勤め先に扶養控除等申告書を出しているかを確かめていただく", "もう一か所の源泉徴収票も、年が明けたら忘れずに受け取っていただく", "確定申告が要るかと税額は、税理士か税務署で確かめていただく"], actHead:"現場で使うなら", note:"二か所から給与を受ける方の確定申告の線と条件は国税庁の公表で確かめる。勤め先の副業の決まりは社内の規程。個別の判断は税理士か税務署の窓口。", pre:1, say:"年末調整は一か所でしか受けられないので、もう一か所の給与が一定を超えると確定申告が要ります。両方の源泉徴収票をそろえておきましょう。", more:"扶養控除等申告書は一か所にしか出せないので、給与の多いほうに出すことが多いですが、決まりではありません。住民税は、両方の勤め先が市区町村に給与の額を知らせるので、二つの給与を合わせて計算されます。", why:"家族の状況に応じた控除は一人に一つの勤め先でだけ受ける決まりなので、ほかの勤め先は控除を見込まない率で引くしかなく、合わせた精算を本人の確定申告でする作りになっているからです。" },
      { key:'faq_xszi_kaigyo', faq:1, grp:'szi', q:"個人で事業を始めたら税務署に何を届ける？", re:/開業届|個人事業の開業|(個人で|個人事業|フリーランス|独立して)[^。]{0,14}(事業を始め|始めたら|になったら)[^。]{0,14}(届|届け出|手続|税務署)/, ng:/代理店|募集人|保険業|登録|法人|会社を作|会社設立|設立/, head:"税務署には開業の届け出を出し、青色申告にするなら承認の申請も出します。", body:"個人で事業を始めたときは、税務署に個人事業の開業の届け出を出す決まりがあります。青色申告で申告したい方は、青色申告の承認の申請を期限までに出します。間に合わないと、その年は白色申告になります。人を雇って給与を払うときは、給与を払う事業所の届け出も出します。都道府県などにも、事業を始めた届け出が要ることがあります。", acts:["事業を始めた日と、青色申告にするかを先に決めていただく", "人を雇うか、家族に給与を払うかを確かめ、要る届け出を書き出す", "届け出の期限と書き方は、税務署か税理士に確かめていただく"], actHead:"現場で使うなら", note:"開業の届け出・青色申告の承認の申請の期限と書き方は国税庁の公表で確かめる。都道府県の届け出は都道府県の窓口。判断は税理士か税務署。", pre:1, say:"個人で事業を始めたら、税務署に開業の届け出を出します。青色申告にするなら承認の申請に期限があるので、早めに確かめましょう。", more:"家族に給与を払って経費にしたいときは、青色申告なら専従者の給与の届け出も要ります。開業の届け出の控えは、事業用の口座を作るときや、仕事の契約で求められることがあるので、手元に残しておきます。消費税の届け出は、売上げの規模などで要るかが変わります。", why:"税務署が事業をしている人を知り、申告の案内を届けられるようにするためで、青色申告は帳簿をきちんと付ける約束と引き換えに特典を受ける形なので、先に申請する作りになっているからです。" },
      { key:'faq_xszi_yotei_nouzei', faq:1, grp:'szi', q:"予定納税とは？", re:/予定納税/, ng:/法人|中間申告|消費税/, head:"前の年の所得税が一定以上の方が、その年の所得税の一部を前もって納める仕組みです。", body:"予定納税は、前の年の所得税の額をもとに計算した額を、その年の途中に二回に分けて前もって納める仕組みです。対象になる方には、税務署から通知が届きます。前もって納めた分は、その年の確定申告で差し引いて精算するので、納めすぎた分は戻ります。事業をやめた、所得が大きく減ったなどのときは、減らすよう申請できます。", acts:["通知が届いたお客様には、納める時期と額を家計の予定に入れていただく", "その年の所得が大きく減りそうなら、減らす申請ができるとお伝えする", "減らす申請の期限と書き方は、税務署か税理士で確かめていただく"], actHead:"現場で使うなら", note:"予定納税の対象・納める時期・減らす申請の期限は国税庁の公表で確かめる。個別の判断は税理士か税務署の窓口。", pre:1, say:"予定納税は、前の年の所得税をもとに、その年の税を前もって納める仕組みです。確定申告で精算されるので、納めすぎた分は戻ります。", more:"予定納税の額は、前の年の所得のうち、財産を売った利益や一時所得などを除いた分の税をもとに計算します。その年の所得が少なくなる見込みなら、減らす申請を考えます。納め忘れると延滞税がかかることがあるので、口座から引き落とす形にしておくと確かです。", why:"所得税を一年分まとめて納めると一度の負担が重くなるので、所得の大きい方には年の途中で分けて前もって納めてもらい、国の収入もならす作りになっているからです。" },
      { key:'faq_xszi_shusei', faq:1, grp:'szi', q:"確定申告を間違えたらどうする？", re:/修正申告|更正の請求|(確定申告|申告)[^。]{0,8}(間違え|間違っ|誤り|まちがえ|まちがっ|ミス)|(確定申告|申告)[^。]{0,10}(あと|後)[^。]{0,8}(誤り|間違|まちが|ミス)|申告した[^。]{0,8}(税金|税額)[^。]{0,8}(多すぎ|少なすぎ|多かった|少なかった)/, ng:/給付金|保険金|控除証明|保険料控除|相続税|贈与税|法人/, head:"税金が少なすぎたら修正申告、多すぎたら更正の請求で直します。", body:"確定申告のあとで誤りに気づいたときは、直し方が二つあります。納めた税が少なすぎたときは、修正申告を出して足りない分を納めます。多すぎたときは、更正の請求を出し、税務署が内容を確かめて認めれば、払いすぎた分が戻ります。申告の期限の前に気づいたときは、出し直すことで直せます。", acts:["気づいた誤りが、税が多すぎる側か少なすぎる側かを書き出していただく", "控えの申告書と、もとになった書類をそろえていただく", "直し方と期限は、税理士か税務署の窓口で確かめていただく"], actHead:"現場で使うなら", note:"修正申告と更正の請求の期限と手続きは国税庁の公表で確かめる。個別の税額と手続きの判断は税理士か税務署の窓口。", pre:1, say:"確定申告を間違えても、あとから直す手続きがあります。税が少なかったら修正申告、多かったら更正の請求なので、控えを持って税務署か税理士に相談しましょう。", more:"税が少なすぎたまま税務署から指摘を受けると、本来の税に加えて加算税がかかることがあります。指摘の前に自分で修正申告をすると、加算税がかからないか軽くなることがあります。更正の請求には期限があるので、気づいたら期限を確かめます。", why:"申告は本人が税額を計算して届け出る仕組みなので、あとで誤りに気づいたときに本人から直せる道と、税を戻すときは税務署が確かめる道の二つを分けて用意しているからです。" },
      { key:'faq_xszi_kigen', faq:1, grp:'szi', q:"確定申告の期限に遅れたらどうなる？", re:/(確定申告|申告)[^。]{0,10}(期限|締め切り|締切)[^。]{0,10}(遅れ|過ぎ|すぎ|間に合わ)|(期限|締め切り|締切)[^。]{0,8}(過ぎ|遅れ)[^。]{0,10}(確定申告|申告)|確定申告[^。]{0,6}(出し忘れ|し忘れ)|還付申告[^。]{0,8}(期限|いつまで)|期限後申告|無申告/, ng:/控除|証明書|保険料|給付金|保険金|相続税|贈与税|法人|ワンストップ/, head:"期限を過ぎても申告はできますが、納める税があると加算税や延滞税がかかることがあります。", body:"確定申告の期限を過ぎても、期限後申告として申告できます。納める税がある方は、本来の税に加えて、無申告加算税や延滞税がかかることがあります。税務署から指摘される前に自分で申告すると、加算税が軽くなる扱いがあります。税金が戻る還付申告は、期限の日を過ぎても、一定の期間のうちなら申告できます。", acts:["出し忘れに気づいたら、納める税があるか戻る税かを先に確かめていただく", "納める税がある方には、気づいた時点で早めに申告するようお伝えする", "加算税や延滞税の扱いは、税理士か税務署の窓口で確かめていただく"], actHead:"現場で使うなら", note:"確定申告の期限・期限後申告・加算税と延滞税・還付申告の期間は国税庁の公表で確かめる。個別の判断は税理士か税務署の窓口。", pre:1, say:"確定申告の期限を過ぎても申告はできます。納める税があるときは、延滞税が日数に応じてかかるので、気づいたら早めに税務署か税理士に相談しましょう。", more:"期限に遅れても、決まった条件に当てはまれば、無申告加算税がかからない扱いもあります。一方、遅れを繰り返すと、加算税が重くなる扱いもあります。期限の時期を家計の予定に書き、要る書類を年の初めにそろえておくと、遅れを防げます。", why:"税は期限までに申告して納めることを前提に組み立てられているので、期限を守った人との釣り合いを取るため、遅れた分には延滞税を、申告しなかったことには加算税をかける作りになっているからです。" },
      { key:'faq_xszi_etax', faq:1, grp:'szi', q:"確定申告はスマホでできる？", re:/e-tax|イータックス|電子申告|(確定申告|申告書)[^。]{0,10}(スマホ|スマートフォン|ネット|オンライン|パソコン|マイナンバーカード)|(スマホ|スマートフォン|ネット|オンライン|パソコン|マイナンバーカード)[^。]{0,10}(確定申告|申告書)/, ng:/相続税|贈与税|法人|消費税|年末調整/, head:"スマホやパソコンから、国税庁の仕組みを使って確定申告を出せます。", body:"確定申告は、国税庁の申告書を作る画面で入力し、e-Taxという仕組みでネットから出せます。マイナンバーカードと、カードを読み取れるスマホがあれば、スマホだけで出すこともできます。給与や年金の源泉徴収票の内容を、スマホのカメラで読み取って入力できる仕組みもあります。紙で印刷して、郵送や窓口に出すこともできます。", acts:["マイナンバーカードと、その暗証番号を確かめていただく", "控除証明書をネットで受け取り、そのまま読み込める保険会社もあるとお伝えする", "出し方に迷うときは、税務署の窓口か電話の相談で確かめていただく"], actHead:"現場で使うなら", note:"e-Taxの使い方と必要なものは国税庁の公表で確かめる。個別の申告の内容の判断は税理士か税務署の窓口。", pre:1, say:"確定申告は、スマホやパソコンからネットで出せます。マイナンバーカードがあればスマホだけでも出せるので、暗証番号を確かめておきましょう。", more:"マイナポータルとつなぐと、保険料の控除証明書や医療費の通知などの中身を、自動で入力できる仕組みがあります。ネットで出すと、控除証明書などの書類を出さずに済む扱いもあります。それでも、もとになった領収書などは、決まった期間は手元に残しておきます。", why:"申告の書類を紙で受け付けて人の手で入力すると手間と時間がかかるので、本人がネットで入力した内容をそのまま受け取れるようにして、申告する人と税務署の両方の手間を減らそうとしているからです。" },
      { key:'faq_xszi_kakutei_junbi', faq:1, grp:'szi', q:"確定申告では何を用意すればいい？", re:/確定申告[^。]{0,10}(何を用意|用意する|用意すれば|必要な書類|要る書類|いる書類|準備|持ち物|集めるもの|そろえる)/, ng:/相続税|贈与税|準確定|法人|控除証明|保険料控除/, head:"収入の分かる書類、控除を受けるための書類、本人の確認の書類、口座の情報の四つです。", body:"確定申告の準備では、次の四つをそろえます。給与や年金の源泉徴収票、事業や副業の収入と経費の記録など、収入の分かる書類。保険料の控除証明書、医療費の明細、寄附の受領証明書など、控除を受けるための書類。マイナンバーカードなどの本人の確認の書類。税金が戻る方は、受け取る口座の情報です。", acts:["年が明けたら、届いた控除証明書を一つの封筒にまとめていただく", "副業や事業のある方には、収入と経費の記録を月ごとにまとめておくようお伝えする", "書類がそろわないときの扱いは、税理士か税務署の窓口で確かめていただく"], actHead:"現場で使うなら", note:"確定申告に要る書類と出し方は国税庁の公表で確かめる。個別の申告の判断は税理士か税務署の窓口。", pre:1, say:"確定申告では、源泉徴収票などの収入の書類、保険料控除の証明書などの控除の書類、本人の確認の書類、戻る税を受け取る口座の四つをそろえましょう。", more:"医療費控除を受ける方は、領収書そのものではなく、医療費の明細書を出します。領収書は手元に残しておきます。健康保険から届く医療費の通知も使えます。保険料の控除証明書は、なくしても保険会社に頼めば出し直してもらえることがあります。", why:"確定申告は、一年の所得と控除を本人が計算して届け出る仕組みなので、計算のもとになった数字を確かめられる書類を、本人の手元でそろえておく必要があるからです。" },
      { key:'faq_xszi_goukei_shotoku', faq:1, grp:'szi', q:"合計所得金額とは？", re:/合計所得金額|(扶養|配偶者控除)[^。]{0,8}(判定|判断)[^。]{0,6}(所得|金額)/, ng:/満期|返戻金|一時所得|保険金/, head:"各所得を合計した額で、退職所得や分けて計算する所得も含み、扶養や控除の判定に使います。", body:"合計所得金額は、給与・事業・年金などの所得に、退職所得や、土地を売った所得のように分けて計算する所得も加えた額です。所得控除を引く前の額で、前の年から繰り越した損失を引く前の額です。配偶者控除や扶養控除の対象になるか、基礎控除の額などの判定に使います。株式の利益のうち、申告しないことを選んだものは入りません。", acts:["扶養に入れたいご家族に、給与のほかの所得もあるかを聞き取る", "退職金を受け取る年は、所得税の扶養の判定に入るので、扶養から外れることがあるとお伝えする", "判定に使う所得の範囲は、税理士か税務署で確かめていただく"], actHead:"現場で使うなら", note:"合計所得金額に入る所得の範囲と判定の額は国税庁の公表で確かめる。住民税の判定は市区町村。個別の判断は税理士か税務署の窓口。", pre:1, say:"合計所得金額は、給与や年金だけでなく、退職金や財産を売った所得も含めた所得の合計で、扶養に入れるかなどの判定に使います。収入ではなく所得で見ることに気をつけましょう。", more:"扶養の判定は、収入ではなく所得で見ます。給与だけの方なら、給与の収入から給与所得控除を引いた額が、その方の所得になります。満期金のような一時所得は、特別控除を引いた残りの半分が入ります。同じように見える総所得金額や総所得金額等は範囲が違うので、制度ごとに確かめます。", why:"控除は、その家族の暮らしをどれだけ所得で支えているかを見て決めるため、分けて計算する所得も含めて、その人の一年の稼ぎの全体を一つの物差しでそろえて測る必要があるからです。" },
      { key:'faq_xszi_furusato_henreihin', faq:1, grp:'szi', q:"ふるさと納税の返礼品に税金はかかる？", re:/(返礼品|お礼の品)[^。]{0,14}(税金|課税|所得|確定申告|申告|満期)|ふるさと納税[^。]{0,8}(返礼品|お礼の品)[^。]{0,12}(税|所得|申告)/, head:"返礼品は一時所得になり、ほかの一時所得と合わせて一定を超えると税がかかります。", body:"ふるさと納税の返礼品は、受け取った品の価値が一時所得として扱われます。一時所得には年ごとの特別控除があるので、その年のほかの一時所得と合わせて控除の範囲に収まれば、税はかかりません。満期金や解約返戻金などを同じ年に受け取ると、合わせて控除を超えることがあります。品の価値の見積もり方は、税務署に確かめます。", acts:["その年に受け取った返礼品と、満期金などのほかの一時所得を書き出していただく", "満期金を受け取る年は、返礼品も合わせて数えるとお伝えする", "申告が要るかと品の価値の見積もり方は、税理士か税務署で確かめていただく"], actHead:"現場で使うなら", note:"返礼品の扱いと一時所得の特別控除は国税庁の公表で確かめる。品の価値の見積もり方と申告の判断は税理士か税務署の窓口。", pre:1, say:"ふるさと納税の返礼品は一時所得になりますが、特別控除の範囲なら税はかかりません。満期金などを受け取る年は合わせて数えるので、税務署か税理士に確かめましょう。", more:"一時所得は、特別控除を引いた残りの半分が、ほかの所得と合わせて計算されます。給与だけの方は、給与のほかの所得が一定以下なら確定申告が要らないこともあります。ただし、医療費控除などで確定申告をするときは、一時所得も含めて申告します。", why:"返礼品は、寄附に対して自治体から受け取る品で、働いた対価でも財産を売った利益でもない一時的な利益にあたるので、税の上では一時所得として扱う決まりになっているからです。" },
      { key:'faq_xszi_onestop_wasure', faq:1, grp:'szi', q:"ワンストップ特例の申請を出し忘れたら？", re:/ワンストップ[^。]{0,12}(出し忘れ|忘れ|間に合わ|遅れ|届かな|送り忘れ|何か所|何カ所|何ヶ所|いくつ|何団体|引っ越|引越|住所が変わ|転居)/, head:"出し忘れても、確定申告で寄附金控除を受ければ、ふるさと納税の控除を受けられます。", body:"ワンストップ特例の申請が期限に間に合わなかったときは、確定申告で寄附金控除を受けることで、控除を受けられます。確定申告では、その年の全ての寄附を含めて申告し、寄附の受領証明書などが要ります。ワンストップ特例は、寄附先が一定の数までで、確定申告をしない方が使える仕組みです。申請のあとで住所や名前が変わったときは、寄附先へ変更の届けを出します。", acts:["寄附した自治体の数と、申請書を出したかを一覧にしていただく", "間に合わなかったときは、寄附の受領証明書をそろえて確定申告をするようお伝えする", "申請の期限と出し方は、寄附先の自治体か税務署の窓口で確かめていただく"], actHead:"現場で使うなら", note:"ワンストップ特例の期限・寄附先の数・変更の届けは総務省と寄附先の自治体の公表で確かめる。申告の判断は税理士か税務署の窓口。", pre:1, say:"ワンストップ特例の申請を出し忘れても、確定申告をすればふるさと納税の控除は受けられます。寄附の受領証明書を捨てずにそろえておきましょう。", more:"医療費控除などで確定申告をする方は、ワンストップ特例の申請をしていても特例は使えなくなるので、確定申告にふるさと納税の寄附も全て書きます。寄附先が一定の数を超えたときも確定申告になります。同じ自治体に何度寄附しても、数は一つとして数えます。", why:"ワンストップ特例は、確定申告をしない会社員などの手間を省くために、寄附先が申請をもとに住民税から差し引けるようにした仕組みなので、申請が届かないときや確定申告をするときは、申告で控除を受ける本来の形に戻るからです。" },
      { key:'faq_xszi_fukkou', faq:1, grp:'szi', q:"復興特別所得税とは？", re:/復興特別所得税|復興税|所得税[^。]{0,6}(上乗せ|上のせ)[^。]{0,8}(税|分)/, ng:/法人|住民税|均等割/, head:"東日本大震災からの復興の財源にあてるため、所得税の額に上乗せして納める国の税です。", body:"復興特別所得税は、東日本大震災からの復興の財源にあてるために設けられた国の税です。決められた期間、その年の所得税の額に一定の率をかけた額を、所得税と一緒に納めます。給与や報酬から源泉徴収される税にも含まれ、源泉徴収票の源泉徴収税額は、所得税と復興特別所得税を合わせた額です。", acts:["源泉徴収票の源泉徴収税額に、復興特別所得税も含まれているとお伝えする", "確定申告書には、所得税と合わせた額を書く欄があると添える", "率と期間の最新は、国税庁の公表か税務署の窓口で確かめていただく"], actHead:"現場で使うなら", note:"復興特別所得税の率と期間は国税庁の公表で確かめる。財源の見直しで変わることがあるので最新を確かめる。個別の税額の判断は税理士か税務署の窓口。", pre:1, say:"復興特別所得税は、震災からの復興の財源のために、所得税の額に上乗せして納める税です。源泉徴収票の税額にも含まれています。", more:"この税は所得税の額をもとにかかるので、所得控除や税額控除で所得税が少なくなれば、この税も少なくなります。預金の利子や配当から差し引かれる税にも含まれます。財源の見直しで率や期間が変わることがあるので、国税庁の公表で最新の内容を確かめます。", why:"震災からの復興にかかる費用を、国債の返済も含めて長い期間をかけて広く分け合うため、所得税を納める方に少しずつ負担してもらう仕組みにしたからです。" },
      /* szk.json */
      { key:'faq_xszk_nagare', faq:1, grp:'szk', q:"相続の手続きはどんな流れで進む？", re:/相続(の)?(手続き?|手続)[^。]{0,10}(流れ|順番|全体|何から|進め方|進み方|段取り|全体像)|相続の流れ|相続(手続き?)?の全体像/, ng:/相続税|保険金|遺産分割協議|放棄|登記|会社|自社株|事業承継|名義変更|口座|相談先|専門家/, head:"遺言の確認、相続人と財産の確定、分け方の話し合い、名義の切り替えと申告の順に進みます。", body:"初めに遺言があるかを確かめ、戸籍で相続人を、通帳や郵便物で財産と借金を確かめます。そのうえで、遺言どおりに分けるか、相続人全員の話し合いで分け方を決め、預金や不動産の名義を切り替えます。手続きごとに期限があり、放棄の判断は早い時期に決める必要があるので、全体の順番を先に一枚にしておくと進めやすくなります。", acts:["遺言の有無・相続人・財産と借金・分け方・名義と申告の五つの段を紙に書き、ご遺族と今どこかを確かめる", "期限のある手続きは、それぞれの期限を家庭裁判所・法務局・税理士で確かめていただく", "保険金の請求は相続の手続きと別に進むことを伝え、保険会社の窓口を案内する"], actHead:"現場で使うなら", note:"手続きの順番と期限は家庭裁判所・法務局・市区町村の窓口で、税は税理士、法律上の判断は弁護士で確かめる。", pre:1, say:"相続の手続きは、遺言の確認、相続人と財産の確定、分け方の話し合い、名義の切り替えの順に進みます。期限のある手続きもあるので、全体の順番を一緒に整理しましょう。", more:"段ごとに相手が変わります。遺言の検認や放棄は家庭裁判所、不動産の名義は法務局、預金は金融機関、相続税は税務署が受け持ち、申告の作成は税理士の業務です。亡くなった方の所得税の申告が要る場合もあります。どこに何を出すかを一覧にしておくと、ご遺族の負担が軽くなります。", why:"相続人と財産が決まらないと分け方を決められず、分け方が決まらないと名義を切り替えられないからです。前の段の結果が次の段の材料になる仕組みなので、順番に進めます。" },
      { key:'faq_xszk_kigen', faq:1, grp:'szk', q:"相続の手続きにはどんな期限がある？", re:/相続[^。]{0,10}(期限|締め切り|いつまでに)/, ng:/相続税|放棄|登記|遺留分|保険金|請求|申告|国庫|払戻|払い戻/, head:"主な期限は、放棄の判断、亡くなった方の所得税の申告、相続税の申告、相続登記、遺留分の請求の五つです。", body:"期限の長さは手続きごとに違い、数え始めの日にも手続きごとの決まりがあります。放棄は早い時期に決める必要があり、相続税の申告と納付にも期限があります。相続登記は義務になり、遺留分の請求にも期限があるので、分かった時点で一覧にしておきます。", acts:["期限のある手続きを五つ並べ、それぞれの数え始めの日と期限を窓口と税理士に確かめて書き込む", "放棄を考えるかどうかは早めに話題にし、迷うときは家庭裁判所の窓口か弁護士を案内する", "相続税がかかるかもしれないときは、早い段階で税理士につなぐ"], actHead:"現場で使うなら", note:"各期限の長さと数え始めの日は家庭裁判所・法務局・税務署の公表で確かめ、個別の判断は弁護士・司法書士・税理士へ。", pre:1, say:"相続には手続きごとに期限があり、数え始めの日も違います。放棄、所得税と相続税の申告、登記、遺留分の五つを一覧にして、専門家に期限を確かめていただきましょう。", more:"期限を過ぎると選べなくなる手続きと、遅れると加算される税がかかる手続きがあります。放棄は期限を過ぎると原則として相続を受け入れた扱いになり、相続税の申告が遅れると税が重くなることがあります。期限を延ばすよう家庭裁判所に申し立てられる手続きもあるので、迷うときは早めに相談します。", why:"相続の手続きは、権利を早く確定させて、相続人やお金の貸し借りの相手が困らないように、それぞれに期限が決められているからです。" },
      { key:'faq_xszk_koseki', faq:1, grp:'szk', q:"相続の手続きで、戸籍はどこまで集める？", re:/戸籍[^。]{0,16}(どこまで|範囲|出生から|生まれてから|本籍地以外|取り寄せ|広域)|(出生から|生まれてから)[^。]{0,10}戸籍|本籍地[^。]{0,12}(遠|違う市|別の市|以外)/, ng:/保険金|請求|年金|保険会社|給付|法定相続情報/, head:"亡くなった方の生まれてから亡くなるまでの戸籍と、相続人の今の戸籍を集めます。", body:"亡くなった方の戸籍を生まれてから亡くなるまで続けて集めると、子どもが何人いるかなど、相続人が誰かを確かめられます。結婚や転籍などで戸籍は分かれていくので、何通にもなることがあります。本籍地以外の市区町村の窓口でまとめて請求できる仕組みもありますが、請求できる人や使えない戸籍には決まりがあります。", acts:["誰の戸籍がどこまで要るかは、提出先の金融機関や法務局に先に確かめていただく", "本籍地が遠い方には、近くの市区町村の窓口でまとめて請求できるかを確かめるよう伝える", "戸籍を何度も出すのが大変な方には、法務局の法定相続情報の一覧図も案内する"], actHead:"現場で使うなら", note:"戸籍の請求のしかたと請求できる人は市区町村の窓口で、相続人が誰かの個別の判断は弁護士・司法書士へ。", pre:1, say:"相続の手続きには、亡くなった方の生まれてから亡くなるまでの戸籍と、相続人の今の戸籍が要ります。何通にもなることが多いので、提出先に必要な範囲を先に確かめましょう。", more:"子どもがいない場合は、親や兄弟姉妹が相続人になることがあり、そのときは親の戸籍まで要ることがあります。また、戸籍を集めて初めて、前の結婚の子どもや認知した子どもが分かることもあります。相続人の範囲は戸籍で決まるので、思い込みで手続きを進めないことが大切です。", why:"相続人が誰かは、付き合いの深さではなく戸籍の記載で決まるからです。途中の戸籍が欠けると、ほかに相続人がいないことを示せないため、続けて集めます。" },
      { key:'faq_xszk_ichiranzu', faq:1, grp:'szk', q:"法定相続情報の一覧図とは？", re:/法定相続情報|戸籍[^。]{0,8}(束|何度も|何回も|何通も)/, head:"相続人が誰かを一枚にまとめ、法務局が認めた写しを戸籍の束の代わりに使える仕組みです。", body:"戸籍の束と、相続人を一覧にした図を法務局に出すと、登記官が確かめたうえで、その写しを無料で交付してくれます。預金の解約や不動産の名義の切り替えなどで、戸籍の束の代わりに使えます。使える手続きかどうかは、提出先で確かめます。", acts:["預金や不動産など提出先が多いご遺族に、一覧図の写しが使えるかを提出先で確かめていただく", "申し出の書類と出し方は、法務局の窓口や案内で確かめていただく", "手続きを代わりに頼みたい方には、司法書士などの専門家を案内する"], actHead:"現場で使うなら", note:"申し出のしかた・要る書類・使える手続きは法務局の窓口と、提出先の金融機関で確かめる。", pre:1, say:"法定相続情報の一覧図は、相続人が誰かを法務局が確かめて一枚にまとめたものです。戸籍の束の代わりに使える手続きが多いので、提出先が多いときに役立ちます。", more:"一覧図の写しは要る枚数を受け取れるので、金融機関を何か所も回るときに、戸籍の束を返してもらうのを待たずに並行して進められます。一覧図は戸籍から分かる相続人を書いたもので、放棄や分け方の結果までは表しません。生命保険金の請求に使えるかは保険会社で確かめます。", why:"手続きのたびに戸籍の束を出して返してもらう手間を省き、相続の名義の切り替えを進めやすくするために作られた仕組みだからです。" },
      { key:'faq_xszk_yuigon_sagasu', faq:1, grp:'szk', q:"遺言があるかどうか、どう調べる？", re:/遺言(書)?[^。]{0,10}(あるか|有無|残したか|残していたか|残されているか|探す|探し|調べ|検索|見つから)|(遺言|遺言書)(が|を)?(あるか|ないか)/, ng:/受取人|保険金/, head:"公正証書遺言は公証役場で、法務局に預けた遺言は法務局で調べられ、自宅の遺言は探すしかありません。", body:"公正証書で作った遺言は、相続人などが公証役場で、作られているかを調べてもらえます。法務局に預けた自筆の遺言は、法務局で預けてあるかの証明を受けられます。自宅などに置いた自筆の遺言は調べる仕組みが無いので、机や金庫、貸金庫などを探します。", acts:["公正証書で作った覚えがあるかを、ご家族に確かめていただく", "調べ方と持ち物は、公証役場と法務局の窓口で確かめていただく", "遺言が見つかったら、開ける前に扱い方を家庭裁判所の窓口で確かめるよう伝える"], actHead:"現場で使うなら", note:"調べられる人と要る書類は公証役場と法務局の窓口で確かめる。遺言の中身の判断は弁護士へ。", pre:1, say:"遺言があるかは、公正証書なら公証役場、法務局に預けた遺言なら法務局で調べられます。ご自宅に置いた遺言は探すしかないので、心当たりの場所を一緒に考えましょう。", more:"遺言が見つからないまま分け方を決めたあとで遺言が出てくると、話し合いをやり直すことになる場合があります。分け方の話し合いの前に、調べられるところは調べておきます。見つかった遺言が一通とは限らず、内容が食い違う部分は後に作られた遺言が優先する決まりもあります。", why:"遺言があると、遺言の内容が分け方の出発点になるからです。遺言の有無で手続きの進め方が変わるため、分け方を話し合う前に確かめます。" },
      { key:'faq_xszk_hokan', faq:1, grp:'szk', q:"遺言書を法務局に預ける制度とは？", re:/(遺言|遺言書)[^。]{0,10}(法務局|保管所|保管制度|預け|預か)|法務局[^。]{0,10}遺言|遺言書保管/, head:"自筆で書いた遺言を本人が法務局に預け、なくしたり書き換えられたりするのを防ぐ制度です。", body:"遺言を書いた本人が法務局に出向いて預けます。法務局は決まった形で書かれているかを確かめますが、中身が有効かまでは見ません。預けた遺言は家庭裁判所の検認が要らず、本人が亡くなったあと、本人が決めておいた方へ知らせが届く仕組みもあります。", acts:["自分で書いた遺言を家に置いているお客様に、預ける仕組みがあることと、予約が要るかを窓口で確かめるよう伝える", "中身が有効かや分け方の相談は、弁護士などの専門家につなぐ", "預けたことをご家族に伝えておくよう、お客様にお勧めする"], actHead:"現場で使うなら", note:"預け方・手数料・予約・知らせの仕組みは法務局の窓口と案内で確かめる。中身が有効かの判断は弁護士へ。", pre:1, say:"自筆の遺言は、法務局に預けておくと、なくしたり書き換えられたりする心配が減ります。家庭裁判所の検認も要らなくなるので、仕組みを法務局で確かめてみてください。", more:"法務局が見るのは日付や署名などの形で、分け方が遺留分に配慮しているかや、内容がご家族の思いに合っているかは見ません。中身を整えるのは別の話なので、書く前に専門家に相談する方もいます。預けたあとで書き直したいときは、預けた遺言を返してもらったり、新しい遺言を預け直したりできます。", why:"自宅に置いた自筆の遺言は、見つからない・書き換えられる・家庭裁判所の検認が要る、という弱点があり、それを補うために作られた制度だからです。" },
      { key:'faq_xszk_mitsukatta', faq:1, grp:'szk', q:"自宅で遺言書が見つかったらどうする？", re:/遺言(書)?[^。]{0,10}(見つかっ|出てき|見つけた|発見)|(封|封筒)[^。]{0,8}遺言|遺言(書)?[^。]{0,8}(開け|開封)/, ng:/二つ|二通|複数|どちらが|優先|新しい|保険金|受取人/, head:"封のある遺言は開けずに、家庭裁判所で検認という手続きを受けます。", body:"自宅で見つかった自筆の遺言は、家庭裁判所に検認を申し立て、相続人などが立ち会える場で開けて中身を確かめます。封のある遺言を勝手に開けても遺言が無効になるわけではありませんが、決まりに反することになります。法務局に預けた遺言と公正証書遺言は、検認が要りません。", acts:["見つけた方に、封を開けずにそのまま保管していただくよう伝える", "申し立ての書類と出し方は、家庭裁判所の窓口で確かめていただく", "遺言の中身が有効かや分け方の相談は、弁護士などの専門家につなぐ"], actHead:"現場で使うなら", note:"検認の申し立てのしかたと要る書類は家庭裁判所の窓口で、遺言が有効かの判断は弁護士へ。", pre:1, say:"封のある遺言は開けずに、家庭裁判所で検認を受けてから開けます。開けてしまっても無効にはなりませんが、まずは封をしたまま保管しておいてください。", more:"検認は、遺言の形や状態をその日の時点で記録して、あとで書き換えられるのを防ぐ手続きです。遺言が有効かどうかを決める手続きではありません。検認が済まないと、預金や不動産の名義の切り替えに遺言を使えないことが多いので、早めに申し立てます。", why:"自筆の遺言は書いた本人のほかに確かめた人がいないので、見つかった時点の状態を家庭裁判所で記録して、相続人のあいだで中身を疑い合わないようにするためです。" },
      { key:'faq_xszk_shikkousha', faq:1, grp:'szk', q:"遺言執行者とは？", re:/遺言執行(者|人)|遺言[^。]{0,6}執行者|執行者に(選ば|指定)/, ng:/保険金|受取人/, head:"遺言の内容を実現するために、預金の解約や名義の切り替えなどの手続きを進める人です。", body:"遺言で決めておくほか、家庭裁判所に選んでもらうこともあります。執行者は、任務を始めたら相続人に遺言の内容を知らせ、財産の一覧を作って渡し、遺言どおりに手続きを進めます。相続人のほか、弁護士や司法書士、信託銀行などがなることもあります。", acts:["遺言に執行者の名前が書かれているかを、ご遺族に確かめていただく", "執行者に選ばれて負担が重い方には、専門家に任せる道があることと、家庭裁判所の窓口を伝える", "保険金の受取人は遺言とは別に決まっていることがあるので、保険会社で確かめる"], actHead:"現場で使うなら", note:"執行者の仕事の範囲と選び方は家庭裁判所の窓口で確かめ、個別の判断は弁護士・司法書士へ。", pre:1, say:"遺言執行者は、遺言に書かれたとおりに名義の切り替えなどを進める人です。選ばれて負担が重いときは、専門家に任せる道もあるので相談してみましょう。", more:"執行者がいると、相続人が勝手に財産を処分しても、遺言の実現をさまたげる行いとして効力が否定されることがあります。執行者は、自分の判断で専門家に仕事を任せることもできます。選ばれても引き受けるかは選べますが、引き受けたあとで辞めるには家庭裁判所の許しが要ります。", why:"相続人が何人もいると、遺言どおりに手続きを進める役が決まらず止まりやすいため、実現の役目を一人に任せられるようにした仕組みだからです。" },
      { key:'faq_xszk_yuigon_chigau', faq:1, grp:'szk', q:"遺言と違う分け方にしてもいい？", re:/遺言(書)?[^。]{0,8}(と違う|と異なる|どおりに(しない|分けない|分けなく|しなく)|どおりでなく|通りに(しない|分けない|分けなく)|に従わない|を無視)|遺言(書)?[^。]{0,16}(話し合って|話し合いで)[^。]{0,10}(分け|決め)/, ng:/保険金|受取人|納得|不公平|無効/, head:"相続人と遺言で財産をもらう人の全員が同意すれば、遺言と違う分け方にできる場合があります。", body:"遺言があっても、相続人と遺言で財産を受け取る人の全員が合意すれば、話し合いで違う分け方を決められる場合があります。ただし、遺言で分けることを禁じていたり、遺言執行者がいたりすると扱いが変わります。一人でも反対があれば、遺言が出発点になります。", acts:["遺言で財産を受け取る人が相続人のほかにいないかを、遺言の文面で確かめていただく", "違う分け方を考えるときは、決める前に弁護士か司法書士に進め方を相談するよう伝える", "相続税がかかる場合は、分け方で税が変わることがあるので税理士につなぐ"], actHead:"現場で使うなら", note:"遺言と違う分け方ができるかの個別の判断は弁護士、名義の切り替えは司法書士、税は税理士で確かめる。", pre:1, say:"遺言があっても、相続人と遺言で財産を受け取る方の全員が同意すれば、違う分け方にできる場合があります。決める前に専門家に確かめていただきましょう。", more:"全員で決めた分け方は遺産分割協議書にまとめ、全員が署名と押印をします。遺言執行者がいるときは、執行者の同意を得て進めるのが普通です。遺言の内容が一部の方に偏っているときは、遺言を出発点に話し合ったうえで、遺留分の話になることもあります。", why:"遺言は亡くなった方の思いを形にしたものですが、受け取る人が全員そろって別の分け方を望むなら、その意思も尊重できると考えられているからです。" },
      { key:'faq_xszk_yuigon_fuman', faq:1, grp:'szk', q:"遺言の内容に納得できないと言われたら？", re:/遺言(書)?[^。]{0,12}(納得でき|納得いか|不公平|おかしい|無効|怪しい|偽物|認めたくない|認められない)/, ng:/保険金|受取人/, head:"遺言そのものの有効性を争う道と、遺留分を請求する道があり、どちらも弁護士に相談します。", body:"書いたときに判断する力があったか、本人が書いたものか、決まった形を守っているかが疑わしいときは、遺言が有効かを争う道があります。遺言は有効でも取り分が大きく偏っているときは、遺留分として一定の額を求められる場合があります。どちらも期限や証拠の集め方が大事なので、早めに弁護士へつなぎます。", acts:["お気持ちを受け止めたうえで、こちらでは有効かどうかを決められないことを伝える", "遺言の写しと、書かれた頃の様子が分かる記録を手元にまとめておくよう伝える", "地域の弁護士会や法律相談の窓口など、弁護士の相談先を案内する"], actHead:"現場で使うなら", note:"遺言が有効かと遺留分の判断は弁護士へ。相談の窓口は地域の弁護士会や法テラスで確かめる。", pre:1, say:"お気持ちはもっともです。遺言が有効かどうかを争う道と、遺留分を求める道があり、どちらも弁護士の判断になるので、早めに相談してみてください。", more:"遺言が有効かを争うときは、話し合いや家庭裁判所の調停を経て、裁判で決めることもあります。遺留分は、遺言で多く受け取った方にお金で払ってもらう形になっています。気持ちがこじれると話し合いが長引くので、中に立つ専門家を早めに入れる方もいます。", why:"遺言は亡くなった方の最後の意思として尊重されますが、本人が本当に書いたかや、残された家族の最低限の取り分を守る決まりもあり、その判断は法律の専門家の領域だからです。" },
      { key:'faq_xszk_kakinaoshi', faq:1, grp:'szk', q:"遺言は書き直せる？", re:/遺言(書)?[^。]{0,10}(書き直|書きなおし|作り直|変えたい|変更|取り消|撤回|やり直)|遺言(書)?[^。]{0,8}(二つ|二通|複数|何通)|(新しい|後の|前の)遺言[^。]{0,8}(優先|どちら|どっち|取り消)/, ng:/受取人|保険金|保険/, head:"遺言はいつでも書き直せ、内容が食い違う部分は、後に書いた遺言が優先します。", body:"遺言を書いた本人は、新しい遺言を書くことで、前の遺言の全部または一部を取り消せます。形の決まりは前と同じで、公正証書の遺言を自筆の遺言で取り消すこともできます。前の遺言と食い違わない部分は前の遺言も生きているので、両方を読み合わせます。", acts:["書き直したいお客様に、前の遺言をどうするかも含めて専門家に相談するよう伝える", "法務局や公証役場に預けている遺言の扱いは、それぞれの窓口で確かめていただく", "保険金の受取人は遺言とは別に決まることがあるので、受取人の変更が要るかを保険会社で確かめる"], actHead:"現場で使うなら", note:"書き直しの形と預けた遺言の扱いは法務局・公証役場の窓口で、内容の判断は弁護士・司法書士へ。", pre:1, say:"遺言は何度でも書き直せて、食い違う部分は後に書いた遺言が優先します。前の遺言をどうするかも含めて、専門家に相談しながら整えましょう。", more:"遺言を書いたあとに、その財産を生前に売ったり贈ったりすると、その部分は取り消したものとみなされます。また、書き直した遺言が見つからなければ前の遺言で手続きが進んでしまうので、新しい遺言の置き場所をご家族に伝えておくことも大切です。", why:"遺言は亡くなるまで効力が生じないので、家族の状況や本人の気持ちが変わったときに、最後の意思に合わせて直せるようにしているからです。" },
      { key:'faq_xszk_bunpou', faq:1, grp:'szk', q:"法定相続分はどう決まる？", re:/法定相続分|相続分(の)?(割合|決まり方|決め方|計算|比率)|(配偶者|妻|夫|子ども|子供|兄弟|姉妹|親)[^。]{0,10}の相続分|(配偶者|妻|夫|子ども|子供|兄弟|姉妹)[^。]{0,12}相続人のときの相続分/, ng:/保険金|受取人|相続税|遺留分/, head:"相続人の組み合わせで決まる目安で、遺言や話し合いで別の分け方にすることもできます。", body:"法定相続分は、配偶者と子ども、配偶者と親、配偶者と兄弟姉妹のように、相続人の組み合わせごとに決まっています。後の順番の相続人と並ぶほど、配偶者の割合は大きくなります。同じ順番の人どうしは原則として等しく分け、結婚していない親の子どもも同じ扱いです。", acts:["相続人が誰かを戸籍で確かめてから、相続分の目安を専門家に確かめていただく", "分け方は話し合いで決められることを伝え、法定相続分どおりに分ける決まりではないと説明する", "相続税の計算では法定相続分を使う場面があるので、税は税理士につなぐ"], actHead:"現場で使うなら", note:"相続分の割合と個別の当てはめは弁護士・司法書士で、相続税での使い方は税理士で確かめる。", pre:1, say:"法定相続分は、相続人の組み合わせごとに決まった目安です。必ずその割合で分けるわけではなく、話し合いで決めることもできます。", more:"亡くなった方より先に子どもが亡くなっていると、その子ども（孫）が代わりに相続人になり、親の相続分を引き継ぎます。兄弟姉妹のうち片方の親だけが同じ方は、両親が同じ兄弟姉妹の半分になる決まりもあります。組み合わせが込み入っているときは、専門家に一覧にしてもらいます。", why:"遺言や話し合いが無いときでも分け方の基準がないと困るので、亡くなった方と近い関係の人ほど手厚くなるよう、法律で目安を決めているからです。" },
      { key:'faq_xszk_naien', faq:1, grp:'szk', q:"内縁の妻に財産を残すには？", re:/(内縁|事実婚|籍を入れていない|入籍していない|パートナー)[^。]{0,12}(財産|遺産|相続|残し|残す|受け取れ|渡せ|渡す)/, ng:/受取人|保険金|保険料|控除|生命保険|ペット|会社|事業|ビジネス|住宅|家賃|年金/, head:"内縁や事実婚の相手は相続人にならないので、遺言などで残す準備が要ります。", body:"籍を入れていない相手は、長く一緒に暮らしていても相続人になりません。財産を残したいときは、遺言で遺贈する、生前に贈与するなどの方法があり、相続人の遺留分にも配慮が要ります。相続人がいないときに限り、家庭裁判所に財産を分けてもらうよう求める道もあります。", acts:["籍を入れていないご夫婦に、相続人にはならないことと、遺言で残す道があることを伝える", "遺言の書き方や遺留分への配慮は、弁護士や司法書士に相談するよう伝える", "生命保険の受取人に指定できるかは、保険会社の決まりで確かめる"], actHead:"現場で使うなら", note:"遺言・遺贈・特別縁故者の個別の判断は弁護士・司法書士、税は税理士、受取人の範囲は保険会社で確かめる。", pre:1, say:"籍を入れていないお相手は相続人にならないので、遺言などで準備しておくと、思う形で財産を残しやすくなります。専門家に相談しながら進めましょう。", more:"遺言で財産を受け取る場合、相続税がかかるときは、配偶者向けの軽減が使えず、税の額が加算される扱いになることがあります。住まいを残したいときは、名義や賃貸の契約も確かめておきます。お互いの思いを書面にしておくことが、残された方を守ることにつながります。", why:"相続人の範囲は戸籍上の関係で決まり、一緒に暮らした年月だけでは決まらない仕組みだからです。" },
      { key:'faq_xszk_shiranai', faq:1, grp:'szk', q:"会ったことのない相続人がいたら？", re:/(会ったことのない|会ったこともない|知らない|面識のない|疎遠な)[^。]{0,10}(相続人|兄弟|姉妹|子ども|子供|親族|甥|姪)|前の結婚の(子|子ども|子供)[^。]{0,12}(話し合|協議|遺産|分け)|(疎遠|面識)[^。]{0,12}(遺産|相続|話し合)/, ng:/受取人|保険金|保険/, head:"会ったことがなくても相続人なので、分け方を決めるにはその方の合意も要ります。", body:"相続人かどうかは戸籍で決まるので、付き合いが無い方にも、話し合いに加わっていただく必要があります。戸籍の附票で住所を確かめられる場合があり、最初は手紙で事情を丁寧に伝えるのが普通です。こじれそうなときや連絡が難しいときは、弁護士や司法書士に間に入ってもらう道があります。", acts:["相続人の一覧を戸籍で作ってから、付き合いの無い方がいないかを確かめていただく", "最初の連絡は、事情とこれからの流れを書いた手紙にするのが普通だと伝える", "話がこじれそうなときは、弁護士や司法書士を案内する"], actHead:"現場で使うなら", note:"相続人の確定と連絡の進め方は弁護士・司法書士、住所の調べ方は市区町村の窓口で確かめる。", pre:1, say:"会ったことのない方でも相続人なので、分け方を決めるには合意が要ります。最初の連絡のしかたを含めて、専門家に相談しながら進めましょう。", more:"前の結婚の子どもや、認知した子どもは、今の家族の子どもと同じ順番の相続人です。話し合いに加わってもらえないときは、家庭裁判所の調停を使う道もあります。最初の手紙で財産の一覧や分け方の案を一方的に送ると、かえってこじれることがあるので、伝え方を専門家と相談します。", why:"分け方の話し合いは相続人全員の合意で決める仕組みで、一人でも欠けると、決めた分け方が有効にならないからです。" },
      { key:'faq_xszk_yukue', faq:1, grp:'szk', q:"相続人の一人の行方が分からないときは？", re:/相続人[^。]{0,14}(行方|所在が|居場所|音信|連絡が(つか|つき|取れ|とれ))|(行方|音信|連絡の取れない|連絡がつかない)[^。]{0,10}相続人|(行方|音信)[^。]{0,16}(遺産|相続)/, ng:/受取人|保険金|契約者|請求|給付|保険会社|被保険者/, head:"家庭裁判所に、その方の代わりに財産を管理する人を選んでもらい、話し合いを進める道があります。", body:"行方の分からない相続人がいると、その方を抜いて分け方を決められません。家庭裁判所に不在者財産管理人を選んでもらい、裁判所の許しを得て話し合いに加わってもらう方法があります。生死が長く分からないときは、失踪宣告という手続きが使える場合もあります。", acts:["まず戸籍の附票などで住所を確かめ、手紙を送るなど連絡を試みたかを確かめていただく", "見つからないときの手続きは、家庭裁判所の窓口か弁護士・司法書士に相談するよう伝える", "保険金の受取人と連絡がつかない話は相続とは別なので、保険会社の手続きを案内する"], actHead:"現場で使うなら", note:"不在者財産管理人と失踪宣告の要件と申し立ては家庭裁判所の窓口で、個別の判断は弁護士・司法書士へ。", pre:1, say:"連絡の取れない相続人がいても、家庭裁判所に代わりの管理人を選んでもらって話し合いを進める道があります。進め方は家庭裁判所や専門家に確かめていただきましょう。", more:"管理人が加わる話し合いでは、行方の分からない方の取り分を確保する分け方が求められるのが普通です。管理人には弁護士などが選ばれ、費用を先に納めるよう求められることもあります。手続きには時間がかかるので、期限のある手続きと並行して早めに相談します。", why:"分け方は相続人全員の合意で決める仕組みなので、一人でも欠けると決められず、その方の権利を守りながら手続きを進める役が要るからです。" },
      { key:'faq_xszk_miseinen', faq:1, grp:'szk', q:"相続人に未成年の子どもがいるときは？", re:/(相続人|遺産分割|遺産の分け方|分割協議)[^。]{0,14}(未成年|特別代理人)|未成年[^。]{0,14}(相続人|遺産分割|分割協議|遺産)|特別代理人|(子どもが小さ|子供が小さ)[^。]{0,14}(遺産|相続|分け方)/, ng:/受取人|保険金|請求|給付|保険会社|口座/, head:"親と未成年の子が一緒に相続人のときは、子のために家庭裁判所で特別代理人を選んでもらいます。", body:"親と子が同じ相続の相続人になると、親が子の分まで話し合いで決めると、親の取り分と子の取り分がぶつかります。そのため、子のために家庭裁判所が選んだ特別代理人が話し合いに加わります。子が何人もいれば、子ごとに特別代理人が要るのが普通です。", acts:["相続人の中に未成年の方がいないかを、戸籍と生年月日で確かめていただく", "申し立ての書類と、分け方の案の出し方は、家庭裁判所の窓口で確かめていただく", "分け方の案づくりは、弁護士か司法書士に相談するよう伝える"], actHead:"現場で使うなら", note:"特別代理人の申し立てと、成年になる年齢は家庭裁判所の窓口と公的な案内で確かめ、個別の判断は弁護士・司法書士へ。", pre:1, say:"親とお子さまが一緒に相続人のときは、お子さまのために家庭裁判所で特別代理人を選んでもらいます。手続きを家庭裁判所に確かめてから、分け方を話し合いましょう。", more:"特別代理人の申し立てでは、分け方の案を一緒に出し、子の取り分が守られているかを家庭裁判所が見ます。子の取り分が法定相続分を下回る案は認められにくいことがあります。子が成年になるのを待つ方法もありますが、待つあいだに期限のある手続きが進められないことがあるので、専門家に相談します。", why:"親が子の代わりに決めると、親が多く受け取るほど子の取り分が減る関係になるため、子の側に立つ人を別に選んで、子の権利を守る決まりだからです。" },
      { key:'faq_xszk_ninchi', faq:1, grp:'szk', q:"相続人に認知症の方がいると遺産分割はどうなる？", re:/(相続人|遺産分割|分割協議|遺産の分け方|相続の手続)[^。]{0,16}(認知症|判断能力|判断する力)|(認知症|判断能力が落ち|判断能力の落ち)[^。]{0,16}(相続人|遺産分割|分割協議|遺産)/, ng:/受取人|保険金|請求|給付|保険会社|社長|経営者|会社|株|契約者|口座/, head:"判断する力が十分でない方は話し合いに加われないので、成年後見人を選んでもらって進めるのが普通です。", body:"遺産の分け方の話し合いは、内容を理解して判断できる人どうしでないと有効になりません。判断する力が十分でない相続人がいるときは、家庭裁判所に成年後見人などを選んでもらい、その方が本人に代わって加わります。後見人は、相続が終わったあとも本人の財産を見守り続けるのが普通です。", acts:["相続人の中に判断が難しくなっている方がいないかを、ご家族に確かめていただく", "後見の申し立てのしかたは、家庭裁判所の窓口や市区町村の相談窓口で確かめていただく", "分け方の案や手続きの進め方は、弁護士か司法書士に相談するよう伝える"], actHead:"現場で使うなら", note:"後見の申し立ては家庭裁判所の窓口で、話し合いに加われるかは医師・弁護士・司法書士で確かめる。", pre:1, say:"判断する力が十分でない方がいると、そのままでは分け方を決められないことがあります。家庭裁判所に後見人を選んでもらう道があるので、専門家に相談しながら進めましょう。", more:"後見人は本人の利益を守る立場なので、本人の取り分を法定相続分より大きく減らす分け方には応じにくいのが普通です。また、ご家族が後見人を務めていても、その方も相続人なら、別に特別代理人などが要ることがあります。親が元気なうちの備えとして、遺言を作っておく方もいます。", why:"分け方の話し合いは、相続人それぞれが自分の取り分を理解して合意する仕組みなので、判断する力が十分でない方の権利を守る人が要るからです。" },
      { key:'faq_xszk_inai', faq:1, grp:'szk', q:"相続人がいないと財産はどうなる？", re:/相続人が(い|居)(ない|なかった|なけれ)|相続人(が)?(一人も|誰も)|身寄りのない[^。]{0,10}(遺産|財産|相続)|相続財産清算人|特別縁故者/, ng:/受取人|保険金|保険/, head:"清算人が借金などを払い、残りは縁のあった方に分けられるか、国のものになります。", body:"相続人がいないときは、利害関係のある人などの申し立てで家庭裁判所が相続財産清算人を選び、借金や遺言で贈られた分を払います。そのうえで、一緒に暮らしていた方や介護をしていた方などが求めれば、家庭裁判所が財産の一部を分けることがあります。残った財産は国のものになります。", acts:["身寄りの少ないお客様には、遺言で誰に残すかを決めておく道があることを伝える", "清算人や縁故者の手続きは、家庭裁判所の窓口か弁護士に確かめていただく", "生命保険の受取人の指定が今の状況に合っているかを、保険会社の手続きで確かめる"], actHead:"現場で使うなら", note:"相続財産清算人と特別縁故者の手続きと要件は家庭裁判所の窓口で、個別の判断は弁護士・司法書士へ。", pre:1, say:"相続人がいないと、借金などを払ったあとの財産は、縁のあった方に分けられるか、国のものになります。残したい方がいるなら、遺言で決めておくのが確かです。", more:"縁のあった方に分けるかは家庭裁判所が決めるので、思いどおりになるとは限りません。友人やお世話になった施設、寄付したい団体などに残したいときは、遺言で遺贈しておくのが確かな方法です。遺言執行者も決めておくと、手続きが滞りにくくなります。", why:"持ち主のいなくなった財産をそのままにすると、お金を貸した人なども困るので、清算する人を選んで整理し、残りの行き先を決める仕組みだからです。" },
      { key:'faq_xszk_haijo', faq:1, grp:'szk', q:"相続人になれない人はいる？", re:/相続人(に|には)?なれない|相続(人)?(の)?(廃除|欠格)|相続欠格|(相続|遺産)(の)?(権利|資格)を(失|なく)/, ng:/受取人|保険金|保険/, head:"決まった重い事情があると相続人になれず、本人が家庭裁判所に申し立てて外す仕組みもあります。", body:"亡くなった方の命を奪おうとして刑を受けた、遺言を偽ったり隠したりしたなど、決まった重い事情があると、当然に相続人になれません（相続欠格）。また、本人をひどく虐げたり侮辱したりした相続人を、本人の申し立てや遺言によって家庭裁判所が外す仕組みもあります（廃除）。どちらも、外れた方の子どもが代わりに相続人になります。", acts:["特定の相続人に財産を渡したくないという相談は、遺言と遺留分の話も含めて弁護士につなぐ", "外す手続きは家庭裁判所が事情を見て決めることで、申し立てれば認められるとは限らないと伝える", "外れた方の子どもが代わりに相続人になる点を、相続人の一覧を作るときに確かめていただく"], actHead:"現場で使うなら", note:"欠格と廃除の要件と申し立ては家庭裁判所の窓口で確かめ、個別の判断は弁護士へ。", pre:1, say:"決まった重い事情があると相続人になれず、ご本人が家庭裁判所に申し立てて外す仕組みもあります。個別の事情は弁護士に確かめていただきましょう。", more:"廃除が認められるのは、家庭裁判所が事情を見て重いと判断したときに限られ、認められる例は多くありません。財産を渡したくない相手がいるときは、遺言で取り分を減らす方法もありますが、遺留分の請求を受けることがあります。廃除はあとから取り消すこともできます。", why:"相続は家族の支え合いを前提にした仕組みなので、その前提を大きく損なう行いをした人にまで財産を渡すのは公平でないと考えられているからです。" },
      { key:'faq_xszk_kaigai', faq:1, grp:'szk', q:"相続人が海外に住んでいるときは？", re:/(相続人|兄弟|姉妹|子ども|子供|親族)[^。]{0,10}(海外|外国)[^。]{0,8}(住|在住|暮ら)|(海外|外国)[^。]{0,8}(住む|住んで|在住|暮らす|暮らして)[^。]{0,12}(相続人|兄弟|姉妹|遺産|相続)/, ng:/受取人|保険金|保険料|控除|給付|入院|手術|保険会社|年金/, head:"印鑑証明の代わりに、住んでいる国の日本の大使館などで署名の証明を受けて手続きを進めます。", body:"海外に住む日本人の相続人は、日本の印鑑証明を取れないことが多いので、在外の大使館や領事館で署名証明を受けます。住所を示す書類として在留証明を使うこともあります。書類のやりとりに時間がかかるので、早めに要る書類を確かめておきます。", acts:["海外に住む相続人がいるときは、要る書類を提出先の金融機関や法務局に先に確かめていただく", "署名証明の取り方は、住んでいる国の日本の大使館や領事館の案内で確かめていただく", "書類の取りまとめは、司法書士などの専門家に頼む道もあると伝える"], actHead:"現場で使うなら", note:"署名証明・在留証明の取り方は在外公館の窓口で、名義の切り替えに要る書類は提出先と司法書士で確かめる。", pre:1, say:"海外にお住まいの相続人は、日本の印鑑証明の代わりに、大使館や領事館で署名の証明を受けて手続きをします。時間がかかるので、要る書類を早めに確かめましょう。", more:"外国の国籍の方が相続人のときは、その国の公証の仕組みで書類を整えるなど、別の準備が要ります。相続税では、海外に住む方が財産を受け取る場合の扱いに決まりがあり、住んでいる国でも税がかかることがあるので、税理士に確かめます。郵送の往復を減らすため、書類の案を先にそろえておきます。", why:"日本の印鑑証明は、日本に住民登録がある人のための仕組みなので、海外に住む方には、本人の署名であることを大使館などが証明する別の形が用意されているからです。" },
      /* tet.json */
      { key:'faq_xtet_kokuchibougai', faq:1, grp:'tet', q:"告知妨害や不告知教唆とは？", re:/告知妨害|不告知教唆|告知(の|を)?(とき|際)?に?[^。]{0,4}(募集人|代理店)[^。]{0,8}(してはいけな|禁止|やってはいけな|だめ)|(持病|病気|通院|入院)[^。]{0,8}(書かなくて|言わなくて|告知しなくて)(いい|大丈夫)[^。]{0,6}(と言|と伝え|と勧め)|告知(を|は)?しないよう(に)?(勧め|すすめ|言う|促)/, head:"告知を妨げることも、告知しないよう勧めることも、募集人がしてはいけないことです。", body:"保険業法では、お客様が事実を告げるのを妨げることや、事実を告げないよう勧めることを、募集人の禁止行為としています。「その程度なら書かなくていい」「黙っておけば分からない」と言うことも、これに当たり得ます。告知の誤りは契約の解除や支払われない理由になり、お客様ご自身が困ることになります。", acts:["告知書は被保険者ご本人に読んでいただき、迷う項目はそのまま保険会社に確かめる", "こちらで書かなくていいと判断して伝えない。書くかどうかの線は保険会社が決める", "通院や薬のことは、尋ねられていれば事実のまま書いていただく、と伝える", "言いすぎたと気づいたら、すぐ上長とコンプライアンス担当に伝え、手当てを一緒に考える"], actHead:"現場で使うなら", note:"何が告知妨害に当たるかの判断と、言ってしまったあとの手当ては、所属保険会社の手引きとコンプライアンス担当で確かめる。法律上の判断は弁護士。", pre:1, say:"告知は、ありのままにお書きいただくものです。どこまで書くか迷われたところは、私が決めずに、保険会社に確かめてからご案内します。", more:"よくあるのは、悪気なく「昔のことだから大丈夫ですよ」「薬だけなら書かなくても」と言ってしまう場面です。告知書で何を尋ねているかは商品ごとに違い、期間や対象も決まっているので、こちらの感覚で線を引かないことが大事です。お客様の気持ちに寄り添うことと、告知の線を引くことは別のことと考えます。", why:"保険は、同じくらいの健康状態の方どうしで保険料を分け合う仕組みなので、告知が正しくないと公平が崩れます。募集人が告知を曲げると、お客様が後で保険金を受け取れなくなるおそれがあるため、法律で禁じられています。" },
      { key:'faq_xtet_kokuchimore', faq:1, grp:'tet', q:"申込みのあとで告知漏れに気づいたら？", re:/告知(の)?(漏れ|もれ|忘れ|し忘れ|書き忘れ)|(告知書|告知)[^。]{0,8}(書き忘れ|書き漏ら|書いていな)|告知(の内容|書)?を?(直したい|訂正|修正)|告知(した|の)(後|あと)[^。]{0,12}(思い出|気づ|気付|分か)|(書き忘れ|言い忘れ)[^。]{0,6}(病気|通院|入院)/, head:"告知漏れに気づいたら、早めに保険会社へ申し出て、扱いを確かめていただきます。", body:"告知の誤りや漏れは、そのままにすると、あとで契約の解除や、保険金・給付金が支払われない理由になることがあります。気づいた時点で保険会社に申し出ると、改めて告知を受け直して引受けを判断し直すなど、保険会社所定の扱いになります。結果がどうなるかは、内容と時期で保険会社が決めます。", acts:["お客様から聞いた内容を、日付つきで書き取り、こちらで直したり書き足したりしない", "保険会社の窓口に申し出の方法と要る書類を確かめ、お客様ご本人から申し出ていただく", "結果を見込みで言わず、保険会社の判断を待つとお伝えする", "やりとりの記録を残し、上長にも共有する"], actHead:"現場で使うなら", note:"申し出の受け方・告知の受け直し・その後の扱いは保険会社と契約で違う。保険会社の引受の窓口と約款で確かめる。病気の判断は医師、法律上の判断は弁護士。", pre:1, say:"お知らせくださってありがとうございます。そのままにせず、保険会社に正しい内容をお伝えするのがいちばん安心です。お手続きの方法を確かめてご案内します。", more:"よくあるのは、契約のあとに届いた告知の写しを見返して、健康診断の指摘や、短い通院を書いていなかったと気づく場面です。黙っておけば分からないと考えず、気づいたときに申し出るほうが、お客様の立場を守ることになります。こちらで「その程度なら大丈夫」と言わず、保険会社の判断に委ねます。", why:"告知は保険会社が引受けを決める材料なので、誤りがあれば、本来の内容で判断し直す必要があるからです。気づいていながら黙っていると、あとで支払いの場面でもめるもとになります。" },
      { key:'faq_xtet_koushinkokuchi', faq:1, grp:'tet', q:"更新のときにも告知は要る？", re:/更新[^。]{0,10}(告知|診査|健康状態|審査)|(病気|入院|持病|がん)[^。]{0,10}(でも|しても|したら|になっても)[^。]{0,4}更新(でき|され|は)/, ng:/資格|免許|登録|契約書の更新/, head:"同じ保障のまま自動で更新する保険や特約は、告知なしで更新できるのが一般的です。", body:"更新型の保険や特約は、保険期間が終わるときに、それまでと同じ保障の内容で自動的に続く形が多く、そのときに告知や診査を求めない商品が一般的です。ただし、更新できる年齢の上限があり、更新後の保険料は更新するときの年齢で計算し直されます。保障の額を増やして更新するときなどは、告知が要ることがあります。", acts:["証券で、更新の時期と、更新できる年齢の上限を一緒に確かめる", "更新後の保険料は、保険会社から届く更新の案内で額を確かめてからお伝えする", "増額や内容の変更を伴うときは、告知が要るかを保険会社に確かめる"], actHead:"現場で使うなら", note:"更新の条件・告知の要否・更新できる年齢の上限は、商品と約款で違う。保険会社の約款と更新の案内で確かめる。", pre:1, say:"今のご契約は、同じ保障の内容なら、お体の状態にかかわらず更新できる形が一般的です。更新後の保険料は、お知らせが届いたら一緒に確かめましょう。", more:"よくある勘違いは、病気をしたら更新できなくなる、と思われることです。同じ内容での更新なら続けられる商品が多い一方で、保険料は上がるのが一般的です。保障を減らして更新する道や、更新しない道を選べる商品もあるので、案内が届いた時点で選べることを並べます。", why:"更新型は、保険期間が終わったあとも同じ保障を続けられることを前提に引き受けている仕組みだからです。続けるたびに審査し直すと、病気になった方ほど保障を失うことになり、保険の役目を果たせません。" },
      { key:'faq_xtet_shokugyo', faq:1, grp:'tet', q:"契約のあとで職業が変わったら届け出は要る？", re:/(職業|仕事|職種)[^。]{0,6}(が|を)?(変わ|変え)[^。]{0,16}(届け|届出|連絡|通知|保険はそのまま|保険はどう)|転職[^。]{0,10}(保険会社|届け|届出|通知)[^。]{0,6}(要る|いる|必要|連絡)|危な(い|く)?[^。]{0,4}仕事に(就|変わ|つ)いたら[^。]{0,6}保険/, ng:/部下|後輩|新人|募集人の|自分の仕事|私の仕事|営業の仕事/, head:"届け出が要るかは保険の種類で違い、傷害保険などは職業が変わったら知らせる決まりが多いです。", body:"生命保険では、契約のあとで職業が変わっても、届け出を求めない商品が多くあります。一方、傷害保険など損害保険の一部では、職業や職種が変わったときに保険会社へ知らせる決まりがあり、知らせないと保険金が減らされたり、支払われなかったりすることがあります。勤め先の団体保険は、転職でやめることになるのが一般的です。", acts:["転職を聞いたら、生命保険と損害保険の契約を並べ、届け出が要るものを保険会社に確かめる", "勤め先の団体保険に入っていたら、転職で切れる保障が無いかを一緒に確かめる", "届け出が要る契約は、職業が変わった時点でお客様から保険会社へ知らせていただく"], actHead:"現場で使うなら", note:"職業の変更を知らせる決まりがあるか・知らせないときの扱いは、商品と約款で違う。保険会社の約款と窓口で確かめる。", pre:1, say:"お仕事が変わったら、ご契約によっては保険会社へのお知らせが要るものがあります。一つずつ確かめますね。", more:"見落としやすいのは、職業によって保険料が変わる傷害保険や所得補償保険です。事務の仕事から現場の仕事に移った、自営業になった、といった変化は届け出の対象になりやすいので、転職の話が出たら契約を並べて確かめます。勤め先の団体保険を、辞めたあとも続けられる制度がある会社もあります。", why:"傷害保険などは、仕事によってけがの起きやすさが違うので、職業や職種で保険料を決めています。変わったのに知らせないと、払っている保険料と引き受けている危険がずれるため、知らせる決まりになっています。" },
      { key:'faq_xtet_kakunin', faq:1, grp:'tet', q:"保険会社から契約の確認の電話が来るとお客様に言われた", re:/契約(の)?確認[^。]{0,10}(電話|訪問|担当|連絡|来る|来た|とは)|(保険会社|生命保険会社)(から|の)[^。]{0,8}(確認の(電話|担当|訪問|連絡)|電話で内容を)|確認の担当者が来/, ng:/契約確認書|契約の確認書|自動車|事故/, head:"契約の確認は、保険会社が申込みの内容とご本人の意思を確かめるもので、普通の手続きです。", body:"保険会社は、申込みのあとや契約のあとに、電話や訪問で、契約者や被保険者ご本人に、申込みの内容・告知・ご意向などを確かめることがあります。募集が正しく行われたか、なりすましや告知の誤りが無いかを確かめる目的で、どの契約に行うかは保険会社が決めます。答えるのはご本人で、募集人が代わりに答えることはしません。", acts:["確認があり得ることを、申込みのときに先にお伝えしておく", "ありのままに答えていただければよい、とだけ伝え、答え方をこちらから指示しない", "電話の相手が本当に保険会社か不安な方には、証券や案内にある保険会社の番号で確かめていただく"], actHead:"現場で使うなら", note:"確認を行う契約・方法・担当は保険会社で違う。所属保険会社の手引きと窓口で確かめる。", pre:1, say:"お申し込みの内容を、保険会社がご本人に直接確かめる連絡が入ることがあります。普通のお手続きなので、ありのままにお答えください。", more:"よくあるのは、知らない番号からの電話を詐欺と思われて出られない場面です。前もって伝えておくと、お客様も安心して答えられます。確認の中で、聞いていた話と違う、という声が出たときは、保険会社から募集人に問い合わせが来ることもあるので、説明した内容の記録を残しておきます。", why:"募集人が説明した内容と、お客様の受け取った内容がずれていないかを、募集人とは別の人が確かめることで、契約の正しさを守るためです。不正な契約や告知の誤りを早く見つける役目もあります。" },
      { key:'faq_xtet_yuigon', faq:1, grp:'tet', q:"遺言で保険金の受取人を変えられる？", re:/遺言[^。]{0,12}受取人|受取人[^。]{0,12}遺言/, head:"遺言で受取人を変える道はありますが、保険会社への通知と、契約ごとの確かめが要ります。", body:"保険法では、遺言によって保険金の受取人を変えられることが定められていて、相続人が保険会社に知らせるまでは、保険会社に対して変更を主張できない決まりです。遺言の書き方に不備があったり、契約の時期によって扱いが違ったりすることもあります。確実に変えたいなら、ご存命のうちに保険会社で受取人の変更の手続きをする道もあります。", acts:["遺言の話が出たら、まず保険会社で受取人の変更の手続きができるかを一緒に確かめる", "遺言の書き方や効力の判断はこちらでせず、弁護士や公証役場をご案内する", "被保険者が契約者と違う契約では、被保険者の同意が要るかを保険会社に確かめる"], actHead:"現場で使うなら", note:"遺言による変更の扱い・通知の方法・要る書類は、契約の時期と約款で違う。保険会社の窓口で手続きを、遺言の効力など法律上の判断は弁護士で確かめる。", pre:1, say:"遺言で受取人を変える方法もありますが、手続きが複雑になりやすいです。お元気なうちに保険会社で変更のお手続きをしておくと、ご家族が迷わずに済みます。", more:"よくある行き違いは、遺言には新しい受取人が書いてあるのに、保険会社に知らせる前に前の受取人へ支払われてしまう場面です。また、遺言の中で保険金を財産の一つとして分けるように書いても、それが受取人の変更として扱われるかは書き方によります。迷うときは、遺言を作る段階で弁護士に相談していただきます。", why:"保険金の受取人を決めるのは契約者の意思なので、遺言でもその意思を示せるように法律が定めています。ただ、保険会社は遺言の中身を知らないので、知らせを受けて初めて変更に従える、という決まりになっています。" },
      { key:'faq_xtet_uketoridoui', faq:1, grp:'tet', q:"受取人を変えるのに被保険者の同意は要る？", re:/受取人[^。]{0,12}(変え|変更|替え)[^。]{0,12}(同意|了承|内緒|黙って|誰の)|(同意|了承)[^。]{0,8}受取人[^。]{0,6}(変え|変更)|被保険者[^。]{0,8}(内緒|黙って|知らせず)[^。]{0,8}受取人|契約者と被保険者が違う[^。]{0,10}受取人/, ng:/遺言/, head:"死亡保険金の受取人を変えるときは、契約者と被保険者が違えば、被保険者の同意が要ります。", body:"死亡保険金が支払われる契約で、契約者と被保険者が別の人の場合、受取人を変えるには被保険者の同意が要ると法律で決まっています。被保険者ご本人が知らないまま受取人を変えることはできません。契約者と被保険者が同じ人なら、契約者の手続きで変えられるのが一般的です。", acts:["証券で、契約者と被保険者が同じ人かを先に確かめる", "違うときは、被保険者ご本人に保険会社所定の書類で同意していただく", "被保険者に知らせたくないという相談は、手続きを進めず、同意が要る決まりをそのまま伝える"], actHead:"現場で使うなら", note:"同意の取り方・要る書類は保険会社で違う。保険会社の窓口と約款で確かめる。法律上の判断が要るときは弁護士。", pre:1, say:"ご契約者と保険の対象の方が違うご契約では、受取人を変えるときに、対象の方ご本人の同意が要る決まりです。お二人で書類をご用意いただきます。", more:"迷いやすいのは、妻が契約者・夫が被保険者の契約で、離婚や再婚を機に受取人を変える場面です。被保険者の同意が要るので、関係がこじれていると手続きが進まないことがあります。同意を得られないまま、ほかの人が代わりに署名することは決してしません。", why:"自分の命に保険金が掛かっていて、その受け取り手が誰かは、被保険者ご本人の安全に関わることだからです。知らないうちに受取人が変わると、保険金を目当てにした事件を招くおそれがあるため、法律で同意を求めています。" },
      { key:'faq_xtet_uketorifukusu', faq:1, grp:'tet', q:"受取人を2人以上にできる？", re:/受取人[^。]{0,8}(複数|[0-9二三]人|ふたり|分けて|分けた|割合)|(割合|分け)[^。]{0,8}受取人|保険金を[^。]{0,8}(兄弟|子ども|子供|二人)で分けて受け取/, ng:/遺言|法人|会社|税/, head:"受取人を複数にして、受け取る割合を決められる商品が多くあります。", body:"死亡保険金の受取人は、一人だけでなく複数の方を指定し、それぞれの割合を決められる商品が多くあります。割合を決めないと、等しく分けるなど約款の決まりで扱われるのが一般的です。複数の受取人がいると、それぞれの方が請求の書類をそろえる必要があることがあります。", acts:["分けたい理由を伺い、受取人を分けるか、契約を分けるかを一緒に考える", "割合の決め方と、請求のときの手続きを保険会社に確かめてから説明する", "受取人の誰かが先に亡くなったときの扱いも、約款で一緒に確かめる"], actHead:"現場で使うなら", note:"指定できる人数・割合の決め方・請求の手続きは保険会社と商品で違う。保険会社の約款と窓口で確かめる。相続の分け方の判断は弁護士、税は税理士。", pre:1, say:"受取人をお二人にして、受け取る割合を決めておくこともできます。請求のときの手続きも含めて、確かめてからご案内します。", more:"よくある場面は、子どもたちに等しく残したい、という相談です。受取人を複数にする形と、契約を分けて受取人を一人ずつにする形を並べて考えます。誰に、どんな理由で、どれだけ残したいかを先に伺うと、形を選びやすくなります。受取人の一人が先に亡くなったときの扱いも、あわせて確かめます。", why:"保険金は受取人が自分の権利として受け取るものなので、契約者が誰にどれだけ渡したいかを、受取人と割合で前もって決めておける仕組みになっているからです。" },
      { key:'faq_xtet_dairihenko', faq:1, grp:'tet', q:"指定代理請求人を変えたいと言われた", re:/指定代理請求人[^。]{0,10}(変え|変更|替え|亡くな|死亡|離婚|いなくな)|(離婚|亡くな)[^。]{0,10}指定代理請求人/, head:"指定代理請求人は、契約者が被保険者の同意を得て、保険会社の手続きで変えられるのが一般的です。", body:"指定代理請求人は、被保険者ご本人が請求できないときに代わって請求する方で、なれる人の範囲は保険会社が決めています。離婚やご家族の事情で今の方がふさわしくなくなったとき、亡くなったときは、指定し直しておかないと、いざというときに代わりに請求できる方がいなくなることがあります。", acts:["証券や契約内容のお知らせで、今の指定代理請求人が誰かを一緒に確かめる", "新しく指定したい方が範囲に入るかと、要る書類を保険会社に確かめる", "受取人の見直しも、同じ機会に一緒にお伺いする"], actHead:"現場で使うなら", note:"指定できる人の範囲・被保険者の同意の取り方・要る書類は保険会社で違う。保険会社の窓口と約款で確かめる。", pre:1, say:"代わりに請求していただく方は、ご事情に合わせて変えられます。今どなたになっているかを一緒に確かめて、お手続きをご案内します。", more:"見落としやすいのは、受取人は変えたのに、指定代理請求人は前の配偶者のまま、という契約です。離婚や死別のあとは、受取人と指定代理請求人を同じ機会に並べて見直します。指定代理請求人には、手続きのことを前もって知らせておいていただくと、いざというときに迷われません。", why:"指定代理請求人は、ご本人が病名を知らされていない、意思を伝えられないといった場面に備えて、信頼できる方をあらかじめ決めておく仕組みだからです。ご家族の関係が変われば、決めておく方も変える必要があります。" },
      { key:'faq_xtet_kazokutouroku', faq:1, grp:'tet', q:"保険会社の家族登録の制度とは？", re:/家族(登録|の登録)|家族を(保険会社に)?登録|(家族|親族)の連絡先[^。]{0,10}(登録|届け|届出)|(登録|届け)[^。]{0,8}(家族|親族)の連絡先/, head:"家族登録は、契約者と連絡がつかないときに、保険会社が登録のご家族へ連絡できる仕組みです。", body:"保険会社によっては、契約者のご家族をあらかじめ登録しておき、契約者と連絡が取れないときや、手続きの案内が要るときに、そのご家族へ連絡したり、契約の一部を案内したりできるようにしています。登録できる方の範囲と、ご家族に伝える内容は保険会社が決めています。ご高齢のお客様の契約で、請求漏れや手続きの行き違いを減らすことに役立ちます。", acts:["所属保険会社に家族登録の制度があるか、登録できる方の範囲を確かめる", "契約者ご本人の同意を得てから、登録の書類を案内する", "ご家族に何が伝わるかを、登録の前にご本人に説明する"], actHead:"現場で使うなら", note:"制度の有無・登録できる方・伝える内容・指定代理請求人との違いは保険会社で違う。保険会社の窓口と案内書で確かめる。", pre:1, say:"ご家族を一人登録しておくと、ご本人と連絡がつかないときに、保険会社からご家族へご連絡できます。ご希望があればお手続きをご案内します。", more:"迷いやすいのは、指定代理請求人や受取人との違いです。家族登録は連絡や案内のための登録で、それだけで代わりに請求したり、契約を変えたりできるものではないのが一般的です。お一人暮らしのご高齢のお客様には、受取人と指定代理請求人の見直しと一緒に案内すると、話が伝わりやすくなります。", why:"契約者が引っ越しや入院で連絡を受けられないと、大事な手続きの案内が届かず、請求の漏れや失効につながるからです。連絡の道を二つ持っておくことで、契約を守りやすくする仕組みです。" },
      { key:'faq_xtet_houjinhenko', faq:1, grp:'tet', q:"法人契約で会社名や代表者が変わったら？", re:/(社名|会社名|商号|法人名|代表者|代表取締役|本店|所在地)[^。]{0,6}(が|を)?(変わ|変更|交代|移し|移転)[^。]{0,16}(保険|契約|手続|届)|(契約している|保険の|契約者の)(会社|法人)の(社名|会社名|代表者|本店|所在地)[^。]{0,6}(が|を)?(変わ|変更|交代|移)|(法人|会社)(の|で)?契約[^。]{0,10}(社名|会社名|代表者)[^。]{0,6}(が|を)?(変わ|変更|交代)/, ng:/(社名|名前|会社名)が変わった保険会社|保険会社(の|が)(社名|名前)|合併|代理店/, head:"社名・代表者・所在地が変わったら、保険会社所定の届け出をして、契約の記録を今の情報に合わせます。", body:"法人が契約者の保険では、社名や本店の所在地、代表者が変わったときに、登記の写しなどを添えて保険会社に届け出るのが一般的です。代表者が変わっても、被保険者や受取人は自動では変わりません。前の社長が被保険者の契約をどう扱うかは、会社の方針と規程に沿って決めることです。", acts:["変わった内容と時期を伺い、保険会社に要る書類（登記の写しなど）を確かめる", "法人の契約を一覧にして、被保険者・受取人・保険料を払う口座も今のままでよいかを見る", "退任した役員が被保険者の契約は、扱いを顧問の税理士と相談していただく"], actHead:"現場で使うなら", note:"届け出の書類と手続きは保険会社で違う。保険会社の窓口で確かめる。退任した役員の契約の扱いや経理は顧問の税理士、規程は会社の決まりで確かめる。", pre:1, say:"社名や代表者が変わったときは、保険会社への届け出が要ります。ほかのご契約もまとめて今の情報に合わせますので、一覧にして確かめましょう。", more:"見落としやすいのは、保険料を引き落とす口座の名義も変わっている場面です。口座の名義が変わると引き落としが止まることがあるので、口座の手続きも一緒に確かめます。代表者の交代は、事業承継や退職金の準備の話につながることが多く、契約の役目を見直す機会にもなります。", why:"保険会社は、契約者が誰かを登録された情報で確かめて手続きや案内をするので、情報が古いままだと、案内が届かなかったり、手続きのときに本人の確かめができなかったりするからです。" },
      { key:'faq_xtet_shokenayamari', faq:1, grp:'tet', q:"証券の名前や生年月日が間違っていたら？", re:/(証券|保険証券|契約内容のお知らせ)[^。]{0,12}(間違|誤り|誤記|違って|違う|ちが)|(名前|氏名|漢字|生年月日|性別)[^。]{0,8}(間違|誤り|違って|違う)[^。]{0,8}(証券|保険)/, ng:/証券会社|証券口座|有価証券|株|投資信託|なくし|無くし|紛失|見方|読み方|何が違|どう違|違いは/, head:"記載の誤りは保険会社に申し出て直してもらい、生年月日の誤りは保険料に関わります。", body:"名前の漢字や住所の誤りは、保険会社に申し出て正しい内容に直してもらいます。生年月日や性別の誤りは、保険料の計算に関わるので、約款の決まりに沿って、保険料の差を精算したり、契約の扱いを決め直したりするのが一般的です。誤りが申込書の書き方によるものか、保険会社の登録によるものかで、要る書類が違うことがあります。", acts:["申込書の控えと証券を並べ、どこで違っているかを確かめる", "保険会社の窓口に申し出て、直す手続きと要る書類を確かめる", "生年月日の誤りは、保険料がどう変わるかを保険会社に出してもらってからお伝えする"], actHead:"現場で使うなら", note:"直す手続き・保険料の精算の仕方・契約の扱いは、約款と保険会社で違う。保険会社の窓口と約款で確かめる。", pre:1, say:"お知らせくださってありがとうございます。正しい内容に直す手続きをご案内します。生年月日の違いは保険料に関わるので、保険会社に確かめてからご説明します。", more:"見落としやすいのは、旧字体の漢字が新字体で登録されているような違いです。請求のときに本人確認の書類と名前が合わないと、手続きに時間がかかることがあるので、気づいた時点で直しておきます。申込みの段階で名前と生年月日を本人確認の書類で照らしておくと、こうした誤りを防げます。", why:"証券の記載は、請求や手続きのときに本人を確かめる基になるからです。生年月日は保険料を計算する年齢の基なので、違っていると、払う保険料と引き受けている保障がずれてしまいます。" },
      { key:'faq_xtet_dantaitaishoku', faq:1, grp:'tet', q:"退職したら団体扱いの保険はどうなる？", re:/(退職|辞め|やめ|転職|退社|離職)[^。]{0,16}(団体扱い|(給与|給料)(天引き|引き去り))|(団体扱い|(給与|給料)(天引き|引き去り))[^。]{0,20}(退職|辞め|やめ|転職|退社|離職|個人の払込|口座振替に)|団体扱いから/, ng:/団体保険|団体信用|団信|社会保険|厚生年金|健康保険|住民税/, head:"勤め先を通した払込（団体扱い）は退職で終わるので、口座振替などの払込方法に変える手続きをします。", body:"団体扱いは、保険料を給料から引いて勤め先がまとめて払う払込の方法で、契約そのものは個人の契約です。退職すると団体扱いが使えなくなり、口座振替などに切り替える手続きが要ります。団体扱いで保険料が抑えられていた契約は、切り替えのあと保険料が変わることがあります。勤め先が契約者の団体保険とは別のものです。", acts:["退職の時期を伺い、団体扱いの契約が無いかを証券で一緒に確かめる", "切り替え先の払込方法と、切り替えまでの保険料の払い方を保険会社に確かめる", "勤め先の団体保険に入っていたら、退職で切れる保障を別に確かめる"], actHead:"現場で使うなら", note:"団体扱いの終わり方・切り替えの手続き・保険料の変わり方は、保険会社と勤め先の取り決めで違う。保険会社の窓口と勤め先の担当部署で確かめる。", pre:1, say:"お給料から引かれていた保険料は、退職されると引けなくなります。口座振替などへの切り替えのお手続きを一緒に進めましょう。", more:"見落としやすいのは、最後のお給料のあと、切り替えが済むまでの間の保険料です。払われないまま猶予期間を過ぎると失効することがあるので、退職の話を伺ったら切り替えを早めに確かめます。勤め先の団体保険を、退職後も個人で続けられる制度がある会社もあるので、勤め先の案内も見ていただきます。", why:"団体扱いは、勤め先と保険会社の取り決めで保険料を集める仕組みなので、勤め先を離れると、その取り決めの外になるからです。契約は個人のものなので、払込の方法だけを変えれば続けられます。" },
      { key:'faq_xtet_meiginin', faq:1, grp:'tet', q:"保険料を引き落とす口座の名義人が亡くなったら？", re:/(口座|名義人)[^。]{0,10}(亡くな|死亡|凍結)|(亡くなった|死亡した)[^。]{0,8}口座[^。]{0,10}(保険料|引き?落)/, ng:/受取人|保険金|給付金|請求/, head:"名義人が亡くなった口座は使えなくなるので、払込の口座を変える手続きを早めにします。", body:"金融機関は、口座の名義人が亡くなったことを知ると、その口座の出し入れを止めるのが一般的で、保険料の引き落としもできなくなります。そのままにすると、払込の猶予期間を過ぎて契約が失効することがあります。契約者が別にいるなら、契約者の口座などに払込の方法を変える手続きをします。", acts:["名義人が亡くなった口座から引き落としている契約が無いかを、証券と契約内容のお知らせで並べる", "新しい口座の手続きと、それまでの保険料の払い方を保険会社に確かめる", "契約者も同じ方なら、契約者の変更や請求の手続きを先に確かめる"], actHead:"現場で使うなら", note:"口座の扱いは金融機関、払込方法の変更と猶予の扱いは保険会社で違う。保険会社の窓口と金融機関で確かめる。", pre:1, say:"お亡くなりになった方の口座は、保険料の引き落としに使えなくなります。ご契約が途切れないよう、別の口座へのお手続きを一緒に進めましょう。", more:"よくあるのは、契約者は息子さんなのに、保険料はお父様の口座から引き落としていた、という契約です。ご葬儀のあとの手続きが重なる時期なので、保険料のことは後回しになりがちです。ご家族から連絡をいただいたら、引き落とし口座の名義もあわせて確かめます。", why:"口座の名義人が亡くなると、その預金は相続の手続きの対象になり、勝手に引き出されないよう金融機関が出し入れを止めるからです。" },
      { key:'faq_xtet_yuuyojiko', faq:1, grp:'tet', q:"払込の猶予期間中に亡くなったら保険金は出る？", re:/猶予期間[^。]{0,8}(中|の間|のうち)[^。]{0,10}(亡くな|死亡|入院|事故|手術|請求|出る|支払)|(未払い|未納|払えていな|払っていな|引き落としができていな)[^。]{0,8}(事故|亡くな|入院|請求)/, ng:/国民年金|年金保険料|国民健康保険|国保|税金|自動車|車/, head:"猶予期間の間に起きたことは保障されるのが一般的で、払われていない保険料は差し引かれます。", body:"保険料の払込が遅れても、決められた猶予期間の間は契約が続いているので、その間に亡くなったり入院したりしたときは、保険金や給付金の対象になるのが一般的です。そのとき、まだ払われていない保険料は、支払われる額から差し引かれるか、払い込みを求められます。猶予期間を過ぎて失効したあとの出来事は、保障されません。", acts:["請求の連絡が来たら、払込の状況と猶予期間の終わりを保険会社に確かめる", "未払いの保険料の扱いを保険会社に確かめてから、ご家族にお伝えする", "払込が止まっている契約を見つけたら、猶予期間のうちにお客様へ連絡する"], actHead:"現場で使うなら", note:"猶予期間の長さ・差し引き方・失効の時期は、払い方と約款で違う。保険会社の窓口と約款で確かめる。", pre:1, say:"保険料の払込が遅れていても、猶予の期間の間なら、ご契約は続いています。払われていない保険料の扱いも含めて、保険会社に確かめます。", more:"よくある勘違いは、一度でも引き落としができないと、すぐ保障が無くなると思われることです。猶予期間の間は続いていますが、期間は払い方によって違うので、案内が届いたら早めに払っていただきます。自動振替貸付が付いている契約では、猶予期間を過ぎても、貸付で保険料が払われて続くことがあります。", why:"引き落としの行き違いなど、うっかりした遅れで保障を失わないよう、払込に猶予を設けているからです。猶予期間は契約が生きている期間なので、その間の出来事は保障の対象になります。" },
      { key:'faq_xtet_shikkoukaiyaku', faq:1, grp:'tet', q:"失効と解約は何が違う？", re:/失効[^。]{0,6}解約[^。]{0,8}(違|同じ|区別)|解約[^。]{0,6}失効[^。]{0,8}(違|同じ|区別)|失効(したら|すると)[^。]{0,6}解約(と同じ|扱い)|解約しなくても[^。]{0,8}(なくな|無くな|消え|切れ)/, head:"解約は契約者が申し出て契約を終えること、失効は保険料が払われずに契約の効力がなくなることです。", body:"解約は、契約者の申し出で契約を終わらせる手続きで、解約返戻金があれば受け取れます。失効は、保険料が払われないまま猶予期間を過ぎ、自動振替貸付などでも払えなかったときに、契約の効力がなくなることです。失効した契約は、決められた期間のうちなら復活できる商品がありますが、解約した契約は元に戻せません。", acts:["払込が止まっている契約は、失効の前に払込の方法や払済などの道を一緒に確かめる", "失効した契約は、復活ができる期間と要る手続きを保険会社に確かめる", "解約はやり直しがきかないことを、手続きの前に必ずお伝えする"], actHead:"現場で使うなら", note:"失効の時期・復活できる期間と条件・失効した契約の解約返戻金の扱いは、約款で違う。保険会社の約款と窓口で確かめる。", pre:1, say:"解約はご自身でご契約を終えるお手続き、失効は保険料が払われないままご契約の効力が止まることです。失効なら元に戻せる道が残っていることがあります。", more:"よくある勘違いは、払込をやめれば解約になると思われることです。払わないまま放っておくと失効になり、解約返戻金があっても、請求しないと受け取れないことがあります。保険料が払えないときは、放っておかずに、減額・払済・貸付などの道と並べて決めていただきます。", why:"失効は、保険料という約束の払いが続かなかったことで、契約が効力を失う仕組みです。契約者が自ら終わらせる解約と違い、意思に反して保障が切れることがあるので、復活という戻り道が用意されている商品があります。" },
      { key:'faq_xtet_fukkatsushinki', faq:1, grp:'tet', q:"失効した契約は、復活と入り直しのどちらがいい？", re:/復活[^。]{0,10}(新しく|新規|入り直|契約し直|加入し直)|(新しく|新規|入り直|契約し直|加入し直)[^。]{0,10}復活/, head:"復活はもとの契約の条件に戻すこと、入り直しは今の年齢と商品で新しく契約することです。", body:"復活は、失効した契約を、もとの保障の内容と保険料のまま戻す手続きで、告知や診査を受け、失効していた間の保険料を払い込むのが一般的です。入り直しは、今の年齢と今ある商品で新しく契約するので、保険料も保障の中身も変わります。どちらも健康状態によっては引き受けられないことがあり、どちらが合うかはご事情で違います。", acts:["失効した契約の証券を見て、もとの保障の内容と保険料を確かめる", "復活できる期間と、払い込む額を保険会社に出してもらう", "今の商品で入り直したときの保障と保険料を並べ、決めるのはお客様と伝える"], actHead:"現場で使うなら", note:"復活できる期間・払い込む額・告知の扱いは約款と保険会社で違う。保険会社の約款と窓口で確かめる。", pre:1, say:"もとのご契約に戻す方法と、今の商品で入り直す方法があります。保障の中身とご負担を並べてお見せしますので、それを見てお決めください。", more:"よくある迷いは、もとの契約のほうが保険料が安いから復活一択、と考えることです。もとの契約の予定利率や保障の中身が今の暮らしに合っているか、失効していた間の保険料をまとめて払えるか、も一緒に見ます。お体の状態によっては、どちらも難しいことがあるので、先に保険会社へ確かめます。", why:"復活は、もとの約束をそのまま生かす道で、入り直しは今の条件で約束をし直す道だからです。保険料は契約したときの年齢と条件で決まるので、どちらを選ぶかで負担と保障が変わります。" },
      { key:'faq_xtet_shikkoumama', faq:1, grp:'tet', q:"失効したままの契約は、どうなっている？", re:/失効(した|して)(まま|いる契約|保険)[^。]{0,12}(放|どう|ある|見つ|残|そのまま)|失効した[^。]{0,8}(解約返戻金|返戻金|お金)|(昔|前に|以前)[^。]{0,4}失効した[^。]{0,6}(契約|保険)/, head:"失効した契約でも、解約返戻金があれば、請求しないと受け取れないことがあります。", body:"失効した契約は、保障は止まっていますが、復活できる期間のうちなら戻せることがあります。積み立てた部分がある契約では、解約返戻金にあたるお金を、契約者が請求して受け取る形になるのが一般的です。放っておくと受け取れるお金に気づかないまま、ということが起こるので、見つけた時点で保険会社に確かめます。", acts:["証券番号と契約者のお名前で、保険会社に今の状態を問い合わせていただく", "復活できるか・受け取れるお金があるかを、両方とも確かめる", "受け取る手続きは、契約者ご本人から保険会社に申し出ていただく"], actHead:"現場で使うなら", note:"失効したあとの扱い・受け取れるお金・請求の期限は約款と保険会社で違う。保険会社の窓口と約款で確かめる。", pre:1, say:"保障は止まっていますが、受け取れるお金が残っていることがあります。保険会社に今の状態を一緒に確かめましょう。", more:"見つかりやすいのは、引っ越しや口座の変更をきっかけに払込が止まり、そのままになっていた契約です。保険会社からの通知が古い住所に届いていて、気づかなかったという方も少なくありません。受け取りの権利にも期限があることがあるので、見つけたら早めに確かめていただきます。", why:"失効しても、それまでに積み立てた部分は契約者のお金として残っていることがあるからです。ただ、保険会社は契約者の申し出を受けて手続きをするので、請求しないまま残ってしまうことがあります。" },
      { key:'faq_xtet_manryou', faq:1, grp:'tet', q:"保険料の払込が満了したら、保障はどうなる？", re:/(払込|払い込み|払込み|保険料の払い)(期間)?(が)?(満了|終わ|終了)[^。]{0,16}(保障|保険料|どうなる|続|通知|案内|手続)|払込満了/, ng:/国民年金|年金保険料|厚生年金|iDeCo|イデコ|ideco|nisa|ニーサ|ローン|定期付|定期保険特約|減る|なぜ/, head:"払込が満了しても保障は続く契約が多く、そのあとの保険料は払わなくなります。", body:"保険料を払う期間が、保障の期間より短い契約では、払込が満了したあとも、決められた保障の期間が終わるまで保障が続きます。そのあとは保険料を払いません。ただし、特約によっては払込の満了と同じ時期に保障が終わるものや、更新して保険料を払い続けるものがあります。満了の前後で、どの保障がいつまで続くかを確かめておきます。", acts:["証券で、主契約と特約ごとに、払込の期間と保障の期間を並べる", "満了と同じ時期に終わる特約が無いかを、保険会社の案内で確かめる", "口座からの引き落としが止まるかを、案内が届いたら一緒に確かめる"], actHead:"現場で使うなら", note:"特約の扱い・満了後の手続き・引き落としの止まり方は契約と保険会社で違う。保険会社の約款と案内で確かめる。", pre:1, say:"保険料のお払込みが終わっても、保障はこのまま続くご契約です。ただ、特約の中には同じ時期に終わるものがあるので、一つずつ確かめましょう。", more:"勘違いが多いのは、払込が終わったら保障も終わる、と思われることです。反対に、主契約は続くのに、医療の特約は払込の満了で終わってしまい、入院の保障が無くなっていた、ということもあります。満了の案内は、保障を並べて見直すきっかけにもなります。", why:"払込の期間を短くした契約は、働いて収入があるうちに保険料を払い終え、そのあとは保険料なしで保障を持てるように作られているからです。特約は主契約と別の約束なので、終わる時期が違うことがあります。" },
      { key:'faq_xtet_zougaku', faq:1, grp:'tet', q:"保障の額を増やしたいと言われたら？", re:/増額|(保険金額|保険金の額|死亡保障|保障額|保障の額)[^。]{0,6}(を)?(増や|上げ|多くし|大きくし)/, ng:/年金|給料|給与|賞与|保険料が(上が|増え)|保険料の増額|手数料|とは|って何|ってなに|の意味|意味を/, head:"今の契約に上乗せできる商品と、できない商品があり、どちらも告知が要るのが一般的です。", body:"保障を増やすには、今の契約の保険金額を増やす方法と、別の契約を新しく足す方法があります。今の契約に上乗せできるかは商品によって違い、できる場合も、増やす部分は告知や診査を受けて、今の年齢で保険料を計算し直すのが一般的です。お体の状態によっては、増やせないことがあります。", acts:["なぜ増やしたいかを伺い、必要な額を一緒に考えてから方法を選ぶ", "今の契約に上乗せできるかと、要る告知を保険会社に確かめる", "上乗せと別の契約を足す形を、保険料と保障で並べてお見せする"], actHead:"現場で使うなら", note:"上乗せできるか・告知と診査の要否・保険料の計算は商品と保険会社で違う。保険会社の窓口と約款で確かめる。", pre:1, say:"保障を増やす方法は、今のご契約に上乗せする形と、別のご契約を足す形があります。どちらができるかを確かめて、並べてご説明します。", more:"増やしたいという声が出るのは、お子さんが生まれた、家を買った、事業を始めた、といった暮らしの変化のときです。まず何のためにいくら要るかを確かめると、増やす額も、増やす期間も決めやすくなります。いずれ減らす前提なら、期間を区切った保障を足すほうが合うこともあります。", why:"保障を増やすことは、保険会社が引き受ける危険が大きくなることなので、増やす部分は新しく引き受けるのと同じように、健康状態と今の年齢で判断し直すからです。" },
      { key:'faq_xtet_koushinshinai', faq:1, grp:'tet', q:"更新しないで終わらせたいと言われたら？", re:/更新(しない|せず|させない|を止め|をとめ|を断|を希望しな|しないで)|自動更新を(止|や|と)/, ng:/資格|免許|登録|賃貸|契約書|サブスク|携帯|会員|車検|自動車|火災/, head:"更新しないときは、更新の時期より前に、保険会社所定の方法で申し出るのが一般的です。", body:"自動で更新される保険や特約は、何も申し出なければ更新され、新しい保険料で続きます。更新しないで終わらせたいときは、更新の時期より前に、保険会社所定の書類や方法で申し出ます。申し出の期限は、更新の案内に書かれているのが一般的です。更新しないと、その時期で保障が終わります。", acts:["終わらせる理由を伺い、保障を減らして更新する道があるかも一緒に確かめる", "更新の案内で、申し出の期限と方法を確かめる", "終わったあとに要る備えが残っていないかを、ほかの契約と並べて見る"], actHead:"現場で使うなら", note:"申し出の期限・方法・保障を減らして更新できるかは、商品と保険会社で違う。保険会社の更新の案内と窓口で確かめる。", pre:1, say:"更新しない場合は、更新の時期より前のお申し出が要ります。期限は案内に書かれていますので、一緒に確かめましょう。", more:"よくあるのは、保険料が上がるので終わらせたい、という相談です。終わらせる前に、保障の額を減らして更新する、必要な期間だけ別の形で備える、といった道を並べます。更新しないと決めた場合も、そのあとで同じ保障を持とうとすると、年齢と健康状態で難しくなることがあると伝えます。", why:"自動更新は、手続きを忘れて保障が切れないよう、申し出が無ければ続く形にしてあるからです。終わらせたいときに申し出が要るのは、その反対の意思を保険会社に示す必要があるためです。" },
      { key:'faq_xtet_fukkyu', faq:1, grp:'tet', q:"払済保険や延長保険から、もとの契約に戻せる？", re:/(払済|払い済み|延長保険|延長定期)[^。]{0,14}(もとに戻|元に戻|復旧|戻せ|戻し)|復旧/, ng:/災害|地震|システム|データ|道路|工事|電気|水道|ガス/, head:"決められた期間のうちなら、告知と差額の払込みを条件に、もとの契約に戻せる商品があります。", body:"払済保険や延長保険に変えたあと、保険会社が決めた期間のうちなら、もとの保障の内容に戻すことを受け付ける商品があり、これを復旧と呼びます。戻すときは、告知や診査を受け、もとの契約との差にあたるお金を払い込むのが一般的です。復旧を受け付けない商品や、お体の状態で戻せないこともあります。", acts:["払済や延長に変えた時期と、もとの契約の内容を証券で確かめる", "復旧できる期間と払い込む額を、保険会社に出してもらう", "戻すか、今のまま続けるか、新しく備えるかを並べて決めていただく"], actHead:"現場で使うなら", note:"復旧の可否・期間・払い込む額・告知の扱いは、商品と保険会社で違う。保険会社の約款と窓口で確かめる。", pre:1, say:"決められた期間のうちなら、もとのご契約に戻せることがあります。戻すときのご負担を保険会社に出してもらいますので、それを見てお決めください。", more:"戻したいという声が出るのは、払済にしたあと収入が戻った、保障が足りないと気づいた、という場面です。戻すときの払い込みは、まとめて払うことになることが多いので、額を見てから決めていただきます。払済にする前に、戻せる道があるかを先に確かめておくと、あとで迷われません。", why:"払済や延長は、保険料を払えなくなったときに保障を形を変えて残す仕組みなので、事情が戻ったときに、もとの約束へ戻る道を用意している商品があるからです。" },
      { key:'faq_xtet_haitouhikidashi', faq:1, grp:'tet', q:"積み立てた配当金を引き出したいと言われた", re:/配当金[^。]{0,10}(引き出|引出|受け取りたい|下ろ|おろ|払い出|請求)|(積立|据え?置)[^。]{0,4}配当[^。]{0,10}(引き出|引出|受け取|下ろ|おろ)/, ng:/株|投資信託|分配金|nisa|ニーサ|会社の配当|役員|法人/, head:"据え置いた配当金は、契約者の請求で引き出せる商品が多く、引き出すと満期などで受け取る額が減ります。", body:"保険の配当金を保険会社に据え置いて積み立てている場合、契約者が請求すれば、契約を続けたまま引き出せる商品が多くあります。引き出した分は、満期や死亡のときに上乗せされる額から減ります。引き出せるかと方法は、保険会社と商品で違い、受け取ったお金の税の扱いも、受け取り方で変わることがあります。", acts:["証券や契約内容のお知らせで、積み立てている配当金の額を確かめる", "引き出せるかと要る書類を保険会社に確かめ、契約者ご本人から請求していただく", "税の扱いは、顧問の税理士か税務署で確かめていただくようお伝えする"], actHead:"現場で使うなら", note:"引き出せるか・方法・額は商品と保険会社で違い、配当金の額は約束されたものではない。保険会社の窓口で、税の扱いは税理士で確かめる。", pre:1, say:"積み立てている配当金は、ご契約を続けたまま引き出せることがあります。保険会社で額と手続きを確かめてご案内します。", more:"よくある勘違いは、配当金は毎年必ず出るもの、と思われることです。配当金は運用や運営の結果によるもので、出ない年や額が変わる年があります。引き出す前に、引き出したあとの満期の受け取りがどうなるかを並べてお見せすると、決めやすくなります。", why:"配当金は契約者に分配されたお金なので、据え置いている間も契約者のものとして扱われるからです。引き出せば、その分だけ保険会社に預けている額が減るので、あとで受け取る額も減ります。" },
      { key:'faq_xtet_kaiyakunagare', faq:1, grp:'tet', q:"解約の手続きはどう進める？", re:/解約に(要る|いる|必要な)(書類|もの)|解約(の|する)?(手続き|手続|流れ|書類|請求書|進め方|やり方|方法)|解約[^。]{0,6}(書類|請求書)[^。]{0,8}(取り寄せ|要る|いる|必要|何)/, ng:/誰|取り下げ|取下げ|取り消|取消|撤回|戻し|戻せ|預か|あずか|電話|代わりに|代理で|したいと言われ|と言われた|資金繰り|苦しい|払えな|引き止め|止める|やめたいと|乗換|乗り換|クーリング|法人|会社の/, head:"解約は契約者ご本人が保険会社所定の書類や方法で申し出て、保険会社が手続きをします。", body:"解約の申し出は、契約者ご本人から保険会社所定の請求書や手続きの画面で行い、本人確認の書類を添えるのが一般的です。書類が保険会社に届き、不備が無ければ、解約返戻金がある契約は契約者の口座に振り込まれます。解約すると保障は無くなり、元に戻せません。手続きの前に、続ける道や減らす道が無いかも確かめます。", acts:["解約の理由を伺い、減額・払済・特約を外すなど、続ける道を先に並べる", "書類の取り寄せ方と要る本人確認の書類を、保険会社に確かめる", "解約すると戻せないことと、受け取る額の見込みを、手続きの前にお伝えする"], actHead:"現場で使うなら", note:"申し出の方法・要る書類・代理店で書類を扱えるかは保険会社で違う。保険会社の窓口と社内の手順で確かめる。税の扱いは税理士。", pre:1, say:"解約は、ご契約者様から保険会社へお申し出いただくお手続きです。一度解約すると戻せないので、続ける方法が無いかも一緒に見てからにしましょう。", more:"気をつけたいのは、解約して新しい契約に入るつもりの場面です。新しい契約が成立する前に解約すると、保障の無い期間ができることがあります。解約の書類は、保険会社から契約者ご本人に直接送る形をとる会社もあるので、社内の手順で確かめてからご案内します。", why:"解約は契約者の財産と保障に関わる手続きなので、本人の意思を書面などで確かめて保険会社が行う形になっているからです。やり直しがきかないので、手続きの前に選べる道を並べることが大事です。" },
      { key:'faq_xtet_kaiyakudare', faq:1, grp:'tet', q:"保険を解約できるのは誰？", re:/解約(できる|する)の?は誰|解約の手続きは誰|誰が(解約|解約の手続き)|(被保険者|受取人)[^。]{0,6}(が|は|も)[^。]{0,6}(勝手に)?解約(でき|して)/, ng:/認知症|後見|成年|入院中|意識/, head:"解約できるのは契約者で、被保険者や受取人が一人で解約することはできません。", body:"保険の解約は、契約を結んだ契約者の権利です。被保険者や受取人は、契約者でない限り、一人で解約することはできません。法人が契約者なら、手続きは法人として行います。契約者が亡くなった場合は、契約を引き継いだ方が契約者になってから手続きをします。", acts:["証券で契約者が誰かを先に確かめ、その方から申し出ていただく", "契約者でない方からの依頼は、手続きを進めず、契約者ご本人に確かめる", "契約者が亡くなっているときは、契約者の変更から案内する"], actHead:"現場で使うなら", note:"契約者が手続きできないときの扱い・要る書類は保険会社で違う。保険会社の窓口で確かめる。法律上の判断は弁護士。", pre:1, say:"解約のお手続きは、ご契約者様ご本人からのお申し出になります。ご家族からのご依頼のときは、ご契約者様に確かめてから進めます。", more:"よくあるのは、契約者は夫、被保険者は妻という契約で、妻から解約したいと言われる場面です。保障を受ける方の気持ちも大事ですが、手続きの権利は契約者にあるので、ご夫婦で話していただくようお伝えします。契約者が判断できない状態のときは、成年後見などの話になり、保険会社と専門家に相談します。", why:"契約者は保険料を払い、契約を変えたり終えたりできる立場で、解約返戻金を受け取るのも契約者だからです。ほかの人が勝手に解約できると、契約者の財産が損なわれます。" },
      { key:'faq_xtet_denwakaiyaku', faq:1, grp:'tet', q:"お客様から電話で解約してほしいと言われた", re:/電話(で|から)[^。]{0,8}解約|解約[^。]{0,8}(書類|請求書)[^。]{0,8}(預か|あずか|代わりに|代理店で)|(代わりに|代理で)[^。]{0,8}解約(の手続|して|でき)/, ng:/資金繰り|苦しい|払えな|認知症|後見/, head:"電話の依頼だけでは解約はできず、契約者ご本人が保険会社所定の方法で申し出ます。", body:"解約は契約者ご本人の意思を確かめて行う手続きなので、電話で頼まれても、募集人がその場で解約を済ませることはできません。保険会社所定の請求書や手続きの画面で、ご本人から申し出ていただきます。解約の書類を代理店で預かってよいか、保険会社から直接送るかは、保険会社と社内の決まりで違います。", acts:["依頼を受けた日時と内容を記録し、まず理由を伺う", "解約の方法と、書類を代理店で扱えるかを、保険会社の手引きと社内で確かめる", "お客様の代わりに書類を書いたり、印鑑を預かったりしない"], actHead:"現場で使うなら", note:"解約の受け方・書類の扱い・代理店の役目は保険会社と社内の決まりで違う。保険会社の手引きと社内の手順で確かめる。", pre:1, say:"解約のお手続きは、ご契約者様ご本人からのお申し出が要ります。お手続きの方法をご案内しますね。その前に、差し支えなければご事情を伺ってもよろしいですか。", more:"電話で解約と言われる理由は、保険料の負担、ほかで入り直した、内容に不満がある、などさまざまです。理由によっては減額や払済で続けられることもあるので、まず伺います。ただし、続けるよう強く勧めて申し出を受けないことはしません。申し出を受けた記録は残しておきます。", why:"解約は、契約者の保障と財産に関わる手続きなので、本人の意思を確かな形で確かめる必要があるからです。代わりに書いたり預かったりすると、本人の意思と違う手続きが起きるおそれがあります。" },
      { key:'faq_xtet_henreikinjiki', faq:1, grp:'tet', q:"解約返戻金はいつ振り込まれる？", re:/(解約返戻金|返戻金|解約(の|した)お金)[^。]{0,10}(いつ|振り?込|入金|入る|かかる|まだ)/, ng:/税|所得|確定申告|法人|経理|額は|いくら|少な/, head:"書類が保険会社に届き、不備が無ければ、保険会社所定の日数のうちに契約者の口座に振り込まれます。", body:"解約返戻金は、解約の請求書と要る書類が保険会社に届き、内容を確かめて不備が無ければ、契約者の口座に振り込まれます。振り込みまでの日数は、保険会社が手続きの案内や約款で示しています。書類に不備があると戻ってきて、そのぶん遅れます。振り込まれたら、保険会社から支払いの明細が届くのが一般的です。", acts:["いつ書類を出したかを伺い、保険会社に手続きの状況を問い合わせる", "不備で戻っていないかを確かめ、戻っていれば直し方をご案内する", "振り込み先の口座が契約者名義かを確かめる"], actHead:"現場で使うなら", note:"振り込みまでの日数・明細の届き方は保険会社で違う。保険会社の窓口と手続きの案内で確かめる。", pre:1, say:"書類が保険会社に届いて確かめが済むと、ご契約者様の口座に振り込まれます。今どの段階かを保険会社に確かめてご連絡します。", more:"遅れる理由でいちばん多いのは、書類の不備です。署名や印鑑、本人確認の書類の写しが足りないと戻ってきます。申し出のときに要るものを一つずつ確かめておくと、遅れを防げます。解約返戻金を当てにして支払いの予定を立てている方には、日数に余裕を持っていただきます。", why:"保険会社は、解約が契約者本人の意思によるものか、書類に誤りが無いかを確かめてから支払うので、届いてから振り込みまでに確かめの時間がかかるからです。" },
      { key:'faq_xtet_henreikinshoukai', faq:1, grp:'tet', q:"今の解約返戻金の額を知りたいと言われた", re:/(解約返戻金|返戻金|解約したら)[^。]{0,10}(額|いくら)[^。]{0,8}(知りたい|調べ|確か|照会|分か)|(解約返戻金|返戻金)(の)?(照会|試算|見積)/, ng:/税|所得|法人|経理|少ないのはなぜ|なぜ少な|払った(額|保険料)より/, head:"今の額は、契約者が保険会社に照会して確かめ、ウェブのページで見られる保険会社もあります。", body:"解約返戻金の額は、経過した期間や払い込んだ保険料、契約者貸付の残りなどで変わるので、今の額は保険会社に照会して確かめます。照会できるのは契約者ご本人が基本で、保険会社の窓口のほか、契約者向けのウェブのページで見られる会社もあります。証券に載っている表は、決められた時点の目安です。", acts:["契約者ご本人から、保険会社の窓口かウェブのページで照会していただく", "貸付の残りや未払いの保険料が差し引かれるかも、一緒に確かめる", "額を聞いたうえで、解約のほかに続ける道があるかを並べる"], actHead:"現場で使うなら", note:"照会の方法・照会できる人・差し引かれるものは保険会社で違う。保険会社の窓口と契約者向けの案内で確かめる。", pre:1, say:"今の解約返戻金は、保険会社に照会すると分かります。ご契約者様ご本人からのお問い合わせになりますので、方法をご案内します。", more:"証券の表を見て額を伝えると、時点がずれていたり、貸付の残りを引き忘れたりして、実際の額と違ってしまうことがあります。額をお伝えするときは、保険会社が出した数字をそのまま使います。照会の理由が解約のご検討なら、減額や払済で続けた場合の額も並べてお見せします。", why:"解約返戻金は、契約の経過とともに毎月のように変わり、貸付や未払いの保険料も差し引かれるので、正しい額は保険会社の記録でしか出せないからです。" },
      { key:'faq_xtet_kaiyakumodosu', faq:1, grp:'tet', q:"解約したあとで、取り消したいと言われた", re:/解約[^。]{0,8}(取り消し|取消|撤回|取り下げ|取下げ|無かったこと|なかったこと|やっぱり続け|戻したい|元に戻)/, ng:/クーリング|申込(の|を)(撤回|取り消)|キャンセル/, head:"解約が済んだ契約は元に戻せないのが一般的で、手続きの途中ならすぐ保険会社に問い合わせます。", body:"解約は、手続きが済むと契約が終わり、あとから元に戻すことはできないのが一般的です。書類が保険会社に届く前や、手続きが済む前なら、取り下げを受け付けることがあるので、気づいた時点ですぐ保険会社に問い合わせます。戻せないときは、新しく契約し直すことになり、今の年齢と健康状態で引受けが判断されます。", acts:["書類をいつ出したかを伺い、すぐ保険会社に手続きの状況を確かめる", "戻せないときは、今の年齢と健康状態で入り直したときの保障と保険料を並べる", "やりとりを記録し、解約の前の説明に足りないところが無かったかも振り返る"], actHead:"現場で使うなら", note:"取り下げを受け付けるか・その期限は保険会社で違う。保険会社の窓口ですぐに確かめる。", pre:1, say:"すぐに保険会社に手続きの状況を確かめます。もし済んでいたら元には戻せないので、そのときは新しくご準備する方法を一緒に考えましょう。", more:"こうした相談は、解約したあとに病気が見つかった、家族に反対された、という場面で起こります。解約の前に、戻せないことと、入り直すときの条件が変わることを伝えておくのが、いちばんの備えです。手続きの途中なら間に合うこともあるので、迷わずすぐに連絡します。", why:"解約は契約を終わらせる手続きで、終わった契約を戻すと、保険会社がその間の危険を引き受けていなかったことと食い違うからです。だから、戻すのではなく、新しく引受けを判断し直す形になります。" },
      { key:'faq_xtet_coolinghouhou', faq:1, grp:'tet', q:"クーリング・オフはどうやって申し出る？", re:/(クーリング・?オフ|クーリングオフ)[^。]{0,12}(どうやって|やり方|方法|書き方|送り方|送り先|宛先|メール|電話で|ウェブ|はがき|ハガキ|書面)/, ng:/できない|できません|対象外/, head:"クーリング・オフは、契約者が保険会社に、書面か保険会社が決めた電磁的な方法で申し出ます。", body:"クーリング・オフは、申込みの撤回や契約の解除を、契約者から保険会社に直接申し出る手続きです。申し出の方法は書面が基本で、保険会社が定める電磁的な方法（電子メールや申し出の画面など）でも受け付ける会社があります。申し出の宛先と書く内容は、申込みのときに受け取る書面に書かれているので、それに沿って申し出ていただきます。", acts:["申込みのときの書面で、宛先・書く内容・受け付ける方法を一緒に確かめる", "募集人に伝えるだけでは申し出にならないことを、はっきり伝える", "送った日が分かる形で残していただくよう、お伝えする"], actHead:"現場で使うなら", note:"受け付ける方法・宛先・書く内容は保険会社で違う。申込みのときの書面と保険会社の窓口で確かめる。", pre:1, say:"クーリング・オフは、ご契約者様から保険会社へ直接お申し出いただく手続きです。お申し込みのときにお渡しした書面に方法が書いてありますので、一緒に確かめましょう。", more:"気をつけたいのは、募集人に電話で伝えたことで済んだと思われる場面です。申し出の相手は保険会社なので、書面などで保険会社に届くことが要ります。送った日を残すために、記録が残る方法で送っていただくと安心です。申し出を受けたら、その事実を社内の決まりに沿って記録します。", why:"クーリング・オフは、契約者が落ち着いて考え直せるよう、法律で認められた権利なので、本人の意思を保険会社に確かに届ける形が決められているからです。" },
      { key:'faq_xtet_coolinghenkin', faq:1, grp:'tet', q:"クーリング・オフしたら保険料は戻る？", re:/(クーリング・?オフ|クーリングオフ)[^。]{0,14}(保険料|お金|返金|返って|戻る|戻って|違約金|手数料|費用)/, ng:/できない|できません|対象外/, head:"クーリング・オフをすると、払い込んだ保険料は返されるのが一般的で、違約金はかかりません。", body:"クーリング・オフが成り立つと、申込みの撤回や契約の解除として扱われ、既に払い込んだ保険料は保険会社から返されるのが一般的です。契約者が違約金や損害の賠償を求められることはありません。返し方と時期は保険会社が決め、申込みのときの書面や保険会社からの案内で示されます。", acts:["払い込んだ保険料と払い方（口座・カードなど）を確かめる", "返し方と時期を保険会社に確かめてから、お客様にお伝えする", "返金を受けたら、お客様と一緒に確かめて記録を残す"], actHead:"現場で使うなら", note:"返し方・時期・保障が始まっていた場合の扱いは保険会社と契約で違う。保険会社の窓口と申込みのときの書面で確かめる。", pre:1, say:"クーリング・オフをされた場合、お払込みいただいた保険料はお返しするのが一般的で、違約金はかかりません。お返しの方法と時期は保険会社に確かめてご連絡します。", more:"カードで保険料を払っていた場合は、カード会社を通して返される形になり、明細に出るまで時間がかかることがあります。お客様が二重に払ったように見えて驚かれないよう、返し方を先にお伝えしておきます。", why:"クーリング・オフは、契約者に不利益なく考え直していただくための仕組みなので、払った保険料を返し、違約金も取らない形になっているからです。" },
      { key:'faq_xtet_coolinghikitome', faq:1, grp:'tet', q:"クーリング・オフしたいと言われたら、引き止めていい？", re:/(クーリング・?オフ|クーリングオフ)[^。]{0,16}(引き止め|引きとめ|説得|考え直|思いとどま|断れ|断って|止め|理由を聞)/, head:"クーリング・オフはお客様の権利なので、申し出を妨げたり、強く引き止めたりしません。", body:"クーリング・オフは、契約者が落ち着いて考え直せるよう法律で定められた権利で、募集人が断ったり、申し出を遅らせたりすることはできません。誤解がもとで迷われているなら、事実を正しくお伝えするのはかまいませんが、決めるのはお客様です。何度も説得したり、不安で押したりすると、苦情や問題になります。", acts:["申し出を受け止め、手続きの方法を書面に沿ってご案内する", "誤解があれば、事実だけをお伝えし、決めるのはお客様と伝える", "申し出を受けた日と内容を記録し、社内の決まりに沿って上長に伝える"], actHead:"現場で使うなら", note:"申し出を受けたときの社内の手順・記録の仕方は、所属保険会社の手引きと社内の決まりで確かめる。法律上の判断は弁護士。", pre:1, say:"承知しました。お手続きの方法をご案内します。もし説明が足りずにご不安になったことがあれば、そこだけ改めてご説明させてください。お決めになるのはお客様です。", more:"理由を伺うことは、説明の足りなかった点を知るうえで役に立ちますが、答えたくない方に無理に聞くことはしません。家族に反対された、ほかと比べたい、といった理由なら、それ自体がもっともな判断です。こちらの説明の仕方を見直す材料として受け止めます。", why:"募集の場では、その場の雰囲気や勢いで申し込んでしまうことがあるので、冷静に考え直す時間を契約者に保障する仕組みだからです。引き止めると、その仕組みの意味が失われます。" },
      { key:'faq_xtet_coolingitsu', faq:1, grp:'tet', q:"クーリング・オフの期間はいつから数える？", re:/(クーリング・?オフ|クーリングオフ)[^。]{0,10}(いつから|いつまで|数え|起算|期限|期間|何日)/, ng:/できない|できません|対象外/, head:"申込みの日と、クーリング・オフの説明の書面を受け取った日の、遅いほうから数えるのが一般的です。", body:"クーリング・オフの期間は、申込みをした日か、クーリング・オフについて書かれた書面を受け取った日の、どちらか遅い日から数えるのが一般的です。期間の長さは法律で決まっていて、保険会社によってはそれより長くしている会社もあります。期間のうちに申し出を出せばよく、具体的な日数と数え方は書面に書かれています。", acts:["申込みの日と、書面を受け取った日を、お客様と一緒に確かめる", "期間の長さは、その契約の書面に書かれた内容をそのまま伝える", "期限が近いときは、記録の残る方法で早めに申し出ていただく"], actHead:"現場で使うなら", note:"期間の長さ・数え方・申し出が届いた日か出した日かは、法律と保険会社の決まりで確かめる。申込みのときの書面と保険会社の窓口で確かめる。", pre:1, say:"クーリング・オフの期間は、お申し込みの日か、説明の書面をお受け取りになった日の、遅いほうから数えます。日数は書面に書かれていますので、一緒に確かめましょう。", more:"よくある勘違いは、契約が成立した日や、証券が届いた日から数える、と思われることです。数え始めの日を正しく確かめるために、申込みの日と書面を受け取った日を記録しておきます。クーリング・オフができない場合もあるので、書面でその点も一緒に見ます。", why:"書面を受け取らないうちに期間が過ぎると、権利があることを知らないまま終わってしまうので、書面を受け取った日からも数えるようにして、権利を確かに使えるようにしているからです。" },
      { key:'faq_xtet_dairitenhenko', faq:1, grp:'tet', q:"担当の代理店を変えたいと言われた", re:/(担当の?|契約の)?代理店を?(変え|変更|替え|移し|移す)|(ほかの|他の|別の)代理店に[^。]{0,8}(移|変|替)|代理店(の)?(変更|移管)|前の代理店から[^。]{0,10}(引き継|担当)/, ng:/募集人の登録|登録の変更|所属|廃業|合併|受け入れる側|受け入れ側/, head:"担当の代理店を変えるのは、契約者のご意思をもとに、保険会社所定の手続きで行います。", body:"契約の担当の代理店は、契約者が望めば、保険会社所定の手続きで変えられるのが一般的です。新しい代理店がその保険会社の商品を扱っていることが前提で、保険会社によっては、契約者の申し出の書類を求めます。担当が変わっても、契約の中身や保険料は変わりません。前の代理店を悪く言って変えていただくことはしません。", acts:["変えたい理由と契約者のご意思を確かめる", "自分の代理店がその保険会社を扱っているかと、要る手続きを保険会社に確かめる", "前の担当や代理店の悪口を言わず、事実だけをお伝えする"], actHead:"現場で使うなら", note:"担当の代理店を変える手続き・要る書類・扱っていない保険会社の契約の扱いは保険会社で違う。保険会社の代理店の窓口と社内の手順で確かめる。", pre:1, say:"担当の代理店は、ご契約者様のお申し出で変えられることがあります。ご契約の中身は変わりませんので、ご安心ください。手続きを確かめてご案内します。", more:"気をつけたいのは、担当を移していただくことを目当てに、前の代理店の説明を否定する言い方です。お客様の誤解を正すことと、前の担当を責めることは違います。担当を引き継いだら、証券と契約内容のお知らせで中身を一緒に確かめ、受取人や連絡先の古いところを直す機会にします。ほかの代理店へ移りたいと言われたときは引き止めず、手続き中の事故や問い合わせをどちらが受けるかを決めます。", why:"契約の担当は、契約者に案内や手続きの支えをする役目なので、契約者が誰に頼みたいかで決めてよいからです。契約そのものは保険会社と契約者の間のものなので、担当が変わっても中身は変わりません。" },
      { key:'faq_xtet_tashadairiten', faq:1, grp:'tet', q:"ほかの代理店で入った契約の手続きを頼まれた", re:/(ほかの|他の|別の|他社の)代理店(で|の)[^。]{0,14}(手続|変更|請求|頼まれ|手伝|見てほし|見て)/, ng:/契約を?移|変え|変更したい代理店|担当の代理店を/, head:"ほかの代理店の契約は、担当の代理店か保険会社につなぐのが基本で、勝手に手続きを進めません。", body:"契約には担当の代理店があり、手続きの取次ぎは、その代理店か保険会社が行うのが基本です。ほかの代理店の契約の手続きを、自分の代理店で進めてよいかは、保険会社と社内の決まりで違います。お客様が困っているときは、保険会社の窓口の連絡先をお伝えするなど、手続きが止まらないように支えます。", acts:["証券で、どの保険会社のどの代理店の契約かを確かめる", "担当の代理店か保険会社の窓口をご案内し、連絡先をお伝えする", "自分の代理店で扱ってよいかは、社内と保険会社に確かめてから動く"], actHead:"現場で使うなら", note:"他の代理店の契約の手続きを扱えるかは、保険会社と社内の決まりで違う。保険会社の代理店の窓口と社内の手順で確かめる。", pre:1, say:"こちらのご契約は、ほかの代理店さんのご担当です。お手続きが止まらないよう、担当の代理店か保険会社の窓口をご案内しますね。", more:"よくあるのは、ご家族の契約をまとめて見てほしい、という相談です。内容を一緒に見ることと、手続きを代わりに進めることは分けて考えます。担当を移したいというご意思がはっきりしていれば、担当の代理店を変える手続きを確かめます。", why:"契約の手続きは、担当の代理店が契約の記録と経緯を持って行う形になっているからです。担当でない代理店が手続きを進めると、記録が食い違ったり、責任の所在が分からなくなったりします。" },
      { key:'faq_xtet_denwahonnin', faq:1, grp:'tet', q:"電話で保全の手続きを頼まれたら、本人をどう確かめる？", re:/電話[^。]{0,20}(本人|ご本人)[^。]{0,8}(確か|確認)|(本人|ご本人)(確認|を確か)[^。]{0,10}電話|電話(で|から)[^。]{0,10}(住所|名義|受取人|口座)[^。]{0,6}(変え|変更)/, ng:/詐欺|振り込め|知らない番号/, head:"電話では、保険会社や社内が決めた項目でご本人と確かめ、合わなければ手続きを進めません。", body:"電話の相手がご契約者ご本人かは、声だけでは分かりません。保険会社や社内が決めた確かめの項目（お名前・生年月日・証券番号・登録の住所など）でご本人と確かめ、合わないときは手続きを進めず、書面での手続きや折り返しの電話に切り替えます。住所・受取人・口座の変更は、電話では受け付けず書類で行う保険会社もあります。", acts:["社内で決めた本人の確かめの項目を、毎回同じ順で聞く", "確かめた項目と、受けた依頼の内容を記録する", "少しでも合わないときは、手続きを進めず、登録の番号に折り返す"], actHead:"現場で使うなら", note:"電話で受け付けられる手続き・確かめの項目は保険会社と社内の決まりで違う。保険会社の手引きと社内の手順で確かめる。", pre:1, say:"お手続きの前に、ご本人様の確認のため、いくつかお伺いします。お名前と生年月日を教えていただけますか。", more:"ご家族が契約者になりすまして手続きを頼む、ということは実際に起こります。親しいお客様ほど確かめを省きたくなりますが、毎回同じ確かめをすることが、お客様の契約を守ることになります。確かめの項目は、既に登録されている情報と照らせるものにします。", why:"保全の手続きは、契約者の財産と保障に関わるので、本人でない人の依頼で手続きが進むと、契約者に大きな不利益が生じるからです。電話は顔が見えないので、決めた項目で確かめる必要があります。" },
      { key:'faq_xtet_hozenkiroku', faq:1, grp:'tet', q:"保全の依頼を受けたら、何を記録する？", re:/(保全|手続き|変更)の?(依頼|申し出|対応)[^。]{0,12}(記録|履歴|残し|残す|書く|メモ)|(対応|保全)(の)?履歴/, ng:/苦情|クレーム|意向把握|比較推奨|面談の記録|商談記録/, head:"受けた日時・相手・確かめたこと・依頼の中身・取った手続き・お客様への連絡を、その日のうちに残します。", body:"保全の依頼は、受けた日時、相手と本人を確かめた方法、依頼の中身、保険会社への取次ぎや書類の送付、お客様への連絡、を記録しておくと、あとで手続きが止まったときや問い合わせを受けたときに、すぐ経緯を確かめられます。記録の形と残す場所は、保険会社と社内の決まりに沿います。お客様の情報は社外へ持ち出しません。", acts:["依頼を受けたら、その日のうちに決まった形で記録する", "書類を送った日と、保険会社で済んだ日も書き足す", "担当が不在でも分かるよう、略さずに書く"], actHead:"現場で使うなら", note:"記録する項目・残す場所・残す期間は、所属保険会社の指示と社内規則で確かめる。", pre:1, say:"ご依頼の内容を記録して、手続きが済むまで確かめます。済みましたらご連絡しますね。", more:"記録が無いと、言った・言わないのやりとりになったり、担当が休みの日に誰も経緯が分からなかったりします。とくに、受取人や口座の変更のように、あとで問題になりやすい手続きは、確かめた方法まで残しておきます。手続きが済んだことをお客様に伝えた日も、記録に入れます。", why:"保全の手続きは、受けてから済むまでに日がかかり、途中で何人もの人が関わるので、経緯を残しておかないと、手続きが止まったり、行き違いが起きたりするからです。" },
      { key:'faq_xtet_web', faq:1, grp:'tet', q:"契約者向けのウェブのページでできる手続きは？", re:/(マイページ|契約者(向け|専用)の?(ウェブ|web|サイト|ページ)|ウェブのページ|webのページ)|(ネット|インターネット|ウェブ|web|アプリ)で[^。]{0,8}(住所|名義|変更|手続|照会)[^。]{0,4}(でき|する)/, ng:/nisa|ニーサ|ideco|イデコ|銀行|証券会社|ねんきんネット|マイナポータル|自動車|車/, head:"住所の変更や契約内容の照会などを、契約者向けのウェブのページで受け付ける保険会社があります。", body:"保険会社によっては、契約者が登録すると使えるウェブのページを用意していて、契約内容や解約返戻金の照会、住所や連絡先の変更、書類の取り寄せなどができます。受け付ける手続きの範囲は保険会社で違い、受取人の変更や解約など、書面で行う手続きもあります。登録と使い方は、ご契約者ご本人に行っていただきます。", acts:["所属保険会社のページで、どの手続きができるかを先に確かめる", "登録の方法をご案内し、パスワードなどはお客様ご自身で管理していただく", "ページでできない手続きは、書類での方法を一緒にご案内する"], actHead:"現場で使うなら", note:"できる手続きの範囲・登録の方法は保険会社で違い、見直されることもある。保険会社の契約者向けの案内と窓口で確かめる。", pre:1, say:"保険会社の契約者向けのページから、住所の変更やご契約内容の確認ができることがあります。登録の方法をご案内しますね。", more:"ご高齢の方は、登録の操作でつまずくことがあります。横で一緒に手順を見るのはよいですが、パスワードを預かったり、代わりに操作したりはしません。ページで手続きができると、書類の行き来が無くなって早く済む一方で、操作の誤りに気づきにくいので、済んだあとに一緒に内容を確かめます。", why:"契約者が自分で手続きできる道を用意すると、書類の郵送を待たずに早く済み、保険会社と代理店の手間も減るからです。ただ、本人の確かめが要る大事な手続きは、書面で行う形を残しています。" },
      { key:'faq_xtet_hozenfubi', faq:1, grp:'tet', q:"変更の書類が不備で戻ってきた", re:/(変更|保全|名義|住所|受取人|解約|請求)[^。]{0,8}(書類|請求書|届)[^。]{0,10}(不備|戻って|返送|返され|差し戻)/, ng:/申込|申し込み|口座振替/, head:"戻ってきた理由を保険会社の連絡で確かめ、直す所だけをお客様にご案内します。", body:"保全の書類は、署名や記入の漏れ、本人確認の書類の写しが足りない、書き直しの仕方が決まりと違う、などで戻ってくることがあります。保険会社からの連絡で、どこが不備かを確かめ、お客様に直していただく所だけを分かりやすく伝えます。募集人が代わりに書き直したり、署名を書いたりはしません。", acts:["保険会社の連絡で、不備の箇所と直し方を確かめる", "直していただく所に印を付け、要るものと一緒にお客様へお伝えする", "同じ不備が続くなら、受け付けの時の確かめの項目を見直す"], actHead:"現場で使うなら", note:"直し方・書き直しのときの決まり・要る書類は保険会社で違う。保険会社の手引きと窓口で確かめる。", pre:1, say:"お手数をおかけします。書類に一か所直していただきたい所がありました。直す所に印を付けてお送りしますので、ご確認ください。", more:"不備で戻ると、お客様にもう一度手間をかけていただくことになり、手続きも遅れます。受け付けるときに、署名・日付・本人確認の書類の写しを、その場で一緒に確かめるだけで、多くの不備は防げます。訂正の仕方には保険会社の決まりがあるので、修正液などを使わないようお伝えします。", why:"保全の書類は、契約者本人の意思を確かめる証になるので、記入の漏れや決まりと違う書き方があると、保険会社は手続きを進められないからです。" },
      { key:'faq_xtet_toritsugi', faq:1, grp:'tet', q:"保全の手続きは、代理店でどこまでできる？", re:/(保全|変更)の?(手続き|手続)[^。]{0,8}代理店[^。]{0,8}(どこまで|でき|受け付)|代理店(で|が)[^。]{0,8}(受け付け|受付|できる|済ませ)[^。]{0,8}(手続|保全|変更)|代理店(で|が)[^。]{0,4}(手続|保全)[^。]{0,8}(済ませ|でき|受け付)|(保全|手続き)の取次/, ng:/募集人の登録|登録の手続/, head:"多くの保全は、代理店が書類を取り次ぎ、手続きそのものは保険会社が行います。", body:"住所や受取人の変更、解約などの保全は、代理店がお客様から依頼を受け、書類の案内や受け取りをして保険会社に取り次ぎ、手続きを済ませるのは保険会社、という形が一般的です。代理店がどの手続きを取り次げるか、書類を預かってよいかは、保険会社との委託の契約と社内の決まりで決まります。取り次げない手続きは、保険会社の窓口をご案内します。", acts:["所属保険会社の手引きで、取り次げる手続きの一覧を確かめる", "取り次いだ書類は、送った日と控えを記録する", "取り次げない手続きは、保険会社の窓口と連絡先をお伝えする"], actHead:"現場で使うなら", note:"取り次げる手続き・書類の扱い・代理店の権限は、保険会社との委託の契約と手引き・社内の決まりで違う。保険会社の代理店の窓口で確かめる。", pre:1, say:"このお手続きは、私がお預かりして保険会社にお取り次ぎします。保険会社で手続きが済みましたら、改めてご連絡します。", more:"よくある勘違いは、代理店に書類を渡した時点で手続きが済んだ、と思われることです。保険会社に届いて確かめが済むまでは、手続きは終わっていません。済んだことを保険会社の通知で確かめてから、お客様にお伝えします。", why:"代理店は、保険会社から委託された範囲で契約の手続きを支える立場で、契約の記録を変えるのは保険会社だからです。取り次ぎの範囲を決めておくことで、手続きの責任がはっきりします。" },
      { key:'faq_xtet_shitsuken', faq:1, grp:'tet', q:"保険に質権を設定したいと言われた", re:/質権|(担保|借入れの担保|借入の担保)[^。]{0,8}(保険|生命保険)[^。]{0,6}(入れ|に|を)|(保険|保険金)[^。]{0,6}担保に/, ng:/住宅ローン|団信|団体信用/, head:"質権は、保険金などを借入れの担保にする仕組みで、保険会社の承諾など所定の手続きが要ります。", body:"事業の借入れなどの担保として、保険金や解約返戻金を受け取る権利に、金融機関が質権を設定することがあります。設定には、契約者と金融機関の取り決めに加え、保険会社所定の手続きと承諾が要るのが一般的です。質権が付いている間は、保険金が金融機関に支払われたり、解約や受取人の変更が自由にできなかったりします。", acts:["金融機関から求められた内容と、対象の契約を確かめる", "保険会社に、質権の設定の手続きと要る書類を確かめる", "設定したあとに解約や変更をするときの扱いを、事前にお伝えする"], actHead:"現場で使うなら", note:"質権の設定・解除の手続き・保険金の扱いは保険会社と契約で違う。保険会社の窓口で手続きを、借入れの条件は金融機関で、法律上の判断は弁護士で確かめる。", pre:1, say:"保険を借入れの担保にするお手続きですね。保険会社の承諾が要りますので、要る書類と、設定したあとの扱いを確かめてご案内します。", more:"法人の借入れのときに、社長が被保険者の保険に質権を付けてほしい、と金融機関から言われる場面があります。質権が付くと、もしものときの保険金が借入れの返済に回るので、ご家族や会社に残るお金が変わります。借入れを返し終えたら、質権を外す手続きを忘れないようにします。保険の棚卸しをするときは、担保の設定の有無も一覧に入れます。", why:"保険金や解約返戻金は、契約者のお金として価値があるので、借入れの担保として使えるからです。保険会社が承諾するのは、支払いの相手が変わることを保険会社が知っておく必要があるためです。" },
      { key:'faq_xtet_koushinannai', faq:1, grp:'tet', q:"保険の更新の案内が届いたら、何を確かめる？", re:/(保険|定期保険|医療保険|特約|生命保険|がん保険)[^。]{0,8}更新の(案内|お知らせ|通知)|更新の(案内|お知らせ|通知)[^。]{0,10}(保険|確か|見方|何を)/, ng:/資格|免許|登録|募集人|研修|賃貸|車|自動車|火災|損保|伝え|説明する|説明すれば/, head:"更新後の保険料・保障の内容・更新できる年齢の上限・更新しないときの申し出の期限を確かめます。", body:"更新の案内には、更新後の保険料、更新後も同じかどうかの保障の内容、次の更新の時期、更新しないときの申し出の方法と期限が書かれているのが一般的です。保険料は更新するときの年齢で計算し直すので、上がることが多くあります。同じ内容で続けるか、保障を減らして更新するか、終わらせるかを、ほかの契約と並べて決めていただきます。", acts:["更新前と更新後の保険料と保障を、案内をもとに並べる", "更新できる年齢の上限と、次の更新の時期を確かめる", "減らして更新する道や、更新しない道があるかを保険会社に確かめる"], actHead:"現場で使うなら", note:"案内の中身・減らして更新できるか・申し出の期限は商品と保険会社で違う。保険会社の更新の案内と窓口で確かめる。", pre:1, say:"更新のご案内が届いたら、保険料と保障がどう変わるかを一緒に見ましょう。続け方はいくつかありますので、並べてからお決めください。", more:"案内が届いてから期限までが短いことがあるので、更新の時期は前もって分かっていれば、早めに声をかけます。今の暮らしに必要な保障の額が変わっていることも多く、更新は見直しのきっかけになります。ただし、不安で押して乗り換えを勧める話にはしません。", why:"更新は、同じ保障を続けられる大事な機会である一方、保険料が上がることが多いので、続ける・減らす・終える、の選択を、中身を見て選んでいただく必要があるからです。" },
      { key:'faq_xtet_hikiotoshibi', faq:1, grp:'tet', q:"保険料の引き落とし日を変えたいと言われた", re:/(引き?落とし|引落|振替|口座振替)(の)?日[^。]{0,10}(変え|変更|選べ|選び|ずら|給料日)|(保険料)[^。]{0,6}(引き?落とし|振替)の?日/, ng:/できな|落ちな|残高|未納|失効|クレジット|カード/, head:"保険料の振替日は保険会社が決めていることが多く、選べる会社と選べない会社があります。", body:"口座振替の日は、保険会社が金融機関と取り決めた日にまとめて引き落とす形が多く、契約者が自由に選べないことがあります。一方で、いくつかの日から選べる保険会社もあります。変えられないときは、引き落としの口座を給料の入る口座にする、払い方を変えるなどの手を考えます。", acts:["所属保険会社で振替日を選べるかを確かめる", "選べないときは、口座や払い方を変える道を並べる", "残高が足りずに引き落としができなかったときの扱いも、あわせて伝える"], actHead:"現場で使うなら", note:"振替日・選べるか・引き落としができなかったときの再振替の扱いは保険会社で違う。保険会社の窓口と案内で確かめる。", pre:1, say:"保険料の引き落とし日は、保険会社で決まっていることが多いです。変えられるかを確かめて、難しければほかの方法を一緒に考えましょう。", more:"引き落とし日を変えたい理由の多くは、給料日の前で残高が足りなくなる、というものです。引き落としができないことが続くと、失効のおそれが出てくるので、日を変えられない場合でも、口座の組み替えなどで確実に払える形を一緒に作ります。", why:"保険会社は、多くの契約の保険料を決まった日にまとめて引き落とすことで、手続きの手間と費用を抑えているからです。そのため、契約ごとに日を変えにくい仕組みになっています。" },
      { key:'faq_xtet_henkotsuchi', faq:1, grp:'tet', q:"変更の手続きのあと、保険会社から何が届く？", re:/(変更|手続き)(の)?(あと|後)[^。]{0,12}(届く|届か|証券|通知|お知らせ)|(変え|変更し)た(あと|後)[^。]{0,8}証券[^。]{0,6}(新しく|変わ|再発行)|変更(の)?(通知|お知らせ)[^。]{0,6}(届か|来な)|(住所|受取人|名義)変更が済んだか/, ng:/税|支払調書|法人の経理/, head:"手続きが済むと、保険会社から変更の通知が届き、証券を新しく出すか書き添えるかは保険会社で違います。", body:"保全の手続きが済むと、保険会社から契約者に、変更の内容を知らせる通知が届くのが一般的です。受取人や保障の内容が変わったときは、証券を新しく出す会社と、通知を証券と一緒に保管していただく会社があります。通知が届いたら、変えた内容が正しく反映されているかを確かめていただきます。", acts:["手続きを取り次いだら、通知が届く時期の目安を保険会社に確かめる", "通知が届いたら、お客様と一緒に変更の内容を確かめる", "届かないときは、保険会社に手続きの状況と送り先の住所を確かめる"], actHead:"現場で使うなら", note:"通知の形・証券を出し直すかは保険会社と手続きで違う。保険会社の窓口と手引きで確かめる。", pre:1, say:"お手続きが済むと、保険会社から変更のお知らせが届きます。届きましたら、内容が合っているか一緒に確かめさせてください。", more:"見落としやすいのは、住所の変更と一緒に頼んだ別の手続きが、片方だけ済んでいる場面です。通知を見て、頼んだことが全て反映されているかを確かめます。変更の通知は、あとで証券と一緒に見返すことになるので、証券と同じ場所に保管していただくようお伝えします。", why:"変更が正しく反映されたかを、契約者が自分の目で確かめられるようにするためです。通知が届かなければ、手続きが止まっているか、送り先が違っている、という知らせにもなります。" },
      { key:'faq_xtet_saigaitokubetsu', faq:1, grp:'tet', q:"大きな災害のとき、保険料の払込みは待ってもらえる？", re:/(災害|被災|地震|台風|水害|豪雨)[^。]{0,16}(保険料|払込|払い込み)[^。]{0,10}(待|猶予|延|払えな|難し)|(災害|被災)[^。]{0,14}(特別|特例)(な|の)?(取扱|取り扱)/, ng:/自動車|車|火災保険|地震保険|損保|損害保険|家財|建物/, head:"大きな災害のときは、保険会社が払込猶予期間を延ばすなどの特別な取扱いをすることがあります。", body:"大きな災害で被災された方に向けて、生命保険会社が、保険料の払込猶予期間を延ばす、請求の書類を簡単にする、契約者貸付の扱いを変える、などの特別な取扱いを行うことがあります。対象の地域・期間・中身は、災害ごとに保険会社が決めて公表します。お客様からの申し出が要るものもあります。", acts:["所属保険会社の公表で、対象の地域と取扱いの中身を確かめる", "被災されたお客様に、取扱いがあることと申し出の方法をお伝えする", "証券が無くても手続きができるかも、保険会社に確かめる"], actHead:"現場で使うなら", note:"特別な取扱いの有無・対象・期間・中身は災害ごとに保険会社が決める。所属保険会社の公表と窓口で確かめる。", pre:1, say:"大きな災害のときは、保険料のお払込みを待つなどの特別な取扱いが用意されることがあります。今回の内容を確かめてご案内します。", more:"被災された直後は、お客様は保険のことまで気が回りません。こちらから連絡し、無事を伺ったうえで、払込みや請求の取扱いを短くお伝えすると助けになります。証券や印鑑を失くされていても手続きできることがあるので、そこも確かめます。", why:"被災して一時的に保険料を払えなくなった方の保障が、失効で切れてしまわないようにするためです。災害の大きさと地域は毎回違うので、そのたびに保険会社が中身を決めて公表します。" },
      { key:'faq_xtet_naiyoutsuchi', faq:1, grp:'tet', q:"毎年届く契約内容のお知らせは、何を確かめる？", re:/(契約内容|ご契約内容)の(お知らせ|通知|ご案内)|(毎年|年に一度|年一回)[^。]{0,8}(届く|届いた|来る)[^。]{0,8}(通知|お知らせ)[^。]{0,8}(保険|見方|何を|確か)/, ng:/ねんきん定期便|年金|税|源泉|控除証明/, head:"契約者・被保険者・受取人・住所・保障の内容と、貸付の残りや配当金の額を確かめます。", body:"保険会社によっては、年に一度などの決まった時期に、契約内容のお知らせを契約者に送っています。今の保障の内容、受取人、登録の住所、解約返戻金や配当金の額、契約者貸付の残りなどが載っているのが一般的です。受取人や住所が古いままになっていないか、保障が今の暮らしに合っているかを確かめるきっかけになります。", acts:["受取人と指定代理請求人が、今のご家族の形に合っているかを確かめる", "登録の住所・電話番号が今のものかを確かめる", "貸付の残りや未払いが無いかを確かめ、気になる所は保険会社に問い合わせる"], actHead:"現場で使うなら", note:"お知らせの有無・載る項目・届く時期は保険会社で違う。保険会社の契約者向けの案内と窓口で確かめる。", pre:1, say:"毎年届くお知らせは、ご契約の中身を確かめる良い機会です。受取人やご住所が今のままで合っているか、一緒に見てみましょう。", more:"お知らせは届いても開けずにしまわれていることが多く、受取人が離婚した前の配偶者のまま、住所が引っ越す前のまま、ということがよくあります。年に一度お客様と一緒に見る習慣を作ると、手続きの漏れを防げます。保障の見直しの話は、お客様が望まれたときだけにします。", why:"契約は長く続くので、ご家族や住まいが変わっても、届け出をしないと契約の記録は昔のままになるからです。定期的に中身を知らせることで、契約者が気づいて直せるようにしています。" },
      { key:'faq_xtet_honninshorui', faq:1, grp:'tet', q:"保全の手続きに要る本人確認の書類は？", re:/本人確認(の)?(書類|書面)|(運転免許証|免許証|マイナンバーカード|保険証|パスポート)の?(写し|コピー)[^。]{0,10}(要る|いる|必要|求め|出す|出せ)/, ng:/申込|口座開設|nisa|ニーサ|銀行|証券会社|マイナポータル|ねんきん/, head:"運転免許証などの公的な書類の写しを添えるのが一般的で、使える書類は保険会社が決めています。", body:"解約や受取人の変更、支払いの請求など、財産や保障に関わる手続きでは、契約者や請求する方の本人確認の書類の写しを求められるのが一般的です。運転免許証やマイナンバーカードの表面などの公的な書類が使われることが多く、どの書類を受け付けるか、何枚要るか、住所が違うときの扱いは保険会社が決めています。", acts:["手続きの案内で、受け付ける書類の一覧と出し方を先に確かめる", "写しを預かるときは、要る面だけにし、番号などを扱う決まりを社内で確かめる", "登録の住所と書類の住所が違うときは、住所の変更を先に済ませる"], actHead:"現場で使うなら", note:"受け付ける書類・枚数・写しの扱い方は保険会社と手続きで違う。保険会社の手引きと窓口、個人情報の扱いは社内の決まりで確かめる。", pre:1, say:"このお手続きには、ご本人様を確かめる書類の写しが要ります。どの書類をお使いいただけるか、案内に沿ってご説明しますね。", more:"不備で戻りやすいのは、書類の有効期限が切れている、登録の住所と書類の住所が違う、写しが不鮮明、の三つです。マイナンバーカードは、番号の書かれた面を写さないよう決めている保険会社もあるので、案内に沿って写していただきます。預かった写しの扱いは、社内の個人情報の決まりに沿います。", why:"解約や受取人の変更は、本人でない人の手で行われると、契約者に大きな不利益が出る手続きなので、公的な書類で本人を確かめる形になっているからです。" },
      /* cmp.json */
      { key:'faq_xcmp_hitaimen', faq:1, grp:'cmp', q:"お客様に会わずに、書類だけで申込みを受けてもいい？", re:/(会わずに|会わないで|面談せずに|面談しないで|対面せず|一度も会わ)[^。]{0,16}(申込|申し込|契約|手続)|(郵送|書類)だけで[^。]{0,10}(申込|申し込|契約|手続)/, ng:/部下|後輩|新人|メンバー|上司|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"会わずに進めるなら、保険会社が認めた方法で、説明と意向の確かめを省かずに行います。", body:"保険会社によっては、郵送やインターネット、オンライン面談で申込みを受ける方法を用意しています。どの方法でも、ご本人の確かめ、ご意向の確認、契約概要と注意喚起情報の説明は省けません。会わずに書類だけを送り、記入して返してもらう形は、説明が届いたかを確かめられないので、認められた手順かを先に確かめます。", acts:["会わずに進めてよい方法があるかを、所属の保険会社の手引きで確かめる", "書類を送るときも、説明する日時を決めて、電話やオンラインで読み合わせる", "申込書の記入と署名は、必ずご本人にしていただく", "どの方法で説明し、どう確かめたかを面談の記録に残す"], actHead:"現場で使うなら", note:"使える申込みの方法・本人確認の仕方・説明の記録の残し方は、所属の保険会社と御社の手順で違う。迷ったらコンプライアンス担当へ。", go:"iko", say:"お忙しいところすみません。書類をお送りする前に、大事な点だけでも、画面越しかお電話で一緒に確かめさせてください。", more:"よくあるのは、ご家族の紹介で、契約者のご本人と一度も話さないまま書類だけが行き来する形です。この形だと、ご本人が内容を理解して決めたかを示せません。オンライン面談ができるなら、画面で書類を一緒に見ながら説明し、その日時を記録します。", why:"保険の説明は、お客様が分かったうえで決めたことを確かめる仕組みだからです。会わずに書類だけで進めると、説明が届いたか、ご本人の意思かが分からず、後で聞いていないという行き違いが起きやすくなります。" },
      { key:'faq_xcmp_ayamari', faq:1, grp:'cmp', q:"説明が間違っていたと後から気づいた", re:/(説明|お?伝え(し)?た(内容|こと)|案内)[^。]{0,10}(間違って|間違えて|間違えた|違って|誤って|誤り)|(間違った|誤った|違う)(説明|案内)を[^。]{0,6}(して|し)|(誤って|間違えて)[^。]{0,10}(説明|案内|伝え)(して|てい|た)/, ng:/部下|後輩|新人|メンバー|上司|研修|会社から|保険会社から|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"間違った説明に気づいたら、その日のうちに上長へ伝え、お客様に正しい内容を説明し直します。", body:"説明の間違いは、隠したり、自分だけで直そうとしたりすると、あとで大きな行き違いになります。まず上長に、いつ・誰に・何を・どう伝えたかを報告し、正しい内容を書面で確かめます。そのうえでお客様にお詫びし、正しい内容を説明し直します。申込みのあとなら、契約に影響があるかを、上長と保険会社に確かめてから連絡します。", acts:["いつ・誰に・何と伝えたかを、思い出せるまま上長へ報告する", "正しい内容を、約款・パンフレット・設計書で確かめてから連絡する", "お客様が考え直したいと言われたら、その気持ちを優先し、手続きを案内する", "説明し直した日と内容を、面談の記録に書き足す"], actHead:"今日やること", note:"申込み後の扱い・保険会社への報告の要否・お客様への伝え方は、所属の保険会社と御社の決まりで違う。上長とコンプライアンス担当で確かめてから連絡する。", go:"iko", say:"先日のご説明に誤りがありました。申し訳ありません。正しい内容を書面でお持ちしましたので、改めてご説明させてください。そのうえで、もう一度ゆっくり考えていただければと思います。", more:"間違いやすいのは、保障が始まる時期、支払われない場合、解約したときの扱い、受け取り方、特約の範囲です。直すときは、間違えた一言だけでなく、その前後の説明が正しかったかも一緒に確かめます。お客様が契約を見直したいと言われたら、どんな手続きがあるかを保険会社の決まりで確かめて案内します。", why:"お客様は、説明を土台に契約を決めているので、土台が違っていれば、決めた理由そのものが崩れるからです。早く直すほど、お客様が選び直せる道が残り、こちらへの信頼も保てます。" },
      { key:'faq_xcmp_yomu_jikan', faq:1, grp:'cmp', q:"書類を読む時間がないから早く済ませてと言われた", re:/(読む時間|読んでいる時間|説明(を聞く)?時間)[^。]{0,8}(ない|無い|取れな)|(説明|読み合わせ)(は)?(いい|いらない|要らない|省いて|はしょって|飛ばして)|(書面|書類|パンフレット)を読まずに|早く(済ませ|サイン|署名|終わらせ)[^。]{0,6}(て|たい)/, ng:/部下|後輩|新人|メンバー|上司|研修|会議|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"時間が無いと言われても、大事な点の説明は省かず、短く要点を読み合わせます。", body:"書面を読む時間が無い、説明はいいから早く、と言われることがあります。それでも、保障の始まる時期、支払われない場合、解約したときの扱い、告知の大切さといった大事な点は、要点だけでも一緒に確かめます。その日に時間が取れなければ、申込みを別の日にすることも選べます。", acts:["大事な点だけを指で示しながら、短く読み合わせる", "時間が足りなければ、続きを別の日にして、その場で申し込んでいただかない", "読み合わせたことと、お客様が急いでいた事情を面談の記録に残す"], actHead:"現場で使うなら", note:"省けない説明の項目と、申込みの前に確かめる書面は、所属の保険会社の手引きで決まっている。迷ったら上長とコンプライアンス担当で確かめる。", go:"iko", say:"お時間がない中ありがとうございます。大事なところだけ、短くご一緒に確かめさせてください。その場で決めていただく必要はありません。", more:"急いでいるお客様ほど、後で思っていたのと違うと感じやすくなります。説明を短くするコツは、全てを読み上げるのではなく、お客様にとって不利になりうる点に絞ることです。それでも時間が取れないときは、書面をお預けして、読んだあとに改めて会う日を決めます。", why:"説明を省いた契約は、お客様が不利な点を知らないまま決めたことになり、後で行き違いが起きたときに、お客様にも代理店にも大きな負担が残るからです。" },
      { key:'faq_xcmp_atsukai_nai', faq:1, grp:'cmp', q:"扱っていない会社の商品と比べてほしいと言われた", re:/(扱って(い)?ない|取り?扱い(の)?ない|取扱いのない|扱いのない|委託を受けて(い)?ない|委託のない|うちにない)[^。]{0,10}(会社|保険会社|保険|商品)[^。]{0,14}(比べ|比較|どっち|どちら|評判|違い)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"扱っていない会社の商品の優劣は言わず、扱っている範囲と、比べるときの見方を伝えます。", body:"委託を受けていない会社の商品は、こちらで中身を正しく確かめられず、説明する立場にもありません。優劣を言うと、根拠のない比較になり、他社をおとしめることにもなりかねません。代わりに、保障の範囲や支払いの条件、保険料の払い方など、比べるときに見る点を伝え、その会社の資料はその会社に確かめていただきます。", acts:["扱っている保険会社の範囲を、最初にはっきり伝える", "比べるときの見方（保障の範囲・支払いの条件・払う期間）を紙に書いてお渡しする", "その会社の商品の中身は、その会社の資料と窓口で確かめていただくよう伝える"], actHead:"現場で使うなら", note:"扱っていない会社の商品について話してよい範囲は、所属の保険会社と御社の比較推奨の方針で決まっている。迷ったらコンプライアンス担当へ。", go:"hikaku", say:"その会社の商品は私どもでは扱っていないので、良し悪しは申し上げられません。比べるときに見ていただきたい点を、紙にまとめますね。", more:"よくあるのは、お客様が別の代理店の設計書を持って来られる場面です。設計書を見て優劣を言うと、条件の違いを見落としたまま比べることになります。お客様と一緒に、ご意向に照らしてどこを比べればよいかを整理し、その会社の説明はその会社から受けていただきます。", why:"自分が中身を確かめていない商品を比べると、誤った比較や不当な比較になりやすく、お客様の判断を狂わせるからです。見方を渡すほうが、お客様が自分で比べる力になります。" },
      { key:'faq_xcmp_itaku_gai', faq:1, grp:'cmp', q:"委託を受けていない保険会社の商品を売ってもいい？", re:/(委託を受けて(い)?ない|委託のない|代理店契約(の|が)?(ない|無い)|取引(の|が)?ない|扱って(い)?ない|取り?扱い(の)?ない)[^。]{0,10}(会社|保険会社|保険)[^。]{0,14}(売|勧め|案内|申し込ませ|申込|募集|紹介)/, ng:/部下|後輩|新人|メンバー|比べ|比較|どっち|どちら|評判|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"委託を受けていない会社の商品は、募集できません。扱える会社の範囲で提案します。", body:"保険の募集ができるのは、委託契約を結んでいる所属の保険会社の商品だけです。代理店契約のない会社の商品を勧めたり、申込みの手続きを取り次いだりすると、決まりの外の募集になります。お客様がその会社の商品を望むときは、その会社や、その会社の代理店に相談していただくよう案内します。", acts:["自分が募集できる保険会社と商品の範囲を、社内の一覧で確かめておく", "範囲の外の商品を望まれたら、その会社の窓口へ相談していただくよう伝える", "見返りを受ける約束で、ほかの会社へお客様をつながない"], actHead:"現場で使うなら", note:"募集できる保険会社と商品の範囲・取り扱いを増やす手続きは、所属の保険会社との委託契約と御社の規程で決まっている。社内の担当とコンプライアンス担当で確かめる。", say:"その会社の保険は、私どもでは扱っておりません。詳しいご案内は、その保険会社の窓口でお受けいただけます。", more:"よくあるのは、まだ委託を受けていない会社の新しい商品を勧めたくなる場面です。取り扱いを増やすには、保険会社との委託契約と募集人の届出が先に要ります。手続きが済むまでは、商品の説明や設計書の作成もしないのが原則です。", why:"保険会社は、委託した代理店と募集人に対して、教育や管理の責任を負っているからです。委託のない会社の商品を扱うと、その責任の外で説明が行われ、間違いがあってもお客様を守る仕組みが働きにくくなります。" },
      { key:'faq_xcmp_tantou_henko', faq:1, grp:'cmp', q:"お客様から担当を変えてほしいと言われた", re:/担当(者)?(を|は)?[^。]{0,4}(変えて|替えて|代えて|外して|交代|変更して)[^。]{0,8}(ほしい|欲しい|くれ|ください|もらいたい|言われ|頼まれ)|(別の|ほかの|他の|違う)(人|方|担当|担当者)に[^。]{0,4}(担当|代わって|替わって)[^。]{0,6}(ほしい|欲しい|もらいたい|ください)|担当(者)?の(変更|交代)を[^。]{0,4}(求め|頼ま|言わ)/, ng:/部下|後輩|新人|メンバー|上司|退職|辞め|異動|引き継|引継|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)/, head:"担当を変えたいと言われたら、受け止めて理由を伺い、上長と相談して会社の手順で進めます。", body:"お客様から担当を変えてほしいと言われるのは、つらいことですが、お客様の正当な希望です。言い訳や引き止めをせず、話していただける範囲で理由を伺い、上長に伝えます。理由に説明や対応への不満が含まれていれば、苦情として記録します。新しい担当への引継ぎは、会社の手順で、契約や約束ごとを漏れなく渡します。", acts:["その場で反論せず、お礼と、会社として対応することを伝える", "理由は無理に聞き出さず、話していただいたことをそのまま記録する", "不満が含まれていれば、苦情の台帳にも記録する", "引継ぎの書類に、お客様との約束ごとと進めている手続きを書き出す"], actHead:"現場で使うなら", note:"担当の変更の手続き・引継ぎの範囲・苦情として扱うかは、御社の規程と所属の保険会社の決まりで違う。上長とコンプライアンス担当で確かめる。", go:"kujo", say:"ご希望を伺いました。至らない点があり申し訳ありません。会社で相談し、改めてご連絡いたします。", more:"よくある理由は、連絡が遅い、話が合わない、説明が押し付けがましい、といったものです。理由が自分にあると分かれば、ほかのお客様への接し方を見直す材料になります。新しい担当に代わったあとも、自分から連絡して引き止めるようなことはしません。引き継ぐときは、知っていることを正しく伝え、お客様に同じ話を何度もさせないようにします。", why:"担当者との関係は、お客様が安心して契約を続けるための土台だからです。希望が無視されると、契約そのものへの不信につながり、苦情や解約の原因にもなります。" },
      { key:'faq_xcmp_meibo_kau', faq:1, grp:'cmp', q:"名簿業者から買ったリストで営業してもいい？", re:/(名簿|リスト)[^。]{0,10}(買|購入)|名簿業者|(買った|購入した)[^。]{0,6}(名簿|リスト)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|紛失|なくし|失くし|漏れ|漏洩|漏えい/, head:"買ったリストを使う前に、出どころと取得の経緯を確かめ、御社と保険会社の決まりに従います。", body:"名簿の購入が認められるかは、御社と所属の保険会社の決まりが先です。個人情報を第三者から受け取る側には、相手がどう取得したかを確かめて記録する決まりがあります。不正に集めたと分かる名簿は使えません。勧誘の電話やダイレクトメールでも、断られた方に繰り返さない配慮が要ります。", acts:["使う前に、御社の規程と所属の保険会社の決まりで、購入した名簿が使えるかを確かめる", "業者から、名簿をどう集めたかの説明を書面で受け取り、残しておく", "お客様にどこで情報を知ったかを聞かれたら、正直に答える", "断られた方には二度と連絡しないよう、リストに印を付ける"], actHead:"現場で使うなら", note:"購入した名簿の扱いは、所属の保険会社と御社の個人情報の規程で決まっている。法律上の判断は個人情報保護委員会の窓口や弁護士で確かめる。", say:"突然のご連絡で失礼します。こちらの情報は、名簿の業者から入手したものです。ご不要でしたら、今後ご連絡いたしません。", more:"困るのは、お客様にどこで私の情報を知ったのかと聞かれて、答えられない場面です。出どころを答えられない名簿は使わないのが安全です。保険の勧誘の電話は、録音や時間帯の配慮も会社の決まりにあるので、あわせて確かめます。", why:"個人情報は、本人が知らないところで回ると、それだけで不信と苦情につながるからです。保険はお客様の暮らしの深い情報を扱う仕事なので、入口の情報の扱いが信頼の土台になります。" },
      { key:'faq_xcmp_shokai_jizen', faq:1, grp:'cmp', q:"紹介者から、紹介先の方の事情を先に聞いてもいい？", re:/(紹介者|紹介してくれる(人|方)|紹介元)[^。]{0,16}(事情|病気|借金|年収|収入|家族|詳しい|健康)[^。]{0,12}(聞|教え|知)|(紹介される(方|人)|紹介先)の[^。]{0,10}(事情|病気|借金|年収|家族)[^。]{0,10}(紹介者|事前|先に|会う前)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|契約したか|入ったのか|結果|紹介料/, head:"紹介者から聞く話は、ご本人が話してよいと思う範囲にとどめ、病気などは聞き出しません。", body:"紹介者が、相手の病気や借金、家族の事情まで先に教えてくれることがあります。ご本人の知らないところで深い事情を聞くと、面談でも知っている前提で話してしまいがちです。紹介者には、どんな方か、何に困っているかの大まかなところだけを伺い、詳しいことはご本人から直接伺います。健康のことは、告知の手続きの中で、ご本人に申告していただくものです。", acts:["紹介者には、ご本人に紹介のことを伝えてあるかを先に確かめる", "深い事情を話し始めたら、ご本人から直接伺いますと伝えて止める", "聞いてしまった話は記録に書かず、面談でもご本人が話すまで触れない"], actHead:"現場で使うなら", note:"紹介を受けるときの個人情報の扱いは、御社の個人情報の規程と所属の保険会社の決まりで確かめる。迷ったらコンプライアンス担当へ。", say:"ありがとうございます。詳しいことは、ご本人から直接お伺いしたいので、まずはご紹介いただけることをお伝えいただけますか。", more:"先に事情を知っていると、提案の準備はしやすく感じます。でも、ご本人がまだ話していないことを担当者が知っていると分かれば、紹介者との関係も、こちらへの信頼も傷つきます。告知に関わる病気の話を紹介者から聞いた場合も、告知はご本人の言葉で行っていただきます。", why:"個人情報は、本人から、本人が分かる目的で受け取るのが基本だからです。とくに健康や借金の情報は、知られたくない度合いが大きく、扱いを誤ると紹介そのものが止まってしまいます。" },
      { key:'faq_xcmp_doui', faq:1, grp:'cmp', q:"個人情報の取扱いの同意書は、何のために取る？", re:/個人情報[^。]{0,12}(同意|利用目的|取扱い|取り扱い)[^。]{0,12}(何のため|なぜ|理由|説明|どうす|聞かれ|サイン|取る)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|漏れ|漏洩|漏えい|紛失|なくし|失くし|消して|削除|見せて|開示/, head:"同意書は、何に使い誰に渡すかを知っていただき、納得のうえで情報を預かるためのものです。", body:"保険の手続きでは、お客様の情報を、代理店から保険会社へ渡したり、引受けの審査や保険金の支払いに使ったりします。同意書や利用目的の説明は、その使い道と渡す先を、お客様に前もって知っていただくためのものです。健康の情報のように慎重な扱いが要る情報もあるので、書面を見せながら、使い道を一つずつ伝えます。", acts:["同意書の利用目的と渡す先を、お客様と一緒に読み合わせる", "聞かれたら、保険会社の審査や手続きに使うことを、具体的な言葉で伝える", "同意をいただいた書面の控えの扱いを、会社の手順どおりにする"], actHead:"現場で使うなら", note:"同意書の様式・利用目的の書き方・控えの扱いは、所属の保険会社と御社の個人情報の規程で決まっている。細部は社内の担当とコンプライアンス担当で確かめる。", say:"こちらは、お預かりする情報を、何に使い、どこへお渡しするかをお知らせする書面です。分からないところがあれば、遠慮なくお聞きください。", more:"よくあるのは、同意書を手続きの一枚として流し、何に使うかを説明しない形です。お客様が後で、勝手に使われたと感じる原因になります。保険会社に渡すこと、ほかの目的には使わないこと、問い合わせ先がどこかの三つを伝えるだけでも、受け取り方が変わります。", why:"個人情報は、本人が知らない使い方をされたときに、最も強い不信を生むからです。使い道を先に伝えておけば、お客様は安心して情報を預けられ、後の行き違いも防げます。" },
      { key:'faq_xcmp_sakujo', faq:1, grp:'cmp', q:"お客様から、自分の情報を消してほしいと言われた", re:/(情報|個人情報|データ|名簿|リスト|連絡先)[^。]{0,10}(消して|削除|外して|消去|利用を?止め|利用を?停止)[^。]{0,8}(ほしい|欲しい|くれ|ください|求め|言われ|頼まれ)|(データ|情報)も消して/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|自分のスマホ|携帯の|捨てる|廃棄|見えて|bcc/, head:"消してほしいと言われたら、連絡を止め、会社の手順で削除や利用の停止を受け付けます。", body:"連絡をやめてほしい、情報を消してほしいと言われたら、まず営業の連絡を止めます。そのうえで、上長と御社の個人情報の窓口に伝え、会社の手順で受け付けます。契約が続いているお客様の情報や、法令や保険会社の決まりで残すことになっている記録は、消せないことがあるので、その場で全て消しますとは約束しません。", acts:["営業の連絡をすぐ止め、連絡しない方の印を付ける", "その日のうちに、上長と個人情報の窓口へ伝える", "消せるもの、残すものの説明は、会社の窓口から行っていただく"], actHead:"現場で使うなら", note:"削除や利用の停止の受け方・残す記録の範囲は、御社の個人情報の規程と所属の保険会社の決まりで決まっている。窓口とコンプライアンス担当で確かめる。", say:"かしこまりました。今後こちらからのご案内は控えます。情報の扱いについては、会社の担当から改めてご連絡いたします。", more:"担当者が自分の携帯の連絡先だけを消して済ませると、会社のシステムや名簿に残ったまま、別の人から連絡が行ってしまいます。どこに情報があるかを会社として洗い出し、手順に沿って止めるのが確実です。", why:"連絡を望まない方に連絡を続けることは、不快な思いをさせるだけでなく、苦情のもとになるからです。消せないものがある理由も会社から説明すれば、お客様の納得につながります。" },
      { key:'faq_xcmp_kenkou_joho', faq:1, grp:'cmp', q:"お客様の病気や健康の情報は、どう扱う？", re:/(病気|病歴|健康|持病|既往)(の|や)?[^。]{0,6}(情報|内容|こと)[^。]{0,10}(扱|保管|メモ|共有|しまう|持ち歩)|(告知書|医師の書類)の?(写し|コピー)[^。]{0,10}(保管|扱|置|しまう)|(病歴|持病)を[^。]{0,8}(メモ|書き留め|共有)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|診査|健康診断|見直|告知の書き方|告知義務|告知(し|す)|保険料|入れる|入れない/, head:"健康の情報は、とくに慎重に扱う情報です。必要な人だけが見られる形で、決まった場所に置きます。", body:"病気や通院、告知の内容は、知られたくない度合いの大きい情報で、法律でも慎重な扱いが求められています。告知書の写しや医師の書類は、会社が決めた場所と方法で保管し、持ち歩いたり、私物の手帳やスマホに書き写したりしません。社内で共有するのは、手続きに必要な人と範囲にとどめます。", acts:["告知書の写しや医師の書類の置き場所と持ち出しの決まりを、社内の規程で確かめる", "私物の手帳やスマホに、病名や通院の内容を書かない", "手続きが済んだ書類は、会社の手順どおりに返すか保管する"], actHead:"現場で使うなら", note:"健康の情報の取扱い・保管と廃棄の方法は、所属の保険会社と御社の個人情報の規程で決まっている。細部は社内の担当とコンプライアンス担当で確かめる。", say:"お伺いした健康のことは、手続きに必要な範囲だけで使い、決まった場所で大切にお預かりします。", more:"起きやすいのは、面談の帰りに鞄ごと置き忘れる、メモ帳に書いた病名を別のお客様の前で開く、といった事故です。持ち歩く書類を減らし、会社の決まった場所にすぐ戻すことが、いちばんの備えになります。", why:"健康の情報は、漏れたときにお客様の仕事や暮らしにまで影響することがあるからです。保険の仕事はこの情報を預かることで成り立っているので、扱いの丁寧さがそのまま信頼になります。" },
      { key:'faq_xcmp_rokuon_himitsu', faq:1, grp:'cmp', q:"お客様に伝えずに面談を録音してもいい？", re:/(伝えずに|知らせずに|黙って|こっそり|無断で|内緒で|断らずに)[^。]{0,14}(録音|録画)|(録音|録画)[^。]{0,8}(伝えず|知らせず|黙って|無断|内緒)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|電話|お客様が録音|お客様に録音された/, head:"録音するときは、目的を伝えてお客様の了承をいただき、会社の決まった方法で残します。", body:"言った言わないを防ぐために、面談を録音したいと考えることがあります。録音するなら、録音すること、何のために使うか、どう保管するかをお客様に伝え、了承をいただきます。会社が録音の方法や保管の決まりを持っている場合はそれに従い、私物のスマホに残したままにしません。了承を得られなければ、録音せずに面談の記録を丁寧に残します。", acts:["録音してよいか、どう保管するかを、御社の規程で先に確かめる", "面談の最初に、録音の目的と使い道を伝え、了承をいただく", "断られたら録音せず、面談のあとすぐに要点を記録に残す"], actHead:"現場で使うなら", note:"面談の録音の可否・了承の取り方・保管と消去の方法は、御社の規程と所属の保険会社の決まりで違う。法律上の判断は弁護士の領分。", say:"大事なお話なので、聞き違いがないよう、録音させていただいてもよろしいですか。内容を確かめるためだけに使います。", more:"黙って録音した音声は、後で見つかったときに、お客様の信頼を大きく損ないます。録音は、了承をいただいて初めて、お客様にとっても安心の材料になります。録音した音声にも個人情報が入るので、保管の場所と消す時期を会社の決まりで扱います。", why:"録音は、お客様の言葉と声をそのまま残すもので、知らないうちに残されるのを不快に感じる方が多いからです。了承を得た録音なら、双方の行き違いを防ぐ道具になります。" },
      { key:'faq_xcmp_rokuon_okyaku', faq:1, grp:'cmp', q:"お客様が面談を録音したいと言ってきた", re:/(お客様|お客さん)[^。]{0,10}(録音|録画)[^。]{0,10}(したい|させて|され|始め|しても|いいか)|(お客様|お客さん)に[^。]{0,8}(録音|録画)され/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|電話|こっそり|黙って|伝えずに|知らせずに/, head:"お客様の録音は断らずに受け止め、録音されても困らない、正確な説明を心がけます。", body:"お客様が説明を録音したいと言うのは、後で家族と確かめたい、聞き漏らしたくないといった理由が多くあります。断らずに受け止めるのが基本で、説明を正しく残す助けにもなります。録音されると分かったら、言い切りや、書面にないことを口だけで約束していないかを、いつも以上に気をつけます。", acts:["録音の申し出には、どうぞと伝え、説明の始めから録音していただく", "書面を指しながら説明し、口だけの約束をしない", "録音されたことを、面談の記録に書いておく"], actHead:"現場で使うなら", note:"お客様が録音したときの対応や記録の残し方は、御社の規程で確かめる。録音の内容をめぐる行き違いが起きたら、上長とコンプライアンス担当へ。", say:"どうぞ、録音していただいて構いません。あとでご家族と確かめるときにも、お役に立てばうれしいです。", more:"録音を嫌がるそぶりを見せると、お客様は何か隠しているのではと感じます。普段から、書面にないことを言わない、保障の範囲を言い切らない、という説明をしていれば、録音されても困ることはありません。録音は、自分の説明の仕方を振り返る機会にもなります。", why:"お客様が安心して決めるためには、説明をあとで確かめられることが助けになるからです。録音を受け止める姿勢そのものが、誠実に説明しているという信頼につながります。" },
      { key:'faq_xcmp_sns_tsunagaru', faq:1, grp:'cmp', q:"お客様とインスタやフェイスブックでつながってもいい？", re:/(インスタ|フェイスブック|facebook|instagram|sns|ツイッター)[^。]{0,12}(つなが|繋が|友達申請|フォロー|コメント)|(お客様|契約者)の(投稿|sns)[^。]{0,8}(コメント|いいね|フォロー)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|発信|載せ|宣伝|広告|ライン|line|調べ|下調べ/, head:"つながるかは会社の決まりに従い、つながっても、契約や健康の話はSNSでしません。", body:"お客様とSNSでつながることを、会社の規程で決めている代理店や保険会社があります。認められている場合でも、契約の内容や健康、お金の相談は、SNSのメッセージやコメントで扱わず、会社が認めた連絡の方法に移します。お客様の投稿に、契約を知っているからこそ分かることを書き込むのも避けます。", acts:["お客様とSNSでつながってよいかを、御社の規程で確かめる", "つながったら、仕事用と私用の使い分けを決めておく", "相談のメッセージが来たら、会社の連絡の方法で改めて返事をする"], actHead:"現場で使うなら", note:"お客様とSNSでつながること・メッセージの扱いは、御社のSNSの規程と所属の保険会社の決まりで違う。迷ったらコンプライアンス担当へ。", say:"SNSでもつながっていただき、ありがとうございます。保険のご相談は、お電話か面談で、きちんと伺いますね。", more:"困るのは、ほかの人も見られるコメント欄に、先日のご入院は大丈夫でしたか、のように書いてしまう場面です。お客様は、保険の担当者とのつながりも、健康のことも、周りに知られたくないかもしれません。いいねやコメントをするときも、その一言で何が伝わるかを考えます。", why:"SNSは、ふだんの付き合いと仕事のやりとりの境目があいまいになりやすいからです。境目を決めておけば、お客様の情報を守りながら、気軽なつながりも続けられます。" },
      { key:'faq_xcmp_sns_shirabe', faq:1, grp:'cmp', q:"面談の前に、お客様のことをSNSで調べてもいい？", re:/(sns|インスタ|フェイスブック|facebook)[^。]{0,8}(で|を)[^。]{0,4}(調べ|下調べ|見て|検索)|(お客様|見込み客|紹介された(方|人))[^。]{0,10}(sns|インスタ|フェイスブック)[^。]{0,10}(調べ|見|下調べ)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|発信|投稿して|載せ|宣伝|広告|つなが|繋が|友達申請|フォロー|コメント|調べてき|調べて来|調べてく/, head:"公開されている範囲を話題づくりに見るのは控えめに。見た情報を、知っている前提で話しません。", body:"お客様が公開している投稿でも、本人の知らないところで集めて営業に使うと、のぞかれたと感じる方がいます。会社の情報や、お客様が自分で発信していることを、話題の参考に軽く見る程度にとどめ、家族構成や暮らしぶりを調べ上げることはしません。面談では、SNSで見た話を出さず、ご本人から伺います。", acts:["調べてよい範囲を、御社の規程で確かめておく", "SNSで見たことは記録に書かず、面談でご本人から伺い直す", "家族や子どもの写真など、営業に使わない情報には触れない"], actHead:"現場で使うなら", note:"お客様の情報をネットで集めることの扱いは、御社の個人情報の規程と所属の保険会社の決まりで確かめる。迷ったらコンプライアンス担当へ。", say:"今日は、ご家族のことや、お仕事のことを、少し伺ってもよろしいですか。", more:"下調べで知った、お子さんの学校や旅行先の話を口にすると、お客様は驚き、警戒します。話題の準備は、会社のホームページや業界の動きのように、相手が知られてもよいと考える情報で行うのが安全です。", why:"個人情報は、本人が分かる形で受け取るのが信頼の基本だからです。調べたことを知らずに話されると、お客様は自分のことがどこまで見られているのか分からず、不安になります。" },
      { key:'faq_xcmp_boshu_bunsho', faq:1, grp:'cmp', q:"どんな資料が募集文書になる？", re:/募集文書[^。]{0,8}(当たる|なる|入る|とは|範囲|どんな)|(どんな|どの)(資料|書類|もの)が[^。]{0,4}募集文書|(提案書|比較表|チラシ|資料|手作り)[^。]{0,14}(審査|承認|募集文書)[^。]{0,6}(要る|必要|当たる|受け)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|最安|業界一|作り直|期限|ロゴ|体験談/, head:"契約を勧めるためにお客様に見せる資料は、自作でも募集文書として扱うのが基本です。", body:"保険会社のパンフレットや設計書だけでなく、自分で作った提案書、比較表、チラシ、ホームページやSNSの投稿も、保険の契約を勧める目的でお客様に見せるなら、募集文書として扱われることが多くあります。多くの保険会社は、募集文書を使う前に審査や承認を受ける手順を決めています。どこまでが対象かは、保険会社と御社の決まりで確かめます。", acts:["自分で作った資料を使う前に、審査が要るかを保険会社と社内で確かめる", "承認を受けた資料は、承認の番号や期限を控えておく", "審査を受けていない資料は、お客様に見せない"], actHead:"現場で使うなら", note:"募集文書の範囲・審査と承認の手順・表示のきまりは、所属の保険会社の手引きと御社の規程で決まっている。広告の担当とコンプライアンス担当で確かめる。", say:"お見せしている資料は、保険会社の確認を受けたものです。詳しくは、契約概要と注意喚起情報で一緒に確かめましょう。", more:"迷いやすいのは、手書きの図や、その場で書いた数字のメモです。保険料や返戻金の数字を書いて渡すと、それが比較や約束のように受け取られることがあります。説明のためのメモは手元に残し、お渡しするのは承認を受けた資料と設計書にすると安全です。", why:"募集文書は、お客様が契約を決める材料になるので、誤解を招く書き方や不当な比較があると、お客様の判断を狂わせるからです。審査の手順は、その誤りを使う前に見つけるためにあります。" },
      { key:'faq_xcmp_kigen_gire', faq:1, grp:'cmp', q:"承認の期限が切れたパンフレットを使ってもいい？", re:/(期限|使用期限|有効期限)[^。]{0,6}(切れ|過ぎ)[^。]{0,10}(パンフ|資料|チラシ|募集文書|設計書)|(古い|改定前の|前の版の|旧版の)(パンフ|資料|チラシ|募集文書)|(パンフ|資料|チラシ)[^。]{0,6}(期限|使用期限)[^。]{0,4}(切れ|過ぎ)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|自動車|免許|保険証|作り直|ないように|防ぎたい|防ぐ|管理/, head:"期限の切れた資料は使いません。手元から外し、今の版の資料に差し替えます。", body:"募集に使う資料には、保険会社の承認の期限や、商品の改定に合わせた版があります。期限が切れた資料や改定前の資料は、保険料や保障の内容が今と違うことがあり、お客様の誤解のもとになります。手元に古い資料が残っていたら使わずに外し、今の版を取り寄せます。もう渡してしまったと気づいたら、上長に伝え、正しい資料を届けて説明し直します。", acts:["鞄や机の資料の承認の期限と版を、定期的に見直す", "古い資料は、会社の手順どおりに回収し、処分する", "古い資料を渡したお客様には、上長と相談して正しい資料で説明し直す"], actHead:"現場で使うなら", note:"資料の承認の期限・版の見分け方・回収の手順は、所属の保険会社と御社の規程で決まっている。広告の担当とコンプライアンス担当で確かめる。", say:"先日お渡しした資料に、古い版が混ざっていました。申し訳ありません。今の内容の資料をお持ちしましたので、改めてご説明します。", more:"起きやすいのは、営業車や自宅に置いた資料の束から、確かめずに一部を出してしまう場面です。持ち歩く資料を減らし、出かける前に版を確かめる習慣にすると防げます。商品の改定のお知らせが来たら、その日のうちに古い版を外します。", why:"古い資料は、今は無い保障や、今と違う保険料を示していることがあり、お客様の判断をゆがめるからです。承認の期限は、資料の中身が今も正しいことを保つための仕組みです。" },
      { key:'faq_xcmp_logo', faq:1, grp:'cmp', q:"保険会社のロゴを、自分の代理店のチラシに使ってもいい？", re:/(保険会社|取扱保険会社|取り扱い保険会社)(の)?(ロゴ|マーク|商標)[^。]{0,14}(使|載せ|入れ|並べ)|(ロゴ|マーク)[^。]{0,10}(チラシ|ホームページ|名刺|看板)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|自分の(会社|代理店)のロゴ|自社のロゴ/, head:"保険会社のロゴや社名の使い方は、保険会社が決めています。使う前に承認を受けます。", body:"保険会社のロゴやマークは、その会社のものです。チラシやホームページ、名刺に使うときは、保険会社が決めた使い方の決まりに従い、多くの場合は事前の承認が要ります。ロゴを大きく出すと、保険会社そのものの広告や、保険会社の社員のように見えることもあるので、代理店の名前と立場が分かる見せ方にします。", acts:["使いたい場所と見せ方を決めて、保険会社の担当者に承認の手順を聞く", "保険会社から渡された正しいロゴのデータだけを使う", "代理店の名前と、どの保険会社の代理店かを、同じ面に分かるように書く"], actHead:"現場で使うなら", note:"ロゴの使い方・承認の手順・表示のきまりは、所属の保険会社の手引きで決まっている。代理店担当者と御社の広告の担当で確かめる。", say:"私どもは、これらの保険会社の代理店として、商品をご案内しています。", more:"迷いやすいのは、ネットから拾った画像を使う、色や形を変える、複数の会社のロゴを並べて一つだけ大きく見せる、といった使い方です。どれも保険会社の決まりに触れることがあります。保険会社に渡されたデータを、そのままの形で使います。", why:"ロゴは、お客様が誰の商品で、誰が説明しているかを見分ける目印だからです。使い方を誤ると、保険会社の社員だと誤解されたり、保険会社が勧めているように見えたりします。" },
      { key:'faq_xcmp_meishi', faq:1, grp:'cmp', q:"名刺に保険のプロや専門家と書いてもいい？", re:/(名刺|肩書|プロフィール)[^。]{0,14}(プロ|専門家|スペシャリスト|エキスパート|資格|実績|第一人者)[^。]{0,10}(書|入れ|並べ|載せ|名乗)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|ロゴ|マーク|取る|取った|勉強/, head:"肩書きは、持っている資格と実際の立場を正しく書き、誤解を招く言い方を避けます。", body:"名刺やプロフィールの肩書きは、お客様が担当者を信頼する手がかりになります。持っていない資格を名乗る、期限の切れた資格を書く、実績を大きく見せる、保険会社の社員のように見える書き方をする、といったことは、お客様の誤解を招きます。名刺の表示にも、保険会社や御社の決まりがあることが多いので、作る前に確かめます。", acts:["書く資格が、今も有効か、正式な名前かを確かめる", "実績の数字を書くなら、何を数えたかと時点を確かめられるものだけにする", "名刺の案を、上長と保険会社の決まりで確かめてから刷る"], actHead:"現場で使うなら", note:"名刺やプロフィールの表示のきまりは、所属の保険会社の手引きと御社の規程で決まっている。資格の名乗り方は、それぞれの資格の団体の決まりで確かめる。", say:"私は、この代理店で保険のご案内を担当しております。持っている資格は、こちらに書いてあるとおりです。", more:"よくあるのは、勉強中の資格を取得したように書く、相続や税金の専門家を名乗って、税理士や弁護士の仕事まで引き受けるように見せる、といった書き方です。専門家と書くほど、お客様はその分野の判断まで任せてよいと受け取ります。", why:"肩書きは、お客様がどこまで相談してよいかを決める手がかりになるからです。実際より大きく見せると、担当の範囲を超えた相談を受けてしまい、お客様に不利益を与えるおそれがあります。" },
      { key:'faq_xcmp_mail_annai', faq:1, grp:'cmp', q:"見込み客に、案内のメールをまとめて送ってもいい？", re:/(案内|宣伝|広告|営業)[^。]{0,4}(の)?メール[^。]{0,10}(まとめて|配信|送りたい|送っても|送ろう|送る)|(メールマガジン|メルマガ)[^。]{0,10}(配信|送|始め)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|bcc|宛先|見えて|返事|返信|満期|更新|更改/, head:"宣伝のメールは、受け取ることに同意した方に送り、送り主と配信の止め方を書くのが原則です。", body:"広告や宣伝のメールは、相手から受け取ることへの同意を前もっていただいて送るのが原則で、送り主の名前や、配信を止める方法を書くことも求められます。名刺交換の扱いなど、同意が要らない場合の線は細かく決まっているので、迷ったら同意をいただいてから送るのが安全です。メールの中身も募集文書として扱われることがあるので、審査の手順も確かめます。", acts:["送る相手から、案内のメールを受け取る同意をいただいているかを確かめる", "メールに、送り主と問い合わせ先と配信を止める方法を書く", "配信を止めたいと言われたら、すぐに送る先から外す", "メールの文面を、募集文書の審査に回すかを確かめる"], actHead:"現場で使うなら", note:"宣伝のメールの同意と表示のきまりは、特定電子メールの決まりと所属の保険会社・御社の規程で確かめる。細部は迷惑メールの相談窓口や御社の担当へ。", say:"今後、保険や暮らしのお金に関するご案内を、メールでお送りしてもよろしいですか。不要になれば、いつでも止められます。", more:"宛先が見えるまま送る事故は、別の答えで扱っています。ここで大事なのは、送ってよい相手かどうかです。同意をいただいた日と方法を、送る先の一覧に一緒に残しておくと、後で聞かれたときに答えられます。", why:"頼んでいない宣伝のメールは、受け取る人の負担になり、迷惑メールとして苦情を招くからです。同意と止め方を先に用意しておけば、受け取る人も安心して読めます。" },
      { key:'faq_xcmp_seminar', faq:1, grp:'cmp', q:"セミナーのあと、その場で申込みを受けてもいい？", re:/(セミナー|勉強会|相談会|説明会)[^。]{0,16}(その場で|すぐに|会場で|終わりに)[^。]{0,10}(申込|申し込|契約)|(セミナー|勉強会|相談会)の(あと|後)[^。]{0,8}(申込|申し込|契約)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|集客|集め|話す|講師|メール/, head:"セミナーの場では申込みを急がせず、個別の面談で、ご意向と説明の手順を踏んでから進めます。", body:"セミナーや勉強会は、知識を届ける場です。その場で申込書を配って書いてもらう形は、周りの雰囲気に押されて決める方が出やすく、ご意向の確かめや重要事項の説明も一人ずつ十分にできません。関心を持った方とは個別の面談の日を決め、会社の手順で説明してから申込みを受けます。セミナーの案内や資料が募集文書に当たるかも、事前に確かめます。", acts:["セミナーの最後は、個別の相談の希望を伺う紙を配るまでにする", "申込みは、日を改めた面談で、意向の確かめと説明をしてから受ける", "セミナーの資料と案内文を、事前に保険会社と社内の審査に回す"], actHead:"現場で使うなら", note:"セミナーでの募集の扱い・資料の審査の手順は、所属の保険会社の手引きと御社の規程で決まっている。迷ったらコンプライアンス担当へ。", go:"iko", say:"本日はありがとうございました。気になったことは、個別にゆっくり伺います。その場で決めていただく必要はありません。", more:"起きやすいのは、会場の熱気の中で何人かが申し込むと、ほかの方も遅れまいと続く場面です。後で冷静になったときに、勧められて決めたと感じる方が出ます。セミナーは信頼を得る場、申込みは一人ずつの面談の場、と分けて考えます。", why:"大勢の前では、一人ひとりのご意向や事情を確かめられず、周りに合わせて決めてしまう方が出るからです。日を改めることで、お客様が自分の考えで決めたと言える形になります。" },
      { key:'faq_xcmp_mokuteki', faq:1, grp:'cmp', q:"保険の話と言わずにアポを取ってもいい？", re:/(保険の話|保険のこと|保険の案内|目的)[^。]{0,4}(と言わず|を言わず|を伏せ|を隠し|を告げず|と言わない)|(ライフプラン|家計|お茶|食事|雑談)[^。]{0,10}(と言って|と誘って|で誘って|でもと誘って)[^。]{0,16}(保険|勧め)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|招待|ご馳走|おごる|奢る|接待/, head:"会う約束のときに、保険のご案内の目的があることを伝えます。目的を隠して会いません。", body:"会ってから保険の話を始めると、お客様は、だまされたと感じます。訪問や面談の約束をするときは、保険のご案内や見直しの相談が目的に入っていることを、前もって伝えます。ライフプランや家計の相談として会う場合も、保険のご提案をすることがあると伝えておくと、お客様は安心して時間をとってくれます。", acts:["アポの電話やメッセージで、保険のご案内の目的があることを一言添える", "当日の最初に、今日は何の話をするかを改めて伝える", "目的と違う話になったら、続けてよいかを伺う"], actHead:"現場で使うなら", note:"勧誘の前に目的を伝えることの扱いは、御社の勧誘方針と所属の保険会社の決まりで確かめる。迷ったら上長とコンプライアンス担当へ。", say:"今回は、保険の見直しも含めて、暮らしのお金のお話をさせていただけたらと思っています。", more:"気をつけたいのは、知人として食事に誘い、途中から保険の話に切り替える形です。断りにくい関係ほど、お客様は後で不満を抱えます。最初に目的を伝えて断られたなら、それはお客様の答えとして受け止めます。", why:"目的を知って会うかどうかを選ぶことは、お客様の自由な判断の出発点だからです。目的を隠した面談は、その後の説明がどれだけ丁寧でも、信頼の土台を欠いたものになります。" },
      { key:'faq_xcmp_hizuke', faq:1, grp:'cmp', q:"申込書の日付を、月末に合わせてずらしてもいい？", re:/(申込書|申込日|申し込み日|申込みの日付)[^。]{0,8}(日付)?[^。]{0,10}(ずら|空けた|空欄|さかのぼ|前倒し|後ろ倒し)|((申込書|申込み|申し込み)の?日付|申込日|申し込み日)[^。]{0,10}(書き換|変え)|(違う|別の)日付を[^。]{0,4}(入れ|書)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|不備|訂正印|書き間違|意向|記録/, head:"申込書の日付は、お客様が実際に書いた日のままにし、空けたまま預かったりずらしたりしません。", body:"申込書の日付は、お客様がいつ申し込んだかを示す大事な記録です。数字の締めに合わせて日付をずらす、空けたまま預かって後で入れる、といった扱いは、記録の作り変えになり、保障が始まる日や告知の時期にも関わります。締めに間に合わないときは、その月の数字にならないことを受け入れます。", acts:["日付は、お客様に、その場で書いていただく", "締め日に追われて日付を変えたくなったら、上長に相談する", "書き間違いの直し方は、保険会社の決まった方法で行う"], actHead:"現場で使うなら", note:"申込書の日付の書き方・訂正の仕方は、所属の保険会社の手引きで決まっている。迷ったら上長とコンプライアンス担当へ。", say:"本日の日付で、こちらにご記入をお願いします。日付は、ご記入いただいた日をそのまま書いていただく決まりです。", more:"言われやすいのは、上長や同僚からの、今月の数字にしたいから日付を合わせて、という声です。日付を動かすと、保障が始まる日がずれる、告知と日付が合わない、といった問題がお客様の側に出ます。断る理由として、お客様のためだと伝えます。", why:"申込みの日付は、いつからお客様を守るか、いつの健康状態で引き受けたかの基準になるからです。日付を動かすことは、お客様の保障そのものを危うくします。" },
      { key:'faq_xcmp_hakushi', faq:1, grp:'cmp', q:"白紙の申込書に、先にサインだけもらってもいい？", re:/(白紙|空欄)[^。]{0,10}(申込書|書類|用紙)?[^。]{0,10}(サイン|署名|押印|印鑑)|(サイン|署名|押印)(だけ)?[^。]{0,8}(先に|預か|もらって|してもら)[^。]{0,10}(後で|後から|あとで|あとから)|(後で|後から|あとで|あとから)[^。]{0,10}(記入|書く|書き)[^。]{0,10}(サイン|署名|押印)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|名義|代筆|代わりに書|家族が|奥様が|ご主人が/, head:"白紙や空欄のある書類に、先に署名をもらいません。内容を書いてから署名いただきます。", body:"署名や押印は、お客様が書類の内容を確かめて、それで申し込むと示すものです。白紙や空欄のある書類に先に署名をもらうと、後から書いた内容が、お客様の意思と違っていても見分けられません。お客様が承知していても、担当者が中身を書き入れる形は、作成契約や記録の作り変えを疑われます。内容を全て書き、読み合わせてから署名いただきます。", acts:["書類は、記入の欄を全て埋めてからお客様にお渡しする", "お客様に書いていただく欄は、お客様ご自身に書いていただく", "時間が無ければ、日を改めて、そろった書類で署名いただく"], actHead:"現場で使うなら", note:"申込書の記入と署名のきまり・代筆の扱いは、所属の保険会社の手引きで決まっている。迷ったら上長とコンプライアンス担当へ。", say:"中身を全てご確認いただいてから、最後にご署名をお願いします。", more:"よくあるのは、お客様が忙しく、二度も会うのは悪いと考えて、先に署名だけもらっておこうとする場面です。そのひと手間を省くと、後で、こんな内容で頼んでいないと言われたときに、守る材料がありません。署名は最後、と決めておきます。", why:"署名は、お客様がその内容に同意したことを示す大事な証だからです。白紙の署名は、その証を空っぽにし、お客様と担当者の両方を危うくします。" },
      { key:'faq_xcmp_houjin_shomei', faq:1, grp:'cmp', q:"法人契約の申込書を、社長以外の方が書いてもいい？", re:/(法人|会社|法人契約)[^。]{0,14}(申込書|署名|申込み|申し込み)[^。]{0,14}(社長以外|代表者以外|経理|総務|代わりに|代理で)|(社長|代表者)(が忙しい|の代わり|以外)[^。]{0,14}(申込書|署名|書いて)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|意向|ご意向|希望|被保険者の同意/, head:"法人の申込書は、権限のある方が署名します。代わりの方で足りるかは保険会社の決まりで確かめます。", body:"法人の契約では、会社を代表して契約する権限のある方の署名が要ります。代表者でなくても、権限を任された方が署名できる場合がありますが、その範囲と確かめ方は保険会社の手引きで決まっています。経理や総務の方に、権限を確かめずに書いていただくと、後で会社として申し込んだかが争いになることがあります。被保険者になる方の同意は、別に要ります。", acts:["申込みの前に、署名する方と、その権限の確かめ方を保険会社の手引きで確かめる", "社長に会えないときも、目的と内容は社長に確かめ、記録に残す", "被保険者になる方の同意を、別にいただく段取りを組む"], actHead:"現場で使うなら", note:"法人の申込みの署名者・権限の確かめ方・必要な書類は、所属の保険会社の手引きで決まっている。会社の決まりごとの判断は、顧問の弁護士の領分になることがある。", go:"iko", say:"こちらのご契約は、会社としてのお申込みになるので、お申込みいただく方を確かめさせてください。", more:"よくあるのは、社長の印鑑を経理の方が預かっていて、そのまま押してもらう形です。印鑑が本物でも、社長が内容を知らなければ、会社の意思で決めたとは言いにくくなります。短い時間でも社長と話し、何のための契約かを伺ってから進めます。", why:"法人の契約は会社のお金の使い方を決めるもので、誰が決めたかが後で問われやすいからです。権限のある方の意思を確かめておけば、会社とお客様の両方を守れます。" },
      { key:'faq_xcmp_kashikari', faq:1, grp:'cmp', q:"お客様とお金の貸し借りをしてもいい？", re:/(お客様|お客さん|顧客|契約者)[^。]{0,12}(お金|金銭)[^。]{0,8}(貸し借り|貸して|借り|貸す|貸し)|(お金|金銭)の(貸し借り|貸借)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|保険料|立て替|立替|契約者貸付|貸付制度|ローン|役員/, head:"お客様とのお金の貸し借りはしません。頼まれても、丁寧にお断りします。", body:"担当者とお客様のお金の貸し借りは、親しい間柄でも、断りにくい関係を生み、契約の判断をゆがめます。多くの保険会社や代理店は、お客様との金銭の貸し借りを禁じる決まりを持っています。お客様からお金に困っていると相談されたら、公的な相談窓口や、使える保険の仕組みがあるかを、会社の手順で確かめて案内します。", acts:["頼まれたら、会社の決まりで貸し借りができないことを伝えて断る", "お金に困っている事情を伺ったら、上長に相談し、案内できる窓口を確かめる", "自分が借りる立場の話も、どんなに親しくても受けない"], actHead:"現場で使うなら", note:"お客様との金銭の貸し借りの決まりは、所属の保険会社と御社の規程で決まっている。お金の困りごとの窓口は、自治体や公的な相談窓口で確かめる。", say:"お力になりたい気持ちはあるのですが、会社の決まりで、お客様とのお金のやりとりはできません。ほかに使える仕組みがないか、一緒に考えさせてください。", more:"起きやすいのは、長い付き合いのお客様に、少しの額だけと頼まれる場面です。一度応じると、次の契約の話や解約の相談で、お互いに言いたいことが言えなくなります。保険の契約者貸付が使えるかは、保険会社の決まりで確かめて案内します。", why:"お金の貸し借りがあると、お客様は担当者に勧められた契約を断りにくくなり、担当者もお客様に不利な点を言いにくくなるからです。契約の判断を、お金の関係から切り離しておくためです。" },
      { key:'faq_xcmp_tsucho', faq:1, grp:'cmp', q:"お客様の通帳やキャッシュカードを預かってもいい？", re:/(通帳|キャッシュカード|印鑑|実印|暗証番号)[^。]{0,10}(預か|預け|持ち帰|借り)|(代わりに|代理で)[^。]{0,6}(お金を)?(下ろ|引き出|振り込)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|保険証券|証券を|証書|法人|会社の|社長/, head:"通帳やカード、印鑑は預かりません。手続きはお客様ご自身にしていただきます。", body:"通帳やキャッシュカード、印鑑、暗証番号は、お客様の財産そのものに結びつくものです。預かったり、代わりにお金を下ろしたりすると、なくしたときや、お金の出入りが問題になったときに、担当者の責任が問われ、着服を疑われることもあります。多くの保険会社や代理店は、こうしたものを預からない決まりを持っています。手続きに要る情報は、お客様の目の前で書き写していただきます。", acts:["頼まれても、会社の決まりで預かれないことを伝える", "口座の情報が要る書類は、お客様に書いていただき、その場で確かめる", "お客様が手続きに困っているなら、ご家族や窓口の手助けを案内する"], actHead:"現場で使うなら", note:"お客様の通帳・印鑑などの扱いの決まりは、所属の保険会社と御社の規程で決まっている。迷ったら上長とコンプライアンス担当へ。", say:"大事なものなので、お預かりはできません。書類のこの欄だけ、通帳を見ながらご記入いただけますか。", more:"よくあるのは、ご高齢のお客様に、面倒だから預かって手続きしておいて、と頼まれる場面です。親切のつもりで預かると、後でご家族から疑われる原因になります。ご本人ができないときは、ご家族の同席や、保険会社の手続きの方法を相談します。", why:"お客様の財産に直接触れると、どれだけ誠実にしても、後で疑いを晴らす材料がないからです。預からないことが、お客様と担当者の両方を守ります。" },
      { key:'faq_xcmp_shiharai_yakusoku', faq:1, grp:'cmp', q:"保険金が出るかどうか、その場で答えてもいい？", re:/(保険金|給付金|保険で)[^。]{0,10}(出るか|出ます|出る|支払われ|払われ)[^。]{0,14}(その場で|答え|約束|言って|言い切|聞かれ)|(たぶん|きっと)[^。]{0,6}(支払われ|出ます|払われ)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|税|非課税|課税|相続|時効|期限|請求の仕方|手続きの|いつ|口座|受取人|代理請求/, head:"支払うかを決めるのは保険会社です。その場で出るとも出ないとも言い切らず、確かめます。", body:"保険金や給付金を支払うかは、約款と、事故や病気の事実をもとに、保険会社が判断します。担当者がその場で、出ます、大丈夫です、と言うと、支払われなかったときに、言われたのに、という強い苦情になります。逆に、出ないと言い切って、請求の機会を失わせることもあってはなりません。約款のどこに当たりそうかを伝えたうえで、請求の手続きを案内します。", acts:["その場では、支払いを判断するのは保険会社だと伝える", "請求に要る書類と手順を、保険会社の決まりで確かめて案内する", "出ないと思っても、請求するかどうかはお客様に決めていただく"], actHead:"現場で使うなら", note:"支払いの判断・請求の手順は、所属の保険会社の約款と手引きで決まっている。迷ったら保険会社の支払いの窓口と上長へ。", say:"お支払いできるかは、保険会社が書類を見て判断します。請求の手続きを、一緒に進めさせてください。", more:"よくあるのは、お客様を安心させたくて、たぶん大丈夫ですよと言ってしまう場面です。その一言は、お客様の中では約束として残ります。支払いの条件で迷うところは、保険会社の窓口に確かめてから伝えると、結果がどちらでも信頼を失いません。", why:"支払いの判断は、約款と事実を確かめる専門の手続きで、担当者の見込みとは違うことがあるからです。言い切らずに請求を勧めれば、お客様が受け取れるものを受け取り損ねることも防げます。" },
      { key:'faq_xcmp_souzoku_soudan', faq:1, grp:'cmp', q:"相続の分け方の相談に乗ってもいい？", re:/(遺産|相続)[^。]{0,6}(の)?(分け方|分割|分ける|揉め|もめ)[^。]{0,12}(相談|アドバイス|間に入|乗って|教え|言われ|頼まれ)|遺言(書)?の(書き方|作り方)[^。]{0,8}(教え|頼まれ|手伝)|(遺産|相続)をどう分け/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|相続税|保険金|受取人|非課税|順番|誰になる|放棄/, head:"分け方の判断や揉めごとの間に入るのは、弁護士などの領分です。保険でできることだけを伝えます。", body:"遺産をどう分けるか、遺言をどう書くか、相続人どうしの争いにどう対応するかは、法律の判断が絡み、弁護士や司法書士、税の面では税理士の領分です。保険の担当者が分け方を勧めたり、揉めごとの間に入って交渉したりすると、担当の範囲を超えます。保険でできるのは、受取人の指定や、相続のときに使えるお金の準備など、保険の仕組みの説明までです。", acts:["分け方や遺言の相談を受けたら、弁護士や司法書士、税理士につなぐ", "保険で備えられることと、備えられないことを分けて伝える", "揉めごとの話では、どちらかの立場に立つ発言をしない"], actHead:"現場で使うなら", note:"相続の分け方・遺言・相続人の争いは、弁護士や司法書士の領分。相続税は税理士。保険でできることの説明の範囲は、所属の保険会社の手引きで確かめる。", say:"分け方のご相談は、専門の先生にお話しされるのがよいと思います。保険でお役に立てるところは、私からご説明します。", more:"起きやすいのは、長い付き合いのお客様に、あなたの意見を聞きたいと頼まれる場面です。その一言が、ほかの相続人には、担当者が一方の味方をしたと映ります。保険の役目を伝えたうえで、専門の先生を交えた場をつくるお手伝いにとどめます。", why:"相続の分け方は、家族の関係と法律の判断が重なるところで、間違えると取り返しがつかない争いになるからです。担当の範囲を守ることで、家族のどなたからも信頼される立場でいられます。" },
      { key:'faq_xcmp_kenmei', faq:1, grp:'cmp', q:"お客様に、保険会社の社員だと思われている", re:/(保険会社の社員|保険会社の人|保険会社の方)[^。]{0,6}(だと|と)[^。]{0,4}(思われ|勘違い|誤解)|(どこの会社の人|どこの会社の方)[^。]{0,6}聞かれ|(契約を決められる|あなたが決められる)[^。]{0,6}聞かれ|代理店と保険会社の違い[^。]{0,8}(お客様|説明)/, ng:/部下|後輩|新人|メンバー|と(言|伝え)(って|て)(も)?(いい|よい|大丈夫)|乗合|専属/, head:"所属する保険会社の名前と、代理店としてどんな立場で手続きするかを、最初にはっきり伝えます。", body:"お客様は、保険の担当者を保険会社の社員だと思い込んでいることがあります。募集のときは、どの保険会社の代理店か、そして契約を結ぶ権限を持つ代理か、保険会社へ取り次ぐ媒介かという立場を、お客様に明らかにすることが求められています。名刺や最初の説明で、所属の保険会社と自分の立場を伝えます。", acts:["名刺や最初の説明で、所属の保険会社の名前を伝える", "自分が代理として契約を結べるのか、媒介として取り次ぐのかを、保険会社の決まりで確かめて伝える", "お客様の誤解に気づいたら、その場で正しく言い直す"], actHead:"現場で使うなら", note:"所属の保険会社の明らかにし方・代理か媒介かの区別は、所属の保険会社との委託契約と手引きで決まっている。代理店担当者とコンプライアンス担当で確かめる。", say:"私は、こちらの保険会社から委託を受けた代理店の担当として、ご案内しています。", more:"誤解が起きやすいのは、保険会社のロゴの入った資料だけで説明している場面です。代理か媒介かで、契約を結ぶのが誰かが違います。違いを分かる言葉で伝えておくと、後で聞いていなかったという行き違いを防げます。", why:"お客様は、誰と契約し、誰に責任を問えるのかを知ったうえで決める必要があるからです。立場をはっきりさせることが、お客様の判断の土台になります。" },
      /* dun.json */
      { key:'faq_xdun_itaku', faq:1, grp:'dun', q:"代理店委託契約では、何が決まっている？", re:/委託契約|代理店契約(書)?(の中身|とは|には|で何)/, ng:/新しく|新しい|別の保険会社|増や|追加|やめ|解除したい|法人化|法人にし|結ぶまで|開業|始め|立ち上げ|開き/, head:"委託契約には、任される仕事の範囲、守る決まり、手数料、終わり方が決まっています。", body:"保険代理店は、保険会社と代理店委託契約を結んで、募集や事務を任されます。契約には、扱える商品や仕事の範囲、保険料の扱い、守る決まり（法令と保険会社の規程）、手数料の決まり、契約の見直しや終わり方などが書かれているのが一般的です。代理店の毎日の事務の多くは、この契約と保険会社の手引きに沿って動きます。", acts:["委託契約書と付いている規程の一覧を手元に置き、どこに何が書いてあるかを社内で共有する", "扱える商品や仕事の範囲に迷ったら、委託契約と手引きを見てから保険会社の担当に聞く", "契約の中身が改められたら、変わった点を事務の手順に反映する"], actHead:"現場で使うなら", note:"委託契約の中身は保険会社ごとに違う。読み方に迷う条項は保険会社の担当に、法律上の判断が要るときは弁護士に確かめる。", say:"当社は、保険会社と代理店の契約を結び、決められた範囲でご案内とお手続きをしています。", more:"委託契約には、本文のほかに、手数料の規程や事務の取扱いの決まりが別に付いていることが多くあります。保険会社が複数あれば、決まりもそれぞれ違うので、会社ごとに違う点を一覧にしておくと事務の誤りを防げます。", why:"代理店は保険会社の代わりにお客様と接するので、どこまで任せるか、どの決まりを守るかを先に約束しておかないと、お客様への責任の所在があいまいになるからです。" },
      { key:'faq_xdun_noriai_add', faq:1, grp:'dun', q:"新しい保険会社の商品も扱いたい。何が要る？", re:/(乗合|乗り合い)(の)?(保険会社|会社)?[^。]{0,6}(増や|増える|追加|広げ)|(扱う|取り扱う|取扱う)(保険会社|会社)[^。]{0,4}(増や|増える|追加)|(新しく|新しい|別の)(保険会社|会社)[^。]{0,10}(代理店契約|委託契約|乗合|扱いたい|取り扱いたい|商品も扱)/, head:"扱う保険会社を増やすには、その会社と委託契約を結び、登録や届出を済ませます。", body:"新しい保険会社の商品を扱うには、その保険会社と代理店委託契約を結び、募集人の登録や届出、その会社の研修などを済ませるのが一般的です。保険会社は、代理店の体制や募集の様子、事務の力を見て委託するかを決めます。手続きが済むまでは、その会社の商品を募集できません。", acts:["扱いたい保険会社の窓口に、委託の条件と要る書類を確かめる", "増やしたあとの事務（申込書の様式・精算・手数料の決まり）の違いを先に一覧にする", "比較推奨の方針と社内の規程を、扱う保険会社の数に合わせて見直す"], actHead:"現場で使うなら", note:"委託の条件・登録や届出の手続き・研修の中身は、保険会社と生保・損保で違う。相手の保険会社の窓口と御社の担当で確かめる。", say:"当社が扱う保険会社と商品は、いつでもお伝えします。扱っていない会社の商品は、ご案内できません。", more:"扱う保険会社が増えると、お客様にお見せできる幅が広がる一方で、申込みの様式、精算の時期、手数料の決まり、事務の窓口が会社ごとに違って、事務の誤りが起きやすくなります。増やす前に、事務を受け持つ人と手順を決めておきます。乗合の数が増えると、比較推奨の体制も問われます。", why:"保険会社は、自社の商品を任せる代理店が決まりを守って募集できるかに責任を持つので、委託する前に体制を確かめ、募集人ごとに登録や届出を求めるからです。" },
      { key:'faq_xdun_tantousha', faq:1, grp:'dun', q:"保険会社の代理店担当者には、何を相談すればいい？", re:/(保険会社|損保|生保)(の)?(代理店)?(担当|営業担当|担当者|担当社員)[^。]{0,14}(相談|聞|頼|付き合|つきあ|何を|どこまで)|代理店担当(者|の人|社員)/, ng:/食い違|お客様の担当|担当替え|担当を替|担当が替|担当が変/, head:"保険会社の担当者には、商品・事務・決まりの確かめと、代理店の体制づくりを相談できます。", body:"保険会社の代理店担当者は、代理店が決まりどおりに募集し、事務を回せるように支える役目を持つのが一般的です。商品の細かい取扱い、事務の手順、研修の案内、点検の準備、資料の版の確かめなどは、遠慮せず聞いてよい中身です。お客様ごとの判断を任せるのではなく、代理店が決める材料をもらう相手と考えます。", acts:["聞きたいことを、契約の番号・見た資料・自分の案の三つにまとめてから連絡する", "答えをもらったら、日付と担当者の名前を添えて社内の記録に残す", "社内の規程と違う答えに見えたら、その場で決めず社内の担当と照らす"], actHead:"現場で使うなら", note:"担当者の役目と相談の窓口の分け方は、保険会社ごとに違う。保険会社の案内と御社の担当で確かめる。", say:"細かい取扱いは、保険会社の担当にも確かめてからお答えします。少しお時間をいただけますか。", more:"担当者の答えは、口頭のままにすると、あとで社内とずれたときに確かめようがありません。メールや書面でもらえるものはもらい、口頭なら日付と名前を記録します。保険会社の担当者が替わったときにも、記録があれば引き継ぎが楽になります。", why:"保険会社は代理店に募集を任せている分、代理店の体制や募集の品質を見る責任があり、担当者はその窓口だからです。" },
      { key:'faq_xdun_toiawase', faq:1, grp:'dun', q:"保険会社に問い合わせるとき、何をそろえておく？", re:/(保険会社|事務の窓口|コールセンター|代理店窓口)[^。]{0,10}(問い合わせ|問合せ|電話|聞く)[^。]{0,10}(前|そろえ|準備|コツ|一度で|何を)/, ng:/食い違|事故|苦情|クレーム/, head:"問い合わせの前に、契約の番号・聞きたいこと・自分で調べたことをそろえておきます。", body:"保険会社の事務の窓口は、契約の番号や代理店の番号から契約を探して答えるので、それが手元に無いと話が進みません。聞きたいことを一文にし、手引きや資料のどこを見て、どこが分からなかったかを添えると、一度で答えをもらいやすくなります。答えは、日付・窓口・担当者の名前と一緒に残します。", acts:["証券番号などの契約の番号・代理店の番号・お客様のお名前を手元に出してから電話する", "聞きたいことを一文にし、見た手引きのページと分からない点を書いておく", "答えを聞いたら、その場で読み上げて確かめ、社内の記録に残す"], actHead:"今日やること", note:"問い合わせの窓口と、代理店が確かめてよい範囲は保険会社ごとに違う。保険会社の案内と御社の手順で確かめる。", say:"保険会社に確かめてから、改めてご連絡します。いつ頃ご連絡するかだけ、先にお伝えしますね。", more:"お客様の情報を電話で伝えるときは、窓口が求める本人の確かめに沿い、要る範囲だけを伝えます。答えが社内の手引きと違って聞こえたら、その場で決めず、社内の担当と照らしてから動きます。同じ問いが何度も出るなら、社内の手順書に答えを書き足します。", why:"事務の窓口は多くの代理店から問い合わせを受けていて、契約を特定できないと答えられないからです。答えを記録するのは、あとで誰が何を聞いたかを示せるようにするためです。" },
      { key:'faq_xdun_tsuchi', faq:1, grp:'dun', q:"保険会社から届く事務連絡や通知は、どう管理する？", re:/(保険会社|本社|損保|生保)(から|の)[^。]{0,6}(事務連絡|通知|お知らせ|通達|連絡文書|案内文)[^。]{0,14}(管理|追|見落|回|共有|多|整理|どう)|(事務連絡|取扱(い)?(の)?変更(の)?(通知|お知らせ))[^。]{0,10}(見落|管理|回|共有|追)/, ng:/お客様に届|お客様へ届|戻ってき|届かな|改定/, head:"保険会社からの通知は、届いた日・中身・社内で直すことを一覧にして回します。", body:"保険会社からは、商品の改定、事務の取扱いの変更、様式の差し替え、研修や点検の案内などが届きます。読んだだけで終えると、古いやり方が社内に残ります。届いたら、いつから・何が変わるか・誰が何を直すかを書き出し、関わる人が読んだことを確かめます。", acts:["届いた通知を、日付・保険会社・件名・いつから変わるかの一覧にまとめる", "手順書や資料で直すところがあれば、受け持つ人と期日を決める", "関わる人が読んだかを、名前と日付で残す"], actHead:"今日やること", note:"通知の届け方と、代理店に求められる対応は保険会社ごとに違う。保険会社の案内と御社の手順で確かめる。", say:"保険会社の取扱いが変わったときは、私どもからもお知らせします。気になる案内が届いたら、遠慮なくお聞きください。", more:"通知は、保険会社の代理店向けの画面や、メール、紙など、届く場所がばらばらになりやすいものです。届く場所を決め、受け持つ人を一人決めると見落としが減ります。点検では、通知を受けて社内でどう直したかを聞かれることがあるので、直したことも記録します。", why:"取扱いの変更は、知らずに前のやり方を続けると、お客様への説明の誤りや手続きの不備につながるからです。" },
      { key:'faq_xdun_keijou', faq:1, grp:'dun', q:"計上とは？成立とは何が違う？", re:/計上(と|は|って|とは|の意味|はいつ|される)|(成立|申込み|申し込み)と[^。]{0,8}計上/, ng:/損金|資産|経理|仕訳|法人|益金|しめ|締め|間に合|またぎ/, head:"計上は、申込みや契約を保険会社や代理店の数字として数える扱いのことです。", body:"申込みは、お客様が保険会社に契約を申し込んだ時点、成立は、保険会社が引き受けて契約の手続きが済んだ時点を指すのが一般的です。計上は、それを成績や手数料の計算の上で数える扱いで、いつ・何を基準に数えるかは、保険会社と商品で決まっています。同じ契約でも、申込み・成立・計上の日が違うことがあります。", acts:["扱う保険会社ごとに、計上の基準になる時点を手引きで確かめて一覧にする", "申込みの日・成立の日・計上の日を、契約ごとの記録に分けて書く", "お客様への説明には計上の言葉を使わず、保障がいつ始まるかで伝える"], actHead:"現場で使うなら", note:"計上の基準・締めの日・成立までの流れは、保険会社と商品で違う。所属の保険会社の手引きと御社の担当で確かめる。", say:"保障がいつから始まるかは、保険会社のお手続きが済んでから、改めてお伝えします。", more:"よくある勘違いは、計上されれば保障が始まっていると思うことです。保障の始まりは約款の決まりで決まり、計上とは別の話です。お客様には、保障がいつから始まるかを、保険会社の案内に沿って伝えます。", why:"計上は、保険会社と代理店の数字や手数料を数えるための扱いで、お客様との約束である保障とは目的が違うからです。" },
      { key:'faq_xdun_jimu_nagare', faq:1, grp:'dun', q:"申込みを預かってから、代理店の事務は何をする？", re:/(申込(書|み)?|申し込み)(を|の)?(預か|受け|受付|お預かり)[^。]{0,14}(事務|流れ|段取り|何を|あと|後|成立まで)|申込(み)?(の)?(あと|後)[^。]{0,8}(事務|成立まで)/, ng:/控え|不備|記入漏れ|提出する前|書き間違/, head:"申込みを預かったら、点検・送付・記録・追いかけ・成立の連絡の順で事務を回します。", body:"申込みを預かったら、書類や画面の入力に漏れが無いかを確かめ、決められた方法で保険会社へ送り、何をいつ送ったかを記録します。そのあと、不備の連絡や審査の結果を待ちながら成立までの進み具合を追いかけ、成立したらお客様に知らせます。どの段も、自分の記憶ではなく記録に残します。", acts:["申込みごとに、預かった日・送った日・保険会社の受付・不備・成立の欄を持つ一覧を作る", "送る前の点検は、社内の手順に沿って、できれば別の人の目でも見る", "成立まで時間がかかっている申込みは、一覧で決まった日に確かめる"], actHead:"現場で使うなら", note:"送り方・点検の項目・成立までの流れは、保険会社と申込みの方法で違う。所属の保険会社の事務の手引きと御社の手順で確かめる。", say:"お申し込みの書類は、保険会社へお送りしました。お手続きが済みましたら、私からご連絡します。", more:"画面での申込みでも、送ったあとに保険会社の審査や確かめの連絡が入ることがあるので、追いかける一覧は要ります。保障の始まりに第一回の保険料の払い込みが関わる商品もあるので、払い込みの方法と時期もお客様と確かめます。", why:"申込みは、お客様が保障を待っている大事な手続きで、送ったまま追いかけないと、不備や払い込みの遅れに気づくのが遅れ、保障の始まりも遅れるおそれがあるからです。" },
      { key:'faq_xdun_soufu', faq:1, grp:'dun', q:"申込書類を保険会社へ送るとき、何を記録する？", re:/送付(簿|記録|の記録|台帳)|(申込書(類)?|書類)(を)?(保険会社)?(へ|に)?[^。]{0,6}送(る|った|付)[^。]{0,10}(記録|残|分からな|確か)/, ng:/送り先|宛先|間違|別の(お客様|方|人)|ほかの(お客様|方|人)|控えを|お客様に送/, head:"送るときは、誰の・何の書類を・いつ・どう送ったかを、送る前に一覧に書きます。", body:"申込書類はお客様の大事な情報が載った書類で、保険会社へ届いたかを後から確かめられることが大事です。お客様のお名前、書類の種類と枚数、送った日、送り方、送った人を記録し、保険会社の受付を確かめたら印を付けます。届かないときに、どこで止まったかを追えるようにします。", acts:["送る前に、書類の種類と枚数を一覧と照らし、封をする前に別の人と読み合わせる", "送り方は、保険会社と社内の手順で決められた方法だけを使う", "保険会社の受付が確かめられない書類は、決まった日に問い合わせる"], actHead:"今日やること", note:"送り方・記録の項目・届いたことの確かめ方は、所属の保険会社と御社の手順で違う。事務の手引きと御社の担当で確かめる。", say:"お預かりした書類は、記録を付けたうえで保険会社へお送りします。届いたことも確かめますので、ご安心ください。", more:"送ったつもりで机に残っていた、別のお客様の書類を一緒に封筒に入れてしまった、というのが起こりやすい事故です。封をする前に、一覧と中身を一枚ずつ照らすと防げます。画面で送る申込みでも、送信の完了の画面や受付の番号を残しておきます。", why:"申込書類が途中で無くなったり、別の人へ届いたりすると、お客様の情報の事故になり、保障の始まりも遅れるからです。記録があれば、どこで止まったかをすぐに追えます。" },
      { key:'faq_xdun_miseiritsu', faq:1, grp:'dun', q:"申込んだのに、なかなか成立しない契約はどう追う？", re:/(成立しな|成立していな|未成立|成立まで)[^。]{0,14}(追|管理|溜ま|たま|長引|どう)|(審査|引受)[^。]{0,8}(長引|時間がかか|遅)[^。]{0,10}(申込|契約)/, ng:/謝絶|条件が付|条件付|保険金|給付金|査定/, head:"成立していない申込みは、止まっている理由ごとに分け、決めた日に確かめます。", body:"成立しない理由は、書類の不備、告知や診査の結果を待っている、第一回の保険料が払い込まれていない、保険会社の確かめの連絡が済んでいない、などに分かれます。理由が分からないまま待つと、お客様の保障の始まりが遅れます。一覧で理由と次に確かめる日を決め、自分から保険会社とお客様に動きます。", acts:["未成立の申込みを、理由（不備・審査・払い込み・確かめの連絡）ごとに分けて一覧にする", "理由が分からないものは、契約の番号を添えて保険会社に確かめる", "お客様には、何を待っているかと、次にいつ連絡するかを伝える"], actHead:"今日やること", note:"成立までの流れ・審査の期間・申込みが取り下げになる扱いは、保険会社と商品で違う。所属の保険会社の手引きと担当で確かめる。", say:"保険会社で、お申し込みの確認を進めています。いま何を待っているかと、次にいつご連絡するかをお伝えしますね。", more:"長く止まっている申込みは、保険会社の決まりで、時期を過ぎると取り下げの扱いになることがあるので、放っておけません。お客様の都合で書類がそろわないときも、催促するのではなく、何が要るかと、そろわないとどうなるかを先にお伝えします。", why:"成立までの間、お客様はまだ保障を受けられないことが多く、止まった理由に早く手を打つほど、保障が始まるのも早くなるからです。" },
      { key:'faq_xdun_buntan', faq:1, grp:'dun', q:"募集する人と事務をする人で、仕事をどう分ける？", re:/(募集|営業)(する人|担当)?と(事務|内勤|内務)[^。]{0,16}(分け|分担|役割)|(事務|内勤|内務)(の)?(分担|役割分担|受け持ち)|(事務|内勤)を誰が(受け持|やる|担当)/, ng:/体制を整え|部下|後輩|新人|メンバー/, head:"勧誘と説明は登録した募集人、手続きの事務は決めた人が受け持ち、受け渡しの形を決めます。", body:"商品の説明や勧誘など募集にあたる仕事は、登録や届出を済ませた募集人しかできません。書類の点検・送付・記録・保険会社との事務の連絡は、決めた人がまとめて受け持つと、漏れや重なりが減ります。大事なのは、どこで仕事を受け渡すかと、受け渡したことの記録を決めておくことです。", acts:["申込みから成立までの仕事を書き出し、段ごとに受け持つ人の名前を入れる", "募集にあたる仕事を、登録の無い人に任せていないかを確かめる", "休みのときに代わる人も、段ごとに決めておく"], actHead:"現場で使うなら", note:"登録の無い人に任せてよい事務の範囲は、所属の保険会社の手引きと御社の規程で決まっている。迷うものは社内の担当と保険会社に確かめる。", say:"お手続きの書類は、事務の担当者がお預かりして保険会社とやりとりします。ご説明は、引き続き私が受け持ちます。", more:"分担で起きやすいのは、誰の仕事か決まっていない隙間です。不備の連絡を誰がお客様に伝えるか、保険会社からの通知を誰が読むか、の二つは決めておかないと、互いに相手がやったと思って止まります。小さな代理店でも、一覧に名前を書くだけで漏れが減ります。", why:"募集には登録が要るという法令の線と、事務の漏れを防ぐという実務の線の、両方を同時に守るためです。" },
      { key:'faq_xdun_jimuin', faq:1, grp:'dun', q:"登録のない事務員は、お客様にどこまで話していい？", re:/(登録(の)?(ない|無い)|登録していない|募集人(では|じゃ)?(ない|でない))[^。]{0,8}(事務|内勤|スタッフ)|(事務員|事務スタッフ|内勤(の人|者)?)[^。]{0,12}(答え|話して|どこまで|できる)/, ng:/知人|友人|家族|妻|夫|手伝/, head:"登録の無い人は、商品の説明・勧誘・申込みの取次ぎをせず、事務の受付までにします。", body:"保険の募集にあたる行為（商品の説明・勧誘・申込みの取次ぎなど）は、登録や届出を済ませた募集人しかできません。登録の無い事務員は、決められた範囲の事務、例えば来客や電話の受付、担当の募集人へのつなぎ、事務の書類の整理などを受け持ちます。どこまでが事務かは、保険会社の手引きと社内の規程で決めておきます。", acts:["商品の中身を聞かれたら、担当の募集人からご連絡しますと伝え、聞かれたことを書き留めて渡す", "事務員が受け持ってよい仕事の一覧を作り、社内で共有する", "迷う仕事は、始める前に社内の担当と保険会社に確かめる"], actHead:"現場で使うなら", note:"事務員に任せてよい範囲は、所属の保険会社の手引きと御社の規程で決まっている。迷うものは御社のコンプライアンス担当に確かめる。", say:"その点は、担当の募集人から改めてご説明します。お伺いした内容は、きちんと伝えておきます。", more:"電話で、この保険はどうですかと聞かれたときに、親切のつもりで中身を答えてしまうのが、いちばん起きやすい線の越え方です。答えずに受け止め、担当につなぐ言い方を決めておくと、事務員も迷いません。事務員が募集人の登録を目指すなら、それまでの間の線を本人と確かめておきます。", why:"募集にあたる行為は、お客様に誤解や不利益を与えないよう、決まった教育と登録を受けた人に限る決まりがあるからです。" },
      { key:'faq_xdun_daichou', faq:1, grp:'dun', q:"顧客台帳には何を載せておく？", re:/(顧客|お客様)(の)?(台帳|名簿|管理表|一覧表)[^。]{0,10}(載せ|項目|整え|作|何を|まとめ)|(台帳|名簿)(を|の)?(作り|整え|項目)/, ng:/持ち帰|持ち出|自宅|私物|捨て|廃棄|処分|研修|帳簿/, head:"顧客台帳には、お客様と契約、連絡と手続きの記録を、決めた項目で載せます。", body:"顧客台帳は、お客様ごとに、お名前と連絡先、ご契約の一覧（保険会社・商品・番号・満期や更新）、面談や手続きの記録、次にやることをまとめたものです。項目をそろえておくと、担当が替わっても、点検で聞かれても、すぐに出せます。載せるのは仕事に要る範囲だけにし、見られる人を決めます。", acts:["載せる項目を社内で決め、全てのお客様で同じ形にそろえる", "病歴など特に気をつける情報は、載せる場所と見られる人を絞る", "台帳を直したら、直した日と人が分かるようにする"], actHead:"現場で使うなら", note:"載せてよい情報の範囲と扱い方は、御社の個人情報の規程と所属の保険会社の手引きで決まっている。社内の担当で確かめる。", say:"お客様の情報は、ご契約のお手続きとご案内に要る範囲で、決まった方法で管理しています。", more:"台帳は、契約の記録だけでなく、意向把握や比較推奨の記録、苦情や事故の記録とつながっていると、点検で指摘されたお客様の記録をすぐに出せます。保険会社の画面にある情報と社内の台帳がずれないよう、お客様からのお届けの変更は両方に反映します。", why:"お客様の情報が人ごとの手帳や記憶に散らばると、担当が替わったときや問い合わせを受けたときに、誰も正しく答えられなくなるからです。" },
      { key:'faq_xdun_jouhou_kanri', faq:1, grp:'dun', q:"お客様の情報を扱うパソコンや棚で、何を決めておく？", re:/(パソコン|pc|棚|キャビネット|書庫)[^。]{0,12}(パスワード|鍵|かぎ|ロック|見られる人|管理)|(顧客情報|お客様の情報|個人情報)[^。]{0,8}(見られる人|アクセス|権限)|(お客様の情報|顧客情報)を扱う[^。]{0,14}(決め|ルール)/, ng:/持ち帰|持ち出|自宅|私物|保管するか|探せな|壊れ|消え|バックアップ|システムのid|システムのパスワード/, head:"お客様の情報は、見られる人を決め、鍵とパスワードで守り、使い終えたら閉じます。", body:"代理店には、お客様の情報を漏らさず、無くさず、勝手に変えられないように守る仕組みが求められます。パソコンは一人ずつのパスワードで使い、席を離れるときは画面を閉じます。紙の書類は鍵の掛かる棚に入れ、鍵の持ち主を決めます。誰がどの情報を見られるかを、仕事に要る範囲で決めます。", acts:["パソコンと保険会社のシステムは、一人ずつのIDとパスワードで使い、使い回さない", "書類の棚の鍵の持ち主と、帰るときに閉めたかを確かめる人を決める", "退職や異動のときに、見られる範囲とパスワードを止める手順を決める"], actHead:"現場で使うなら", note:"守り方の細部は、御社の個人情報の規程と所属の保険会社の手引きで決まっている。社内の担当とコンプライアンス担当で確かめる。", say:"お客様の情報は、決まった者だけが扱い、鍵とパスワードで守っています。", more:"起きやすいのは、付箋に書いたパスワード、共有のIDの使い回し、開いたままの画面、机に出したままの申込書です。帰る前に机と画面の様子を見回すだけでも、起きやすい漏れの多くを防げます。", why:"お客様の情報が漏れると取り返しがつかず、お客様と保険会社の信頼を一度に失うからです。守り方を人まかせにせず仕組みにしておくのは、うっかりを前提にしているためです。" },
      { key:'faq_xdun_tablet', faq:1, grp:'dun', q:"タブレットでの申込みに切り替えると、事務は何が変わる？", re:/(タブレット|ペーパーレス|画面で申し込|電子(の)?申込|電子手続)[^。]{0,14}(切り替|切替|変え|変わ|気をつけ|準備|事務|注意)|(紙|紙の申込書)から[^。]{0,6}(タブレット|電子|画面)/, ng:/控え|写し|パスワード|鍵|なくし|紛失|壊れ/, head:"画面での申込みは、書類の点検が減る代わりに、本人の確かめと記録の残し方が大事になります。", body:"画面での申込みは、入力の漏れを画面が止めてくれるので、書類の不備は減りやすくなります。一方で、お客様ご本人が画面を見て内容を確かめ、ご本人が入力や署名をしたことが大事になります。控えの渡し方や、通信が切れたときの扱い、端末の管理も、紙とは違う手順になります。", acts:["お客様に画面を渡し、ご本人に内容を読んでいただいてから署名していただく", "控えの渡し方（画面・メール・紙）を、保険会社の手順でお客様と確かめる", "端末の持ち出しと置き場所、パスワードの決まりを社内で決める"], actHead:"現場で使うなら", note:"画面での申込みの手順・使える商品・控えの扱いは、保険会社ごとに違う。所属の保険会社の手引きと御社の手順で確かめる。", say:"こちらの画面で、お申し込みの内容をご自身で確かめていただけますか。分からないところは、その都度お聞きください。", more:"画面だと手続きが早く進むので、説明を急いだように見えやすくなります。重要事項の説明や意向の確かめは、紙のときと同じだけ時間をかけます。お客様の代わりに画面を操作して入力を進めるのは避け、ご本人が操作したことが分かる形にします。", why:"画面での申込みでも、お客様ご本人の意思で申し込んだことが契約の土台であることは変わらず、それを後から示せる形で残すことが求められるからです。" },
      { key:'faq_xdun_backup', faq:1, grp:'dun', q:"顧客の記録のデータは、どう控えておく？", re:/バックアップ|データ(の)?控え|控えておく方法|(パソコン|端末|データ)[^。]{0,8}(壊れ|消え|飛ん)|(記録|データ)[^。]{0,8}(どう)?控えて/, ng:/申込(書|み)?の控え|お客様の控え|お客様控え/, head:"記録のデータは、決めた場所へ、決めた間隔で控え、戻せるかも確かめておきます。", body:"端末の故障や紛失、うっかり消してしまうことで、お客様の記録が失われることがあります。控えは、社内で決めた安全な場所に、決めた間隔で取り、控えの中にもお客様の情報があることを忘れずに守ります。控えを取るだけでなく、実際に戻せるかを時々確かめます。", acts:["控えを取る人・間隔・置き場所を決め、取った日を記録する", "控えの置き場所も、見られる人を絞り、鍵やパスワードで守る", "時々、控えから実際に記録を戻せるかを試す"], actHead:"現場で使うなら", note:"控えの置き場所と方法は、御社の個人情報の規程と所属の保険会社の手引きで決まっている。社内の担当で確かめる。", say:"お客様の記録は、決まった方法で控えを取り、無くならないように守っています。", more:"外のサービスや個人のスマホに控えるのは、社内の決まりで許された場合だけにします。控えのファイルを持ち歩くときも、お客様の情報を持ち出すのと同じ扱いになります。消えてから慌てないよう、控えの手順を手順書に書いておきます。", why:"記録は、お客様への説明や点検で、過去に何をしたかを示す唯一の材料なので、失うとお客様と代理店の両方が困るからです。" },
      { key:'faq_xdun_tejunsho', faq:1, grp:'dun', q:"社内の事務の手順書は、どう作ればいい？", re:/(事務|内務|手続き)(の)?(手順書|マニュアル|手引き書)|(手順書|マニュアル)[^。]{0,6}(作り|作成|作りた|無い|ない|整え)|事務の手順を書いたもの/, ng:/保険会社の(事務の)?手引き/, head:"手順書は、いまのやり方を段ごとに書き出し、保険会社の手引きと照らしてから作ります。", body:"手順書は、新しく書き起こすより、いまの仕事を段ごとに書き出すほうが早く、現場に合ったものになります。段ごとに、誰が・何を見て・どう確かめ・どこに記録するかを書き、保険会社の手引きや社内の規程とずれていないかを照らします。よく出る問いと答えも添えると、聞き直しが減ります。", acts:["申込み・保全・精算など、よくある仕事から一つずつ段を書き出す", "書いた手順を、保険会社の手引きと社内の規程で照らして直す", "改めた日と改めた点を記し、古い版は使わないようにする"], actHead:"現場で使うなら", note:"手順書の中身は、所属の保険会社の手引きと御社の規程に沿っていることが前提。照らし方は社内の担当と保険会社に確かめる。", say:"お手続きは決まった手順で進めていますので、担当が替わっても同じようにご案内できます。", more:"手順書は、作った人しか読めない文章だと使われません。新しく入った人に一度読んでもらい、分からなかった所を直すと、ぐっと使えるものになります。保険会社の通知で取扱いが変わったら、手順書のどこを直すかをすぐに決めます。", why:"人の記憶に頼った事務は、休みや退職で止まり、人によってやり方がずれて不備が増えるからです。書いておけば、誰がやっても同じ確かめができます。" },
      { key:'faq_xdun_kitei', faq:1, grp:'dun', q:"代理店に備えておく社内規程には、どんなものがある？", re:/(社内)?規程(類)?(の)?(種類|一覧)|規程(は|を)何を作|どんな(社内)?規程|規程類|規程(には|は)[^。]{0,4}(どんな|何が)/, ng:/誰が|体制を整え|手数料|副業|服務|休暇|有給/, head:"募集の進め方・お客様の情報・苦情・記録・教育の決まりを、まず一覧にして持っているかを見ます。", body:"代理店に求められる体制は、募集の規模や扱う保険会社で違います。一般には、募集の手順（意向の確かめ方・比べ方・書類の扱い）、お客様の情報の扱い、苦情の受け方、記録の残し方、募集人の教育と管理、といった決まりを文書にして、社内で共有しておきます。何をどこまで作るかは、保険会社の指示と御社の規模で決めます。", acts:["今ある規程・手順書・決まりの文書を全て集め、名前と最後に直した日を一覧にする", "一覧の中で、文書にしていないが口で決めているものに印を付ける", "所属の保険会社の担当に、求められている規程の種類を確かめる"], actHead:"今日やること", note:"求められる規程の種類と中身は、保険業法と監督指針、所属の保険会社の指示、御社の規模で変わる。所属の保険会社と社内の規程の担当で確かめる。", say:"お客様の情報や手続きの扱いは、社内の決まりに沿って進めています。ご不明な点があれば、いつでもお尋ねください。", more:"規程は作って終わりではなく、実際の動きと合っているかが見られます。規程に書いてあるのに誰もしていない手順は、無いより説明が難しくなります。書くときは、誰が・いつ・何をするか・どこに記録するか、の四つを入れると守りやすくなります。", why:"募集の決まりを人の記憶に頼ると、人が替わったときに抜けるからです。文書にしておけば、新しい募集人にも同じ形で伝えられ、点検でも説明できます。" },
      { key:'faq_xdun_jimu_miss', faq:1, grp:'dun', q:"事務の手続きを間違えたと気づいたら？", re:/(手続き|手続|事務)[^。]{0,8}(間違え|ミス|誤っ|誤り)|間違えて(出|手続)/, ng:/書類|送り先|宛先|なくし|書き間違|申込書|記入漏れ|お客様に説明|間違えそう|保険会社が多|保険会社ごと|乗合/, head:"黙って直さず、上長と保険会社の担当にすぐ伝え、直し方を決めてから動きます。", body:"手続きの間違いは、気づいた時点で上長に伝え、保険会社の担当に、何をどう間違えたかを契約の番号と一緒に伝えます。自分の判断で取り消したり出し直したりすると、二重の手続きになることがあります。お客様に影響がある間違いなら、伝え方とお詫びの仕方も上長と決めてから連絡します。", acts:["間違えた手続きの名前・契約の番号・出した日・間違えた中身を一行で書く", "上長に伝え、保険会社の担当への連絡を誰がするか決める", "直したあと、なぜ起きたかと次の防ぎ方を記録に残す"], actHead:"今日やること", note:"手続きを取り消す・出し直す方法は、保険会社と手続きの種類で違う。所属の保険会社の事務の手引きと担当、社内の上長で確かめる。", say:"お手続きの中で、こちらの確かめが足りない点がありました。直し方を保険会社と確かめて、改めてご連絡します。", more:"間違いを伝えにくいのは、責められると感じるからです。社内では、間違いを早く言った人を責めない決まりにしておくと、小さいうちに直せます。記録には、誰が間違えたかより、どの手順で起きたかを書きます。", why:"事務の間違いは、時間がたつほど直す手続きが増え、お客様に届く影響も大きくなるからです。早く伝えれば、保険会社が持っている直し方を使えることが多くなります。" },
      { key:'faq_xdun_shiryo_han', faq:1, grp:'dun', q:"パンフレットや資料の版は、どう管理する？", re:/(パンフレット|資料|チラシ|募集資料|設計書)[^。]{0,10}(版|差し替|最新|期限切れ)|古い(パンフレット|資料|チラシ)/, ng:/書き足|数字を|手作り|自作|作ってもいい|自分で作/, head:"資料ごとに版と使える期間を一覧にし、古い版は手元から引き上げます。", body:"パンフレットや募集資料には、作られた時期や管理の番号が入っていることが多く、商品の改定で古くなります。使っている資料を一覧にして、版と使える期間、置き場所を書いておきます。新しい版が届いたら、営業かばんや車の中、事務所の棚に残った古い版を引き上げます。", acts:["手元と事務所の資料を集め、資料の名前・版・使える期間を一覧にする", "使える期間が過ぎた資料を引き上げ、決まった方法で処分する", "新しい版が届いたときに、誰が差し替えを知らせるか決める"], actHead:"今日やること", note:"資料の使える期間・管理の番号の見方・処分の仕方は、保険会社の決まりで違う。所属の保険会社の担当と社内の規程で確かめる。", say:"お渡しする資料は、いま使えるものかを確かめてからお持ちしています。新しい資料が出たときは、改めてお届けします。", more:"古い版を使うと、保険料・保障の中身・取扱いが今と違う説明になることがあります。版を一覧で持っておけば、点検でどの資料をいつまで使ったかを説明できます。手元に一部だけ残すときは、見本と分かる印を付けておきます。", why:"募集の資料は、保険会社が中身を確かめたうえで使える形にしているからです。古い版のまま説明すると、正しい説明をしたつもりでも事実と違う説明になります。" },
      { key:'faq_xdun_kaitei', faq:1, grp:'dun', q:"商品が改定されるとき、代理店では何を準備する？", re:/(商品|保険料|約款)[^。]{0,4}(の)?改定[^。]{0,18}(準備|事務|整え|やること|案内|前)|改定前の(申込書|様式|パンフレット)/, ng:/駆け込み|今のうち|急いで|上がる前に|下がる前に/, head:"切り替わる日・使える資料と様式・途中の申込みの扱いを、保険会社の案内で確かめて社内に配ります。", body:"商品の改定では、切り替わる日を境に、使える申込書の様式・パンフレット・設計書が変わります。改定の前に申込みを預かった契約と、後の契約で扱いが違うこともあります。保険会社の案内を読み、切り替わる日、古い様式の使える期限、途中の申込みの扱いを社内で一枚にまとめて配ります。", acts:["保険会社の改定の案内から、切り替わる日と使えなくなる様式を書き出す", "手元の古い申込書と資料に、使える最後の日を書いた付箋を付ける", "改定をまたぐ申込みが無いか、預かり中の申込みを確かめる"], actHead:"今日やること", note:"改定の日・様式の使える期限・途中の申込みの扱いは、保険会社ごとに案内される。所属の保険会社の案内と担当で確かめる。", say:"商品の内容が変わる時期がありますので、いま検討中の内容がどちらで扱われるかを確かめてご案内します。その場で決めていただく必要はありません。", more:"改定を、お客様を急がせる話に使わないことが大切です。保険料が変わることを理由に決断を迫ると、不安で押す形になります。伝えるのは事実と日付までにして、決めるのはお客様に任せます。", why:"改定の切り替わりでは、古い様式で申込みを預かると出し直しになり、お客様に手間をかけるからです。前もって日付を社内で共有すれば、手続きの間違いを防げます。" },
      { key:'faq_xdun_kyujitsu', faq:1, grp:'dun', q:"休業日のお客様の連絡先は、どう案内する？", re:/(休業日|休みの日|休日|年末年始|夏季休|連休|休みのあいだ)[^。]{0,14}(連絡|問い合わせ|案内|受け方|電話)/, ng:/自分の休み|有給|休みたい|休めない|休暇を取|夜や|夜と休|夜間や/, head:"休みの前に、保険会社の窓口と代理店の連絡の受け方を決め、お客様に伝わる形にしておきます。", body:"代理店が休みのあいだも、事故や病気、手続きの問い合わせは起きます。保険会社には、事故の受付や契約の問い合わせの窓口があることが多いので、その案内を留守番電話・ホームページ・お客様へのお知らせに載せておきます。休み明けに誰が折り返すかも決めておきます。", acts:["休みのあいだに使える保険会社の窓口の名前と受付の時間を確かめる", "留守番電話の言葉とホームページの案内を、休みの前に直す", "休み明けに、折り返しの連絡を誰がいつするか決める"], actHead:"今日やること", note:"窓口の名前と受付の時間は保険会社と商品で違う。所属の保険会社の案内で確かめ、社内の連絡の決まりは御社の規程で決める。", say:"お休みのあいだに事故やお急ぎのご用があったときは、保険会社の窓口が受け付けています。連絡先をお控えいただけますか。", more:"連絡の受け方は、留守番電話に残った用件を休み明けにまとめて見る形が多いですが、事故の連絡は待たせないように保険会社の窓口へ案内します。携帯電話への転送をするときは、出られないときの案内も決めておきます。", why:"お客様が困るのは、休みのあいだに誰にも連絡がつかないことだからです。窓口を前もって伝えておけば、休みでもお客様は手続きを進められます。" },
      { key:'faq_xdun_tougou', faq:1, grp:'dun', q:"ほかの代理店と一緒になるとき、契約はどうなる？", re:/代理店[^。]{0,8}(合併|統合|一緒にな|譲渡|事業を譲)|(合併|統合|譲渡|譲り受)[^。]{0,8}代理店|代理店の事業を譲/, ng:/保険会社が合併|担当を変え|担当変更|乗り換|乗換/, head:"契約の担当を移す手続き・お客様へのお知らせ・記録の引き継ぎを、保険会社と決めてから進めます。", body:"代理店どうしが一緒になると、お客様の契約の担当代理店を移す手続きが要ることがあります。保険会社ごとに手続きと時期が違うので、所属の保険会社と先に決めます。お客様には、担当が変わることと連絡先を知らせます。意向把握などの記録、顧客台帳、苦情の記録も、引き継ぐ範囲と方法を決めます。", acts:["扱っている保険会社ごとに、担当を移す手続きと必要な書類を確かめる", "引き継ぐ記録（顧客台帳・意向把握・苦情・書類の控え）を一覧にする", "お客様へのお知らせの文と送る時期を決める"], actHead:"今日やること", note:"担当を移す手続き・お客様への知らせ方・記録の引き継ぎ方は、保険会社と委託契約で違う。所属の保険会社で確かめる。会社どうしの契約は弁護士に相談する。", say:"代理店の体制が変わり、ご契約の担当が変わります。ご契約の中身は変わりません。新しい連絡先をお知らせします。", more:"引き継ぎで抜けやすいのは、口頭で受けていたお客様の要望と、途中の手続きです。手続き中の契約と、満期や更新が近い契約を先に一覧にすると、移るあいだにお客様を待たせずに済みます。", why:"担当が変わることは、お客様にとって大事なお知らせだからです。記録が引き継がれていないと、新しい担当が同じことを何度も聞くことになります。" },
      { key:'faq_xdun_dairi_baikai', faq:1, grp:'dun', q:"代理と媒介は、どう違う？", re:/代理と媒介|媒介と代理|(締結の)?代理[^。]{0,6}媒介|媒介(とは|って何|の意味)|^媒介[?？]?$/, ng:/告知/, head:"代理は保険会社に代わって契約を結ぶこと、媒介は申込みを取り次ぐことで、承諾は保険会社です。", body:"締結の代理は、保険会社から任された範囲で、代理店がお客様と契約を結ぶ形です。媒介は、お客様と保険会社のあいだに入って申込みを取り次ぐ形で、契約を承諾するかは保険会社が決めます。一般に損害保険の代理店は代理、生命保険の募集人は媒介のことが多いですが、御社がどちらかは委託契約で決まっています。", acts:["所属の保険会社ごとの委託契約で、代理か媒介かの書き方を確かめる", "お客様に渡す書類や名刺に、どちらの立場かを示す決まりがあるか確かめる"], actHead:"今日やること", note:"代理か媒介か、任されている範囲は、保険会社と委託契約で決まる。所属の保険会社の委託契約と担当で確かめる。", say:"私どもは保険会社から任された立場でご案内しています。お申込みを引き受けるかどうかは保険会社が決めます。", more:"どちらの立場かで、契約が成り立つ時期や、お客様から受け取った書類や告知の扱いが変わります。媒介の立場で、引き受けられますと言い切ると、事実と違う説明になります。立場を示すことは、お客様が誰と話しているかを知るためにも大切です。", why:"お客様は、目の前の募集人が保険会社の代わりにどこまで決められるかを知って、話を聞く権利があるからです。立場が分からないまま申込むと、あとで成り立っていなかったと分かることがあります。" },
      { key:'faq_xdun_meishi', faq:1, grp:'dun', q:"名刺には何を書いておく？", re:/名刺[^。]{0,10}(書|載せ|入れ|作り|作る|表記|記載)/, ng:/渡し方|もらった|交換|渡すとき/, head:"代理店の名前と自分の名前に加えて、どの保険会社の募集をしている立場かが分かる書き方にします。", body:"名刺は、お客様が誰と話しているかを知る最初の書類です。代理店の名前、自分の名前、連絡先のほかに、扱っている保険会社や、代理か媒介かといった立場が分かる書き方が求められることがあります。保険会社や代理店の決まりで書き方が決まっていることもあるので、作る前に確かめます。", acts:["今の名刺に、代理店名・連絡先・所属の保険会社が書いてあるか見る", "所属の保険会社と社内に、名刺の書き方の決まりがあるか確かめる"], actHead:"今日やること", note:"名刺に書く項目の決まりは、保険会社と社内の規程で違う。所属の保険会社と御社の規程で確かめる。", say:"私は保険代理店の募集人として、こちらの保険会社の商品をご案内しています。名刺に連絡先を書いておきます。", more:"肩書きに、持っていない資格や、保険会社の社員と誤って受け取られる書き方をしないことが大切です。乗合の代理店なら、扱う保険会社の一覧を別の紙で渡す形もあります。", why:"お客様は、話している相手がどの保険会社の、どんな立場の人かを知ってから話を聞くべきだからです。立場が分かる名刺は、あとの誤解を防ぎます。" },
      { key:'faq_xdun_kyoudou', faq:1, grp:'dun', q:"ほかの代理店と一緒に募集するときは？", re:/共同募集|(ほかの|別の|他の)代理店(の人)?と(一緒|共同)[^。]{0,10}(募集|訪|お客様)/, ng:/合併|統合|引き継|譲渡/, head:"共同で募集するときは、保険会社の決まりに沿って、役割と記録の残し方を前もって取り決めます。", body:"ほかの代理店と一緒に募集するときは、保険会社に届け出や決まった手続きが要ることがあります。どちらがお客様に説明し、意向を確かめ、書類を扱うのか、役割を前もって決めます。お客様には、二つの代理店が関わることを伝えます。意向把握などの記録は、どちらが残すかを決めておきます。", acts:["所属の保険会社に、共同募集の手続きと届け出が要るか確かめる", "説明・意向の確認・書類の扱い・記録を、どちらが受け持つか書き出す", "お客様に、二つの代理店が関わることをどう伝えるか決める"], actHead:"今日やること", note:"共同募集の手続き・届け出・手数料の扱いは、保険会社と委託契約で決まる。所属の保険会社で確かめる。社内の決まりは御社の規程で確かめる。", say:"今回は、私どもともう一つの代理店でご案内します。それぞれの役割と連絡先をお伝えします。", more:"役割を決めないまま一緒に動くと、説明が重なったり抜けたりします。とくに、意向の確かめと比べて勧めた理由の記録は、どちらにも無いという形になりやすいので、受け持つ側を先に決めます。", why:"お客様から見ると、誰が責任を持って説明しているかが分からなくなるからです。取り決めを残しておけば、あとで問い合わせや苦情があったときにも答えられます。" },
      { key:'faq_xdun_haigyou', faq:1, grp:'dun', q:"代理店をやめるとき、お客様の契約はどうなる？", re:/代理店[^。]{0,8}(やめる|辞める|廃業|閉じる|閉める|畳|続けられな)|代理店の廃業/, ng:/募集人が辞め|退職|部下|社員が|保険会社が/, head:"代理店をやめても契約は保険会社との契約として続くので、担当を移す手続きを保険会社と進めます。", body:"お客様の保険の契約は、保険会社とお客様のあいだで結ばれています。代理店をやめても、契約がそれだけで消えることは一般にありません。担当する代理店を移す手続き、委託契約を終える手続き、登録の届け出、記録の引き継ぎや処分を、所属の保険会社と順番を決めて進めます。お客様には、新しい担当と連絡先を知らせます。", acts:["所属の保険会社ごとに、委託契約を終える手続きと担当の移し方を確かめる", "手続き中の契約・満期が近い契約・苦情の対応中の契約を一覧にする", "お客様へのお知らせの文と送る時期を決める"], actHead:"今日やること", note:"委託契約を終える手続き・担当の移し方・届け出・記録の扱いは、保険会社と登録の種類で違う。所属の保険会社で確かめる。", say:"代理店の体制が変わりますが、ご契約はこれまでどおり続きます。新しい担当と連絡先をお知らせします。", more:"やめる時期が決まったら、早めに保険会社に伝えるほど、お客様を待たせない引き継ぎができます。お客様の書類や記録は、引き継ぐもの・保険会社に返すもの・処分するものに分け、処分の方法も保険会社の決まりで確かめます。", why:"お客様の契約は続くのに、連絡先が分からなくなると、事故や手続きのときに困るからです。引き継ぎを決めてからやめれば、お客様の暮らしに穴をあけずに済みます。" },
      { key:'faq_xdun_tantou_ukeru', faq:1, grp:'dun', q:"ほかの代理店のお客様の担当を引き継ぐことになった", re:/(ほかの|他の|他社の|別の)代理店(の|から)[^。]{0,12}(引き継|移って|移管|受け入れ)|担当代理店の変更[^。]{0,8}受け入れ|移ってきた(お客様|契約)/, ng:/合併|統合|譲渡/, head:"契約の中身・手続き中のもの・満期や更新の時期を確かめ、早めにお客様へ担当の挨拶をします。", body:"担当が移ってきた契約は、保険会社の記録で契約の中身、保険料の払い方、手続き中のもの、満期や更新の時期を確かめます。前の代理店がどんな説明をしていたかは分からないことが多いので、決めつけずに、お客様に今のご希望を伺い直します。顧客台帳に移ってきた日と経緯を書いておきます。", acts:["移ってきた契約を一覧にし、満期や更新が近い順に並べる", "お客様への担当の挨拶を、いつどの方法でするか決める", "顧客台帳に、移ってきた日と経緯を書き足す"], actHead:"今日やること", note:"担当を受け入れる手続きと、確かめられる記録の範囲は、保険会社で違う。所属の保険会社で確かめる。", say:"このたびご契約の担当となりました。いまのご契約の中身と、ご希望を改めて伺えますか。", more:"移ってきた直後に新しい保険を勧めると、担当が変わった理由を疑われることがあります。最初は、契約の中身の確かめと連絡先の案内にとどめ、見直しの話はお客様の希望を伺ってからにします。", why:"お客様は、担当が変わったことで不安を感じていることが多いからです。最初の連絡が確かめと挨拶であれば、信頼を引き継ぎやすくなります。" },
      { key:'faq_xdun_kaigyou', faq:1, grp:'dun', q:"保険代理店を始めるには、何が要る？", re:/代理店[^。]{0,6}(を)?(始め|開業|立ち上げ|開く|開き)|委託契約を結ぶまで/, ng:/独立|将来の夢|向いて/, head:"保険会社との委託契約、登録と届け出、社内の体制の三つを、保険会社の担当と順番に整えます。", body:"保険代理店を始めるには、扱いたい保険会社と代理店委託契約を結び、決められた登録や届け出をします。保険会社は、代理店の体制（募集の手順・お客様の情報の扱い・苦情の受け方・教育）や、募集人の資格を確かめます。何が要るかは保険の種類と保険会社で違うので、保険会社の代理店の担当に相談するところから始めます。", acts:["扱いたい保険の種類と保険会社を書き出す", "保険会社の代理店の担当に、委託契約と登録の流れを聞く日を決める", "社内の規程や記録の残し方を、何から作るか一覧にする"], actHead:"今日やること", note:"委託契約の条件・登録と届け出の手続き・求められる体制は、保険の種類と保険会社で違う。所属を考えている保険会社と、登録の窓口で確かめる。", say:"保険会社から任された代理店として、ご案内できる準備を整えています。", more:"始める前に、事務所・お客様の情報を扱う場所・保険料をお預かりするときの扱いを決めておくと、委託契約の確かめも進みやすくなります。最初から多くの保険会社を扱うより、扱える事務の量で決めるほうが間違いを防げます。", why:"代理店は、保険会社から募集を任される立場だからです。体制が整っていないと、お客様への説明や手続きの質を保てず、委託契約も結べません。" },
      { key:'faq_xdun_yubin', faq:1, grp:'dun', q:"お客様あての郵便が戻ってきた", re:/(郵便|郵送|手紙|書類)[^。]{0,10}(戻って|戻った|返送|宛先不明|届かなかった)|届かなかった郵便/, ng:/住所の変更|住所変更|引っ越|連絡がつか|送り先を間違|宛先を間違/, head:"開けずに戻ってきた理由を確かめ、記録に残してから、お客様に別の方法で連絡します。", body:"郵便が戻ってきたときは、封を開けずに、戻ってきた理由（宛先不明・転居先不明・受け取りがない）を確かめます。戻ってきた日と郵便の中身の種類を記録し、電話など別の方法でお客様に連絡して、今の住所を伺います。保険会社からの大事な書類なら、保険会社にも戻ってきたことを伝えます。", acts:["戻ってきた郵便の宛名・中身の種類・戻った理由・日付を記録する", "お客様に電話など別の方法で連絡し、今の住所を伺う", "保険会社の書類なら、所属の保険会社の担当に戻ったことを伝える"], actHead:"今日やること", note:"戻ってきた書類の扱いと保管の仕方は、保険会社と社内の決まりで違う。所属の保険会社と御社の規程で確かめる。", say:"お送りした書類がこちらに戻ってまいりました。いまのご住所を伺ってもよろしいですか。", more:"戻ってきた郵便は、お客様の情報が書かれたものなので、決まった場所に保管し、放っておかないことが大切です。住所が分かったら、住所の変更の手続きをご案内します。", why:"戻ってきた書類の中には、更新や払込みの案内など、届かないとお客様が困るものがあるからです。記録を残しておけば、届かなかったことをあとで説明できます。" },
      { key:'faq_xdun_azukarisho', faq:1, grp:'dun', q:"お客様から書類を預かるとき、預かり証は要る？", re:/預かり証|預り証|(書類|原本)を預か[^。]{0,10}(残す|記録|決まり|とき)/, ng:/印鑑|通帳|現金|持ち帰|自宅|なくし|キャッシュカード/, head:"何を・いつ・誰が預かり、いつ返すかを書いた控えを残し、お客様にも渡します。", body:"お客様から書類を預かるときは、預かったものの名前、預かった日、預かった人、返す予定の日を書いた控えを作り、お客様にも渡すと、あとで行き違いが起きません。預かり証の様式が保険会社や社内で決まっていることもあります。原本は、できるだけその場で写しを取って返す形にします。", acts:["預かる書類の名前・日・預かった人・返す日を書く控えの形を決める", "保険会社と社内に、預かり証の様式の決まりがあるか確かめる", "預かった書類を置く決まった場所を決める"], actHead:"今日やること", note:"預かり証の様式・預かってよい書類・保管の仕方は、保険会社と社内の規程で違う。所属の保険会社と御社の規程で確かめる。", say:"この書類をお預かりします。お預かりした日と返す予定の日を書いた控えをお渡しします。", more:"預かったままにすると、なくしたときにお客様の大事な書類を失うことになります。返したときにも、返した日を記録しておきます。印鑑や通帳など、預かってはいけないものは預かりません。", why:"預かった書類は、お客様の大切な情報だからです。控えがあれば、預かった・返したの行き違いを防ぎ、なくしたときにも何が無いかがすぐ分かります。" },
      { key:'faq_xdun_noriai_jimu', faq:1, grp:'dun', q:"乗合で保険会社ごとに事務が違って混乱する", re:/(乗合|保険会社ごと|保険会社が多)[^。]{0,12}(事務|手続|混乱|間違え|違い|整理)/, ng:/とは|意味|増や|追加|比較|比べ|推奨/, head:"保険会社ごとの違いを、手続きの種類ごとに一枚の早見表にまとめ、迷ったら手引きに戻ります。", body:"乗合の代理店では、同じ手続きでも保険会社ごとに書類・送り先・締めの日が違います。手続きの種類（申込み・名義の変更・解約・事故の連絡）を縦に、保険会社を横に並べた早見表を作ると、どこが違うかが一目で分かります。早見表は保険会社の手引きから作り、手引きが変わったら直します。", acts:["よく使う手続きを五つほど選び、保険会社ごとの書類と送り先を表にする", "早見表の出どころの手引きの名前と、直した日を書き添える", "表にない手続きは、保険会社の手引きで確かめる決まりにする"], actHead:"今日やること", note:"手続きの書類・送り先・締めの日は保険会社ごとに決まっている。所属の保険会社の事務の手引きと担当で確かめる。", say:"保険会社ごとにお手続きの方法が違うため、確かめてから進めます。少しお時間をいただくことがあります。", more:"早見表は便利ですが、古くなると間違いの元になります。保険会社からの事務連絡で手続きが変わったときに、誰が表を直すかを決めておきます。新しい募集人には、まず早見表の見方から伝えます。", why:"保険会社が多いほど、記憶に頼った手続きは間違えやすくなるからです。違いを見える形にしておけば、人が替わっても同じ手続きができます。" },
      { key:'faq_xdun_nyusha', faq:1, grp:'dun', q:"新しい募集人が入ったとき、事務で何を整える？", re:/(新しい|新しく入った|入社した)(募集人|社員|人|スタッフ)[^。]{0,14}(事務|登録|手続|準備|流れ|整え)/, ng:/教育|育て|教え|面接|採用|辞め|指導/, head:"登録と届け出が済むまで募集をさせず、そのあいだにIDや資料、社内の決まりの共有を整えます。", body:"新しい募集人は、試験や登録、保険会社への届け出が済むまで、お客様に保険を勧めることができません。そのあいだに、保険会社の代理店システムのID、名刺、資料、社内の規程と手順書の共有、お客様の情報の扱いの決まりの確かめを進めます。募集を始めてよい日を、本人と社内で共有します。", acts:["登録と届け出の手続きと、募集を始められる日を確かめる", "IDや名刺、資料、手順書を渡す日を一覧にする", "社内の規程とお客様の情報の扱いを本人と読み合わせる日を決める"], actHead:"今日やること", note:"登録と届け出の手続き・募集を始められる時期は、保険の種類と保険会社で違う。所属の保険会社と社内の登録の担当で確かめる。", say:"新しく担当に加わった者です。いまは先輩と一緒にご案内しています。", more:"登録が済む前に、お客様の前で保険の中身を説明させると、登録のない募集になるおそれがあります。同行させるときも、話すのは登録のある募集人にします。始めてよい日は、社内の一覧に書いておきます。", why:"登録と届け出が済んでいない人の募集は、お客様にも代理店にも大きな問題になるからです。事務を先に整えておけば、始めた日から安心して動けます。" },
      { key:'faq_xdun_nenkan', faq:1, grp:'dun', q:"代理店の一年の事務の予定は、どう立てる？", re:/(一年|年間|毎年)[^。]{0,6}(の)?(事務|届け出|点検|予定)/, ng:/目標|数字|売上|成績|お金|支払|資金|賞与|ボーナス|税/, head:"届け出・点検・研修・規程の見直しの時期を一枚の暦に並べ、担当と準備を始める日を書きます。", body:"代理店の事務には、毎年決まった時期に来るものがあります。保険会社の点検、募集人の研修や資格の更新、規程の見直し、帳簿や記録の整理、商品の改定の時期などです。これを一枚の暦に並べ、それぞれに担当と、準備を始める日を書いておくと、直前に慌てずに済みます。時期は保険会社の案内で確かめます。", acts:["去年の点検・研修・届け出の時期を思い出し、暦に書き出す", "それぞれに担当と準備を始める日を書く", "保険会社から時期の案内が来たら、暦を直す人を決める"], actHead:"今日やること", note:"届け出・点検・研修の時期は、保険会社と登録の種類で違う。所属の保険会社の案内と社内の規程で確かめる。", say:"手続きの時期を決めて、社内で準備を進めています。ご案内が必要なときは、早めにご連絡します。", more:"暦は、一人の頭の中ではなく社内で見られる場所に置きます。毎月の初めに今月と来月の予定を見る時間を決めておくと、抜けにくくなります。", why:"一年に一度の事務ほど、やり方を忘れやすいからです。暦と担当を決めておけば、人が替わっても同じ時期に同じ準備ができます。" },
      /* eba.json */
      { key:'faq_xeba_apo_kikeiyaku', faq:1, grp:'eba', q:"既契約のお客様にアポの電話をするとき、最初に何と言う？", re:/(既契約|契約(して|中|済み)|ご契約)[^。]{0,12}(お客様|お客さん|方)?[^。]{0,10}(アポ|面談のお願い)[^。]{0,10}(電話|架電|連絡)/, ng:/部下|後輩|新人|メンバー|断られ|怖|苦手/, head:"最初に名乗って、電話の用件と、かかる時間を一言で伝えます。", body:"既契約のお客様は、電話の向こうで「何かあったのか」「売り込みか」と身構えます。名乗りのあとすぐに、今日の用件（契約の点検のお願い・ご案内したい手続き など）と、電話が短く終わることを伝えると、話を聞いていただきやすくなります。会うかどうかはお客様に決めていただき、断られても次の連絡の方法だけ伺って終えます。", acts:["名乗り・会社名・担当している契約の名前を、最初の一息で言う", "用件は一つだけにして「少しだけお時間よろしいですか」と都合を伺う", "会う理由を、お客様の側の言葉（ご契約の中身の確かめ）で伝える", "都合が悪ければ、かけ直してよい時間帯を伺って切る"], actHead:"電話の順番", note:"お客様への連絡の方法と記録の残し方は、所属の保険会社と御社の手順で確かめる。", say:"いつもお世話になっております、ご契約を担当している◯◯です。ご契約の中身を一度ご一緒に確かめるお時間をいただけないかと思い、お電話しました。今、少しだけよろしいですか。", more:"よくある失敗は、名乗ったあとに天気や近況の話を長く続け、用件が最後になることです。お客様は用件が分からないまま聞くので、落ち着きません。会う理由は、証券の確かめ・ご家族の変化の確かめ・手続きのご案内など、お客様に役立つことにします。新しい保険の話をしたいなら、そのことも隠さずに伝えます。", why:"電話は顔が見えないぶん、用件が分からない時間がお客様の不安になるからです。先に用件と時間を言うと、お客様は聞くかどうかを自分で決められ、こちらへの信頼も崩れません。" },
      { key:'faq_xeba_rusuden', faq:1, grp:'eba', q:"お客様の留守番電話に、何を残せばいい？", re:/留守番電話|留守電|留守番(の)?メッセージ/, ng:/部下|後輩|新人|メンバー/, head:"名前と会社名と、急ぎかどうかだけを短く残し、契約の中身は話しません。", body:"留守番電話は、お客様ご本人以外の方が聞くこともあります。名前・会社名・用件のおおまかな種類（ご案内したいことがある、など）と、急ぎかどうか、こちらからかけ直す時間を残します。契約の内容・病気や保険金の話・金額は吹き込みません。急ぎの用件なら、折り返しの番号をゆっくり二度言います。", acts:["最初に名前と会社名、最後にもう一度名前を言う", "用件は「ご契約のことでご案内があります」くらいにとどめる", "急ぎでないときは「またこちらからお電話します」と伝えて、折り返しの負担をかけない", "残した日時と内容を、お客様の記録に書いておく"], actHead:"残すこと", note:"留守番電話やメッセージに残してよい範囲は、御社の個人情報の取り扱いの手順で確かめる。", say:"◯◯保険代理店の◯◯です。ご契約のことでご案内があり、お電話しました。急ぎではありませんので、またこちらからおかけします。失礼いたします。", more:"家の電話やご家族と共用の電話では、とくに中身を言わないことが大切です。かけ直すと伝えたら、その時間を守ってかけ直します。何度かけてもつながらないときは、手紙やメールなど、お客様が前に教えてくださった別の方法に切り替えます。", why:"留守番電話は誰が聞くか選べないからです。保険の話は、ご家族にも知られたくないことを含む場合があります。名前と会社名だけなら、誰が聞いても困らず、お客様は折り返すかどうかを自分で決められます。" },
      { key:'faq_xeba_youken', faq:1, grp:'eba', q:"電話で「何の用ですか」と警戒された", re:/(何の用|用件は(何|なに)|ご用件は)[^。]{0,20}(警戒|身構|聞かれ|言われ|どう返|返す)|(電話|架電)[^。]{0,12}(警戒され|身構えられ)/, ng:/部下|後輩|新人|メンバー/, head:"用件を一文で言い直し、今ここで決めることは何もないと伝えます。", body:"警戒されるのは、お客様にとって用件が見えないからです。言い訳や前置きを重ねずに、何のための電話かを一文で言い直します。そのうえで、今は日程か次の連絡の方法を伺うだけで、何かを決めていただく電話ではないことを添えます。話す気がない様子なら、その場で引いて、記録に残します。", acts:["「ご契約の中身の確かめのお願いです」のように、用件を一文で言い直す", "「今日は何かを決めていただくお電話ではありません」と先に言う", "続けてよいか、かけ直すかを、お客様に選んでいただく"], actHead:"返し方", note:"電話での勧誘の仕方と、記録の残し方は、所属の保険会社と御社の手順で確かめる。", say:"突然お電話して失礼しました。ご契約の中身を一度ご一緒に確かめていただけないかという、お願いのお電話です。今日何かを決めていただくことはありませんので、ご都合の良いときを伺えればと思います。", more:"警戒のあとに長く説明を始めると、売り込みの電話だと受け取られます。用件を短くし、相手の返事を待つ時間を取ります。お客様が何度も同じ電話を受けて困っている場合もあるので、連絡してほしくないと言われたら、その気持ちを記録して、同じ連絡を繰り返さないようにします。", why:"人は相手の目的が分からないと身を守ろうとするからです。目的と、決めなくてよいことが分かると、話を聞くかどうかを落ち着いて選べます。" },
      { key:'faq_xeba_nittei', faq:1, grp:'eba', q:"アポの日程の候補は、どう出せばいい？", re:/(アポ|面談|訪問|商談)[^。]{0,6}(日程|日時|候補日|候補の日)[^。]{0,10}(出し方|決め方|候補|いくつ|どう(出|決|提案))/, ng:/部下|後輩|新人|メンバー|キャンセル|延期|リスケ|変更/, head:"こちらから二つか三つの候補を出し、合わなければお客様の都合を伺います。", body:"「いつがいいですか」と丸ごと聞くと、お客様は予定を見直す手間がかかり、返事が後回しになりがちです。こちらから日にちと時間帯の候補をいくつか出すと選ぶだけで済みます。どれも合わなければ、都合のよい曜日や時間帯を伺い、改めて候補を出します。決まったら、日時・場所・所要時間・持ち物を文字で送ります。", acts:["平日と週末、昼と夕方のように、性質の違う候補を混ぜて出す", "面談にかかる時間の目安を、候補と一緒に伝える", "決まったら、日時・場所・所要時間・持ってきていただく物を文字で送る"], actHead:"現場で使うなら", note:"面談の連絡と記録の残し方は、御社の手順で確かめる。", say:"来週ですと、火曜の午後か、木曜の夕方はいかがでしょうか。どちらも合わなければ、ご都合のよい曜日を教えてください。お時間はおおよそ一時間を見ています。", more:"ご夫婦でお会いしたいときは、お二人がそろう時間を先に伺います。候補を出すときに、お客様が選びにくい時間（早朝・夜遅く）を混ぜないようにします。決まった日の前に予定が変わることもあるので、連絡のつく方法を一つ確かめておきます。", why:"選ぶだけで済むと、お客様の手間が小さくなり、返事が早くなるからです。合わないときにお客様の都合を伺えば、押しつけにもなりません。" },
      { key:'faq_xeba_zenjitsu', faq:1, grp:'eba', q:"面談の前日に、確認の連絡は入れたほうがいい？", re:/(面談|アポ|訪問|商談)[^。]{0,6}(前日|前の日)[^。]{0,12}(確認|連絡|リマインド|メール|電話)|(前日|前の日)[^。]{0,8}(確認|リマインド)[^。]{0,6}(連絡|メール|電話)/, ng:/部下|後輩|新人|メンバー|準備/, head:"入れます。日時・場所・持ち物だけを短く送り、変更してよいことも添えます。", body:"前日の連絡は、お客様が予定を思い出し、持ち物をそろえる助けになります。長い文は要りません。日時・場所・所要時間・持ってきていただく物（保険証券など）を短く送り、都合が悪くなったら遠慮なく言ってほしいと添えます。変更してよいと書いておくと、当日の急な取りやめより、前もって連絡をいただけることが多くなります。", acts:["日時・場所・所要時間・持ち物を、四行ほどにまとめて送る", "「ご都合が変わった場合は、お気軽にご連絡ください」と一言添える", "お客様が前に選んだ連絡の方法で送る"], actHead:"送る中身", note:"お客様への文字の連絡の方法（メール・ショートメッセージ・LINE など）が使えるかは、御社と所属の保険会社の手順で確かめる。", say:"明日はお時間をいただきありがとうございます。午後二時に、ご自宅に伺います。ご契約中の保険証券があれば、ご用意をお願いします。ご都合が変わった場合は、お気軽にお知らせください。", more:"持ち物は、こちらが本当に必要なものだけに絞ります。多すぎると準備が負担になります。前日の連絡で、聞いておきたいことを一つ書き添えてもよいです（「明日はお子様のことから伺いたいと思っています」など）。お客様は面談の中身を前もって考えておけます。", why:"人の予定は日がたつと記憶から薄れるからです。前日に思い出していただくと準備がそろい、面談の時間をお客様の話に使えます。変更の逃げ道を書いておくと、お客様の負担も軽くなります。" },
      { key:'faq_xeba_chikoku', faq:1, grp:'eba', q:"面談の約束の時間に遅れそう", re:/(面談|アポ|訪問|約束|商談)[^。]{0,12}(遅れそう|遅れる|遅刻|間に合わな|間に合いそうにな)|(遅れそう|遅刻しそう)[^。]{0,10}(お客様|お客さん|面談|訪問)/, ng:/部下|後輩|新人|メンバー|お客様が遅|お客さんが遅|お客様が遅刻|お客さんが遅刻/, head:"遅れると分かった時点で連絡し、着く時刻の見込みと、日を改める道を伝えます。", body:"遅れの連絡は、早いほどお客様の負担が小さくなります。約束の時刻を過ぎてからではなく、分かった時点でお詫びと着く時刻の見込みを伝えます。お客様の次の予定に響きそうなら、短くするか日を改めるかを、お客様に選んでいただきます。着いたら言い訳より先にお詫びし、終わる時刻は前の約束どおりに守ります。", acts:["遅れが分かった時点で、電話でお詫びと着く時刻の見込みを伝える", "「お時間を短くするか、別の日に改めるか、どちらがよろしいですか」と伺う", "着いたら最初にお詫びし、終わる時刻は前のとおりにする"], actHead:"その場でやること", note:"遅れや取りやめの連絡の残し方は、御社の手順で確かめる。", say:"申し訳ありません、道が混んでおり、お約束から十五分ほど遅れそうです。このあとのご予定に差し支えるようでしたら、別の日に改めさせていただくこともできます。", more:"見込みは少し長めに伝え、それより早く着くようにします。短く言って二度遅れの連絡をすると、信頼を大きく損ないます。お客様が日を改めることを選んだら、その場で次の候補を二つほど出し、改めて文字で送ります。", why:"お客様の時間は、こちらの都合で動かしてよいものではないからです。早い連絡と選べる道があれば、お客様は自分の予定を守れ、こちらの誠実さも伝わります。" },
      { key:'faq_xeba_encho', faq:1, grp:'eba', q:"面談が終わる予定の時刻を過ぎそう", re:/(面談|商談|打ち合わせ)[^。]{0,10}(長引|延び|延長|オーバー|過ぎそう|長くな|終わらせ方|時間どおり|時間通り|時間を過ぎ)|(終わる|終わり|約束)の?(時刻|時間)[^。]{0,8}(過ぎ|延ば|オーバー)/, ng:/部下|後輩|新人|メンバー|会議|朝礼/, head:"約束の時刻が来たら一度区切り、続けるか次に回すかをお客様に伺います。", body:"話が弾んでいても、お客様には次の予定や疲れがあります。約束の時刻が近づいたら、こちらから「お時間になりました」と区切り、今日分かったことを短くまとめます。続けてよいかを伺い、迷う様子があれば、残りは次の面談に回します。決める話を長引いた時間の中で進めないことも大切です。", acts:["約束の少し前に「そろそろお時間です」とこちらから言う", "今日伺ったことと、次に話すことを一言ずつまとめる", "続けるか次回にするかを、お客様に選んでいただく"], actHead:"区切り方", note:"面談の記録の残し方と、ご高齢のお客様の面談の長さの考え方は、御社と所属の保険会社の手順で確かめる。", say:"お約束のお時間になりました。今日は大切なことをたくさん伺えました。このまま少し続けてもよろしいですか、それとも続きは次回にしましょうか。", more:"延ばす場合も、どれくらい延ばすかを先に言います。「あと十分ほど」と決めてから続けると、お客様は安心して話せます。疲れた様子のときは、こちらから次回を提案します。長い時間の最後に申込みの話をすると、判断の負担が大きくなります。いつも長引くなら、始めに終わりの時刻を伺い、話すことを二つか三つに決めておきます。", why:"約束を守ることが、次の面談への信頼になるからです。区切ってお客様に選んでいただけば、時間の主導権がお客様に残り、押しつけにもなりません。" },
      { key:'faq_xeba_shokaisaki', faq:1, grp:'eba', q:"紹介していただいた方に、初めて連絡するときは？", re:/紹介(して|され|で|いただい|頂い|してもらっ)[^。]{0,10}(方|人|相手|連絡先|先)[^。]{0,10}(初めて|最初|一回目)?[^。]{0,8}(連絡|電話|メール|お会い)|紹介先[^。]{0,10}(連絡|電話|メール)/, ng:/部下|後輩|新人|メンバー|お礼|御礼|報告|紹介料|謝礼/, head:"紹介してくださった方の名前と、どう聞いて連絡したかを最初に伝えます。", body:"紹介された方は、知らない人から連絡が来た、と受け取ります。最初に、誰の紹介か、その方からどう聞いたかを伝えると、連絡の理由が分かり、警戒が緩みます。そのうえで、会うかどうかはご本人が決めてよいこと、紹介者に気を使って会わなくてよいことを伝えます。連絡先は、紹介者がご本人の了承を得ているかを先に確かめておきます。", acts:["連絡の前に、紹介者がご本人の了承を得ているかを確かめる", "最初の一言で、紹介者の名前と、どう聞いたかを伝える", "「ご紹介だからと気になさらず、ご判断ください」と添える", "連絡したことを、紹介者に一言伝えておく"], actHead:"最初の連絡の順番", note:"紹介でいただいた連絡先の取り扱いは、御社の個人情報の手順で確かめる。紹介のお礼の決まりは社内で確かめる。", say:"◯◯様からご紹介いただきました、保険代理店の◯◯です。保険の見直しを考えていらっしゃると伺い、ご連絡しました。ご紹介だからとお気になさらず、話を聞いてみるかどうかは、ご自身で決めてください。", more:"紹介者が話していた内容と、ご本人の思いがずれていることがあります。最初の連絡では、紹介者から聞いた話を決めつけず、「どんなことが気になっていますか」とご本人から伺います。会わないと言われたら、すぐに引き、紹介者にもその旨を伝えます。", why:"連絡の理由と、断ってよいことが分かれば、紹介された方は落ち着いて判断できるからです。紹介者の名前を出すのは、つながりを示すためで、会う義理を作るためではありません。" },
      { key:'faq_xeba_shokai_kotowari', faq:1, grp:'eba', q:"紹介をお願いしたら、断られた", re:/紹介[^。]{0,10}(お願い|頼ん|頼み)[^。]{0,10}(断られ|嫌な顔|渋られ|無理と言われ)|紹介(を)?断られ/, ng:/部下|後輩|新人|メンバー|紹介が出な|紹介が出ませ|頼み方/, head:"すぐにお礼を言って引き、関係はこれまでどおりと伝えます。", body:"紹介を断る理由は、知人に迷惑をかけたくない、保険の話を持ち出しにくい、など、お客様の気づかいであることが多いです。理由を問いただしたり、もう一度頼んだりせず、聞いてくださったことへのお礼を言って引きます。そのあとも、ご契約の点検や連絡はこれまでどおり続けます。", acts:["「お気になさらないでください」とお礼を言って、その話を終える", "断られたことを記録し、しばらくは同じお願いをしない", "次の連絡も、ご契約の点検や手続きの話など、いつもどおりに戻す"], actHead:"そのあとの動き", note:"紹介のお願いと記録の残し方、紹介のお礼の決まりは、御社と所属の保険会社の手順で確かめる。", say:"聞いてくださってありがとうございます。お気になさらないでください。これからも、ご契約のことは変わらずお手伝いします。", more:"断られたあとの態度は、お客様がよく見ています。急に連絡が減ると、紹介のためだけに付き合っていたように見えます。もし将来、お客様のほうから「知人が困っている」と話が出たら、そのときに、紹介者に負担のかからない形（こちらの連絡先を渡していただくだけ、など）をお伝えします。", why:"紹介は、お客様の信頼を分けていただくことだからです。断る自由があると分かれば、関係は傷つかず、お客様が本当に紹介したいと思ったときに思い出していただけます。" },
      { key:'faq_xeba_hisashiburi', faq:1, grp:'eba', q:"長い間連絡していなかったお客様に、連絡しにくい", re:/(長い間|長く|何年も|しばらく|ずっと|久しく)[^。]{0,8}(連絡して(い)?な|会って(い)?な|放って|ご無沙汰)|ご無沙汰(して|の)[^。]{0,10}(お客様|お客さん|方)|久しぶりに[^。]{0,10}(お客様|お客さん|既契約)[^。]{0,8}(連絡|電話)/, ng:/部下|後輩|新人|メンバー|友人|友達|知人|知り合い|親戚|アポ/, head:"連絡しなかったことを一言お詫びし、ご契約の中身の確かめから入ります。", body:"間が空いたことをお客様も感じています。言い訳を重ねず、ご無沙汰をお詫びする一言から始めます。そのうえで、今のご契約が暮らしに合っているかを確かめたい、という理由で会う時間をお願いします。住所や連絡先・ご家族が変わっていることも多いので、手続きの漏れがないかも一緒に確かめます。", acts:["「長くご連絡できず、失礼しました」と最初にお詫びする", "連絡の理由は、ご契約の中身と登録の内容の確かめにする", "住所・連絡先・受取人・ご家族の変化を、手続きの漏れがないか確かめる", "次からは、年に一度の点検の時期をお客様と決めておく"], actHead:"現場で使うなら", note:"住所や受取人の変更などの手続きは、所属の保険会社の手順と書類で確かめる。", say:"長くご連絡できず、失礼しました。ご契約の中身が今の暮らしに合っているか、一度ご一緒に確かめさせていただけないかと思い、ご連絡しました。", more:"連絡しなかった間に、お客様が入院や引っ越しをしていることがあります。請求できたものが手つかずになっていないか、届くはずの書類が届いていないかを、点検の中で一緒に見ます。お客様から「誰も連絡してこなかった」と言われたら、そのとおりなので、言い返さずに受け止めます。", why:"空いた間を責められる前にこちらから認めると、お客様は話を聞く構えに戻りやすいからです。会う理由をお客様の得になる確かめにすれば、久しぶりの連絡でも売り込みに見えません。" },
      { key:'faq_xeba_hikitsugi', faq:1, grp:'eba', q:"前任から引き継いだお客様に、最初の連絡は何と言う？", re:/(引き継いだ|引き継ぎで|引継いだ|前任(の担当)?から|担当替えで)[^。]{0,14}(お客様|お客さん|既契約)[^。]{0,14}(最初|初めて|あいさつ|挨拶|連絡|電話)/, ng:/部下|後輩|新人|メンバー|上司として|管理職|辞めた募集人|連れて行|初めて会う|初めてお会い/, head:"担当が変わった理由と、ご契約の中身はそのまま続くことを、最初に伝えます。", body:"担当が変わると、お客様は「契約はどうなるのか」「また一から話すのか」と不安になります。最初の連絡では、名乗りと、担当が変わったこと、ご契約の中身や手続きはそのまま続くことを伝えます。そのうえで、前の担当から聞いていることを決めつけず、一度会ってご契約を一緒に確かめたいとお願いします。", acts:["名乗りと、担当が変わったことを、最初の一息で伝える", "ご契約の中身・保険会社の窓口・手続きは変わらないと添える", "前の担当から引き継いだ記録を読み、聞き直す手間を減らす", "一度お会いして、登録の内容とご家族の変化を確かめる時間をお願いする"], actHead:"最初の連絡でやること", note:"担当の変更の届けと、お客様へのお知らせの方法は、所属の保険会社と御社の手順で確かめる。", say:"このたび、◯◯に代わってご契約を担当することになりました、◯◯です。ご契約の中身はそのまま続きますので、ご安心ください。一度、ご契約の内容をご一緒に確かめるお時間をいただけますか。", more:"前の担当とお客様のあいだで約束していたこと（次の点検の時期・調べると言っていたこと）が残っていないかを、記録で先に確かめます。お客様が前の担当を気に入っていた場合は、前の担当を悪く言わず、引き継いだことを大切にする姿勢を見せます。担当の変更を知らせる書面が保険会社から届くこともあるので、その時期も確かめておきます。", why:"お客様が気にしているのは、担当の人より先に、ご自分の契約が守られるかどうかだからです。続くことが分かれば、新しい担当の話を聞く構えができます。" },
      { key:'faq_xeba_koukai_seki', faq:1, grp:'eba', q:"更改の面談が、手続きだけで終わってしまう", re:/更改[^。]{0,12}(手続きだけ|事務的|作業だけ|話を広げ|ほかの話|他の話|何を話|話すこと|会話が)/, ng:/部下|後輩|新人|メンバー|生保|生命保険|教える時間|追われ/, head:"更改の席では、補償の確かめのあとに、この一年の暮らしの変化を一つ伺います。", body:"更改は、お客様と会える数少ない機会です。手続きの説明と補償の確かめを済ませたあと、この一年で変わったこと（車に乗る人・住まい・ご家族・仕事）を一つだけ伺います。変化があれば、今の補償で足りているかを一緒に見ます。ほかの保険の話は、お客様の話から必要が見えたときにだけ、次の機会として伺います。", acts:["手続きと補償の確かめを先に終え、お客様の用件を済ませる", "「この一年で、車に乗る方やお住まいに変わりはありましたか」と一つだけ聞く", "変化が出たら、今の補償で足りているかを一緒に確かめる", "ほかの話は、お客様の言葉から必要が見えたときだけ、次回にお願いする"], actHead:"現場の順番", note:"更改のときの説明と意向の確かめの手順は、所属の保険会社と御社の手順で確かめる。", say:"手続きはこれで済みました。せっかくですので一つだけ伺えますか。この一年で、車に乗る方やお住まい、ご家族のことで変わったことはありましたか。", more:"変化を一度にたくさん聞くと、お客様は面倒に感じます。一つ聞いて、出てきた話を深めるほうが、自然に続きます。例えば、お子様が運転を始めた・在宅の仕事が増えた・親御さんと同居を始めた、といった話は、補償の見直しにもつながります。何も変わっていなければ、それを記録して終えます。", why:"更改はお客様にとって手続きの日で、提案の日ではないからです。用件を先に済ませると、お客様は落ち着いて話してくださり、変化の話から本当に必要なことが見えてきます。" },
      { key:'faq_xeba_koukai_yuusou', faq:1, grp:'eba', q:"更改は郵送で済ませたいと言われた", re:/(更改|更新|継続)[^。]{0,14}(郵送|書類だけ|会わずに|会わなくて|来なくていい|手続きだけで(いい|済ま|お願い))/, ng:/部下|後輩|新人|メンバー|追われ|教える時間/, head:"お客様の希望に合わせ、説明と意向の確かめは、保険会社の決めた方法で漏れなく行います。", body:"会わずに済ませたいという希望は、お客様の都合として受け止めます。ただ、補償の中身が変わる更改では、変わる点の説明と、お客様の意向の確かめが要ります。郵送や電話、オンラインなど、所属の保険会社が認める方法で、要点を短く伝えます。変わる点があるときは、その部分だけでも電話で説明させていただけるかを伺います。", acts:["希望を受け止め、手続きの方法を保険会社の決まりで確かめる", "変わる点（保険料・補償・特約）があれば、その部分だけを短く電話で伝える", "書類の返送の期限と、分からないときの問い合わせ先を書いて渡す"], actHead:"現場で使うなら", note:"郵送・電話・オンラインでの更改の手続きと説明の方法は、所属の保険会社と御社の手順で確かめる。", say:"承知しました。書類をお送りします。今回は保険料の変わる点が一つありますので、その部分だけ、五分ほどお電話でご説明させていただけますか。", more:"会いたくない理由が、忙しさなのか、売り込みを避けたいのかで、次の接し方が変わります。売り込みを避けたい様子なら、今回は手続きだけと先に約束すると、次の機会に会っていただきやすくなります。返送が遅れたときに補償が切れないよう、期限の前に一度だけ確かめの連絡を入れます。", why:"お客様の時間を大切にすることと、補償の中身を正しく伝えることは、両方とも欠かせないからです。方法をお客様に合わせても、伝えるべきことを省かなければ、どちらも守れます。" },
      { key:'faq_xeba_susumanai', faq:1, grp:'eba', q:"何度会っても、話が前に進まない", re:/(何度|何回|毎回|いつも)[^。]{0,10}(会って|面談|話して|お会い)[^。]{0,12}(進まな|決まらな|前に進ま|話が進ま)|(面談|お会い|商談)を重ね[^。]{0,10}(進まな|決まらな)|話が前に進まな/, ng:/部下|後輩|新人|メンバー|ご夫婦|奥様|ご主人|奥さん|旦那|社内|会議|上司/, head:"止まっている理由を、必要・中身・お金・時期・決める人のどこかに分けて、お客様と確かめます。", body:"話が進まないときは、お客様の中で何かが決まっていないことが多いです。必要と感じているか、中身が分かっているか、お金の折り合いがつくか、今決める時期か、ほかに決める人がいるか、のどこで止まっているかを、率直に伺います。今は見送るという答えも、お客様の大切な判断として受け止めます。", acts:["「どこで迷っていらっしゃるか、教えていただけますか」と率直に伺う", "必要・中身・お金・時期・決める人のどれかに分けて書き出す", "止まっている点だけを、次の面談の中身にする", "「今は見送る」という選択肢も、こちらから示す"], actHead:"現場の順番", note:"提案の経過と、お客様の意向の記録の残し方は、所属の保険会社と御社の手順で確かめる。", go:"iko", say:"何度もお時間をいただき、ありがとうございます。どこで迷っていらっしゃるのか、率直に伺えますか。今は見送るというお考えでも、もちろん大丈夫です。", more:"よくあるのは、こちらが毎回新しい説明を足して、お客様の迷いが増えていることです。迷いの中身を一つに絞ってから会うと、面談が短くなり、お客様も判断しやすくなります。決める人がほかにいるなら、その方に同席していただけるかを伺います。", why:"迷いの理由が見えないまま会い続けると、お客様もこちらも疲れるからです。止まっている点が分かれば、次に話すことが決まり、お客様が自分で判断できる形になります。" },
      { key:'faq_xeba_sairenraku', faq:1, grp:'eba', q:"断られたお客様に、もう一度連絡してもいい？", re:/断(られ|わられ)(た)?[^。]{0,10}(お客様|お客さん|方|人)[^。]{0,10}(もう一度|また|再び|改めて)[^。]{0,8}(連絡|電話|アポ|会|お願い)/, ng:/部下|後輩|新人|メンバー|怖|苦手|紹介/, head:"はっきり断られた話を、同じ形で繰り返し勧めることはしません。", body:"お客様がはっきり断った話を、時期を置かずに何度も持ち出すと、強引な勧誘と受け取られます。ただ、既にあるご契約の点検・手続き・ご案内の連絡は、断られた提案とは別の用件です。断られたときに「また何かあれば」と言っていただいた範囲や、お客様のほうから相談があったときに、改めてお話しします。連絡してほしくないと言われたら、その気持ちを記録して守ります。", acts:["断られたときの言葉と、連絡してよいかどうかを記録に残す", "既にあるご契約の点検や手続きの連絡は、提案とは分けて行う", "次の提案は、お客様の暮らしの変化や、お客様からの相談があったときにする"], actHead:"現場で使うなら", note:"お断りのあとの連絡の可否と頻度、記録の残し方は、所属の保険会社と御社の手順で確かめる。", say:"以前はご検討いただき、ありがとうございました。今日は、今のご契約の点検のご案内でご連絡しました。前にお話しした件は、お考えが変わったときにお声がけいただければ十分です。", more:"断られた理由が、時期（今は忙しい・家を買うまで）だったのか、中身そのものだったのかで、次の機会が変わります。時期の理由なら、その時期が来たときに一度だけ伺います。中身の理由なら、同じ提案は繰り返しません。記録に理由を残すと、次の連絡で同じ失敗をしません。", why:"断る自由が守られていると分かれば、お客様は安心してこちらと付き合いを続けられるからです。繰り返しの勧誘は、既にあるご契約の信頼まで損ないます。" },
      { key:'faq_xeba_kotowari_riyuu', faq:1, grp:'eba', q:"お客様に断られた理由を、聞いてもいい？", re:/断(られ|わられ)[^。]{0,8}理由[^。]{0,10}(聞|伺|尋ね|確かめ|教えて)|(見送|お断|断)り?(られた)?の?理由[^。]{0,10}(聞|伺|尋ね)|見送られた理由/, ng:/部下|後輩|新人|メンバー|紹介/, head:"一度だけ、責めない聞き方で伺い、答えたくない様子なら深追いしません。", body:"断られた理由は、次にほかのお客様へ話すときの大切な手がかりになります。ただ、理由を問いただされるとお客様は言い訳を求められているように感じます。決めてくださったことへのお礼を先に言い、「今後の参考に」と前置きして一度だけ伺います。答えにくそうなら、その場で話を終えます。", acts:["最初に、検討してくださったことへのお礼を言う", "「よろしければ、今後の参考に一つだけ伺えますか」と前置きする", "返ってきた理由に反論せず、そのまま書き取る", "理由を記録し、提案の仕方を見直す材料にする"], actHead:"聞き方", note:"お客様の意向と、見送りの記録の残し方は、所属の保険会社と御社の手順で確かめる。", say:"ご検討いただき、ありがとうございました。よろしければ今後の参考に、一つだけ伺ってもいいですか。どのあたりが合わなかったでしょうか。お答えにくければ、もちろん大丈夫です。", more:"理由を聞いたあとで、その場で別の案を出すと、断ったことを覆そうとしているように見えます。聞いたら、いったん受け止めて終えます。理由は、保険料・中身・時期・担当への不安などに分けて記録しておくと、自分の提案の癖が見えてきます。", why:"理由を聞くのは、お客様を説得し直すためではなく、こちらの伝え方を直すためだからです。その目的が伝われば、お客様は気持ちよく答えてくださり、関係も続きます。" },
      { key:'faq_xeba_mayoi', faq:1, grp:'eba', q:"迷っているお客様の背中を押してもいい？", re:/背中を押|後押し(して|する|すべ)|(迷って|決めかね|悩んで)(いる|る)?[^。]{0,4}(お客様|お客さん)[^。]{0,12}(どう声|声をかけ|押|どうす|どう接)|(お客様|お客さん)が(迷って|決めかねて|悩んで)[^。]{0,10}(どう声|声をかけ|押|どうす|どう接)/, ng:/部下|後輩|新人|メンバー|自分の背中/, head:"押しません。迷いの中身を言葉にしていただき、決めない選択も一緒に示します。", body:"迷っているのは、お客様の中にまだ確かめたいことがあるからです。ここで背中を押すと、お客様は自分で決めたという感覚を持てず、あとで後悔や解約につながりやすくなります。何が気になっているかを言葉にしていただき、その点だけを一緒に確かめます。今日は決めない、という選択もはっきり示します。", acts:["「どのあたりが気になっていますか」と、迷いの中身を伺う", "気になる点を一つずつ、書面やパンフレットで一緒に確かめる", "「その場で決めていただく必要はありません」と、こちらから言う"], actHead:"現場で使うなら", note:"お客様の意向の確かめと記録の手順は、所属の保険会社と御社の手順で確かめる。", go:"iko", say:"迷われるのは当然だと思います。どのあたりが気になっていらっしゃるか、教えていただけますか。今日決めていただく必要はありませんので、気になる点を一緒に確かめましょう。", more:"よくある迷いは、保険料が続けられるか・本当にこの保障が要るか・家族はどう思うか、の三つです。どれかが分かれば、確かめることが絞れます。迷いが家族のことなら、ご家族と一緒にもう一度お話しする日を決めます。こちらの思いで迷いを打ち消そうとしないことが大切です。", why:"決めるのはお客様だからです。お客様が自分の言葉で納得して決めた契約は、長く続き、何かあったときにも内容を分かっていてくださいます。" },
      { key:'faq_xeba_kangaenaoshi', faq:1, grp:'eba', q:"申込みのあとで、お客様に考え直したいと言われた", re:/(申込み?|申し込み|申し込ん|契約し)[^。]{0,10}(あと|後)[^。]{0,12}(考え直|やっぱり|やめたい)/, ng:/部下|後輩|新人|メンバー|自分が/, head:"引き止めずに気持ちを伺い、取り消しの方法を保険会社の書面どおりに案内します。", body:"考え直したいという声は、まず受け止めます。どこが気になったのかを伺い、説明が足りなかった点があれば正しく伝え直します。それでもやめたいときは、引き止めずに、取り消しや撤回の方法（クーリング・オフなど）を、保険会社の書面と窓口の案内どおりに伝えます。こうした連絡があったことは、上長にも伝えます。", acts:["「どのあたりが気になりましたか」と、責めずに伺う", "説明の足りなかった点があれば、書面で正しく伝え直す", "やめたいときは、取り消しの方法と期限を保険会社の書面で一緒に確かめる", "連絡の内容を記録し、上長に伝える"], actHead:"現場の順番", note:"取り消し・撤回（クーリング・オフなど）が使えるかと期限は、契約の書面と所属の保険会社の窓口で確かめる。社内の報告の手順も確かめる。", go:"kujo", say:"ご連絡ありがとうございます。どのあたりが気になられたか、伺ってもよろしいですか。お取りやめになる場合は、手続きの方法を保険会社の書面でご案内しますので、ご安心ください。", more:"考え直しの理由が、ご家族の反対・保険料の負担・内容の思い違いなど、何かで次の対応が変わります。思い違いなら正しく伝え直し、そのうえでお客様に決めていただきます。引き止めのために条件を変えたり、急がせたりはしません。取り消しの手続きの期限が近いときは、とくに早く案内します。", why:"お客様が落ち着いて考え直せることが、契約の信頼の土台だからです。取り消しの方法を正しく案内すれば、お客様は安心し、こちらの誠実さも伝わります。" },
      { key:'faq_xeba_gamen_hannou', faq:1, grp:'eba', q:"画面越しだと、お客様の反応が分からない", re:/(画面越し|ウェブ会議|web会議|zoom|ズーム|リモート|オンライン)[^。]{0,10}(反応|表情|分かって(いる|る)か|理解|顔色)[^。]{0,10}(分からな|わからな|読めな|つかめな|見えな)/, ng:/部下|後輩|新人|メンバー|1on1|研修|朝礼/, head:"反応は見るものではなく、区切りごとに言葉で伺うものにします。", body:"画面越しでは、うなずきや手元の様子が見えにくく、こちらは説明を続けてしまいがちです。一つの話を終えるたびに「ここまでで気になるところはありますか」と区切り、お客様の言葉で反応を伺います。分かっていただけたかは、お客様に一言で言い直していただくと確かめられます。", acts:["一枚の資料を説明したら、必ず一度区切って伺う", "「今の点を、ご自分の言葉で言うとどうなりますか」と確かめる", "お客様が話すあいだは、こちらの画面の資料を止めて待つ"], actHead:"現場で使うなら", note:"画面越しの面談で説明や手続きを行えるかと、その方法は、所属の保険会社と御社の手順で確かめる。", say:"ここまでで、気になるところや分かりにくいところはありますか。画面越しですと私から表情が見えにくいので、遠慮なくおっしゃってください。", more:"反応が少ないお客様には、選んでいただく形の問いが効きます（「保険料と保障の大きさなら、今日はどちらを先に話しましょうか」）。カメラを切っているお客様には、無理につけてもらわず、声で区切りを増やします。説明が長くなりそうなときは、資料を先に送り、お客様の手元で見ていただきます。", why:"顔が見えにくい場では、黙っていることが分かったしるしにならないからです。区切りごとに言葉で伺えば、分からないまま話が進むことを防げます。" },
      { key:'faq_xeba_kaisen', faq:1, grp:'eba', q:"オンラインでお客様と話している途中で、回線が切れた", re:/(オンライン|ウェブ会議|web会議|zoom|ズーム|リモート|画面越し|ビデオ通話)[^。]{0,16}(回線|接続|通信|画面)[^。]{0,6}(切れ|落ち|途切れ|止ま|固ま)/, ng:/部下|後輩|新人|メンバー|1on1|研修|朝礼/, head:"あらかじめ決めておいた電話に切り替え、切れる前の話の続きから再開します。", body:"回線は切れるものとして準備しておきます。面談の最初に、切れたときはどちらから、どの電話にかけるかを決めておくと、お客様が慌てません。切れたら、こちらからすぐに連絡し、つながったら切れる前にどこまで話したかを確かめてから続けます。大切な説明の途中だったときは、その部分を初めから話し直します。", acts:["面談の最初に「切れたときは、私からお電話します」と決めておく", "つながったら「どこまでお聞きになれましたか」と確かめる", "説明の途中で切れた部分は、初めから話し直す", "続けにくいときは、残りを別の日にする"], actHead:"準備と、切れたとき", note:"画面越しでの説明・申込みの手続きの方法と、途中で切れたときの扱いは、所属の保険会社と御社の手順で確かめる。", say:"途中で切れてしまい、失礼しました。最後にお聞きになれたのは、どのあたりまででしたか。大事な部分でしたので、そこからもう一度ご説明します。", more:"切れた原因がお客様の通信の具合なら、カメラを切って声だけにすると続けられることがあります。申込みの手続きの途中で切れたときは、どこまで進んだかを保険会社の手順で確かめ、自分の判断で続きを進めません。お客様が疲れた様子なら、無理に続けず別の日を決めます。", why:"切れたあとにお客様が困るのは、どうすればよいか分からないことだからです。先に決めておけば慌てずに済み、話の続きを確かめることで、聞き漏れたままの説明も残りません。" },
      { key:'faq_xeba_online_moushikomi', faq:1, grp:'eba', q:"オンラインで、申込みの手続きまで進めていい？", re:/(オンライン|画面越し|ウェブ会議|web会議|zoom|ズーム|リモート|ビデオ通話)[^。]{0,8}(で|の)?[^。]{0,6}(申込み?|申し込み|契約の手続き|契約手続き|契約まで)[^。]{0,10}(進め|済ませ|して(も)?いい|できる|られる|まで)/, ng:/部下|後輩|新人|メンバー|研修|朝礼/, head:"所属の保険会社が認めた方法と手順があるときだけ、その手順どおりに進めます。", body:"画面越しでの申込みは、保険会社ごとに、使える仕組み（電子の申込み・本人の確かめ・書面の渡し方）と手順が決まっています。重要事項の説明・意向の確かめ・告知も、その手順に沿って漏れなく行う必要があります。自分で工夫した方法で進めず、決まった方法が無ければ、対面や郵送の手続きに切り替えます。", acts:["所属の保険会社に、画面越しで使える申込みの方法があるかを先に確かめる", "重要事項の説明と意向の確かめを、手順どおりに画面で行う", "告知は、お客様ご本人に入力・記入していただく", "決まった方法が無ければ、対面か郵送に切り替える"], actHead:"進め方", note:"画面越しの申込み・本人の確かめ・書面の交付の方法は、所属の保険会社の手順と御社のコンプライアンス担当で確かめる。", go:"iko", say:"お申込みの手続きは、保険会社が決めた方法で進めます。画面越しでできる方法がありますので、手順に沿ってご説明します。ご不安な点は、その都度お尋ねください。", more:"よくある失敗は、申込書の写真をメッセージで送ってもらう、画面越しに口頭で告知を聞いてこちらが書く、といった自己流の進め方です。どちらも保険会社の手順から外れるおそれがあります。お客様の手元の機器や通信の具合で手続きが止まることもあるので、途中で切れたときの扱いも先に確かめておきます。", why:"申込みは、お客様が説明を受けて自分の意思で決めたことを残す手続きだからです。決まった方法で行えば、あとでお客様にも保険会社にも、正しく進めたことを示せます。" },
      { key:'faq_xeba_orikaeshi', faq:1, grp:'eba', q:"お客様からの電話に出られなかった。折り返しはどうする？", re:/(お客様|お客さん|契約者)[^。]{0,6}(から)?の?(電話|着信)[^。]{0,10}(出られな|出れな|気づかな|取れな|折り返)|(電話|着信)に出られな[^。]{0,12}(お客様|お客さん|折り返)|折り返し(の電話|方|の仕方|はいつ)/, ng:/部下|後輩|新人|メンバー|上司|保険会社から|事務から/, head:"できるだけ早く折り返し、出られなかったお詫びのあとに、まず用件を伺います。", body:"お客様からの電話は、事故や入院など急ぎの用件のこともあります。気づいたら、できるだけ早く折り返し、出られなかったお詫びを一言伝えて、すぐに用件を伺います。すぐに折り返せないときは、何時ごろにかけ直すかを文字で知らせます。事故の連絡だったときは、保険会社の事故の受付も一緒に案内します。", acts:["留守番電話や文字の連絡が残っていないか、先に確かめる", "「お電話に出られず、失礼しました」と言い、すぐに用件を伺う", "すぐにかけ直せないときは、かけ直す時刻を文字で知らせる", "事故や急ぎのときは、保険会社の受付の番号も伝える"], actHead:"折り返しの順番", note:"事故や急ぎの連絡の受け方と、保険会社の受付への案内の手順は、所属の保険会社と御社の手順で確かめる。", say:"先ほどはお電話に出られず、失礼しました。どうされましたか。", more:"折り返しの電話で、こちらの話（提案や面談の日程）を先にしないことが大切です。お客様の用件を聞き終えてからにします。急ぎの用件が多い時期（台風のあと・年末など）は、出られないときの連絡先を、名刺や案内に書いておくとお客様が困りません。", why:"電話をかけてきたお客様には、そのときに伝えたいことがあるからです。早く折り返して用件を先に伺えば、急ぎの用件も遅れずに済み、頼れる担当だと感じていただけます。" },
      { key:'faq_xeba_denwa_wake', faq:1, grp:'eba', q:"電話で済ませる話と、会って話す話の分け方は？", re:/(電話|メール|文字)で(済ませ|済む|伝えていい|伝えてよい|いい話|よい話|十分)[^。]{0,16}(会って|対面|面談)|(会って|対面で)(話す|伝える)[^。]{0,16}(電話|メール)[^。]{0,8}(違い|分け|線引き|どこまで)|どこまで電話で済ませ/, ng:/部下|後輩|新人|メンバー|録音|上司/, head:"日程や手続きの案内は電話や文字で、保障の中身と意向の確かめは会って話します。", body:"日程の調整・届いた書類の案内・手続きの進み具合のように、短く伝えて終わる話は電話や文字で済ませます。保障の中身の説明・お客様の意向の確かめ・申込みは、資料を一緒に見ながら、会って話すか、保険会社が認める方法で行います。健康やお金のように込み入った話や、お客様が不安を抱えている話も、顔を合わせるほうが伝わります。", acts:["電話や文字で済ませる用件は、一つに絞って短くする", "保障の中身や意向の話になりそうなら、会う日を決めて改める", "電話で話した内容は、日時と一緒に記録に残す"], actHead:"分け方", note:"電話での説明や勧誘の仕方と記録の手順は、所属の保険会社と御社の手順で確かめる。", say:"そのお話は、資料を見ながらご説明したほうが分かりやすいので、一度お時間をいただけますか。今日のお電話では、日程だけ決めさせてください。", more:"電話で保障の説明を始めると、資料が手元に無いお客様は内容を思い描けず、誤解が残りやすくなります。逆に、会うたびに手続きの案内だけをすると、お客様の時間を取りすぎます。用件ごとに、伝える方法を最初に決めてから連絡すると、どちらの失敗も防げます。", why:"伝える方法によって、お客様が分かる量が違うからです。中身の話を会って伝えれば誤解が減り、短い用件を電話で済ませれば、お客様の時間を大切にできます。" },
      { key:'faq_xeba_mail_henshin', faq:1, grp:'eba', q:"お客様からのメールには、いつまでに返事をすればいい？", re:/(お客様|お客さん|契約者)[^。]{0,4}(から|の)の?(メール|メッセージ|問い合わせ)[^。]{0,12}(返事|返信|返す|答え)|(お客様|お客さん)から(メール|メッセージ)で[^。]{0,6}(質問|問い合わせ|相談)[^。]{0,14}(返事|返信|返す|いつまで)|(メール|メッセージ)[^。]{0,4}(への)?(返信|返事)の(速さ|早さ|タイミング)/, ng:/部下|後輩|新人|メンバー|上司|保険会社から|事務から|来な|こな|ない/, head:"受け取ったことはその日のうちに返し、答えに時間がかかるなら、いつまでに返すかを伝えます。", body:"お客様は、メールが届いたか、読まれたかが分からないと不安になります。すぐに答えられない質問でも、受け取ったことと、いつまでに答えるかを先に返します。調べた答えは約束した日までに送り、保障や手続きの込み入った内容は、文だけで済ませず電話や面談で補います。", acts:["その日のうちに「受け取りました。◯日までにお返事します」と返す", "答えは約束した日までに、短く要点から書く", "込み入った内容は、文のあとに電話で補う", "健康や口座の情報など、送ってはいけない中身を文に書かない"], actHead:"返し方", note:"メールでやりとりしてよい内容と、個人情報の扱いは、御社の手順で確かめる。", say:"ご連絡ありがとうございます。いただいたご質問は、保険会社にも確かめたうえで、明日の夕方までにお返事します。", more:"保障が出るかどうかなどの問いに、メールで言い切って答えると、あとで違ったときに文が残ります。支払いの判断は保険会社がするので、「保険会社に確かめます」と返し、確かめた答えを伝えます。返事を約束した日に間に合わないときは、その前に遅れることを知らせます。", why:"早い一言があれば、お客様は待つ時間を安心して過ごせるからです。約束した日を守ることが、メールでのやりとりでも信頼になります。" },
      { key:'faq_xeba_mimi', faq:1, grp:'eba', q:"耳が聞こえにくいお客様への説明は？", re:/(耳(が|の)(遠|聞こえにく|悪)|聞こえにくい|聞こえづらい|難聴|補聴器)[^。]{0,16}(お客様|お客さん|方)|(お客様|お客さん)[^。]{0,8}(耳(が|の)(遠|聞こえにく|悪)|聞こえにくい|聞こえづらい|補聴器)/, ng:/部下|後輩|新人|メンバー|自分の耳|私の耳/, head:"静かな場所で、正面から、ゆっくり話し、大切なことは書いて見せます。", body:"聞こえにくい方は、聞き返すのを遠慮して、分かったふりをしてしまうことがあります。周りの音が少ない場所で、口元が見えるよう正面に座り、短い文でゆっくり話します。保険料・保障の中身・手続きの期限のような大切なことは、紙に書いて見せ、分かっていただけたかを一言で言い直していただきます。", acts:["静かな場所を選び、お客様の正面に座る", "一文を短くし、大きな声より、ゆっくりはっきり話す", "大切なことは紙に書いて、指さしながら伝える", "ご家族の同席を望まれるかを伺う"], actHead:"現場で使うなら", note:"理解の確かめと、ご家族の同席・記録の手順は、所属の保険会社と御社の手引きで確かめる。", go:"iko", say:"聞き取りにくいところがあれば、何度でもおっしゃってください。大事なところは、こちらに書いてお見せしますね。", more:"声を大きくすると、かえって音が割れて聞き取りにくくなる方もいます。どちらの耳が聞こえやすいか、どの話し方がよいかを、最初にご本人に伺うのが確かです。電話よりも、会って書いて見せるほうが伝わる方も多いので、連絡の方法も一緒に決めておきます。", why:"保険の説明は、聞き違いがそのまま思い違いにつながるからです。書いて見せ、言い直していただくことで、お客様が本当に分かったうえで決められます。" },
      { key:'faq_xeba_kourei_jikan', faq:1, grp:'eba', q:"ご高齢のお客様と会う時間帯と長さは、どう決める？", re:/(高齢|年配|お年寄り)[^。]{0,8}(お客様|お客さん|方)[^。]{0,4}(と|に)会う[^。]{0,6}(時間帯|時間の長さ|長さ|時間|何時)/, ng:/部下|後輩|新人|メンバー|自分の親|私の親|うちの親/, head:"ご本人の体調のよい時間帯を伺い、長さは短めにして、日を分けることも前提にします。", body:"ご高齢のお客様は、疲れが出ると、聞いた内容を落ち着いて考えにくくなります。会う時間帯は、こちらの都合ではなく、ご本人やご家族に体調のよい時間を伺って決めます。一度の面談は短めにし、説明と決める話を同じ日に詰め込まず、日を分けることを最初から前提にします。", acts:["ご本人やご家族に、体調のよい時間帯を伺って決める", "一度の面談は短めにし、終わる時刻を最初に伝える", "説明の日と、決めていただく日を分ける", "ご家族の同席を望まれるかを、日程を決めるときに伺う"], actHead:"現場で使うなら", note:"ご高齢のお客様の面談の回数・同席・記録の手順と対象の考え方は、所属の保険会社と御社の手引きで確かめる。", go:"iko", say:"ご体調のよい時間に合わせて伺います。午前と午後では、どちらが楽ですか。お話は短めにして、続きは別の日にもう一度伺うつもりでいます。", more:"食事のあとや通院の日は、疲れていたり眠くなったりすることがあります。ご家族から、いつごろが落ち着いているかを伺えると確かです。面談の途中で疲れた様子が見えたら、予定より早くても終えます。決める話を持ち越すことは、お客様にとっても安心になります。", why:"落ち着いて考えられる状態で話を聞いていただくことが、ご本人の意思で決めていただく前提になるからです。時間と回数をお客様に合わせることで、無理のない判断を守れます。" },
      { key:'faq_xeba_kourei_shiryou', faq:1, grp:'eba', q:"ご高齢のお客様に見せる資料は、どう用意する？", re:/(高齢|年配|お年寄り)[^。]{0,8}(お客様|お客さん|方)[^。]{0,8}(資料|パンフレット|書面|設計書)[^。]{0,12}(用意|見せ|大きく|出し方|作|分かりやす)/, ng:/部下|後輩|新人|メンバー|自分の親|私の親|うちの親/, head:"保険会社が用意した資料を使い、見せる枚数を絞って、大切な所を指さしながら説明します。", body:"資料を自分で作り直したり書き足したりすると、募集の資料として認められない形になるおそれがあります。使うのは保険会社が用意したパンフレット・設計書・重要事項の書面です。そのうえで、一度に見せる枚数を絞り、大切な所を指さしながら、ゆっくり説明します。文字を大きくした版があるかや、拡大して見せてよいかは、保険会社と社内で確かめます。", acts:["保険会社が用意した資料だけを使い、自分で書き足さない", "一度に机に出す資料を一枚か二枚にする", "大切な所は指さし、読み上げてから、言い直していただく", "大きな文字の版があるかを、保険会社に確かめる"], actHead:"現場で使うなら", note:"資料の拡大・作り直しの可否と、ご高齢のお客様への説明の手順は、所属の保険会社と御社のコンプライアンス担当で確かめる。", go:"iko", say:"今日は、この二枚だけでご説明します。大事な所はここです。分かりにくい所があれば、何度でもお尋ねください。", more:"よくある失敗は、分かりやすくしようとして、手書きのまとめや自作の表を渡すことです。善意でも、募集の資料の審査を通っていないものになります。手書きで説明したいときは、その場で書いて見せるだけにして、渡す紙は保険会社の資料にします。照明や老眼鏡の有無にも気を配ります。", why:"お客様が後で見返す資料は、保険会社が内容を確かめたものである必要があるからです。そのうえで見せ方を工夫すれば、正しさと分かりやすさの両方を守れます。" },
      { key:'faq_xeba_madahayai', faq:1, grp:'eba', q:"若いお客様に、保険はまだ早いと言われた", re:/(若い|20代|二十代|社会人)[^。]{0,16}(まだ早い|まだ先でいい|まだいい|早すぎ)|(若い|20代|二十代)から[^。]{0,8}(保険)?[^。]{0,4}(は)?早い|(保険|保険なんて)[^。]{0,4}(は)?まだ(早い|先でいい)/, ng:/部下|後輩|新人|メンバー|(自分|私|僕)(が|は)若/, head:"そう思われるのは自然だと受け止め、今の暮らしで困ることがあるかだけを一緒に確かめます。", body:"若いうちは、病気やけがを自分のこととして考えにくく、まだ早いと感じるのは自然です。保険の必要を説くより先に、病気で働けない期間があったら暮らしはどうなるか、勤め先や公的な制度でどこまで支えられるかを一緒に確かめます。足りないところが無ければ、今は入らないという答えも尊重します。", acts:["「そう思われるのは自然です」と、まず受け止める", "働けない期間の暮らしを、勤め先と公的な制度で支えられるか一緒に確かめる", "今は入らないという答えも、お客様の判断として受け止める", "暮らしが変わったとき（結婚・転職・住まい）に、また相談できると伝える"], actHead:"現場で使うなら", note:"勤め先の制度は本人の勤め先の規程、公的な制度は加入している健康保険や年金の窓口で確かめる。保障の中身は保険会社の資料で確かめる。", say:"そう思われるのは自然だと思います。保険の話の前に、もし病気で少し働けない時期があったら、勤め先や国の制度でどこまで支えられるか、一緒に見てみませんか。", more:"若い方に将来の病気の話を重ねると、不安で押す形になります。話は今の暮らしの範囲にとどめます。健康なうちのほうが入りやすい、という言い方は、急がせる話に聞こえやすいので避け、事実として聞かれたときだけ、告知の仕組みとして説明します。", why:"決めるのはお客様で、必要を感じていない方に勧めても続かないからです。今の暮らしで困ることを一緒に確かめれば、必要かどうかをお客様が自分で判断できます。" },
      { key:'faq_xeba_oya_hoken', faq:1, grp:'eba', q:"親が払っていた保険を、自分で払うことになった", re:/(親|親御さん|両親|お父様|お母様)[^。]{0,4}(が|に)?[^。]{0,8}(掛けて|払って|入って)(い|もらって|くれて)[^。]{0,10}(保険)[^。]{0,16}(引き継|自分で払|本人が払|本人に)/, ng:/部下|後輩|新人|メンバー|名義|契約者の変更|契約者を変|大丈夫|要らな|いらな/, head:"中身をご本人に知っていただき、手続きと受取人を、ご本人の今の暮らしに合わせて確かめます。", body:"親御さんが掛けていた保険は、お子さん本人が中身を知らないことが多いです。まず証券で、何の保障が、いつまで、いくらの保険料で続くかを一緒に確かめます。払う人や契約者を変える手続きは保険会社の決まりで行い、受取人や保障の大きさが今の暮らしに合っているかも、ご本人と確かめます。", acts:["証券で、保障の中身・期間・保険料をご本人と一緒に確かめる", "払う人や契約者を変える手続きの書類を、保険会社に確かめる", "受取人と保障の大きさが、今の暮らしに合っているかを伺う", "税の扱いの問いは、税理士・税務署で確かめるよう案内する"], actHead:"現場で使うなら", note:"契約者の変更などの手続きは所属の保険会社で確かめる。払う人が変わったときの税の扱いは、税理士・税務署で確かめる。", say:"親御さんが大切に続けてこられた保険ですね。まず、どんな保障が、いつまで続くのかを一緒に確かめましょう。そのうえで、今の暮らしに合っているかを考えていきます。", more:"親御さんが契約者のままで、保険料だけ本人が払う形にしていることもあります。誰が契約者で、誰が払っているかで、将来の受け取りのときの税の扱いが変わることがあるので、言い切らずに確かめる先を案内します。親御さんにも同じ説明を共有したいかを、ご本人に伺います。", why:"続けるかどうかを決めるのは、これから払うご本人だからです。中身を知っていただいてから考えれば、親御さんの思いも、ご本人の暮らしも、どちらも大切にできます。" },
      { key:'faq_xeba_sns', faq:1, grp:'eba', q:"お客様がネットの動画で見た話を信じている", re:/(ネットの動画|ネットの記事|ネット記事|ネットで見た|動画で見た|動画で観た)[^。]{0,20}(信じ|うのみ|鵜呑み|言ってく|返し方)|(お客様|お客さん)が(ネット|動画)[^。]{0,12}(信じ|うのみ|鵜呑み)/, ng:/部下|後輩|新人|メンバー|発信|投稿|載せ|フォロワー|安い|安かった/, head:"否定せずに、お客様が何を知りたくてその情報に行き着いたのかを伺います。", body:"SNSの話には、正しいものも、一部だけを切り取ったものもあります。いきなり否定すると、お客様は自分の調べたことを否定されたと感じます。まず、どの話が気になったのかと、その話を見て何を確かめたいと思ったのかを伺います。そのうえで、お客様のご契約や暮らしに当てはめて、書面で一緒に確かめます。", acts:["「どの話が気になりましたか」と、まず伺う", "その話を、お客様のご契約の書面や公的な資料と照らす", "当てはまる所と当てはまらない所を、分けて伝える"], actHead:"現場で使うなら", note:"保障の中身は保険会社の約款・パンフレットで、公的な制度は所管の窓口や公的機関の資料で確かめる。", say:"その話、気になりますよね。どのあたりが気になりましたか。お客様のご契約に当てはまるかどうか、書面で一緒に確かめてみましょう。", more:"SNSで流れる話は、誰にでも当てはまる言い方になっていることが多く、年齢・家族・勤め先の制度で答えが変わる部分が抜けがちです。その抜けている部分を一緒に埋めると、お客様は自分の判断の材料が増えたと感じます。投稿した人や他の商品を悪く言わないことも大切です。", why:"お客様が自分で調べるのは、損をしたくない、よく分かって決めたい、という気持ちからだからです。その気持ちを受け止めて書面で確かめれば、お客様の判断を助ける役に立てます。" },
      { key:'faq_xeba_shouken_nashi', faq:1, grp:'eba', q:"初回の面談で、お客様が保険証券を持ってこなかった", re:/(証券|保険証券)[^。]{0,4}(を)?[^。]{0,4}(持ってこな|持って来な|忘れ|持参されな|無いまま|ないまま)/, ng:/部下|後輩|新人|メンバー|なくし|無くし|紛失|見当たら|捨て/, head:"その日は暮らしと意向を伺う日にし、今の保険の中身は次の機会に証券で確かめます。", body:"証券が無いと、今の保険の中身を思い出で話すことになり、思い違いが残ります。その日は、ご家族や暮らし、気になっていることを伺う時間に切り替えます。今の保険の中身は、次の面談までに証券や保険会社からのお知らせを見つけていただき、一緒に確かめます。記憶だけで比べたり、見直しを勧めたりはしません。", acts:["その日の話を、暮らしと意向を伺う中身に切り替える", "次の面談までに、証券か保険会社からの契約内容のお知らせを探していただく", "記憶だけで今の保険を評価しない"], actHead:"現場で使うなら", note:"証券をなくしたときの再発行や、契約内容のお知らせの取り寄せ方は、加入している保険会社の窓口で確かめる。", go:"iko", say:"今日はご家族のことや気になっていることを中心に伺います。今の保険の中身は、次回、証券を見ながら一緒に確かめましょう。保険会社からの契約内容のお知らせでも大丈夫です。", more:"お客様が「確か入院でいくら出るはず」と覚えていることと、証券の中身が違うことはよくあります。記憶をもとに話を進めると、あとで食い違いが出て信頼を損ないます。証券が見つからないときは、加入している保険会社の窓口で、契約の内容を確かめる方法をご本人に案内します。", why:"今の保険の中身を正しく分かっていないと、見直しの話が思い違いの上に立つからです。その日を意向を伺う日に変えれば、時間も無駄にならず、次の面談で確かな話ができます。" },
      { key:'faq_xeba_toriaezu', faq:1, grp:'eba', q:"「とりあえず資料だけください」と言われた", re:/(とりあえず|ひとまず|話はいいから)[^。]{0,8}(資料|パンフレット|パンフ)[^。]{0,6}(だけ)|(資料|パンフレット)だけ[^。]{0,8}(欲しい|ください|置いて|送って|もらえ)/, ng:/部下|後輩|新人|メンバー|作っ|作成/, head:"資料はお渡ししたうえで、どこを見ればよいかと、何が気になっているかを一つだけ伺います。", body:"資料だけ欲しいという言葉には、今は話を聞く時間が無い、売り込まれたくない、自分で見て決めたい、などの気持ちがあります。断られたと受け取らず、資料はお渡しします。そのうえで、どこから見ればよいかを一言添え、何が気になって資料を求めたのかを一つだけ伺います。次の連絡の取り方は、お客様に選んでいただきます。", acts:["資料はその場で渡し、見るとよい所に印を付けて伝える", "「何が気になって資料をご覧になりたいですか」と一つだけ伺う", "次の連絡の方法と時期を、お客様に選んでいただく"], actHead:"現場で使うなら", note:"お渡しする資料は保険会社が用意したものを使い、渡した記録の残し方は御社の手引きで確かめる。", say:"はい、お渡しします。まずこの頁だけご覧いただくと全体がつかめます。差し支えなければ、何が気になってご覧になりたいと思われたか、一つだけ伺ってもいいですか。", more:"資料を渡して終わりにすると、多くの場合、そのまま読まれずに置かれます。気になっていることが一つ分かれば、次に連絡するときに、その点だけを短く伝えられます。何度も連絡して追いかけると売り込みになるので、連絡の方法と時期はお客様に決めていただきます。", why:"お客様が自分のペースで考えたいという気持ちを尊重しつつ、何を確かめたいのかが分かれば、次の一回を役に立つ連絡にできるからです。" },
      { key:'faq_xeba_memo', faq:1, grp:'eba', q:"面談中にメモを取ってもいい？", re:/(面談|商談|お客様の前|お客様の話)[^。]{0,10}(メモを取|メモし|メモをと|書き留め)|メモの取り方|メモを取ると話が止ま/, ng:/部下|後輩|新人|メンバー|録音|研修|会議|セミナー/, head:"最初に一言断ってから取り、書いた内容は最後に読み上げて、聞き違いが無いかを確かめます。", body:"メモを取ること自体は失礼ではなく、聞いたことを正しく残すために大切です。ただ、黙って書き続けると、お客様は何を書かれているのか気になります。最初に「大事なことを聞き違えないよう、メモを取らせてください」と断ります。面談の終わりに要点を読み上げ、聞き違いが無いかを確かめると、そのまま意向把握の記録にも生かせます。", acts:["最初に「メモを取らせてください」と一言断る", "書くのは要点だけにして、お客様の顔を見て聞く時間を多くする", "最後に要点を読み上げて、聞き違いが無いか確かめる", "メモの扱い（持ち帰り・保管）を社内の決まりに合わせる"], actHead:"現場で使うなら", note:"お客様の情報を書いたメモの持ち出し・保管・破棄の決まりは、御社の個人情報の取り扱いの規程で確かめる。", go:"iko", say:"大事なお話を聞き違えないように、メモを取らせていただいてもいいですか。最後に一度、読み上げて確かめます。", more:"メモに書いたお客様の言葉は、意向把握の記録の「最初のご意向」を書くときの材料になります。お客様の言い方のまま残すと、あとで自分の解釈が混ざらずに済みます。メモを持ち歩くときは、なくさない工夫と、社内での保管の決まりを守ることが大切です。書くことに気を取られたら、一度手を止めて顔を上げます。", why:"聞いたことを正しく残し、最後にお客様と一緒に確かめることが、意向に沿った提案の土台になるからです。" },
      { key:'faq_xeba_dassen', faq:1, grp:'eba', q:"面談でお客様の話が脱線して戻らない", re:/(話|世間話|雑談)[^。]{0,8}(脱線|それて|それていく|長くて|終わってしま)|(本題)[^。]{0,4}(に)?(入れな|戻れな|戻せな)|話の長い(お客様|お客さま|方)|(お客様|お客さま)の話が[^。]{0,4}(長|終わらな)/, ng:/部下|後輩|新人|メンバー|会議|朝礼|長く脱線/, head:"話を遮らずに受け止め、区切りで「今日はこの話を伺いに来ました」と時間と目的を言い直します。", body:"脱線した話には、お客様の暮らしや気持ちが表れていることが多く、全てが無駄ではありません。ただ、時間が尽きると大事な話ができません。最初に今日の目的と終わる時刻を伝えておき、話の区切りで「そのお話、大事ですね。今日は残りの時間で、ここを伺わせてください」と戻します。脱線の中で出たご家族や暮らしの話は、意向を伺う材料として拾います。", acts:["面談の始めに、今日の目的と終わる時刻を伝える", "区切りで「残りの時間で、ここを伺わせてください」と戻す", "脱線した話に出たご家族や暮らしの話を、意向の材料として拾う"], actHead:"現場で使うなら", note:"面談の時間の目安と記録の残し方は、御社の手引きと上長に確かめる。", say:"そのお話、とても大事ですね。残りの時間で、今日伺いたかったこの点だけ、お聞かせいただいてもいいですか。", more:"戻すときに大切なのは、お客様の話をつまらないものとして扱わないことです。「その話につながるのですが」と、出てきた話題から本題へ橋をかけると、自然に戻れます。毎回時間が足りない方には、面談を短く分けて回数を増やすほうが合うこともあります。聞いたことを「つまり、ここが気になっているのですね」と短くまとめて返すのも、本題へつなぐ方法です。", why:"お客様は、自分の話を聞いてもらえたと感じると、本題にも耳を傾けやすくなるからです。目的と時間を共有しておけば、戻すことも失礼になりません。" },
      { key:'faq_xeba_kotaerarenai', faq:1, grp:'eba', q:"面談中、お客様の質問にその場で答えられない", re:/(質問|聞かれ)[^。]{0,10}(その場で)?[^。]{0,4}(答えられな|答えに詰ま|詰ま|分からな|わからな)|(分からない|知らない)(こと|質問)を[^。]{0,4}(聞かれ|され)|答えられない質問/, ng:/部下|後輩|新人|メンバー|上司|社長|面接|試験|答えられない質問をされた/, head:"推測で答えず「確かめてからお答えします」と伝え、いつまでに、どの方法で返すかを約束します。", body:"その場で答えようとして推測で話すと、間違ったことをお客様に伝えるおそれがあります。分からないことは「正確にお答えしたいので、確かめてからご連絡します」と伝えます。そのうえで、いつまでに、電話かメールかなど、どの方法で返すかをその場で決めます。持ち帰った問いは、保険会社や社内の担当に確かめ、約束した日までに必ず返します。", acts:["推測で答えず「確かめてからお答えします」と伝える", "返す期日と方法を、その場でお客様と決める", "質問をお客様の言葉のまま書き留める", "保険会社や社内の担当に確かめ、約束の日までに返す"], actHead:"現場で使うなら", note:"商品の中身は所属の保険会社、手続きや社内の決まりは上長・内務の担当で確かめる。税は税理士、法律の判断は弁護士の領分。", say:"大事なご質問なので、正確にお答えしたいと思います。確かめて、お約束の日までにご連絡します。お電話とメール、どちらがよろしいですか。", more:"答えに詰まったことは、信頼を損なうことではありません。損なうのは、間違ったことを言い切ることと、約束した連絡をしないことです。持ち帰った問いに丁寧に返すと、かえって信頼が深まります。よく聞かれる問いは、次の面談の前に調べておくと準備になります。推測を事実のように言ってしまったと気づいたら、すぐに訂正します。", why:"保険の説明は、間違えるとお客様の判断を誤らせるからです。確かめてから答えることは、お客様の判断を守る姿勢そのものです。" },
      { key:'faq_xeba_zatsudan_hondai', faq:1, grp:'eba', q:"雑談から本題に入るタイミングが分からない", re:/(雑談|世間話|アイスブレイク)[^。]{0,8}(から|のあと)[^。]{0,10}(本題|保険の話|切り替え|移る|入る|入り方)|(雑談|世間話)[^。]{0,12}(切り出せな|移れな)/, ng:/部下|後輩|新人|メンバー|会議|朝礼/, head:"最初に今日の目的を伝えておけば、区切りで「では、今日の本題を」と自然に移れます。", body:"雑談から本題に移るのが難しいのは、本題に入ると売り込みが始まると、お客様もこちらも感じているからです。面談の始めに「今日は、ご家族の暮らしのことを伺って、今の備えを一緒に確かめる時間にしたいと思います」と目的を伝えておくと、区切りで自然に戻れます。雑談で出た話題から本題へ橋をかけるのも一つの方法です。", acts:["面談の始めに、今日の目的と流れを一言で伝える", "雑談の区切りで「では、今日の本題を伺います」と切り替える", "雑談に出た話題（ご家族・仕事・住まい）を本題への橋にする"], actHead:"現場で使うなら", note:"面談の流れと最初に伝えることの決まりは、御社の手引きと上長で確かめる。", say:"では、今日の本題に入らせてください。先ほどのお子さんのお話にもつながるのですが、ご家族の暮らしのことを少し伺ってもいいですか。", more:"雑談を長くすれば打ち解けるとは限りません。お客様の時間を大切にしていることが伝わるほうが、信頼につながります。雑談は短めにして、本題の中で、お客様の話をよく聞く時間をとるほうが、関係は深まります。雑談は始めに、本題は真ん中に、次の約束は最後に、と順番を決めておくと迷いません。", why:"面談の目的を最初に共有しておくと、お客様は何の時間なのかが分かって安心し、本題への切り替えも唐突に感じないからです。" },
      { key:'faq_xeba_kuwashii', faq:1, grp:'eba', q:"お客様のほうが保険に詳しいとき、どう話す？", re:/(お客様|お客さん)[^。]{0,6}(の)?(ほう|方)が[^。]{0,8}(詳し|知って)|(自分|私)より[^。]{0,6}詳し[^。]{0,8}(お客様|お客さん|相手)|(詳しい|専門家並み)[^。]{0,6}(お客様|お客さん)|(お客様|お客さん)が[^。]{0,8}(詳しくて|詳しすぎ)|知識のある(お客様|お客さん)|試されている/, ng:/部下|後輩|新人|メンバー|上司|社長|先輩/, head:"知識で張り合わず、お客様が何を確かめたいのかを伺い、手続きと書面の正しさで役に立ちます。", body:"詳しいお客様は、一般的な説明より、自分の考えが正しいかを確かめたい、比べる材料が欲しい、といった目的を持っていることが多いです。知識で張り合おうとすると、かえって話がかみ合いません。お客様の考えをまず伺い、確かめたい点を一緒に整理します。分からないことは持ち帰り、約款や保険会社の資料で正確に返すことが、いちばんの役立ち方です。", acts:["「どのあたりを確かめたいですか」と、お客様の目的を伺う", "お客様の考えを聞いたうえで、書面で一緒に確かめる", "分からないことは推測せず、確かめてから返す"], actHead:"現場で使うなら", note:"商品の中身は所属の保険会社の約款・資料で、税は税理士・税務署で確かめる。", say:"よくご存じなので、お考えを先に伺えますか。そのうえで、確かめたい点を書面で一緒に見ていきましょう。", more:"詳しいお客様ほど、説明の正確さと、手続きの段取りのよさを見ています。一般的な話を長くするより、お客様のご契約や暮らしに当てはめたときに何が変わるかを、短く正確に伝えるほうが喜ばれます。お客様から教わることがあれば、素直にお礼を言います。お客様の理解に誤りがあるときは、書面を示して静かに伝えます。", why:"お客様の知識を尊重して目的に合わせると、話がかみ合い、こちらが本当に役立てる所がはっきりするからです。" },
      { key:'faq_xeba_kawari_kimeru', faq:1, grp:'eba', q:"奥様に「主人に任せています」と言われた", re:/(主人|夫|旦那|妻|家内|嫁|奥さん)に[^。]{0,4}(任せて|任せっきり|まかせて)/, ng:/部下|後輩|新人|メンバー|社長|会社|経理/, head:"任せている気持ちを受け止め、ご夫婦それぞれの考えを伺える場を、お二人に選んでいただきます。", body:"任せているという言葉の裏には、よく分からない、相手を信頼している、自分が口を出すと揉める、などの気持ちがあります。保険はご家族みんなの暮らしに関わるので、任されている方だけで決めると、あとで食い違いが出ることがあります。無理に巻き込まず、ご夫婦が一緒に話を聞ける日を伺い、それぞれが大事にしたいことを一つずつ聞かせていただきます。", acts:["「お任せできる方がいるのは心強いですね」と受け止める", "ご夫婦お二人で話を聞ける日があるかを伺う", "それぞれが大事にしたいことを一つずつ伺う", "決めるのはご夫婦だと伝え、どちらか一方を説得しない"], actHead:"現場で使うなら", note:"ご家族の同席や意向の残し方は、御社の手引きと所属の保険会社の決まりで確かめる。", go:"iko", say:"お任せできる方がいるのは心強いですね。保険はご家族みんなに関わるので、もしよろしければ、次はお二人そろってお話を伺える日はありますか。", more:"任されている側が、本当は相手の考えも聞きたいと思っていることはよくあります。お二人の考えを並べてみると、大事にしたいことが同じだと分かって話が進むこともあります。どちらかの考えを正しいとせず、違いがあれば、そのまま記録に残します。", why:"保険はご家族の暮らしを支えるもので、ご家族それぞれの思いが反映されてこそ、決めたあとも安心して続けられるからです。" },
      { key:'faq_xeba_nikaime', faq:1, grp:'eba', q:"2回目の面談では何をすればいい？", re:/(2回目|二回目|2度目|二度目|次回)の(面談|商談|訪問)[^。]{0,10}(何を|進め方|準備|話すこと|すれば)|(2回目|二回目|2度目|二度目)に(会う|お会いする|伺う)[^。]{0,10}(準備|何を|話す)/, ng:/部下|後輩|新人|メンバー|研修/, head:"前回伺ったことを読み上げて合っているか確かめ、前回持ち帰った問いに答えてから先へ進みます。", body:"2回目の面談は、前回から時間がたって、お客様の考えが変わっていることもあります。まず前回伺ったご意向と暮らしの話を短く読み上げ、合っているか、変わったことは無いかを確かめます。次に、前回持ち帰った質問に答えます。そのうえで、今日の目的と流れを伝えてから先へ進みます。提案は、ご意向を確かめ直してからにします。", acts:["前回伺ったご意向と暮らしの話を読み上げ、変わったことが無いか伺う", "前回持ち帰った質問に、最初に答える", "今日の目的と流れを伝えてから進める", "ご意向が変わっていたら、記録を直してから提案に入る"], actHead:"現場で使うなら", note:"面談ごとの意向の確かめ方と記録の残し方は、所属の保険会社と御社の手引きで確かめる。", go:"iko", say:"前回、こんなお話を伺いました。今も同じお考えですか。変わったことがあれば教えてください。それから、前回いただいたご質問にお答えします。", more:"前回の話を読み上げると、お客様はきちんと聞いてもらえていたと感じます。考えが変わっていたら、それを責めずに新しい考えとして受け止めます。前回の記録を見返す時間を面談の前にとっておくと、読み上げが短く正確になります。", why:"提案はお客様のご意向に沿っている必要があり、ご意向は時間とともに変わることがあるからです。確かめ直してから進めると、提案のずれを防げます。" },
      { key:'faq_xeba_plan_kazu', faq:1, grp:'eba', q:"提案するプランは、いくつ用意すればいい？", re:/(プラン|提案|案)[^。]{0,4}(の数|は(いくつ|何案|何個)|をいくつ)|(いくつ|何案|何個)[^。]{0,6}(プラン|提案|案)|何案(ぐらい|くらい)?[^。]{0,4}(出|用意|見せ)|(一つに絞る|1つに絞る)[^。]{0,10}(提案|プラン)|(提案|プラン)[^。]{0,8}(一つに絞る|1つに絞る)|(プラン|提案)は[^。]{0,4}(いくつ|何案|何個)/, ng:/部下|後輩|新人|メンバー|研修|会議/, head:"数を決めて揃えるより、ご意向に沿って比べた理由を説明できる形で、少ない案を並べます。", body:"案を多く並べると、お客様はかえって選べなくなります。一つだけだと、ほかと比べたのかが伝わりにくくなります。大切なのは数より、ご意向に沿って何を比べ、なぜこの案をお勧めするのかを説明できることです。比べた商品と理由は比較推奨の記録に残し、決めるのはお客様だと伝えます。案の出し方は、御社の推奨の方針に合わせます。", acts:["ご意向を確かめ直してから、比べる商品を選ぶ", "案は少なくし、それぞれ何が違うかを一言で言えるようにする", "お勧めする理由を、ご意向の言葉で説明する", "比べた商品と理由を比較推奨の記録に残す"], actHead:"現場で使うなら", note:"比較推奨の方法と、案の出し方の決まりは、御社の推奨の方針と所属の保険会社の指示で確かめる。", go:"hikaku", say:"伺ったご意向に合わせて、比べたうえで二つに絞りました。違いはここです。私がこちらをお勧めする理由はこうですが、決めていただくのはお客様です。", more:"案の違いが保険料だけになっていると、お客様は安いほうを選ぶしかなくなります。保障の範囲・期間・続け方など、ご意向に関わる違いを示します。どの案にも合わない所があれば、隠さずに伝えます。案を選んでいただけなかったときも、そのまま受け止めます。特定の保険会社の商品に絞って勧めるときは、その理由もお伝えします。", why:"比べて勧める理由が説明できれば、お客様は納得して選べるからです。数を揃えることより、ご意向とのつながりを示すことが、比較推奨の目的に合っています。" },
      { key:'faq_xeba_zenkai_wasure', faq:1, grp:'eba', q:"お客様が前回の面談の内容を覚えていない", re:/(前回|前の面談|この前)[^。]{0,10}(内容|話|説明|こと)?[^。]{0,8}(覚えていな|覚えてな|忘れて)/, ng:/部下|後輩|新人|メンバー|自分が|私が|僕が|認知/, head:"覚えていないことを責めず、前回の要点を短く読み上げてから、今日の話を始めます。", body:"面談のあとに日がたてば、前回の話を覚えていないのは自然なことです。「前回お話ししましたが」と始めると、お客様は責められたように感じます。前回の要点を、書いた記録をもとに短く読み上げ、今も同じお考えかを確かめてから今日の話に入ります。いつも覚えていない様子が続くときは、資料の渡し方や面談の間隔を見直します。", acts:["「前回の要点を、少しだけおさらいさせてください」と始める", "記録をもとに、前回伺ったご意向を短く読み上げる", "今も同じお考えかを確かめてから、今日の話に入る", "面談の終わりに、今日の要点を書いて渡すかを、保険会社の決まりで確かめる"], actHead:"現場で使うなら", note:"面談の要点をお客様に渡すときの書面の扱いは、所属の保険会社と御社のコンプライアンス担当で確かめる。", go:"iko", say:"前回伺ったことを、少しだけおさらいさせてください。ご家族の暮らしで、こんなことを大事にしたいと伺いました。今も同じお考えですか。", more:"前回の話を覚えていないのは、話の量が多すぎたか、お客様にとって大事な話になっていなかったか、のどちらかのことが多いです。一回の面談で伝えることを減らし、最後に今日の要点を一緒に言い直すと、覚えていただきやすくなります。ご高齢の方で気になる様子があれば、上長に相談します。", why:"お客様が理解して納得したうえで決めることが前提だからです。前回の話を確かめ直すことで、理解のずれを残さずに進められます。" },
      { key:'faq_xeba_kodomo_doseki', faq:1, grp:'eba', q:"小さなお子さん連れのお客様との面談は？", re:/(子ども|子供|お子さん|お子様|赤ちゃん)(連れ|を連れ|と一緒)[^。]{0,12}(面談|お客様|ご夫婦|来た|進め)|(面談中)?[^。]{0,4}(お子さん|子ども|子供|赤ちゃん)が[^。]{0,4}(騒い|泣い|ぐずっ)/, ng:/部下|後輩|新人|メンバー|学資|教育資金/, head:"話す量を減らして短く区切り、決める話は落ち着ける日に分けることを最初に伝えます。", body:"小さなお子さんがいると、親御さんはお子さんに気を取られ、説明に集中しにくくなります。それはお客様のせいではありません。最初に「今日は大事な所だけ伺って、決めるお話は別の日にします」と伝えておくと、親御さんも安心します。話は短く区切り、お子さんが落ち着かないときは中断します。説明と決める話を同じ日に詰め込みません。", acts:["最初に「今日は大事な所だけ伺います」と伝える", "話を短く区切り、お子さんの様子で中断する", "決める話は、落ち着いて話せる日に分ける", "オンラインや短い面談を重ねる形も提案する"], actHead:"現場で使うなら", note:"面談の分け方と記録の残し方は、御社の手引きと上長に確かめる。", say:"お子さんと一緒で大変ですね。今日は大事な所だけ伺って、決めるお話は落ち着ける日に改めてお伺いします。途中で休んでも大丈夫です。", more:"お子さんの気を引くために、おもちゃや菓子を渡すのは、贈答の決まりに触れることがあるので、社内の決まりで確かめてからにします。面談の場所を、お子さんが過ごしやすい所に変えていただくのも一つです。説明が中断した所は、次の面談の始めに必ず確かめ直します。", why:"落ち着いて話を聞ける状態で考えていただくことが、納得して決めていただく前提になるからです。日を分けることは、お客様の判断を守ることにもなります。" },
      { key:'faq_xeba_fuzai', faq:1, grp:'eba', q:"約束の時間に伺ったら、お客様が不在だった", re:/(伺ったら|訪問したら|訪問したのに|行ったら)[^。]{0,10}(不在|留守|誰もいな|いなかった)|(約束の時間|約束したのに)[^。]{0,14}(不在|留守|いなかった|誰もいな)/, ng:/部下|後輩|新人|メンバー|留守番電話|留守電/, head:"責める言葉を残さず、気づかいの一言と次の連絡の方法だけを伝え、日を改めます。", body:"約束の時間に不在なのは、急な用事、体調、日時の思い違いなど、お客様にも事情があることが多いです。何度も呼び鈴を鳴らしたり、長く待ったりせず、短く連絡を入れます。伝えるのは、伺ったことと、気づかいの一言と、次の連絡の方法だけにします。書き置きを残すときは、お客様の情報が他の人に見える形にしないよう気をつけます。", acts:["呼び鈴は控えめにし、長く待たない", "短く連絡を入れ、気づかいの一言と次の連絡の方法だけ伝える", "書き置きは、お客様の情報が見えない形にする", "次の約束では、前日に短く確かめの連絡を入れる"], actHead:"現場で使うなら", note:"書き置きやポストへの投函で残してよい中身は、御社の個人情報の規程で確かめる。", say:"本日伺いましたが、ご不在のようでしたので失礼しました。お変わりありませんか。ご都合のよいときに、改めてご連絡いただければ伺います。", more:"約束を忘れられていたと感じても、それを言葉にすると関係が冷えます。次の約束を決めるときは、前日に確かめの連絡をしてよいかを伺っておくと、同じことが起きにくくなります。続けて連絡がつかない場合は、追いかけすぎず、お客様から連絡をいただける形にとどめます。", why:"お客様の事情を思いやる一言を残すことで、次に会うときも気まずくならず、関係を続けられるからです。" },
      { key:'faq_xeba_jitaku', faq:1, grp:'eba', q:"お客様のご自宅に伺うときのマナーは？", re:/(ご自宅|お宅|お客様の家|お客様のお宅)[^。]{0,4}(に|で)[^。]{0,8}(伺う|訪問|面談|お邪魔)|(訪問|伺う)[^。]{0,8}(手土産|マナー)/, ng:/部下|後輩|新人|メンバー|飛び込み|アポなし|伺う面談/, head:"約束の時刻と終わる時刻を守り、伺う人数と目的を先に伝え、手土産は社内の決まりで確かめます。", body:"ご自宅は、お客様の暮らしの場所です。伺う日時・人数・目的・終わる時刻を前もって伝え、約束の時刻を守ります。部屋の中のものや家族の様子に、必要以上に触れません。手土産は、贈答の決まりに関わることがあるので、社内の決まりで確かめてからにします。ご高齢の方のお宅では、ご家族の同席を望まれるかも伺っておきます。", acts:["伺う日時・人数・目的・終わる時刻を、前もって伝える", "約束の時刻を守り、終わる時刻には区切る", "手土産の扱いを、社内の決まりで確かめる", "家の中の様子に、必要以上に触れない"], actHead:"現場で使うなら", note:"訪問の手順・手土産や贈答の扱い・ご高齢のお客様の同席は、御社の手引きと所属の保険会社の決まりで確かめる。", say:"当日は私一人で伺います。ご契約の中身を一緒に確かめる時間で、終わりは◯時ごろを予定しています。ご都合が変わったら遠慮なくおっしゃってください。", more:"お宅に伺うと、帰りにくくなるのはお客様のほうです。終わる時刻を最初に伝えておくと、お客様は安心して話せます。決める話をその日に詰め込むと、自宅で断りにくい雰囲気を作ってしまうので、決めていただく日は分けることも提案します。", why:"お客様の暮らしの場所を尊重することが、落ち着いて考えていただくための前提だからです。" },
      { key:'faq_xeba_senmon_yougo', faq:1, grp:'eba', q:"面談でつい専門用語を使ってしまう", re:/専門用語|(保険の言葉|説明の言葉|言葉|用語)が[^。]{0,8}(通じな|難しい|むずかしい|分かりにく|わかりにく|伝わらな)/, ng:/部下|後輩|新人|メンバー|英語|外国/, head:"言葉を言い換えたら、元の言葉も一緒に伝え、書面のどこに書いてあるかを指さします。", body:"保険の言葉は、毎日使っているこちらには普通でも、お客様には初めて聞く言葉が多いです。言葉をやさしく言い換えるのは大切ですが、言い換えだけだと、あとで書面を読んだときにどこの話か分からなくなります。言い換えたら「書面ではこの言葉で書いてあります」と元の言葉も伝え、書面の場所を指さします。言い換えで意味が変わらないよう、正確さを保ちます。", acts:["言い換えたあと、書面の元の言葉も一緒に伝える", "書面のどこに書いてあるかを指さす", "「分かりにくい言葉があれば止めてください」と最初に伝える", "言い換えで意味が変わっていないか、保険会社の資料で確かめておく"], actHead:"現場で使うなら", note:"言葉の正しい意味と、お客様への説明に使ってよい言い方は、所属の保険会社の約款・資料と社内の手引きで確かめる。", say:"分かりにくい言葉があったら、遠慮なく止めてください。今の話は、書面ではこの言葉で書いてあります。ここです。", more:"言い換えるときに気をつけたいのは、分かりやすくしようとして中身を変えてしまうことです。例えば「出ます」「大丈夫です」のような言い方は、条件を落としてしまいがちです。条件のある話は、条件ごと伝えます。辞書で言葉の意味を一緒に引いて見せるのも一つの方法です。", why:"お客様が書面を自分で読み返せることが、納得して決めていただく土台になるからです。言い換えと元の言葉をつなぐことで、分かりやすさと正確さを両立できます。" },
      { key:'faq_xeba_kazoku_kuchidashi', faq:1, grp:'eba', q:"面談でご家族が横から口を挟んでくる", re:/(ご家族|家族|息子さん|娘さん|お子さん)[^。]{0,8}(口を挟|話を遮|反対意見|話を引き取|割り込)/, ng:/部下|後輩|新人|メンバー|会議/, head:"ご家族の考えを受け止めたうえで、最後はご本人の言葉でお考えを伺います。", body:"同席したご家族は、ご本人を心配して口を挟むことが多いです。ご家族の考えも大切な意見として受け止め、遮りません。そのうえで、ご本人に向き直って「ご本人としてはいかがですか」と伺い、ご本人の言葉でお考えを聞きます。ご家族とご本人の考えが違うときは、どちらかを説得せず、違いをそのまま記録に残し、決める日を分けます。", acts:["ご家族の意見を遮らず、大切な意見として受け止める", "ご本人に向き直って、ご本人の言葉で考えを伺う", "考えが違うときは、どちらも説得せず記録に残す", "決める日を分け、ご本人が落ち着いて考えられるようにする"], actHead:"現場で使うなら", note:"ご家族の同席と意向の残し方、ご高齢のお客様の確かめ方は、所属の保険会社と御社の手引きで確かめる。", go:"iko", say:"ご心配はもっともだと思います。ありがとうございます。ご本人としては、いかがですか。ご本人のお考えを伺えますか。", more:"ご家族の言うことが正しく聞こえても、契約するのはご本人です。ご本人がご家族の前で本音を言いにくい様子なら、別の日にご本人だけで話を聞ける場を、ご家族の了承のもとで設けることもあります。ご家族を敵にしないことが、ご本人の安心にもつながります。", why:"保険の契約は、ご本人の意思で決めていただくものだからです。ご家族の思いも大切にしながら、ご本人の考えを確かめることで、無理のない判断を守れます。" },
      { key:'faq_xeba_sonohi_owari', faq:1, grp:'eba', q:"面談の終わり方で気をつけることは？", re:/(面談|商談)の(終わり方|最後|終わり|締めくくり|締め)[^。]{0,10}(気をつけ|何を|確かめ|どう|一言|伝え)|(面談|商談)を[^。]{0,4}(どう)?(締めくく|締め)/, ng:/部下|後輩|新人|メンバー|クロージング|申込|決断/, head:"今日の要点を一緒に言い直し、次にすることと次の連絡をお客様と決めてから終えます。", body:"面談の最後は、話を聞いてもらえたか、次に何が起きるかを、お客様が確かめる時間です。今日伺ったことの要点を読み上げ、聞き違いが無いか確かめます。次にこちらがすること（持ち帰った問いに答える・資料を用意する）と、お客様にお願いすること（証券を探す・ご家族と話す）を言葉にし、次の連絡の日と方法を決めます。その場で決めていただく必要はありません、と添えます。", acts:["今日伺ったことの要点を読み上げ、聞き違いが無いか確かめる", "こちらがすることと、お客様にお願いすることを言葉にする", "次の連絡の日と方法を、お客様と決める", "「その場で決めていただく必要はありません」と添える"], actHead:"現場で使うなら", note:"面談の記録の残し方と、次回までの期限の目安は、御社の手引きと上長に確かめる。", go:"iko", say:"今日は、こんなお話を伺いました。合っていますか。次回までに私はこれを用意します。その場で決めていただく必要はありませんので、ご家族ともゆっくりお話しください。", more:"終わりに要点を言い直すと、お客様は自分の話が伝わったと感じ、こちらも記録を正しく書けます。次の約束を決めずに終えると、連絡が途切れやすくなります。ただ、無理に次の日を決めさせず、お客様が決めやすい形（連絡の方法だけ決めるなど）にします。", why:"お客様が安心して次の一歩を考えられるのは、何が決まって何が決まっていないかが分かるときだからです。" },
      { key:'faq_xeba_kekkon_mae', faq:1, grp:'eba', q:"結婚を控えたお客様には、最初に何を伺う？", re:/(結婚を控え|これから結婚|婚約中|結婚前|結婚予定)[^。]{0,12}(お客様|お二人|カップル|相談|面談|伺|聞いて)/, ng:/部下|後輩|新人|メンバー|自分が|私が|僕が/, head:"お二人の暮らしの予定と、今入っている保障・勤め先の制度を並べて確かめるところから始めます。", body:"結婚を控えたお二人は、住まい・仕事・お子さんの予定など、これからの暮らしを考えている時期です。保険の話より先に、お二人の暮らしの予定を伺います。そのうえで、それぞれが今入っている保険と、勤め先の制度・公的な制度でどこまで支えられるかを並べて確かめます。受取人や保障の大きさは、暮らしが決まってから一緒に考えます。", acts:["お二人の暮らしの予定（住まい・仕事・お子さん）を伺う", "それぞれが今入っている保険を、証券で確かめる", "勤め先の制度と公的な制度でどこまで支えられるかを一緒に見る", "お二人それぞれの考えを伺い、どちらか一方を説得しない"], actHead:"現場で使うなら", note:"勤め先の制度は勤め先の規程、公的な制度は所管の窓口、受取人や名前の変更の手続きは加入している保険会社で確かめる。", go:"iko", say:"おめでとうございます。保険のお話の前に、これからの暮らしの予定を伺えますか。お二人がそれぞれ今入っている保険も、一緒に並べて見てみましょう。", more:"結婚の前後は、お名前や住所が変わり、保険会社への届け出が要ることがあります。受取人が親御さんのままになっていることもよくあります。急いで新しい保険を勧めるより、今の保険の届け出と受取人を整えることのほうが先に役立つことが多いです。", why:"保険はお二人のこれからの暮らしを支えるもので、暮らしの予定が分かってこそ、必要な備えをお二人が自分で判断できるからです。" },
      /* hei.json */
      { key:'faq_xhei_uketsuke', faq:1, grp:'hei', q:"会社に電話すると受付で社長につないでもらえない", re:/(受付|代表電話|電話)[^。]{0,12}(社長|代表|経営者)[^。]{0,8}(つないで|繋いで|取り次|取次|つながら|繋がら|話せな|会えな)|(社長|代表)(に|へ)[^。]{0,6}(取り次い|取次い|つないで|繋いで)(もらえ|くれ|いただけ)な/, ng:/部下|後輩|新人|自分の会社|うちの会社/, head:"受付を越えようとするより、受付の方に用件を正直に伝えて、つなぎ方を相談します。", body:"受付の方は、社長の時間を守るのが仕事です。保険の営業と分かると断られるのは自然なことで、言い方を変えてすり抜けようとすると信頼を失います。誰の紹介か、何のために、どれくらいの時間をいただきたいかを短く伝え、社長に伝えていただく形や、手紙で用件をお送りする形をお願いします。", acts:["電話の前に、名乗り・紹介してくださった方・用件・いただきたい時間を一行ずつ書く", "受付の方には、社長にお伝えいただく形でよいかを尋ね、無理に代わってもらわない", "断られたら、用件を書いた手紙をお送りしてよいかだけ確かめて電話を終える"], actHead:"現場で使うなら", note:"電話での勧誘の決まりと記録の仕方は、御社の手順と所属保険会社のコンプライアンスの決まりで確かめる。", say:"保険代理店の者です。◯◯様からのご紹介で、社長に一度ご挨拶をお願いできればと思っています。ご都合を社長にお伝えいただけますでしょうか。", more:"場面の例は、紹介の無い会社へ初めて電話するときです。このときは、無理に社長と話そうとせず、会社の集まりや取引のある方からの紹介を探すほうが近道になることがあります。よくある勘違いは、受付の方を通り過ぎる相手と考えることで、受付の方は後々の取り次ぎも担う大事な方です。", why:"受付は会社の窓口で、社長に届く話を選ぶ役目を持っているためです。正直に用件を伝える相手には、社長の判断を仰いでくださることがあり、偽った相手は二度と通さなくなります。" },
      { key:'faq_xhei_shokai_keiro', faq:1, grp:'hei', q:"社長を紹介してもらうには、誰に頼めばいい？", re:/(社長|経営者|法人のお客様|会社のお客様)(を|の|と)[^。]{0,8}(紹介|知り合)[^。]{0,10}(誰|どこ|ルート|経路|もらう|もらえ|頼め|頼む)/, ng:/税理士|会計事務所|会計士|部下|後輩|社長から|経営者から|社長に|経営者に|(社長|経営者)の(お客様|お客さん)(から|に)|から別の(社長|経営者)|仲間/, head:"社長の紹介は、社長と日ごろ利害の無い付き合いのある方に頼むのが基本です。", body:"頼める相手は、経営者の既契約のお客様、取引のある会社の方、同じ業界の集まりの仲間、地域の経営者の会の方などです。紹介してくださる方には、どんな方に何のために会いたいかを具体的にお伝えし、紹介した方の顔をつぶさない進め方を約束します。紹介料のようなお礼の扱いは、決まりで確かめます。", acts:["紹介をお願いできる方を、関係の深さと経営者とのつながりで書き出す", "会いたい方の業種や規模と、お会いして伺いたいことを一枚にまとめて渡す", "紹介のあとは、会えたかどうかと様子を、紹介してくださった方へ必ず報告する"], actHead:"現場で使うなら", note:"紹介へのお礼や紹介料の扱いは、保険業法の決まりと所属保険会社・御社のコンプライアンス担当で確かめる。", say:"経営者の方で、会社のこれからのお金のことを一度整理したい方がいらっしゃれば、ご紹介いただけないでしょうか。お会いしたら、どんな話をしたかは必ずご報告します。", more:"一緒に見るのは、経営者の既契約のお客様の一覧と、そのお客様の取引先や業界の集まりです。よくある勘違いは、紹介は数をお願いするものと考えることで、一人の紹介を丁寧に進めて報告するほうが、次の紹介につながります。税理士の先生からの紹介は、別の気配りが要ります。", why:"社長は、信頼している人の紹介なら、知らない営業の話でも時間を取ってくださるためです。紹介した方は自分の信用を貸しているので、その信用を守る進め方が次の紹介を生みます。" },
      { key:'faq_xhei_shacho_shokai', faq:1, grp:'hei', q:"社長から別の社長を紹介してもらうには？", re:/(社長|経営者)(の(お客様|お客さん))?(から|に)[^。]{0,12}(別の|知り合いの|お知り合いの|仲間の|ほかの|他の)?(社長|経営者)(仲間)?[^。]{0,6}(紹介|ご紹介)|(社長|経営者)仲間[^。]{0,6}(紹介|ご紹介)/, ng:/部下|後輩|税理士|会計事務所/, head:"社長の紹介は、社長ご自身の役に立てたことが伝わってからお願いします。", body:"社長の周りには、同じ悩みを持つ経営者が多くいます。ご自身の会社のお金の整理が役に立ったと感じていただけたあとに、同じように整理したほうがよさそうな方がいらっしゃるかを伺います。紹介される方には、社長がどんな話を受けたかが伝わるので、何をした担当かを短く言葉にしておきます。", acts:["社長の会社で役に立てたことを、社長の言葉で振り返っていただく", "紹介をお願いする前に、どんな方に役立てるかを一言で言える形にしておく", "紹介のあとは、社長に経過を報告し、紹介先の話の中身までは話さない"], actHead:"現場で使うなら", note:"紹介へのお礼の扱いと、紹介先の情報の取り扱いは、所属保険会社と御社のコンプライアンス担当で確かめる。", say:"社長の会社で整理したお金の流れの表のように、一度まとめておいたほうが安心できそうな経営者の方がいらっしゃれば、ご紹介いただけないでしょうか。", more:"場面の例は、決算のあとの面談で、社長に会社の一年のお金の予定表をお渡しした回です。役に立った手応えがあるときに、紹介を一言お願いします。よくある勘違いは、契約の直後にすぐお願いすることで、社長が中身を実感する前だと、紹介される方にも何の担当か伝わりません。", why:"社長は、紹介した相手に迷惑がかからないかを一番気にするためです。自分が受けて役に立ったことなら、相手にも勧められると感じていただけます。" },
      { key:'faq_xhei_dantai', faq:1, grp:'hei', q:"法人会や商工会議所の集まりにはどう関わる？", re:/(法人会|商工会議所|商工会|経営者の会|経営者団体|青年会議所|中小企業家|ロータリー|ライオンズ)[^。]{0,14}(関わ|参加|入る|入ると|入った|役立|何を|どう|集まり)/, ng:/部下|後輩|交流会/, head:"経営者の集まりでは、保険を売る場にせず、会の役目を担って顔を覚えていただきます。", body:"地域や業界の経営者の集まりは、会員どうしの学びや交流のための場です。入ってすぐに保険の話をすると敬遠されます。会の行事の手伝いや係を引き受け、会員として長く参加するうちに、会社の相談を受ける関係が生まれます。会によっては勧誘の決まりがあるので、先に確かめます。", acts:["入る前に、会の目的と、会員どうしの勧誘の決まりを確かめる", "行事の係や手伝いを引き受け、会の中での役目を一つ持つ", "名刺を交わした方には、その場の話題に沿ったお礼だけを送り、勧誘の連絡をしない"], actHead:"現場で使うなら", note:"会の勧誘の決まりは各団体の規約で、会費や参加の扱いは御社の社内の決まりで確かめる。", say:"この会では、保険のお話はこちらからは控えています。会社のことで気になることがあれば、いつでも声をかけてください。", more:"一緒に見るのは、会の規約と行事の予定表です。よくある勘違いは、名刺の数が成果になると考えることで、会の中で信頼される役目を持つほうが、相談の声がかかります。続けて参加することが前提なので、通える会を一つか二つに絞ります。", why:"経営者の集まりでは、会員は営業を受けに来ているわけではないためです。役目を果たす姿を見てもらうと、売り込まない相手として信頼され、会社の相談が自然に来るようになります。" },
      { key:'faq_xhei_jizen', faq:1, grp:'hei', q:"社長に会う前に、会社の何を調べておく？", re:/(社長|経営者|法人|会社)[^。]{0,10}(会う前|訪問(する)?前|面談の前|伺う前|行く前|訪ねる前)[^。]{0,14}(調べ|下調べ|見て|見てお|確かめ|準備)|(会社|法人)(訪問|の訪問)の?(前の)?(下調べ|事前の調べ|準備)/, ng:/部下|後輩|個人の/, head:"会社の歩み・事業の中身・業界の動きの三つを、公開されている情報から調べておきます。", body:"会社のホームページで創業の年や沿革・事業の中身・社長の言葉を、業界のニュースで最近の動きを見ておきます。登記の情報で役員や本店の場所を確かめておくこともあります。調べたことは面談で答え合わせのように並べず、社長の口から話していただくきっかけに使います。", acts:["会社のホームページから、沿革・事業・社長の言葉を一枚に書き写す", "業界のニュースで、最近の動きを一つ選び、社長に伺う問いにしておく", "調べて分からなかったことを、面談で伺うことの一覧にする"], actHead:"現場で使うなら", note:"公開の情報の調べ方は御社の手順で、登記の情報の読み方は司法書士や法務局の案内で確かめる。調べた個人の情報の扱いは御社のコンプライアンス担当で確かめる。", say:"ホームページで会社の歩みを拝見しました。創業のころのお話を、社長から直接伺えればうれしいです。", more:"場面の例は、紹介で初めて伺う建設会社です。施工の実績のページから得意な工事を、業界のニュースから人手の話題を拾っておくと、社長の悩みに近い問いができます。よくある勘違いは、調べたことを全て話してしまうことで、社長が話す場を奪ってしまいます。", why:"社長は自分の会社に関心を持ってくれる相手に話をしたくなるためです。下調べは、社長の話を深く聞くための準備で、知識を見せるためのものではありません。" },
      { key:'faq_xhei_shokai_kiku', faq:1, grp:'hei', q:"社長との初めての面談では何を聞く？", re:/(社長|経営者)(と|との|に)[^。]{0,4}(初めて|初回|最初)の?[^。]{0,6}(面談|会った|会う|訪問|お会い)[^。]{0,14}(何を(聞|伺)|聞くこと|伺うこと|聞くべき|伺うべき)|(初めて|初回|最初)の?(社長|経営者)(訪問|面談|との面談)[^。]{0,10}(何を(聞|伺)|聞くこと|伺うこと|聞くべき|伺うべき)/, ng:/部下|後輩|オンライン/, head:"初めての面談では、会社の歩みと、社長がこれから会社をどうしたいかを伺います。", body:"保険の話は初回ではしないくらいのつもりで、創業や継いだときの話、今いちばん気にかけていること、数年先に会社をどうしていたいか、の順で伺います。社長の言葉を書き留め、次の面談でその言葉に沿って整理したものをお持ちします。会社の数字は、関係ができてから伺います。", acts:["伺うことを、これまで・今・これからの三つの見出しで書いておく", "社長の言葉はそのまま書き留め、次の面談の資料の見出しに使う", "面談の終わりに、次に何をお持ちするかと、次の日程を一つ決める"], actHead:"現場で使うなら", note:"面談で伺った会社と社長の情報の扱いは、御社の手順と所属保険会社のコンプライアンスの決まりで確かめる。", say:"今日は保険のお話ではなく、社長が会社をどうされたいかを伺いに来ました。会社を始められたころのことから、お聞かせいただけますか。", more:"場面の例は、二代目の社長との初回です。継いだときの思いと、先代から引き継いだ課題を伺うと、事業承継や借入の話に自然につながります。よくある勘違いは、初回で困りごとを全部聞き出そうとすることで、話しやすい順に伺うほうが本音に近づきます。", why:"社長が保険を考えるのは、会社の行き先と困りごとがはっきりしたときだからです。行き先が見えないうちに保険の話をしても、何のための備えかが社長に伝わりません。" },
      { key:'faq_xhei_nayami', faq:1, grp:'hei', q:"経営者の悩みはどう聞けばいい？", re:/(経営者|社長|オーナー)の?[^。]{0,4}(悩み|困りごと|困り事|課題|心配事)[^。]{0,8}(聞き方|聞き出|どう聞|聞けば|知るには|引き出)|(経営者|社長|オーナー)が[^。]{0,4}(何に|何を|何で)(困って|悩んで)[^。]{0,10}(知る|聞く|聞け|分かる|わかる|つかむ|探る)/, ng:/部下|後輩|自分の悩み|私の悩み|リスクを伝え/, head:"経営者の悩みは、人・お金・売上・これからの四つの切り口で、順に伺います。", body:"いきなり何に困っていますかと聞くより、社員の採用や定着、資金繰りや借入、取引先や売上の動き、後継者や社長ご自身のこれから、のように切り口を示すと、社長は話しやすくなります。話が出たら、なぜそれが気になるのかを一段深く伺い、保険で答えられることと、ほかの専門家に任せることを分けて考えます。", acts:["人・お金・売上・これからの四つを紙に書き、社長に選んでいただく", "出てきた悩みには、いつから・何がきっかけで、を一つずつ伺う", "保険で備えられる悩みと、税理士や社会保険労務士に任せる悩みを分けてメモする"], actHead:"現場で使うなら", note:"税・労務・法律の悩みは、顧問の税理士・社会保険労務士・弁護士の領域。こちらで判断せず、専門家につなぐ。", say:"経営者の方からよく伺うのは、人のこと、お金のこと、売上のこと、これからのことです。この中で、今いちばん気にかかっているのはどれでしょうか。", more:"一緒に見るのは、四つの切り口を書いた一枚の紙です。社長が指さしたところから話を始めます。よくある勘違いは、保険で解決できる悩みだけを探すことで、保険と関係の無い悩みを丁寧に聞くほうが、相談相手として信頼されます。", why:"社長は悩みを一人で抱えていることが多く、言葉にする機会が少ないためです。切り口があると話しやすくなり、話してみて初めて自分の悩みの順番に気づく社長も多くいます。" },
      { key:'faq_xhei_jikan', faq:1, grp:'hei', q:"社長と会える時間が短い。何を話す？", re:/(社長|経営者)[^。]{0,10}(時間が短|短い時間|少ししか時間|時間を少し|時間がほとんど|時間が少な)|(社長|経営者)との?[^。]{0,4}(面談|面会)の?時間が短/, ng:/部下|後輩|上司/, head:"短い時間には、社長に決めていただくことを一つに絞って持っていきます。", body:"社長の時間は限られているので、前もって用件を一つに絞り、資料は一枚にまとめ、結論と確かめたいことを先に伝えます。決められないことは次回に回し、経理の方や総務の方と進められることは、社長の了承を得て担当の方と進めます。終わる時刻は自分から守ります。", acts:["面談の前に、今日社長に決めていただくことを一つだけ書く", "資料は一枚にし、結論・理由・確かめたいことの順に並べる", "終わる予定の時刻の少し前に、自分から話をまとめる"], actHead:"現場で使うなら", note:"担当の方と進めてよい範囲と、社長の了承の取り方は、会社の決まりと御社の手順で確かめる。", say:"お時間をいただきありがとうございます。今日は一つだけ、ご判断いただきたいことをお持ちしました。残りは経理のご担当の方と進めてもよろしいでしょうか。", more:"場面の例は、朝礼のあとに少しだけ時間をもらえる社長です。このときは資料を読んでいただく時間は無いので、一枚の紙で指さしながら話します。よくある勘違いは、短い時間に全てを詰め込むことで、話が多いほど社長は決められなくなります。", why:"社長は一日に多くの判断をしているので、判断の材料が絞られているほど決めやすいためです。時間を守る相手には、次の時間も取ってくださるようになります。" },
      { key:'faq_xhei_keiri', faq:1, grp:'hei', q:"経理や総務の担当者とはどう付き合う？", re:/(経理|総務|事務|窓口)(の)?(担当者|担当の方|ご担当|方)[^。]{0,12}(付き合|接し|接す|関係|やりとり|やり取り|仲良|うまく)/, ng:/部下|後輩|うちの会社|自分の会社|社内の|代理店の|奥様|奥さん/, head:"経理や総務の方は、社長と並ぶ大事な相手として、手間を減らす形で関わります。", body:"法人の保険の手続きや書類のやりとりは、多くの場合、経理や総務の方が担います。社長だけと話を進めると、担当の方が事情を知らないまま書類を受け取ることになり、手続きが止まります。社長の了承を得て担当の方にも話を共有し、書類は分かりやすく整えて渡し、問い合わせには早く答えます。", acts:["社長に、経理や総務のどなたと手続きを進めればよいかを伺う", "担当の方に渡す書類は、何のための書類か・いつまでに何をするかを一枚に添える", "担当の方からの問い合わせには、その日のうちに答えるか、いつ答えるかを伝える"], actHead:"現場で使うなら", note:"担当の方と共有してよい情報の範囲は、社長の了承と、御社と所属保険会社のコンプライアンスの決まりで確かめる。", say:"手続きの書類は、ご担当の方の手間が少しでも減るように整えてお持ちします。分からないところがあれば、いつでもご連絡ください。", more:"一緒に見るのは、保険料の引き落としの口座や、年に一度の保険会社からの書類の届き先です。よくある勘違いは、担当の方は社長の決めたことを処理するだけの方だと考えることで、実際は保険の書類の扱いを一番よく知っている方です。社長が交代しても、担当の方との関係が続くこともあります。", why:"法人の保険は、契約のあとも保険料の支払い・経理の処理・書類の保管が毎年続くためです。その実務を担う方が分かりやすく扱えると、会社の中で保険がきちんと管理されます。" },
      { key:'faq_xhei_tantou_idou', faq:1, grp:'hei', q:"法人の窓口の担当者が異動した。どうする？", re:/(法人|会社|先方|取引先)の?[^。]{0,8}(窓口|経理|総務|担当者|担当の方|ご担当)[^。]{0,10}(異動|辞め|退職|替わ|変わ|交代)/, ng:/部下|後輩|自分の|私の|うちの代理店|保険会社|代理店担当|募集人|代表者|社長が|会社名/, head:"担当の方が替わったら、新しい方にご挨拶し、会社で入っている保険の一覧を一緒に確かめます。", body:"前の担当の方が知っていたこと（保険の目的・書類の保管場所・支払いの流れ）が、新しい方に引き継がれていないことがあります。社長の了承を得て、新しい担当の方に保険の一覧と、毎年の手続きの予定を説明します。前の担当の方へのお礼も、できる範囲で伝えます。", acts:["会社で入っている保険の一覧と、毎年の手続きの予定を一枚にまとめる", "社長の了承を得て、新しい担当の方に挨拶と説明の時間をいただく", "保険会社からの書類の届き先や連絡先が、前の担当の方のままになっていないか確かめる"], actHead:"現場で使うなら", note:"届き先や連絡先の変更の手続きは、所属保険会社の手順で確かめる。新しい担当の方に話す範囲は社長の了承と御社の決まりで決める。", say:"これまでのご担当の方と進めていた保険の手続きを、一覧にまとめてお持ちしました。ご都合のよいときに、一度ご説明させてください。", more:"場面の例は、経理の方が退職して、保険料の引き落としの通知が誰にも見られないまま机に残っていた会社です。よくある勘違いは、会社が覚えていると思い込むことで、実際は担当の方の頭の中にしか無いことも多くあります。新しい担当の方との最初の説明は、手続きの予定から始めます。", why:"法人の保険は、担当の方の手で毎年の手続きが回っているためです。担当が替わったときに説明を入れておかないと、保険の目的が忘れられ、手続きの漏れや、要る保険の解約につながることがあります。" },
      { key:'faq_xhei_kessaisha', faq:1, grp:'hei', q:"法人で保険を決めるのは誰？", re:/(法人|会社)[^。]{0,8}(保険|契約)[^。]{0,8}(決めるのは誰|誰が決め|決裁者|決裁権|決定権|決める権限)|決裁者[^。]{0,8}(確かめ|見極め|誰|分から)|(社長|会長|専務)[^。]{0,4}(と|か)[^。]{0,4}(社長|会長|専務)[^。]{0,6}(どちらが|どっちが)[^。]{0,4}決め/, ng:/部下|後輩|うちの会社|自分の会社|うちの代理店/, head:"法人の保険を決める方は、会社によって違うので、初めの面談で率直に伺います。", body:"社長が全て決める会社もあれば、会長や専務、経理の責任者の意見が大きい会社、役員の会議や稟議を通す会社もあります。決める方を知らないまま話を進めると、最後に別の方の反対で止まります。誰が・どの順で・どんな手続きで決めるのかを伺い、決める方が全員そろう場を作ります。", acts:["初めの面談で、保険のことはどなたとどなたで決めるかを伺う", "社内の手続き（役員の会議・稟議）があるか、どんな資料が要るかを伺う", "決める方全員がそろう日に、提案の説明の場をお願いする"], actHead:"現場で使うなら", note:"会社の決め方は会社の定款と社内の規程で決まる。会社法上の手続きの判断は弁護士・司法書士、経理の扱いは顧問の税理士で確かめる。", say:"保険のことは、社長お一人でお決めになりますか。ほかにご意見を伺っておいたほうがよい方がいらっしゃれば、その方にも一緒に聞いていただける日を作れればと思います。", more:"場面の例は、社長は乗り気でも、経理を見ている会長が保険料の負担を気にしている会社です。会長に事情を知らせないまま申込みに進むと、あとで解約の話になることがあります。よくある勘違いは、社長の了承があれば十分だと考えることで、会社の中の納得まで考えます。", why:"法人の保険は会社のお金で払う長い付き合いで、社長一人の気持ちだけでは続かないためです。決める方が納得していると、契約のあとも保険の目的が会社の中で守られます。" },
      { key:'faq_xhei_ringi', faq:1, grp:'hei', q:"稟議に通す資料を作ってほしいと頼まれた", re:/(稟議|りんぎ|決裁用|役員会|取締役会)[^。]{0,12}(資料|書類|通す|かける|作って|作る|お願い|頼まれ)/, ng:/部下|後輩|うちの会社|自分の会社|うちの代理店|社内の会議/, head:"稟議の資料は、保険会社の資料を土台に、会社が決めるための材料を並べる形で作ります。", body:"書くのは、何のための保険か（目的）・誰が契約者・被保険者・受取人か・保険料と払い方・解約したときの扱いの考え方・経理の扱いは顧問の税理士に確かめること、などです。こちらで作る資料は募集の資料にあたることがあり、保険会社の審査が要る場合があります。有利だと言い切る書き方はしません。", acts:["担当の方に、会社の稟議の書式と、決める方が気にしている点を伺う", "保険会社の設計書と契約概要をもとに、目的・契約の形・保険料を一枚に並べる", "こちらで作る資料が審査の要るものかを、所属保険会社に先に確かめる"], actHead:"現場で使うなら", note:"自作の資料の扱いは所属保険会社の募集文書の決まりで確かめる。経理の扱いは顧問の税理士の判断で、資料にも確かめる先として書く。", say:"稟議の資料は、保険会社の資料をもとに、目的と契約の形をまとめてお作りします。経理の扱いは、顧問の税理士の先生にご確認いただく形で書かせてください。", more:"一緒に見るのは、会社の稟議の書式・保険会社の設計書・契約概要・注意喚起情報です。よくある勘違いは、営業の資料をそのまま稟議に載せることで、会社の決める方には目的と負担と注意点が見えることが大事です。資料に書いた数字は、保険会社の資料と同じかを必ず照らします。", why:"稟議は、担当の方が会社の中で決める方に説明するための書類で、担当の方の責任にもなるためです。正確で偏りの無い資料は担当の方を守り、会社の判断を確かなものにします。" },
      { key:'faq_xhei_saiyou', faq:1, grp:'hei', q:"人が採れない・辞めると悩む社長にどう話す？", re:/(人が採れな|採用(が|で)[^。]{0,6}(うまくいかな|難し|困)|人手不足|人手が足りな|社員が(定着しな|辞め|すぐ辞め|続かな)|定着(しな|率))[^。]{0,16}(社長|経営者|会社|どう話|何を話|話し方)/, ng:/部下|後輩|新人|メンバー|うちの代理店|自分の会社|うちの会社/, head:"人の悩みには、保険の前に、社長が社員に何を約束したいかを一緒に言葉にします。", body:"採用や定着の悩みは、給料・働き方・職場の雰囲気・将来の安心など、いくつもの理由が重なっています。保険で答えられるのはその一部（万一の保障や退職金の準備など）です。社長の話を伺い、労務のことは社会保険労務士、採用の仕組みはその専門家に任せ、保険で支えられる部分だけを提案します。", acts:["辞めた方の理由として社長が感じていることを、そのまま伺う", "保険で支えられること・ほかの専門家が支えることを分けて一枚にする", "社会保険労務士など、相談できる専門家がいるかを伺う"], actHead:"現場で使うなら", note:"労務・就業規則・助成金のことは社会保険労務士、採用の仕組みは、その分野の専門家に任せる。保険でできることを広く言わない。", say:"社員の方が長く働きたいと思える会社にするために、社長が約束したいことは何でしょうか。保険でお手伝いできるのはその一部なので、ほかの専門家の方とも一緒に考えさせてください。", more:"一緒に見るのは、社員の人数と年代・退職金の規程・今ある休みの制度です。よくある勘違いは、福利厚生の保険で採用の悩みが解決すると話すことで、社長の期待を外すと信頼を失います。保険は約束を形にする道具の一つとして位置づけます。", why:"人の悩みの根は会社ごとに違い、保険だけで解決できることは限られているためです。できることとできないことを分けて話す相手は、社長にとって信頼できる相談相手になります。" },
      { key:'faq_xhei_doui', faq:1, grp:'hei', q:"社員に保険をかけることを、社長が社員に話したがらない", re:/(社員|従業員|役員|スタッフ)(に|には|へ)[^。]{0,4}(内緒|黙って|知らせず|知らせない|話さず|話さない|言わず|言わない|言いたがらな|話したがらな|伝えたがらな|伝えず)[^。]{0,16}(保険|かけ|掛け|入れ|契約)|(保険|かけ|掛け)[^。]{0,16}(社員|従業員|スタッフ)(に|には|へ)[^。]{0,4}(内緒|黙って|知らせず|知らせない|話さず|話さない|言わず|言わない|言いたがらな|話したがらな|伝えたがらな)/, ng:/うちの会社|自分の会社|団体|部下|後輩|家族に|妻に|夫に|奥様に|ご主人に/, head:"社員を被保険者にする死亡の保険は社員ご本人の同意が要るので、内緒では進めません。", body:"契約者以外の人を被保険者とする死亡の保険は、被保険者の同意が無いと効力が生じない決まりです。社長が話したがらないのは、自分の命にお金をかけられていると社員に受け取られないかを、心配していることが多いからです。何のための保険か・受取人は誰か・万一のときにご家族へどう届くかを、社長の言葉で伝える場を一緒に準備します。", acts:["社長が社員に話しにくい理由を、先に一つずつ伺う", "目的・受取人・万一のときの流れを、社長が話す順に一枚にまとめる", "同意の取り方と書類は、所属保険会社の申込みの手順で確かめる"], actHead:"現場で使うなら", note:"同意の様式と手続きは所属保険会社の約款と手順で確かめる。死亡退職金や弔慰金の規程は社会保険労務士と顧問の税理士、法律の解釈が問題になる場面は弁護士に確かめる。", say:"この保険は会社が契約し、皆さんを被保険者にするものです。何のための保険で、万一のときにご家族へどう届くかをご説明したうえで、同意をお願いしています。", more:"一緒に見るのは、会社の死亡退職金や弔慰金の規程です。保険金を規程に沿ってご家族に渡す形になっていると、社長も社員も話しやすくなります。よくある勘違いは、会社が保険料を払うから同意は要らないと考えることで、同意が無いと契約そのものが成り立ちません。", why:"本人の知らないところで命に保険がかけられると、悪用のおそれや、知ったときの不信につながるためです。同意の決まりは被保険者を守るためにあり、説明の場は社員の安心にもつながります。" },
      { key:'faq_xhei_shain_setsumei', faq:1, grp:'hei', q:"会社で入る保険を社員にどう説明する？", re:/(会社|法人)(で|が)[^。]{0,6}(入る|入った|かける|かけた|契約する|契約した)[^。]{0,6}(保険|制度)[^。]{0,10}(社員|従業員|スタッフ)[^。]{0,6}(説明|伝え|知らせ)|(社員|従業員)(へ|に)の?[^。]{0,4}(保険|制度)の?(説明|伝え方)|(会社|法人)の[^。]{0,4}(保険|制度)[^。]{0,8}(社員|従業員|スタッフ)(に|へ)[^。]{0,4}(説明|伝え|知らせ)/, ng:/うちの会社|自分の会社|社内の|部下|後輩|説明会|内緒|黙って|知らせず|知らせない|話さず|言わず/, head:"社員への説明は、会社が何のためにこの仕組みを用意したかを、社長の言葉で先に伝えます。", body:"保険の中身から話すと、社員は自分に何の得があるのかだけを気にします。社長が社員とその家族をどう守りたいかを先に伝え、そのあとで、誰が保険料を払うか・受取人は誰か・辞めたときや万一のときにどうなるかを、規程に沿って説明します。分からないことの問い合わせ先も伝えます。", acts:["社長に、この仕組みを用意した理由を一言で話していただく", "説明は、目的・保険料を払う人・受取人・辞めたとき・万一のときの順に並べる", "規程や保険会社の資料と違うことを口頭で言わないよう、資料を指さして説明する"], actHead:"現場で使うなら", note:"説明の内容は会社の規程と所属保険会社の資料に合わせる。就業規則や労務の扱いは社会保険労務士、経理と税は顧問の税理士で確かめる。", say:"この仕組みは、社長が皆さんとご家族の安心のために用意したものです。万一のときや辞めるときにどうなるかを、規程に沿ってご説明します。", more:"一緒に見るのは、会社の死亡退職金や弔慰金の規程・退職金の規程・保険会社の資料です。よくある行き違いは、受取人が会社になっている保険を、社員が自分のための保険だと思い込むことです。説明が曖昧だと、後で誤解が生まれます。規程に書いてあることだけを話します。", why:"福利厚生は社員が知って初めて安心につながるもので、誤解されると不信の元になるためです。目的と受取人をはっきり伝えると、社員は会社の思いを受け取りやすくなります。" },
      { key:'faq_xhei_keyman', faq:1, grp:'hei', q:"社長以外のキーマンの保障はどう考える？", re:/キーマン|キーパーソン|(幹部|部長|専務|常務|役員|技術者|職人)[^。]{0,12}(万一|もしも|亡くな)[^。]{0,12}(会社|売上|保障|備え)|(幹部社員|幹部|専務|常務)の?[^。]{0,4}保障/, ng:/部下|後輩|うちの会社|自分の会社|社長が|社長に/, head:"キーマンの保障は、その方がいなくなったとき会社の何が止まるかを書き出すことから始めます。", body:"売上の多くを担う営業の責任者や、会社に一人しかいない技術者、取引先との関係を持つ役員などがいなくなると、売上が落ちたり、代わりの人を探すお金がかかったりします。その方が担っている仕事と、止まったときの影響を社長と一緒に書き出し、備え方の一つとして保険を考えます。ご本人の同意が要ります。", acts:["その方が担う仕事・売上・取引先との関係を社長と書き出す", "代わりの人を育てる・探すのにかかる期間とお金を、社長の見込みで伺う", "被保険者になる方には、目的と受取人を説明し同意をいただく"], actHead:"現場で使うなら", note:"保険料の経理と税の扱いは顧問の税理士、同意の手続きは所属保険会社の手順で確かめる。必要な額を言い切らない。", say:"もし◯◯部長がいなくなったら、会社のどの仕事が止まるかを、一度一緒に書き出してみませんか。備えるかどうかは、書き出してから社長に決めていただければ大丈夫です。", more:"場面の例は、社長のほかに一人の職人さんが仕事の中心を担っている工務店です。その方がいなくなると、受けている工事を進められなくなることがあります。よくある勘違いは、社長の保障だけを考えることで、会社によっては社長より売上への影響が大きい方がいます。", why:"中小企業では、特定の人の力に売上や信用が集まっていることが多いためです。その方がいなくなったときの穴を埋める間のお金を考えるのが、キーマンの保障の考え方です。" },
      { key:'faq_xhei_teiansho', faq:1, grp:'hei', q:"法人の提案書には何を書く？", re:/(法人|社長|経営者|会社)(向け|へ|に出す|に渡す|の)?の?[^。]{0,4}(提案書|提案資料)[^。]{0,10}(何を書|書くこと|中身|作り方|作る|まとめ)/, ng:/部下|後輩|自作|加工|書き換/, head:"法人の提案書には、目的・会社の数字との関係・出口・注意点を一枚に並べます。", body:"まず社長から伺った悩みや目的を社長の言葉で書き、次に決算書から拾った数字（借入・手元の預金など）との関係、契約の形（契約者・被保険者・受取人）と保険料、いつ何のために受け取るか（出口）、注意点（解約したときの扱い・経理は顧問の税理士に確かめること）を並べます。有利だと言い切らない書き方にします。", acts:["一枚目の頭に、社長から伺った言葉をそのまま目的として書く", "契約の形と出口を、図か表で一目で分かるように並べる", "注意点と確かめる先（顧問の税理士・保険会社の資料）を同じ紙に必ず書く"], actHead:"現場で使うなら", note:"自作の資料の扱いは所属保険会社の募集文書の決まりで確かめる。経理と税の扱いは顧問の税理士の判断。", say:"社長から伺ったことを目的として頭に書き、そのための形と注意点を一枚にまとめました。経理の扱いは顧問の先生にご確認いただく前提でご覧ください。", more:"一緒に見るのは、保険会社の設計書・契約概要・会社の決算書です。よくある勘違いは、解約返戻率の表を提案の中心にすることで、社長が知りたいのは会社のどの困りごとにどう効くかです。数字は保険会社の資料の数字をそのまま使い、こちらで加工しません。", why:"社長が判断するのは、保険が会社の目的に合うかどうかだからです。目的と出口と注意点が一枚で見えると、社長も顧問の税理士も同じ紙で考えられます。" },
      { key:'faq_xhei_houjinnari', faq:1, grp:'hei', q:"個人事業から会社にしたお客様に、何を確かめる？", re:/法人成り|法人化(した|する|したい|された|して)|(個人事業|自営業|個人事業主)[^。]{0,10}(会社にし|会社を(作|立ち上げ|設立)|法人にし|法人を(作|設立))|(お客様|お客さん)[^。]{0,6}会社を(作|立ち上げ|設立)/, ng:/代理店|うちの会社|自分の会社|私の会社|わが社|自分が法人|私が法人|部下|後輩/, head:"会社にすると社会保険・受け取り方・契約の形が変わるので、三つを順に確かめます。", body:"個人事業のときと会社にしたあとでは、入る公的な保険（国民健康保険と国民年金から、健康保険と厚生年金へ）、ご本人の受け取り方（事業の利益から、会社からの役員報酬へ）、保険を誰の名前で持つかが変わることが多くあります。今の保険を個人のままにするか、会社で新しく用意するかは、顧問の税理士の確認と合わせて考えます。", acts:["会社にした時期と、健康保険・厚生年金に入ったかを伺う", "個人のときの保険を一覧にし、個人のまま続けるものと会社で考えるものに分ける", "役員報酬の決め方と保険料の払い方は、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"社会保険の加入の要件と手続きは年金事務所と社会保険労務士、役員報酬と保険料の経理と税は顧問の税理士、契約の形は所属保険会社の資料で確かめる。", say:"会社にされたことで、公的な保険やお金の受け取り方が変わっているかもしれません。今のご契約が新しい形に合っているか、一緒に確かめさせてください。", more:"よくある勘違いは、個人で入っていた保険を、そのまま会社の契約に移せば済むと考えることです。契約者を変えると税と経理の扱いが変わるので、移すかどうかは顧問の税理士の確認が先です。健康保険に変わると、病気やけがで休んだときの公的な支えも変わるので、休んだときの備えも見直します。", why:"会社にすると、社長ご本人と会社が別の財布になり、どちらが何に備えるかが変わるためです。個人のときのままの保険では、守る相手と払う人がずれることがあります。" },
      { key:'faq_xhei_kojin_kara', faq:1, grp:'hei', q:"社長個人の保険の相談から、会社の話にどう広げる？", re:/(社長|経営者)(個人|の個人)[^。]{0,10}(保険|契約|見直し|相談)[^。]{0,16}(会社|法人)[^。]{0,6}(話|保険|契約|相談|つなげ|広げ)|(個人の保険|個人契約)[^。]{0,10}(付き合い|担当)[^。]{0,10}(社長|経営者)[^。]{0,10}(会社|法人)/, ng:/分け|役割|違い|どちらで|個人で入るか|法人で入るか|部下|後輩/, head:"社長個人の保険の整理を丁寧に終え、会社の話は社長が望んだときに伺います。", body:"個人の保険の見直しは、ご家族を守るお金の話です。その中で、会社の借入の保証人になっているか、退職の予定があるかを伺うと、会社と個人のお金がつながっているところが見えてきます。そこで初めて、会社の側の備えも一度整理しませんかと尋ね、社長がうなずいたら、決算書や会社の保険の話に進みます。", acts:["個人の保険の見直しの最後に、会社の借入の保証人になっているかを伺う", "個人の保障の表に、会社から受け取るお金（役員報酬・退職金の予定）の欄を作る", "会社の話に進むときは、会社の保険の一覧と顧問の先生の有無から伺う"], actHead:"現場で使うなら", note:"個人と会社のどちらで備えるかの税と経理の扱いは顧問の税理士、契約の形は所属保険会社の資料で確かめる。会社の情報の扱いは御社の手順に沿う。", say:"ご家族の備えを整理する中で、会社の借入やご退職の予定とつながるところが見えてきました。差し支えなければ、会社の側の備えも一度一緒に整理しませんか。", more:"よくある失敗は、個人の見直しの途中で会社の保険の話を持ち出し、個人の相談が中途半端になることです。個人の整理を終えてから、つながるところを一つだけ示します。社長が会社の保険はほかの人に任せていると言うときは、無理に入らず、困ったときに声をかけていただける関係を残します。", why:"個人の相談をきちんと終えた担当には、会社のことも任せられるかを判断する材料がそろうためです。社長にとって会社と家計はつながっていて、両方を一緒に整理できる相手は心強い存在になります。" },
      { key:'faq_xhei_koukeisha_kankei', faq:1, grp:'hei', q:"社長の後継者とも関係を作っておくには？", re:/(後継者|跡継ぎ|後継ぎ|跡取り|次の社長|社長の(息子|娘|ご子息|お子)(さん|様)?)[^。]{0,12}(関係を(作|つく|築)|付き合い|つながっ|つながり|繋が|会わせ|紹介してもら|顔をつな)/, ng:/部下|後輩|自分の|私の|うちの代理店|わが社|育て|育成|決め方|継がない|継ぎたくない|継がせ|自社株|株を|株式を/, head:"後継者の方とは、社長の了承を得て、会社のこれからを一緒に聞く場で関係を作ります。", body:"社長が元気なうちは、後継者の方と担当が話す機会はなかなかありません。社長に、会社の保険や備えの中身を、次を担う方にも知っておいていただきたいと伝え、同席の場をお願いします。後継者の方には売り込まず、会社の今の備えを説明し、これからの考えを伺います。", acts:["社長に、後継者の方にも会社の備えを知っていただきたいと伝え、同席をお願いする", "後継者の方には、会社の保険の一覧と、それぞれの役目を説明する", "後継者の方ご本人の考えと、ご本人の暮らしの備えは、別の機会に伺う"], actHead:"現場で使うなら", note:"会社の情報を後継者の方に伝えてよい範囲は、社長の了承と御社の手順で確かめる。承継の進め方や株の扱いは、顧問の税理士や弁護士の領分。", say:"会社の保険がどんな役目を持っているかを、次を担われる方にも知っておいていただけると安心です。一度ご一緒に、今の備えを説明させてください。", more:"場面の例は、社長の息子さんが専務として入っている会社です。社長だけと話していると、代替わりのときに担当が誰にも知られていない状態になります。よくある勘違いは、承継の話を担当から持ち出すことで、承継の話をいつするかは社長が決めることです。担当は、今の備えを伝えるところから始めます。", why:"会社の保険は代替わりのあとも続くもので、次の社長が中身を知らないと、役目が引き継がれないためです。今の社長の了承のもとで会っていると、後継者の方も安心して話を聞けます。" },
      { key:'faq_xhei_tasha_tantou', faq:1, grp:'hei', q:"会社に、既に付き合いのある代理店がいると言われた", re:/^(?=.*(会社|法人|社長|経営者))(?=.*((付き合い(の|が)ある|付き合っている|取引のある|長く付き合)[^。]{0,4}(代理店|保険の担当|保険屋|保険会社の(担当|人))|(担当の代理店|担当代理店)が[^。]{0,4}(いる|います|ある)|(会社|法人)の保険は[^。]{0,8}(ほかの|他の|別の)(代理店|担当|保険屋)))/, ng:/部下|後輩|うちの代理店|自分の代理店|私の代理店|乗換|乗り換|知り合いから|知人から|友人から|悪口|批判|変えたい|移したい|移す|担当を変|引き継/, head:"今の代理店を否定せず、会社の保険の役目を一緒に整理する手伝いを申し出ます。", body:"長く付き合っている代理店がいる会社では、その関係も社長の大事な財産です。比べて乗り換えを勧める話から入ると、社長は今の担当を守る側に回ります。今の契約の中身を変える話ではなく、会社の保険が今の会社の状態に合っているかを、一緒に一覧にして確かめる役を申し出ます。損害保険と生命保険で担当が分かれていることもあります。", acts:["今の代理店との付き合いの長さと、満足している点を先に伺う", "会社の保険を一覧にして、役目と受取人を確かめる手伝いを申し出る", "一覧で気になる点があっても、まず今の担当に相談されるようお伝えする"], actHead:"現場で使うなら", note:"今の契約を見直すときの乗換の扱いと説明は、所属保険会社の決まりと御社のコンプライアンスの手順で確かめる。経理と税の扱いは顧問の税理士の領分。", say:"長くお付き合いのある担当の方がいらっしゃるのは心強いことです。今のご契約を変える話ではなく、会社の保険の役目を一覧にして整理するお手伝いならできます。", more:"場面の例は、自動車や火災の保険は長年の代理店に任せていて、社長の万一や退職金の備えは誰とも話していない会社です。このときは、まだ誰も見ていないところの話から始められます。よくある勘違いは、ほかの代理店の契約を悪く言えば任せてもらえると考えることで、それは社長の判断を否定することになります。", why:"社長は、今の担当を選んだ自分の判断を守りたいと考えるためです。否定されない相手には、空いているところや困っていることを話しやすくなります。" },
      { key:'faq_xhei_hokengirai', faq:1, grp:'hei', q:"社長が保険の話そのものを嫌がる", re:/(社長|経営者|オーナー)[^。]{0,10}(保険の話|保険と言)[^。]{0,10}(嫌が|嫌な顔|避け|聞いてもらえな|聞いてくれな|毛嫌い|うんざり)|(保険の話|保険と言)[^。]{0,10}(社長|経営者)[^。]{0,6}(嫌が|嫌な顔|避け|聞いてもらえな|聞いてくれな)/, ng:/部下|後輩|奥様|ご主人|奥さん|旦那|妻が|夫が|家族が|嫌な思い|前の担当|刺さらな|聞き流|保険屋さん|苦手|保険は嫌い|保険が嫌い|営業が|営業は|勧誘|売り込み/, head:"保険の話は脇に置き、会社の困りごとと社長のこれからの予定を伺う人になります。", body:"社長が保険の話を嫌がる理由は、売り込まれる時間だと感じていることや、前に勧められて困った経験があることが多いものです。保険という言葉を急いで出さず、会社の歩み・社員のこと・借入やこれからの計画など、社長が考えていることを伺います。困りごとの中に、備えで手伝えることが見えたときに、初めて保険の話をしてよいかを尋ねます。", acts:["次の面談の用件を、保険ではなく会社のこれからの予定を伺うことにする", "社長が前に保険で困ったことがあるかを、責めずに伺う", "保険の話をするときは、話してよいかを先に尋ねてからにする"], actHead:"現場で使うなら", note:"保険の話に入るときの説明の仕方と記録は、所属保険会社の募集の決まりと御社のコンプライアンスの手順で確かめる。", say:"今日は保険のご案内ではなく、会社のこれまでとこれからを伺いに参りました。お困りのことがあれば、一緒に整理させてください。", more:"場面の例は、毎月のように保険の営業の電話が来ていて、名乗っただけで身構える社長です。このときは、次に来る用件を先に約束し、その約束を守ることを繰り返します。よくある勘違いは、保険の良さを熱心に話せば分かってもらえると考えることで、嫌がっている相手には話すほど遠くなります。", why:"社長が嫌がっているのは保険そのものより、自分の時間を売り込みに使われることだからです。話を聞いてくれる相手だと分かると、社長も困りごとを話しやすくなります。" },
      { key:'faq_xhei_merit', faq:1, grp:'hei', q:"「うちの会社に何のメリットがある？」と社長に聞かれた", re:/(会社|法人|うち|御社)[^。]{0,12}(メリット|いいこと|良いこと|良さ|利点|何がいい|何が良い)[^。]{0,12}(聞かれ|言われ|尋ねられ|問われ)/, ng:/部下|後輩|自分の会社|私の会社|うちの代理店|わが社|ideco|nisa|イデコ|ニーサ|転職|副業|団体保険|退職金制度/, head:"税の効果から答えず、社長が気にしている困りごとに、どの役目で応えるかで答えます。", body:"メリットを聞かれて税の扱いから話すと、社長は保険を税の道具として受け取り、決算の都合だけで判断するようになります。先に、伺った話の中の困りごと（借入の返済・社員の定着・退職の準備など）を一つ挙げ、この保険がその困りごとのどこを支えるかを伝えます。費用と、合わないときに起きることも同じ場で伝えます。", acts:["答える前に、これまで伺った会社の困りごとを一つ確かめる", "その困りごとに対して、この保険が支える役目を一言で伝える", "保険料の負担と、途中でやめたときに戻るお金が払った額より少ないことがある点も伝える"], actHead:"現場で使うなら", note:"経理と税の扱いは顧問の税理士の領分で、こちらから言い切らない。商品の説明は所属保険会社の資料と募集の決まりに沿う。", say:"社長が気にされていた借入の返済の件で言いますと、この備えは、万一のときに会社に返済のお金を残す役目を持ちます。合わない点も含めてご説明しますので、比べてご判断ください。", more:"よくある失敗は、メリットを聞かれて、経費で落ちる・税金が少なくなると答えてしまうことです。税の扱いは契約の形と時期で変わり、判断は顧問の税理士が行います。もう一つは、良い点だけを並べることで、社長は合わない点も聞けたときに、話を信じやすくなります。", why:"社長は、自分の会社のために考えてくれているかを、答え方で見ているためです。困りごとから答える相手は、会社の事情を分かっている人として受け止められます。" },
      { key:'faq_xhei_suuji_kiku', faq:1, grp:'hei', q:"社長に売上や利益を聞いても失礼にならない？", re:/(社長|経営者)(に|へ)?[^。]{0,8}(売上|利益|借入|会社の数字|業績|年商)[^。]{0,12}(聞|尋ね|伺)[^。]{0,10}(失礼|いいの|迷|にくい|づらい|ずらい|良いの)|(売上|利益|会社の数字|業績|年商)[^。]{0,6}(を|は)?[^。]{0,6}(社長|経営者)(に|へ)[^。]{0,6}(聞|尋ね|伺)[^。]{0,10}(失礼|いいの|迷|にくい|づらい)/, ng:/部下|後輩|決算書|決算月|年収|家計|保険料/, head:"何のために伺うかを先に伝え、答えなくてよいと添えれば、失礼にはなりにくいです。", body:"社長が数字を聞かれて身構えるのは、何に使われるか分からないときです。会社に万一があったときに要るお金や、借入の返済の備えを考えるために伺う、と目的を先に伝えます。正確な額でなくても、おおよその規模や、増えているか減っているかの向きで足りることが多く、伺った数字をメモしてよいかも確かめます。", acts:["数字を伺う前に、何を考えるために伺うのかを一言で伝える", "正確な額ではなく、おおよその規模と増減の向きを伺う形にする", "伺った数字をメモしてよいかを確かめ、ほかに出さないことを伝える"], actHead:"現場で使うなら", note:"会社の数字の扱いと保管は、御社の個人情報と機密の扱いの手順で確かめる。数字の読み方や税の判断は顧問の税理士の領分。", say:"会社に万一のことがあったときに要るお金を考えるために、差し支えない範囲で、売上と借入のおおよその規模を伺えますか。お答えになりにくいことは、そのままで構いません。", more:"場面の例は、初めての面談で、社長が会社の歩みは楽しそうに話すのに、数字の話になると口が重くなる場面です。このときは、その日は数字を伺わず、次回に目的を伝えてから伺います。よくある勘違いは、数字を聞かないと話が進まないと焦ることで、関係ができてから見せていただける数字も多くあります。", why:"社長にとって会社の数字は、信用と引き換えに見せるものだからです。目的と扱いが分かると、何のために聞かれているかに納得でき、安心して話せます。" },
      { key:'faq_xhei_kessango', faq:1, grp:'hei', q:"決算が終わった社長との面談では、何を話す？", re:/(決算|期末)(が|の)?(終わっ|済ん|明け|後|あと)[^。]{0,14}(社長|経営者|会社|法人|お客様)[^。]{0,12}(面談|訪問|訪ね|話す|話題|確かめ|進め)/, ng:/部下|後輩|法人税|税金を払|納税|自分の会社|うちの代理店|決算前|直前|駆け込み|節税/, head:"決算の数字を一緒に振り返り、この一年で会社に起きた変化と来期の予定を伺います。", body:"決算が終わった時期は、社長が一年を振り返り、来期を考えている時期です。決算書の手元のお金と借入の動き、社員の増減や役員の顔ぶれの変化、来期に予定している設備や採用を伺い、今の保険の役目がその変化に合っているかを一緒に確かめます。この時期には新しい保険の提案を急がず、変化の確かめを先にします。", acts:["決算書の写しをいただけるかを伺い、前の期と並べて変化を見る", "社員・役員・借入・来期の予定の四つの変化を伺う", "今の保険の役目と受取人が、その変化に合っているかを一覧で確かめる"], actHead:"現場で使うなら", note:"決算の数字の読み方と保険料の経理と税の扱いは顧問の税理士、契約の内容の変更は所属保険会社の手続きで確かめる。", say:"決算お疲れさまでした。この一年で会社に起きた変化と、来期のご予定を伺えますか。今の備えがその変化に合っているかを、一緒に確かめたいと思います。", more:"一緒に見るのは、前の期と今の期の決算書を並べたときの、手元のお金と借入の残りの動きです。よくある勘違いは、利益が出た年は保険を増やす話をする好機だと考えることで、決算が終わったあとの面談は、変化を確かめて一年の備えを整える場です。役員が替わったときは、被保険者と受取人も確かめます。", why:"決算の直後は、社長が会社の一年を数字で見ている時期だからです。変化を一緒に確かめる担当は、売り込む人ではなく、会社の一年を見守る人として受け止められます。" },
      { key:'faq_xhei_teian_tomaru', faq:1, grp:'hei', q:"法人の提案が、何か月も止まっている", re:/(法人|会社|社長|経営者)[^。]{0,10}(提案|提案書|見積)[^。]{0,12}(止まっ|動かな|進まな|宙に浮|寝かされ)/, ng:/部下|後輩|自分の会社|うちの代理店|上司|会議で/, head:"止まっている場所を、決める人・時期・社内の手続き・顧問の先生の確認の順に確かめます。", body:"法人の提案は、社長が前向きでも、役員会や稟議、顧問の税理士の確認、資金繰りの都合で止まることがあります。催促の連絡を重ねる前に、社長か窓口の方に、今どこで止まっているかを率直に尋ね、こちらで用意できる資料があれば整えます。見送りも選べることを伝えると、本当の理由を話していただけることがあります。", acts:["窓口の方に、今どの段階で止まっているかを尋ねる連絡を一度だけ入れる", "顧問の先生の確認待ちなら、先生に渡す資料が足りているかを確かめる", "見送っても関係は変わらないと伝え、次に話す時期を社長に決めていただく"], actHead:"現場で使うなら", note:"提案の内容を見直すときの説明と記録は、所属保険会社の募集の決まりと御社の手順で確かめる。経理と税の確認は顧問の税理士の領分。", say:"ご提案の件、今どのあたりでご検討いただいているかを伺えますか。見送りも含めてご判断いただいて構いませんので、こちらで用意できる資料があればお申し付けください。", more:"場面の例は、社長は乗り気だったのに、決算の前に資金繰りを見直すことになり、話が止まった会社です。このときは提案をいったん置き、決算のあとに改めて伺う約束をします。よくある失敗は、止まっている理由を確かめないまま、別の案を次々に持ち込むことです。", why:"法人の判断には社長以外の人と手続きが関わり、止まる場所が個人の契約より多いためです。止まっている場所が分かれば、こちらが動けるところと待つところを分けられます。" },
      { key:'faq_xhei_gyoushu', faq:1, grp:'hei', q:"業種によって、社長に伺うことを変えたほうがいい？", re:/業種[^。]{0,10}(ごと|によって|に合わせ|の違い|で違|で変わ|別)[^。]{0,14}(話|伺|聞|中身|備え|提案|変え|違う|違い)/, ng:/部下|後輩|比準|株価|株の評価|交流会|異業種/, head:"業種で会社のお金の流れと人の頼り方が違うので、伺うことの順番を変えます。", body:"例えば、季節で売上の波が大きい業種、資格を持つ人や職人が欠けると仕事が止まる業種、設備や在庫に多くのお金がかかる業種では、気にしている困りごとが違います。業種を知ったら、お金が入る時期と出る時期、誰が欠けると仕事が止まるか、借入を何に使っているかを先に伺い、備えの話の順番を決めます。", acts:["面談の前に、その業種のお金の流れの特徴を業界の資料で調べておく", "誰が欠けると仕事が止まるかと、売上の波がいつ来るかを伺う", "業種の思い込みで決めつけず、社長の会社の場合はどうかを確かめる"], actHead:"現場で使うなら", note:"業種ごとの決まりや許認可は所管の窓口や業界団体、労務は社会保険労務士、経理と税は顧問の税理士で確かめる。", say:"この業界ならではのお困りごとがあれば教えてください。お金の入る時期と、仕事を支えている方が誰かを伺えると、備えの話がしやすくなります。", more:"場面の例は、腕のいい職人さんが数人いる工務店で、社長より職人さんが欠けるほうが仕事が止まる会社です。このときは社長の保障より先に、職人さんの病気やけがへの備えの話になることがあります。よくある勘違いは、業種の一般論で会社の困りごとを決めつけることです。", why:"会社の困りごとは、お金の入り方と、仕事を誰が支えているかで決まる部分が大きいためです。業種を手がかりに伺うと、社長は自分の会社を分かろうとしている人だと受け止めます。" },
      { key:'faq_xhei_motteiku', faq:1, grp:'hei', q:"社長に会うたびに、何を持っていけばいい？", re:/(社長|経営者)[^。]{0,8}(会うたび|訪ねる(とき|たび)|毎回|伺うたび|行くたび)[^。]{0,12}(何を持って|持っていく|持って行|用意)|(保険以外|保険の話以外)[^。]{0,8}(社長|経営者)[^。]{0,8}(役に立つ|喜ばれ|喜ぶ)[^。]{0,6}(話|情報|もの)|(社長|経営者)[^。]{0,4}(に|が)喜ばれる(話題|情報)/, ng:/部下|後輩|贈|お土産|手土産|プレゼント|お中元|お歳暮|商品券|食事|ゴルフ|雑談|世間話/, head:"前回の話の続きと、社長の会社に関わる新しい情報を一つ持っていきます。", body:"毎回の訪問に用件があると、社長は時間を取りやすくなります。持っていくのは、前回社長が気にしていたことへの答え、社長の業界や地域の動き、公的な支援の窓口の案内など、会社の役に立つ情報です。保険の新しい商品の案内は、社長から聞かれたときにします。調べたことの出どころも一緒に伝えます。", acts:["前回の面談の記録から、社長が気にしていたことを一つ選び、答えを用意する", "社長の業界や地域の話題を一つ、出どころと一緒に持っていく", "渡す情報は一枚にまとめ、保険の話をするかは社長に尋ねてから決める"], actHead:"現場で使うなら", note:"渡す資料の扱いは、所属保険会社の募集資料の決まりと御社のコンプライアンスの手順で確かめる。公的な支援の内容は、それぞれの窓口の案内で確かめる。", say:"前回お話しされていた件で、役に立ちそうな情報を一枚にまとめてきました。保険の話ではありませんので、お時間のあるときにご覧ください。", more:"場面の例は、前回の面談で社長が人手不足に悩んでいると話していた会社です。このときは、地域の公的な相談の窓口の案内を持っていくだけでも、話を覚えていてくれた人として受け止められます。よくある勘違いは、毎回新しい保険の資料を持っていくことで、社長は売り込みの訪問だと感じます。", why:"社長は、自分の話を覚えていて次に生かしてくれる相手を信頼するためです。役に立つ情報を持ってくる担当には、困ったときに相談しようと考えるようになります。" },
      { key:'faq_xhei_ginkou', faq:1, grp:'hei', q:"社長の取引銀行の担当者とは、どう関わる？", re:/(取引銀行|取引先の銀行|メインバンク|銀行|信用金庫|信金|金融機関)の?[^。]{0,4}(担当者|担当の(方|人)|人|行員|営業)[^。]{0,12}(関わ|付き合|関係|勧めて|紹介|一緒|組め|組む|会う|会って|会い)/, ng:/部下|後輩|融資|借りたい|口座|ローン|自分の|私の|うちの代理店|窓販|メインバンクとは|変えたい|一つに絞|複数/, head:"銀行の担当者とは張り合わず、社長の了承の範囲で、役目を分けて付き合います。", body:"銀行は会社にお金を貸す立場で、社長の借入や資金繰りの事情をよく知っています。銀行の窓口でも保険を扱っているので、同じ会社に保険の話をしていることもあります。社長から伺った会社の情報を、社長の了承なく銀行の担当者に話すことはせず、借入の返済の備えなど、銀行と関わる話は社長を通して進めます。", acts:["銀行の担当者と話してよいか、何を話してよいかを社長に先に伺う", "借入の残りと返済の予定は、社長から伺ったことだけを使って備えを考える", "銀行の担当者が保険の話をしているときは、比べて悪く言わず、社長の判断に任せる"], actHead:"現場で使うなら", note:"銀行と情報をやりとりしてよい範囲は、社長の了承と御社の個人情報と機密の扱いの手順で確かめる。借入と返済の扱いは社長と金融機関、税は顧問の税理士の領分。", say:"銀行のご担当の方とお話しすることがあれば、どこまでお伝えしてよいかを先に伺っておきたいと思います。会社のことは、社長のご了承の範囲でだけ扱います。", more:"場面の例は、社長が借入の返済のことを気にしていて、銀行の担当者からも保険の話をされている会社です。このとき大事なのは、どちらが先に預かるかではなく、借入の返済の備えが会社のお金の流れに合っているかです。よくある勘違いは、銀行の担当者と組めば紹介がもらえると考えることで、銀行には銀行の決まりがあります。", why:"銀行と保険の担当は、社長から見るとどちらも会社のお金の相談相手で、張り合う姿は社長に負担をかけるためです。情報を勝手に動かさない担当は、社長が安心して借入の話もできる相手になります。" },
      { key:'faq_xhei_shigyou', faq:1, grp:'hei', q:"社会保険労務士や司法書士の先生とは、どう組めばいい？", re:/(社会保険労務士|社労士|司法書士|弁護士|行政書士|士業)[^。]{0,8}(先生|事務所)?[^。]{0,8}(組め|組む|協力|連携|一緒に|つながり|つながる|付き合)/, ng:/部下|後輩|税理士|紹介料|報酬|謝礼|お金を払|自分の会社|うちの会社|相談したい|に相談|紹介してもらう|紹介をお願い/, head:"お互いの仕事の線を守り、社長の困りごとを、その先生の領分ごとに渡し合う関係にします。", body:"法人の困りごとには、就業規則や社会保険の手続き（社会保険労務士）、登記（司法書士）、契約や争い（弁護士）など、保険では答えられないものが多く含まれます。こちらは困りごとを聞き取り、どの先生の領分かを社長に伝え、社長の了承を得てつなぎます。先生からは、保険で備えられる話を受け取ります。紹介にお金のやりとりを絡めるかは、社内の決まりで確かめます。", acts:["先生ごとに、どんな相談を受けているかと、つないでほしい相談を伺う", "社長の相談を先生につなぐときは、社長の了承を得て、困りごとを一枚にまとめて渡す", "紹介のお礼の扱いは、御社のコンプライアンスの決まりと所属保険会社の決まりで確かめる"], actHead:"現場で使うなら", note:"紹介にお金や便宜のやりとりを伴うときの扱いは、御社のコンプライアンス担当と所属保険会社の決まりで確かめる。先生ごとの業務の範囲は、それぞれの会の案内で確かめる。", say:"就業規則のご相談は、社会保険労務士の先生の領分になります。社長のご了承をいただければ、お困りの点をまとめて、先生にお伝えすることもできます。", more:"場面の例は、社長が社員の退職金規程を見直したいと話している会社です。規程そのものは社会保険労務士の先生の領分で、こちらは規程と保険がつながっているかを見ます。よくある失敗は、先生の領分の質問にその場で答えてしまうことで、先生との信頼を失います。", why:"社長の困りごとは保険だけで終わらないためです。それぞれの先生の領分を尊重して渡し合う担当は、先生からも社長からも頼りにされます。" },
      { key:'faq_xhei_benkyou', faq:1, grp:'hei', q:"法人営業のために、何を勉強すればいい？", re:/(法人営業|法人の営業|法人(の)?保険|法人の担当|法人を担当|社長と話せ|経営者と話せ)[^。]{0,14}(勉強|学べ|学ぶ|学ん|知識|身につけ|身に付け)/, ng:/部下|後輩|新人|メンバー|資格|試験|教え|研修を|勉強会|セミナー/, head:"決算書の基本、会社の保険の経理、社会保険と退職金、事業を継ぐ流れの四つから学びます。", body:"社長との話は、会社のお金の話です。まず決算書で手元のお金・借入・利益の流れが読めること、次に会社で入る保険の経理の大まかな考え方（細部は税理士の領分）、社員に関わる社会保険と退職金の仕組み、事業を継ぐときの流れの入口を学びます。どれも答えを出すためではなく、社長の話を正しく聞き、どの先生につなぐかを分かるためです。", acts:["決算書の手元のお金・借入・利益の流れの三つを、実物を見ながら読む練習をする", "会社で入る保険の経理の考え方は、所属保険会社の研修資料で学ぶ", "社会保険と退職金の仕組みは、公的な案内で基本を押さえる"], actHead:"現場で使うなら", note:"会社の保険の経理の細部と税は顧問の税理士、社会保険と労務は社会保険労務士の領分。学ぶ資料は所属保険会社の研修と公的な案内で、最新の内容を確かめる。", say:"会社のお金のことは、顧問の先生方の領分を大事にしながら伺います。税や労務の細かな判断は、それぞれの先生と一緒に確かめます。", more:"よくある勘違いは、法人営業には税の細かな知識が要ると考え、税の答えを覚えようとすることです。税額の判断は税理士の業務で、こちらに要るのは、どの話が税の話かを見分けて先生につなぐ力です。学ぶ順番は、決算書が読めることが先です。", why:"社長は、自分の会社のお金の話が通じる相手かどうかを、最初のやりとりで見ているためです。基本が分かっていると、社長の話を遮らずに聞けて、先生につなぐ話も正しく渡せます。" },
      { key:'faq_xhei_benkyoukai', faq:1, grp:'hei', q:"社長から、社員向けのお金の勉強会を頼まれた", re:/(社員|従業員|スタッフ|職場)[^。]{0,8}(向け|に向けた|のため|で)[^。]{0,4}(の)?(お金|保険|年金|ライフプラン|家計|老後)[^。]{0,4}(の)?(勉強会|セミナー|説明会|講座)|(社長|経営者|お客様の会社|法人)[^。]{0,12}(社員|従業員)[^。]{0,8}(勉強会|セミナー|説明会)/, ng:/部下|後輩|新人|メンバー|自分の会社|うちの会社|うちの代理店|社内の|記録|台帳|集客|集まらな|申込|その場で/, head:"中身は暮らしのお金の一般的な仕組みにして、その場では勧めず、個別の相談は希望する方だけにします。", body:"会社の中の勉強会は、社員にとって断りにくい場です。社長の了承のもとで、公的な保障の仕組みや家計の考え方など、一般的な知識を伝える場にします。その場で保険を勧めたり、申込書を配ったりはしません。個別の相談は、希望する方が後日申し込める形にし、勤務時間の扱いは会社と決めておきます。相談の中身は社長にも伝えません。", acts:["社長と、勉強会の目的・時間・扱わないこと（その場の勧誘）を先に決める", "資料は、公的な制度の仕組みと家計の考え方を中心に一般的な内容で作る", "個別の相談の受け方と、相談の中身を会社に伝えないことを、社員に先に伝える"], actHead:"現場で使うなら", note:"勉強会で使う資料の扱いと、職場で募集するときの決まりは、所属保険会社の募集資料の決まりと御社のコンプライアンスの手順で確かめる。勤務時間の扱いは会社の規程で確かめる。", say:"今日は保険のご案内ではなく、暮らしのお金の仕組みのお話です。ご相談をご希望の方は、後日個別に伺います。ご相談の内容は会社にはお伝えしません。", more:"場面の例は、社長が社員の老後の暮らしを気にして、年金の仕組みを話してほしいと頼んできた会社です。このときは、公的年金の仕組みと、見込み額を確かめる方法までを伝え、一人ひとりの判断は個別の相談に回します。よくある失敗は、勉強会の終わりに保険の案内を配り、社員が会社に勧められたと受け取ることです。", why:"職場の勉強会は社長の名前で開かれるので、社員は会社の勧めとして受け取りやすいためです。勧めない場にすると、社員は安心して聞け、社長の福利厚生としての思いも伝わります。" },
      { key:'faq_xhei_shokuiki', faq:1, grp:'hei', q:"法人のお客様の社員の方から、個人の保険の相談を受けてもいい？", re:/(会社|法人|職場|社長の会社|取引先)の?[^。]{0,8}(社員|従業員|スタッフ)[^。]{0,8}(から|の)[^。]{0,8}(個人の)?(保険|家計|お金)[^。]{0,4}の?(相談|見直し)|職場で[^。]{0,8}(社員|従業員)の?[^。]{0,4}(個人の)?(保険|家計)[^。]{0,4}の?相談/, ng:/部下|後輩|新人|メンバー|自分の会社|うちの会社|うちの代理店|わが社|社内の|団体保険|グループ保険|勉強会|セミナー|説明会|健康保険|厚生年金|扶養|有給/, head:"受けられます。職場で伺うなら社長の了承を取り、中身は会社に伝えないと約束します。", body:"法人のお客様の社員の方は、社長とつながりのある担当に相談することに、気を遣うことがあります。職場に伺って相談を受けるなら、社長の了承と、時間や場所の扱いを会社と決めます。相談の中身や契約の有無は、社員ご本人の同意なしに社長や会社へ伝えません。社長の会社との関係を理由に、社員の方に契約をお願いすることもしません。", acts:["職場で相談を受けてよいか、時間と場所の扱いを社長と決める", "社員の方に、相談の中身を会社に伝えないことを最初に伝える", "相談の記録は、会社の契約の記録と分けて残す"], actHead:"現場で使うなら", note:"職場での募集の扱いと、相談の記録の残し方は、所属保険会社の募集の決まりと御社のコンプライアンスと個人情報の扱いの手順で確かめる。", say:"ご相談の内容は、会社や社長にお伝えすることはありません。ご本人とご家族のための相談として伺いますので、気になることをそのままお話しください。", more:"場面の例は、社長から、社員の保険の相談にも乗ってやってほしいと言われた会社です。このときも、相談するかどうかは社員の方ご本人が決めることで、社長からの指示で相談の場を作ると、社員は断りにくくなります。よくある勘違いは、社長の紹介だから話が早いと考えることです。", why:"社員の方は、会社に家計や健康のことを知られるのを心配するためです。中身を会社に伝えない約束があると、安心して相談でき、社長の会社との関係も守られます。" },
      { key:'faq_xhei_hikitsugi_houjin', faq:1, grp:'hei', q:"法人のお客様を前任から引き継いだ。最初に何をする？", re:/(法人の(お客様|契約)|会社の契約|法人契約)[^。]{0,10}(引き継|引継|受け持)|(担当替え|担当交代|前任|前の担当)[^。]{0,10}(法人|会社)|引き継いだ(法人|会社)の(社長|経営者)/, ng:/部下|後輩|新人|メンバー|m&a|承継|継ぐ|継がせ|事業を引き継|会社を引き継|自社株|株を|株式を|買収|譲り|代理店から|ほかの代理店|他の代理店|保険会社の担当/, head:"社長と窓口の方にあいさつし、契約の一覧・規程・決算月・顧問の先生を確かめ直します。", body:"法人の引継ぎでは、社長のほかに、経理や総務の窓口の方、顧問の税理士の先生との関係も一緒に引き継ぎます。前任の記録から、契約ごとの役目と受取人、退職金や弔慰金の規程とのつながり、決算月、前任が約束していたことを書き出し、あいさつのときに社長と窓口の方に間違いが無いかを確かめていただきます。", acts:["前任の記録から、契約ごとの役目・受取人・保険料・満期を一覧にする", "社長と窓口の方へのあいさつで、前任が約束していたことが残っていないかを伺う", "顧問の先生にも、担当が替わったことを社長の了承を得て伝える"], actHead:"現場で使うなら", note:"担当の替わり方の手続きと記録は、所属保険会社の決まりと御社の手順で確かめる。経理と税の扱いは顧問の税理士の領分。", say:"このたび担当を引き継ぎました。前の担当からの記録を一覧にしてきましたので、間違いが無いか、またお約束していたことが残っていないかを確かめさせてください。", more:"よくある失敗は、社長にだけあいさつして、手続きを担っている窓口の方や顧問の先生に知らせないことです。窓口の方が前の担当に連絡し続け、手続きが止まることがあります。前任が口頭で約束していたこと（見直しの時期や資料の送付）は記録に残っていないことがあるので、あいさつのときに必ず伺います。", why:"法人の契約は、社長・窓口・顧問の先生の三者の間で動いていて、担当の交代はその全員の段取りに関わるためです。最初に確かめ直す担当は、前任との違いを不安に思わせません。" },
      { key:'faq_xhei_kiridashi_taishoku', faq:1, grp:'hei', q:"社長の退職金の話を、どう切り出す？", re:/(社長|経営者|役員)(の|に)?[^。]{0,4}(退職金|退職慰労金|引退|退職の時期|退任|勇退)[^。]{0,12}(切り出|持ち出|きっかけ|伺えば|聞けば|どう聞|どう伺|話をする|話の入)/, ng:/部下|後輩|自分の|私の|社員の|従業員の|いくら|税金|税は|受け取り方|年金で受|一時金|規程|規定/, head:"退職金の額より先に、社長がいつ・どんな形で会社を離れたいかを伺うところから入ります。", body:"退職金の話は、社長にとって会社を離れる日の話で、急に持ち出されると、まだ先の話だと流されがちです。先に、いつごろまで今の仕事を続けたいか、そのあとはどう過ごしたいか、会社に残る形か離れる形かを伺います。時期と形が見えると、いつ・何のお金から払うかの準備の話に自然に進めます。", acts:["社長が今の仕事をいつごろまで続けたいかと、そのあとの過ごし方を伺う", "会社に残る形か、離れる形かを、決めていなくてよい前提で伺う", "退職金の規程があるかを確かめ、準備の話は顧問の先生と一緒に進めると伝える"], actHead:"現場で使うなら", note:"役員退職金の額や支給の扱い、税は顧問の税理士の領分。規程の整え方は顧問の税理士と確かめ、会社の決め方の手続きが問題になる場面は弁護士に確かめる。", say:"社長は、いつごろまで今のお仕事を続けたいとお考えですか。お決めになっていなくても構いません。そのあとの過ごし方を伺えると、準備の話がしやすくなります。", more:"場面の例は、社長がまだ現役で働くつもりで、退職の話に乗ってこない会社です。このときは退職金ではなく、社長がいつか会社を離れるときに、会社と家族のお金がどう分かれるかという整理として話します。よくある勘違いは、退職金を税の話から始めることで、税の扱いは顧問の先生の領分です。", why:"退職金は、社長の人生の区切りと会社のお金の両方に関わる話で、本人の思いが決まらないと準備の形も決まらないためです。時期と形を先に伺うと、社長は自分の将来の相談として話せます。" },
      { key:'faq_xhei_houmon_hindo', faq:1, grp:'hei', q:"法人のお客様には、どのくらいの間隔で伺えばいい？", re:/^(?=.*(法人|会社|社長|経営者))(?=.*(訪問|伺う|伺え|伺い|顔を出|会いに|訪ね))(?=.*(頻度|間隔|ペース|何か月おき|月に何度|年に何度))/, ng:/部下|後輩|新人|メンバー|上司|1on1|介護|看護|診療|会社員|自分の会社|うちの会社|うちの代理店/, head:"決まった回数より、会社の一年の節目に合わせて伺う時期を、社長と先に決めます。", body:"法人のお客様には、決算・役員の改選・社員の入れ替わり・借入の見直しなど、一年の中で備えが変わる節目があります。決算のあとの振り返りを毎年の軸にし、年の途中にもう一度、変化を確かめる場を置き、節目の変化があれば伺う、と社長と決めておくと、どの訪問にも用件ができます。大事なのは回数より、伺うたびに前回からの変化を確かめることです。", acts:["決算のあとの振り返りの面談を、毎年の予定として社長と決めておく", "役員・社員・借入・事業の変化があったら知らせていただくようお願いする", "伺うたびに、前回からの変化を一枚に書き足して残す"], actHead:"現場で使うなら", note:"訪問の記録の残し方と、既契約のお客様への連絡の決まりは、御社の手順と所属保険会社の決まりで確かめる。", say:"毎年、決算が終わったころに一度、会社の一年の変化を伺いにまいります。役員や社員の入れ替わり、借入の見直しがあったときも、お声がけいただければ伺います。", more:"場面の例は、契約のあと、更新の書類のときにしか会っていない会社です。そのあいだに役員が替わり、受取人や被保険者が今の会社に合わなくなっていることがあります。よくある勘違いは、顔を出す回数が多いほど信頼されると考えることで、用件のない訪問は社長の時間を使うだけになります。", why:"会社の備えは、役員や社員、借入の変化で、少しずつ合わなくなっていくためです。節目に合わせて伺う担当は、社長にとって会社の変化を一緒に見てくれる人になり、変化があったときに思い出してもらえます。" },
      { key:'faq_xhei_zeirishi_naisho', faq:1, grp:'hei', q:"社長に「顧問の税理士には内緒で」と言われた", re:/(税理士|顧問の先生|会計事務所)[^。]{0,8}(内緒|知られ(ない|たくない|ずに)|言わないで|言わずに|黙って|通さず|通さない|知らせず|知らせない|話さないで|話さずに|抜きで|飛ばして)/, ng:/部下|後輩|自分の|私の|うちの代理店|わが社|家族に|妻に|夫に|奥様に|ご主人に|確定申告|申告書/, head:"顧問の先生を外したい理由を伺い、会社の保険には先生の確認が要ることを正直に伝えます。", body:"社長が顧問の税理士に知られたくないと言うのは、前に保険の話を止められた、お金の使い方を言われたくない、などの事情があることが多いです。けれども会社で払う保険料は帳簿に載り、決算や申告の中で顧問の先生の目に触れることになるので、先生が知らないまま進めると、あとで社長が困ります。理由を伺い、先生に伝える時期と見せる資料を、社長と一緒に決めます。", acts:["顧問の先生に知られたくない理由を、責めずに伺う", "会社で払う保険料の経理と税の扱いは、先生の確認が要ることを伝える", "先生に伝える時期と見せる資料を、社長と一緒に決める"], actHead:"現場で使うなら", note:"保険料の経理と税の扱いは顧問の税理士の領分で、こちらから言い切らない。社長とのやりとりと説明の記録は、御社のコンプライアンスの手順で確かめる。", say:"会社でお支払いになる保険料は帳簿に載りますので、経理と税の扱いは顧問の先生のご確認が要ります。先生にお伝えする時期と中身を、社長と一緒に決めさせてください。", more:"場面の例は、前に顧問の先生に保険の提案を止められ、今度は先生を通さずに決めたいと話す社長です。このときは、先生が何を心配して止めたのかを伺うと、資金繰りや契約の形の問題が見えることがあります。よくある失敗は、社長の言うとおりに先生を外して進め、決算のときに社長と先生の間で行き違いが生まれることです。", why:"顧問の先生は会社のお金の流れ全体を見ている方で、知らないところで動いたお金があると、社長と先生の信頼が揺らぐためです。先生を外さない担当は、社長にとっても先生にとっても、安心して話せる相手になります。" },
      { key:'faq_xhei_hoken_misete', faq:1, grp:'hei', q:"社長に、会社の保険証券を見せてもらうには？", re:/(会社|法人|社長)[^。]{0,12}(保険証券|証券)[^。]{0,8}(見せて|見せたがらな|出して|拝見|お借り|預か)/, ng:/部下|後輩|新人|メンバー|再発行|なくし|無くし|紛失|見方|読み方|どこを見|何から|証券会社|有価証券|自分の|私の/, head:"何のために見るかを先に伝え、契約を変える話ではないと添えてお願いします。", body:"社長が会社の保険証券を見せたがらないのは、今の担当への遠慮や、乗り換えを勧められるのではという心配があることが多いからです。会社の保険の役目と受取人が、今の会社の状態に合っているかを確かめるために拝見したい、と目的を先に伝えます。拝見したら、分かったことを一枚にまとめてお返しし、気になる点は今の担当に相談されるよう伝えます。", acts:["見せていただく前に、何を確かめるために拝見するのかを一言で伝える", "その場で拝見するだけにするか、写しを預かってよいかを社長に伺う", "拝見したあと、分かったことを一枚にまとめて社長にお返しする"], actHead:"現場で使うなら", note:"証券の写しを取るときの扱いと保管は、御社の個人情報と機密の扱いの手順で確かめる。今の契約を見直すときの説明は、所属保険会社の決まりに沿う。", say:"会社でお入りの保険が、今の会社の状態に合っているかを確かめるために、証券を拝見できますか。ご契約を変えるお話ではありません。分かったことは一枚にまとめてお返しします。", more:"場面の例は、長く付き合っている代理店の担当がいて、その契約を見せると角が立つと考えている社長です。このときは、今の担当を否定しないことを先に約束し、見るのは役目と受取人だけでも構いませんと伝えます。よくある失敗は、拝見した場で他社の契約の弱いところを指摘し、社長の判断を否定してしまうことです。", why:"会社の保険証券には、会社が誰のために何に備えているかが書いてあり、社長にとっては見せる相手を選ぶものだからです。目的と扱いが分かると、社長は安心して見せられ、見せたあとも役に立ったと感じられます。" },
      { key:'faq_xhei_doseki', faq:1, grp:'hei', q:"社長との面談に、奥様や経理の方が同席した", re:/^(?=.*(社長|経営者|法人|会社))(?=.*(同席|一緒に(出て|話を聞|聞|座|来)|同じ席))(?=.*(奥様|奥さん|専務|常務|経理|総務|役員|番頭))/, ng:/部下|後輩|新人|メンバー|上司|先輩|同行|高齢|ご高齢|年配|認知|口を挟|話を遮|反対意見|勉強会|セミナー|説明会|役員会|取締役会/, head:"同席の方の役目を先に伺い、社長の個人の話はその場で出してよいかを確かめます。", body:"小さな会社では、社長の奥様が役員や経理を担い、手続きや支払いの実務を回していることがあります。最初に同席の方の役目と、決めるときに誰の考えを聞くかを伺い、説明は社長だけでなく同席の方にも向けます。社長ご本人の健康やご家族のこと、個人の保険の話は、同席の方の前で話してよいかを社長に先に確かめます。", acts:["同席の方の役目と、決めるときに誰の考えを聞くかを最初に伺う", "資料は同席の方の分も用意し、説明は社長と同席の方の両方に向ける", "社長の健康や個人の保険の話は、同席の方の前で話してよいかを先に伺う"], actHead:"現場で使うなら", note:"同席の方に伝えてよい情報の範囲は、社長の了承と御社の個人情報の扱いの手順で確かめる。手続きの書類の扱いは所属保険会社の決まりに沿う。", say:"本日はご同席いただきありがとうございます。差し支えなければ、会社でのご担当の役目を伺えますか。資料は皆様の分をご用意しましたので、気になる点はご遠慮なくお尋ねください。", more:"場面の例は、社長が話す横で、経理をしている奥様が保険料の負担を気にしている会社です。このときは、奥様の質問に丁寧に答えることが、社長の判断を助けます。よくある失敗は、社長だけを見て話し、実務を担う方を置き去りにすることです。手続きの段取りは、実務を担う方と決めます。", why:"法人の判断は社長が下しても、手続きや支払いを回すのは同席の方であることが多いためです。同席の方にも分かる説明をする担当は、会社全体から信頼される相手になります。" },
      { key:'faq_xhei_kiroku_houjin', faq:1, grp:'hei', q:"法人のお客様との面談の記録には、何を残す？", re:/(法人|会社|社長|経営者)[^。]{0,10}(面談|打ち合わせ|打合せ|商談|訪問)[^。]{0,10}(記録|書き残)[^。]{0,10}(残す|何を|書く|書け|書いて|気をつけ|注意|どう)/, ng:/部下|後輩|新人|メンバー|意向|比較推奨|苦情|送付|保全|告知|健康|病気|録音|バックアップ|議事録|メモを取|自分の会社|うちの会社|うちの代理店/, head:"誰が同席し、誰が何を決め、次に誰が何を確かめるかを、その日のうちに残します。", body:"法人では、社長・役員・経理の方など複数の人が関わり、決めることも社内の手続きを経ることがあります。面談の記録には、日時と場所、同席した方の名前と役目、伺った会社の変化、決まったことと決まっていないこと、こちらが約束したこと、次に確かめる人と時期を書きます。決算書から伺った数字は、記録に写す範囲を決め、御社の決まりに沿って扱います。", acts:["同席した方の名前と役目、決める人が誰かを、面談の日のうちに書く", "こちらが約束したことと、先方が確かめることを分けて書く", "決算書の数字は写す範囲を決め、記録の置き場所を御社の決まりに合わせる"], actHead:"現場で使うなら", note:"面談の記録の残し方と保管、会社の情報の扱いは、御社のコンプライアンスと個人情報の扱いの手順、所属保険会社の決まりで確かめる。", say:"本日伺ったことと、次にこちらで確かめることを、まとめてお送りします。間違いや足りないところがあれば、お知らせください。", more:"場面の例は、社長は前向きだったのに、経理の方の確認が要るとあとで分かった面談です。記録に、誰が何を確かめるかを書いておけば、次の連絡の相手を間違えません。よくある失敗は、社長の言葉だけを書き、同席の方の心配を書き落とすことです。担当が替わったときも、記録があれば会社との約束が引き継げます。", why:"法人の話は、関わる人と手続きが多く、何か月かにわたって進むことがあるためです。誰が何を決めたかが残っていると、会社とのやりとりの食い違いを防げ、あとで経緯を確かめるときにも役立ちます。" },
      { key:'faq_xhei_shacho_koutai', faq:1, grp:'hei', q:"担当している会社の社長が交代した。何を確かめる？", re:/(会社|法人)[^。]{0,10}(社長|代表者|代表取締役)(が|の)?[^。]{0,7}(交代|交替|替わ)|(会社|法人)[^。]{0,10}(社長|代表者)が(代わっ|変わっ)/, ng:/部下|後輩|自分の|私の|うちの代理店|わが社|取引先に|金融機関|銀行|公表|発表|自社株|株を|株式を|相続|担当者|担当の方|窓口/, head:"新しい社長にあいさつし、契約ごとの被保険者・受取人・役目が今の会社に合うかを確かめます。", body:"社長が替わると、前の社長が会長として残ったり、役員を退いたりして、会社の保険の被保険者や受取人の役目が今の会社に合わなくなることがあります。新しい社長には、会社の保険の一覧とそれぞれの役目を説明し、前の社長の契約を続けるか、役目を変えるかを、顧問の税理士の確認と合わせて判断していただきます。前の社長にも、これまでのお礼を伝えます。", acts:["新しい社長に、会社の保険の一覧とそれぞれの役目を説明する", "前の社長が被保険者の契約を、続けるか役目を変えるかを新しい社長に伺う", "前の社長の退職金と保険のつながりは、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"契約者や受取人の変更、被保険者を替えられるかどうかは所属保険会社の約款と手続き、退職金と税の扱いは顧問の税理士、役員の変更の登記は司法書士の領分で確かめる。", say:"このたびは社長へのご就任、おめでとうございます。会社でお入りの保険の一覧と、それぞれの役目をご説明させてください。前の社長のご契約をどうするかは、顧問の先生と一緒に考えましょう。", more:"場面の例は、前の社長が会長として残り、新しい社長が会社の判断をする会社です。このとき、前の社長を被保険者にした契約が、事業の保障の役目から、退職の準備の役目に変わっていることがあります。よくある失敗は、新しい社長へのあいさつを後回しにして、前の社長とだけ話し続けることです。", why:"会社の保険の役目は、誰が会社を動かしているかで変わるためです。代替わりのときに備えを一緒に確かめる担当は、新しい社長にとっても頼れる相談相手になります。" },
      { key:'faq_xhei_akaji_kaisha', faq:1, grp:'hei', q:"赤字の会社の社長に、保険の話をしてもいい？", re:/赤字[^。]{0,12}(会社|法人|社長|経営者)[^。]{0,16}(保険|提案|備え|話し方|話を)|(会社|法人)[^。]{0,6}(が)?赤字[^。]{0,16}(保険|提案|備え|話し方|話を)/, ng:/部下|後輩|自分の|私の|うちの代理店|わが社|家計|個人事業|欠損金|繰越|法人税|損益分岐|どころ|余裕がな|お金がな|払えな|無理|断ら|言われ/, head:"話してよいです。ただし保険料が資金繰りを苦しくしないかを先に確かめ、税の効果では勧めません。", body:"赤字の会社でも、社長に万一があったときの借入の返済や、社員の給料の支払いへの備えが要ることはあります。けれども保険料は毎年の資金繰りから出ていくので、まず手元のお金と借入の返済の予定を伺い、保険料を払い続けられるかを社長と一緒に確かめます。税の扱いを理由に勧めることはせず、税のことは顧問の税理士に確かめていただきます。", acts:["手元のお金と借入の返済の予定を伺い、保険料を払い続けられるかを確かめる", "今ある保険の役目と保険料を一覧にし、重なりがないかを先に見る", "税の扱いは顧問の税理士に確かめていただき、こちらからは言い切らない"], actHead:"現場で使うなら", note:"保険料の経理と税の扱いは顧問の税理士、資金繰りと借入は社長と金融機関の領分。商品の説明は所属保険会社の資料と募集の決まりに沿う。", say:"会社に万一のことがあったときの備えは、業績の良し悪しに関わらず要ることがあります。まずは手元のお金と返済のご予定を伺い、無理のない形かどうかを一緒に確かめさせてください。", more:"場面の例は、一時的な赤字で、社長が借入の返済を気にしている会社です。このときは新しい保険より先に、今の保険の役目と保険料を見直し、借入の返済の備えに足りているかを確かめます。よくある失敗は、利益が出ていない会社に、税の効果を前に出して勧めることで、社長の資金繰りを苦しくします。", why:"赤字の会社の社長は、出ていくお金に人一倍気を配っているためです。資金繰りを先に一緒に確かめる担当は、売り込む人ではなく、会社を守る相談相手として受け止められます。" },
      /* hkk.json */
      { key:'faq_xhkk_sonekibunki', faq:1, grp:'hkk', q:"損益分岐点とは？", re:/損益分岐|(固定費)と(変動費)|(変動費)と(固定費)|(いくら|どれだけ|どこまで)(売れば|売り上げれば|売上があれば)[^。]{0,10}(赤字|黒字|利益)/, ng:/年金|繰下げ|繰上げ/, head:"損益分岐点は、売上と費用がちょうど同じになり、利益がゼロになる売上の点です。", body:"費用は、売上に関係なくかかる固定費（家賃・人件費・借入の利息・保険料など）と、売上に応じて増える変動費（仕入れ・外注など）に分けて考えます。売上から変動費を引いた残りで固定費をまかなえる点が損益分岐点で、これを超えた分が利益になります。", acts:["社長に、毎月必ず出ていく固定費の中身を書き出していただく", "社長に万一があり売上が落ちたとき、固定費をどれだけの間まかなえるかを一緒に考える", "費用の分け方と計算は、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"固定費と変動費の分け方は会社の会計の方針で違う。計算と数字の解釈は顧問の税理士、事業の計画は社長と専門家で確かめる。", say:"毎月どうしても出ていくお金と、売上に応じて増えるお金を分けて見ると、会社が持ちこたえられる線が見えてきます。一緒に書き出してみませんか。", more:"よくある勘違いは、売上が増えれば利益も同じように増えると考えることです。固定費の大きい会社は、損益分岐点を超えると利益が増えやすい一方、売上が少し落ちただけで赤字になりやすくなります。社長が営業の中心の会社では、社長に万一があったときに売上がこの線を下回る間の固定費が、備えの話の土台になります。", why:"固定費は売上が落ちても減らないため、売上がどこまで下がると赤字になるかを知っておくと、会社の持ちこたえる力をつかめるからです。事業保障の話も、この固定費をまかなう考え方から始まります。" },
      { key:'faq_xhkk_rieki_shurui', faq:1, grp:'hkk', q:"粗利・営業利益・経常利益の違いは？", re:/(粗利|売上総利益|営業利益|経常利益|当期純利益|税引前当期純利益)[^。]{0,16}(違い|違う|とは|って何|の意味|順番|種類)|利益の(種類|段階)/, head:"利益は、売上から何を差し引いたかで、売上総利益・営業利益・経常利益・当期純利益と段階が分かれます。", body:"売上から仕入れなどの原価を引いたものが売上総利益（粗利）、そこから人件費や家賃などの販売費及び一般管理費を引いたものが本業のもうけを表す営業利益です。借入の利息など本業の外の収入と費用を足し引きしたものが経常利益、臨時の利益や損失と税を差し引いた残りが当期純利益です。", acts:["数年分の損益計算書を並べ、どの段階の利益が動いているかを社長と一緒に見る", "本業のもうけ（営業利益）と、臨時の出来事を分けて伺う", "保険の解約などで受け取ったお金がどこに載っているかは、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"どの収入や費用をどの段階に載せるかは、会社の会計の処理による。数字の解釈と処理は顧問の税理士に確かめる。", say:"利益にはいくつか段階があり、本業でどれだけもうけているかと、臨時の出来事を分けて見ると、会社の調子がつかみやすくなります。", more:"よくある勘違いは、当期純利益だけで会社の調子を見ることです。例えば、建物を売った年は臨時の利益で当期純利益が大きく見えても、営業利益は落ちていることがあります。法人の保険を解約して受け取ったお金も、本業のもうけとは別の段階に載ることが多いので、本業の力と混ぜて見ないようにします。", why:"利益を段階に分けるのは、本業の力、借入などお金の集め方の影響、その年だけの出来事を分けて見られるようにするためです。どこで利益が減っているかが分かると、社長が気にしていることの中身が見えます。" },
      { key:'faq_xhkk_jikoshihon', faq:1, grp:'hkk', q:"自己資本比率とは？", re:/自己資本比率|自己資本(の)?割合/, head:"自己資本比率は、会社の資産のうち、返す必要のない純資産でまかなっている割合です。", body:"貸借対照表の純資産を、資産の合計で割って求めます。高いほど借入などの返す必要のあるお金に頼らずに会社を回していることになり、低いと借入への頼り方が大きいことを表します。目安は業種によって違うので、同じ会社の数年分の動きで見ます。", acts:["数年分の決算書で、純資産と資産の合計の動きを社長と一緒に見る", "高い・低いと評価せず、借入をどう考えているかを社長に伺う", "目安と見方は、顧問の税理士や取引の金融機関に確かめていただく"], actHead:"現場で使うなら", note:"業種ごとの目安と金融機関の見方は、顧問の税理士と取引の金融機関で確かめる。こちらでは会社の良し悪しを言い切らない。", say:"会社の持ち物のうち、返さなくてよいお金でまかなっている割合を見ると、借入への頼り方が分かります。数年分を並べて見てみませんか。", more:"よくある勘違いは、自己資本比率が高ければ手元のお金も多いと考えることです。純資産が厚くても、その分が設備や売掛金に変わっていて、現預金は少ないことがあります。資産に計上した保険の積立金も資産に含まれるので、帳簿の額と解約したときに戻る額が違うことも合わせて見ます。", why:"返す必要のあるお金に頼る割合が大きいほど、売上が落ちたときや借入の条件が変わったときの影響を受けやすいからです。金融機関もこの割合を、会社の持ちこたえる力を見る手がかりの一つにしています。" },
      { key:'faq_xhkk_ryudou', faq:1, grp:'hkk', q:"流動比率とは？", re:/流動比率|当座比率|(流動資産)と(流動負債)|(流動負債)と(流動資産)/, head:"流動比率は、近いうちに払うお金に対して、近いうちにお金になる資産がどれだけあるかを表します。", body:"貸借対照表の流動資産（現預金・売掛金・在庫など、決算の日から次の一年の間にお金になる予定の資産）を、流動負債（買掛金・短期の借入など、同じ間に払う予定の負債）で割って求めます。近いうちの支払いに困らないかを見る手がかりで、より手堅く見るときは在庫を除いた当座比率を使います。", acts:["流動資産の中身（現預金・売掛金・在庫）の割合を社長と一緒に見る", "在庫や売掛金がすぐにお金になるかを、社長の言葉で伺う", "見方と目安は、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"比率の目安は業種と会社の事情で違う。数字の解釈は顧問の税理士、借入の判断の見方は取引の金融機関で確かめる。", say:"近いうちに払うお金と、近いうちに入ってくるお金を並べると、資金繰りの余裕が見えてきます。一緒に確かめてみませんか。", more:"よくある勘違いは、流動比率が高ければ安心と考えることです。売れ残りの在庫や回収の遅れている売掛金が多いと、比率は高く見えても手元のお金は足りないことがあります。だから、中身の現預金がどれだけあるかを合わせて見ます。", why:"会社が立ち行かなくなるのは、払うべきお金が手元に無くなったときだからです。近いうちの支払いと、近いうちに入るお金の釣り合いを見ると、その心配の度合いをつかめます。" },
      { key:'faq_xhkk_tsumitatekin', faq:1, grp:'hkk', q:"決算書の保険積立金とは？", re:/保険(料)?積立金|(積立金|資産計上額)[^。]{0,10}(解約返戻金|返戻金)[^。]{0,8}(同じ|違|差)/, head:"保険積立金は、法人の保険料のうち資産として計上した分が、貸借対照表に積み上がったものです。", body:"法人の保険料は、契約の形によって、全てを費用にするもの、一部を資産に計上するもの、全てを資産に計上するものがあります。資産に計上した分が保険積立金などの名前で載ります。これは帳簿の上の額で、今解約したときに戻る解約返戻金の額とは、多くの場合違います。", acts:["決算書の保険積立金の額と、保険会社が出す解約返戻金の額を並べて見る", "どの契約の分がいくら積み上がっているかを、顧問の税理士の資料と照らす", "解約したときの扱いは、こちらで言い切らず顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"資産に計上する割合と解約したときの処理は、契約の形と時期で違う。経理の扱いは顧問の税理士、解約返戻金の額は保険会社で確かめる。", say:"決算書に載っている保険の積立金と、今解約したときに戻る額は同じではありません。保険会社の資料と並べて確かめてみましょう。", more:"よくある勘違いは、保険積立金の額がそのまま手元のお金として使えると考えることです。解約すると、戻る額と帳簿の額の差が会社の収入や損失として扱われます。金融機関も、帳簿の額と実際に戻る額が違うことを踏まえて見ることがあるので、解約返戻金の推移表を手元に置いておきます。", why:"保険料のうち将来戻る見込みのある部分を、払った年の費用にせず資産として持っておくのが会計の考え方だからです。ただ帳簿の額は払った保険料の積み上げで、戻る額は保険会社の計算で決まるので、二つはずれます。" },
      { key:'faq_xhkk_yakuin_kariire', faq:1, grp:'hkk', q:"役員借入金とは？", re:/役員(から(の)?)?借入金|(社長|代表|経営者|役員)(から(の)?)?(借入金|借り入れ)[^。]{0,10}(とは|どうな|相続|見方|扱い|何を)|(社長|代表|経営者)が(会社|法人)に(貸し|貸付|お金を貸)/, head:"役員借入金は、社長などの役員が会社に貸しているお金で、社長個人から見ると財産の一つです。", body:"会社にとっては返す必要のある負債ですが、社長個人にとっては会社に返してもらう権利（貸付金）で、社長が亡くなると相続の財産になります。会社に返す力が無くても財産として数えられることがあり、相続の場面でご家族が困ることがあります。", acts:["決算書で役員借入金の額と、数年分の動きを社長と一緒に見る", "このお金を今後どうするつもりかを、社長に伺う", "相続での扱いと手当ての方法は、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"相続での評価と、返してもらう・放棄する・資本に替えるといった手当ては、どれも税が関わる。判断は顧問の税理士、法律の扱いは弁護士で確かめる。", say:"社長が会社に貸しているお金は、社長の財産として相続の場面にも出てきます。今後の扱いを、顧問の先生と一緒に考えておきませんか。", more:"場面の例としては、創業のころから社長が会社の資金を何度も立て替えてきて、決算書の役員借入金が大きくなっている会社です。よくある勘違いは、会社の中のお金なので相続には関係ないと考えることです。手当ての方法はいくつかありますが、どれも会社と社長個人の両方に税が関わるので、こちらで勧めずに顧問の税理士につなぎます。", why:"お金を貸した人は返してもらう権利を持ち、その権利も預金と同じく財産として相続の対象になるからです。会社が返せるかどうかとは別に数えられることがあるので、早めに整理しておく意味があります。" },
      { key:'faq_xhkk_yakuin_kashitsuke', faq:1, grp:'hkk', q:"役員貸付金とは？", re:/役員(への)?貸付金|(社長|代表|経営者|役員)(への|に対する)貸付金|(会社|法人)が(社長|代表|経営者|役員)に(貸し|貸付|お金を貸)/, head:"役員貸付金は、会社が社長などの役員に貸しているお金で、金融機関から厳しく見られることがあります。", body:"会社にとっては返してもらう権利なので資産に載りますが、事業に使われていないお金で、返ってくるかも分かりにくいと見られやすい科目です。会社のお金と社長個人のお金の区別がついていないと受け取られることもあり、利息の扱いなど税の面でも確かめることが出てきます。", acts:["決算書に役員貸付金があるか、どのくらいの間残っているかを社長と一緒に見る", "責める言い方をせず、貸付になった事情を社長に伺う", "返し方や利息の扱いは、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"利息の扱いと税の処理は顧問の税理士、金融機関の見方は取引の金融機関で確かめる。こちらから返し方を決めない。", say:"会社から社長への貸付は、金融機関から理由を聞かれることがある科目です。どういう事情で残っているかを、顧問の先生と整理しておきませんか。", more:"よくある勘違いは、資産に載っているので会社にとって安心な数字だと考えることです。金融機関は、回収の見込みが分からない資産として割り引いて見ることがあります。社長個人の保険料を会社の口座から払っていて貸付になっている形もあるので、保険の契約の形と支払いの口座も合わせて確かめます。", why:"会社のお金は事業のために使うもので、役員個人に貸したままのお金は事業の役に立たず、返ってこないおそれもあると見られるからです。会社と社長個人のお金を分けているかは、経営者保証の考え方でも見られる点です。" },
      { key:'faq_xhkk_shisanhyou', faq:1, grp:'hkk', q:"試算表とは？", re:/試算表[^。]{0,12}(とは|って何|の意味|何に使|見方|違い|違う|意味|使い方|見せて)|月次(の)?(試算表|決算)/, head:"試算表は、帳簿を月などの区切りで締めて作る、決算書と同じ形の途中の数字です。", body:"決算書は一年に一度ですが、試算表は月ごとなどに作るので、期の途中の売上・利益・手元のお金・借入の残りをつかめます。決算の見込みを早めに知る、金融機関に会社の様子を伝える、といった場面で使います。作るのは会社の経理か、顧問の税理士です。", acts:["社長の了承を得て、直近の試算表を前の期の同じ時期と並べて見る", "決算の見込みは試算表をもとに、顧問の税理士と一緒に確かめる", "お預かりした試算表は、社内の決まりに沿って扱い、社外に出さない"], actHead:"現場で使うなら", note:"試算表の数字は途中のもので、決算で直ることがある。数字の解釈は顧問の税理士、資料の扱いは社内の決まりで確かめる。", say:"期の途中の数字を試算表で見ておくと、決算の直前に慌てずに済みます。顧問の先生にも確かめながら、一緒に見ていきましょう。", more:"場面の例としては、決算の数か月前に試算表を見て、今期の利益の見込みと、次の期に予定している大きな支払いを並べる形です。よくある勘違いは、試算表の利益がそのまま決算の利益になると考えることで、決算では減価償却などの処理が入って数字が変わります。", why:"決算書だけを見ていると、会社の様子が分かるのが年に一度になり、気づくのが遅れるからです。途中の数字で早めに見通しを持つと、社長も顧問の税理士も、落ち着いて次の手を考えられます。" },
      { key:'faq_xhkk_kurikoshi', faq:1, grp:'hkk', q:"赤字の欠損金は翌年以降どうなる？", re:/欠損金|(赤字|損失)[^。]{0,10}(繰り越|繰越)|(赤字|損)の(年|期)[^。]{0,10}(次の年|翌年|翌期|来期|次の期)/, head:"会社の赤字（欠損金）は、決まった範囲で次の期以降に繰り越し、黒字の期の所得から差し引けます。", body:"法人税には、赤字の期の欠損金を次の期以降に持ち越して、黒字になった期の所得から差し引ける仕組みがあります。繰り越せる期間や、一年に差し引ける上限は、会社の規模などで決まりが違い、改正もあります。赤字が続いた会社の税の見通しは、この仕組みで変わります。", acts:["赤字の年が続いた会社では、税の見通しを顧問の税理士に確かめていただく", "保険の話は、税の都合ではなく保障の目的から始める", "欠損金の額と期限は、こちらで計算しない"], actHead:"現場で使うなら", note:"繰り越せる期間・差し引ける上限・会社の規模ごとの扱いは、国税庁の資料と顧問の税理士で最新のものを確かめる。", say:"赤字の年の損は、決まった範囲で次の年以降の税の計算に使える仕組みがあります。詳しい扱いは、顧問の先生に確かめていただくのが確かです。", more:"よくある勘違いは、黒字になった年はすぐに税がかかると考えることです。過去の欠損金が残っていれば、その分を差し引いて計算されます。法人の保険の話でも、欠損金がある会社では税の見通しが違うので、税の話を先に持ち出さず、保障の目的と保険料を払い続けられるかから話します。", why:"事業の成果は一年ごとに区切って計算しますが、赤字と黒字の年がある会社で、黒字の年だけに税がかかると負担が重くなるからです。期間をまたいで損と益をならす考え方として、この仕組みがあります。" },
      { key:'faq_xhkk_naibu_ryuho', faq:1, grp:'hkk', q:"内部留保とは？", re:/内部留保|利益剰余金/, head:"内部留保は、会社が利益から税と配当を差し引いて残してきた分の積み重ねで、お金そのものとは限りません。", body:"貸借対照表では、純資産の中の利益剰余金として表れます。ただ、残した利益は設備・売掛金・在庫などに形を変えていることが多く、同じ額の現預金があるわけではありません。会社がすぐに使えるお金は、現預金のほうで確かめます。", acts:["利益剰余金と現預金の額を並べ、差がどこに変わっているかを社長と一緒に見る", "社長が大丈夫と思っている理由を、言葉で伺う", "数字の解釈は、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"純資産の中身と数字の解釈は顧問の税理士、自社株の評価との関わりは税理士で確かめる。こちらでは会社の良し悪しを言い切らない。", say:"会社に残してきた利益と、今すぐ使えるお金は同じではありません。どこに形を変えているかを、一緒に確かめてみませんか。", more:"よくある勘違いは、内部留保が多ければ手元のお金も多いと考えることです。例えば、工場を建てた会社は利益剰余金が厚くても、現預金は借入の返済で減っていることがあります。利益を積み上げてきた会社は、自社株の評価が高くなっていることもあり、事業を継ぐ話にも関わります。", why:"会計では、利益は稼いだときに数え、そのお金を何に使ったかは別に記録するからです。残した利益の額と、それが今どんな形で会社にあるかは、分けて見る必要があります。" },
      { key:'faq_xhkk_shihonkin', faq:1, grp:'hkk', q:"資本金と純資産の違いは？", re:/(資本金)と(純資産)|(純資産)と(資本金)|資本金(が)?[^。]{0,8}(大きい|多い|少ない|小さい)[^。]{0,8}(安心|大丈夫|意味|会社)|資本金(とは|って何|の意味)/, head:"資本金は株主が出した元手の記録で、純資産は残してきた利益などを含む全体です。", body:"純資産は、資本金・資本剰余金・利益剰余金などから成ります。資本金が大きくても、赤字が続けば利益剰余金が減り、純資産が資本金を下回ることもあります。会社の持ちこたえる力は、資本金の額より、純資産と手元のお金の動きで見ます。", acts:["資本金・利益剰余金・純資産を、数年分並べて社長と一緒に見る", "資本金の額だけで会社を評価しない", "資本金を変える話は、顧問の税理士と司法書士に確かめていただく"], actHead:"現場で使うなら", note:"資本金の額で変わる税や手続きの扱いは顧問の税理士、資本金の変更の登記は司法書士で確かめる。", say:"資本金は会社を始めたときなどに出したお金の額で、今の会社の力は純資産と手元のお金の動きのほうでよく見えます。一緒に確かめてみましょう。", more:"よくある勘違いは、資本金が大きい会社ほどお金を持っていると考えることです。資本金は出したときの額の記録で、そのお金は既に設備や運転資金に使われていることがあります。資本金の額によって税や手続きの扱いが変わることもあるので、変える話は顧問の先生に任せます。", why:"資本金は株主が出したお金を会社が守るべき元手として記録したもので、その後の稼ぎや損は利益剰余金のほうに表れるからです。だから会社の今の姿は、純資産の全体で見ます。" },
      { key:'faq_xhkk_shikinguri_hyo', faq:1, grp:'hkk', q:"資金繰り表はどう作る？", re:/資金繰り表|資金(の)?予定表|(資金繰り)[^。]{0,6}(の)?(表|作り方|書き方)|お金の出入り(の)?表/, head:"資金繰り表は、月ごとに、繰り越したお金・入るお金・出るお金・次の月へ繰り越すお金を並べた表です。", body:"前の月から繰り越した現預金に、売上の入金などの入るお金を足し、仕入れ・給与・家賃・保険料・税などの出るお金を引きます。借入と返済は別の段に分けて書き、残りを次の月へ繰り越します。過ぎた月の実績と、これからの予定を並べて書くと、お金が足りなくなる月を前もってつかめます。", acts:["社長の了承を得て、今の資金繰り表があるか、作っているのは誰かを伺う", "保険料の払い方（月払・年払）を資金繰り表に入れて、負担の月を一緒に見る", "作り方と数字は、顧問の税理士や会社の経理の方に確かめていただく"], actHead:"現場で使うなら", note:"資金繰り表の形は会社と金融機関で違う。作り方と数字は顧問の税理士・会社の経理、借入の相談は取引の金融機関で確かめる。", say:"月ごとのお金の出入りを表にしておくと、足りなくなりそうな月が前もって見えます。保険料の払い方も、この表で負担の月を確かめてから決めましょう。", more:"よくある勘違いは、利益の予定と資金繰りの予定を同じものと考えることです。売上の入金が遅れる月、賞与や税をまとめて払う月、借入の返済が重なる月は、利益が出ていてもお金が減ります。法人の保険料を年払いにすると、その月だけ出るお金が大きくなるので、資金繰り表で確かめます。", why:"会社は赤字でなくても、払うときにお金が無ければ立ち行かなくなるからです。お金の出入りを月ごとに先回りして見ておくと、借入の相談や支払いの段取りを早めに打てます。" },
      { key:'faq_xhkk_temoto_meyasu', faq:1, grp:'hkk', q:"会社の手元資金はどれくらい持てばいい？", re:/(会社|法人|事業)[^。]{0,8}(手元資金|手元のお金|現預金|置いておくお金|持っておくお金)[^。]{0,12}(どれくらい|どのくらい|目安|いくら|何か月|十分|足り)|(手元資金|手元のお金)[^。]{0,6}(の)?目安[^。]{0,8}(会社|法人)/, ng:/生活費|家計|個人/, head:"会社の手元資金に決まった額は無く、毎月の固定費と、入金と支払いの時期のずれから考えます。", body:"家賃・給与・借入の返済など毎月必ず出るお金、売上が入るまでの期間、季節による売上の波、賞与や税をまとめて払う月を並べると、どれだけ手元に置けば支払いが止まらないかが見えてきます。月の売上の何か月分といった言い方もありますが、業種と会社の事情で違います。", acts:["資金繰り表で、お金がいちばん少なくなる月とその額を社長と一緒に見る", "社長に万一があったとき、売上が戻るまでの固定費を書き出す", "目安の考え方は、顧問の税理士や取引の金融機関に確かめていただく"], actHead:"現場で使うなら", note:"業種ごとの目安と借入の枠の考え方は、顧問の税理士と取引の金融機関で確かめる。こちらで額を言い切らない。", say:"手元に置くお金の正解の額はありませんが、毎月出ていくお金と入金の時期を並べると、会社に合った目安が見えてきます。一緒に整理してみませんか。", more:"場面の例としては、売上の入金が取引先から遅れて入る会社で、給与と仕入れの支払いが先に来る月です。よくある勘違いは、借入の枠があるので手元のお金は少なくてよいと考えることで、会社の状況が悪くなると枠が使えないこともあります。法人の保険の解約返戻金を当てにするなら、戻る額と手続きの時間も確かめます。", why:"会社は支払いが一度止まると、取引先や金融機関からの信用に響くからです。どれだけ置くかは、出ていくお金の大きさと、入るまでの間の長さで決まるので、会社ごとに違います。" },
      { key:'faq_xhkk_site', faq:1, grp:'hkk', q:"入金サイトと支払サイトとは？", re:/(入金|回収|支払い?|手形)サイト|サイトが(長|短)|売掛金[^。]{0,10}(入金まで|回収まで|入るまで)[^。]{0,8}(期間|大事|長|なぜ)/, head:"サイトは、売上や仕入れが決まってから実際にお金が動くまでの期間で、この差が資金繰りを左右します。", body:"売上を計上してから入金されるまでを回収サイト、仕入れてから支払うまでを支払サイトと呼びます。回収が支払いより遅いと、その間のお金を会社が手元で用意することになります。売上が増えるほど、この間に用意するお金も大きくなります。", acts:["主な取引先ごとの入金と支払いの時期を、社長に伺う", "回収と支払いの差の期間を、資金繰り表で一緒に確かめる", "取引の条件を変える話は、社長と取引先・金融機関の間のことなので、こちらで勧めない"], actHead:"現場で使うなら", note:"取引の条件と資金繰りの考え方は、社長と顧問の税理士、借入の相談は取引の金融機関で確かめる。", say:"売上が入るまでの期間と、支払うまでの期間の差を見ると、会社が手元に用意しておくお金の大きさが分かります。一緒に確かめてみましょう。", more:"場面の例としては、大きな取引先との取引が増え、入金は先なのに外注先への支払いが先に来る会社です。売上が伸びているのに資金が苦しいと社長が話すときは、このずれが原因のことがあります。社長に万一があって取引が止まると、入金の予定がずれることもあるので、事業保障の話の材料になります。", why:"利益は売上が決まったときに数えますが、お金は実際に入金されるまで使えないからです。入るまでと払うまでの期間の差が、そのまま会社が立て替えておくお金になります。" },
      { key:'faq_xhkk_nouzei_jiki', faq:1, grp:'hkk', q:"決算のあと法人税を払うお金はいつ要る？", re:/(法人税|消費税|事業税)[^。]{0,12}(いつ払|いつ納|払う時期|納める時期|まとめて|準備|お金)|中間(申告|納付)|決算の(あと|後)[^。]{0,12}(税金|税)[^。]{0,8}(払|納|出て)/, ng:/相続税|贈与税|所得税/, head:"法人税などは、決算のあとの申告と一緒にまとめて払い、期の途中に中間の納付がある会社もあります。", body:"決算が終わると、法人税・法人住民税・事業税を申告と一緒に納めます。前の期の税額などによっては、期の途中に中間の申告と納付があります。消費税も、売上で預かった分から仕入れなどで払った分を差し引いて納める仕組みで、中間の納付がある会社もあります。どれも、資金繰り表に先に入れておくお金です。", acts:["税をまとめて払う月を、資金繰り表に入れてあるか社長と一緒に確かめる", "その月と、法人の保険料の年払いの月が重ならないかを見る", "時期と額は、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"申告と納付の期限・中間申告の要否・額は、会社の決算期と前の期の税額で変わる。顧問の税理士と税務署で確かめる。", say:"決算のあとは税をまとめて払う時期があるので、その月の資金繰りを先に見ておくと安心です。顧問の先生に時期を確かめて、表に入れておきましょう。", more:"よくある勘違いは、売上で受け取った消費税を会社のお金として使ってしまうことです。預かった消費税は、いずれ納める分なので、手元のお金から分けて考えます。法人の保険料を年払いにする場合も、税をまとめて払う月と重ならないかを資金繰り表で確かめます。", why:"税は利益や売上に応じて後からまとめて払う形なので、その月だけ出ていくお金が大きくなるからです。前もって分けておかないと、黒字の会社でも支払いの月にお金が足りなくなります。" },
      { key:'faq_xhkk_kurushii_hoken', faq:1, grp:'hkk', q:"会社の資金繰りが苦しいとき、法人の保険はどうする？", re:/(会社|法人|社長)[^。]{0,16}(資金繰り|お金|経営)[^。]{0,4}(が)?[^。]{0,4}(苦し|厳し|きつ)[^。]{0,16}(保険|契約)|(法人|会社)の?(保険料|保険)[^。]{0,10}(会社の)?(負担になっ|重荷|重く(なっ|感じ))|(資金繰り|経営|会社|法人)が(苦し|厳し|きつ)[^。]{0,16}保険/, head:"資金繰りが苦しいときも、先に解約を決めず、保障を残す方法から並べて社長に選んでいただきます。", body:"払い方の変更、保障の減額、保険料の払い込みをやめて保障を小さく残す払済、解約返戻金の範囲で借りる契約者貸付、解約など、方法はいくつかあります。それぞれ、残る保障・戻る額・経理の扱い・あとで元に戻せるかが違います。解約すると、同じ保障に入り直せないこともあります。", acts:["借入や支払いの相談など、会社の資金繰りの手当てを先に社長に伺う", "保険会社の資料で、方法ごとに残る保障と戻る額を並べて見せる", "経理の扱いは顧問の税理士に、手続きは保険会社に確かめていただく"], actHead:"現場で使うなら", note:"方法ごとの扱いは契約と約款で違う。手続きと戻る額は保険会社、経理と税は顧問の税理士、借入の相談は取引の金融機関で確かめる。", say:"苦しいときほど、急いでやめる前に、保障を残す方法と残さない方法を並べて比べてから決めませんか。その場で決めていただく必要はありません。", more:"場面の例としては、売上が落ちた期に、社長から法人の保険を全部やめたいと言われる形です。社長に万一があったときの借入の返済など、その保険が何のために入っていたかを先に思い出していただきます。よくある勘違いは、解約すれば手元のお金が増えるだけと考えることで、戻った額と帳簿の額の差が収入として扱われることがあります。", why:"会社が苦しい時期ほど、社長に万一があったときの影響は大きくなるからです。一度解約すると、年齢や体の状態で同じ保障に入り直せないことがあるので、残す方法を先に並べます。" },
      { key:'faq_xhkk_kariire_shurui', faq:1, grp:'hkk', q:"会社の借入にはどんな種類がある？", re:/証書貸付|手形貸付|当座貸越|(会社|法人)の?(借入|借り入れ|融資)[^。]{0,8}(種類|形|違い)|(銀行|金融機関)(から|の)[^。]{0,4}(借り方|融資)[^。]{0,6}(種類|違い)/, head:"会社の借入には、主に証書貸付・手形貸付・当座貸越があり、返し方と使い道が違います。", body:"証書貸付は契約書を交わし、決めた期間で分けて返す形で、設備や長めの運転資金に使われます。手形貸付は短い期間の運転資金に使われ、期日に返すか借り直します。当座貸越は決めた枠の中で、必要なときに借りて返す形です。信用保証協会の保証が付くものと、付かないものもあります。", acts:["借入の返済予定表を見せていただき、借入ごとの形と返済の予定を一緒に書き出す", "社長に万一があったとき、どの借入がどうなるかを金融機関に確かめていただく", "借り方の判断はこちらでせず、社長と取引の金融機関で決めていただく"], actHead:"現場で使うなら", note:"借入の条件・期限・社長に万一があったときの扱いは、借入の契約と取引の金融機関で確かめる。保証の法律の扱いは弁護士。", say:"借入には形がいくつかあり、返し方が違います。どの借入がいつまでに、どう返す予定かを一緒に書き出しておくと、万一のときの備えも考えやすくなります。", more:"よくある勘違いは、借入の残高の合計だけを見ることです。毎月分けて返す借入と、期日にまとめて返すか借り直す借入では、資金繰りへの響き方が違います。短い借入を借り直しながら使っている会社では、会社の状況が変わると借り直しができないこともあるので、その分も考えます。", why:"借入は、何に使うお金かによって、返し方と期間を合わせて作られているからです。形が分かると、どの月にどれだけ返すお金が要るか、社長に万一があったときに何が起きるかを考えやすくなります。" },
      { key:'faq_xhkk_tanki_chouki', faq:1, grp:'hkk', q:"短期借入金と長期借入金の違いは？", re:/(短期借入金|長期借入金|短期借入|長期借入|短期の借入|長期の借入)[^。]{0,12}(違い|違う|とは|って何|の意味|見方|どう見|多い)|長期借入金[^。]{0,10}(次の期|一年|返す分)/, head:"短期借入金は決算の日から次の一年の間に返す予定の借入で、長期借入金はそれより先まで返す借入です。", body:"貸借対照表では、近いうちに返す借入を流動負債の短期借入金に、それより先まで返す借入を固定負債の長期借入金に載せます。長期の借入のうち次の一年の間に返す分を、別の科目に分けて載せている会社もあります。短期の借入が多いと、近いうちの返済に向けたお金の手当てが要ります。", acts:["二つの借入金の額と、手元の現預金を並べて社長と一緒に見る", "借入の返済予定表で、次の一年に返す額を確かめる", "科目の載せ方と数字の解釈は、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"科目の分け方は会社の会計の処理による。数字の解釈は顧問の税理士、借入の条件は取引の金融機関で確かめる。", say:"借入には近いうちに返すものと、先まで返すものがあり、決算書では分けて載っています。次の一年に返す額を、一緒に確かめておきませんか。", more:"よくある勘違いは、長期借入金はしばらく返さなくてよい借入だと考えることです。多くは毎月分けて返しているので、次の一年の返済額は資金繰りに入れます。短期の借入を借り直しながら使っている会社では、決算書の上では短期でも、実際には長く借り続けていることもあります。", why:"会社の支払いの力を見るときは、近いうちに出ていくお金と、近いうちに入るお金を比べることが大事だからです。返す時期で借入を分けておくと、その比べ方がしやすくなります。" },
      { key:'faq_xhkk_hoshoukyoukai', faq:1, grp:'hkk', q:"信用保証協会とは？", re:/(信用)?保証協会|代位弁済/, head:"信用保証協会は、中小企業が金融機関から借りるときに、保証人の役目を引き受ける公的な機関です。", body:"保証が付くと、金融機関は貸しやすくなり、会社は保証の対価として保証料を払います。会社が返せなくなると、協会が金融機関に代わりに返し（代位弁済）、そのあと会社は協会にそのお金を返していくことになります。保証が付いても、返す義務が無くなるわけではありません。", acts:["借入の中に、保証協会の保証が付いたものがあるかを社長に伺う", "保証料と返済の予定を、借入の返済予定表と一緒に確かめる", "保証の条件と制度の細部は、取引の金融機関や保証協会に確かめていただく"], actHead:"現場で使うなら", note:"保証の条件・保証料・制度の内容は、各地の信用保証協会と取引の金融機関で確かめる。返せないときの法律の扱いは弁護士。", say:"保証協会の保証は借入をしやすくする仕組みで、返す義務はそのまま残ります。どの借入に付いているかを、返済の予定と一緒に整理しておきましょう。", more:"よくある勘違いは、保証協会が付いていれば返せなくなっても大丈夫と考えることです。協会が代わりに返したあとは、会社と保証人が協会に返していきます。社長が個人で連帯保証もしているかは、借入ごとに違うので、保証の契約書で確かめます。", why:"中小企業は担保や実績が少なく、金融機関が貸しにくいことがあるので、公的な機関が保証を引き受けて、お金を借りやすくする仕組みが作られています。ただ借りたお金を返すのは会社であることは変わりません。" },
      { key:'faq_xhkk_guideline', faq:1, grp:'hkk', q:"経営者保証に関するガイドラインとは？", re:/経営者保証(に関する)?ガイドライン|経営者保証[^。]{0,12}(外|なし|無し|解除|とは|って何|中身|条件)|(個人保証)[^。]{0,4}(を)?外(して|す|せ)/, head:"社長の個人保証に頼りすぎない借入を進めるための、金融機関と経営者の自主的な決まりです。", body:"会社と社長個人の資産や経理を分けていること、会社の財務の基盤がしっかりしていること、決算書などを金融機関に適時適切に出していることなどが、保証を求めない借入を考えてもらうときの目安として示されています。事業を継ぐときの保証の扱いや、保証をした方の債務の整理の考え方も含まれています。", acts:["保証を外す話は、社長から取引の金融機関に相談していただく", "会社と社長個人のお金の分け方を、顧問の税理士と一緒に整えていただく", "保証が外れるかどうかの見込みは、こちらで言わない"], actHead:"現場で使うなら", note:"ガイドラインの中身と使い方は、取引の金融機関と中小企業庁などの公表資料、保証の法律の扱いは弁護士で確かめる。外れるかどうかを言い切らない。", say:"社長の個人保証については、金融機関と相談するための考え方を示した決まりがあります。会社と個人のお金の分け方を整えることが、その相談の入口になります。", more:"よくある勘違いは、ガイドラインがあれば保証は必ず外れると考えることです。外すかどうかは、会社の状況を見て金融機関が判断します。事業を継ぐ場面では、前の社長の保証と後継ぎの方の保証の扱いが話題になるので、承継の話と一緒に、顧問の先生と金融機関を交えて考えます。", why:"社長の個人保証は、会社が立ち行かなくなったときに社長とご家族の暮らしまで失わせることがあり、事業を継ぐ人が見つからない理由にもなるからです。保証に頼りすぎない借入の考え方を示すために、この決まりが作られています。" },
      { key:'faq_xhkk_kinyu_me', faq:1, grp:'hkk', q:"金融機関は会社のどこを見ている？", re:/(金融機関|銀行|信用金庫)[^。]{0,4}(は|が)[^。]{0,8}(会社|決算書|どこ|何)[^。]{0,8}(を)?(見て|見る|気にす|評価)|(融資|借入)[^。]{0,6}(の)?(とき|審査)[^。]{0,8}(金融機関|銀行)[^。]{0,6}(見る|気にす)|金融機関の目線|債務者区分/, head:"金融機関は、会社が借入を返していける力があるかを、利益・純資産・手元のお金・資金の使い道から見ます。", body:"本業の利益と、お金の出ていかない費用である減価償却費から、借入を無理なく返せるかを見ます。純資産がマイナスになっていないか、手元のお金が足りているか、借りたお金を何に使うかも確かめます。金融機関は取引先の状態を区分して融資を判断しており、試算表や計画をきちんと出してくれるかも、信用の材料になります。", acts:["社長に、取引の金融機関から何を求められているかを伺う", "社長に万一があったとき、金融機関がどう動くかを社長から確かめていただく", "金融機関とのやりとりに、こちらから口を挟まない"], actHead:"現場で使うなら", note:"融資の判断と条件は取引の金融機関が決める。決算書の数字の解釈は顧問の税理士で確かめ、こちらで融資の見込みを言わない。", say:"金融機関は、会社が借入を返していける力を見ています。社長に万一があったときにその力がどうなるかも、一緒に考えておきませんか。", more:"金融機関がよく見るのは、借入の残りが本業の稼ぐ力に比べて重すぎないか、役員貸付金のように事業と関係の薄い資産が無いか、会社と社長個人のお金が分かれているか、です。社長が営業の中心の会社では、社長に万一があったときの返済の見通しも、金融機関が気にする点になります。", why:"金融機関が貸したお金は、会社が稼いだお金から返してもらうしかないからです。だから、今の数字だけでなく、これから返していける力と、会社の様子を正直に伝えてくれるかを見ます。" },
      { key:'faq_xhkk_mainbank', faq:1, grp:'hkk', q:"取引する金融機関は一つに絞るべき？", re:/メインバンク|(取引|付き合)[^。]{0,6}(金融機関|銀行)[^。]{0,8}(一つ|一行|絞|複数|いくつ|何行)|(複数|いくつも)の(金融機関|銀行)[^。]{0,8}(取引|付き合)/, ng:/個人|口座を作|nisa|ニーサ/, head:"取引する金融機関の数に決まりは無く、一つに絞る形にも複数の形にも考え方があります。", body:"主に取引している金融機関をメインバンクと呼び、一つと深く付き合うと、会社の事情を分かってもらいやすいと考える社長もいます。複数と付き合うと、条件を比べたり、一つの金融機関の事情に左右されにくくなったりすると考える社長もいます。どちらが良いかは、会社の事情と社長の考え方で決まります。", acts:["今どの金融機関と、どの借入や口座で取引しているかを社長と一緒に書き出す", "変える・増やす話は、社長と顧問の税理士、金融機関で決めていただく", "こちらからどの金融機関が良いとは言わない"], actHead:"現場で使うなら", note:"取引の金融機関の選び方は社長の判断。条件と影響は取引の金融機関と顧問の税理士で確かめ、こちらでは勧めない。", say:"取引する金融機関の数に正解はなく、社長のお考え次第です。今の取引の様子を書き出しておくと、どう付き合うかを考えやすくなります。", more:"場面の例としては、借入を増やしたいのに今の金融機関の反応が良くないと、社長が話す形です。こちらは選び方を勧めず、借入の中身と返済の予定を書き出すところを手伝います。保険料の引き落とし口座や、法人の保険を担保にした借入がある場合は、金融機関を変えると手続きが要ることも伝えます。", why:"金融機関との付き合い方は、会社の借入の条件や、困ったときの相談のしやすさに関わる経営の判断だからです。募集人が口を出す範囲ではないので、整理の手伝いまでにします。" },
      { key:'faq_xhkk_hensai_jouken', faq:1, grp:'hkk', q:"会社の借入の返済が苦しいと社長に相談された", re:/返済条件(の)?(変更|緩和|見直し)|(借入|借り入れ|融資)[^。]{0,8}(の)?返済[^。]{0,8}(苦し|厳し|きつ|待って|減らし|猶予)|返済(を)?(待って|猶予|減らして)[^。]{0,8}(もら|いただ)/, ng:/住宅ローン|カードローン|奨学金/, head:"借入の返済が苦しいときは、まず取引の金融機関に相談していただくよう、社長にお伝えします。", body:"金融機関には、返済の額を減らす、期間を延ばすなどの条件の変更を相談できることがあります。そのときは、会社の今の状況と、これからどう立て直すかの計画を求められることが多く、条件を変えている間は新しい借入が難しくなることもあります。顧問の税理士や、商工会議所・よろず支援拠点などの公的な相談窓口も頼れます。", acts:["責める言い方をせず、社長の話を最後まで伺う", "金融機関と顧問の先生への相談を先にしていただくよう勧める", "保険の解約を先に勧めず、社長に万一があったときの備えが切れないかを確かめる"], actHead:"現場で使うなら", note:"返済条件の変更ができるかは金融機関の判断。立て直しの計画は顧問の税理士や公的な相談窓口、保証と法律の扱いは弁護士で確かめる。", say:"返済が苦しいときは、ひとりで抱えずに、まず取引の金融機関と顧問の先生に相談してみてください。保険のことは、そのあとで一緒に整理しましょう。", more:"よくある勘違いは、返済の相談をすると取引が終わると考えて、相談を遅らせることです。苦しくなる前に相談するほど、取れる手は多くなります。保険の面では、資金のために法人の保険を解約すると、社長に万一があったときの借入の返済の備えも無くなるので、残す方法から並べて考えます。", why:"金融機関も、貸したお金が返ってこなくなるより、条件を変えてでも返し続けてもらうほうを考えることがあるからです。ただ判断するのは金融機関なので、募集人は相談の入口へつなぐ役にとどめます。" },
      { key:'faq_xhkk_setsubi', faq:1, grp:'hkk', q:"設備は借入で買うかリースにするか？", re:/(設備|機械|車両|社用車)[^。]{0,12}(リース|借入|借りて|ローン)[^。]{0,10}(か|どちら|どっち|迷|相談|考え)|設備投資[^。]{0,10}(資金|お金|考え方|手当て)|(機械|設備)を(買う|購入する)[^。]{0,8}(資金|お金)/, head:"借入で買うかリースにするかは、資金繰り・持ち主・やめやすさの違いで社長が決めます。", body:"借入で買うと会社の持ち物になり、借入を返しながら減価償却で費用にしていきます。リースは使う権利に料金を払う形で、まとまったお金が要らない一方、途中でやめにくい契約も多く、合計の支払いは条件で違います。どちらが合うかは、手元のお金・借入の枠・使う期間・会計と税の扱いで変わります。", acts:["設備の使い道と使うつもりの期間を、社長の言葉で伺う", "借入とリースの返済や支払いの予定を、資金繰り表に並べて見ていただく", "会計と税の扱いは顧問の税理士、借入の条件は取引の金融機関に確かめていただく"], actHead:"現場で使うなら", note:"リースの契約の形と会計・税の扱いは、契約と会社の会計の方針で違う。顧問の税理士と取引の金融機関、リース会社で確かめる。", say:"設備を買うかリースにするかは、毎月のお金の出方と、途中でやめられるかが違います。資金繰り表に並べて、社長のお考えで選んでいただくのがよいと思います。", more:"よくある勘違いは、リースなら借入ではないので会社の負担にならないと考えることです。毎月の支払いは固定費になり、途中でやめると残りの料金を求められる契約もあります。社長に万一があったときも支払いは続くので、事業保障の話では、借入の返済と並べてリースの支払いも固定費として書き出します。", why:"設備のお金の手当ては、会社の手元のお金と借入の枠をどう使うかという経営の判断だからです。形ごとに、お金の出方・持ち主・やめやすさが違うので、並べて比べると社長が決めやすくなります。" },
      { key:'faq_xhkk_teiki_dougaku', faq:1, grp:'hkk', q:"定期同額給与の仕組みは？", re:/定期同額|役員報酬[^。]{0,8}(毎月|月ごと)[^。]{0,10}(同じ|同額|変え|変わ|変動)/, head:"役員報酬を会社の費用とするには、原則として毎月同じ額で払う決まりがあります。", body:"役員は自分の報酬を自分たちで決められるので、利益の出方に合わせて報酬を動かすと、税の計算が会社の都合で動いてしまいます。そこで、決まった時期に決めた額を毎月同じように払うものを費用として認める仕組みになっています。改定できる時期や、例外として認められる場合には決まりがあります。", acts:["役員報酬を変えたい話が出たら、時期と理由を顧問の税理士に先に確かめていただく", "保険料を払うために報酬を動かす話は、こちらから持ち出さない", "報酬の額の判断は社長と顧問の税理士で決めていただく"], actHead:"現場で使うなら", note:"改定できる時期・例外の扱い・費用として認められる範囲は、国税庁の資料と顧問の税理士で確かめる。こちらで額や時期を決めない。", say:"役員報酬は、毎月同じ額で払う決まりがあり、変える時期にも決まりがあります。変えたいお考えがあれば、まず顧問の先生に時期を確かめていただくのが確かです。", more:"よくある勘違いは、利益が出た月に役員報酬を増やせば会社の税が減ると考えることです。期の途中で決まりに沿わずに増やした分は、会社の費用として認められないことがあります。社長個人の手取りと会社の税の両方に関わるので、保険の話と混ぜずに、顧問の税理士の判断を先にいただきます。", why:"役員は会社の中で報酬を決める側でもあるため、決め方に枠を設けないと、利益の調整に使えてしまうからです。毎月同じ額という形にすることで、報酬が利益の都合で動かないようにしています。" },
      { key:'faq_xhkk_houshu_henkou', faq:1, grp:'hkk', q:"期の途中で役員報酬を変えたいと言われた", re:/(期の途中|期中|途中)[^。]{0,8}役員報酬[^。]{0,10}(変え|上げ|下げ|減ら|増や)|役員報酬[^。]{0,8}(を)?(下げ|減らし|上げ|増やし)(たい|て|る)/, ng:/年金|社会保険|厚生年金|健康保険/, head:"期の途中で役員報酬を変えるときは決まりがあるので、変える前に顧問の税理士に確かめていただきます。", body:"役員報酬は、決まった時期に改定するのが原則で、期の途中で変えるのは、役職が大きく変わったときや、業績が著しく悪くなったときなど、決まった場合に限られます。決まりに沿わずに変えると、会社の費用として認められない部分が出ることがあります。報酬を変えると、社会保険料や社長個人の税・手取りも変わります。", acts:["変えたい理由と時期を、社長の言葉で伺う", "変える前に顧問の税理士へ相談していただくよう勧める", "社長個人の保障や保険料の払い方に響くかは、報酬が決まってから一緒に見直す"], actHead:"現場で使うなら", note:"期の途中で変えられる場合と手続きは、国税庁の資料と顧問の税理士、社会保険の扱いは社会保険労務士で確かめる。", say:"期の途中で役員報酬を変えるのは決まりがあるので、変える前に顧問の先生に確かめていただくのが確かです。報酬が決まってから、保障の見直しも一緒に考えましょう。", more:"場面の例としては、売上が落ちた期に、社長が自分の報酬を下げて会社のお金を守りたいと話す形です。社長のお考えは大事にしつつ、手続きは顧問の税理士に任せます。報酬が下がると社長個人の手取りも下がるので、社長個人で払っている保険料が重くならないかは、報酬が決まってから見ます。", why:"役員報酬の額は会社の税と社長個人の税・社会保険料の両方に関わり、変え方を間違えると思わぬ負担が出るからです。決まりに沿って変えるために、先に専門家に確かめていただきます。" },
      { key:'faq_xhkk_jizen_kakutei', faq:1, grp:'hkk', q:"事前確定届出給与とは？", re:/事前確定(届出)?給与|役員(の)?賞与|役員に(賞与|ボーナス)/, head:"事前確定届出給与は、役員に賞与を出す時期と額を前もって税務署に届け出て、そのとおりに払う形です。", body:"役員の賞与は、そのままでは会社の費用として認められにくいですが、決まった期限までに支給する時期と額を届け出て、届けたとおりに払えば、費用として扱われる仕組みがあります。届けた額と違う額を払うと、費用として認められないことがあります。届け出の期限と手続きには決まりがあります。", acts:["役員賞与のお考えがあれば、時期を顧問の税理士に先に確かめていただく", "届け出の手続きはこちらで行わず、顧問の税理士に任せていただく", "賞与の受け取りで社長個人の手取りがどう変わるかも、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"届け出の期限・様式・届けた額と違う場合の扱いは、国税庁の資料と顧問の税理士で確かめる。申告と手続きは税理士の業務。", say:"役員の賞与は、前もって時期と額を届け出て、そのとおりに払う形があります。届け出の期限があるので、お考えがあれば早めに顧問の先生へ相談してみてください。", more:"よくある勘違いは、届け出をしておけば、あとで業績に合わせて額を変えられると考えることです。届けた額と違う額を払うと、その賞与が費用として認められないことがあります。社長個人の税と社会保険料にも関わるので、保険料の払い方の話とは混ぜずに、顧問の税理士の判断を先にいただきます。", why:"役員は自分たちで報酬を決められる立場なので、賞与を利益の調整に使えないように、前もって決めて届けた形だけを認めているからです。決めたとおりに払うことが、この形の要になります。" },
      { key:'faq_xhkk_houshu_shaho', faq:1, grp:'hkk', q:"役員報酬と社会保険料・年金のつながりは？", re:/役員報酬[^。]{0,12}(社会保険料|厚生年金|年金|健康保険)|(社長|役員)の?(報酬|給与)[^。]{0,8}(と|で)[^。]{0,4}(社会保険料|厚生年金|年金)/, head:"役員報酬の額は、会社と社長が払う社会保険料と、社長が将来受け取る厚生年金の額につながっています。", body:"社会保険に入っている会社の役員は、報酬の額に応じて健康保険と厚生年金の保険料を、会社と本人で払います。報酬を下げると保険料も下がりますが、将来の厚生年金や、病気で休んだときの手当ても小さくなることがあります。報酬を決めるときは、税・社会保険料・将来の受け取りを並べて考えます。", acts:["報酬を変えるお考えがあれば、社会保険労務士と顧問の税理士に先に確かめていただく", "社長の老後の資金を考えるときは、厚生年金の見込みを日本年金機構の資料で確かめていただく", "報酬を下げて保険料に回す話は、こちらから勧めない"], actHead:"現場で使うなら", note:"保険料の率と上限・年金の額の計算は、日本年金機構と社会保険労務士、税は顧問の税理士で確かめる。こちらで額を言い切らない。", say:"役員報酬の額は、社会保険料だけでなく、社長の将来の年金や病気のときの手当てにもつながっています。変えるときは、両方を並べて顧問の先生と考えていただくのが確かです。", more:"よくある勘違いは、役員報酬を下げて社会保険料を減らせば、会社も社長も負担が軽くなるだけと考えることです。将来の厚生年金や、障害や亡くなったときの公的な保障も小さくなることがあります。社長の保障を考えるときは、公的な保障がどれだけあるかを先に確かめ、そのうえで足りない分を考えます。", why:"社会保険料は報酬に応じて決まり、厚生年金の受け取りもその保険料の記録から計算されるからです。今の負担と将来の受け取りがつながっているので、片方だけを見て決めないようにします。" },
      { key:'faq_xhkk_koushi', faq:1, grp:'hkk', q:"会社と社長個人のお金を分けるには？", re:/公私混同|(会社|法人)(と|の)[^。]{0,4}(社長|個人)[^。]{0,4}(の)?(お金|財布|口座)[^。]{0,8}(分け|区別|まざ|混ざ|混同|一緒)|(会社|法人)の口座[^。]{0,10}(個人|社長)[^。]{0,8}(支払|払って|使って)|(社長|個人)[^。]{0,4}(と|の)[^。]{0,2}(会社|法人)[^。]{0,4}(の)?(お金|財布|口座)[^。]{0,8}(分け|区別|まざ|混ざ|混同|一緒)/, ng:/家計|夫婦/, head:"会社と社長個人のお金は、口座と支払いを分け、会社のお金を個人のことに使わないのが基本です。", body:"会社の口座から社長個人の支払いをしたり、社長のお金で会社の支払いをしたりすると、役員貸付金や役員借入金が増え、決算書が読みにくくなります。金融機関からは、会社と経営者の資産が分かれているかを見られ、経営者保証の考え方にも関わります。分けるための整理は、顧問の税理士と一緒に進めます。", acts:["保険料がどの口座から払われているかを、契約ごとに確かめる", "責める言い方をせず、分けておくと金融機関や承継の場面で説明しやすいことを伝える", "分け方と過去の整理は、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"過去に混ざった分の整理と税の扱いは顧問の税理士、金融機関の見方は取引の金融機関で確かめる。", say:"会社と社長個人のお金を分けておくと、金融機関への説明も、事業を継ぐときの整理もしやすくなります。保険料の払い方から一緒に確かめてみませんか。", more:"場面の例としては、社長個人の保険料を会社の口座から引き落としている会社です。そのままでは役員貸付金や役員への給与と見られることがあり、扱いは顧問の税理士が決めます。よくある勘違いは、小さな会社なので分けなくても困らないと考えることで、承継や借入の場面で説明に困ることがあります。", why:"会社と社長は別の人格で、お金も別に記録されるからです。混ざっていると、会社の本当の姿が決算書から読めなくなり、金融機関や後継ぎの方が判断しにくくなります。" },
      { key:'faq_xhkk_taishoku_seido', faq:1, grp:'hkk', q:"社員の退職金制度にはどんな形がある？", re:/退職金制度|(社員|従業員)の?退職金[^。]{0,10}(種類|形|準備|制度|仕組み|どう用意)|退職金を外の制度/, ng:/うちの会社|社内|わが社|自分の|私の/, head:"社員の退職金には、会社が払う形・外の制度に積み立てる形などがあり、組み合わせもあります。", body:"退職金規程を作って会社の手元から払う形、中小企業退職金共済のような外の制度に掛金を払う形、企業型の確定拠出年金のように社員ごとの口座で運用する形、法人の保険で準備する形などがあります。それぞれ、会社の負担の出方・社員が受け取る形・途中でやめるときの扱いが違います。", acts:["今の退職金の規程と、何で準備しているかを社長に伺う", "制度の選び方は、社会保険労務士と顧問の税理士に確かめていただく", "保険で準備する話は、規程と払う時期が決まってからにする"], actHead:"現場で使うなら", note:"制度ごとの要件・掛金の扱い・規程の作り方は、社会保険労務士・顧問の税理士・各制度の窓口で確かめる。こちらで制度を勧めない。", say:"社員の退職金の準備には、いくつかの形があります。まず今の規程と準備の方法を確かめてから、どう組み合わせるかを専門家と一緒に考えるのが確かです。", more:"よくある勘違いは、退職金の準備は保険だけで考えるものだと思うことです。規程が無いまま準備だけを始めると、いつ・誰に・いくら払うかが決まらず、準備したお金の使い道がはっきりしません。外の制度は会社に戻らないお金になることもあるので、形ごとの違いを先に並べます。", why:"退職金は社員と約束したお金で、払う時期と額は規程で決まるからです。準備の形によって会社の負担の出方や、社員が受け取る形が変わるので、規程と準備を合わせて考えます。" },
      { key:'faq_xhkk_houtei_fukuri', faq:1, grp:'hkk', q:"法定福利と法定外福利の違いは？", re:/法定(外)?福利|(会社|企業)の?福利厚生[^。]{0,8}(種類|例|違い|とは|って何)/, ng:/養老|ハーフタックス/, head:"法定福利は法律で会社に負担が決められているもの、法定外福利は会社が自分で決めて用意するものです。", body:"法定福利には、健康保険・厚生年金・雇用保険・労災保険などの会社の負担分があり、人を雇うと給料のほかにかかります。法定外福利は、社宅・慶弔見舞金・健康診断の上乗せ・社員旅行・団体保険など、会社が決めて用意するものです。法定外福利は、規程に決めて社員に公平に用意することが基本です。", acts:["今の福利厚生の中身と規程があるかを社長に伺う", "法定外の福利厚生を変える話は、社会保険労務士と顧問の税理士に確かめていただく", "保険を福利厚生に使う話は、社員全員に公平な形かを先に見る"], actHead:"現場で使うなら", note:"会社の負担の率と対象は社会保険労務士、福利厚生の費用の扱いは顧問の税理士、規程の作り方は社会保険労務士で確かめる。", say:"会社の福利厚生には、法律で決まっているものと、会社が自分で決めるものがあります。今どんなものを用意しているかを、規程と一緒に確かめてみませんか。", more:"よくある勘違いは、福利厚生のつもりで一部の役員だけを対象にすることです。特定の人だけに向けたものは、福利厚生として扱われないことがあります。人を雇うと給料のほかに会社の社会保険料の負担もかかるので、社員が増えたときの固定費の話にも関わります。", why:"人を雇う会社には、法律で決まった社会保険の負担があり、それに加えて社員の暮らしを支えるために会社が用意するものがあるからです。二つを分けて見ると、会社の人件費の全体がつかめます。" },
      { key:'faq_xhkk_shataku', faq:1, grp:'hkk', q:"社宅や借り上げ社宅の仕組みは？", re:/役員社宅|借り上げ社宅|借上社宅|社宅[^。]{0,10}(仕組み|とは|って何|家賃|規程|考え方|受け取)/, ng:/寮|入れる|うちの|社内|わが社|私の|自分の/, head:"社宅は、会社が持っている家や借りた家を社員や役員に貸し、家賃の一部を本人から受け取る仕組みです。", body:"会社が家を借りて社員や役員に貸す形を借り上げ社宅と呼びます。本人から受け取る家賃が少なすぎると、その差が給与として扱われることがあり、受け取る額の考え方には決まりがあります。役員の社宅は、社員の場合と考え方が違うところがあります。規程を作って、対象と家賃の決め方を決めておきます。", acts:["社宅の規程があるか、対象と家賃の決め方を社長に伺う", "受け取る家賃の額の考え方は、顧問の税理士に確かめていただく", "社宅の費用も固定費として、事業保障の話の固定費に入れて書き出す"], actHead:"現場で使うなら", note:"本人から受け取る家賃の額の考え方と給与の扱いは、国税庁の資料と顧問の税理士、規程は社会保険労務士で確かめる。", say:"社宅は、会社が貸す家の家賃の一部を本人から受け取る仕組みで、受け取る額には決まりがあります。規程と一緒に、顧問の先生に確かめていただくのが確かです。", more:"よくある勘違いは、社宅にすれば家賃を全て会社の費用にできると考えることです。本人から受け取る額が少なすぎると、その分が給与とされることがあります。社長に万一があったときに、役員の社宅の契約をどうするかも、ご家族の暮らしに関わるので確かめておきます。", why:"住まいを会社が用意する分も、本人にとっては給料の代わりになる面があるため、受け取る家賃の額によっては給与として扱う考え方があるからです。決まりに沿って規程を作ることで、扱いがはっきりします。" },
      { key:'faq_xhkk_hoken_yakume', faq:1, grp:'hkk', q:"法人の保険にはどんな役目がある？", re:/(法人|会社)(の)?(保険|で入る保険|で入っている保険)[^。]{0,10}(役目|役割|目的|何のため|理由)|(会社|法人)(が|で)保険に入る(理由|目的)|法人保険の(役目|役割|目的)/, head:"法人の保険の役目は、事業の保障・退職金・福利厚生・事業を継ぐ準備の四つに分けられます。", body:"社長に万一があったときに借入の返済や固定費をまかなう事業の保障、役員や社員の退職金の準備、社員とご家族を支える福利厚生、自社株や事業を継ぐときのお金の準備です。どの役目のために、いつ、誰が受け取るお金かを先に決めると、保険の形と期間が決まります。決算の都合で入るものではありません。", acts:["今入っている保険を、役目ごとに一覧にして社長と一緒に見る", "受け取る時期と使い道を、社長の予定と並べて書き出す", "経理と税の扱いは、こちらで言い切らず顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"役目ごとの経理と税の扱いは契約の形で違う。顧問の税理士、保障の中身は保険会社と約款で確かめる。", say:"会社の保険は、事業を守る・退職金を準備する・社員を支える・事業を継ぐ、の役目ごとに整理すると、何が足りて何が重なっているかが見えてきます。一緒に一覧にしてみませんか。", more:"よくある勘違いは、利益が出たときに税の都合で保険を選ぶことです。役目がはっきりしない保険は、解約の時期も使い道も決まらず、あとで困ることがあります。役目から入ると、保障の額は借入や固定費から、退職金の準備は規程と時期から考えられ、顧問の税理士にも説明しやすくなります。", why:"保険は将来のある時点にお金を届ける道具なので、何のために、いつ、誰に届けるかで、選ぶ形が変わるからです。役目を先に決めると、社長も顧問の税理士も判断しやすくなります。" },
      { key:'faq_xhkk_tanaoroshi', faq:1, grp:'hkk', q:"会社で入っている保険を整理するには？", re:/(会社|法人)(で|の)?[^。]{0,6}(保険)[^。]{0,8}(整理|一覧|棚卸|洗い出|まとめ)|保険の棚卸|(会社|社長の会社)に[^。]{0,4}どんな保険[^。]{0,6}(ある|入って)[^。]{0,6}(分から|知らな)/, head:"会社の保険は、契約ごとに役目・受取人・保険料・満期・戻る額を一覧表にすると整理できます。", body:"保険証券と、保険会社から届く契約の内容のお知らせを集め、契約者・被保険者・受取人・保障の額・保険料と払い方・保険の期間・解約返戻金の推移・経理の扱いを一枚にします。役目ごとに分けると、重なっている保障や、目的のはっきりしない契約が見えてきます。", acts:["社長の了承を得て、保険証券と契約の内容のお知らせを集めていただく", "契約ごとの役目と受取人を、社長の言葉で確かめる", "経理の扱いの欄は、顧問の税理士の資料と照らす"], actHead:"現場で使うなら", note:"契約の中身と戻る額は保険会社、経理の扱いは顧問の税理士で確かめる。他社の契約をこちらで評価しない。", say:"会社で入っている保険を一枚の表にすると、何のための保険か、重なっていないかが見えてきます。証券を集めるところから、一緒に始めてみませんか。", more:"場面の例としては、代替わりのたびに付き合いで入った保険が積み重なり、社長が全体を覚えていない会社です。よくある勘違いは、整理すると解約の話になると構えることで、まずは役目を確かめるだけです。他社の契約も含めて並べますが、良し悪しは言い切らず、社長が決める材料にとどめます。", why:"保険は契約したときの目的が、年月とともに見えにくくなるからです。一覧にすると、社長に万一があったときにどこからいくら届くかが分かり、顧問の税理士とも同じ表で話せます。" },
      { key:'faq_xhkk_hensai_gensen', faq:1, grp:'hkk', q:"借入の返済のお金はどこから出る？", re:/(借入|借り入れ|融資)[^。]{0,8}(返済|返す)[^。]{0,8}(元手|お金|原資|財源)[^。]{0,8}(どこ|何|から)|返済(の)?原資|返済できる力|(利益)と[^。]{0,4}(借入|借り入れ)の返済/, ng:/住宅ローン|個人|家計/, head:"会社の借入は、税を払ったあとの利益と減価償却費を足した分から返すのが基本です。", body:"借入の返済は費用にならないので、損益計算書の利益から税を払い、残った分で返します。減価償却費は費用として利益を減らしますが、お金は出ていかないので、その分も返済に使えます。この合計より毎年の返済額が大きいと、手元のお金を減らしながら返していることになります。", acts:["一年の返済額を、借入の返済予定表から社長と一緒に書き出す", "利益と減価償却費の合計と、返済額を並べて見る", "数字の解釈は、顧問の税理士と取引の金融機関に確かめていただく"], actHead:"現場で使うなら", note:"返済の力の見方は金融機関ごとに違う。数字の解釈は顧問の税理士、借入の条件と見方は取引の金融機関で確かめる。", say:"借入は、税を払ったあとの利益と減価償却費から返していくのが基本です。毎年の返済額と並べると、無理なく返せているかが見えてきます。", more:"よくある勘違いは、利益が出ていれば借入は問題なく返せていると考えることです。利益より返済額が大きい会社は、手元のお金を減らしながら返しています。社長に万一があって利益が落ちると返済の元手も減るので、事業保障の話では、この差を埋める期間を考える材料になります。", why:"借入の返済はお金が出ていくのに費用にはならないため、税を払ったあとに残るお金でしか返せないからです。減価償却費はお金が出ていかない費用なので、その分を足して返す力を見ます。" },
      { key:'faq_xhkk_jigyou_keikaku', faq:1, grp:'hkk', q:"事業計画書とは？", re:/(事業|経営)計画(書)?/, head:"事業計画書は、会社がこれから何をして、売上・利益・お金・人をどう動かすかを書いた計画です。", body:"会社の目指す姿、商品やお客様、売上と利益の見込み、設備や人の計画、資金の手当て、借入の返済の予定などをまとめます。金融機関に借入を相談するとき、補助金を申し込むとき、社内で方針を共有するとき、事業を継ぐときなどに使います。作るのは社長で、顧問の税理士や専門家が手伝います。", acts:["計画の中の人と借入の予定を、社長に伺う", "社長に万一があったときに計画がどうなるかを、一緒に考える", "計画の数字の作り方は、顧問の税理士や公的な相談窓口に確かめていただく"], actHead:"現場で使うなら", note:"計画の作り方と数字は顧問の税理士・商工会議所・よろず支援拠点などの窓口、借入の相談は取引の金融機関で確かめる。", say:"これからの計画を書き出しておくと、金融機関への相談も、社員への方針の共有もしやすくなります。計画の中の人とお金の予定から、備えの話もできます。", more:"よくある勘違いは、事業計画書は借入のときだけ作る書類だと考えることです。数年先の売上・設備・人の予定が見えると、退職金の準備や事業を継ぐ時期の話も同じ表の上でできます。保険の話は計画の上に重ねるもので、計画の数字をこちらで作ることはしません。", why:"計画を言葉と数字にすると、社長の頭の中にある予定を、金融機関・社員・後継ぎの方と共有できるからです。共有できると、それぞれが同じ前提で判断できます。" },
      { key:'faq_xhkk_hojokin', faq:1, grp:'hkk', q:"補助金と助成金の違いは？", re:/補助金|助成金/, head:"補助金は主に事業の取り組みを、助成金は主に雇用や人の育成を支える公的なお金です。", body:"補助金は、設備投資や新しい取り組みなどに対して出るもので、募集の時期と予算があり、申し込んでも審査で選ばれないことがあります。助成金は、主に厚生労働省の雇用や人の育成に関するもので、要件を満たせば受けられる形が多いです。どちらも原則として、使ったあとに受け取る形で、先に会社のお金が要ります。", acts:["使えるかどうかは、こちらで言い切らず窓口や専門家に確かめていただく", "受け取るまでの間の資金繰りを、社長と一緒に確かめる", "申請の手続きは、社会保険労務士・認定された支援機関などの専門家に任せていただく"], actHead:"現場で使うなら", note:"制度の中身・要件・募集の時期は、各省庁・自治体の公表資料と、助成金は社会保険労務士、補助金は認定された支援機関などの窓口で確かめる。", say:"補助金は事業の取り組みに、助成金は主に雇用や人の育成に出るお金です。受け取るまでに会社のお金が先に要ることが多いので、資金繰りも合わせて確かめておきましょう。", more:"よくある勘違いは、採択されればすぐにお金が入ると考えることです。多くは事業を終えて報告したあとに受け取るので、その間の支払いは会社が用意します。保険の契約や保険料を補助金の対象にできるかといった話は、こちらで言わず、窓口に確かめていただきます。", why:"国や自治体が、事業の成長や雇用を後押しするために設けているお金だからです。目的に沿って使われたかを確かめてから払う形が多いので、使ったあとに受け取る順番になります。" },
      { key:'faq_xhkk_komon_inai', faq:1, grp:'hkk', q:"税理士がついていない会社にはどう話す？", re:/(顧問の?|顧問)?税理士(が|の先生が)?(いない|ついていない|付いていない|おらず)|(自分で|社長が)[^。]{0,4}(申告|経理)して(いる|る)[^。]{0,8}(会社|社長)/, head:"顧問の税理士がいない会社でも税の扱いは言い切らず、確かめる先を社長に用意します。", body:"保険の経理や税の扱いは契約の形で違い、言い切ると社長の判断を誤らせることがあります。顧問の税理士がいない会社では、税務署の相談窓口や、税理士会の相談会、新しく税理士を探す方法などを伝え、社長が確かめてから決められるようにします。保険の話は、役目と保障の中身から始めます。", acts:["経理と税の扱いはこちらで決めず、確かめる先を社長にお伝えする", "保険の役目と保障の中身を先に話し、税の話を入口にしない", "社長の了承を得て、税理士を交えてから決めていただくよう段取りする"], actHead:"現場で使うなら", note:"税の扱いと申告は税理士の業務。税務署の相談窓口・各地の税理士会の相談で確かめる。こちらから特定の税理士を勧めない。", say:"保険の経理や税の扱いは、こちらで言い切れない部分があります。税務署の窓口や税理士の先生に確かめていただいてから、落ち着いて決めていただければ大丈夫です。", more:"よくある勘違いは、顧問の税理士がいない会社なら、募集人が税の扱いまで説明してよいと考えることです。税額の計算や申告の相談は税理士の業務なので、こちらは仕組みと確かめる先までにとどめます。保険料を払い続けられるかと、役目に合った形かを先に一緒に確かめます。", why:"税の扱いを間違えると、あとで社長に思わぬ負担がかかり、その責任は募集人には負えないからです。確かめる先を用意しておくと、社長が安心して判断でき、信頼にもつながります。" },
      { key:'faq_xhkk_nenpyo', faq:1, grp:'hkk', q:"会社の一年のお金の予定表はどう作る？", re:/(会社|法人)の?(一年|年間)[^。]{0,8}(お金|支払い|予定|流れ)|(賞与|ボーナス)[^。]{0,4}(や|と)[^。]{0,4}(税金|税)[^。]{0,8}(時期|一覧|予定)/, ng:/決算月|決算の時期/, head:"決算・税の支払い・賞与・保険の更新や満期を、月ごとに一枚に並べた表にします。", body:"決算と申告、税をまとめて払う月、賞与の月、設備の支払いや借入の返済が大きい月、保険の更新・満期・年払いの月を一枚に並べます。お金が少なくなる月と、社長が落ち着いて話せる時期が見えるので、保険の見直しの話も、決算の直前ではなく余裕のある時期に置けます。", acts:["社長の了承を得て、決算・税・賞与の月を伺い一枚に並べる", "保険の年払い・更新・満期の月を同じ表に書き込む", "税の時期は顧問の税理士に、保険の時期は保険会社の資料で確かめていただく"], actHead:"現場で使うなら", note:"税の申告と納付の時期は顧問の税理士、保険の更新と満期は保険会社の資料で確かめる。", say:"会社の一年のお金の動きを一枚に並べておくと、慌ただしい月と、落ち着いて話せる月が見えてきます。保険の見直しも、余裕のある時期に一緒に考えましょう。", more:"よくある勘違いは、決算が近づいてから保険の話をすると喜ばれると考えることです。決算の直前に利益を消す話にすると、保険の役目があいまいになり、顧問の税理士も困ります。一年の予定表があれば、見直しは決算から離れた時期に、役目の話として置けます。", why:"会社のお金は月ごとに大きく動き、社長の忙しさも決算や賞与の時期に偏るからです。先に予定を並べておくと、お金の負担と話すタイミングの両方を考えて段取りできます。" },
      { key:'faq_xhkk_zaiko', faq:1, grp:'hkk', q:"在庫が増えると資金繰りはどうなる？", re:/在庫[^。]{0,10}(資金繰り|お金|現預金|手元|決算書|増え|多い|売れ残)/, ng:/火災|家財|保険金|損害/, head:"在庫が増えると、仕入れに払ったお金が売れるまで眠るので、利益が出ていても手元のお金は減ります。", body:"仕入れた商品は、売れるまでは費用ではなく資産として貸借対照表に載ります。そのため在庫が増えると、利益は変わらないのに現預金が減る形になります。売れ残った在庫は、帳簿の額ほどのお金にならないこともあります。在庫の額と、売れるまでの期間を合わせて見ます。", acts:["決算書の在庫の額を、数年分並べて社長と一緒に見る", "在庫が増えている理由を、社長の言葉で伺う", "在庫の評価と数字の解釈は、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"在庫の評価の方法と会計の扱いは顧問の税理士、在庫そのものの火災などの備えは損害保険の担当で確かめる。", say:"在庫は売れるまでお金が眠っている状態なので、増えると手元のお金が減ります。在庫の額の動きを数年分並べて、一緒に確かめてみませんか。", more:"場面の例としては、売上が伸びて仕入れを増やした会社が、利益は出ているのに資金が苦しいと話す形です。よくある勘違いは、在庫が多いほど会社の財産が多いと考えることで、売れ残りは値下げしないとお金にならないこともあります。在庫を多く持つ会社は、火災などで在庫を失ったときの備えも別に確かめます。", why:"会計では、仕入れたお金は商品が売れたときに初めて費用になるからです。売れるまでの間はお金が商品の形に変わっているだけなので、利益とお金の動きにずれが出ます。" },
      { key:'faq_xhkk_urikake', faq:1, grp:'hkk', q:"売掛金の回収が遅れたらどうなる？", re:/売掛金[^。]{0,10}(回収|遅れ|払って|入らな|焦げ付)|貸倒(れ)?|(取引先|得意先)が[^。]{0,6}(払って(くれ)?ない|支払わない|払わない)/, ng:/倒産防止|セーフティ|共済/, head:"回収が遅れると、売上は立っていてもお金が入らず、支払いを会社が立て替え続けます。", body:"売掛金は、売上を計上したあと、まだ受け取っていないお金です。回収が遅れると資金繰りが苦しくなり、取引先が払えなくなると回収できない貸倒れになることがあります。売掛金が一つの取引先に偏っている会社ほど、影響が大きくなります。", acts:["主な取引先ごとの売掛金の額と、入金の予定を社長に伺う", "一つの取引先への偏りがあるかを、一緒に確かめる", "回収の手続きは弁護士、会計と税の扱いは顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"回収の法的な手続きは弁護士、貸倒れの会計と税の扱いは顧問の税理士、取引先の倒産への備えは各制度の窓口で確かめる。", say:"売掛金は、売上を立てたあと、まだ受け取っていないお金です。入金の予定と、一つの取引先への偏りを確かめておくと、資金繰りの心配の度合いが見えてきます。", more:"よくある勘違いは、売上が立てば会社のお金が増えたと考えることです。入金されるまでは、仕入れや給与の支払いを会社が立て替えています。取引先の倒産に備える制度もあるので、その話は確かめる先を伝えるところまでにし、こちらで加入を勧めることはしません。", why:"会社のお金が増えるのは、売上を立てたときではなく、実際に入金されたときだからです。回収が遅れるほど、立て替えておくお金が大きくなり、資金繰りを圧迫します。" },
      { key:'faq_xhkk_gijiroku', faq:1, grp:'hkk', q:"法人の保険の加入や退職金で議事録は要る？", re:/議事録|(取締役会|株主総会)(の)?(決議|承認)[^。]{0,8}(保険|退職金|要る|必要)|(保険|退職金)[^。]{0,10}(取締役会|株主総会)/, head:"役員の退職金や報酬は株主総会などで決めるのが原則で、決めたことは議事録に残しておくのが基本です。", body:"役員の退職金や報酬の額は、定款か株主総会の決議で決める仕組みが会社法にあります。保険に入るときも、会社の大きな支出として取締役会などで決める会社があります。議事録は、何をいつ誰が決めたかの記録で、税の場面や事業を継ぐ場面で、会社の判断を説明する材料になります。", acts:["役員の退職金の規程と、過去の議事録があるかを社長に伺う", "議事録の作り方は、司法書士や顧問の税理士に確かめていただく", "議事録の文面をこちらで作らない"], actHead:"現場で使うなら", note:"決議の要否と議事録の作り方は会社の定款と会社法、司法書士・弁護士、税の場面での扱いは顧問の税理士で確かめる。", say:"役員の退職金などは、会社で決めたことを議事録に残しておくと、あとで説明が必要になったときの材料になります。作り方は専門の先生に確かめていただくのが確かです。", more:"よくある勘違いは、小さな会社では社長が決めれば議事録は要らないと考えることです。役員の退職金を払うときなどは、決めた手続きが記録として求められることがあります。保険の話では、退職金の規程と決議の記録がそろっているかを先に確かめると、受け取ったお金の使い道がはっきりします。", why:"役員の報酬や退職金は、役員自身が受け取るお金なので、株主の目の届く形で決める仕組みになっているからです。記録が残っていると、会社の判断が正しい手続きで行われたことを示せます。" },
      { key:'faq_xhkk_zouka_unten', faq:1, grp:'hkk', q:"売上が伸びているのにお金が足りないのはなぜ？", re:/(売上|業績)が(伸び|増え|上が)[^。]{0,14}(お金|資金|現預金)[^。]{0,6}(足りな|減|苦し|厳し)|黒字なのに[^。]{0,8}(お金|資金|現預金)[^。]{0,6}(減|足りな|無い|ない)|(売上|業績)が伸びるほど[^。]{0,6}(資金|お金)が(要る|必要)/, head:"売上が伸びると入金より先に支払いが増え、黒字でも手元のお金が足りなくなります。", body:"売上が増えると、売掛金と在庫が増え、その分のお金を会社が先に用意することになります。入金が支払いより遅い会社ほど、売上の伸びに合わせて用意するお金も大きくなります。設備の購入や借入の返済が重なると、黒字でも資金繰りが苦しくなります。", acts:["売掛金・在庫・買掛金の動きを、数年分の決算書で社長と一緒に見る", "資金繰り表で、お金が少なくなる月を先に確かめる", "借入の相談は取引の金融機関、数字の解釈は顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"運転資金の考え方と借入の相談は取引の金融機関、数字の解釈は顧問の税理士で確かめる。", say:"売上が伸びるときほど、入金より先にお金が出ていくので、手元のお金が足りなくなることがあります。資金繰り表で、少なくなる月を先に確かめておきましょう。", more:"場面の例としては、大きな取引が決まって仕入れと人を増やした会社が、利益は出ているのに支払いの月にお金が足りなくなる形です。よくある勘違いは、黒字なら資金繰りの心配は無いと考えることです。こうした時期に社長に万一があると影響が大きいので、事業保障の話の背景にもなります。", why:"利益は売上を立てたときに数えますが、お金は入金されてから増え、支払いは先に来るからです。売上が伸びるほど、この間に立て替えるお金が大きくなります。" },
      { key:'faq_xhkk_jinkenhi', faq:1, grp:'hkk', q:"社員を一人増やすと会社にどんなお金がかかる？", re:/(社員|従業員|人)を[^。]{0,4}(増やす|雇う|採用する)[^。]{0,10}(お金|費用|かかる|掛かる|固定費)|人件費(の)?全体|給料(の)?ほかに[^。]{0,6}(何が|かかる|掛かる)|(採用|雇用)で[^。]{0,4}増える[^。]{0,4}(固定費|費用|お金)/, head:"社員を雇うと、給料のほかに会社の社会保険料の負担・採用や教育の費用・福利厚生などのお金がかかります。", body:"給料と賞与に加えて、健康保険・厚生年金・雇用保険・労災保険の会社の負担分、通勤手当、採用の広告や面接の手間、教えるための時間、退職金の準備、福利厚生などがかかります。人件費は毎月出ていく固定費になり、売上が落ちても簡単には減らせません。", acts:["今の人件費の中身を、給料と会社の負担に分けて社長と一緒に書き出す", "人を増やす計画を、資金繰り表と事業計画に入れていただく", "社会保険の会社の負担は社会保険労務士、費用の扱いは顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"会社の社会保険料の負担の率と対象は社会保険労務士、人件費の会計の扱いは顧問の税理士で確かめる。", say:"社員を一人増やすと、給料のほかにも会社が負担するお金がいくつもあります。人件費の中身を書き出しておくと、計画も備えも考えやすくなります。", more:"よくある勘違いは、人件費は給料の額だけで考えることです。会社の社会保険料の負担や教育の時間を足すと、毎月の固定費はもっと大きくなります。社員が増えた会社では、社長に万一があったときにまかなう固定費も増えるので、事業保障の額を見直すきっかけになります。", why:"人を雇う会社には、法律で決まった社会保険料の負担があり、採用や教育にもお金と時間がかかるからです。全体をつかむと、売上が落ちたときに会社が持ちこたえる力が見えます。" },
      { key:'faq_xhkk_suunenbun', faq:1, grp:'hkk', q:"決算書を数年分並べる意味は？", re:/決算書[^。]{0,6}(数年分|何期分|数期分|一期分)|前の期と(比べ|並べ)/, head:"決算書は数年分を並べると、一期だけでは見えない会社の動きと、社長が気にしていることが見えてきます。", body:"一期分の決算書は、その年の一時点の姿です。数年分を並べると、売上と利益が伸びているか落ちているか、借入が増えているか減っているか、手元のお金や純資産がどう動いているかが分かります。大きく動いた年には、設備投資・代替わり・取引先の変化など、社長に伺うきっかけがあります。", acts:["社長の了承を得て、数年分の決算書を見せていただく", "大きく動いた年の理由を、社長の言葉で伺う", "数字の解釈は、顧問の税理士に確かめていただく"], actHead:"現場で使うなら", note:"決算書の数字の解釈と会計の処理の違いは顧問の税理士で確かめる。お預かりした資料は社内の決まりに沿って扱う。", say:"決算書は数年分を並べると、会社がどんな道を歩んできたかが見えてきます。大きく動いた年のお話を、ぜひ聞かせてください。", more:"よくある勘違いは、最新の一期分だけで会社の調子を判断することです。たまたま大きな取引があった年や、建物を売った年は、数字が大きく振れます。数年分の動きを見て、社長に理由を伺うと、数字の裏にある予定や心配ごとが分かり、保険の役目の話にもつながります。", why:"会社の数字は年ごとに出来事で振れるので、一つの年だけでは傾向が分からないからです。並べると、社長が実感していることと数字が結びつき、話が具体的になります。" },
      /* kkl.json */
      { key:'faq_xkkl_sakidori', faq:1, grp:'kkl', q:"先取り貯蓄は、どう始めればいい？", re:/先取り(貯蓄|貯金|で貯め)|給料から先に(貯め|よけ|分け|移)|残ったら貯め[^。]{0,10}(貯まらな|続かな|できな)/, ng:/法人|会社の|部下/, head:"給料が入った日に、貯める分を先に別の口座へ移す仕組みにします。", body:"残ったら貯めるやり方だと、使ったあとの残りが毎月変わり、貯まる額が安定しません。給料日に貯める分を先に分け、残りで暮らす形にすると、意志に頼らずに続きます。額は無理なく続けられる額から始め、暮らしに慣れてから見直します。使う時期が決まっているお金と、いざというときのお金は、口座を分けておくと取り崩しを防げます。", acts:["給料日に自動で移る積立や振替の仕組みがあるか、お使いの金融機関で確かめる", "最初の額は、毎月の暮らしが苦しくならない額にする", "貯めるお金の使い道（いざというとき・教育・老後）ごとに、置き場所を分ける", "ライフプランツールの預貯金の欄に今の貯えを入れ、先の見通しを見る"], actHead:"現場で使うなら", note:"自動の積立や振替の仕組みと手数料はお使いの金融機関で、勤め先の積立の制度は勤め先の窓口で確かめる。", say:"貯金は、残ったらではなく、給料日に先に分ける形にすると続きやすいです。まずは無理のない額から始めてみませんか。", more:"先取りの額を大きくしすぎると、月の途中で足りなくなって取り崩し、かえって続かなくなります。最初は小さく始め、しばらく続いたら額を上げるくらいがちょうどよい進め方です。ボーナスや臨時の収入は、毎月の額とは別に、使い道を決めてから分けます。", why:"人は手元にあるお金を使ってしまいやすく、残りを貯める形は意志の強さに左右されるからです。先に分ける仕組みにすると、毎月考えなくても同じ流れで貯まります。" },
      { key:'faq_xkkl_tedori', faq:1, grp:'kkl', q:"ライフプランは、額面と手取りのどちらで考える？", re:/(額面|手取り)[^。]{0,14}(どちら|どっち|ライフプラン|家計|で考え|で入れ|を使)/, ng:/役員報酬|社長|法人|部下/, head:"暮らしに使えるのは手取りなので、家計の見通しは手取りで立てます。", body:"給料の額面から、税金と社会保険料が引かれた残りが手取りです。毎月の生活費や貯金は手取りから出すので、家計の見通しは手取りで立てます。昇給や働き方の変化で、手取りの増え方は額面と同じにはなりません。ライフプランツールは額面の年収を入れると手取りの目安を出すので、源泉徴収票の額面を入れ、目安を実際の振込額と見比べます。", acts:["源泉徴収票の支払金額（額面）と、毎月の振込額（手取り）の両方を用意していただく", "家計の支出と貯金は、手取りの額から割り振る", "手取りの目安と実際の振込額が大きく違えば、引かれているものを給与明細で確かめる"], actHead:"現場で使うなら", note:"税金と社会保険料の細かな計算は、税理士や勤め先の担当の窓口で確かめる。", say:"暮らしに使えるのは手取りなので、家計は手取りで見ていきます。源泉徴収票と、毎月の振込額を一緒に見せていただけますか。", more:"手取りは、扶養する家族・住民税・社会保険料の変わり目などで、同じ額面でも人によって違います。共働きのご家庭では、お二人それぞれの手取りを分けて見ると、どちらかが働き方を変えたときの影響がつかみやすくなります。", why:"額面で家計を組むと、引かれる分を見落として、毎月の暮らしが計画より苦しくなるからです。手取りで考えると、実際に使えるお金と計画がそろいます。" },
      { key:'faq_xkkl_bonus', faq:1, grp:'kkl', q:"ボーナスは、家計にどう組み込めばいい？", re:/(ボーナス|賞与)[^。]{0,12}(家計|組み込|生活費|使い道|当てに|あてに|どう使|回して)/, ng:/住宅ローン|ローンの|法人|会社の|社員の|部下|払い/, head:"ボーナスは毎月の暮らしに入れず、使い道を先に決めて分けます。", body:"ボーナスは会社の業績などで額が変わり、出ない年もあります。毎月の生活費をボーナスで埋める形にすると、出なかった年に家計が回らなくなります。毎月の暮らしは給料の手取りで回し、ボーナスは年に一度の大きな支払い・貯金・家族の楽しみなど、使い道を先に決めて分けます。", acts:["毎月の赤字をボーナスで埋めていないか、一年分の家計を見て確かめる", "ボーナスの使い道を、大きな支払い・貯金・楽しみに分けて決めておく", "ライフプランツールでは、収入を少なめに入れた場合の見通しも見ておく"], actHead:"現場で使うなら", note:"ボーナスの支給の決まりは勤め先の規程で、手取りの額は給与明細で確かめる。", say:"ボーナスは出ない年もあるので、毎月の暮らしは給料で回し、ボーナスは使い道を決めて分けておくと安心です。", more:"住宅ローンのボーナス払いや、保険料の年払いをボーナスに頼っている家計は、出なかった年の手当てを先に考えておきます。ボーナスの一部を、次の年の大きな支払いのために取っておく形も一つの方法です。", why:"ボーナスは額が決まっていないお金なので、決まった支払いに当てると、変わったときに家計全体が揺れるからです。" },
      { key:'faq_xkkl_tokubetsuhi', faq:1, grp:'kkl', q:"年に一度の大きな出費には、どう備える？", re:/年に一度の(大きな)?(出費|支払)|特別費|毎年(の|決まった時期の)[^。]{0,4}大きな(出費|支払)/, ng:/法人|会社の|経費/, head:"毎年来る大きな支払いを書き出し、毎月少しずつ分けておきます。", body:"車検・自動車の税金・固定資産税・帰省・家電の買い替えなど、毎月ではないが毎年のように来る支払いは、来た月だけ家計が赤字になります。一年分を書き出して合計し、月ごとに割った額を別の口座に分けておくと、その月に慌てずに済みます。ライフプランツールでは、大きな出費をライフイベントとして入れておくと、先の見通しに入ります。", acts:["去年の通帳やカードの明細から、毎月ではない支払いを書き出す", "合計を月の数で割り、毎月その額を別の口座へ移す", "車の買い替えやリフォームのような数年ごとの出費は、ライフイベントに入れる"], actHead:"現場で使うなら", note:"税金の額と納める時期は、市区町村の窓口や税理士で確かめる。", say:"毎年来る大きな支払いを一度書き出して、毎月少しずつ分けておくと、その月だけ苦しくなるのを防げます。", more:"書き出すと、思っていたより多いことがよくあります。保険料の年払い・会費・冠婚葬祭も入れます。分けた口座のお金は、ほかの用途に使わないことが続けるコツです。", why:"毎月の家計だけを見ていると、年に一度の支払いが抜け落ち、来るたびに貯金を取り崩すことになるからです。" },
      { key:'faq_xkkl_saifu', faq:1, grp:'kkl', q:"夫婦で財布が別々の家計は、どう整える？", re:/(財布|家計)が別々|別財布|お互いの(貯金|貯蓄|収入)[^。]{0,8}(知らな|分からな)/, ng:/部下|社長|法人|離婚/, head:"財布は別のままで構いません。全体の数字だけを一度、二人で並べます。", body:"別々の財布には、それぞれが自由に使える良さがあります。困るのは、家族全体でどれだけ貯まっていて、教育費や老後にどれだけ回せるのかが誰にも見えないことです。収入・毎月の負担・貯金を、細かい使い道までは出さずに全体の数字だけ並べると、家族としての見通しが立ちます。共通の支払いの分け方と共通の貯金の額を決めておくと、話し合いが続けやすくなります。", acts:["お二人の手取り・共通の支払い・貯金の合計だけを、一枚に並べる", "住まい・教育・老後の費用を、誰がどれだけ受け持つかを決める", "ライフプランツールに夫と妻の収入を分けて入れ、家族全体の見通しを見る"], actHead:"現場で使うなら", note:"お二人の収入や貯金の扱いはご家族で決めること。贈与などの税の扱いは税理士で確かめる。", say:"財布は別のままで大丈夫です。まずは家族全体の数字だけを並べて、教育費や老後にどれだけ回せるかを一緒に見てみませんか。", more:"どちらか一方だけが家計を把握している場合、その方が病気やけがで動けなくなると、もう一方が家計を回せなくなります。口座や保険の一覧を、二人とも分かる場所に置いておくことも大事です。", why:"家族のお金の見通しは、全体の数字がそろわないと立たないからです。細かい使い道まで出さなくても、合計だけで教育費や老後の話はできます。" },
      { key:'faq_xkkl_hikiotoshi', faq:1, grp:'kkl', q:"毎月の引き落としを洗い出すには？", re:/引き落とし[^。]{0,10}(洗い出|把握|多すぎ|見直|一覧|整理)|サブスク|定額(の)?サービス/, ng:/失効|残高不足|できなかった|法人|会社の/, head:"通帳とカードの明細を並べ、毎月決まって出ていくものに印を付けます。", body:"引き落としは自動で出ていくので、契約したまま忘れているものが残りやすい支出です。口座の通帳とカードの明細を並べ、毎月・毎年決まって出ていくものを一覧にします。使っていないサービス・重なっている契約・家族が別々に払っているものが見つかったら、やめる・まとめる・続けるを家族で決めます。", acts:["口座の通帳とカードの明細から、決まって出ていくものを一覧にする", "一覧の横に、使っているか・誰が使うかを書き、やめるものを家族で決める", "年払いのものも忘れずに入れ、年に一度の出費の備えに回す"], actHead:"現場で使うなら", note:"解約の手続きと解約金の有無は、それぞれのサービスの窓口で確かめる。", say:"引き落としは忘れたまま残りやすいので、一度明細を一緒に並べて、使っていないものがないか見てみませんか。", more:"保険料も引き落としの一つですが、保険は外す前に、外したあとに何が残らなくなるかを確かめます。病気になると入り直せないことがあるからです。保険の見直しは、公的な保障と勤め先の制度を確かめてから進めます。", why:"一つ一つの額は小さくても、自動で出ていく支払いは毎月積み重なり、気づかないうちに家計を圧迫するからです。" },
      { key:'faq_xkkl_kuruma', faq:1, grp:'kkl', q:"車にかかるお金は、ライフプランにどう入れる？", re:/車(の|に)[^。]{0,6}(維持費|お金|買い替え|費用)[^。]{0,12}(ライフプラン|家計|入れ|見る|考え)|車を持つと[^。]{0,10}(全部|全体|どれくらい|いくら)/, ng:/自動車保険|任意保険|事故|保険料|法人|社用車|経費/, head:"買う費用と持ち続ける費用を分けて、買い替えの時期ごとに入れます。", body:"車のお金は、買うときの費用と、持っているあいだの費用に分かれます。持っているあいだの費用には、税金・車検・保険料・駐車場・ガソリン・整備があります。ライフプランツールでは、毎月かかる分は生活費に、買い替えはライフイベントの車の買い替えとして時期と額を入れると、将来の見通しに入ります。家族の人数や通勤で、台数や乗り続ける期間が変わる点も話しておきます。", acts:["毎月の駐車場・ガソリン・保険料を、生活費の中で確かめる", "車検や税金は、年に一度の大きな出費として分けておく", "次に買い替える時期と、乗り続ける年数の見込みを家族で話す", "ライフイベントに車の買い替えを入れ、備考に誰の車かを書く"], actHead:"現場で使うなら", note:"自動車の税金の額は自治体で、保険料は保険会社のパンフレットや見積りで確かめる。", say:"車は買うときと持っているあいだで費用が分かれるので、買い替えの時期も入れて、先の見通しを一緒に見てみましょう。", more:"共働きで車が二台ある家庭や、お子さまの送り迎えで車が欠かせない地域では、買い替えが何度も来ます。乗り続ける期間を少し延ばすだけでも、長い目で見た負担が変わります。どの車を選ぶかは、ご家族の暮らし方で決めることです。", why:"車の費用は毎月の分と数年ごとの分が混ざっているので、分けて入れないと、買い替えの年に家計が大きく揺れることに気づけないからです。" },
      { key:'faq_xkkl_shunyugen', faq:1, grp:'kkl', q:"収入が減ったとき、家計で最初にすることは？", re:/(収入|給料|年収|給与)が(減|下が)[^。]{0,14}(家計|見直|最初|何から|どうする|回らな)|収入減/, ng:/法人|会社の業績|役員報酬|部下|保険料が払え|払えな|育休|育児休業|産休/, head:"減った後の手取りで毎月の家計を組み直し、決まった支払いから順に見ます。", body:"収入が減ると、まず毎月の赤字が出ます。減った後の手取りを確かめ、住まい・通信・車・保険など毎月決まって出ていく支払いから順に見ます。貯金を取り崩すなら、いつまで取り崩せるかを先に確かめます。勤め先の手当や公的な給付で使えるものがないかも、あわせて確かめます。ライフプランツールで減った収入を入れて見通しを作り直すと、どこまで続けられるかが見えます。", acts:["減った後の手取りと、毎月の支出を並べて差を出す", "住まい・通信・車など決まった支払いから順に、続けるか変えるかを決める", "保険は外す前に、公的な保障と勤め先の制度で足りる部分を確かめる", "使える給付や手当がないかを、勤め先や市区町村の窓口で確かめる"], actHead:"現場で使うなら", note:"給付や手当の要件は市区町村・ハローワーク・勤め先の窓口で、保険の契約の変え方は保険会社で確かめる。", say:"収入が変わったときは、まず減った後の手取りで毎月の家計を組み直してみましょう。保険をやめる前に、残せる形がないかも一緒に確かめます。", more:"保険料の負担が重いときは、解約だけでなく、保障を減らす・払い方を変えるなどの形があるか保険会社に確かめます。解約すると、同じ条件で入り直せないことがあります。収入が戻る見込みがあるかどうかで、手の打ち方も変わります。", why:"収入が減ったまま前の暮らしを続けると、気づかないうちに貯金が減り続けるからです。先に手取りで組み直すと、どこを変えるかを落ち着いて決められます。" },
      { key:'faq_xkkl_akaji', faq:1, grp:'kkl', q:"毎月の家計が赤字のとき、何から手を付ける？", re:/(家計|毎月)[^。]{0,6}(赤字|足りなくな|マイナス)|貯金を取り崩して(暮らし|生活)/, ng:/法人|会社の|事業|経営|資金繰り|ライフプランツール|試算|老後/, head:"まず支出を書き出し、赤字が毎月の暮らしか、時々の支払いかを分けます。", body:"毎月の暮らしで赤字が出ているなら、住まい・通信・車・保険など決まった支払いから見るのが近道です。年に一度の支払いが来た月だけ赤字なら、毎月少しずつ分けておく形で防げます。カードの分割やリボ払いが重なっている場合は、残高と利息を先に確かめます。取り崩しが続いているときは、貯金がいつまで持つかをライフプランツールで見ておきます。", acts:["通帳とカードの明細から、毎月の支出を書き出す", "赤字が毎月の暮らしからか、時々の支払いからかを分ける", "決まった支払いから、続けるか変えるかを家族で決める", "借入やリボ払いがあれば、残高と利息を確かめる"], actHead:"現場で使うなら", note:"借入の返し方の相談は金融機関や公的な相談の窓口で、給付の扱いは市区町村で確かめる。", say:"赤字のときは、まず何に使っているかを一緒に書き出してみましょう。原因が分かれば、変えるところは案外絞れます。", more:"赤字の家計で新しい保険や積立を足すと、さらに苦しくなります。先に毎月の流れを黒字に戻し、そのあとで将来の備えを考えます。借入の返済が重い場合は、早めに金融機関や公的な相談の窓口に相談します。", why:"原因が分からないまま節約しても、効かないところを削って続かなくなるからです。書き出すと、手を付ける場所が見えます。" },
      { key:'faq_xkkl_naraigoto', faq:1, grp:'kkl', q:"塾や習い事の費用は、ライフプランにどう入れる？", re:/(塾|習い事|月謝)[^。]{0,4}(の|代|を|は|で)?[^。]{0,12}(費用|月謝|お金|家計|ライフプラン|前提|いつまで|続けられ|苦し)/, ng:/部下|法人|学資/, head:"毎月の月謝は生活費に、受験の前の塾代は教育費の山として分けて入れます。", body:"習い事や塾の費用には、毎月の月謝として続く分と、受験の前に増える分があります。毎月の分は、生活費の中で続けられるかを見ます。受験の前に増える分は、学校の費用と同じように教育費の山として、時期と額の見込みを入れます。習い事はお子さまの成長とともに増えたり変わったりするので、ライフプランは時々入れ直します。", acts:["今の習い事の月謝を書き出し、生活費の中に入れる", "受験を考える時期の塾代を、教育費の見込みに足す", "兄弟姉妹がいるときは、費用が重なる時期を確かめる"], actHead:"現場で使うなら", note:"学校や塾の費用の目安は、それぞれの学校の案内や自治体の窓口で確かめる。", say:"習い事や塾は、毎月の分と受験前に増える分を分けて入れると、どの時期に苦しくなりやすいかが見えます。", more:"習い事は、始めると簡単にはやめにくい支出です。いくつも重なる前に、家族でどれを大事にするかを話しておくと、あとで迷いません。教育費は学校の費用だけでなく、通学・制服・部活動の費用もかかります。", why:"習い事や塾は少しずつ増えるので、気づくと毎月の家計を圧迫していることが多いからです。時期を分けて入れると、山が来る前に手を打てます。" },
      { key:'faq_xkkl_shinro', faq:1, grp:'kkl', q:"子どもの進路が決まっていないとき、試算はどう作る？", re:/進路[^。]{0,10}(決まっていな|未定|分からな)|私立か公立か|進学先が(未定|決まっていな)|大学に行くか(分からな|決まっていな)/, ng:/部下|学資/, head:"多めにかかる道で一度作り、ほかの道で作った場合と並べて見ます。", body:"進路はお子さまが決めることで、今の時点で決まっていないのが普通です。試算では、かかる費用が多めの道で一度作っておくと、どの道を選んでも足りなくなりにくくなります。そのうえで、ほかの道で作った場合と並べると、差がどれくらいかが見えます。ライフプランツールは現状と将来の二つのプランを持てるので、進路の違いを入れて見比べられます。", acts:["多めにかかる進路で、教育費を一度入れる", "将来プランに別の進路を入れ、現状と並べる", "進路が見えてきたら、ライフプランを入れ直す"], actHead:"現場で使うなら", note:"学校ごとの費用は、それぞれの学校の案内や自治体の窓口で確かめる。", say:"進路はまだ分からなくて大丈夫です。多めにかかる場合で一度作って、ほかの場合と並べてみましょう。", more:"多めの道で作ると、今の家計では足りないように見えることがあります。不安で決めるのではなく、どの時期にどれだけ差が出るのかを見て、準備の時期を決めます。お子さまが大きくなったら、本人の希望を聞いて入れ直します。", why:"進路は先にならないと決まらないので、一つの道だけで作ると、違う道を選んだときに準備が追いつかないからです。" },
      { key:'faq_xkkl_shiokuri', faq:1, grp:'kkl', q:"大学で一人暮らしをする子の仕送りは、どう見込む？", re:/仕送り|下宿|(子ども|子供|息子|娘)[^。]{0,6}一人暮らし[^。]{0,6}(進学|大学)/, ng:/親(へ|に)|両親(へ|に)|部下|法人/, head:"学費とは別に、住まいと暮らしの費用が在学中ずっと続く前提で入れます。", body:"自宅から通う場合に比べ、一人暮らしでは家賃・暮らしの費用・入学時の引っ越しや家具の費用が加わります。仕送りは在学中ずっと続くので、ライフプランツールでは教育費とは別の支出として、期間と額の見込みを入れます。お子さまのアルバイトや奨学金で受け持つ部分を家族で話して決めておくと、見込みが立てやすくなります。", acts:["進学の候補の地域で、家賃と暮らしの費用の目安を調べる", "入学のときの引っ越し・家具の費用を、その年の出費に足す", "仕送りの額と期間を、教育費とは別に入れる"], actHead:"現場で使うなら", note:"奨学金の要件は、日本学生支援機構や学校の窓口で確かめる。", say:"一人暮らしになると、学費とは別に暮らしの費用が続くので、仕送りの期間も入れて見ておきましょう。", more:"兄弟姉妹が続けて一人暮らしで進学すると、仕送りが重なる時期があります。重なる時期の家計を先に確かめておくと、老後の準備をどこまで続けられるかも見えます。", why:"仕送りは学費と違って目に見えにくく毎月続くので、入れ忘れると在学中の家計の見通しが大きく外れるからです。" },
      { key:'faq_xkkl_kosodate', faq:1, grp:'kkl', q:"子どもが生まれると、家計で何が変わる？", re:/(子ども|子供|赤ちゃん)が生まれ(る|たら|ると|た)[^。]{0,10}家計|(出産|子育て)[^。]{0,8}家計/, ng:/保険|保障|部下|育休|育児休業|終わ|一段落|独立|巣立/, head:"毎月の支出が増え、働き方と住まいの見通しが変わります。両方を入れ直します。", body:"子どもが生まれると、毎月の支出が増え、保育や教育の費用が時期ごとにかかり始めます。育児のための休みや働き方の変化で、収入が一時的に変わることもあります。広い住まいが必要になって、引っ越しや購入を考えるご家庭もあります。ライフプランツールにお子さまを入れると教育費の山がいつ来るかが見えるので、出産を機に入れ直します。", acts:["お子さまの生年月日を入れ、教育費のかかる時期を確かめる", "休みや働き方の変化で、収入がどう変わるかを入れる", "児童手当など受け取れるお金を、使い道を決めて分ける", "万が一のときの備えは、公的な保障から順に確かめる"], actHead:"現場で使うなら", note:"手当や給付の要件は市区町村の窓口で、休みの間の給付は勤め先やハローワークで確かめる。", say:"お子さまが生まれると、教育費の山がいつ来るかが見えてきます。この機会に、ご家族の見通しを一緒に入れ直してみませんか。", more:"子育て期は、収入が変わる時期と支出が増える時期が重なります。ご夫婦どちらかが働き方を変えるなら、その期間と戻る時期の見込みも入れておきます。手当は、何に使うかを決めて分けておくと、日々の暮らしに紛れずに残ります。", why:"子どもが生まれると、家計の出入りと先の大きな出費の両方が変わるからです。早めに入れ直すと、準備の期間を長く取れます。" },
      { key:'faq_xkkl_ikukyu', faq:1, grp:'kkl', q:"育休中の家計は、どう回せばいい？", re:/(育休|育児休業|産休)[^。]{0,10}(家計|やりくり|暮らし|生活費)|(育休|育児休業)を取ると家計/, ng:/部下|社員|メンバー|うちの会社|規定|規程|何日|いつから/, head:"給付が入る時期と額の目安を確かめ、入るまでの分を貯金から見込んでおきます。", body:"育児休業のあいだは、給料の代わりに雇用保険から給付が出る仕組みがあります。ただ、給付は申請してから振り込まれるまでに時間がかかり、最初の入金までは貯金で暮らすことになります。社会保険料の扱いが変わるなど、手取りの変わり方は人によって違います。ライフプランツールで休む期間と戻る時期を入れ、その期間の家計を見ておきます。", acts:["給付の額の目安と振り込まれる時期を、勤め先とハローワークで確かめる", "最初の入金までの暮らしの分を、貯金から分けておく", "戻ったあとの働き方と保育の費用も、続けて入れる"], actHead:"現場で使うなら", note:"給付の要件と額は勤め先の担当の窓口とハローワークで、社内の制度は御社の規程で確かめる。", say:"育休中は給付が入るまでに時間がかかることがあるので、その間の暮らしの分を先に見ておくと安心です。", more:"夫婦で育休を取る場合は、取る順番や期間で家計の変わり方が違います。戻ったあとに働く時間を短くするなら、その期間の手取りも入れます。保育の費用は住んでいる地域や働き方で変わるので、自治体で確かめます。", why:"給付は給料と入る時期が違うので、いつ・どれだけ入るかを知らないと、休みの最初の時期に家計が苦しくなるからです。" },
      { key:'faq_xkkl_kodomo_okane', faq:1, grp:'kkl', q:"子どもにお金のことは、どう教えればいい？", re:/(子ども|子供|息子|娘)(に|へ)[^。]{0,6}お金[^。]{0,10}(教え|伝え)|お小遣い|子ども向けのお金の教育/, ng:/部下|法人|贈与|相続|学資|保険|へのお金の教え方/, head:"少しずつ任せて、自分で選んで使う経験を積んでもらいます。", body:"お金の使い方は、話を聞くより、自分で選んで使ってみて身につきます。お小遣いを決まった額で渡し、使い道を本人に任せると、足りなくなる経験も含めて学べます。大きくなったら、欲しいものに向けて貯める・家族の買い物の予算を一緒に考えるなど、任せる範囲を広げます。家族のお金の話を隠しすぎずに伝えることも助けになります。", acts:["お小遣いの額と渡す日を決め、使い道は本人に任せる", "欲しいもののために貯める経験を、一緒に計画する", "家族の旅行や買い物の予算を、子どもと一緒に考える"], actHead:"現場で使うなら", note:"子ども名義の口座や贈与の扱いは、金融機関の窓口と税理士で確かめる。", say:"お金の使い方は、実際に任せてみると身につきます。お小遣いの使い道を、お子さまに選んでもらうところから始めてみませんか。", more:"失敗しても大きな額にならないうちに経験しておくと、大人になってからの失敗を小さくできます。電子マネーやゲームの課金など目に見えないお金の使い方も、早いうちから話しておくと安心です。", why:"お金の判断は、経験を重ねて身につくものだからです。小さな額で選ぶ練習をしておくと、大きなお金を扱うときに落ち着いて考えられます。" },
      { key:'faq_xkkl_taishokukin_loan', faq:1, grp:'kkl', q:"退職金で住宅ローンを一括で返すべき？", re:/退職金[^。]{0,10}(住宅ローン|ローン)|(住宅ローン|ローン)[^。]{0,10}退職金|ローンが(退職|定年)(後|のあと)も残/, ng:/法人|役員退職金|社長|部下|社員の/, head:"返した後に手元に残るお金で、老後と急な出費をまかなえるかを先に見ます。", body:"退職金で返すと、利息の支払いは止まりますが、手元のお金は大きく減ります。老後は収入が年金中心になり、急な出費や介護・住まいの修繕に使えるお金が手元にあるかが大事です。返すかどうかは、ローンの残りと金利、返した後に残る貯え、毎月の返済を年金で続けられるかを並べて決めます。団体信用生命保険が付いている場合、返すとその保障もなくなります。", acts:["ローンの残りと金利、毎月の返済額を返済予定表で確かめる", "返した場合と返さない場合で、手元に残るお金の見通しを並べる", "団体信用生命保険がなくなった後の、万が一の備えを確かめる"], actHead:"現場で使うなら", note:"ローンの返し方と手数料は金融機関で、退職金の税の扱いは税理士で確かめる。", say:"退職金で返すかどうかは、返した後に手元にどれだけ残るかで決めるのが大事です。両方の場合を並べて見てみませんか。", more:"一部だけ返して毎月の返済を軽くする形もあります。金利が低いローンなら、手元に置いたまま返し続ける考え方もあります。どちらが合うかは、ご家族の暮らし方と手元の安心で決めます。", why:"一度返したお金は取り戻せないので、老後の急な出費に備える分まで返してしまうと、あとで困るからです。" },
      { key:'faq_xkkl_nagaiki', faq:1, grp:'kkl', q:"ライフプランは、何歳まで生きる前提で作る？", re:/何歳まで(生き|の前提|で試算|見れば|見る)|寿命[^。]{0,8}(何歳|前提|試算)|長生き(した場合|したとき|のリスク)[^。]{0,8}(お金|考え|備え)/, ng:/部下|法人|ペット|保険金/, head:"長めの年齢まで作っておき、お金が先に尽きない形かを確かめます。", body:"平均の寿命まで作ると、それより長く生きたときのお金が試算に入りません。寿命は誰にも分からないので、長めの年齢まで作っておくと、長生きしたときも暮らしが続くかを確かめられます。ライフプランツールでは、ご夫婦それぞれの年齢ごとに、預貯金がどう動くかを先まで見られます。長生きに備える形として、公的年金が生きている限り受け取れる仕組みも話しておきます。", acts:["ご夫婦それぞれの長めの年齢まで、預貯金の動きを見る", "お金が尽きる年齢が出たら、働き方・支出・受け取り方で変えられる部分を探す", "公的年金の受け取り方の選び方は、年金事務所で確かめる"], actHead:"現場で使うなら", note:"年金の受け取り方と見込みは、年金事務所や日本年金機構のねんきん定期便で確かめる。", say:"寿命は分からないので、長めの年齢まで見ておくと安心です。どこまでお金が続くかを一緒に確かめてみましょう。", more:"ご夫婦では、どちらかが一人になった後の暮らしの期間も考えます。一人になると、年金の受け取り方や住まいの費用が変わることがあります。試算でお金が尽きる年齢が出ても、不安で決めず、変えられることを順に探します。", why:"長生きは喜ばしいことですが、お金の面では準備した期間より暮らしが長く続くことになるからです。長めに見ておくと、その心配を前もって減らせます。" },
      { key:'faq_xkkl_shuuzen', faq:1, grp:'kkl', q:"持ち家の修繕費は、ライフプランにどう入れる？", re:/(修繕|リフォーム|外壁|屋根)[^。]{0,12}(費用|お金|ライフプラン|見通し|見込|入れ|上が)/, ng:/火災保険|保険金|保険で|地震|台風|雨漏り|減税|控除|補助/, head:"修理の時期と額の目安を、ライフイベントとして先に入れておきます。", body:"持ち家は、年数がたつと外壁・屋根・水回り・設備の修理や交換が来ます。賃貸と違い、その費用は持ち主が受け持ちます。ライフプランツールでは、住まいの欄の修繕・管理の費用に毎年の分を入れ、大きな修理やリフォームはライフイベントとして時期と額の見込みを入れます。マンションは、修繕積立金と管理費の変わる予定を、管理組合の長期の計画で確かめます。", acts:["建てた時期や前の修理の時期から、次の修理の時期の目安を立てる", "大きな修理やリフォームを、ライフイベントに時期と額で入れる", "マンションは長期の修繕の計画と、積立金の変わる予定を確かめる"], actHead:"現場で使うなら", note:"修理の時期と費用の目安は施工会社や管理組合で、補助や減税の要件は自治体と税理士で確かめる。", say:"持ち家は修理の時期が来るので、先に見通しに入れておくと、その年に慌てずに済みます。", more:"修理を後回しにすると、傷みが広がって費用が大きくなることがあります。老後に入ってからの大きな修理は年金の暮らしの中で受け持つことになるので、退職の前に済ませるか、分けて貯めておくかを考えます。", why:"修繕の費用は毎月の家計には出てこないので、見通しに入れないと、来た年に貯金を大きく取り崩すことになるからです。" },
      { key:'faq_xkkl_ichiran', faq:1, grp:'kkl', q:"家族全員の保険を、一覧にするには？", re:/(家族|夫婦|家庭)[^。]{0,8}(保険|保障)[^。]{0,10}(一覧|一枚|まとめ|整理)|(どの|どんな)保険に入っているか[^。]{0,8}(分からな|知らな)|保険証券[^。]{0,8}(整理|一覧|まとめ)/, ng:/法人|会社の|社員|部下|団体/, head:"証券を集めて、誰に・何が起きたら・いくら・いつまで出るかを一枚に並べます。", body:"保険は家族それぞれが別々の時期に入っていることが多く、全体を知っている人がいないことがあります。証券や契約の案内を集め、被保険者・保障の中身・受取人・保障が続く期間・保険料を一枚に並べます。並べると、重なっている保障や、足りない時期が見えてきます。勤め先の団体保険や共済も、分かる範囲で一緒に入れます。", acts:["家にある保険証券・契約の案内・共済の書類を集める", "被保険者・保障の中身・受取人・期間・保険料を一枚に並べる", "保険会社のお客様向けの画面や窓口で、今の契約の中身を確かめる", "一覧の置き場所を、家族の誰もが分かるところにする"], actHead:"現場で使うなら", note:"今の契約の中身と保障の範囲は、各保険会社の窓口や約款で確かめる。", say:"まずは家族の保険を一枚に並べてみませんか。重なっているところと、足りないところが見えてきます。", more:"証券が見つからないときは、口座の引き落としの記録から保険会社を探せます。一覧には、連絡先と担当者も書いておくと、いざというときに家族が請求の連絡をしやすくなります。", why:"保険は持っていても、中身を家族が知らなければ、いざというときに請求できないからです。一覧にすると、見直しの話も同じ紙の上でできます。" },
      { key:'faq_xkkl_kouteki_saki', faq:1, grp:'kkl', q:"保険の見直しは、何から順に確かめる？", re:/(保険|保障)(の|を)?見直(し|す)[^。]{0,8}(何から|順番|順に|前に|手順)|保険を減らす前に|見直しの順番/, ng:/法人|会社の|社員|部下|火災|自動車|車|家財|地震/, head:"公的な保障、勤め先の制度、貯え、の順に確かめ、足りない分を保険で埋めます。", body:"万が一のときのお金は、公的な保障・勤め先の制度・貯えで受け持てる分があります。例えば、亡くなったときの遺族年金、病気やけがのときの高額療養費や傷病手当金、勤め先の死亡退職金や弔慰金です。これらを先に確かめ、それでも足りない時期と額を保険で埋めると、重なりも抜けも減ります。ライフプランツールでご家族の見通しを作ってから、保険の話に進みます。", acts:["ねんきん定期便と勤め先の福利厚生の案内を用意していただく", "公的な保障と勤め先の制度で受け持てる分を書き出す", "残る分を、今の保険で受け持てているかを並べる", "外す保険があれば、外したあとに入り直せるかを先に確かめる"], actHead:"現場で使うなら", note:"公的な保障の要件は年金事務所や健康保険組合・協会けんぽで、勤め先の制度は勤め先の規程で確かめる。", say:"保険を考える前に、公的な保障と勤め先の制度で受け持てる分を一緒に確かめてみませんか。足りない分だけを保険で考えられます。", more:"公的な保障は、働き方や加入している年金・健康保険で中身が変わります。会社員と自営業では、遺族年金や傷病手当金の有無が違うので、同じ保障額では合わないことがあります。共働きでは、お二人それぞれについて確かめます。", why:"公的な保障や勤め先の制度を知らずに保険を組むと、既にある保障と重なって保険料が重くなったり、逆に足りない時期を見落としたりするからです。" },
      { key:'faq_xkkl_dokuritsu', faq:1, grp:'kkl', q:"子どもが独立したら、家計で何を見直す？", re:/(子ども|子供|息子|娘|末っ子)が(独立|巣立|社会人にな|就職し)|子育てが(終わ|一段落)/, ng:/法人|部下|事業承継|後継|要りません|要らない|いらない|不要|必要ない|必要ありません|もう保険|からにします|から考えます|まで待ちます/, head:"教育費が終わった分を老後の準備に回し、遺族の備えの大きさを見直します。", body:"子どもが独立すると、教育費や子どもの暮らしの費用がかからなくなり、家計に余裕が出やすい時期になります。この時期は、老後の準備に回せる期間が残り少なくなる時期でもあります。家族のための死亡保障は、子どもが独立すると必要な大きさが変わることが多いので、ご夫婦お二人の暮らしに合わせて見直します。ライフプランツールで、子どもの独立のあとの見通しを入れ直します。", acts:["教育費が終わった分を、毎月どこに回すかを決める", "ご夫婦だけになった後に必要な備えの大きさを確かめる", "医療や介護の備えと、老後のお金の準備を並べて見る"], actHead:"現場で使うなら", note:"保険の保障の変え方と、変えたときの扱いは保険会社の窓口で確かめる。", say:"お子さまが独立されたら、教育費の分を老後の準備に回せる時期です。ご夫婦お二人の見通しで一緒に入れ直してみませんか。", more:"教育費の分がそのまま毎月の暮らしに消えてしまうと、老後の準備の期間を活かせません。独立の前に、浮く分の使い道を決めておくと残りやすくなります。お子さまの結婚や住宅の援助を考える場合は、その額と時期も入れます。", why:"子どもの独立は、家計の大きな支出が終わり、守る相手も変わる節目だからです。そのままにすると、必要以上の保障を払い続けたり、老後の準備が遅れたりします。" },
      { key:'faq_xkkl_hatarakikata', faq:1, grp:'kkl', q:"夫婦の片方が働き方を変える前提の試算は、どう作る？", re:/働き方を変え[^。]{0,12}(試算|ライフプラン|見通し|収入|家計|前提)|(パート|扶養内)に(変え|切り替え)[^。]{0,10}(ライフプラン|家計|見通し|どうな)|(どちらか|片方)が[^。]{0,4}(仕事を辞め|退職)[^。]{0,10}(見通し|家計|試算|ライフプラン)/, ng:/部下|社員|法人|うちの会社|規定|規程/, head:"変える時期・期間・戻る見込みを入れ、変えない場合と並べて見ます。", body:"働き方を変えると、収入だけでなく、社会保険や年金の加入のしかた、将来の年金の見込みも変わることがあります。試算では、いつから・どれくらいの期間・戻る見込みがあるかを入れます。ライフプランツールの現状プランに今の働き方、将来プランに変えた場合を入れて並べると、どの時期にどれだけ差が出るかが見えます。決めるのはご夫婦で、試算はその材料です。", acts:["変える時期と、続く期間・戻る見込みをご夫婦で話す", "変えた後の手取りと、社会保険の入り方の変わり方を確かめる", "現状と将来の二つのプランで、変える場合と変えない場合を並べる"], actHead:"現場で使うなら", note:"社会保険の加入の条件と扶養の扱いは勤め先と年金事務所で、税の扱いは税理士で確かめる。", say:"働き方を変える場合と変えない場合を並べてみると、どの時期にどれだけ違うかが見えます。決めるのはご夫婦なので、その材料として一緒に作ってみませんか。", more:"収入の壁と呼ばれる線は、税と社会保険で考え方が違い、制度の見直しもあります。収入を抑えるかどうかは、目の前の手取りだけでなく、将来の年金や保障の変わり方も並べて考えます。細かな線は年金事務所と税理士で確かめます。", why:"働き方の変化は、今の収入と将来の年金の両方に響くからです。片方だけを見て決めると、あとで思っていたのと違う見通しになることがあります。" },
      { key:'faq_xkkl_ohitori', faq:1, grp:'kkl', q:"おひとりさまの将来のお金は、どう考える？", re:/(おひとりさま|お一人様|独身|一人)(のまま|で)[^。]{0,8}(暮らす|暮らして|生きて|ライフプラン|将来)|(頼れる|頼る)家族がいな|おひとりさまの将来/, ng:/保険|保障|部下|単身赴任|ひとり親|シングル/, head:"暮らしのお金に加えて、病気・介護・住まい・亡くなった後の手続きを自分で備えます。", body:"一人で暮らしていく場合、収入も支出も自分一人で受け持つので、働けなくなったときの備えが大事になります。老後は、医療や介護が必要になったときに誰に頼むか、住まいをどうするかも先に考えておきます。亡くなった後の手続きや財産の行き先を、元気なうちに決めておく方法もあります。ライフプランツールで、一人の場合の見通しを先まで見ておきます。", acts:["働けなくなったときに、収入をどう受け持つかを確かめる", "老後の住まいと、介護が必要になったときの頼み先を考える", "財産の行き先や亡くなった後の手続きを、どう残すかを考える"], actHead:"現場で使うなら", note:"遺言や任意後見などの手続きは司法書士や弁護士で、公的な制度は市区町村の窓口で確かめる。", say:"お一人の場合は、働けなくなったときと、介護や住まいのことを先に考えておくと安心です。見通しを一緒に作ってみませんか。", more:"遠くに住む兄弟姉妹や甥姪がいる場合、その方に何を頼むかを話しておくと、いざというときに慌てません。財産を誰に残すかは、遺言がないと法律で決まった相続人に行くので、気になる方は専門家に相談します。", why:"一人で暮らす場合は、家族が代わりに動いてくれる場面が少ないので、自分で決めて残しておくことが、将来の安心にそのままつながるからです。" },
      { key:'faq_xkkl_tanshin', faq:1, grp:'kkl', q:"単身赴任で二重の生活費がかかる家計は、どう見る？", re:/単身赴任[^。]{0,10}(家計|生活費|二重|やりくり|ライフプラン|どうなる)|家族と離れて暮らす[^。]{0,6}(やりくり|家計|生活費)/, ng:/部下|社員|法人|うちの会社|規定|規程|手当(の|は|が)(いくら|額|金額)/, head:"赴任先と自宅の二つの暮らしの費用を分けて書き、赴任の期間で見込みます。", body:"単身赴任になると、自宅の暮らしに加えて、赴任先の住まい・食費・光熱費・帰省の交通費がかかります。勤め先の手当や住まいの補助で受け持たれる分を差し引き、残る分を家計で受け持ちます。赴任の期間が分かれば、その期間だけ支出が増える形でライフプランツールに入れます。赴任が終わる時期の見込みも入れておきます。", acts:["赴任先の住まい・食費・光熱費・帰省の費用を書き出す", "勤め先の手当や補助で受け持たれる分を確かめる", "赴任の期間だけ支出が増える形で、見通しに入れる"], actHead:"現場で使うなら", note:"単身赴任の手当や住まいの補助は、勤め先の規程と担当の窓口で確かめる。", say:"単身赴任の間は、二つの暮らしの費用がかかります。手当で受け持たれる分を引いて、残りを一緒に見ておきましょう。", more:"帰省の回数や、家族が赴任先を訪ねる回数で、交通費は大きく変わります。赴任の間に教育費の重い時期が重なる場合は、その時期の家計を先に確かめておきます。", why:"単身赴任の費用は少しずつ積み重なるので、期間が長いほど家計への影響が大きくなるからです。分けて書くと、どこを手当てすればよいかが見えます。" },
      { key:'faq_xkkl_tool_dekiru', faq:1, grp:'kkl', q:"ライフプランツールでは、何ができる？", re:/ライフプランツール(で(は)?|の機能|は)[^。]{0,8}(何ができ|なにができ|何を見せ|何に使|できること|機能)|ライフプランツールの機能/, ng:/部下|法人/, head:"ご家族の収入と支出を入れると、先の預貯金の動きと、気をつけたい点が見えます。", body:"ライフプランツールは、ご家族・収入・住まい・教育・保険・貯えを入れると、年ごとの家計の出入りと預貯金の動きを試算します。現状と将来の二つのプランで見比べ、AI診断が安心できる点と気をつけたい点を両方出します。キャッシュフロー表はPDFにでき、お客様には共有リンクで渡せます。営業サポートには、音声メモ・次の一手・ミーティング概要などがあります。", acts:["サンプルを表示して、画面の流れを一度見ておく", "お客様と一緒に入れる項目と、後で入れる項目を分けておく", "結果は試算の目安であることを、お客様に必ず添えて伝える"], actHead:"現場で使うなら", note:"お客様に資料を渡すときの扱いは、所属保険会社の募集文書の決まりと御社の手順で確かめる。", say:"ご家族の数字を入れると、先の家計の見通しが見えます。一緒に見ながら、気になるところを話していきましょう。", more:"試算は入れた前提で変わります。物価の上がり方・運用の利回り・収入の伸びは、試算の前提として小さく入れてあり、変えると結果も変わります。結果を見せるときは、良いところと気をつけたいところを両方伝え、不安で押す話にしません。", why:"ご家族のお金の見通しは、頭の中だけでは描きにくいからです。数字を年ごとに並べると、お客様ご自身が気づきやすくなります。" },
      { key:'faq_xkkl_tool_nyuryoku', faq:1, grp:'kkl', q:"ライフプランツールは、面談のどこで入力する？", re:/ライフプランツール[^。]{0,12}(入力|入れ)[^。]{0,12}(面談|お客様の前|初回|どこで|いつ|時間がかか|何を)|(面談|初回)[^。]{0,10}ライフプランツール[^。]{0,8}(入力|入れ)|ライフプランツール[^。]{0,12}(面談|初回)[^。]{0,8}(入力|入れ)/, ng:/部下|法人|パスワード|保存/, head:"初回はご家族と収入・住まい・貯えだけ一緒に入れ、細かい所は後で埋めます。", body:"初回の面談で全てを入れようとすると、お客様を待たせてしまいます。ご家族の年齢・収入・住まい・預貯金など大きな項目だけをお客様と一緒に入れ、全体の形を見ていただきます。保険の中身や細かい支出は、証券や明細をお預かりして次回までに入れます。目安のまま残っている入力は件数で出るので、次回に一緒に確かめます。", acts:["面談の前に、分かっている項目だけ入れておく", "面談では大きな項目をお客様と一緒に入れて、形を見ていただく", "目安のままの入力を、次回までに確かめる項目として控える"], actHead:"現場で使うなら", note:"お客様の情報の入力と保存の扱いは、御社の個人情報の取り扱いの決まりと所属保険会社の手順で確かめる。", say:"今日は大きなところだけ一緒に入れて、全体の形を見ていただきますね。細かいところは、次回までにこちらで入れておきます。", more:"お客様と一緒に入れると、数字の意味をその場で話せるので、ご自身の家計として受け止めていただきやすくなります。逆に、事前に全て入れて結果だけ見せると、入れた前提の確かめが抜けやすくなります。", why:"初回の面談で大事なのは、細かい数字より、お客様に自分のこととして見ていただくことだからです。大きな項目だけでも、家計の形は見えます。" },
      { key:'faq_xkkl_tool_plan2', faq:1, grp:'kkl', q:"現状プランと将来プランは、どう使い分ける？", re:/現状(プラン)?と将来(プラン)?|将来プラン[^。]{0,8}(何を|使い|違い|入れ)|二つのプランの違い/, ng:/部下|法人/, head:"現状は今のまま続けた場合、将来は変えたい形を入れて、二つを並べます。", body:"現状プランには、今の暮らし・働き方・貯え方をそのまま続けた場合を入れます。将来プランには、住まいを変える・働き方を変える・積立を始めるなど、考えている変化を入れます。二つを並べると、変えることで先の見通しがどう変わるかが見えます。初回の面談では現状だけを見ていただき、次回に将来の形を一緒に考える進め方もあります。", acts:["現状プランに、今の暮らしをそのまま入れる", "将来プランに、お客様が考えている変化を入れる", "二つの差を、時期と理由で説明する"], actHead:"現場で使うなら", note:"将来の提案を資料にしてお渡しするときの扱いは、所属保険会社の募集文書の決まりで確かめる。", say:"まずは今のまま続けた場合を見ていただき、そのあとで変えたい形と並べてみましょう。違いが一目で分かります。", more:"将来プランに保険や運用の商品を入れて見せるときは、良い点だけでなく注意したい点も同じ場で伝えます。差が大きく見えても、前提で変わることを添えます。お客様が考える変化を先に聞き、こちらの案を押しつけないようにします。", why:"今のままの見通しと、変えた場合の見通しを並べると、お客様ご自身がどこを変えたいかを考えやすくなるからです。" },
      { key:'faq_xkkl_tool_watasu', faq:1, grp:'kkl', q:"ライフプランの試算結果を、お客様に渡していい？", re:/(試算(の)?結果|試算の資料|キャッシュフロー表のpdf|共有リンク)[^。]{0,16}(渡し|送っ|送る|渡す|お渡し|注意)|(ライフプラン|試算)[^。]{0,8}(資料|pdf)[^。]{0,8}(渡|送)/, ng:/部下|法人/, head:"渡す前に、所属保険会社の決まりを確かめ、試算の目安であることを添えます。", body:"試算の資料には、保険や運用の話が載ることがあり、渡し方によっては募集の資料として扱われます。渡す前に、所属保険会社の決まり（募集文書の扱い）と御社の手順を確かめます。資料には、入れた前提と、試算の目安であって結果を約束するものではないことが載っているかを確かめます。共有リンクで送るときは、送り先を間違えないようにします。", acts:["所属保険会社の募集文書の決まりと、御社の手順を確かめる", "資料に試算の前提と注記が載っているかを確かめる", "送り先とお名前を確かめてから送る"], actHead:"現場で使うなら", note:"お客様に渡す資料の扱いは、所属保険会社の決まりと御社のコンプライアンスの担当で確かめる。", say:"こちらは今日の試算をまとめたものです。前提によって変わる目安なので、その点だけご承知おきください。", more:"特定の保険商品を勧める内容や、商品の比較が載る資料は、所属保険会社の審査が要ることがあります。試算の結果だけを渡すのか、提案まで含めるのかで扱いが変わることがあるので、迷うときは渡す前に上長やコンプライアンスの担当に確かめます。", why:"お客様は渡された資料を後から見返し、ほかの方にも見せることがあるからです。決まりに沿った資料にしておくと、お客様にも御社にも安心です。" },
      { key:'faq_xkkl_tool_hozon', faq:1, grp:'kkl', q:"ライフプランツールに入れたお客様の情報は、どこに保存される？", re:/ライフプランツール[^。]{0,16}(保存|パスワード|暗号|どこに残|消え)|お客様の資料は暗号化/, ng:/部下|法人/, head:"お使いの端末のブラウザの中に、ログインのパスワードから作った鍵で暗号化して残ります。", body:"保存したお客様の資料は、お使いの端末のブラウザの中に残ります。資料は、ログインのパスワードから作った鍵で暗号化して置かれます。パスワードを忘れると、誰にも開けなくなります。端末を替えるときや、ブラウザの記録を消すときは、先に控えを取っておきます。お客様の情報を扱う決まりは、御社の個人情報の取り扱いに従います。", acts:["ログインのパスワードを、決まった方法で控えておく", "端末を替える前に、資料の控えを取る", "お客様の情報の扱いを、御社の決まりで確かめる"], actHead:"現場で使うなら", note:"お客様の情報の取り扱いは、御社の個人情報の決まりと所属保険会社の指示で確かめる。", say:"ご入力いただいた内容は、この端末の中に鍵をかけて保存しています。", more:"暗号化していても、端末を手にした人がパスワードを知っていれば開けます。端末の画面のロックや、共用の端末で使わないことも大事です。端末が壊れると資料も開けなくなるので、控えを取る習慣をつけます。", why:"お客様のご家族やお金の情報は、とくに大切に扱う必要があるからです。仕組みを知っておくと、お客様に聞かれたときにも正しく説明できます。" },
      { key:'faq_xkkl_tool_meyasu', faq:1, grp:'kkl', q:"目安のままの入力が残っていると出たら、どうする？", re:/目安のまま/, ng:/部下|法人/, head:"お客様の実際の数字に入れ替えるか、目安のままでよいかを一つずつ確かめます。", body:"ライフプランツールは、入れていない項目に一般的な目安の値を置いて試算します。目安のままの項目が残っていると、その件数が帯で出ます。生活費・年金・保険など、お客様ごとに違いやすい項目ほど、実際の数字に入れ替えると試算の確かさが上がります。分からない項目は、次回までに書類で確かめる項目として控えます。", acts:["帯の件数から、目安のままの項目を確かめる", "お客様の実際の数字が分かる項目から入れ替える", "分からない項目は、確かめる書類と一緒に控える"], actHead:"現場で使うなら", note:"年金の見込みは日本年金機構のねんきん定期便で、保険の中身は保険会社の契約の案内で確かめる。", say:"ここはまだ一般的な目安のままなので、分かる範囲でお客様の数字に入れ替えていきましょう。", more:"目安のままの試算でも全体の形はつかめますが、結果をお客様に渡すなら、どの項目が目安なのかを伝えます。とくに年金と生活費は結果に大きく響くので、ねんきん定期便や家計の明細で確かめます。", why:"目安は一般的な家庭を想定した値なので、そのまま使うと、お客様の家計と離れた結果になることがあるからです。" },
      { key:'faq_xkkl_lp_minaoshi', faq:1, grp:'kkl', q:"ライフプランは、どのくらいの頻度で見直す？", re:/ライフプラン[^。]{0,8}(見直|作り直|更新|入れ直)[^。]{0,10}(頻度|タイミング|いつ|きっかけ|時期)|ライフプラン[^。]{0,12}(頻度|間隔)[^。]{0,8}(見直|作り直|更新|入れ直)|ライフプラン[^。]{0,6}(いつ|どのタイミングで)[^。]{0,6}(見直|作り直|更新|入れ直)/, ng:/部下|法人|保険の見直し/, head:"年に一度と、ご家族の大きな変化があったときに入れ直します。", body:"ライフプランは、作った時点の前提で描いたものなので、暮らしが変わると見通しも変わります。結婚・出産・住宅の購入・転職・子どもの独立・退職などの節目には、入れ直すきっかけになります。大きな変化がなくても、年に一度、収入や貯えを入れ直すと、見通しのずれに早く気づけます。ライフプランツールでは、前回との違いを並べて見られます。", acts:["保存した資料の前回の数字と、今の数字を並べる", "ご家族の節目があったら、その場で入れ直す", "年に一度の見直しの時期を、お客様と決めておく"], actHead:"現場で使うなら", note:"見直しの連絡の方法と記録の残し方は、御社の手順と所属保険会社の決まりで確かめる。", say:"ご家族の暮らしが変わると見通しも変わります。年に一度、数字を入れ直して一緒に確かめませんか。", more:"見直しのときは、前回からどこが変わったかを一緒に見ると、お客様にとって分かりやすくなります。貯えが増えていればそれを一緒に確かめ、ずれていれば理由を探します。責める話にせず、次の一年の形を決める場にします。", why:"ライフプランは作って終わりではなく、暮らしの変化に合わせて直していくことで役に立つからです。" },
      { key:'faq_xkkl_tool_shindan', faq:1, grp:'kkl', q:"ライフプランツールのAI診断の結果は、どう伝える？", re:/ai診断[^。]{0,12}(結果|伝え|話し方|見せ|説明|安心できる点|気をつけたい点)/, ng:/部下|法人|健康/, head:"安心できる点から先に伝え、気をつけたい点は変えられることと一緒に話します。", body:"AI診断は、試算の結果から、安心できる点と気をつけたい点を両方出します。先に安心できる点を伝えると、お客様は落ち着いて話を聞けます。気をつけたい点は、どの時期に何が起きそうかと、変えられることを一緒に話します。AI診断はご入力からの目安で、結果を約束するものではないことも添えます。片方だけを見せる形にはしません。", acts:["安心できる点を先に、お客様の言葉で言い直して伝える", "気をつけたい点は、時期と理由を一緒に確かめる", "変えられることを将来プランに入れ、並べて見る"], actHead:"現場で使うなら", note:"結果の伝え方と資料の扱いは、所属保険会社の募集の決まりと御社の手順で確かめる。", say:"まず、今の家計で安心できるところからお伝えしますね。そのうえで、気をつけたいところと、変えられることを一緒に見ていきましょう。", more:"気をつけたい点だけを強く伝えると、不安で押す話になります。安心できる点も同じ重さで伝え、お客様ご自身がどこを変えたいかを選べるようにします。分野ごとの詳しい欄には、知っておきたい一般的なお話も出るので、会話のきっかけにできます。", why:"お客様は良い点も悪い点も知って初めて、自分で判断できるからです。両方を伝えると、お客様の信頼にもつながります。" },
      { key:'faq_xkkl_lp_nenkin', faq:1, grp:'kkl', q:"ライフプランの年金の額は、何を見て入れる？", re:/(ライフプラン|試算)[^。]{0,12}年金(の額|の見込み|は|を)?[^。]{0,8}(入れ|何を見|定期便)|年金の(額|見込み)を(ライフプラン|試算)に/, ng:/部下|法人|企業年金|個人年金|ideco|イデコ/, head:"ねんきん定期便の見込みの額を入れ、働き方が変わる場合は見直します。", body:"公的年金の見込みは、ねんきん定期便とねんきんネットで確かめられます。ライフプランツールには、ねんきん定期便の数字から見込みを入れる欄があります。若い方の見込みは、今までの加入の分だけの額のことがあり、これから働く分が入っていない場合があります。働き方や受け取り始める時期で額が変わるので、変える予定があれば見直します。", acts:["お客様に、最新のねんきん定期便を用意していただく", "ねんきん定期便の数字から、見込みを入れる", "受け取り始める時期や働き方の変化を、別のプランで試す"], actHead:"現場で使うなら", note:"年金の見込みと受け取り方は、年金事務所や日本年金機構のねんきん定期便とねんきんネットで確かめる。", say:"年金はねんきん定期便の見込みから入れます。次回までに、お手元の最新の定期便を見せていただけますか。", more:"共働きのご夫婦は、お二人それぞれの見込みを入れます。勤め先の企業年金や退職金は公的年金とは別なので、勤め先の案内で確かめて分けて入れます。年金の額は制度の見直しで変わることがあるので、前提として伝えます。", why:"老後の見通しは、年金の見込みで大きく変わるからです。お客様ご自身の定期便の数字を使うと、試算がご家族の実際に近づきます。" },
      { key:'faq_xkkl_lp_shorui', faq:1, grp:'kkl', q:"ライフプランを作るとき、お客様に何を用意してもらう？", re:/(ライフプラン|試算)[^。]{0,12}(用意|準備|必要な書類|資料)[^。]{0,8}(して|もら|は|何|もの)|ライフプランの面談で必要|ライフプランツールに入れるための(資料|書類)/, ng:/部下|法人/, head:"源泉徴収票、ねんきん定期便、保険証券、住宅ローンの返済予定表の四つが基本です。", body:"収入は源泉徴収票、年金の見込みはねんきん定期便、今の保障は保険証券や契約の案内、住宅ローンは返済予定表で確かめます。毎月の支出は、家計簿がなくても通帳やカードの明細でおおよそが分かります。全てがそろわなくても始められ、分からない項目は目安のまま置いて、次回に確かめます。", acts:["面談の前に、用意していただきたい書類を案内する", "そろった書類から順に、数字を入れていく", "そろわない書類は、次回までに確かめる項目として控える"], actHead:"現場で使うなら", note:"お預かりした書類の扱いと返し方は、御社の個人情報の決まりと所属保険会社の手順で確かめる。", say:"源泉徴収票、ねんきん定期便、保険証券、住宅ローンの返済予定表があると、より実際に近い形で作れます。そろわなくても大丈夫です。", more:"書類をお預かりする場合は、預かったものと返す日を記録します。写しをいただく場合も、保管と廃棄の方法を御社の決まりに合わせます。お客様が見せたくない書類は無理に求めず、分かる範囲の数字で作ります。", why:"書類の数字を使うと、思い込みではなくご家族の実際に近い試算になるからです。準備の負担を軽く伝えると、お客様も気軽に用意できます。" },
      { key:'faq_xkkl_lp_iyagaru', faq:1, grp:'kkl', q:"ライフプランを作るのを嫌がるお客様には？", re:/ライフプラン[^。]{0,8}(嫌が|要らな|いらな|作りたくな|断られ)|(お金のこと|家計)[^。]{0,8}(聞かれたくな|見せたくな)/, ng:/部下|法人/, head:"無理に作らず、お客様が気になっていることだけから始めます。", body:"お金のことを細かく話すのは、多くの方にとって気が重いことです。全てを聞こうとせず、お客様が今気になっていること一つから始めます。例えば教育費のことだけ、老後のことだけでも、ご家族の大きな数字で形は見えます。作るかどうかはお客様が決めることで、その場で決めていただく必要はありません。", acts:["お客様が今いちばん気になっていることを一つ伺う", "その話に要る数字だけを、分かる範囲で伺う", "続けるかどうかは、お客様に決めていただく"], actHead:"現場で使うなら", note:"お客様の情報を伺う範囲と記録の残し方は、御社の個人情報の決まりで確かめる。", say:"全部をお聞きするつもりはありません。今いちばん気になっていることだけ、一緒に見てみませんか。", more:"嫌がる理由は、売り込まれる心配・数字を責められる心配・面倒さなど人によって違います。理由を先に伺うと、話し方を変えられます。サンプルの家族で画面の流れを見ていただくと、どんなものか分かって安心されることもあります。", why:"お客様が嫌がる中で無理に聞き出すと、信頼を失ってしまうからです。気になることから始めると、お客様が自分から話してくださる場面が増えます。" },
      { key:'faq_xkkl_tool_sample', faq:1, grp:'kkl', q:"ライフプランツールのサンプルは、どう使う？", re:/(ライフプランツール|画面)[^。]{0,8}(サンプル|見本)|サンプルの家族|サンプルを表示|画面の流れを先に見せ/, ng:/部下|法人/, head:"サンプルの家族で画面の流れを先に見せ、どんなものかを分かっていただきます。", body:"ライフプランツールには、サンプルの家族を表示する機能があります。お客様の数字を入れる前に、サンプルで、入力の画面から結果のグラフやAI診断までの流れを見ていただくと、何をするのかが分かって安心されます。サンプルは架空の家族の入力例で、お客様の結果とは違うことを添えます。見せたあとは、お客様の数字に入れ替えて始めます。", acts:["面談の初めに、サンプルで画面の流れを見ていただく", "サンプルは入力例であることを、はっきり伝える", "お客様の数字に入れ替える前に、保存してある資料と混ざらないか確かめる"], actHead:"現場で使うなら", note:"画面をお客様に見せるときの扱いは、所属保険会社の募集の決まりと御社の手順で確かめる。", say:"まず見本のご家族で、どんな画面になるかを見ていただきますね。これは入力例なので、このあとお客様の数字で作り直します。", more:"サンプルを表示すると、入力中の内容は置き換わります。お客様の入力の途中では使わないようにし、保存してから表示します。サンプルの結果をお客様の見通しと取り違えられないよう、画面を見せる順番に気をつけます。", why:"何をするか分からないまま数字を聞かれると、お客様は構えてしまうからです。流れが見えると、自分のことを話しやすくなります。" },
      { key:'faq_xkkl_lp_event', faq:1, grp:'kkl', q:"ライフイベントは、どう入れればいい？", re:/ライフイベント[^。]{0,10}(入れ|使い方|どう)|(お祝い|記念日|大きな出費)の予定[^。]{0,8}ライフプラン/, ng:/部下|法人/, head:"時期と額の見込みを入れ、備考に誰の何のための出費かを書いておきます。", body:"ライフイベントには、車の買い替え・旅行・リフォームなど、毎月ではない大きな出費を時期と額で入れます。内容の欄を押すと候補が出て、選ぶと一般的な目安が入るので、お客様の予定に合わせて直します。備考に、誰の車か・何のための旅行かを書いておくと、次に見たときに思い出せます。繰り返す出費は、時期ごとに入れます。", acts:["お客様の今後の大きな予定を、時期と一緒に伺う", "候補の目安を、お客様の予定に合わせて直す", "備考に、誰の何のための出費かを書く"], actHead:"現場で使うなら", note:"目安の数字の出どころは画面に小さく出るので、お客様に伝えるときは、前提であることを添える。費用の詳しい見込みは各施工会社や旅行会社などの窓口で確かめる。", say:"これからの大きな予定を一緒に入れておきましょう。時期が見えると、その年に向けた準備がしやすくなります。", more:"ライフイベントは、楽しみの予定を入れる場でもあります。旅行や家族のお祝いを入れておくと、そのためにどれだけ貯めればよいかが見え、家計の話が前向きになります。予定が変わったら、その都度入れ直します。", why:"大きな出費は来る年が分かっていれば準備できますが、入れていないと、その年に貯金を大きく取り崩すことになるからです。" },
      /* nkn.json */
      { key:'faq_xnkn_mijikai', faq:1, grp:'nkn', q:"厚生年金に少しだけ入っていた期間も年金になる？", re:/(少しだけ|少しの間|短い間|短い期間|短期間|数年だけ|数か月だけ|一時期)[^。]{0,16}(厚生年金|会社員|会社勤め|勤め)[^。]{0,16}(年金|反映|出る|もらえ|受け取|どうな)|(厚生年金|会社員|会社勤め)[^。]{0,10}(少しだけ|短い間|短い期間|短期間|数年だけ)[^。]{0,12}(年金|反映|出る|もらえ|受け取|どうな)/, ng:/遺族|障害|在職|働きながら|脱退一時金|ideco|イデコ|企業年金|個人年金|確定拠出|退職金/, head:"厚生年金に入っていた期間が短くても、受け取る資格を満たせば、その期間の分の老齢厚生年金が出ます。", body:"老齢厚生年金は、国民年金と合わせた受給資格期間を満たしていれば、厚生年金に入っていた期間が短くても、その期間の給与に応じた額が老齢基礎年金に上乗せされます。額は期間に応じて小さくなります。若い頃の短い勤め先の記録が、ほかの記録とつながっていないこともあるので、ねんきん定期便で確かめることが大事です。", acts:["ねんきん定期便の加入記録に、若い頃の勤め先が全て載っているかを一緒に確かめる", "載っていない勤め先があれば、年金事務所で記録を調べていただくよう案内する", "短い期間の分は額が小さいので、老後の見込みは記録どおりの見込み額で考える"], actHead:"現場で使うなら", note:"受給資格期間の長さと、本来より前に受け取る仕組みの加入期間の要件は制度で決まる。記録と見込み額は日本年金機構・年金事務所で確かめる。", say:"会社員として厚生年金に入っていた期間が短くても、その分の年金は上乗せされます。昔の勤め先の記録がきちんと載っているか、ねんきん定期便で見てみましょう。", more:"結婚や出産の前に数年だけ会社員だった方や、学生のあとに少し勤めた方に多い話です。名字が変わったり、昔の年金の番号が分かれていたりして、記録がつながっていないこともあります。また、本来より前に受け取る特別支給の老齢厚生年金には、加入期間の要件が別にあります。", why:"老齢厚生年金は、厚生年金に入っていた月ごとの給与に応じて積み上がる作りなので、期間が短くても、その月の分は額に反映されます。受給資格は国民年金と合わせた期間で見るため、厚生年金だけの長さでは決まりません。" },
      { key:'faq_xnkn_fuyasu', faq:1, grp:'nkn', q:"公的年金を増やす方法はある？", re:/(公的年金|老齢年金|年金額|年金の額|年金)[^。]{0,6}(を|は)?[^。]{0,4}(増やす|増やせ|増やした|多くした|多くする|上乗せした)/, ng:/個人年金|企業年金|ideco|イデコ|確定拠出|nisa|ニーサ|自営業|個人事業|フリーランス|付加|基金|任意加入|繰り?下げ|追納/, head:"公的年金を増やす道は、繰下げ・任意加入・追納・付加年金・厚生年金に入って働くの五つが中心です。", body:"受け取り始めを遅らせる繰下げで額を増やす、満額に足りない方が任意加入で納めた月を足す、免除や猶予の期間の保険料を追納する、自営業の方が付加保険料を納めて付加年金を上乗せする、厚生年金に入って働いて報酬比例の部分を積み上げる、が主な道です。それぞれ対象の方と条件が違い、納める保険料や待つ期間との釣り合いを見て選びます。", acts:["ねんきん定期便で、未納・免除の月、満額との差、厚生年金の加入期間を先に確かめる", "当てはまる道だけを並べ、どれを選ぶかはお客様が決めることとして伝える", "国民年金基金やiDeCoは私的な上乗せで、公的年金とは別の制度だと分けて説明する"], actHead:"現場で使うなら", note:"対象の方・条件・増える額は制度で決まり改定される。ご本人の場合は日本年金機構・年金事務所で確かめる。どの道が得かは言い切らない。", say:"公的年金は、受け取り始めを遅らせる、足りない期間を納める、働いて厚生年金に入る、などで増やす道があります。どれが合うかは、ご本人の記録を見て一緒に考えましょう。", more:"例えば、学生の頃の学生納付特例を追納していない方は追納、満額に足りない方は任意加入、自営業の方は付加年金、会社員を続ける方は厚生年金の積み上げ、と記録によって効く道が違います。繰下げは待つ間の暮らしのお金が要るので、ほかの道と合わせて考えます。", why:"公的年金の額は、納めた保険料の月数と給与、受け取り始めの時期で決まる作りなので、増やす道もこの三つのどれかに働きかける形になります。制度の外の貯蓄や運用とは分けて考えると整理しやすくなります。" },
      { key:'faq_xnkn_koumuin', faq:1, grp:'nkn', q:"公務員の年金は会社員と違う？", re:/(公務員|教員|教職員|共済組合員)[^。]{0,10}(の)?年金|共済年金|年金払い退職給付|職域加算/, ng:/ideco|イデコ|個人型|確定拠出|遺族|障害|企業年金|個人年金/, head:"公務員も今は厚生年金に入っていて、老後の年金の作りは会社員とほぼ同じです。", body:"公務員や私立学校の教職員が入っていた共済年金は、被用者年金の一元化で厚生年金にまとめられ、今は会社員と同じ厚生年金に入っています。手続きや支払いは共済組合が受け持つ部分があります。一元化の前の期間には職域加算の扱いが残り、一元化のあとの期間には、公務員などに年金払い退職給付という別の仕組みがあります。", acts:["公務員の方の老後の見込みも、ねんきん定期便とねんきんネットで確かめられると伝える", "年金払い退職給付や職域加算の扱いは、所属の共済組合に確かめていただく", "会社員の期間と公務員の期間の両方がある方は、記録が全てつながっているかを確かめていただく"], actHead:"現場で使うなら", note:"一元化の前後の扱い・職域加算・年金払い退職給付の細部は、所属の共済組合と日本年金機構・年金事務所で確かめる。", say:"公務員の方も、今は会社員と同じ厚生年金に入っています。公務員だけの上乗せの仕組みは、所属の共済組合で確かめていただきます。", more:"一元化の前に公務員として働いていた期間がある方は、その期間に応じた職域加算の分を受け取れることがあります。民間の会社と公務員の両方で働いた方は、年金事務所でも共済組合でも請求の相談ができる仕組みになっていますが、記録の確かめは早めに済ませておくと手続きが進めやすくなります。", why:"働き方によって年金の制度が分かれていると、同じ収入でも受け取る額に差が出るため、公平にするために制度がまとめられました。公務員の上乗せの部分だけは、別の仕組みに切り替わっています。" },
      { key:'faq_xnkn_teiji', faq:1, grp:'nkn', q:"働きながら厚生年金に入ると、年金は増える？", re:/在職定時改定|退職時改定|(働きながら|働き続け|再雇用|年金をもらいながら|受け取りながら)[^。]{0,16}(厚生年金|保険料)[^。]{0,16}(増え|増や|反映|上が|積み)/, ng:/減|止ま|カット|遺族|障害|個人年金|企業年金|ideco|イデコ|確定拠出/, head:"老齢厚生年金を受け取りながら厚生年金に入って働くと、納めた保険料は年金の額に反映されます。", body:"働きながら厚生年金の保険料を納めると、その分は年に一度、老齢厚生年金の額に反映される仕組みがあり、在職定時改定と呼ばれます。退職して厚生年金を離れたときにも、それまでの分が反映されます（退職時改定）。対象になる年齢には決まりがあります。給与と年金の合計で年金が止まる在職老齢年金とは別の仕組みです。", acts:["定年後も厚生年金に入って働く方には、年金が止まる話だけでなく増える仕組みもあると伝える", "増える額の見込みは、ねんきんネットや年金事務所で確かめていただく", "働き方を決めるときは、給与・年金・保険料の三つを並べて、お客様が選べるようにする"], actHead:"現場で使うなら", note:"対象の年齢・反映の時期と計算は制度で決まり改定される。個別の額は日本年金機構・年金事務所で確かめる。", say:"年金を受け取りながら厚生年金に入って働くと、納めた保険料が毎年、年金の額に反映されます。止まる話だけでなく、増える仕組みもあります。", more:"前は、退職するまで納めた保険料が年金に反映されませんでしたが、今は働いている間も年に一度見直されます。その一方で、給与と年金の合計が基準を超えると在職老齢年金で一部が止まるので、増える分と止まる分の両方を見ます。", why:"長く働く方が増えたので、働いて納めた保険料の効果を、退職を待たずに年金に反映させるため設けられました。働きながら受け取る方の年金を、少しずつ積み上げる作りです。" },
      { key:'faq_xnkn_kakyu', faq:1, grp:'nkn', q:"加給年金が付かない・止まるのはどんなとき？", re:/加給年金[^。]{0,12}(付かな|つかな|止ま|もらえな|受け取れな|打ち切|終わ|なくな|対象外|ケース|どうな|いつまで)|(妻|夫|配偶者|奥様)[^。]{0,16}加給年金[^。]{0,8}(どうな|止ま|終わ|なくな)/, ng:/繰り?下げ|改正/, head:"加給年金は、配偶者が一定の年齢になる、配偶者自身が一定の年金を受け取れる、などで止まります。", body:"加給年金は、ご本人の厚生年金の加入期間が長く、生計を維持している配偶者や子がいるときに、老齢厚生年金に加わります。配偶者が一定の年齢になる、配偶者が加入期間の長い老齢厚生年金や障害年金を受け取る権利がある、子が一定の年齢を過ぎる、ご家族の収入が基準以上、繰下げで待っている間、などは付かないか止まります。2025年の改正で額の見直しも決まっています。", acts:["年の差のあるご夫婦には、加給年金が付く期間と終わる時期を年金事務所で確かめていただく", "配偶者の加給年金が終わると、生年月日によって配偶者に振替加算が付くことがあると伝える", "繰下げを考える方には、待つ間は加給年金を受け取れないことを判断の材料に入れていただく"], actHead:"現場で使うなら", note:"加入期間・年齢・収入の基準と額は制度で決まり、改正で見直しも進む。対象かどうかは日本年金機構・年金事務所で確かめる。", say:"加給年金は、配偶者の年齢や配偶者ご自身の年金などで、付かなかったり途中で止まったりします。ご夫婦の生年月日と記録で、年金事務所に確かめてみましょう。", more:"例えば、夫が先に年金を受け取り始め、年下の妻がまだ一定の年齢になっていない間だけ、加給年金が付く形がよくあります。妻自身が厚生年金に長く入っていた場合は、妻の年金を受け取る権利が生まれた時点で止まります。届け出や書類が要る場面もあるので、年金請求書の案内で確かめます。", why:"加給年金は、ご本人が年金を受け取り始めても、生計を支えている配偶者や子がまだ年金を受け取れない間の暮らしを補う、家族手当のような上乗せです。そのため、配偶者が自分の年金を受け取れるようになると役目を終えます。" },
      { key:'faq_xnkn_kaigai', faq:1, grp:'nkn', q:"海外に住んでいる間の年金はどうなる？", re:/(海外|外国|国外)[^。]{0,16}(年金|国民年金|厚生年金)|(年金|国民年金|厚生年金)[^。]{0,16}(海外|外国|国外)|社会保障協定/, ng:/保険会社|海外の保険|外貨|香港|控除|旅行|入院|手術|給付金|個人年金|ideco|イデコ|nisa|ニーサ|外国人|脱退一時金/, head:"海外にいる間の年金は、日本の会社から赴任するか、自分で移り住むかで違い、社会保障協定も関わります。", body:"日本の会社との雇用が続いたまま海外へ赴任する場合は、多くは日本の厚生年金に入り続けます。相手の国と社会保障協定があれば、保険料を二重に払わずに済む形や、加入期間を通算する形があり、中身は国ごとに違います。仕事を辞めて海外に移り住む場合は、国民年金に入る義務はなくなりますが、申し出て任意加入できます。海外に住みながら日本の年金を受け取ることもできます。", acts:["海外赴任が決まったお客様には、勤め先と年金事務所で、厚生年金と社会保障協定の扱いを確かめていただく", "海外に移り住む方には、任意加入しないと国民年金の空いた期間が生まれることを伝える", "相手の国の年金制度の扱いは、こちらで判断せず、年金事務所や相手の国の窓口で確かめていただく"], actHead:"現場で使うなら", note:"社会保障協定の相手の国と中身・任意加入の条件は国ごとに違い、変わる。日本年金機構・年金事務所と勤め先で確かめる。", say:"海外にいる間の年金は、日本の会社から赴任するか、ご自身で移り住むかで扱いが違います。相手の国との社会保障協定も関わるので、出発前に年金事務所で確かめましょう。", more:"海外に移り住んで任意加入しなかった期間は、受給資格期間には数えられるものの、年金の額には反映されない期間になります。その間に病気やけがをすると、障害基礎年金の対象にならないことがあるので、長く海外に住む予定の方は、任意加入するかどうかを出発前に決めておきます。", why:"公的年金は、その国に住む人や働く人が入る仕組みなので、国をまたいで働くと、二重に入ったり期間が分かれたりします。それを調整するために、国どうしで社会保障協定を結んでいます。" },
      { key:'faq_xnkn_bunkatsu', faq:1, grp:'nkn', q:"離婚したら年金は分けられる？", re:/(離婚|別れ)[^。]{0,16}(年金|厚生年金)|年金分割|(3|三)号分割|合意分割/, ng:/養育費|慰謝料|保険金|受取人|生命保険|学資|個人年金|遺族|ideco|イデコ|控除|税/, head:"離婚のときは、婚姻の間の厚生年金の記録を分ける年金分割を請求でき、国民年金の部分は分けません。", body:"年金分割は、婚姻していた間の厚生年金の記録（給与の記録）を夫婦で分ける仕組みで、国民年金の部分は分けません。話し合いや裁判所の手続きで割合を決める合意分割と、扶養されていた一定の時期より後の期間を、相手の同意なしに分けられる分割があります。分けた記録は、その方の老齢厚生年金の額に反映されます。請求には期限があり、まず年金分割のための情報通知書で記録を確かめます。", acts:["離婚を考えているお客様には、年金分割という仕組みがあると伝え、記録の確かめ方を年金事務所で案内していただく", "割合の決め方や財産分与との関係は、こちらで判断せず弁護士につなぐ", "分けたあとの年金の見込みは、年金事務所で確かめていただく"], actHead:"現場で使うなら", note:"分割の割合の上限・対象の期間・請求の期限は法律で決まる。手続きは日本年金機構・年金事務所、割合の取り決めや財産分与は弁護士・家庭裁判所で確かめる。", say:"離婚のときは、婚姻していた間の厚生年金の記録を分ける年金分割を請求できます。請求には期限があるので、まず年金事務所で記録を確かめましょう。", more:"年金分割で分けるのは、受け取る年金そのものではなく、厚生年金の記録です。分けてもらった方は、その記録をもとに、ご自身が受け取る年齢になってから老齢厚生年金として受け取ります。分けた記録はご自身のものとして残り、相手のその後の事情では変わりません。", why:"婚姻の間は夫婦で協力して暮らしを支えたと考え、その間に積み上がった厚生年金の記録を、離婚のあとも二人の年金に分けて生かすために設けられました。" },
      { key:'faq_xnkn_dairi', faq:1, grp:'nkn', q:"親の年金の手続きを子が代わりにできる？", re:/(親|父|母|祖父|祖母|夫|妻|家族|本人)[^。]{0,10}(の)?年金[^。]{0,16}(代わり|代理|代行|委任|子が|子ども|家族が)|年金[^。]{0,12}(委任状|代理人|代理で|代わりに|家族が代わ)|委任状[^。]{0,12}年金|代理人[^。]{0,8}年金/, ng:/認知症|判断能力|成年後見|後見|意思能力|社労士|社会保険労務士|保険金|生命保険|指定代理|代理請求|受取人|亡くな|死亡/, head:"親御さんの年金の手続きや相談は、委任状と代理の方の本人確認の書類があれば、代わりにできます。", body:"年金事務所での相談や手続きは、ご本人が書いた委任状と、代わりに行く方の本人確認の書類があれば、ご家族などが代わりにできます。委任状には、何を任せるかを書きます。ご本人が意思を示すのが難しいときは、委任状では足りないことがあり、成年後見などの別の仕組みが関わります。年金の振込先は、原則としてご本人の口座です。", acts:["親御さんの年金の相談を代わりに受けたいご家族には、委任状の様式と要る書類を年金事務所で確かめていただく", "ご本人の意思の確認が難しい場合は、こちらで判断せず、弁護士や司法書士などの専門家につなぐ", "ご本人の基礎年金番号やマイナンバーの控えを、こちらで預からない"], actHead:"現場で使うなら", note:"委任状の様式・本人確認の書類は日本年金機構が決める。ご本人の判断能力に関わる手続きは弁護士・司法書士・家庭裁判所で確かめる。", say:"親御さんの年金の手続きや相談は、ご本人が書いた委任状と、代わりに行く方の本人確認の書類があれば、ご家族が代わりにできます。要る書類を年金事務所で確かめましょう。", more:"委任状の様式は日本年金機構の案内にあり、ご本人が自分で書いて署名します。年金の見込み額や記録の相談を代わりに受けるときも同じです。電話の相談では、ご本人でないと答えられない内容があるので、前もって確かめておくと手間が省けます。", why:"年金の記録や額は大事な個人の情報なので、ご本人の意思で任せたことを書面で確かめてから、代わりの方に伝える作りになっています。" },
      { key:'faq_xnkn_soudan', faq:1, grp:'nkn', q:"年金の相談はどこでできる？", re:/年金[^。]{0,8}(の)?(相談|聞き)[^。]{0,10}(どこ|窓口|できる|したい|乗って|受けたい|予約)|年金事務所[^。]{0,10}(予約|場所|どこ|行き方|持ち物|何を持)|街角の年金相談センター|ねんきんダイヤル|年金[^。]{0,8}(電話|ダイヤル)[^。]{0,8}(聞|相談|窓口)|年金[^。]{0,10}(聞ける|相談できる)[^。]{0,4}(窓口|ところ|場所)/, ng:/個人年金|企業年金|ideco|イデコ|確定拠出|保険会社|ハラスメント|社内|代わり|代理|委任|家族が/, head:"年金の相談は、年金事務所や街角の年金相談センター、電話のねんきんダイヤルで受けられます。", body:"記録や見込み額、請求の相談は、全国の年金事務所と街角の年金相談センターで受けられ、予約をしておくと待たずに済みます。電話のねんきんダイヤルでも、一般的な相談ができます。国民年金の加入や免除の相談は、住所地の市区町村の窓口でも受け付けます。障害年金の請求など込み入った手続きは、社会保険労務士に頼む方法もあります。行くときは、基礎年金番号の分かるものと本人確認の書類を持って行きます。", acts:["年金の相談を受けたら、こちらで答えを決めず、年金事務所などの窓口と予約の取り方を案内する", "相談に行く前に、ねんきん定期便と本人確認の書類を用意していただく", "有料で手続きを頼む場合は、社会保険労務士に頼むものだと伝える"], actHead:"現場で使うなら", note:"窓口の場所・予約の方法・受け付ける内容は日本年金機構が案内する。国民年金の加入と免除は市区町村、手続きの代行は社会保険労務士へ。", say:"年金の相談は、年金事務所や街角の年金相談センターで受けられ、予約をすると待たずに済みます。ねんきん定期便を持って行くと、話が早く進みます。", more:"窓口では、ご本人の記録をもとに、見込み額や受け取りを遅らせたときの額、遺族年金の見込みなども出していただけます。生命保険の話の前に、公的な年金の見込みを窓口で確かめていただくと、保障の話の土台がはっきりします。", why:"年金の額や要件は一人ひとりの記録で決まるので、記録を見られる公的な窓口で確かめるのがいちばん確かです。手続きの代行は、資格のある社会保険労務士の業務とされています。" },
      { key:'faq_xnkn_tedori', faq:1, grp:'nkn', q:"年金の振込額が思ったより少ないのはなぜ？", re:/年金[^。]{0,10}(振込|振り込|手取り|入金)[^。]{0,12}(少な|減|思ったより|違う|足りな|なぜ|どうして|引かれ|理由)|年金から[^。]{0,10}(介護保険料|保険料|国民健康保険|後期高齢者|住民税|引かれ|天引|差し引)|年金振込通知書/, ng:/所得税|源泉|扶養親族等申告書|確定申告|個人年金|企業年金|ideco|イデコ|保険会社|振込先|口座|ねんきん|定期便/, head:"年金の振込額は、年金から介護保険料や健康保険の保険料、税金などが差し引かれた額です。", body:"公的年金は年に何回かに分けて、前の月までの分がまとめて振り込まれます。年金の額によっては、介護保険料、国民健康保険や後期高齢者医療の保険料、住民税、所得税が年金から差し引かれ、振込額は年金の額より少なくなります。差し引かれる額は年の途中で変わることがあり、年金振込通知書などで内訳を確かめられます。働きながら受け取る方は、在職老齢年金で一部が止まっていることもあります。", acts:["振込額が少ないと相談されたら、まず年金振込通知書や改定の通知の内訳を一緒に見る", "保険料や住民税の額のことは市区町村の窓口、所得税のことは税理士・税務署に確かめていただく", "老後の家計を考えるときは、年金の額面ではなく、差し引かれたあとの振込額で考える"], actHead:"現場で使うなら", note:"差し引かれる保険料と税の種類・対象になる年金の額は法律で決まる。保険料と住民税は市区町村、年金は日本年金機構・年金事務所、所得税は税理士・税務署で確かめる。", say:"年金の振込額は、年金から介護保険料や健康保険の保険料、税金などが差し引かれた額です。通知書の内訳を見ると、何が引かれているかが分かります。", more:"例えば、受け取り始めた最初の年は差し引かれていなかった保険料が、途中から年金からの差し引きに切り替わり、振込額が下がったように見えることがあります。老後の家計の見通しでは、年金の額面ではなく、差し引かれたあとの振込額で暮らしのお金を考えると、実際に近くなります。", why:"介護保険や健康保険の保険料、住民税は、納め忘れを防ぐため、一定の額以上の年金から差し引いて納める仕組み（特別徴収）になっています。そのため、振込額は年金の額より少なくなります。" },
      /* shd.json */
      { key:'faq_xshd_pokan', faq:1, grp:'shd', q:"説明の途中で、お客様がついてこられていない", re:/ついて(こ|来)られていな|ぽかんと|表情が曇|話についてこれな|置いてけぼり/, ng:/部下|新人|後輩|研修|勉強会|セミナー/, head:"ついてこられていないと感じたら、先へ進まず、一度止まって確かめます。", body:"表情が曇る、メモの手が止まる、相づちが減るのは、話が置いてけぼりになっている合図です。そのまま続けると、残りの説明が届かなくなります。「ここまでで、気になるところはありますか」と一度止まり、相手の言葉で言い直してもらうと、どこで止まったかが見えます。", acts:["説明を三つほどの区切りに分け、区切りごとに一度止まる", "止まったときは、相手の言葉で言い直してもらう", "分かりにくかった所は、紙に図を描いて説明し直す"], actHead:"今日やること", note:"重要な事項の説明と理解の確かめ方は、所属の保険会社と社内の募集の手引に沿って行う。", say:"少し話を進めすぎたかもしれません。ここまでのところで、引っかかっているところはありませんか。", more:"置いてけぼりになった方は、自分から止めてくださいとは言いにくいものです。だからこちらが区切りを作ります。区切りで聞くのは「分かりましたか」ではなく「どこが気になりましたか」です。分かったかどうかを聞くと、多くの方は分かったと答えます。", why:"人は分からないと言うと相手に悪いと感じ、黙ってうなずくことがあるからです。区切りを決めておくと、お客様が気を使わずに止まれます。" },
      { key:'faq_xshd_ketsuron', faq:1, grp:'shd', q:"説明が回りくどいと言われた", re:/回りくどい|まわりくどい|結論から話|結論が見えな|何が言いたいのか(分から|わから)/, ng:/部下|新人|後輩|報告/, head:"回りくどいと言われたら、最初の一文で結論を言う形に変えます。", body:"説明が長くなるのは、前置きと理由を先に並べ、結論が最後に来るからです。お客様は結論が分からないまま聞くので、途中で疲れます。「結論から言うと〜です。理由は二つあります」と、先に結論と理由の数を言ってから中身に入ると、相手は話の地図を持って聞けます。", acts:["次の面談の説明を、結論・理由・次にすることの三行に書いてから臨む", "話し始めの一文を「結論から言うと」で始める", "理由の数を先に言い、その数だけ話す"], actHead:"今日やること", note:"説明の順番を変えても、お伝えしなければならない事項は省かない。何を伝えるかは社内の募集の手引と所属の保険会社の決まりで確かめる。", say:"先に結論からお伝えしますね。そのあとで、理由と、次にご検討いただきたいことを順にお話しします。", more:"結論から話すと冷たく聞こえないか気になる方もいます。そのときは、結論の前に相手の言葉を一言だけ受けてから入ります。結論のあとに理由を言い、最後に次にすることを言って終えると、長さは同じでもまとまって聞こえます。", why:"聞き手は、話がどこに向かうか分からないと、全ての話を覚えておこうとして疲れるからです。結論が先にあると、残りの話をその理由として整理して聞けます。" },
      { key:'faq_xshd_wakatta', faq:1, grp:'shd', q:"お客様の「分かりました」は本当に分かっている？", re:/分かりました(と|って)?[^。]{0,10}(本当|ほんと|伝わ|理解)|うなずいて[^。]{0,10}(理解|分かって|わかって|伝わ)|理解(できた|している|してもらえた)か[^。]{0,4}(確か|分から|わから|不安)|伝わったか[^。]{0,4}(確か|不安|分から|わから)/, ng:/部下|新人|後輩|研修/, head:"分かりましたの一言だけで、伝わったと決めないことです。", body:"うなずきや「分かりました」は、話を聞いていますという合図のことが多く、中身が伝わった印とは限りません。確かめるには、「ご家族にお話しするとしたら、どう伝えますか」のように、お客様の言葉で言い直してもらいます。言い直しにずれがあれば、そこが説明の足りないところです。", acts:["大事な説明のあとに、お客様の言葉で言い直してもらう問いを一つ用意する", "言い直しのずれを責めず、こちらの説明を足す", "確かめた内容は面談の記録に残す"], actHead:"今日やること", note:"重要事項の説明と意向の確かめ方、その記録の残し方は、所属の保険会社と社内の手引に沿う。", go:"iko", say:"大事なところなので、確かめさせてください。今のお話を、ご家族に伝えるとしたら、どんなふうに伝えますか。", more:"言い直してもらうときは、試験のように聞こえないよう、こちらの説明が足りているかを確かめたいと先に伝えます。ずれていたら、お客様ではなく説明の側を直します。言い直しが合っていれば、それをそのまま面談の記録に書くと、あとで見返したときに分かりやすくなります。", why:"人は相手を気づかって、分からなくても分かりましたと答えることがあるからです。自分の言葉で言い直すと、どこまで分かっているかが本人にもこちらにも見えます。" },
      { key:'faq_xshd_sougaku', faq:1, grp:'shd', q:"月々の保険料と総額をどう見せればいい？", re:/(保険料|払い込|払込)[^。]{0,8}総額|総額[^。]{0,6}(見せ|伝え|示)|月額だけ|月々[^。]{0,8}総額/, ng:/相続|税|退職|年金|ローン/, head:"月々の額だけでなく、払い込む期間と総額も同じ大きさで並べます。", body:"月々の額だけを大きく見せると、負担が小さく見え、あとで総額を知ったときに驚かれます。月々の額、払い込む期間、総額を、同じ大きさの字で一つの表に並べると、お客様が自分で比べられます。総額は設計書の数字をそのまま使い、こちらで丸めたり言い換えたりしません。", acts:["説明の紙に、月々の額・期間・総額を同じ大きさで並べる欄を作る", "総額は設計書の数字をそのまま書き写す", "総額を見たお客様の受け止めを、その場で聞く"], actHead:"今日やること", note:"保険料と払込の総額は、保険会社の設計書の数字で示す。見せ方の決まりは社内の募集資料の手引と所属の保険会社で確かめる。", say:"毎月の保険料と、払い込んでいただく期間、そして払い込みの合計を並べてお見せしますね。合計を見て、気になるところがあればお聞かせください。", more:"途中でやめたときに戻るお金がある商品は、払い込みの合計と並べて、時期ごとの戻るお金も設計書から見せます。どちらかが大きく見える見せ方にはしません。お客様が月々と合計のどちらを気にされているかで、話の順番を変えます。", why:"小さい額だけを見せると、お客様は全体の大きさを知らないまま決めることになり、あとで不信につながるからです。数字を並べると、お客様が自分で判断できます。" },
      { key:'faq_xshd_kazu_shiboru', faq:1, grp:'shd', q:"資料の数字が多すぎて伝わらない", re:/数字(が|を)?[^。]{0,4}(多すぎ|多くて|詰め込)|数字だらけ/, ng:/部下|新人|目標|ノルマ|成績/, head:"一枚の紙に載せる数字は、お客様の問いに答える数字に絞ります。", body:"数字が多いと、どれが大事な数字かをお客様が選ばなければならず、伝わりません。面談の前に、このお客様が知りたいことを一つ決め、その答えになる数字を大きく、ほかの数字は別の紙に分けます。省いた数字も、聞かれたらすぐに出せるようにしておきます。", acts:["面談の前に、お客様が一番知りたいことを一行で書く", "その答えになる数字だけを一枚目に載せる", "ほかの数字は二枚目に分け、聞かれたら見せる"], actHead:"今日やること", note:"お伝えしなければならない数字と注意の事項は省かない。どれを必ず示すかは、所属の保険会社と社内の募集資料の手引で確かめる。", say:"今日は、お客様が気にされていた点にお答えする数字を、まず一枚にまとめました。ほかの数字も用意していますので、気になればお見せします。", more:"絞るときに、都合の良い数字だけを残さないよう気をつけます。良い点の数字を載せたら、同じ紙に注意する点の数字も載せます。絞るのは数字の量で、見せる中身の釣り合いではありません。", why:"一度に見られる数字には限りがあり、多すぎると全てが同じ重さに見えて、大事な数字が埋もれるからです。" },
      { key:'faq_xshd_graph', faq:1, grp:'shd', q:"グラフで説明するときに気をつけることは？", re:/グラフ/, ng:/作り方|エクセル|excel|ツールの使い方|部下|新人/, head:"グラフは、軸の目盛りと何の数字かを先に指さしてから見せます。", body:"グラフは一目で伝わる分、見せ方で印象が大きく変わります。縦の目盛りの始まりを途中にすると差が大きく見え、期間を切り取ると増え方の印象が変わります。見せる前に、縦と横が何の数字か、どこから始まるかを指でさして伝えると、お客様が自分で読めます。試算のグラフには前提の数字を添えます。", acts:["使うグラフの縦の目盛りが、どこから始まっているかを確かめる", "グラフの横に、前提の数字を書いた一行を付ける", "見せたあと、お客様にどう読めたかを聞く"], actHead:"今日やること", note:"試算のグラフと前提の示し方は、所属の保険会社と社内の募集資料の手引で確かめる。将来の運用の結果は約束できない。", say:"このグラフは、縦が金額、横が年です。前提にしている数字をここに書いていますので、前提が変わると形も変わります。", more:"運用の結果を使うグラフは、良い場合だけを描かず、前提を変えた形も並べると、お客様が幅で考えられます。色で良し悪しを決めつけないこと、一つのグラフに数字を詰め込みすぎないことも気をつけます。", why:"人はグラフの形をまず見て、目盛りや前提を読む前に印象を持つからです。先に読み方を伝えると、形だけの印象で決めずに済みます。" },
      { key:'faq_xshd_hayakuchi', faq:1, grp:'shd', q:"説明が早口になってしまう", re:/早口|話すのが(速|早)い|話す(スピード|速さ)/, ng:/部下|新人|後輩/, head:"早口は、話す量を減らすと自然に落ち着きます。", body:"早口になるのは、伝えたいことを全て話そうとして、時間に詰め込むからです。速さを意識して落とすより、一回の面談で話すことを減らし、区切りごとに相手の返事を待つほうが続きます。大事な一文の前で一度だけ間を置くと、そこが大事だと相手にも伝わります。", acts:["次の面談で話すことを三つに絞って書く", "大事な一文の前で、ひと呼吸置くと決める", "自分の説明を録音して聞き、速さと間を確かめる"], actHead:"今日やること", note:"話す量を減らしても、お伝えしなければならない事項は省かない。省けない事項は社内の募集の手引で確かめる。", say:"少し早口になっていましたら、遠慮なくおっしゃってください。大事なところは、ゆっくりお伝えします。", more:"緊張すると早口になる方は、話し始めの一文だけをゆっくり言うと決めておくと、その後の速さも落ち着きます。お客様の話す速さに少し合わせると、相手も聞きやすくなります。", why:"聞き手は、話の速さよりも間で大事なところを見分けるからです。間が無いと、全ての言葉が同じ重さで流れていきます。" },
      { key:'faq_xshd_banichi', faq:1, grp:'shd', q:"万一のときの話を、重くせずに切り出すには？", re:/(万一|もしも|死亡保障)[^。]{0,10}(話|話題)[^。]{0,10}(重く|切り出|しにく|どう始め|始めにく)|(万一|もしも)の話/, ng:/部下|新人|家族会議|相続|事業承継/, head:"万一の話は、怖さではなく、ご家族の暮らしを守る話として切り出します。", body:"万一の話が重くなるのは、亡くなることそのものを話の中心に置くからです。中心に置くのは、ご家族のこれからの暮らしです。「もしものときに、ご家族の暮らしがどう続くかを一緒に見ておきたい」と目的を先に伝え、話すかどうかをお客様に選んでもらうと、押しつけになりません。", acts:["切り出す前に、話の目的を一文で言えるようにしておく", "話してよいかを先にお客様に聞く", "ご家族の暮らしの話を中心にし、怖がらせる例は使わない"], actHead:"今日やること", note:"保障の中身と、ご家族の暮らしに関わる公的な制度は、保険会社のパンフレットと公的な窓口の案内で確かめる。", say:"ご家族のこれからの暮らしについて、もしものときのことも含めて、一度一緒に見ておきたいと考えています。今日お話ししてもよろしいですか。", more:"身近な方を亡くされたばかりのお客様には、無理に切り出しません。お客様が話したくない様子なら、別の日にします。公的な遺族年金などの仕組みを先に知っておくと、保険だけの話にならず、お客様も落ち着いて聞けます。", why:"人は怖さで動かされると、あとで納得できずに後悔しやすいからです。目的がご家族の暮らしだと伝わると、お客様は自分のこととして考えられます。" },
      { key:'faq_xshd_fuan_ukeru', faq:1, grp:'shd', q:"お客様が不安そうにしているときの受け止め方", re:/(お客様|お客さま|相手)[^。]{0,8}(不安そう|心配性|不安が強)|不安が強い(お客様|お客さま|方)|不安を(どう)?受け止め/, ng:/自分|私|僕|部下|新人/, head:"不安そうなお客様には、まず不安の中身を言葉にしてもらいます。", body:"不安そうな様子を見て、すぐに安心させる言葉を返すと、お客様は分かってもらえなかったと感じます。先に「どんなことが気になっていますか」と聞き、出てきた不安を一つずつ紙に書くと、漠然とした不安が具体的な問いに変わります。そのうえで、答えられることと、ほかで確かめることを分けて伝えます。", acts:["気になっていることを聞き、出てきた順に紙に書く", "答えられることと、ほかの窓口で確かめることを分ける", "大丈夫ですとすぐに言わず、まず聞く"], actHead:"今日やること", note:"不安の中身が体の調子や法律、税のことなら、医師や弁護士、税理士など専門家の窓口を案内する。保障の中身は保険会社の資料で確かめる。", say:"気になっていることを、思いつく順で結構ですので、聞かせていただけますか。一つずつ書き出して、一緒に整理しましょう。", more:"不安が強い方は、同じ話を何度か確かめたくなることがあります。そのたびに落ち着いて説明し、書いた紙を渡しておくと、家に帰ってからも確かめられます。その場で決めていただく必要はありません、と伝えておくと、お客様は安心して考えられます。", why:"不安は、中身が分からないときほど大きく感じるからです。言葉にして書き出すと、何が分かれば安心できるかが本人にも見えます。" },
      { key:'faq_xshd_osanai', faq:1, grp:'shd', q:"不安で押さずに備えの話をするには？", re:/不安で押さ|怖がらせ(ず|ない)|脅す(よう|ような)|脅さ(ず|ない)/, ng:/リスクを伝えても|刺さらな|部下|新人/, head:"不安で押さず、事実と打てる手を対にして伝えます。", body:"備えの話は、起きたら困ることだけを並べると怖がらせる話になります。伝えるのは、起きうることの事実、公的な制度や今の備えでどこまで足りるか、足りない分にどんな手があるか、の三つです。事実と手を必ず並べ、決めるのはお客様だと最後に添えると、押しつけになりません。", acts:["起きうることを一つ挙げるたびに、打てる手を並べて書く", "公的な制度と今の備えを先に確かめてから話す", "最後に、その場で決めなくてよいと伝える"], actHead:"今日やること", note:"公的な制度の中身は公的な窓口の案内で、保障の中身は保険会社の資料で確かめる。募集の言い方の決まりは社内のコンプライアンスの手引で確かめる。", say:"起きるかもしれないことと、公的な制度や今の備えでどこまで足りるかを、並べてお見せします。足りない分があれば、どんな手があるかも一緒に見ましょう。", more:"怖い話や、身近な人の出来事を持ち出して決めるのを急がせる話し方は使いません。お客様が自分で考えるための材料を出すのがこちらの役目です。不安が強く出たお客様には、話をいったん止めて、気持ちを聞きます。", why:"怖さで決めた備えは、怖さが薄れたときに続かなくなり、お客様の後悔にもつながるからです。事実と手が並ぶと、お客様が落ち着いて選べます。" },
      { key:'faq_xshd_naku', faq:1, grp:'shd', q:"面談中にお客様が泣き出した", re:/(お客様|お客さま|相手|奥様|ご主人|ご家族)[^。]{0,10}(泣き出|泣いて|泣かれ|涙ぐ|涙を)/, ng:/部下|新人|後輩|自分が|私が|僕が/, head:"お客様が泣き出したら、話を止めて、落ち着くまで待ちます。", body:"涙は、話の中で大事なことに触れた合図であることが多いものです。説明を続けたり、慰めの言葉を重ねたりせず、話を止めて静かに待ちます。落ち着いたら「少し休みましょうか」「今日はここまでにしましょうか」と、続けるかどうかをお客様に選んでもらいます。", acts:["話を止め、飲み物やハンカチなど落ち着ける間を作る", "続けるかどうかをお客様に選んでもらう", "その日は申込みの話に進まず、次の約束を相手に合わせて決める"], actHead:"今日やること", note:"お客様のつらさが強く、体や心の調子が心配なときは、医師や公的な相談の窓口を案内する。社内の上長にも共有する。", say:"無理にお話を続けなくて大丈夫です。少し休みましょうか。今日はここまでにして、また改めてお話ししても構いません。", more:"涙の理由をこちらから聞き出そうとはしません。お客様が話したいときに聞きます。泣いたあとの気持ちのまま申込みに進むと、あとで後悔されることがあるので、その日は決める話をしません。", why:"気持ちが大きく動いているときは、落ち着いて判断できないからです。待つことと、続けるかを選んでもらうことで、お客様が自分のペースを取り戻せます。" },
      { key:'faq_xshd_news_fuan', faq:1, grp:'shd', q:"ニュースやネットを見て不安になっているお客様", re:/(ニュース|ネット|テレビ|sns|記事|動画)[^。]{0,14}(不安|心配)/, ng:/詐欺|自分|私|僕|部下/, head:"ニュースで不安になっているお客様には、まずどこで何を見たかを聞きます。", body:"ニュースやネットの情報は、一部だけが切り取られていることがあります。否定から入らず、どこで何を見て、何が心配になったのかを聞きます。そのうえで、その情報がお客様のご契約やご家庭に当てはまるかを、保険会社の資料や公的な案内で一緒に確かめます。分からないことは確かめて返事をします。", acts:["見た情報の出どころと中身を、お客様に聞いて書き留める", "ご契約に当てはまるかを、保険会社の資料で確かめる", "すぐに答えられないことは、確かめて返事をすると約束する"], actHead:"今日やること", note:"制度の改正や保険会社の経営に関わる話は、公的な発表と保険会社の公表、所属の保険会社の担当で確かめる。", say:"どちらで、どんなお話をご覧になりましたか。お客様のご契約に当てはまるかどうか、資料で一緒に確かめてみましょう。", more:"ネットの情報が間違っていると決めつけると、お客様は自分の判断を否定されたと感じます。情報の正しい部分は認め、ご自分に当てはまるかどうかを分けて考えると、落ち着いて話せます。", why:"不安は、自分に当てはまるかどうかが分からないときに大きくなるからです。出どころと当てはまり方を分けると、何を心配すればよいかが見えます。" },
      { key:'faq_xshd_kurikaeshi', faq:1, grp:'shd', q:"お客様が同じ心配を何度も繰り返す", re:/同じ(心配|質問|こと)を[^。]{0,6}(何度|繰り返|何回)|何度(説明|話)しても/, ng:/部下|新人|後輩/, head:"同じ心配が繰り返されるのは、まだ答えが腹に落ちていない合図です。", body:"何度も同じことを聞かれると、こちらは説明が下手なのかと焦ります。繰り返されるのは、説明の中身より、気持ちのほうが落ち着いていないことが多いものです。同じ説明を重ねる前に「そこが一番気になっているのですね」と受け止め、答えを紙に書いて渡すと、お客様が家でも確かめられます。", acts:["繰り返される心配を、一番気になっている点として受け止める", "答えを紙に一行で書いて渡す", "次の面談の始めに、その心配がどうなったかを聞く"], actHead:"今日やること", note:"答えの中身は、保険会社の資料と約款で確かめてから書く。分からないことは社内の担当に確かめる。", say:"そこが一番気になっていらっしゃるのですね。答えを紙に書いておきますので、お家でもう一度見ていただけますか。", more:"同じ心配が何度も出る方は、ご家族など誰かに説明しなければならない立場のことがあります。誰に伝えるのかを聞き、その方向けの言い方で書くと、繰り返しが止まることがあります。", why:"人は気になることが解けないまま残っていると、確かめるために同じ問いを繰り返すからです。紙に残ると、確かめる先が手元にできます。" },
      { key:'faq_xshd_futatsu', faq:1, grp:'shd', q:"二つの案でお客様が迷っている", re:/(二つ|2つ|両方|aとb)[^。]{0,10}(案|プラン)[^。]{0,10}迷|(二つ|2つ)の(案|プラン)|aとbの?どちら/, ng:/他社|比べてほしい|競合|部下|新人/, head:"二つの案で迷われたら、違いを一行ずつ並べ、何を大事にするかを聞きます。", body:"二つの案で迷うのは、どちらにも良い点があるからです。こちらがどちらかを勧める前に、二つの違いを同じ項目で並べ、お客様が何を大事にしたいか（保険料の負担、保障の厚さ、続けやすさなど）を聞きます。大事にしたいことが決まると、どちらが合うかをお客様自身が選べます。", acts:["二つの案の違いを、同じ項目で一行ずつ並べる", "お客様が何を大事にしたいかを聞いて書く", "選んだ理由を、お客様の言葉で記録に残す"], actHead:"今日やること", note:"案の比べ方と勧めるときの説明は、社内の推奨の方針と所属の保険会社の決まりで確かめる。", go:"hikaku", say:"お二つの違いを、同じ項目で並べてみました。お客様が一番大事にしたいのは、どの点でしょうか。", more:"違いを並べるときは、片方の良い点だけでなく、両方の注意点も同じ紙に書きます。こちらの好みを先に言うと、お客様はそれに合わせてしまうことがあります。お勧めを聞かれたら、お客様の大事にしたいことに照らして理由を添えて答えます。", why:"人は良い点が並ぶと決められなくなりますが、自分の大事にしたいことが一つ決まると、それを物差しにして選べるからです。" },
      { key:'faq_xshd_kimerarenai', faq:1, grp:'shd', q:"お客様がなかなか決められない", re:/(お客様|お客さま|相手)[^。]{0,8}(決められな|決めきれ|決めかね|決まらな)|決めてもらえな|優柔不断/, ng:/自分|私|僕|二つ|2つ|aとb|どちら|どっち|部下|新人/, head:"決められないお客様には、決められない理由を一緒に分けます。", body:"決められない理由は、情報が足りない、ご家族と話していない、お金の見通しが立たない、急ぐ理由がない、などに分けられます。理由によって次にすることが違うので、まず何が引っかかっているかを聞きます。決めるのを促すより、迷いの理由を一つ減らすほうが、お客様にとって納得のいく決め方になります。", acts:["引っかかっている理由を聞き、紙に分けて書く", "理由ごとに次にすることを一つ決める", "その場で決めなくてよいと伝え、次の約束を決める"], actHead:"今日やること", note:"ご意向の確かめ方と記録の残し方は、所属の保険会社と社内の手引に沿う。", go:"iko", say:"急いで決めていただく必要はありません。今、どのあたりが引っかかっているか、聞かせていただけますか。", more:"急ぐ理由がないから決めないのは、自然なことです。その場合は、決めないままでも変わらないことを伝え、お客様が考える時間を取れるようにします。決めないことも、お客様の選んだ答えとして受け止めます。", why:"人は迷いの理由がはっきりしないと、決めること自体を先に延ばすからです。理由が分かれば、何を確かめれば決められるかが見えます。" },
      { key:'faq_xshd_chokuzen', faq:1, grp:'shd', q:"申込みの直前になってお客様が迷い出した", re:/(申込|申し込|署名|サイン)[^。]{0,8}(直前|前に|手前|寸前)[^。]{0,12}(迷|考え直|ためら)|最後の最後で[^。]{0,12}(迷|考え直|ためら)/, ng:/キャンセル|取り消|取消|撤回|部下|新人/, head:"申込みの直前の迷いは、止まってよい合図として受け止めます。", body:"申込書を前にして迷いが出るのは、決めることの重さを感じたからです。説得で進めようとせず、「どこが気になりましたか」と聞いて、迷いの中身を確かめます。気になる点が解ければ進めばよく、解けなければその日は申込みをせずに持ち帰っていただきます。迷いを残したままの申込みは、あとの後悔につながります。", acts:["迷いの中身を聞き、その場で答えられるかを確かめる", "答えられないことは確かめて返事をすると伝える", "迷いが残るなら、その日は申込みをしない"], actHead:"今日やること", note:"申込みのあとに取りやめる仕組みと手続きは、保険会社の書面と約款で確かめてお伝えする。", say:"少しでも気になるところがあれば、今日お申し込みいただかなくても大丈夫です。どこが気になったか、聞かせていただけますか。", more:"直前の迷いを、こちらの押しが足りないせいだと考えないことです。迷いが出たら、説明のどこかに足りないところがあったと考えて、その点を確かめます。持ち帰っていただくときは、次に会う日と、それまでに確かめることを決めておきます。", why:"決める直前は、それまで見えていなかった心配が一気に表に出やすいからです。そこで止まれる面談は、お客様の信頼を深めます。" },
      { key:'faq_xshd_shiharai_ikari', faq:1, grp:'shd', q:"保険金が出なかったとお客様が怒っている", re:/(保険金|給付金|支払)[^。]{0,12}(出な|払われ|対象外|下りな|おりな)[^。]{0,16}(怒|責め|不満|お叱り)/, ng:/暴言|怒鳴|罵倒|土下座|部下|新人/, head:"保険金が出ずに怒っているお客様には、気持ちの受け止めと事実の確かめを分けます。", body:"お怒りの気持ちは、その場で受け止めます。ただし、支払うかどうかの判断は保険会社が約款に沿って行うもので、こちらがその場で出る、出ないを言うことはできません。いつ、どの請求で、保険会社から何と説明されたかを確かめ、保険会社の窓口と一緒に理由を確かめると伝えます。苦情として記録にも残します。", acts:["お気持ちを受け止め、言い訳から話し始めない", "請求の日と、保険会社からの説明の中身を確かめる", "保険会社の窓口に理由を確かめ、苦情として記録に残す"], actHead:"今日やること", note:"支払いの判断と理由の説明は保険会社が行う。約款と保険会社の窓口、社内の苦情の手引で確かめ、上長に共有する。", go:"kujo", say:"お気持ちはよく分かります。どの請求で、保険会社からどのような説明があったかを確かめて、理由を保険会社と一緒に確かめます。", more:"その場で、払われるはずです、と言ってしまうと、あとで結果が違ったときに信頼を大きく失います。支払いの理由に納得できないときは、保険会社の相談の窓口や業界の相談の窓口があることをお伝えします。こちらの説明の仕方に原因があったなら、それは率直に謝ります。", why:"怒りの中には、思っていたことと違ったという気持ちと、説明への不信の二つがあるからです。気持ちを受け止めることと事実を確かめることを分けると、どちらにも誠実に向き合えます。" },
      { key:'faq_xshd_ayamaru', faq:1, grp:'shd', q:"どこまで謝ればいいのか分からない", re:/謝る範囲|どこまで謝|謝りすぎ|謝り過ぎ|謝り方|非を認め/, ng:/部下|上司|社長|家族|妻|夫|子ども/, head:"謝るのは、相手の気持ちを害したことと、こちらの落ち度です。", body:"謝りすぎると、こちらに非のないことまで認めたように受け取られ、話がこじれることがあります。謝ることを二つに分けます。ご不快な思いをさせたことへのお詫びはすぐに伝え、事実のほうは確かめてから話します。こちらの落ち度が分かったら、そこははっきり謝ります。", acts:["気持ちへのお詫びと、事実の確かめを分けて話す", "事実は確かめてから返事をすると伝える", "落ち度が分かったら、何が悪かったかを具体的に謝る"], actHead:"今日やること", note:"責任の範囲に関わる話は、その場で決めずに社内の上長と苦情の手引で確かめる。法律上の判断が要るときは弁護士へ。", go:"kujo", say:"ご不快な思いをおかけして、申し訳ありません。事実を確かめて、改めてご連絡いたします。", more:"何が悪かったかを言わずに謝り続けると、お客様には中身のない謝罪に聞こえます。落ち度が分かったときは、何が悪かったか、どう直すか、同じことをどう防ぐか、の三つを伝えます。保険会社の判断に関わることは、こちらの言葉で約束しません。", why:"お詫びと事実を混ぜると、お客様は何を謝られたのかが分からず、かえって不信が残るからです。分けて伝えると、気持ちにも事実にも誠実に向き合えます。" },
      { key:'faq_xshd_ikari_mail', faq:1, grp:'shd', q:"お客様から怒りのメールが届いた", re:/(怒り|お叱り|強い言葉|激怒)[^。]{0,8}(メール|メッセージ|line|ライン)|(メール|メッセージ)[^。]{0,10}(怒って|お叱り)|怒っている(お客様|お客さま)への(メール|メッセージ)/, ng:/暴言|怒鳴|罵倒|部下|上司/, head:"怒りのメールには、受け取ったことだけをすぐに返し、中身は確かめてから返します。", body:"怒りのメールにその場で長く返すと、言葉の一つ一つが新しい火種になります。まず「拝見しました。事実を確かめて、改めてご連絡します」と、受け取ったことと次の連絡の時期だけを返します。中身の返事は、事実を確かめ、上長に見てもらってから送ります。言い分を並べるより、電話や面談で直接お話しする場を提案するほうが収まることが多いものです。", acts:["受け取ったことと、次の連絡の時期だけをすぐに返す", "返事の文は、送る前に上長に見てもらう", "メールでやり取りを続けず、電話か面談で話す場を提案する"], actHead:"今日やること", note:"苦情の受け方と記録は社内の苦情の手引に沿い、上長に共有する。法律上の判断が要るときは弁護士へ。", go:"kujo", say:"ご連絡ありがとうございます。内容を拝見しました。事実を確かめたうえで、改めてこちらからご連絡いたします。", more:"返事の文では、相手の言葉を一つずつ取り上げて反論しない、感情の言葉に感情で返さない、約束できないことを書かない、の三つを守ります。メールは残るので、あとで読み返されても困らない文にします。謝るのは、ご不快な思いをさせたことと、分かっている落ち度です。", why:"文字のやり取りは表情や声の調子が伝わらず、同じ言葉でも冷たく受け取られやすいからです。直接話すと、気持ちを受け止めていることが伝わります。" },
      { key:'faq_xshd_iraira', faq:1, grp:'shd', q:"お客様の態度にイラッとしてしまった", re:/(お客様|お客さま|お客さん|顧客|相手)[^。]{0,12}(イラッ|いらっと|イライラ|いらいら|カチン|かちん|腹が立|ムカッ|むかっ)|(イラッ|いらっと|イライラ|いらいら|カチン|かちん|腹が立|ムカッ|むかっ)[^。]{0,12}(お客様|お客さま|お客さん|顧客)/, ng:/部下|新人|後輩|上司|家族|妻|夫|子ども|社長が/, head:"腹が立ったときは、その場で返さず、一呼吸置いてから話を続けます。", body:"腹が立つのは、こちらが大事にしていることに相手が触れたからです。その気持ちを抑え込むより、まず自分がイラッとしたことに気づくだけで、言葉を選べるようになります。その場では言い返さず、相手の言葉の中に何を求めているかを探し、「〜ということですね」と受け止めてから話を続けます。", acts:["イラッとしたら、心の中で一呼吸置いてから返す", "相手が求めていることを一言で書き出す", "面談のあと、何に腹が立ったかを書いて振り返る"], actHead:"今日やること", note:"お客様の言動が暴言や脅しのように度を越えるときは一人で抱えず、社内の上長と決まりに沿って対応する。", say:"ご不快な思いをさせてしまったようでしたら、申し訳ありません。お客様が一番気にされているのは、どの点でしょうか。", more:"腹が立ったことを、自分が未熟だと責める必要はありません。気づいて言葉を選べたなら、それで十分です。言動が度を越えるときは、我慢を続けるのではなく、上長に相談して、担当の替え方や対応の決まりに沿います。", why:"腹が立ったまま返した言葉は、相手の気持ちをさらに強くし、話の中身から離れてしまうからです。一呼吸置くと、相手の求めていることに目が向きます。" },
      { key:'faq_xshd_hannou', faq:1, grp:'shd', q:"お客様の反応が薄くて手応えがない", re:/反応が(薄|な|無)|無表情|手応え(が|を)?[^。]{0,4}(な|無|感じられ)/, ng:/部下|新人|研修|セミナー|勉強会|会議|sns|投稿|dm|チラシ|広告|紹介/, head:"反応が薄いときは、説明を足さず、お客様に一つ問いを渡します。", body:"反応が薄いのは、興味がないとは限りません。考えている、話の中身が自分のことと結びついていない、遠慮している、などのこともあります。説明を重ねるより、「ここまでで、ご自分のこととして気になるところはありましたか」と一つ問いを渡し、答えを待ちます。答えにくそうなときは、二つの選択肢から選んでもらうと話しやすくなります。", acts:["説明の区切りで、お客様に一つ問いを渡して待つ", "答えにくそうなら、二つの選択肢から選んでもらう", "反応が薄かった箇所を面談のあとに書き出す"], actHead:"今日やること", note:"ご意向の確かめ方と記録の残し方は、所属の保険会社と社内の手引に沿う。", go:"iko", say:"少し私ばかり話してしまいました。ここまでで、ご自分のこととして気になったところはありましたか。", more:"反応が薄い方を、こちらが盛り上げようとして話し続けると、かえって話しにくくなります。問いを渡したあとの間は、こちらから埋めずに待ちます。何度か面談を重ねると話してくださる方も多いので、一回の反応で決めつけません。", why:"人は聞くだけの時間が続くと、自分のこととして考えるきっかけを失うからです。問いを渡すと、話の中身を自分に当てはめて考え始めます。" },
      { key:'faq_xshd_kikijouzu', faq:1, grp:'shd', q:"面談でつい自分ばかり話してしまう", re:/自分ばかり(話|しゃべ)|聞き上手|しゃべりすぎ|喋りすぎ|話しすぎてしま|説明(が|ばかり)[^。]{0,4}多くな/, ng:/部下|上司|会議|家族|妻|夫/, head:"自分ばかり話してしまうときは、話す前に聞くことを三つ決めておきます。", body:"説明が多くなるのは、伝えなければと焦るからです。面談の前に、お客様に聞きたいことを三つ紙に書き、説明はそのあとに回すと決めます。聞いたら、答えをまとめて返し、もう一歩だけ「それはどうしてですか」と聞きます。お客様の話す時間が長いほど、こちらの説明はお客様に合ったものになります。", acts:["面談の前に、お客様に聞くことを三つ書いておく", "聞いた答えをまとめて返し、もう一歩だけ理由を聞く", "面談のあと、どちらが多く話したかを振り返る"], actHead:"今日やること", note:"ご意向の聞き方と記録の残し方は、所属の保険会社と社内の手引に沿う。", go:"iko", say:"説明の前に、少しお伺いさせてください。今のお暮らしで、お金のことで気になっていることはありますか。", more:"聞くときは、答えを予想して先回りしないことが大事です。お客様が言葉を探しているときは待ちます。聞いた話を自分の得意な商品の話へすぐにつなげると、お客様は誘導されたと感じます。", why:"お客様は自分の話を聞いてもらえたと感じたときに、こちらの説明にも耳を傾けるからです。聞いた中身が、そのまま提案の土台になります。" },
      { key:'faq_xshd_jinmon', faq:1, grp:'shd', q:"質問ばかりで尋問みたいになってしまう", re:/尋問|取り調べ|取調べ|質問攻め|質問ばかり|聞くことが多くて/, ng:/部下|上司|面接/, head:"尋問にならないよう、質問の前に、なぜ聞くのかを一言添えます。", body:"質問が尋問のように感じられるのは、なぜ聞かれるのか分からないまま答えさせられるからです。質問の前に「ご家族に合った形を考えたいので」と理由を添え、答えてくださったら「ありがとうございます、〜なのですね」と受け止めてから次に進みます。答えにくいことは、答えなくてよいと先に伝えます。", acts:["質問の前に、聞く理由を一言添える", "答えを受け止める一言を挟んでから次の質問に進む", "答えにくそうなことは、答えなくてよいと伝える"], actHead:"今日やること", note:"お伺いする内容とその扱い方は、社内の手引と個人情報の取り扱いの規程で確かめる。", say:"ご家族に合った形を考えたいので、いくつか伺わせてください。答えにくいところは、お答えいただかなくて大丈夫です。", more:"質問は、数字や事実を聞くものと、気持ちや考えを聞くものを交ぜると、会話らしくなります。事実ばかり続くと書類の記入のように感じられます。聞いた答えに一言の受け止めを返すことが、尋問と会話の違いです。", why:"人は理由の分からない質問に答えると、自分の情報が何に使われるのか心配になるからです。理由と受け止めがあると、安心して話せます。" },
      { key:'faq_xshd_aizuchi', faq:1, grp:'shd', q:"相づちが単調になってしまう", re:/相づち|相槌|あいづち|うなずき方/, ng:/部下|上司/, head:"相づちは、言葉を変えるより、相手の言葉を一部返すと深まります。", body:"「はい」「なるほど」だけが続くと、聞き流しているように聞こえます。相手の言葉の大事な一部を「お子さまの学費が、ですね」と返すと、聞いていることが伝わり、相手は続きを話しやすくなります。驚き、共感、確かめ、の三つの相づちを場面で使い分けると、単調になりません。", acts:["相手の言葉の大事な一部を、そのまま返してみる", "驚き・共感・確かめの相づちを一つずつ用意する", "面談のあと、どの相づちが多かったかを振り返る"], actHead:"今日やること", note:"面談の進め方と言葉づかいは、社内の手引に沿う。", say:"お子さまの学費が、一番気がかりなのですね。もう少し詳しく聞かせていただけますか。", more:"相づちでは、相手の話を自分の話に変えないことも大事です。「私もそうでした」と自分の話を始めると、話の主役がこちらに移ります。共感を伝えたら、すぐに相手の話に戻します。", why:"人は自分の言葉が返ってくると、ちゃんと聞いてもらえていると感じるからです。" },
      { key:'faq_xshd_kanjou_jijitsu', faq:1, grp:'shd', q:"お客様の気持ちと事実を分けて聞くには？", re:/(気持ち|感情)と事実|事実と(気持ち|感情)|思い込みと事実|気持ちの話と事実/, ng:/部下|上司|報告|自分の気持ち/, head:"気持ちと事実は、聞きながら紙の左右に分けて書くと整理できます。", body:"お客様の話には、起きたことの事実と、それについての気持ちが混ざっています。どちらも大事ですが、扱い方が違います。紙の左に事実、右に気持ちを書き分け、事実は確かめ、気持ちは受け止めます。気持ちを事実のように扱って説得したり、事実を気持ちで片づけたりしないことが大事です。", acts:["面談のメモを、事実と気持ちの二つの欄に分ける", "事実は資料で確かめ、気持ちは言葉で受け止める", "面談の終わりに、二つを分けて読み上げる"], actHead:"今日やること", note:"事実の確かめは保険会社の資料と約款で行う。意向の記録の残し方は社内の手引に沿う。", say:"起きたことと、そのときのお気持ちを、分けて伺ってもよろしいですか。どちらも大事なので、両方書き留めておきます。", more:"気持ちの中に、ご意向の芯があることがよくあります。心配だという気持ちの奥に、何を守りたいかが隠れています。事実だけで提案を組むと、気持ちに合わない案になりやすいので、両方を記録に残します。", why:"人は気持ちと事実が混ざったままだと、何に困っているのかを自分でも整理できないからです。分けて書くと、お客様にも見えるようになります。" },
      { key:'faq_xshd_me', faq:1, grp:'shd', q:"お客様の目を見て話せない", re:/目を(見て話せな|合わせるのが|見ると)|視線(のやり場|が合わな)|目が合わせられな/, ng:/部下|研修|人前|セミナー/, head:"目を見続けなくてよく、大事な一言のときだけ目を合わせれば伝わります。", body:"ずっと目を見ていると、お客様も緊張します。ふだんは資料や相手の口元、首元のあたりを見て、大事な一言を言うときと、相手の話を受け止めるときだけ目を合わせます。資料を二人で見る並び方にすると、目線が自然に資料へ向き、話しやすくなります。", acts:["大事な一言を言うときだけ、目を合わせると決める", "資料を二人で一緒に見る並び方にする", "相手の話を受け止めるときに、顔を上げる"], actHead:"今日やること", note:"体や心の調子に不安が続くときは、医師や社内の相談の窓口に相談する。", say:"こちらの資料を、一緒に見ながらお話ししてもよろしいですか。気になるところは、いつでも止めてください。", more:"横に並んで資料を見る、角を挟んで座る、など座り方でも目線の負担は変わります。オンラインの面談では、大事な一言のときだけカメラを見ると、相手には目が合ったように見えます。", why:"人は相手がずっと目を見ていると、圧を感じることがあるからです。大事なところで目が合うと、その一言が強く伝わります。" },
      { key:'faq_xshd_kinchou', faq:1, grp:'shd', q:"面談の前になると緊張してしまう", re:/緊張|頭が真っ白/, ng:/人前|研修|勉強会|セミナー|会議|発表|早口|部下|新人の|試験|目を/, head:"緊張は消すより、準備の形を決めて付き合うほうが続きます。", body:"緊張するのは、その面談を大事に思っているからです。消そうとするより、緊張しても進められる形を作ります。最初の一言と、聞くことを三つ紙に書いておくと、頭が真っ白になってもそこへ戻れます。面談の前に、うまく話すことより、お客様の話を聞くことが今日の役目だと思い直すと、肩の力が抜けます。", acts:["面談の最初の一言を紙に書いておく", "聞くことを三つ書いた紙を手元に置く", "面談のあと、うまくいったことを一つだけ書く"], actHead:"今日やること", note:"体や心の調子に不安が続くときは、医師や社内の相談の窓口に相談する。", say:"今日はお時間をいただき、ありがとうございます。まずは、お客様のお話を伺うところから始めさせてください。", more:"緊張していることを、隠そうとしなくても構いません。少し緊張していますと正直に言うと、かえって場がやわらぐことがあります。回数を重ねるうちに、緊張していても進められる形が身についていきます。", why:"緊張は、何を話すかが決まっていないときに強くなるからです。戻れる紙があると、頭が止まっても次の一言が出ます。" },
      { key:'faq_xshd_ishuku', faq:1, grp:'shd', q:"社長や年上のお客様の前で萎縮してしまう", re:/(社長|経営者|年上|目上|年配|お客様|お客さま|お客さん)[^。]{0,14}(萎縮|気後れ|圧倒され)|貫禄/, ng:/部下|上司|自分の会社の社長|うちの社長|数字を詰め/, head:"萎縮したら、相手を説得する人ではなく、話を聞いて整理する人だと思い直します。", body:"目上の方の前で萎縮するのは、相手より知っていなければと思うからです。経営者やご経験の多い方は、こちらに全てを教わろうとは思っていません。こちらの役目は、相手の考えを聞き、整理し、確かめる先を示すことです。知らないことは「確かめてご返事します」と言えばよく、その誠実さがかえって信頼になります。", acts:["面談の前に、相手に聞きたいことを三つ書く", "知らないことは、確かめて返事をすると決めておく", "相手の話を一言にまとめて返す練習をする"], actHead:"今日やること", note:"法人の税や会社の制度に関わる判断は、顧問の税理士や社会保険労務士など専門家と確かめる。", say:"社長のお考えを、まずは伺わせてください。私が分からないところは、確かめてからご返事いたします。", more:"年上の方には、話の中で教えていただく姿勢を見せると、会話が進みやすくなります。ただし、へりくだりすぎて必要な説明を省いたり、言うべき注意を言わずに済ませたりしないことです。", why:"人は自分の話をよく聞き、整理してくれる相手を信頼するからです。知識の量で競う必要はありません。" },
      { key:'faq_xshd_shouhin_jishin', faq:1, grp:'shd', q:"勧める商品に自信が持てない", re:/(商品|保険|プラン)[^。]{0,8}自信が(持てな|もてな|ない|無い)|勧めて(いい|よい)のか迷|納得できないまま[^。]{0,6}(提案|勧め)/, ng:/自分自身に|自分に自信/, head:"自信が持てないときは、その商品が誰に合い、誰に合わないかを言葉にします。", body:"商品に自信が持てないのは、どのお客様にも合うように説明しようとしているからかもしれません。どの商品にも、合う方と合わない方がいます。パンフレットと約款を読み直し、その商品が合う方、合わない方、注意する点を三行で書くと、勧めてよい場面と勧めない場面が見えます。合わない方には勧めないことが、誠実な提案です。", acts:["商品が合う方・合わない方・注意する点を三行で書く", "分からない点は、保険会社の担当や社内の詳しい人に聞く", "合わないと思ったお客様には、勧めない"], actHead:"今日やること", note:"商品の中身と注意の事項は、保険会社のパンフレット・約款と、所属の保険会社の担当で確かめる。", go:"hikaku", say:"この商品が合う方と、気をつけていただきたい点の両方を、先にお伝えしますね。", more:"自信が持てない理由が、商品の中身ではなく、売り方への迷いのこともあります。そのときは上長や先輩と、どんな方に合うかを話し合ってみます。お客様のご意向に照らして勧める理由を言えるなら、それが自信の土台になります。", why:"人は相手が良い点しか言わないと、かえって信用しにくくなるからです。合わない点まで言えると、勧める言葉に重みが出ます。" },
      { key:'faq_xshd_keiken_asai', faq:1, grp:'shd', q:"経験が浅いことをお客様にどう伝えればいい？", re:/経験が(浅|少な)|頼りないと思われ|新人であること|若手で[^。]{0,8}信用/, ng:/部下|後輩|新人に|新人が/, head:"経験の浅さは隠さず、確かめる仕組みがあることと一緒に伝えます。", body:"経験の浅さを隠すと、答えられない質問が来たときに困ります。「まだ経験は浅いですが、分からないことはその場で答えず、確かめてご返事します」と先に伝えると、お客様は安心します。上長や詳しい人に確かめられる体制があることを伝えるのも助けになります。経験の代わりに、早く丁寧な返事で信頼を積みます。", acts:["経験の浅さを、確かめる仕組みと一緒に伝える一文を用意する", "答えられない質問は書き留め、確かめて返事をする", "お約束したご返事の時期を守る"], actHead:"今日やること", note:"答えに迷う内容は、社内の上長や所属の保険会社の担当に確かめる。", say:"私はまだ経験が浅いのですが、分からないことはその場でお答えせず、確かめてからご返事します。安心してお聞きください。", more:"若さや経験の浅さは、話しやすさや動きの早さとして受け取ってくださる方もいます。知ったかぶりをせず、確かめた答えを早く返すことを続けると、経験の長さとは別の信頼が育ちます。", why:"お客様が心配しているのは経験の長さそのものより、間違ったことを言われないかだからです。確かめる仕組みが見えると、その心配が小さくなります。" },
      { key:'faq_xshd_omoikomi', faq:1, grp:'shd', q:"お客様の思い込みを否定せずに正すには？", re:/思い込み|勘違い|誤解して|思い違い/, ng:/例え|部下|新人|自分の|事実/, head:"思い込みを正すときは、否定から入らず、そう思われた理由を先に聞きます。", body:"思い込みには、そう考えるだけの理由があります。「違います」と言うと、お客様は自分が否定されたと感じます。先に「そう思われたのは、どんなきっかけでしたか」と聞き、理由を受け止めてから、書面を示して「ここにはこう書いてあります」と事実を並べます。正すのを書面にまかせると、角が立ちません。", acts:["思い込みの理由を先に聞く", "書面の当てはまる所を一緒に読む", "正しい内容を、お客様の言葉で言い直してもらう"], actHead:"今日やること", note:"正しい内容は、保険会社のパンフレットと約款、公的な窓口の案内で確かめてから伝える。", say:"そう思われていたのですね。ここに書いてあることを、一緒に読んでみてもよろしいですか。", more:"思い込みを正したあとは、お客様が恥ずかしい思いをしないよう、同じように考える方は多いと添えます。お客様が正しく、こちらの思い込みだったと分かったときは、素直に認めます。", why:"人は否定されると、考えを守ろうとして、かえって思い込みを強めることがあるからです。理由を聞いて書面で示すと、自分で考え直せます。" },
      { key:'faq_xshd_homeru', faq:1, grp:'shd', q:"お客様をほめるときに気をつけることは？", re:/(お客様|お客さま|相手)を(ほめ|褒め|持ち上げ)|お世辞|見え透/, ng:/部下|新人|後輩|子ども/, head:"ほめるときは、相手の選んだことや行動を、具体的に言葉にします。", body:"見え透いて聞こえるのは、誰にでも言える言葉だからです。「すごいですね」より、「ご家族のために、早くから準備を考えていらっしゃるのですね」のように、相手が選んだことや行動を具体的に言うと伝わります。ほめる言葉で相手を動かそうとすると、お客様はそれを感じ取ります。思ったときだけ言うことです。", acts:["ほめたいと思ったら、相手の行動を一つ具体的に言葉にする", "ほめた直後に提案の話をつなげない", "思ってもいないことは言わない"], actHead:"今日やること", note:"面談での言葉づかいは、社内の手引と所属の保険会社の決まりに沿う。", say:"ご家族のために、早くから準備を考えていらっしゃるのですね。その考えを形にするお手伝いができればと思います。", more:"ほめた直後に申込みの話をすると、ほめ言葉が売り込みの前置きに聞こえます。ほめることと提案は間を空けます。持ち上げすぎると、相手は警戒するか、逆に本音を言いにくくなります。", why:"人は、自分の行動を見てくれていると感じたときに、言葉を素直に受け取るからです。誰にでも言える言葉は、相手を見ていない印に聞こえます。" },
      { key:'faq_xshd_koukai', faq:1, grp:'shd', q:"契約のあと、お客様にこれで良かったのかと言われた", re:/(契約|申込|申し込)[^。]{0,8}(あと|後)[^。]{0,12}(良かったのか|よかったのか|後悔|不安|迷い)|これで(良|よ)かったのか/, ng:/キャンセル|取り消|取消|撤回|部下|新人|迷い始め/, head:"契約のあとの迷いは、決めた理由をお客様と一緒に振り返ると落ち着きます。", body:"大きな決めごとのあとに迷いが出るのは自然なことです。まず迷いの中身を聞き、面談の記録にある、お客様が大事にしたいと言われたことと、選んだ理由を一緒に振り返ります。迷いが解けないときは、申込みのあとに取りやめる仕組みや見直しの方法があるかを書面に沿ってお伝えし、お客様が選べるようにします。", acts:["迷いの中身を、お客様の言葉で聞く", "記録にある選んだ理由を、一緒に読み返す", "取りやめる仕組みや見直しの方法を、書面に沿って伝える"], actHead:"今日やること", note:"申込みのあとに取りやめる仕組みと見直しの手続きは、保険会社の書面と約款、所属の保険会社の担当で確かめる。", go:"iko", say:"迷われるのは自然なことです。お申し込みのときに大事にしたいとおっしゃっていたことを、一緒に振り返ってみませんか。", more:"迷いを打ち消そうとして良い点だけを並べると、お客様は話を聞いてもらえていないと感じます。迷いの理由が説明の不足にあるなら、そこを補います。お客様が取りやめを選ぶなら、それもお客様の判断として手続きを手伝います。", why:"人は決めたあと、選ばなかった案の良さが気になり始めることがあるからです。自分が大事にしたことを思い出すと、選んだ理由に立ち返れます。" },
      { key:'faq_xshd_keigo', faq:1, grp:'shd', q:"敬語が堅すぎて距離を感じさせてしまう", re:/敬語[^。]{0,6}(堅|固|硬)|(丁寧|かしこまり)すぎ|言葉づかいが(堅|固|硬)|壁があると言われ/, ng:/部下|新人|上司|メール/, head:"敬語はそのままに、相手の言葉を拾う一言で距離を縮めます。", body:"距離を感じさせるのは、敬語そのものより、決まった言い回しだけで話しているからです。敬語は崩さず、相手が使った言葉をそのまま拾って返す、自分の気持ちを一言添える、の二つを足すと、堅さがやわらぎます。くだけた言葉に変えるのは、相手がくだけてきたときに、少しずつにします。", acts:["相手が使った言葉を、そのまま一度拾って返す", "説明の合間に、自分の気持ちを一言添える", "くだけた言葉は、相手に合わせて少しずつにする"], actHead:"今日やること", note:"お客様への言葉づかいは、社内の手引に沿う。", say:"今おっしゃった、毎日の暮らしを大事にしたいというお気持ち、私もとても大事だと感じました。", more:"書面の説明は、言葉を崩さずに正確に伝えます。雑談や受け止めの一言では少しやわらかい言葉を使うなど、場面で使い分けます。距離を縮めようとして、なれなれしくなりすぎないよう気をつけます。", why:"人は自分の言葉を拾ってもらうと、決まり文句ではなく自分に向けた言葉だと感じるからです。" },
      { key:'faq_xshd_kibou_soenai', faq:1, grp:'shd', q:"お客様の希望に沿えないことを伝えるには？", re:/(希望|要望)[^。]{0,6}(沿え|添え|応えられ|お応えでき|断らな)|できないことを[^。]{0,4}(どう)?伝え/, ng:/部下|上司|社長|保険金|給付金|告知|引受|加入でき/, head:"希望に沿えないときは、できない理由と、代わりにできることを一緒に伝えます。", body:"できないとだけ伝えると、お客様は突き放されたと感じます。まず希望を受け止め、できない理由を短く伝え、代わりにできることを一つでも示します。理由が保険会社や決まりによるものなら、そのことを正直に伝えます。あいまいな言い方で期待を持たせるほうが、あとで信頼を失います。", acts:["希望を受け止める一言から話し始める", "できない理由を短く、正直に伝える", "代わりにできることを一つ以上用意する"], actHead:"今日やること", note:"できる・できないの判断は、保険会社の決まりと約款、社内の上長に確かめてから伝える。", say:"ご希望はよく分かりました。その形は決まりの上でお受けできないのですが、代わりにこういう形でしたらご用意できます。", more:"できない理由を説明しすぎると、言い訳に聞こえます。理由は短く、代わりの案に時間を使います。代わりの案が無いときも、確かめられる先や、相談できる窓口を示すと、お客様は次に進めます。", why:"人は、断られたことよりも、そのあと何もしてもらえないことに不満を感じるからです。代わりの道があると、話が前に進みます。" },
      { key:'faq_xshd_zenkai_oboeru', faq:1, grp:'shd', q:"前回の面談の話を覚えておくには？", re:/(前回|前の面談|前に話した)[^。]{0,10}(覚えて|忘れ|思い出せ|生かし|活かし)/, ng:/部下|上司|会議/, head:"前回の話は、面談の直後に三行で書き、次の面談の前に読み返します。", body:"前回の話を覚えておくのは、記憶力ではなく仕組みです。面談が終わったらすぐに、お客様が大事にしていること、気になっていること、次にすること、の三行を書きます。次の面談の前にそれを読み返し、始めに「前回は〜とおっしゃっていましたね」と一言添えると、お客様は覚えてもらえていると感じます。", acts:["面談の直後に、三行の記録を書く", "次の面談の前に、その記録を読み返す", "面談の始めに、前回の話を一言添える"], actHead:"今日やること", note:"面談の記録の残し方と保管は、社内の手引と個人情報の取り扱いの規程に沿う。", say:"前回、ご家族の旅行を大事にしたいとおっしゃっていましたね。その後、何か変わったことはありましたか。", more:"記録には、お客様の言葉をそのまま残します。あとで読み返したとき、言葉の温度まで思い出せます。ご家族のお名前や行事の日は次の会話のきっかけになりますが、扱いには気をつけます。", why:"人は前に話したことを覚えてもらえていると、大事にされていると感じるからです。記録があれば、忙しい時期でも話の続きから始められます。" },
      { key:'faq_xshd_kirawaretakunai', faq:1, grp:'shd', q:"お客様に嫌われたくなくて、言うべきことが言えない", re:/嫌われ(たくな|るのが怖|るのがこわ)|悪く思われたくな|言うべきことが言えな|言いにくいことを言えな/, ng:/生保|生命保険|損保|部下|上司|社長に/, head:"言いにくいことほど、お客様を守るために言うと決めておきます。", body:"嫌われたくないのは、お客様との関係を大事にしているからです。けれど、注意点や合わない点を言わずに済ませると、あとで困るのはお客様です。言いにくいことは「大事なことなので、お伝えしておきます」と前置きし、事実を短く伝え、どうするかはお客様に選んでもらいます。言うべきことを言う人のほうが、長く信頼されます。", acts:["言いにくいことを、面談の前に一行で書いておく", "大事なことなのでと前置きして、短く伝える", "どうするかは、お客様に選んでもらう"], actHead:"今日やること", note:"お伝えしなければならない注意の事項は、所属の保険会社と社内の募集の手引で確かめる。", say:"大事なことなので、お伝えしておきます。この点は、お客様にとって気をつけていただきたいところです。", more:"言いにくいことを言ったあと、お客様の反応が硬くなっても、慌てて取り消さないことです。言った理由を落ち着いて伝え、お客様の考えを聞きます。嫌われないことより、あとで後悔させないことを大事にします。", why:"お客様は、良いことしか言わない人より、気をつけることまで言ってくれる人を頼りにするからです。" },
      /* szi.json */
      { key:'faq_xszi_shotoku_shurui', faq:1, grp:'szi', q:"所得の種類にはどんなものがある？", re:/所得の(種類|区分|分け方)|(何|なん)種類の所得|所得は(何|なん)種類|所得[^。]{0,6}(いくつに分かれ|何種類)/, head:"所得税では、所得を十の種類に分け、種類ごとに計算のしかたを決めています。", body:"所得の種類は、利子・配当・不動産・事業・給与・退職・山林・譲渡・一時・雑の十です。種類ごとに、収入から引けるもの（必要経費や給与所得控除など）が違います。多くはほかの所得と合わせて税率を当てますが、退職所得や土地建物の譲渡所得などは分けて計算します。同じお金でも、どの種類に当たるかで計算が変わります。", acts:["お客様の収入を、給与・年金・副収入・売った財産などに分けて書き出す", "どの種類に当たるか迷う収入は、税理士か税務署で確かめていただく", "保険の受け取りがあれば、どの所得に当たるかを保険会社の書類で確かめる"], actHead:"現場で使うなら", note:"所得の種類と計算の決まりは国税庁の公表で確かめる。どの種類に当たるかの個別の判断は税理士か税務署の窓口。", say:"所得は十の種類に分かれていて、種類ごとに税金の計算のしかたが違います。どの種類に当たるかで変わるので、迷う収入は税理士に確かめていただきましょう。", more:"所得と収入は同じ意味ではありません。収入から必要経費や控除を引いたものが所得になります。給与なら給与所得控除、年金なら公的年金等控除を引きます。種類が違えば引けるものも違うので、まず種類を決めることが計算の出発点になります。", why:"所得税は、働いて得たお金・財産を売ったお金・たまたま得たお金など、性質の違う収入を同じ物差しで測らないように、種類ごとに計算のしかたを分けているからです。" },
      { key:'faq_xszi_sogo_bunri', faq:1, grp:'szi', q:"総合課税と分離課税の違いは？", re:/総合課税|分離課税/, head:"総合課税はほかの所得と合わせて税率を当て、分離課税はほかと分けて計算します。", body:"総合課税は、給与・事業・年金などの所得を合計し、合計額に応じて段階的に上がる税率を当てる形です。分離課税は、退職所得・土地建物や株式の譲渡所得などを、ほかの所得と分けて計算する形です。分離課税のうち、自分で申告するものを申告分離課税、支払いのときに税が差し引かれて終わるものを源泉分離課税と呼びます。", acts:["お客様の所得が、合算されるものか分けて計算されるものかを書き分ける", "株の売却や配当がある方には、課税の方式の選び方を税理士に確かめていただく", "どの方式になるかを言い切らず、国税庁の公表か税務署の窓口で確かめる"], actHead:"現場で使うなら", note:"どの所得がどの課税の方式になるかは国税庁の公表で確かめる。方式の選び方と税額の判断は税理士か税務署の窓口。", say:"税金の計算には、ほかの収入と合わせて計算する形と、分けて計算する形があります。どちらになるかは所得の種類で決まるので、細かいところは税理士に確かめましょう。", more:"総合課税は、所得が増えるほど上の段の税率がかかる仕組みです。分離課税にすると、その所得だけを別の決まった税率で計算します。配当のように、総合課税と分離課税のどちらかを選べる所得もあり、選び方で健康保険料などに響くこともあるので、税理士と一緒に確かめます。", why:"退職金や長く持った財産を売ったお金は、何年もかけてたまった分が一度に入るので、ほかの所得と合わせると税率が急に上がりすぎることがあるため、分けて計算する仕組みが置かれているのが理由の一つです。" },
      { key:'faq_xszi_jigyo_zatsu', faq:1, grp:'szi', q:"副業の所得は事業所得と雑所得のどちら？", re:/(事業所得|雑所得)[^。]{0,12}(違い|どっち|どちら|分かれ|区別|判断|なる)|(副業|業務)[^。]{0,10}(事業所得|雑所得)/, ng:/していい|してもいい|就業規則|社内|うちの会社|規定|許可|禁止/, head:"仕事の規模や続け方、帳簿を残しているかなどを見て、事業所得か雑所得かが決まります。", body:"事業所得は、自分の計算と危険のもとで、続けて行う仕事から生じる所得になります。副業の収入は、規模が小さく、生活の中心でないときは雑所得に当たることがあります。国税庁の通達では、帳簿書類を残しているかどうかも判断の手がかりの一つに挙げられています。どちらに当たるかで、赤字をほかの所得と差し引けるかなどが変わります。", acts:["副業の内容・続け方・帳簿を残しているかを、お客様に聞き取る", "どちらに当たるかは言い切らず、税理士か税務署で確かめていただく", "勤め先の決まりで副業が認められているかは、ご本人に勤め先で確かめていただく"], actHead:"現場で使うなら", note:"区分の考え方は国税庁の通達と公表で確かめる。個別の判断は税理士か税務署の窓口。副業そのものの可否は勤め先の規程。", say:"副業の所得は、仕事の規模や続け方、帳簿を残しているかなどで、事業所得か雑所得かが分かれます。ご自身がどちらになるかは、税理士に確かめていただくのが確かです。", more:"事業所得になると、青色申告の特別控除や、赤字をほかの所得と差し引く損益通算が使える場面があります。雑所得では、こうした仕組みが使えません。ただし、事業所得に当たるかは名前の付け方ではなく実態で判断されるので、帳簿をつけて記録を残すことが出発点です。", why:"事業所得には損益通算などの扱いがあるため、生活の中心として続けている仕事と、空いた時間の小さな収入とを分けて扱う必要があり、その線を実態で引く仕組みになっているからです。" },
      { key:'faq_xszi_jouto', faq:1, grp:'szi', q:"譲渡所得とは？", re:/譲渡所得|(財産|資産|ゴルフ会員権|貴金属|金地金)を?売(った|る|却)[^。]{0,10}(税金|所得税|所得|確定申告)/, ng:/株|nisa|相続|マイホーム|住宅|マンション|自宅|居住用|空き家|家を/, head:"土地・建物・株式などの財産を売って得た利益にかかる所得になります。", body:"譲渡所得は、土地・建物・株式・ゴルフ会員権などの財産を売ったときの所得になります。売った金額から、買ったときの費用と売るための費用を引いて計算します。土地と建物は、持っていた期間で長期と短期に分かれ、ほかの所得と分けて計算します。お住まいを売ったときには特例があり、使えるかは要件で決まります。", acts:["売った財産が何か、いつ手に入れたかを最初に確かめる", "買ったときの契約書や領収書が残っているかを、お客様に探していただく", "特例が使えるかと税額は、税理士か税務署で確かめていただく"], actHead:"現場で使うなら", note:"長期と短期の線・特例の要件は国税庁の公表で確かめる。個別の税額と特例の判断は税理士か税務署の窓口。", say:"財産を売って利益が出ると、譲渡所得として税金がかかることがあります。買ったときの書類が計算のもとになるので、まず契約書や領収書を探しておきましょう。", more:"買ったときの費用が分からないと、売った金額のごく一部しか差し引けない決まりがあり、税額が大きくなることがあります。相続で受け継いだ財産は、亡くなった方が買ったときの費用を引き継ぎます。売る前に、書類の有無と特例の要件を税理士と確かめておくのが確かです。", why:"財産の値上がりは、持っている間ではなく売ったときに初めて形になるので、売った時点で利益を計算し、持っていた期間の長さに応じて扱いを分ける仕組みになっているからです。" },
      { key:'faq_xszi_haigusha', faq:1, grp:'szi', q:"配偶者控除と配偶者特別控除の違いは？", re:/配偶者特別控除|配偶者控除[^。]{0,12}(違い|ちがい|どうなる|受けられ|なくなる|減る|消える)|(妻|夫|配偶者)の?(パート|アルバイト|収入)[^。]{0,14}配偶者控除/, ng:/社会保険|健康保険|年金/, head:"配偶者の所得が一定以下なら配偶者控除、それを超えても一定までは配偶者特別控除です。", body:"配偶者の合計所得が一定以下なら配偶者控除を受けられます。それを超えても一定の範囲までは、配偶者の所得に応じて段階的に小さくなる配偶者特別控除を受けられます。また、控除を受ける本人の合計所得が一定を超えると、額が小さくなり、さらに超えると受けられません。判断はその年の最後の日の状況で行います。", acts:["ご本人と配偶者の、その年の見込みの収入を書き出す", "税の控除と健康保険や年金の扶養は基準が別、と最初にお伝えする", "最新の線の額は、国税庁の公表か勤め先の担当の方で確かめていただく"], actHead:"現場で使うなら", note:"控除の線と額は国税庁の公表で確かめる。健康保険と年金の扶養は勤め先と健康保険組合。税額の判断は税理士。", say:"配偶者の所得が一定以下なら配偶者控除、超えても一定までは配偶者特別控除が段階的に受けられます。健康保険の扶養とは基準が別なので、両方を分けて確かめましょう。", more:"配偶者特別控除は、配偶者の所得が増えるにつれて少しずつ小さくなる作りです。そのため、配偶者が少し多く働いても、世帯の手取りがいきなり減る形にはなりにくくなっています。手取りに大きく響きやすいのは、健康保険や年金の扶養から外れる線のほうなので、そちらも勤め先で確かめます。", why:"配偶者を養う負担を税額に映しつつ、配偶者が働く量を抑えすぎないように、所得に応じてなだらかに控除を小さくする仕組みが組み合わされているからです。" },
      /* ygo.json */
      { key:'faq_xygo_museneki', faq:1, grp:'ygo', q:"無選択型の保険とは？", re:/(無選択型保険|無選択型)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(無選択型保険|無選択型)[?？。!！\s]*$/, head:"無選択型は、健康状態の告知や診査をしないで入れる保険です。", body:"主に終身保険や医療保険にある形で、健康状態を問わない代わりに、同じ保障でも保険料は高めに決められ、保険金額や給付の上限も小さく設定されるのが一般的です。加入から決められた期間内に病気で亡くなったときは、保険金ではなく払い込んだ保険料に当たる額の支払いにとどまる、といった条件が付く商品もあります。", acts:["告知のある保険や引受基準緩和型に入れるかを、先に確かめる", "払い込む保険料の合計と保険金額を並べて、お客様と一緒に見る", "加入して間もない時期の支払いの条件を、パンフレットで指さして説明する"], actHead:"お客様と話すなら", note:"保険料・保険金額の上限・加入して間もない時期の支払いの条件は商品ごとに違う。契約概要・約款と保険会社の窓口で確かめる。", say:"健康のことを伺わずに入れる代わりに、保険料や保障の大きさに条件がある保険です。ほかの入り方ができないかを、先に一緒に見てみましょう。", more:"よくある勘違いは、入りやすいからいちばん安心だと考えることです。持病があっても、告知の項目が少ない引受基準緩和型や、通常の保険に条件付きで入れることがあります。先に入れる形を順に確かめ、それでも難しいときの選択肢として話します。", why:"健康状態を確かめない分、保障を受ける人の病気の割合が高くなるからです。加入者どうしの公平を保つため、保険料や保障の上限、加入して間もない時期の支払いに条件を付けて釣り合いを取っています。" },
      { key:'faq_xygo_outoubi', faq:1, grp:'ygo', q:"契約応当日とは？", re:/(年単位の契約応当日|月単位の契約応当日|契約応当日|応当日)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(年単位の契約応当日|月単位の契約応当日|契約応当日|応当日)[?？。!！\s]*$/, head:"契約応当日は、契約日に当たる毎月・毎年の同じ日のことです。", body:"毎月の同じ日を月単位の契約応当日、毎年の契約日と同じ月日を年単位の契約応当日と呼びます。保険料の払込み、更新、配当や生存給付の支払いなど、契約の節目はこの日を基準に決まることが多くあります。契約日に当たる日が無い月は、その月の末日とするなど、扱いが約款で決められています。", acts:["保険証券で契約日を確かめ、更新や払込みの節目がいつになるかをお客様と一緒に書き出す", "更新型の契約は、次の年単位の契約応当日を年間の連絡の予定に入れておく", "保険料の引き落としの日とは別のことがあるので、口座振替の日も合わせて確かめる"], actHead:"お客様と話すなら", note:"何を応当日で決めるか、応当日が無い月の扱いは約款で決まっている。約款と保険会社の窓口で確かめる。", say:"契約日と同じ日付が、毎月・毎年の契約の節目になります。次の更新がいつかを、証券で一緒に確かめておきましょう。", more:"例えば、更新型の定期保険は年単位の契約応当日に更新され、保険料が変わることがあります。お客様が引き落としの額の変化に驚かれる前に、その日がいつかを伝えておくと、問い合わせや解約の申し出も落ち着いて話せます。", why:"保険は期間で保障する契約なので、保険料の期間や保障の区切りを決める基準の日が要るからです。契約日を基準にすると、どの契約も同じ考え方で区切れます。" },
      { key:'faq_xygo_kigetsu', faq:1, grp:'ygo', q:"払込期月とは？", re:/(払い込み期月|払込みの期月|払込期月)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(払い込み期月|払込みの期月|払込期月)[?？。!！\s]*$/, head:"払込期月は、保険料を払い込むことになっている月のことです。", body:"月払いなら毎月の契約応当日が属する月の初日から末日まで、年払いなら年単位の契約応当日が属する月が、一般的な払込期月です。この間に払い込めないと、すぐに失効するのではなく、払込猶予期間に入ります。猶予期間の長さや、その後の扱いは払い方と約款で違います。", acts:["口座の残高不足が続いたお客様には、払込期月と猶予期間の考え方を早めに伝える", "引き落としができなかった連絡が来たら、払い込みの方法と期限を保険会社に確かめてから案内する"], actHead:"お客様と話すなら", note:"払込期月と猶予期間の扱いは、払い方と商品で違う。約款と保険会社の窓口で、そのお客様の契約について確かめる。", say:"保険料は、決まった月の中で払い込む決まりになっています。引き落としができなかったときも、まず一緒に手続きを確かめましょう。", more:"猶予期間を過ぎても払い込みが無いと、契約が失効したり、解約返戻金がある契約では保険料が自動で立て替えられたりします。どちらになるかは契約によるので、思い込みで案内せず、保険会社に確かめてから伝えます。", why:"保険料を前もって払う仕組みで保障が続くので、いつまでに払うかの区切りが要るからです。月の中で幅を持たせることで、給料日や引き落としの日の違いに合わせられます。" },
      { key:'faq_xygo_futanpo', faq:1, grp:'ygo', q:"部位不担保とは？", re:/(特定部位の不担保|特定部位不担保|部位不担保法|部位不担保)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(特定部位の不担保|特定部位不担保|部位不担保法|部位不担保)[?？。!！\s]*$/, head:"部位不担保は、体の特定の部位の病気を、決められた期間は保障から外す引受けの条件です。", body:"告知の内容によっては、保険会社が契約を断る代わりに、過去に治療した部位とその病気について、決められた期間は給付金を支払わない条件で引き受けることがあります。期間が過ぎれば、その部位も保障の対象になる形が一般的です。どの部位を、どれだけの期間外すかは、保険会社の引受けの判断で決まります。", acts:["条件付きの承諾が出たら、外れる部位と期間を書面でお客様と一緒に確かめる", "条件に納得されないときは、ほかの入り方も含めてお客様が選べるように並べる", "外れた部位の病気で入院しても出ないことを、言葉を濁さずに伝える"], actHead:"お客様と話すなら", note:"対象の部位・期間・条件は保険会社の引受けの判断と約款で決まる。承諾の書面と保険会社の窓口で確かめる。", say:"この部位の病気だけは、決められた期間、保障の対象外という条件で引き受けますという返事です。それ以外の保障は通常どおりなので、条件の中身を一緒に確かめましょう。", more:"よくある勘違いは、外れた部位のほかも保障が弱くなると思うことです。外れるのは書面に書かれた部位と病気だけです。逆に、外れた部位の病気が原因の入院や手術は、期間中は請求しても出ないので、請求のときに慌てないよう、最初にはっきり伝えておきます。", why:"再発などの起こりやすさが高い部位をそのまま引き受けると、加入者どうしの公平が崩れるからです。断るのではなく、その部分だけ外すことで、ほかの保障に入れる道を残しています。" },
      { key:'faq_xygo_saihoken', faq:1, grp:'ygo', q:"再保険とは？", re:/(再保険会社|再保険|出再|受再)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(再保険会社|再保険|出再|受再)[?？。!！\s]*$/, head:"再保険は、保険会社が引き受けた契約の一部を、別の保険会社に引き受けてもらう仕組みです。", body:"大きな災害や保険金額の大きな契約が重なると、一社だけでは支払いを抱えきれないことがあります。そこで保険会社は、引き受けた契約の一部を再保険会社などに移し、保険料の一部を払う代わりに支払いの一部を分担してもらいます。再保険を使っても、お客様との契約の相手は元の保険会社のままです。", acts:["お客様に聞かれたら、保険会社どうしの支払いの備えの仕組みとして短く説明する", "支払いや手続きの窓口は、元の保険会社のままであることを伝える"], actHead:"お客様と話すなら", note:"各社の再保険の使い方は経営の情報で、開示の範囲は会社ごとに違う。詳しくは保険会社の開示資料と窓口で確かめる。", say:"保険会社も、大きな災害に備えて、別の保険会社と支払いを分け合う仕組みを持っています。お手続きの窓口は、これまでどおり同じ保険会社です。", more:"再保険は、地震や台風のように一度に多くの契約で支払いが起きる損害保険で特に使われます。生命保険でも、保険金額の大きな契約や新しい種類の保障で使われます。お客様が直接かかわる場面は、ほとんどありません。", why:"支払いが一時に集中すると、保険会社の体力では払い切れないおそれがあるからです。支払いを広く分け合うことで、保険会社は約束どおり支払える力を保ち、大きな契約も引き受けられるようになります。" },
      { key:'faq_xygo_hoshou', faq:1, grp:'ygo', q:"年金の保証期間とは？", re:/(年金の保証期間|保証期間付|保証期間)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(年金の保証期間|保証期間付|保証期間)[?？。!！\s]*$/, head:"保証期間は、受け取る人の生死にかかわらず、年金が支払われる期間です。", body:"保証期間付終身年金では、保証期間の間に受取人が亡くなっても、残りの期間の年金や、それに当たる一時金が遺族に支払われます。保証期間を過ぎたあとは、生きている間だけ年金が続きます。保証期間の長さは契約のときに選び、長くするほど同じ保険料で受け取る年金の額は小さくなるのが一般的です。", acts:["保証期間の間に亡くなったとき、誰がどう受け取るかを一緒に確かめる", "年金の受取人と、残りを受け取る人の指定を、証券で確かめる", "保証期間の長さを選ぶ場面では、年金の額との兼ね合いを並べて見せる"], actHead:"お客様と話すなら", note:"保証期間の長さ・残りの受け取り方・税の扱いは商品と契約で違う。約款と保険会社、税は税理士・税務署で確かめる。", say:"この期間の間は、もしものことがあっても、残りの年金がご家族に渡る形です。期間を過ぎたあとは、生きている間ずっと受け取る年金になります。", more:"よくある勘違いは、終身年金だと早く亡くなると何も残らないと思うことです。保証期間があれば、その間の残りは遺族に渡ります。一方で、遺族が受け取る残りの年金には税がかかる場合があるので、受け取り方と税は税理士にも確かめるよう伝えます。", why:"終身年金は長生きに備える仕組みですが、早く亡くなったときに払い込んだお金が戻らないと感じる方が多いからです。保証期間を設けることで、長生きへの備えと、遺族に残したい気持ちの両方に応えています。" },
      { key:'faq_xygo_genshi', faq:1, grp:'ygo', q:"年金原資とは？", re:/(年金の原資|年金原資)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(年金の原資|年金原資)[?？。!！\s]*$/, head:"年金原資は、年金の支払いを始めるときに積み上がっている、年金のもとになるお金です。", body:"個人年金保険では、払い込んだ保険料が運用されて積み上がり、年金の支払いが始まる時点の積立金が年金原資になります。年金の額は、この年金原資と、受け取る期間、その時点の計算の基準などで決まります。変額個人年金保険では、運用の成果によって年金原資が変わります。", acts:["年金開始のお知らせが届いたら、年金原資と受け取り方の選択肢をお客様と一緒に見る", "一括で受け取るか年金で受け取るかで税の扱いが変わりうることを伝え、税理士にもつなぐ"], actHead:"お客様と話すなら", note:"年金原資の計算・最低保証の有無・受け取り方の選択肢は商品で違う。約款と保険会社、税は税理士・税務署で確かめる。", say:"年金のもとになるお金がどれだけ積み上がっているかで、受け取る年金の額が決まります。受け取り方の選択肢と一緒に、お知らせを見てみましょう。", more:"年金原資に最低保証がある変額個人年金保険もあれば、無いものもあります。受け取りの直前に相場が下がっていると年金原資が小さくなることがあるので、年金開始の時期を動かせるか、受け取り方を変えられるかを、保険会社に確かめておくと選択肢が広がります。", why:"年金は、積み上がったお金を受け取る期間で割り振って払う仕組みなので、もとになる額が決まらないと、年金の額も決まらないからです。年金原資は、積み立てる時期と受け取る時期をつなぐ区切りの額です。" },
      { key:'faq_xygo_sueoki', faq:1, grp:'ygo', q:"据置期間とは？", re:/(据え置き期間|据え置き|据置期間|据置)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(据え置き期間|据え置き|据置期間|据置)[?？。!！\s]*$/, head:"据置期間は、保険料の払い込みを終えてから、年金の受け取りを始めるまでの期間です。", body:"個人年金保険などでは、払い込みが終わってすぐ年金を受け取らずに、しばらく置いてから受け取りを始める契約があります。この間も積立金は運用され続けます。また、満期保険金や死亡保険金をすぐに受け取らず、保険会社に預けておく扱いを据置と呼ぶこともあり、できるかどうかと条件は保険会社で違います。", acts:["払い込みの終わりと年金の始まりの時期を、証券で並べて確かめる", "受け取りを据え置けるかと、その間の扱いを保険会社に確かめてから案内する"], actHead:"お客様と話すなら", note:"据置の可否・期間中の利率や扱い・税は商品と保険会社で違う。約款と保険会社、税は税理士・税務署で確かめる。", say:"保険料を払い終えてから、年金を受け取り始めるまでの間を置く期間です。いつから受け取るかを、証券で一緒に確かめておきましょう。", more:"退職の時期と公的年金の受け取りの時期に合わせて、個人年金の始まりを決める方がいます。据置期間の利率がどう扱われるか、途中で始まりの時期を変えられるかは商品で違うので、保険会社に確かめてから話します。", why:"収入が途切れる時期と年金の受け取りを合わせたい、という暮らしの事情に応えるためです。払い終える時期と使う時期を分けられるようにしています。" },
      { key:'faq_xygo_seizon', faq:1, grp:'ygo', q:"生存給付金とは？", re:/(生存保険金|生存給付金|祝い金|祝金)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(生存保険金|生存給付金|祝い金|祝金)[?？。!！\s]*$/, head:"生存給付金は、決められた時期に被保険者が生きていると支払われるお金です。", body:"学資保険の進学の時期の給付や、一部の医療保険・終身保険で決められた時期ごとに受け取るお金などが、生存給付金や祝金と呼ばれます。受け取らずに保険会社に据え置ける商品もあります。生存給付金の分も保険料に含まれているので、払った保険料の一部を前もって受け取る形と考えると分かりやすくなります。", acts:["受け取りの時期と、据え置いたときの扱いを証券で一緒に確かめる", "受け取ったお金の使い道を、お客様の予定と一緒に決めておく", "税の扱いは契約の形で変わるので、気になる方は税理士・税務署につなぐ"], actHead:"お客様と話すなら", note:"支払いの時期・据置の可否・税の扱いは商品と契約で違う。約款と保険会社、税は税理士・税務署で確かめる。", say:"この保険は、決められた時期にお元気でいらっしゃると受け取れるお金があります。保険料の中から前もって受け取る形なので、使い道を一緒に決めておきましょう。", more:"よくある勘違いは、生存給付金はおまけでもらえると思うことです。その分も保険料に入っています。また、据え置いたお金を忘れたままのお客様もいるので、契約の点検のときに、据え置いた生存給付金が残っていないかを保険会社に確かめます。", why:"学費や暮らしの節目に合わせてお金を受け取りたい、という目的に応えるためです。そのお金は保険料から積み立てているので、受け取る分だけ保険料や満期の額に織り込まれています。" },
      { key:'faq_xygo_jiyuu', faq:1, grp:'ygo', q:"支払事由とは？", re:/(支払い事由|支払の事由|保険事故|支払事由)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(支払い事由|支払の事由|保険事故|支払事由)[?？。!！\s]*$/, head:"支払事由は、保険金や給付金が支払われる条件として、約款に決められた出来事です。", body:"死亡、入院、手術、事故による損害など、どんなときに、どの条件を満たせば支払うかが約款に書かれています。損害保険では、補償の対象になる出来事を保険事故と呼ぶことが多くあります。反対に、支払事由に当たっても支払わない場合を免責事由と呼び、こちらも約款に決められています。", acts:["請求の相談を受けたら、まず約款の支払事由のところをお客様と一緒に開く", "当たるかどうかは保険会社が決めるので、その場で出る・出ないを言い切らない", "免責事由も同じページで確かめ、思い込みの説明をしない"], actHead:"お客様と話すなら", note:"支払事由に当たるかは、保険会社が約款と書類で決める。約款・しおりと保険会社の窓口で確かめる。", say:"保険金が出るかどうかは、約款に書かれた条件に当てはまるかで決まります。その場で出る・出ないを決めずに、書類をそろえて保険会社に確かめましょう。", more:"例えば医療保険の入院給付金でも、病気やけがの治療を目的とした入院であることなど、細かい要件があります。お客様のお話では当てはまりそうでも、医師の書類の内容で変わるので、請求できそうなら請求していただき、判断は保険会社に任せます。", why:"保険は、決めた出来事が起きたときだけ支払う約束なので、条件をはっきり書いておかないと、払う・払わないの判断が人によって変わってしまうからです。同じ条件で公平に支払うために、約款に決めています。" },
      { key:'faq_xygo_juudai', faq:1, grp:'ygo', q:"重大事由による解除とは？", re:/(重大事由による解除|重大事由解除|重大事由)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(重大事由による解除|重大事由解除|重大事由)[?？。!！\s]*$/, head:"重大事由による解除は、信頼関係を壊す重大な事情があるとき、保険会社が契約を解除できる決まりです。", body:"保険金を受け取る目的でわざと事故を起こした、請求で偽りをした、といった重大な事情があると、保険会社は契約を解除できます。保険法に決まりがあり、約款にも書かれています。重大な事情が起きたあとに生じた出来事の分は、支払われないことがあります。反社会的勢力に当たる場合を含める約款も一般的です。", acts:["請求の内容に不自然な点があっても、こちらで疑いを口にせず、事実だけを保険会社に伝える", "お客様に解除の話を持ち出さず、判断は保険会社と社内の上長に任せる"], actHead:"お客様と話すなら", note:"解除に当たるかは保険会社が決め、法律上の争いは弁護士の領分。疑いがあるときは社内の手順で上長と保険会社へ報告する。", say:"保険金のお支払いは、保険会社が書類と事実を確かめて決めます。お分かりのことを、そのままお伝えいただければ大丈夫です。", more:"よくある勘違いは、告知義務違反と同じものと考えることです。告知義務違反は加入のときの告知の問題、重大事由は不正な請求や信頼関係を壊す行いの問題で、別の決まりです。募集人が気づいた不自然な点は、推測を交えずに社内の手順で報告します。", why:"保険は加入者どうしが保険料を出し合う仕組みなので、不正な請求を許すと、正直な加入者の負担が増えてしまうからです。信頼関係を壊す行いには契約を終わらせる手段が要るので、法律で決めています。" },
      { key:'faq_xygo_hokenhou', faq:1, grp:'ygo', q:"保険法とは？", re:/(保険法と保険業法|保険法)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(保険法と保険業法|保険法)[?？。!！\s]*$/, head:"保険法は、保険会社と契約者のあいだの、契約のルールを決めた法律です。", body:"告知義務、保険金の支払い、契約の解除、受取人の変更など、契約の決まりを定めています。保険会社や代理店を監督し、募集の決まりを定める保険業法とは役割が違います。共済の契約も、保険法の契約のルールの対象になります。約款は、保険法の決まりに沿って作られています。", acts:["告知や受取人の相談で、契約のルールの土台として約款と一緒に説明する", "募集のやり方の決まりは、保険業法と社内の手順で確かめる、と分けて考える"], actHead:"お客様と話すなら", note:"個々の契約の扱いは約款と保険会社で確かめる。法律上の判断が要る争いは弁護士の領分。", say:"保険法は保険の契約のルールを決めた法律で、約款もこれに沿って作られています。細かな扱いは、契約の約款で一緒に確かめましょう。", more:"よくある勘違いは、保険法と保険業法を同じものと思うことです。保険法は契約のルール、保険業法は保険会社や代理店がどう業務を行うかの決まりです。例えば告知義務は保険法、意向把握や比較推奨は保険業法の側の話です。", why:"保険は、加入するときに分からないことが多く、保険会社のほうが知識を多く持っている契約だからです。契約者が困らないよう基本のルールを法律で決め、約款がそれを下回らないようにしています。" },
      { key:'faq_xygo_gyakusentaku', faq:1, grp:'ygo', q:"逆選択とは？", re:/(逆選抜|逆選択)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(逆選抜|逆選択)[?？。!！\s]*$/, head:"逆選択は、保険の対象の出来事が起きやすい人ほど、保険に入りたがる傾向のことです。", body:"健康に不安のある人ほど入院の保障を、事故の多い人ほど手厚い補償を求めやすく、そのままでは支払いが増えて保険料が上がり、健康な人が入らなくなる悪い流れが生まれます。告知や診査、引受けの基準、保険料の区分は、この逆選択を防ぎ、加入者どうしの公平を保つための仕組みです。", acts:["告知を面倒がるお客様には、加入者どうしの公平のための仕組みだと説明する", "体調を崩してから急いで入りたいという相談では、告知を正しく書くことを最初に伝える"], actHead:"お客様と話すなら", note:"引受けの基準・告知の項目は保険会社ごとに違う。所属保険会社の引受けの手引と窓口で確かめる。", say:"保険は、皆さんが公平に保険料を出し合う仕組みなので、加入のときに健康のことを伺っています。正しく書いていただくことで、いざというときに安心して請求できます。", more:"体調を崩してから入ろうとする方が告知を軽く書くと、あとで支払われない、契約が解除される、といった形でお客様自身が困ることになります。健康なうちに考えておく意味を、急がせる言い方ではなく、仕組みの話として伝えます。", why:"保険料は、加入者全体で起きる出来事の割合から決めているので、起きやすい人ばかりが集まると、決めた保険料では足りなくなるからです。それを防ぐために、加入のときに状態を確かめています。" },
      { key:'faq_xygo_moral', faq:1, grp:'ygo', q:"モラルリスクとは？", re:/(モラル・ハザード|モラルハザード|モラルリスク|道徳的危険)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(モラル・ハザード|モラルハザード|モラルリスク|道徳的危険)[?？。!！\s]*$/, head:"モラルリスクは、保険金を目的に事故を起こしたり、偽って請求したりするおそれのことです。", body:"保険金を目当てにした放火や、けがを大げさに申し立てる請求などが代表です。似た言葉のモラルハザードは、保険に入っていることで注意が緩み、事故が起きやすくなることを指す使い方が一般的です。保険会社は、加入のときの保険金額が暮らしに見合っているかの確認や、請求の内容の確認で、これらを防いでいます。", acts:["収入や暮らしに比べて大きすぎる保険金額の希望には、目的を丁寧に伺って記録する", "契約者と被保険者の関係が不自然な申込みは、社内の手順で上長に相談する"], actHead:"お客様と話すなら", note:"引受けの基準と不自然な申込みの扱いは、所属保険会社の手引と社内の手順で確かめ、上長に相談する。", say:"保険金額は、ご家族の暮らしに必要な額をもとに考えるものなので、目的と金額の根拠を一緒に確かめさせてください。", more:"現場で気をつけたいのは、受取人がご本人とつながりの薄い人になっている、収入に比べて保険金額が極端に大きい、短い間に複数の保険会社で同じような申込みがある、といった場面です。疑いを口にせず、事実を記録して社内の手順で報告します。", why:"不正な請求が通ると、そのお金は正直な加入者の保険料から出ることになるからです。加入と請求の両方で確かめることで、保険の仕組みそのものの信頼を守っています。" },
      { key:'faq_xygo_kenkoutai', faq:1, grp:'ygo', q:"非喫煙者割引とは？", re:/(非喫煙者保険料率|リスク細分型|非喫煙者割引|健康体割引|健康体料率|優良体)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(非喫煙者保険料率|リスク細分型|非喫煙者割引|健康体割引|健康体料率|優良体)[?？。!！\s]*$/, head:"非喫煙者割引や健康体割引は、たばこを吸わない人や健康状態のよい人の保険料を区分する仕組みです。", body:"一部の保険会社の死亡保険などでは、過去の一定の期間の喫煙の有無や、血圧、体格などの基準で、保険料の区分を分けています。基準を満たすかは、告知や健康診断の結果、検査などで確かめます。どの基準で、どれだけ保険料が変わるかは、保険会社と商品で大きく違います。", acts:["区分のある商品では、基準と確かめ方をパンフレットで一緒に見る", "基準に当たるか迷う方には、思い込みで案内せず、保険会社の確かめ方に任せる"], actHead:"お客様と話すなら", note:"区分の基準・確かめ方・保険料の差は商品ごとに違う。パンフレット・約款と保険会社の窓口で確かめる。", say:"この保険は、たばこや健康診断の結果によって保険料の区分が分かれています。基準に当たるかは保険会社の確かめ方で決まるので、資料で一緒に見てみましょう。", more:"よくある失敗は、たばこをやめたばかりの方に、基準に当たると言い切ってしまうことです。喫煙の有無は過去の一定の期間で見ることが多く、検査で確かめる商品もあります。事実と違う申告は告知義務違反になるので、事実どおり書いていただくよう伝えます。", why:"たばこや血圧などは、病気や死亡の起こりやすさと関係があると考えられているからです。起こりやすさに応じて保険料を分けることで、加入者どうしの負担を公平にしています。" },
      { key:'faq_xygo_sanrigen', faq:1, grp:'ygo', q:"三利源とは？", re:/(三利源|利差益|死差益|費差益)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(三利源|利差益|死差益|費差益)[?？。!！\s]*$/, head:"三利源は、生命保険会社の利益が生まれる三つの源で、死差・費差・利差のことです。", body:"死差は、予定した死亡率より実際に亡くなる方が少なかったときの差、費差は、予定した事業費より実際の経費が少なかったときの差、利差は、予定利率より実際の運用の成果が上回ったときの差です。保険料は予定の数字で計算するので、実際との差が会社の利益や、配当のある契約の配当のもとになります。", acts:["配当や保険会社の決算について聞かれたら、予定と実際の差という見方で説明する", "配当の見込みは約束しない。保険会社の資料にある範囲で話す"], actHead:"お客様と話すなら", note:"各社の三利源の状況は、保険会社の決算資料や開示資料で確かめる。配当の見込みを約束しない。", say:"生命保険の保険料は予定の数字で計算していて、実際との差が保険会社の利益や配当のもとになります。", more:"よくある勘違いは、保険会社の利益は運用だけで生まれると思うことです。実際には、亡くなる方が予定より少ないことや、経費を予定より抑えたことからも利益が生まれます。逆に運用の成果が予定利率に届かないと利差がマイナスになり、これを逆ざやと呼びます。", why:"保険料は、契約のときに予定の死亡率・事業費・利率で決め、長い期間変えないからです。予定は余裕を見込んで置くので、実際との差が出やすく、その差が利益や配当として扱われます。" },
      { key:'faq_xygo_gyakuzaya', faq:1, grp:'ygo', q:"逆ざやとは？", re:/(逆ざや|逆ザヤ|逆鞘)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(逆ざや|逆ザヤ|逆鞘)[?？。!！\s]*$/, head:"逆ざやは、保険会社の実際の運用の成果が、契約で約束した予定利率に届かない状態です。", body:"予定利率の高い時期に入った契約が多いと、その後に金利が下がったとき、約束した利率に見合う運用の成果を上げられず、差をほかの利益で埋めることになります。予定利率は入ったときのまま変わらないのが原則ですが、保険会社が破綻したときなどには、引き下げられることがあります。", acts:["予定利率の高い古い契約を解約する話では、同じ条件には戻れないことを先に伝える", "保険会社の経営の状態を聞かれたら、開示資料の見方を一緒に見て、言い切らない"], actHead:"お客様と話すなら", note:"各社の運用の状況は保険会社の開示資料で確かめる。破綻のときの扱いは生命保険契約者保護機構の案内で確かめる。", say:"古い契約は、入ったときの予定利率がそのまま続く形です。解約すると同じ条件には戻れないので、見直しの前に中身を一緒に確かめましょう。", more:"お客様が古い貯蓄型の保険を解約して新しい商品に替えたいとき、予定利率の高い契約を手放すことになる場合があります。比べるときは、今の契約の利率・保障・告知の要否を新しい契約と公平に並べ、決めるのはお客様です。", why:"保険会社は、予定利率を約束して保険料を決め、その約束を長い期間守る契約を結んでいるからです。市場の金利は変わっても、約束した利率は変えられないので、差が生まれます。" },
      { key:'faq_xygo_kakuzuke', faq:1, grp:'ygo', q:"保険会社の格付けとは？", re:/(保険金支払能力格付け|保険会社の格付け|保険財務力格付け|格付け|格付)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(保険金支払能力格付け|保険会社の格付け|保険財務力格付け|格付け|格付)[?？。!！\s]*$/, head:"格付けは、格付会社が保険会社や債券の支払いの確かさを、記号で示した評価です。", body:"保険会社の格付けは、保険金を約束どおり支払う力を、格付会社が財務の状態などから評価したものです。格付会社ごとに評価の方法や記号が違い、評価は見直されて変わります。格付けは将来を保証するものではなく、保険会社を選ぶときの材料の一つにとどまります。", acts:["格付けを聞かれたら、どの格付会社のいつ時点の評価かを添えて伝える", "格付けだけで商品を勧めず、保障の中身とお客様の必要から考える"], actHead:"お客様と話すなら", note:"格付けは格付会社の意見で、最新のものは格付会社と保険会社の開示で確かめる。会社どうしの優劣を言い切らない。", say:"格付けは、外の会社が見た支払う力の評価で、時々で見直されます。選ぶ材料の一つとして、保障の中身と一緒に考えましょう。", more:"よくある勘違いは、格付けが高ければ破綻しないと思うことです。格付けは意見であり、変わることがあります。比べるときは、同じ格付会社の評価どうしで、時点をそろえて見ます。広告や資料で使うときは、所属保険会社の決まりに沿います。", why:"保険は長い期間の約束なので、その会社が将来も支払えるかを外から見る材料が求められるからです。格付会社が共通の物差しで評価することで、比べる手がかりになります。" },
      { key:'faq_xygo_touroku', faq:1, grp:'ygo', q:"契約内容登録制度とは？", re:/(支払査定時照会制度|契約内容照会制度|契約内容登録制度|契約内容登録)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(支払査定時照会制度|契約内容照会制度|契約内容登録制度|契約内容登録)[?？。!！\s]*$/, head:"契約内容登録制度は、生命保険の契約の内容の一部を業界で共有し、引受けの判断に使う仕組みです。", body:"生命保険協会が運営し、契約や申込みがあると、被保険者の氏名や保険金額などの一部の情報が登録され、各社が引受けのときに照会できます。同じ方が短い間に多くの会社で大きな保険金額の契約をする、といった不自然な加入を防ぐのが目的です。支払いのときに各社の情報を照らし合わせる、支払査定時照会制度もあります。", acts:["申込書の同意の欄の説明で、登録される情報と目的を一言添える", "お客様から自分の登録の中身を知りたいと言われたら、保険会社や生命保険協会の窓口を案内する"], actHead:"お客様と話すなら", note:"登録される項目・期間・照会の仕組みは、生命保険協会の案内と所属保険会社で確かめる。", say:"生命保険のお申込みの内容の一部は業界で共有され、不自然な加入を防ぐために使われます。", more:"お客様が気にされるのは、ほかの会社に契約の中身が知られるのではないか、という点です。登録されるのは決められた一部の項目で、引受けや支払いの判断のために使われることを、申込書の説明に沿って伝えます。共済や少額短期保険の扱いは違うことがあります。", why:"一人の方に極端に大きな保険金額が重なると、保険金目当ての不正のおそれが高まるからです。各社がばらばらに引き受けると気づけないので、業界で情報を共有しています。" },
      { key:'faq_xygo_kazokugata', faq:1, grp:'ygo', q:"家族型の保険とは？", re:/(本人型と家族型|家族型の保険|夫婦型|家族型|本人型)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(本人型と家族型|家族型の保険|夫婦型|家族型|本人型)[?？。!！\s]*$/, head:"家族型は、一つの契約で本人と家族をまとめて保障する形のことです。", body:"医療保険や傷害保険などで、本人だけを保障する形を本人型、本人と配偶者を保障する形を夫婦型、子どもまで含める形を家族型と呼びます。家族の保障は本人の保障より小さく決められることが多く、本人が亡くなったときや離婚したときに家族の保障がどうなるかは約款で決まっています。", acts:["家族型の契約では、本人に万が一のことがあったときに家族の保障が続くかを約款で確かめる", "子どもが独立したときに、本人型へ切り替えられるかを保険会社に確かめる", "家族それぞれに必要な保障を、一人ずつの契約と並べて見比べる"], actHead:"お客様と話すなら", note:"家族の保障の範囲・続け方・切り替えの手続きは商品で違う。約款・契約概要と保険会社の窓口で確かめる。", say:"ご家族をまとめて保障する形です。ご本人に何かあったときにご家族の保障がどうなるかを、一緒に確かめておきましょう。", more:"まとめると手続きが一度で済み、保険料も分かりやすくなります。一方で、主になる方の契約が終わると家族の保障も一緒に終わる商品があります。家族の暮らしの変化に合わせて、一人ずつの契約にしたほうが合う場合もあるので、両方を並べて考えます。", why:"契約を一つにすることで、契約の管理や保険料の払込みをまとめられるからです。その代わり、保障は主になる方の契約に付いた形になるので、続き方に決まりがあります。" },
      { key:'faq_xygo_saigaiwari', faq:1, grp:'ygo', q:"災害割増特約とは？", re:/(災害割増特約|傷害特約|災害割増|災害死亡)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(災害割増特約|傷害特約|災害割増|災害死亡)[?？。!！\s]*$/, head:"災害割増特約は、事故や決められた感染症で亡くなったときに、保険金を上乗せする特約です。", body:"不慮の事故や約款で決められた感染症が原因で、決められた期間内に亡くなったり高度障害になったりしたときに、主契約の保険金に上乗せして支払われます。傷害特約は、事故による死亡に加えて、事故で決められた身体の障害が残ったときにも給付がある形が一般的です。病気で亡くなったときは対象になりません。", acts:["病気と事故で受け取る額が違う契約は、その違いをお客様と一緒に確かめる", "事故の範囲や期間の決まりは、約款の該当する所を指さして説明する"], actHead:"お客様と話すなら", note:"事故の範囲・対象の感染症・事故から亡くなるまでの期間・障害の区分は約款で決まっている。約款と保険会社の窓口で確かめる。", say:"事故などで亡くなったときに、保険金が上乗せされる特約です。病気のときとは受け取る額が違いますので、一緒に確かめておきましょう。", more:"よくある勘違いは、上乗せの額も含めて、どんな亡くなり方でも受け取れると思うことです。事故の範囲は約款で細かく決まっていて、病気が原因のときは主契約の額だけになります。ご家族の備えを考えるときは、病気のときの額を土台に話します。", why:"事故で亡くなる割合は病気より低いので、少ない保険料で事故のときだけの保障を厚くできるからです。そのため、支払いの対象になる原因と期間を決めて保険料を計算しています。" },
      { key:'faq_xygo_nichigaku', faq:1, grp:'ygo', q:"入院給付金日額とは？", re:/(入院給付金日額|給付金日額|入院日額|日額)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(入院給付金日額|給付金日額|入院日額|日額)[?？。!！\s]*$/, head:"入院給付金日額は、入院一日につき受け取る給付金の額のことです。", body:"医療保険の多くは、入院給付金日額に入院した日数を掛けて給付金を計算します。手術給付金なども日額の何倍という形で決められている商品があります。一回の入院や通算で支払う日数には上限があり、日帰りの入院を対象にするかなども商品で違います。最近は、入院の日数にかかわらず一時金で受け取る形もあります。", acts:["日額だけでなく、一回の入院で支払う日数の上限も合わせて確かめる", "手術や通院の給付が日額に連動しているかを、契約概要で確かめる", "健康保険の高額療養費の仕組みと並べて、自己負担のおおよその形を話す"], actHead:"お客様と話すなら", note:"日額の決め方・支払う日数の上限・日帰りの扱い・手術給付の倍率は商品で違う。約款・契約概要と保険会社の窓口で確かめる。", say:"入院した日数に合わせて受け取る、一日あたりの額です。何日分まで受け取れるかも一緒に確かめておきましょう。", more:"日額を大きくすると保険料も上がります。入院の日数は短くなる傾向があり、公的な医療保険で自己負担の上限もあるので、日額を大きくすることだけが備えではありません。入院中の暮らしのお金や収入の減り方と合わせて、必要な額を考えます。", why:"入院の費用や暮らしのお金は日数に応じて増えるので、日数に合わせて払う形が分かりやすいからです。一日の額を決めておくと、支払う額が事前に分かります。" },
      { key:'faq_xygo_account', faq:1, grp:'ygo', q:"アカウント型保険とは？", re:/(アカウント型の保険|アカウント型保険|アカウント型)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(アカウント型の保険|アカウント型保険|アカウント型)[?？。!！\s]*$/, head:"アカウント型保険は、積立の部分と保障の部分を組み合わせた保険です。", body:"正式には利率変動型積立終身保険などと呼ばれます。払い込んだ保険料はまず積立の口座に入り、そこから定期保険や医療保険などの保障の保険料に充てられます。積立の部分の利率は一定の期間ごとに見直され、最低の利率が決められている商品が多くあります。払込みが終わると、積立金をもとに終身保険や年金に移す形をとります。", acts:["積立に回る額と保障に回る額の内訳を、設計書でお客様と一緒に確かめる", "払込みが終わったあとに保障がどうなるかを、時間の流れで書いて見せる", "保障の部分が更新で保険料が上がるかどうかを、約款で確かめる"], actHead:"お客様と話すなら", note:"積立の利率の見直し方・最低の利率・保障の部分の更新の扱いは商品で違う。約款・設計書と保険会社の窓口で確かめる。", say:"積み立てる部分と保障の部分を組み合わせた保険です。払い込んだお金がどこに回っているかを、設計書で一緒に見てみましょう。", more:"よくある勘違いは、払い込んだ保険料が全て積み立てられていると思うことです。保障の部分の保険料が年齢や更新で上がると、積立に回る額が少なくなります。払込みが終わる時点での積立金の見込みと、そのあとの保障の形を確かめます。", why:"暮らしの変化に合わせて保障を組み替えやすくするため、保険料をいったん一つの口座に集める仕組みにしているからです。その分、内訳が見えにくくなるので、設計書で確かめることが大事になります。" },
      { key:'faq_xygo_zougaku', faq:1, grp:'ygo', q:"中途増額とは？", re:/(保険金額の増額|中途増額|増額)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(保険金額の増額|中途増額|増額)[?？。!！\s]*$/, head:"中途増額は、契約の途中で保険金額を大きくすることです。", body:"契約を続けたまま保険金額を大きくしたいときに、増額の手続きをとります。増やす部分については、改めて告知や診査が要り、その時点の年齢と保険料率で保険料が計算されるのが一般的です。商品によっては増額の取り扱いが無く、新しい契約を追加する形になります。", acts:["増額できる商品かどうかを、先に保険会社に確かめる", "増やす部分の告知が要ることを、手続きの前にお客様へ伝える", "新しい契約を足す形と並べて、保険料と保障の違いを見比べる"], actHead:"お客様と話すなら", note:"増額の取り扱いの有無・告知や診査・保険料の計算は商品で違う。約款と保険会社の窓口で確かめる。", say:"今の契約のまま保険金額を大きくする手続きです。増やす部分は健康状態の確認がありますので、手続きの前にお伝えしておきます。", more:"例えば、家族が増えたときや住宅を買ったときに保障を見直す場面で使われます。増やす部分は今の年齢で計算されるので、今の契約より保険料率が高くなります。新しい契約を足す形と並べて、続けやすい形を選びます。", why:"増やす部分は新しく保障を引き受けることになるので、保険会社がその時点の健康状態を確かめる必要があるからです。そのため、増やす部分だけ今の年齢で計算されます。" },
      { key:'faq_xygo_mensekikin', faq:1, grp:'ygo', q:"免責金額とは？", re:/(免責金額の設定|自己負担額|免責金額|免責額)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(免責金額の設定|自己負担額|免責金額|免責額)[?？。!！\s]*$/, head:"免責金額は、損害のうち契約者が自分で負担する額のことです。", body:"損害保険で、損害が出たときに一定の額まではご自身で負担し、それを超えた分を保険で支払う形をとるとき、その自分で負担する額を免責金額と呼びます。車両保険や火災保険などで設定でき、免責金額を大きくすると保険料は低くなるのが一般的です。事故の回数ごとに負担の額を変える形もあります。", acts:["小さな損害は自分で払えるかを伺ってから、免責金額の設定を一緒に考える", "保険料の違いだけでなく、事故のときに払う額も並べて見せる", "事故の回数で負担の額が変わる形かどうかを、契約概要で確かめる"], actHead:"お客様と話すなら", note:"免責金額の選び方・回数ごとの扱い・対象の補償は商品で違う。約款・契約概要と保険会社の窓口で確かめる。", say:"事故のときに、決まった額まではご自身で負担していただく設定です。保険料と事故のときのご負担を並べて、一緒に決めましょう。", more:"よくある見落としは、保険料が下がることだけを見て、事故のときの負担を考えないことです。修理の額が免責金額より小さいときは保険から支払われません。手元のお金で払える額と、事故のあとの保険料の変わり方も合わせて考えます。", why:"小さな損害まで全て保険で払うと、手続きの費用がかさみ、保険料も高くなるからです。自分で払える分を負担してもらうことで、大きな損害に保険のお金を集められます。" },
      { key:'faq_xygo_ichibu', faq:1, grp:'ygo', q:"一部保険とは？", re:/(比例てん補|一部保険|全部保険|比例填補|超過保険)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(比例てん補|一部保険|全部保険|比例填補|超過保険)[?？。!！\s]*$/, head:"一部保険は、保険金額が保険をかける物の値打ちより小さい契約のことです。", body:"保険金額が保険価額と同じ契約を全部保険、小さい契約を一部保険、大きい契約を超過保険と呼びます。一部保険では、損害の額に、保険金額を値打ちで割った割合を掛けて支払う比例てん補の形をとる商品があります。超過保険では、値打ちを超える分は支払われません。", acts:["火災保険の更新では、保険金額と建物の値打ちを並べて確かめる", "比例てん補の決まりがある契約かを、約款で確かめる", "超過している分の保険料を払い続けていないかも合わせて見る"], actHead:"お客様と話すなら", note:"比例てん補の有無・計算の方法・超過の分の扱いは商品で違う。約款と保険会社の窓口で確かめる。", say:"保険金額が建物などの値打ちより小さいと、損害があっても全額が支払われないことがあります。今の金額が合っているかを一緒に確かめましょう。", more:"よくある勘違いは、損害の額が保険金額より小さければ全額受け取れると思うことです。比例てん補の決まりがあると、一部の損害でも割合で減って支払われます。最近の火災保険には、条件を満たせば損害の額まで支払う形もあるので、契約の決まりを確かめます。", why:"保険料は保険金額に応じて決まるので、値打ちより小さく契約した人と、値打ちどおりに契約した人との公平を保つためです。払った保険料の割合に合わせて支払う考え方です。" },
      { key:'faq_xygo_choufuku', faq:1, grp:'ygo', q:"重複保険とは？", re:/(他の保険契約|重複保険|重複契約)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(他の保険契約|重複保険|重複契約)[?？。!！\s]*$/, head:"重複保険は、同じ物の同じ損害に、複数の損害保険をかけていることです。", body:"例えば、同じ家財に二つの火災保険をかけていたり、個人賠償責任の補償を複数の契約の特約で持っていたりする場合です。損害保険は損害を埋め合わせる仕組みなので、複数の契約があっても損害の額を超えて受け取ることはできず、それぞれの契約の決まりに沿って分けて支払われます。保険料を二重に払っていることもあります。", acts:["個人賠償責任や弁護士費用の特約が、家族の別の契約に付いていないかを確かめる", "新しく契約する前に、他の保険契約の有無を伺う"], actHead:"お客様と話すなら", note:"支払いの分け方と、他の保険契約の告知・通知の決まりは商品で違う。約款と保険会社の窓口で確かめる。", say:"同じものに保険が二つかかっていても、受け取れるのは損害の額までです。重なっている特約が無いか、一緒に見てみましょう。", more:"よくある例は、自動車保険と火災保険の両方に個人賠償責任の特約が付いている形です。家族の誰かの契約に一つあれば足りることが多いので、重なりを外すと保険料を抑えられます。ただし、外す契約が解約や車の買い替えで無くなると補償も無くなるので、どれに残すかを考えます。", why:"損害保険は、損害を埋め合わせて元の状態に戻すための仕組みで、保険で得をしない決まりになっているからです。そのため、複数の契約で同じ損害を重ねて受け取ることはできません。" },
      { key:'faq_xygo_daii', faq:1, grp:'ygo', q:"請求権代位とは？", re:/(残存物代位|請求権代位|保険代位|求償)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(残存物代位|請求権代位|保険代位|求償)[?？。!！\s]*$/, ng:/代位弁済/, head:"請求権代位は、保険金を支払った保険会社が、被害者に代わって加害者に請求できる仕組みです。", body:"事故の相手方に責任があるとき、被害を受けた人が自分の保険から保険金を受け取ると、その額の範囲で、相手方に請求する権利が保険会社に移ります。保険会社が相手方に支払いを求めることを求償と呼びます。全損で保険金を支払ったときに、残った物の権利が保険会社に移る残存物代位という決まりもあります。", acts:["自分の保険で先に修理するか、相手方に請求するかの違いを、保険会社に確かめてから案内する", "示談の前にお客様が相手方と約束をしないよう、手続きの順番を伝える"], actHead:"お客様と話すなら", note:"代位の範囲と手続き、示談との関係は約款と法律で決まっている。保険会社と、法律上の判断は弁護士に確かめる。", say:"保険会社が保険金を支払ったあと、相手の方への請求を引き継ぐ仕組みです。相手の方と先に約束をされる前に、ご連絡ください。", more:"よくある見落としは、お客様が相手方と先に示談をして、請求の権利を手放してしまうことです。そうなると保険会社が求償できず、保険金の支払いに影響することがあります。事故の連絡を受けたら、相手方との約束の前に保険会社へつなぎます。", why:"被害を受けた人が保険金と加害者からの賠償の両方を受け取ると、損害の額より多く受け取ることになるからです。権利を保険会社に移すことで、二重に受け取らない形になります。" },
      { key:'faq_xygo_rieki', faq:1, grp:'ygo', q:"被保険利益とは？", re:/(保険にかけられる利益|保険の利益|被保険利益)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(保険にかけられる利益|保険の利益|被保険利益)[?？。!！\s]*$/, head:"被保険利益は、損害が出たときに損をする関係にあることで、損害保険をかける前提になるものです。", body:"損害保険は、ある物に損害が出たときに経済的な損をする人が、その損を埋め合わせるためにかけます。この、損をする関係を被保険利益と呼びます。例えば、持ち主は建物が焼ければ損をするので、建物に保険をかけられます。借りている人や、お金を貸している人など、立場によって損をする中身が違います。", acts:["建物の持ち主と住んでいる人が違うときは、誰がどの補償をかけるかを整理する", "賃貸の部屋では、家財と借りている部屋への賠償を分けて考える"], actHead:"お客様と話すなら", note:"誰がどの利益で契約できるかは、立場と商品で違う。約款と保険会社の窓口で確かめ、法律上の判断は弁護士に確かめる。", say:"保険は、損をする立場の方が、その損に備えてかけるものです。建物の持ち主と住んでいる方が違うときは、誰が何に備えるかを一緒に整理しましょう。", more:"例えば、賃貸に住む方は建物そのものの持ち主ではないので、建物の火災保険は大家さんがかけます。住んでいる方は、自分の家財と、借りている部屋を傷めたときの大家さんへの賠償に備えます。立場ごとに損をする中身を分けると、重なりも抜けも見つけやすくなります。", why:"損をしない人が保険をかけられると、損害が出ることで得をする人が生まれ、事故を招くおそれがあるからです。損をする関係がある人だけがかけられるようにして、保険を健全に保っています。" },
      { key:'faq_xygo_mikeika', faq:1, grp:'ygo', q:"未経過保険料とは？", re:/(未経過保険料|解約返れい金|短期率|月割)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(未経過保険料|解約返れい金|短期率|月割)[?？。!！\s]*$/, head:"未経過保険料は、損害保険を途中でやめたときに、まだ過ぎていない期間に当たる保険料のことです。", body:"火災保険や自動車保険を途中で解約したり、車を手放して契約を終えたりすると、残りの期間の分の保険料が返れい金として戻ることがあります。戻る額の計算には、残りの月数で分ける月割の形と、短期率と呼ばれる決まった割合の表を使う形があり、契約の種類や解約の理由で変わります。払込みの方法によっては、戻らないことや、反対に未払いの分を払うことがあります。", acts:["解約の申し出を受けたら、戻る額の見込みを保険会社に出してもらってから伝える", "車の入れ替えのときは、解約ではなく入れ替えの手続きで続けられるかを先に確かめる", "長期の契約は、残りの年数で戻る額が変わることを伝える"], actHead:"お客様と話すなら", note:"戻る額の計算の方法・短期率の表・払い方ごとの扱いは商品と約款で違う。約款と保険会社の窓口で確かめる。", say:"途中でおやめになると、残りの期間の保険料が戻ることがあります。戻る額は計算の決まりで変わりますので、保険会社に出してもらってからお伝えします。", more:"よくある勘違いは、残りの月数でちょうど割った額が戻ると思うことです。短期率の表を使う契約では、残りの期間で割った額より少なく戻ることがあります。乗り換えを考えるお客様には、戻る額と新しい契約の保険料を並べて見ていただきます。", why:"保険料には、契約を始めるときの手続きの費用なども入っているからです。途中でやめると、その費用を短い期間で負担する形になるので、残りの月数で割った額とは違う計算になることがあります。" },
      { key:'faq_xygo_chouki', faq:1, grp:'ygo', q:"長期係数とは？", re:/(長期一括払|長期係数|長期契約)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(長期一括払|長期係数|長期契約)[?？。!！\s]*$/, head:"長期係数は、火災保険などを何年分かまとめて契約するときに、保険料の計算に使う係数です。", body:"火災保険を一年ごとではなく複数年で契約し、保険料をまとめて払う長期一括払では、一年分の保険料に年数と長期係数を掛けて保険料を出します。長期係数は年数より小さく決められているので、一年ずつ払うより合計が少なくなる形になります。係数の値や、契約できる最長の年数は、制度の見直しで変わってきました。", acts:["更新の時期が近いお客様には、何年で契約するかで保険料の合計がどう変わるかを見せる", "まとめて払う額と、途中でやめたときに戻る額の決まりを合わせて伝える", "保険料の改定が予定されていると聞いたら、保険会社に時期と中身を確かめる"], actHead:"お客様と話すなら", note:"長期係数の値・契約できる最長の年数・途中でやめたときの扱いは改定と商品で変わる。保険会社の窓口と約款で確かめる。", say:"何年分かをまとめて契約するときの計算に使う数字で、一年ずつより合計の保険料が少なくなる形です。途中でやめたときの扱いと一緒に確かめましょう。", more:"よくある見落としは、まとめて払う額の大きさだけを見て、途中で家を売ったり建て替えたりしたときの扱いを確かめないことです。残りの期間の分は戻ることが多いですが、計算の決まりがあります。暮らしの予定と合わせて、何年で契約するかを決めます。", why:"契約を長く続けてもらうと、保険会社は毎年の更新の手続きや費用を減らせるからです。その分を係数に映して、まとめて払う人の保険料を計算しています。" },
      { key:'faq_xygo_sankou', faq:1, grp:'ygo', q:"参考純率とは？", re:/(損害保険料率算出機構|料率算出機構|参考純率|基準料率)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(損害保険料率算出機構|料率算出機構|参考純率|基準料率)[?？。!！\s]*$/, head:"参考純率は、損害保険料率算出機構が出す、保険金の支払いに充てる部分の保険料率の目安です。", body:"損害保険の保険料は、保険金の支払いに充てる純保険料と、保険会社の経費などに充てる付加保険料で成り立ちます。損害保険料率算出機構は、多くの保険会社のデータを集めて、火災保険や自動車保険などの純保険料の部分の目安を参考純率として出し、各社はそれを参考に自社の保険料を決めます。自賠責保険と地震保険では、付加の部分も含めた基準料率が出され、各社は基本的にそれを使います。", acts:["参考純率の改定が報じられたら、保険料がいつから・どう変わるかを保険会社に確かめてから伝える", "会社ごとに保険料が違う理由を聞かれたら、純保険料と付加保険料の二つに分けて説明する"], actHead:"お客様と話すなら", note:"改定の時期と、自社の保険料への反映のしかたは保険会社ごとに違う。保険会社の窓口と公表資料で確かめる。", say:"保険料の目安を業界全体のデータで出しているもので、各社はそれを参考に保険料を決めています。いつから変わるかは、保険会社に確かめてお伝えします。", more:"よくある勘違いは、参考純率が上がると、どの会社の保険料も同じだけ上がると思うことです。各社は参考純率を参考にしつつ、自社のデータや経費で保険料を決めるので、上がり方や時期は会社で違います。更新の案内は、その会社の改定の中身で話します。", why:"一社だけのデータでは、めったに起きない大きな災害の起き方を見込みにくいからです。多くの会社のデータを集めて計算すると、支払いに足りる保険料の目安を確かな形で出せます。" },
      { key:'faq_xygo_kara', faq:1, grp:'ygo', q:"合算対象期間とは？", re:/(受給資格期間|合算対象期間|カラ期間)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(受給資格期間|合算対象期間|カラ期間)[?？。!！\s]*$/, head:"合算対象期間は、年金を受け取る資格の期間には数えるけれど、年金の額には映らない期間のことです。", body:"カラ期間とも呼ばれます。国民年金に任意で加入できたのに加入しなかった期間などが当たり、例えば、以前の制度で会社員の配偶者だった期間や、学生だった期間、海外に住んでいた期間の一部です。老齢基礎年金を受け取るには決められた長さの受給資格期間が要るので、保険料を納めた期間だけでは足りない方も、この期間を合わせると資格を満たすことがあります。", acts:["年金の受け取りの資格が足りないかもしれないと言うお客様には、年金事務所で期間を確かめていただく", "海外に住んでいた方や、以前は専業主婦だった方には、カラ期間に当たる期間が無いかを確かめていただく"], actHead:"お客様と話すなら", note:"どの期間が合算対象期間に当たるかは、生年月日と、その時期の制度で決まる。日本年金機構・年金事務所の窓口で確かめる。", say:"年金を受け取る資格の期間には数えるけれど、額には入らない期間です。昔の働き方や住まいによっては当たる期間があるので、年金事務所で確かめてみましょう。", more:"よくある勘違いは、保険料を納めていない期間は全て資格の期間にならないと思うことです。カラ期間を合わせて資格を満たせば、納めた期間に応じた年金を受け取れます。ただし額は納めた期間で決まるので、額を増やしたいときは任意加入などの道を確かめます。", why:"以前の制度では、国民年金への加入が任意だった人たちがいたからです。加入しなかったことで年金を受け取る資格まで失わないよう、資格の期間には数える形にしています。" },
      { key:'faq_xygo_gentei', faq:1, grp:'ygo', q:"限定承認とは？", re:/(相続の承認|単純承認|限定承認)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(相続の承認|単純承認|限定承認)[?？。!！\s]*$/, head:"限定承認は、受け継いだ財産の範囲で、亡くなった方の借金などを引き継ぐ相続のしかたです。", body:"相続には、財産も借金も全て受け継ぐ単純承認、全て受け継がない相続放棄、受け継いだ財産の範囲でだけ借金を払う限定承認があります。限定承認は、相続人の全員がそろって、決められた期間のうちに家庭裁判所へ申し立てます。財産を使ったり処分したりすると、単純承認をしたとみなされることがあります。手続きが重く、税の扱いも複雑になります。", acts:["借金があるかもしれないと聞いたら、財産を動かす前に専門家へ相談するよう伝える", "生命保険金は受取人のもので、相続の承認のしかたとは別に受け取れる場合があることを、保険会社に確かめてから伝える"], actHead:"お客様と話すなら", note:"申し立ての期間・手続き・税の扱いは法律と事情で決まる。法律上の判断は弁護士・司法書士、税の計算は税理士、手続きは家庭裁判所の窓口で確かめる。", say:"受け継いだ財産の範囲で借金を払う相続のしかたです。財産を動かす前に、専門の先生に一緒に相談しましょう。", more:"よくある見落としは、相続人の一人でも反対すると限定承認ができないことです。また、亡くなった方の口座からお金を使うと、単純承認とみなされるおそれがあります。保険の担当としては、手続きの判断はせず、専門家につなぐことを先にします。", why:"借金のほうが多いか分からないときに、相続人が自分の財産で借金を払う形にならないようにするためです。その代わり、財産の一覧を作り、債権者に知らせる手続きが要ります。" },
      { key:'faq_xygo_daishuu', faq:1, grp:'ygo', q:"代襲相続とは？", re:/(代襲相続人|代襲相続|代襲)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(代襲相続人|代襲相続|代襲)[?？。!！\s]*$/, head:"代襲相続は、相続人になるはずの人が先に亡くなっていたときに、その子が代わりに相続人になる仕組みです。", body:"例えば、亡くなった方の子が先に亡くなっていれば、その子の子、つまり孫が相続人になります。兄弟姉妹が相続人になる場合に、兄弟姉妹が先に亡くなっていれば、その子のおいやめいが相続人になりますが、おいやめいの子へは続きません。相続放棄をした人の子は、代わりに相続人になりません。", acts:["相続の話を伺うときは、先に亡くなったご家族がいないかも一緒に確かめる", "孫やおい・めいが相続人になるかもしれないときは、相続人の確定を専門家に確かめていただく"], actHead:"お客様と話すなら", note:"相続人の範囲と、相続税の計算での扱いは事情で違う。法律上の判断は弁護士・司法書士、税の計算は税理士に確かめる。", say:"ご家族が先に亡くなっているときは、そのお子さまが代わりに相続人になることがあります。誰が相続人になるかは、専門の先生に一緒に確かめていただきましょう。", more:"よくある見落としは、相続人を今いる子どもだけで数えてしまうことです。先に亡くなったお子さまに子がいれば、その孫も相続人になります。相続人が増えると話し合いの相手も増えるので、遺言や保険の受取人の決め方を考えるきっかけになります。", why:"本来受け継ぐはずだった家系に、財産が渡るようにするためです。先に亡くなったかどうかという偶然で、その家系が相続から外れないようにしています。" },
      { key:'faq_xygo_kiyobun', faq:1, grp:'ygo', q:"寄与分とは？", re:/(特別の寄与|特別寄与料|寄与分)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(特別の寄与|特別寄与料|寄与分)[?？。!！\s]*$/, head:"寄与分は、亡くなった方の財産に特に力を尽くした相続人の取り分を、増やす仕組みです。", body:"家業を無給で手伝った、長い間の介護で費用の支出を抑えた、などが当たることがあります。普通の家族の手助けの範囲を超えることが要り、話し合いで決まらなければ家庭裁判所で決めます。相続人ではない親族、例えば長男の配偶者が介護をした場合は、相続人に特別寄与料を求められる仕組みがあり、求められる期間に決まりがあります。", acts:["介護を担ってきたご家族の話を伺ったら、遺言や生命保険の受取人で思いを形にする道もあることを伝える", "寄与分を主張できるかの判断はせず、専門家に相談していただく"], actHead:"お客様と話すなら", note:"寄与分が認められるか・特別寄与料の求め方と期間は法律と事情で決まる。法律上の判断は弁護士、手続きは家庭裁判所の窓口、税は税理士に確かめる。", say:"介護や家業の手伝いで特に力を尽くした方の取り分を、増やす仕組みがあります。認められるかは事情によりますので、専門の先生に相談しましょう。", more:"よくある勘違いは、介護をしたら当然に取り分が増えると思うことです。認めてもらうには、どれだけ尽くしたかを示すことが要り、話し合いがこじれることもあります。元気なうちに遺言を書く、介護をする人を生命保険の受取人にするなど、前もって形にしておく道があります。", why:"相続分を一律に決めると、力を尽くした人とそうでない人が同じ取り分になり、公平でないことがあるからです。その差を相続のときに映すための仕組みです。" },
      { key:'faq_xygo_rosenka', faq:1, grp:'ygo', q:"路線価とは？", re:/(相続税路線価|路線価方式|倍率方式|路線価)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(相続税路線価|路線価方式|倍率方式|路線価)[?？。!！\s]*$/, head:"路線価は、道路ごとに決めた土地の値段で、相続税や贈与税の土地の評価に使います。", body:"国税庁が毎年、市街地の道路ごとに決めて公表します。土地の評価は、路線価に面積を掛け、土地の形や奥行き、角地かどうかなどで調整して出します。路線価が決められていない地域では、固定資産税評価額に決められた倍率を掛ける倍率方式で評価します。実際に売れる値段とは違うことがあります。", acts:["土地をお持ちのお客様には、相続のときの評価の目安を、税理士に出してもらうよう勧める", "相続税の見込みを話すときは、評価は税理士の仕事であることを先に伝える"], actHead:"お客様と話すなら", note:"土地の評価のしかたと調整は事情で違う。国税庁の公表資料で確かめ、評価と税の計算は税理士に確かめる。", say:"道路ごとに決められた土地の値段で、相続のときの土地の評価に使います。評価の計算は税理士の先生にお願いしましょう。", more:"よくある勘違いは、路線価がそのまま土地の値打ちになると思うことです。土地の形や使い方で評価は上下し、特例で大きく下がることもあります。相続税がかかるかどうかは、評価をしてみないと分からないので、早めに税理士に見ていただきます。", why:"土地は一つずつ値段が違い、売るまで値段が決まらないからです。道路ごとの基準を決めておくことで、誰が評価しても同じ考え方で計算できるようにしています。" },
      { key:'faq_xygo_aoiro', faq:1, grp:'ygo', q:"青色申告とは？", re:/(青色事業専従者給与|青色申告特別控除|白色申告|青色申告)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(青色事業専従者給与|青色申告特別控除|白色申告|青色申告)[?？。!！\s]*$/, head:"青色申告は、決められた帳簿をつけることで、税の計算で特典を受けられる確定申告のしかたです。", body:"事業や不動産の所得がある人が、前もって税務署に承認の申請をし、帳簿をつけて申告します。特典には、所得から差し引ける青色申告特別控除、家族への給与を経費にできる青色事業専従者給与、赤字を次の年以降に繰り越せる仕組みなどがあります。承認を受けずに申告する形を白色申告と呼び、白色申告でも帳簿をつけて記録を残すことが求められます。", acts:["事業をしているお客様には、申告のしかたは顧問の税理士に確かめるよう伝える", "家族に給与を払っている事業の方には、保険の話の前に、給与の扱いを税理士に確かめていただく"], actHead:"お客様と話すなら", note:"承認の申請の期限・特別控除の額と条件・帳簿の形は改正と事情で変わる。税務署の窓口と税理士に確かめる。", say:"帳簿をつけることで、税の計算で特典が受けられる申告のしかたです。どの形が合うかは、税理士の先生に確かめていただきましょう。", more:"よくある見落としは、承認の申請に期限があることです。始めたい年に間に合わないと、その年は白色申告になります。特別控除の額は帳簿の形や電子での申告かどうかで変わるので、細かな条件は税理士に確かめます。", why:"帳簿をきちんとつけてもらうことで、税務署が正しい所得をつかみやすくなるからです。その手間に見合う特典を用意して、帳簿をつける人を増やす仕組みです。" },
      { key:'faq_xygo_kennin', faq:1, grp:'ygo', q:"検認の手続きとは？", re:/(家庭裁判所の検認|検認の手続き|検認)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(家庭裁判所の検認|検認の手続き|検認)[?？。!！\s]*$/, head:"検認は、家庭裁判所が遺言書の形や中身の状態を確かめ、書き換えを防ぐための手続きです。", body:"自分で書いた遺言書（自筆証書遺言）や封をした遺言書を見つけた人は、家庭裁判所に検認を申し立てます。封のある遺言書は、家庭裁判所で開けることになっています。公正証書遺言と、法務局に預けた自筆証書遺言は、検認が要りません。検認は遺言が有効かどうかを決めるものではありません。", acts:["遺言書を見つけたと聞いたら、勝手に開けずに家庭裁判所へ相談するよう伝える", "遺言を考えているお客様には、公正証書や法務局に預ける形もあることを、専門家に確かめていただく"], actHead:"お客様と話すなら", note:"検認の手続きと、遺言が有効かどうかは法律で決まる。手続きは家庭裁判所の窓口、法律上の判断は弁護士・司法書士に確かめる。", say:"遺言書を見つけたら、開けずに家庭裁判所で確かめてもらう手続きがあります。どうするかは、専門の先生に一緒に相談しましょう。", more:"よくある勘違いは、検認を受けると遺言が有効だと認められると思うことです。検認は状態を確かめて記録するだけで、有効かどうかの争いは別に決まります。検認を待つ間は相続の手続きが進まないことがあるので、遺言の残し方を考えるきっかけになります。", why:"自分で書いた遺言は、見つけた人に書き換えられたり隠されたりするおそれがあるからです。家庭裁判所で状態を記録しておくことで、あとから変えられないようにしています。" },
      { key:'faq_xygo_shoukibo', faq:1, grp:'ygo', q:"小規模宅地等の特例とは？", re:/(小規模宅地等の特例|小規模宅地の特例|特定居住用宅地|小規模宅地)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(小規模宅地等の特例|小規模宅地の特例|特定居住用宅地|小規模宅地)[?？。!！\s]*$/, head:"小規模宅地等の特例は、自宅や事業の土地の相続税の評価を、条件を満たせば下げる仕組みです。", body:"亡くなった方の自宅の土地、事業に使っていた土地、貸していた土地などを、決められた親族が受け継いで条件を満たすと、決められた面積まで評価を下げられます。誰が受け継ぐか、申告の期限まで住み続けるか、持ち続けるかなどの条件が、土地の種類ごとに決まっています。特例を使って税がかからなくなるときも、申告が要ります。", acts:["自宅の土地をお持ちのお客様には、誰が受け継ぐかで評価が変わることがあると伝え、税理士に確かめていただく", "同居や二世帯住宅の話が出たら、特例の条件を税理士に確かめてから話を進めていただく"], actHead:"お客様と話すなら", note:"使える土地の種類・面積・受け継ぐ人の条件・申告の決まりは改正と事情で変わる。国税庁の公表資料で確かめ、判断と計算は税理士に確かめる。", say:"ご自宅などの土地の相続税の評価を、条件を満たせば下げられる特例です。誰が受け継ぐかで変わりますので、税理士の先生に確かめていただきましょう。", more:"よくある見落としは、特例で税がかからなくなるから申告は要らないと思うことです。申告をしないと特例は使えません。また、遺産の分け方が申告の期限までに決まらないと、使えるのが遅れることがあります。分け方の話し合いの進め方も、早めに専門家に相談します。", why:"自宅や家業の土地に高い税がかかると、住み続けたり事業を続けたりできなくなるおそれがあるからです。暮らしや事業の土台を受け継げるように、評価を下げる仕組みを設けています。" },
      { key:'faq_xygo_haigusha', faq:1, grp:'ygo', q:"配偶者の税額軽減とは？", re:/(配偶者控除\(相続税\)|配偶者の税額の軽減|配偶者の税額軽減)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(配偶者控除\(相続税\)|配偶者の税額の軽減|配偶者の税額軽減)[?？。!！\s]*$/, head:"配偶者の税額軽減は、亡くなった方の配偶者が受け継いだ財産について、相続税を大きく軽くする仕組みです。", body:"配偶者が受け継いだ財産が、法定相続分か決められた額までであれば、配偶者には相続税がかかりません。使うには申告が要り、遺産の分け方が決まっていることが前提です。期限までに分け方が決まらないときは、あとで決まってから使える手続きがあります。", acts:["配偶者に多く残す分け方を考えるお客様には、次の相続での税も合わせて税理士に見ていただく", "分け方の話し合いが長引きそうなときは、申告の期限と手続きを税理士に確かめていただく"], actHead:"お客様と話すなら", note:"軽くなる範囲・申告の決まり・分け方が決まらないときの手続きは法律と事情で決まる。国税庁の公表資料で確かめ、判断と計算は税理士に確かめる。", say:"配偶者の方が受け継ぐ分の相続税を、大きく軽くする仕組みです。次の相続まで含めた分け方を、税理士の先生に見ていただきましょう。", more:"よくある見落としは、配偶者に全て残せば税がかからないので安心だと考えることです。配偶者が亡くなる次の相続のときには、この仕組みは使えず、子どもの税が重くなることがあります。一回目と二回目を合わせて、分け方を考えます。", why:"夫婦の財産は二人で築いたものという考え方と、残された配偶者の暮らしを守るためです。同じ世代の間で財産が移るだけなので、その時点では税を軽くしています。" },
      { key:'faq_xygo_ennou', faq:1, grp:'ygo', q:"相続税の延納とは？", re:/(相続税の延納|相続税の物納|延納|物納)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(相続税の延納|相続税の物納|延納|物納)[?？。!！\s]*$/, head:"延納は、相続税を一度にお金で納められないときに、分けて納める仕組みです。", body:"相続税は、期限までにお金で一度に納めるのが原則です。それが難しいときは、申請して許可を受けると、分けて納める延納ができ、利子税がかかり、担保を出すのが一般的です。延納でも納めるのが難しいときは、決められた財産で納める物納を申請できます。どちらも条件と手続きが細かく決まっています。", acts:["土地が多く現金が少ないお客様には、納めるお金をどう用意するかを税理士と一緒に考えていただく", "納税のお金の備えとして生命保険の話をするときも、税の判断は税理士に任せる"], actHead:"お客様と話すなら", note:"延納・物納の条件・利子税・担保・納められる財産は法律と事情で決まる。税務署の窓口と税理士に確かめる。", say:"相続税をお金で一度に納められないときに、分けて納めたり、財産で納めたりする道があります。条件が細かいので、税理士の先生に確かめていただきましょう。", more:"よくある勘違いは、払えなければ土地で納めればよいと思うことです。物納は延納でも難しいときの道で、納められる財産にも条件があります。財産が土地に偏っているときは、納めるお金をどう用意するかを前もって考えておきます。", why:"税はお金で納めるのが基本ですが、財産のほとんどが土地などで現金が少ない人もいるからです。そうした人が暮らしの土台を急いで手放さずに済むよう、分けて納める道を用意しています。" },
      { key:'faq_xygo_kafu', faq:1, grp:'ygo', q:"寡婦年金とは？", re:/(寡婦年金と死亡一時金|死亡一時金|寡婦年金)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(寡婦年金と死亡一時金|死亡一時金|寡婦年金)[?？。!！\s]*$/, head:"寡婦年金は、国民年金の保険料を納めた夫が年金を受け取らずに亡くなったとき、妻が受け取る年金です。", body:"自営業などで国民年金の第一号被保険者として保険料を納めた期間が決められた長さある夫が、老齢基礎年金などを受け取らずに亡くなると、婚姻の期間などの条件を満たす妻が、決められた年齢の間、寡婦年金を受け取れます。死亡一時金は、第一号被保険者として保険料を決められた期間納めた方が亡くなり、遺族基礎年金を受け取る人がいないときに、家族が受け取れる一時金です。両方に当たるときは、どちらかを選びます。", acts:["自営業の方の家族の話では、遺族基礎年金のほかにこの二つがあることを伝え、年金事務所で確かめていただく", "どちらを選ぶかは、受け取る額と時期を年金事務所に出してもらってから決めていただく"], actHead:"お客様と話すなら", note:"受け取れる条件・期間・額・請求の期限は制度で決まっている。日本年金機構・年金事務所の窓口で確かめる。", say:"国民年金の保険料を納めてきた方が亡くなったとき、遺族年金のほかに、ご家族が受け取れるものがあります。条件がありますので、年金事務所で確かめてみましょう。", more:"よくある見落としは、子どもがいないと国民年金からは何も出ないと思うことです。遺族基礎年金が出ないときでも、寡婦年金や死亡一時金を受け取れることがあります。請求の期限もあるので、亡くなったあとの手続きの一覧に入れておきます。", why:"保険料を納めたのに、年金を受け取る前に亡くなると、納めた分が何も戻らない形になるからです。残された家族に、その分の一部を渡すための仕組みです。" },
      { key:'faq_xygo_kakyu', faq:1, grp:'ygo', q:"加給年金とは？", re:/(加給年金額|加給年金|振替加算)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(加給年金額|加給年金|振替加算)[?？。!！\s]*$/, head:"加給年金は、厚生年金を受け取る人に、条件を満たす配偶者や子がいるときに上乗せされる年金です。", body:"厚生年金に入っていた期間が決められた長さある人が老齢厚生年金を受け取り始めるとき、生計を同じくする年下の配偶者や、決められた年齢までの子がいると加算されます。配偶者が自分の老齢基礎年金を受け取る年齢になると加給年金は止まり、配偶者の生年月日によっては、配偶者の老齢基礎年金に振替加算が付きます。配偶者が自分の年金を受け取っていると止まる場合もあります。", acts:["年の差のあるご夫婦には、加給年金がいつまで付くかを年金事務所で確かめていただく", "年金の繰下げを考えている方には、加給年金への影響を年金事務所で確かめていただく"], actHead:"お客様と話すなら", note:"加算の条件・額・止まる時期・振替加算の対象は生年月日と制度の改正で変わる。日本年金機構・年金事務所の窓口で確かめる。", say:"厚生年金を受け取る方に、条件を満たす配偶者やお子さまがいると上乗せされる年金です。いつまで付くかは、年金事務所で確かめてみましょう。", more:"よくある見落としは、老齢厚生年金を繰り下げると、その間は加給年金も受け取れないことです。年の差のあるご夫婦では、繰り下げの判断で受け取る額の合計が変わることがあります。制度の見直しも予定されているので、最新の扱いを確かめます。", why:"年金を受け取り始めても、年下の配偶者や子をまだ養っている家庭があるからです。配偶者が自分の年金を受け取るまでの間の暮らしを支えるための上乗せです。" },
      { key:'faq_xygo_maisou', faq:1, grp:'ygo', q:"埋葬料とは？", re:/(家族埋葬料|埋葬料|埋葬費|葬祭費)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(家族埋葬料|埋葬料|埋葬費|葬祭費)[?？。!！\s]*$/, head:"埋葬料は、健康保険に入っている人が亡くなったときに、葬儀を行う家族が受け取れる給付です。", body:"会社員などが入る健康保険では、被保険者が亡くなると、生計を支えられていた家族に埋葬料が出ます。家族がいないときは、実際に埋葬をした人に費用の範囲で埋葬費が出ます。被扶養者が亡くなったときは家族埋葬料です。自営業などの国民健康保険や後期高齢者医療制度では、市区町村などから葬祭費が出ます。どれも請求しないと受け取れません。", acts:["ご家族が亡くなった連絡を受けたら、生命保険の請求と一緒に、健康保険の埋葬料や葬祭費の請求も案内する", "健康保険組合によっては上乗せがあるので、加入先に確かめていただく"], actHead:"お客様と話すなら", note:"額・請求の期限・請求の窓口は加入している健康保険で違う。勤め先の健康保険・市区町村の窓口で確かめる。", say:"健康保険から、葬儀のための給付を受け取れます。生命保険の請求と一緒に、手続きを確かめておきましょう。", more:"よくある見落としは、請求しないと受け取れないことと、請求の期限があることです。亡くなったあとは手続きが多く、後回しになりがちです。生命保険の請求の案内をするときに、公的な給付の一覧も一緒にお渡しすると、受け取り漏れを防げます。", why:"葬儀には急にまとまったお金がかかるので、残された家族の負担を少しでも軽くするためです。健康保険の加入者どうしで支え合う仕組みの一つです。" },
      { key:'faq_xygo_taishoku', faq:1, grp:'ygo', q:"退職所得とは？", re:/(退職所得の受給に関する申告書|退職所得)[^。]{0,8}(とは|って|の意味|意味|について|を教え|教えて|を説明|説明して|は何|はなに|は本当|本当|効果|使え|どういう|どんな|知りたい|分かりやすく|わかりやすく|簡単に|仕組み|のこと)|^(退職所得の受給に関する申告書|退職所得)[?？。!！\s]*$/, head:"退職所得は、退職金など、退職をきっかけに受け取るお金にかかる所得のことです。", body:"退職金から、勤めた年数に応じて決まる退職所得控除を差し引き、残りの半分を退職所得とするのが基本で、ほかの所得と分けて税を計算します。勤め先に退職所得の受給に関する申告書を出すと、税が差し引かれて手続きが終わるのが一般的です。勤めた年数が短い役員などは、半分にしない扱いがあります。亡くなって受け取る死亡退職金は、相続税の対象です。", acts:["退職の時期が近いお客様には、受け取り方で税の扱いが変わることがあると伝え、税理士に確かめていただく", "会社の役員の退職金の話は、会社の顧問の税理士を交えて進める"], actHead:"お客様と話すなら", note:"控除の計算・役員などの扱い・一時金と年金での受け取り方の違いは改正と事情で変わる。国税庁の公表資料で確かめ、判断と計算は税理士に確かめる。", say:"退職金にかかる所得で、勤めた年数に応じた控除があります。受け取り方で税が変わることがありますので、税理士の先生に確かめていただきましょう。", more:"よくある見落としは、一時金で受け取るか年金で受け取るかで、税の扱いが変わることです。年金で受け取ると雑所得になり、公的年金と合わせて計算されます。社会保険料にも影響することがあるので、受け取り方は税理士と相談して決めていただきます。", why:"退職金は長く勤めた見返りとして受け取り、老後の暮らしの元にもなるお金だからです。一度に受け取ることで税が重くならないよう、ほかの所得と分けて軽く計算しています。" },
]};var f=window.__mtMoreTake;if(f)f(1,D);else(window.__mtMorePending=window.__mtMorePending||[]).push([1,D]);})();
